window.FG_PARTY = window.FG_PARTY || [];
window.FG_PARTY.push([{"id":"r0503","sections":[{"name":"中共中央办公厅印发《全国党员教育培训工作规划（2024—2028年）》","text":"近日，中共中央办公厅印发了《全国党员教育培训工作规划（2024—2028年）》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《全国党员教育培训工作规划（2024—2028年）》全文如下。\n为加强和改进党员教育培训工作，锻造过硬党员队伍，不断增强党的创造力、凝聚力、战斗力，根据《中国共产党章程》和《中国共产党党员教育管理工作条例》等党内法规，制定本规划。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，全面贯彻习近平总书记关于党的建设的重要思想、关于党的自我革命的重要思想，深入落实新时代党的建设总要求和新时代党的组织路线，以用党的创新理论武装全党为首要政治任务，以增强党性、提高素质、发挥作用为重点，坚持政治引领、分类指导、守正创新、服务大局，教育引导全体党员深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，开拓进取、干事创业，为以中国式现代化全面推进强国建设、民族复兴伟业提供思想政治保证和能力支撑。\n主要目标是：党的创新理论武装进一步深化，用习近平新时代中国特色社会主义思想凝心铸魂取得更大成效，广大党员对这一重要思想的科学体系、核心要义、实践要求和贯穿其中的立场观点方法理解把握更加完整准确全面，用以武装头脑、指导实践、推动工作更加坚定自觉。党员教育培训体系进一步完善，党员教育培训作用更加凸显，日常教育更加规范，常态化培训特别是基本培训机制更加健全，信息技术运用更加充分，上下联动、横向协同的工作格局更加完善。党员教育培训成效进一步提升，广大党员理想信念和政治立场更加坚定，初心使命更加牢固，纪律作风更加严实，党性修养和实践本领显著增强，先锋模范作用充分发挥，党员队伍建设质量不断提高。\n为实现以上目标，以习近平新时代中国特色社会主义思想为核心内容，在开展党内集中教育和抓好党员日常教育基础上，用5年左右时间，全面落实政治理论教育、政治教育和政治训练、党章党规党纪教育、党的宗旨教育、革命传统教育、形势政策教育、知识技能教育等基本任务，分级分类对党员开展有组织的专题培训，确保全体党员应训尽训。党员5年内参加各类集中学习培训累计不少于20天或160学时。基层党组织书记5年内参加各类集中学习培训累计不少于35天或280学时，其中每年参加县级以上党委举办的脱产培训累计一般不少于5天或40学时。党的创新理论教育学时应占总学时的50%以上。党员干部学时要求按照全国干部教育培训规划执行。对年老体弱、行动不便的党员，集中学习培训不作硬性要求。","level":1},{"name":"二、持续用习近平新时代中国特色社会主义思想统一全党思想意志行动","text":"（一）深化学习教育。突出学习贯彻习近平新时代中国特色社会主义思想主题主线，县级以上党委要加强统筹指导，持续推动党的创新理论武装走深走实。落实党的创新理论学习教育计划，各级党委（党组）要结合实际每年作出具体安排、精心组织实施，党支部要组织好集体学习和党员个人自学。党员教育培训机构要完善课程设置和教学方法，提高理论培训质量。党员要读原著、学原文、悟原理，学习《习近平著作选读》、《习近平谈治国理政》、《习近平新时代中国特色社会主义思想专题摘编》等重要著作，跟进学习习近平总书记最新重要讲话和重要论述，切实用党的创新理论凝心铸魂。\n（二）加强解读阐释。及时推出习近平新时代中国特色社会主义思想系列党员教育培训课程，引导广大党员深学细悟党的创新理论。深化“党课开讲啦”活动，广泛组织讲党课和优秀党课展播，党员领导干部要结合党员思想和工作实际按要求定期讲党课。用好主流媒体和新兴媒体，面向基层党员开展生动鲜活的理论宣传教育。中央组织部要会同中央宣传部、中央党校（国家行政学院）等，适时推出解读阐释党的创新理论和路线方针政策的优质课件和读本。\n（三）健全和落实长效机制。各级党组织要巩固拓展学习贯彻习近平新时代中国特色社会主义思想主题教育成果，健全和落实以学铸魂、以学增智、以学正风、以学促干长效机制。把党的创新理论武装与理想信念教育、党性教育结合起来，组织党员重温入党誓词、过“政治生日”，用好红色资源，抓好党史学习教育。推进党纪学习教育常态化长效化，推动广大党员持续做到学纪知纪明纪守纪。注重理论学用转化，针对不同群体党员实际，开展设岗定责、承诺践诺等，引导党员立足岗位担当作为。深入开展“学习身边榜样”活动，激励广大党员创先争优，充分发挥先锋模范作用。\n三、分级分类开展专题培训，教育引导党员在推进中国式现代化中建功立业\n（四）突出专题培训的政治引领性和分类指导性。坚持把学习贯彻习近平新时代中国特色社会主义思想作为对党员开展专题培训的主题主线、首要任务和核心内容，针对党员所在领域行业的实际，引导其系统学习习近平新时代中国特色社会主义思想特别是习近平总书记关于本地区本部门工作的重要论述、重要讲话和重要指示批示精神。\n（五）农村党员培训。学习贯彻习近平总书记关于“三农”工作的重要论述，结合学习运用“千万工程”经验、推动乡村全面振兴等，注重实战技能培训，引导农村党员在服务群众中作表率、在承担急难险重任务时打头阵。各省（自治区、直辖市）党委要结合实际制定农村党员集中轮训计划，组织开展专题培训。\n（六）城市社区党员培训。学习贯彻习近平总书记关于基层治理的重要论述，结合提升城市基层党建引领基层治理效能等，引导城市社区党员提高参与基层治理、为民办事服务等方面能力。各省（自治区、直辖市）党委要结合实际制定城市社区党员专题培训计划，抓好组织实施。\n（七）机关党员培训。学习贯彻习近平总书记关于机关党建的重要讲话和重要指示批示精神，结合以深化党的建设制度改革推动机关党建高质量发展，建设让党中央放心、让人民群众满意的模范机关等，引导机关党员强化政治忠诚、提高政治能力，依法履职、廉洁从政、务实为民。各级党委（党组）要统筹用好干部教育培训成果，坚持抓机关带行业系统，延伸开展普通党员专题培训。\n（八）事业单位党员培训。学习贯彻习近平文化思想和习近平总书记关于教育、科技、卫生健康工作等重要论述，结合深化事业单位改革、强化公共服务职能、推进社会事业发展等，引导事业单位党员增强思想觉悟、专业素养和职业道德，全心全意为人民服务。对宣传思想文化系统事业单位党员，结合坚持党管宣传、党管意识形态、党管媒体，建设社会主义文化强国，深化文化体制机制改革等，引导他们自觉增强脚力眼力脑力笔力，肩负起新时代文化使命。对教育系统党员，结合全面贯彻党的教育方针、加快建设教育强国、落实立德树人根本任务、办好人民满意的教育等，结合实施教育家精神铸魂强师行动，引导他们争做“四有”好老师的示范标杆，矢志为党育人、为国育才。对学生党员，注重把握其思想行为特点，坚持党的创新理论武装与思政课教育、社会实践有机结合，引导他们坚定理想信念，立报国强国大志向、做挺膺担当奋斗者。对科研机构党员，结合坚持“四个面向”的战略导向、加快建设科技强国、推进高水平科技自立自强、加快建设国家战略人才力量、统筹强化关键核心技术攻关等，引导他们弘扬科学家精神，爱党报国、敬业奉献。对医药卫生系统党员，结合贯彻新时代党的卫生健康工作方针、全面推进健康中国建设、深化医药卫生体制改革等，引导他们恪守医德医风医道，更好保障人民健康。各级党委（党组）要针对各类事业单位实际和公益性、服务性、专业性特点，组织开展党员专题培训。\n（九）企业党员培训。学习贯彻习近平总书记关于国有企业改革发展和党的建设、促进民营经济发展、金融工作等重要论述，结合构建高水平社会主义市场经济体制、因地制宜发展新质生产力、建设现代化产业体系、加强新时代廉洁文化建设等，引导企业党员坚定信仰信念信心，为高质量发展贡献智慧和力量。对国有企业党员，结合深化国资国企改革、推动国有资本和国有企业做强做优做大等，引导他们增强责任感使命感，立足岗位建功立业。对金融企业党员，结合加快建设金融强国、坚定不移走中国特色金融发展之路、服务实体经济、防控金融风险、深化金融体制改革等，引导他们诚实守信、依法依规、服务人民，带头弘扬中国特色金融文化，守好中国特色现代金融体系的根和魂。各级党委（党组）要组织好所属（所辖）企业党员专题培训。\n（十）新兴领域党员培训。学习贯彻习近平总书记关于“两个健康”和加强新经济组织、新社会组织、新就业群体党的建设等重要指示精神，结合加强思想政治引领，促进非公有制经济健康发展、非公有制经济人士健康成长，提高党的组织和工作覆盖质量，增强党在新兴领域的号召力凝聚力影响力等，引导党员强化党性观念和党的意识，激发内生动力和创新活力，提升职业技能，更好服务群众、奉献社会。各级党委（党组）要抓好新兴领域党员专题培训。","level":1},{"name":"四、创新方法载体，充分运用信息化手段推动党员教育培训工作提质增效","text":"（十一）丰富党员教育培训方式方法。认真开展党委（党组）理论学习中心组学习、“三会一课”、主题党日，定期举办专题讲座、报告会等，严格落实民主生活会和组织生活会、民主评议党员、谈心谈话等制度，提高党员日常教育质量。规范脱产培训，灵活运用案例讨论、互动交流、现场体验等方法，分期分批组织实施。注重完善基本培训，运用视频集中培训等方式，让优质课件直达一线、覆盖基层，推动基层党组织有组织地开展集中学习研讨，与落实组织生活制度有机结合，不断增强实效性。\n（十二）推进党员教育信息化平台建设。坚持规范有序、集约高效，加强各级各类党员教育信息化平台建设，强化教育培训功能。统筹推进共产党员教育平台一体化建设，开设共产党员网在线课堂，充分发挥共产党员网和中国干部网络学院、中央党校（国家行政学院）“网上党校”、“学习强国”学习平台等作用。引导基层党组织和广大党员规范网络学习行为，提高学网用网能力，在网络空间发挥积极作用。注重运用大数据等技术对党员参训情况进行动态分析，不断提高教育培训精准性。加强平台信息安全管理，严格落实网络安全责任制、网络安全等级保护和数据分类分级保护等制度，确保安全可控。","level":1},{"name":"五、加强组织实施","text":"（十三）明确工作责任。加强对党员教育培训工作的组织领导，压紧压实各级党委（党组）的主体责任、各基层单位党委和党总支的直接实施责任、党支部的具体组织责任，充分发挥组织部门的统筹协调和督促指导作用、宣传部门的内容提供和舆论引导作用、党校（行政学院）的优质课程课件供给保障作用，构建组织部门牵头抓总、相关职能部门齐抓共管、行业系统主管部门分工落实的工作格局。各级党委（党组）主要负责同志要认真履行第一责任人职责，研究部署党员教育培训重点工作，推动解决问题，确保任务落实。明确流动党员教育培训责任，流出地（单位）和流入地（单位）基层党组织联动抓好流动党员教育培训。\n（十四）完善制度机制。优化党员教育培训工作机构职能，依规配强工作力量。以制度建设为重点，深入推进党员教育工作体系化建设。完善党员教育管理、作用发挥机制，加强党员教育培训与发展党员、管理监督服务党员衔接，强化党员教育培训与干部教育培训有效协同。加强基层党组织书记和党务工作者定期轮训，每年举办全国党员教育专题培训班，推动培训成果惠及广大党员。健全教育培训需求调研、激励约束等机制，激发党员参学参训内生动力。建立科学合理的党员调训机制，防止多头调训、重复培训。\n（十五）夯实基础支撑。建立健全党员教育培训师资聘任管理制度，分级分类建立并动态管理师资库。加强党员教育培训内容资源开发与供给，鼓励地方和部门、单位结合实际组织开发高质量特色教材和案例课程。发挥各级党校（行政学院）主渠道作用，规范和加强乡镇（街道）党校、现场教学点和远程教育站点建设，用好各类党员教育培训基地、党群服务中心等阵地。落实党员教育培训经费列入各级年度财政预算和各级党委留存党费主要用于教育培训党员等要求，形成稳定的经费保障机制。为革命老区、民族地区、边疆地区、乡村振兴重点帮扶地区党员教育培训工作提供必要保障。\n（十六）不断改进学风。坚持解放思想、实事求是、与时俱进、求真务实，坚持从严治教、从严治学，弘扬理论联系实际的马克思主义学风，严格培训纪律和学员管理，加强师德师风建设，厉行勤俭节约，讲求培训实效，反对形式主义、官僚主义，切实为基层减负，坚决防止“低级红”、“高级黑”。\n（十七）强化督导评估。建立述学导学督学制度，实施党员脱产培训年度计划备案管理。把党员教育培训开展情况作为党委（党组）书记抓基层党建工作述职评议考核、巡视巡察、民主评议党员的重要内容，强化结果运用。各级党委（党组）要结合实际抓好本规划贯彻落实。中央组织部对本规划实施情况开展中期和5年总结评估工作。重大事项及时按程序向党中央请示报告。\n中国人民解放军和中国人民武装警察部队的党员教育培训工作，由中央军委根据本规划精神制定实施意见。","level":1}]},{"id":"r0504","sections":[{"name":"关于贯彻实施公务员法建设高素质专业化公务员队伍的意见","text":"近日，中共中央办公厅印发了《关于贯彻实施公务员法建设高素质专业化公务员队伍的意见》，并发出通知，要求各级党委（党组）及其组织（人事）部门把学习贯彻新修订的公务员法作为一项严肃的政治任务，把贯彻实施新修订的公务员法与建设高素质专业化公务员队伍结合起来，努力建设一支信念坚定、为民服务、勤政务实、敢于担当、清正廉洁的公务员队伍。","level":1},{"name":"","text":"《意见》强调，要坚持用习近平新时代中国特色社会主义思想武装公务员队伍，把学习贯彻习近平新时代中国特色社会主义思想作为公务员培训的首要任务、考试测查的重要内容和考核监督的重要方面，把政治标准和政治要求贯穿融入公务员队伍建设全过程各方面，推动广大公务员加强政治历练，培养斗争精神、增强斗争本领，践行全心全意为人民服务的根本宗旨，立足岗位、履职尽责，为实现新时代党的历史使命建功立业。\n《意见》提出，要深化分类改革，提高管理科学化水平；拓宽公务员队伍来源渠道，优化队伍结构；强化培养锻炼，提升能力素质；完善考核机制，发挥激励鞭策作用。\n《意见》要求，要坚持从严管理，锤炼过硬作风，健全日常管理监督制度，加强对公务员的全方位管理，着力纠正形式主义、官僚主义，严肃查处不担当、不作为、乱作为等问题，严格依法依规开展考录、培训、考核、职务职级任免升降、奖惩、监督等工作。要加强正向激励，激发公务员队伍活力，突出重视基层导向，切实为基层公务员松绑减负。\n延伸阅读\n中华人民共和国公务员法","level":0}]},{"id":"r0505","sections":[{"name":"关于促进移动互联网健康有序发展的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于促进移动互联网健康有序发展的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于促进移动互联网健康有序发展的意见》全文如下。\n随着信息网络技术迅猛发展和移动智能终端广泛普及，移动互联网以其泛在、连接、智能、普惠等突出优势，有力推动了互联网和实体经济深度融合，已经成为创新发展新领域、公共服务新平台、信息分享新渠道。为深入贯彻落实习近平总书记网络强国战略思想，促进我国移动互联网健康有序发展，现提出如下意见。","level":0},{"name":"一、重要意义和总体要求","text":"1.重要性和紧迫性。党的十八大以来，以习近平同志为核心的党中央高度重视网络安全和信息化工作，成立中央网络安全和信息化领导小组，作出一系列重大决策部署，有力推动了网信事业特别是移动互联网健康发展，对方便人民群众生产生活、促进经济社会发展、维护国家安全发挥了重要作用。当前，随着互联网技术、平台、应用、商业模式与移动通信技术紧密结合，移动互联网新技术快速演进、新应用层出不穷、新业态蓬勃发展，工具属性、媒体属性、社交属性日益凸显，生态系统初步形成、加速拓展，越来越成为人们学习、工作、生活的新空间。与此同时，移动互联网安全威胁和风险日渐突出，并向经济、政治、文化、社会、生态等领域传导渗透。面对新形势新挑战，移动互联网发展管理工作还存在一些短板：体制机制有待完善，法治建设仍显滞后，政策扶持力度不够，自主创新能力不足，核心技术亟需突破，管理基础相对薄弱，企业主体责任落实不到位，安全策略不完备等。这些问题已经制约移动互联网健康有序发展，必须高度重视、抓紧解决。\n2.指导思想。全面贯彻党的十八大和十八届三中、四中、五中、六中全会精神，以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，积极践行新发展理念，坚持以人民为中心的发展思想，坚持鼓励支持和规范发展并行、政策引导和依法管理并举、经济效益和社会效益并重，凝聚共识、防范风险、争取人心、保障安全、促进发展，鼓励和支持技术创新，激发和保护企业活力，不断增强发展内生动力，全方位推进移动互联网健康有序发展，更好服务党和国家事业发展大局，让移动互联网发展成果更好造福人民。\n3.基本原则。坚持发展为民，充分发挥移动互联网优势，缩小数字鸿沟，激发经济活力，为人民群众提供用得上、用得起、用得好的移动互联网信息服务；坚持改革引领，完善市场准入，规范竞争秩序，优化发展环境，全面释放创新活力和市场能量；坚持创新为要，强化目标导向、问题导向、效果导向，发挥管理主体、运营主体、使用主体作用，全方位推进理念、机制、手段等创新；坚持内容为本，创新内容生产，拓展分享渠道，净化交互生态；坚持分类指导，对移动互联网信息服务实行分类管理；坚持安全可控，全面排查、科学评估、有效防范和化解移动互联网迅猛发展带来的风险隐患，切实保障网络数据、技术、应用等安全。","level":1},{"name":"二、推动移动互联网创新发展","text":"4.完善市场准入制度。深入推进简政放权、放管结合、优化服务，进一步取消和下放相关行政审批事项，加快落实由先证后照改为先照后证，简化审批流程、提高审批效率。建立完善与移动互联网演进发展相适应的市场准入制度，健全电信业务分级分类管理制度，健全移动互联网新业务备案管理、综合评估等制度。在确保安全的前提下，引导多元化投融资市场发展，积极稳妥推进电信市场开放，推动形成多种资本成分和各类市场主体优势互补、相互竞争、共同发展的市场新格局。\n5.加快信息基础设施演进升级。全面推进第四代移动通信（4G）网络在城市地区深度覆盖、在农村地区逐步覆盖、在贫困地区优先覆盖。加快第五代移动通信（5G）技术研发，统筹推进标准制定、系统验证和商用部署。增强网络服务能力，简化电信资费结构，实现网络资费合理下降，提升服务性价比和用户体验。创新投资和运营模式，扩大用户宽带接入网普及范围，加快民航客机、高速铁路、城市交通等公共场所无线局域网建设和应用，带动引导商业性服务场所实现无线局域网覆盖和免费开放。加快建设并优化布局内容分发网络、云计算及大数据平台等新型应用基础设施。开放民间资本进入基础电信领域竞争性业务，深入推进移动通信转售业务发展，形成基础设施共建共享、业务服务相互竞争的市场格局。改善互联网骨干网网间互联质量，优化互联架构，探索建立以长期增量成本为基础的网间结算长效机制，更好满足用户携号转网需求，营造良好市场竞争环境。\n6.实现核心技术系统性突破。坚定不移实施创新驱动发展战略，在科研投入上集中力量办大事，加快移动芯片、移动操作系统、智能传感器、位置服务等核心技术突破和成果转化，推动核心软硬件、开发环境、外接设备等系列标准制定，加紧人工智能、虚拟现实、增强现实、微机电系统等新兴移动互联网关键技术布局，尽快实现部分前沿技术、颠覆性技术在全球率先取得突破。落实企业研发费用加计扣除政策，创新核心技术研发投入机制，探索关键核心技术市场化揭榜攻关，着力提升我国骨干企业、科研机构在全球核心技术开源社区中的贡献和话语权，积极推动核心技术开源中国社区建设。\n7.推动产业生态体系协同创新。统筹移动互联网基础研究、技术创新、产业发展与应用部署，加强产业链各环节协调互动。鼓励和支持企业成为研发主体、创新主体、产业主体，加快组建产学研用联盟，推动信息服务企业、电信企业、终端厂商、设备制造商、基础软硬件企业等上下游融合创新。推动信息技术、数字创意等战略性新兴产业融合发展。提高产品服务附加值，加速移动互联网产业向价值链高端迁移。完善覆盖标准制定、成果转化、测试验证和产业化投融资评估等环节的公共服务体系。加快布局下一代互联网技术标准、产业生态和安全保障体系，全面向互联网协议第六版（IPv6）演进升级。统筹推进物联网战略规划、科技专项和产业发展，建设一批效果突出、带动性强、关联度高的典型物联网应用示范工程。\n8.加强知识产权运用和保护。开展移动互联网领域专利导航工作，制定专利布局方向建议清单，鼓励企业面向战略前沿、交叉融合领域开展知识产权战略布局，充实核心技术专利储备。推进知识产权运营交易和服务平台建设，加快推进专利信息资源开放共享，鼓励大型移动互联网企业共同组建专利池，建立资源共享和利益分配机制。建立知识产权风险管理体系，加强知识产权预警和跨境纠纷法律援助。加大对移动互联网技术、商业模式等创新成果的知识产权保护，研究完善法律法规，规范网络服务秩序，提高侵权代价和违法成本，有效威慑侵权行为。","level":1},{"name":"三、强化移动互联网驱动引领作用","text":"9.激发信息经济活力。加快制定完善信息经济发展政策措施，将发展移动互联网纳入国家信息经济示范区统筹推进，鼓励移动互联网领先技术和创新应用先行先试，扶持基于移动互联网技术的创新创业，促进经济转型升级、提质增效。加快实施“互联网+”行动计划、国家大数据战略，大力推动移动互联网和农业、工业、服务业深度融合发展，以信息流带动技术流、资金流、人才流、物资流，促进资源优化配置，促进全要素生产率提升。创新信息经济发展模式，增强安全优质移动互联网产品、服务、内容有效供给能力，积极培育和规范引导基于移动互联网的约车、租房、支付等分享经济新业态，促进信息消费规模快速增长、信息消费市场健康活跃。\n10.支持中小微互联网企业发展壮大。充分运用国家相关政策措施推动中小微互联网企业在移动互联网领域创新发展，支持和促进大众创业、万众创新。进一步发挥国家中小企业发展基金、国家创新基金等政策性基金引导扶持作用，落实好税费减免政策，在信用担保、融资上市、政府购买服务等方面予以大力支持，消除阻碍和影响利用移动互联网开展大众创业、万众创新的制度性限制。积极扶持各类中小微企业发展移动互联网新技术、新应用、新业务，打造移动互联网协同创新平台和新型孵化器，发展众创、众包、众扶、众筹等新模式，拓展境内民间资本和风险资本融资渠道。充分发挥基础电信企业、大型互联网企业龙头带动作用，通过生产协作、开放平台、共享资源等方式，积极支持上下游中小微企业发展。遏制企业滥用市场支配地位破坏竞争秩序，营造公平有序的市场竞争环境。\n11.推进信息服务惠及全民。依托移动互联网加强电子政务建设，完善国家电子政务顶层设计，加快推进“互联网+政务服务”。在保障数据安全和个人隐私的前提下，推动公共信息资源开放利用，优先推进民生保障服务领域政府数据集向社会开放。加快实施信息惠民工程，构建一体化在线服务平台，分级分类推进新型智慧城市建设，促进移动互联网与公共服务深度融合，重点推动基于移动互联网的交通、旅游、教育、医疗、就业、社保、养老、公安、司法等便民服务，依托移动互联网广泛覆盖和精准定位等优势加快向街道、社区、农村等延伸，促进基本公共服务均等化。推动各级党政机关积极运用移动新媒体发布政务信息，提高信息公开、公共服务和社会治理水平。\n12.实施网络扶贫行动计划。按照精准扶贫、精准脱贫要求，加大对中西部地区和农村贫困地区移动互联网基础设施建设的投资力度，充分发挥中央财政资金引导作用，带动地方财政资金和社会资本投入，加快推进贫困地区网络全覆盖。鼓励基础电信企业针对贫困地区推出优惠资费套餐，探索推出“人、机、卡、号”绑定业务，精准减免贫困户网络通信资费。以远程医疗服务、在线教育培训等为重点，大力推动移动互联网新技术新应用为贫困地区农产品销售、乡村旅游、生产指导、就业服务、技能培训等提供更加优质便捷的服务。依托网络公益扶贫联盟等各方力量，推动网信企业与贫困地区结对帮扶，组织知名电商平台为贫困地区开设扶贫频道，积极开发适合民族边远地区特点和需求的移动互联网应用。坚持经济效益和社会效益并重，在深入开展项目论证基础上，充分发挥中国互联网投资基金作用，大力推动基于移动互联网的教育、医疗、公共文化服务等民生保障项目落地和可持续实施。\n13.繁荣发展网络文化。把握移动互联网传播规律，实施社会主义核心价值观、中华优秀文化网上传播等内容建设工程，培育积极健康、向上向善的网络文化。加大中央和地方主要新闻单位、重点新闻网站等主流媒体移动端建设推广力度，积极扶持各类正能量账号和应用。加强新闻媒体移动端建设，构建导向正确、协同高效的全媒体传播体系。在互联网新闻信息服务、网络出版服务、信息网络传播视听节目服务等领域开展特殊管理股试点。大力推动传统媒体与移动新媒体深度融合发展，加快布局移动互联网阵地建设，建成一批具有强大实力和传播力、公信力、影响力的新型媒体集团。","level":1},{"name":"四、防范移动互联网安全风险","text":"14.提升网络安全保障水平。牢固树立正确的网络安全观和动态、综合防护理念，坚持以安全保发展、以发展促安全，全方位、全天候感知移动互联网安全态势，不断强化移动互联网基础信息网络安全保障能力，大力推广具有自主知识产权的网络空间安全技术和标准应用。增强网络安全防御能力，落实网络安全责任制，制定完善关键信息基础设施安全、大数据安全等网络安全标准，明确保护对象、保护层级、保护措施。全面加强网络安全检查，摸清家底、认清风险、找出漏洞、督促整改，建立统一高效的网络安全风险报告机制、情报共享机制、研判处置机制。\n15.维护用户合法权益。完善移动互联网用户信息保护制度，严格规范收集使用用户身份、地理位置、联系方式、通信内容、消费记录等个人信息行为，保障用户知情权、选择权和隐私权。督促移动互联网企业切实履行用户服务协议和相关承诺，完善服务质量管理体系，健全投诉处理机制，提供更加安全、优质、便捷、实用的产品和服务。加大对利用“伪基站”、非法网站、恶意软件等侵害用户权益行为的打击力度，切实维护消费者权益和行业秩序。\n16.打击网络违法犯罪。坚决打击利用移动互联网鼓吹推翻国家政权、煽动宗教极端主义、宣扬民族分裂思想、教唆暴力恐怖等违法犯罪活动。严厉查处造谣诽谤、电信网络诈骗、攻击窃密、盗版侵权、非法售卖个人信息等违法犯罪行为。全面清理赌博、传销、非法集资、淫秽色情、涉枪涉爆等违法违规信息。\n17.增强网络管理能力。强化网络基础资源管理，规范基础电信服务，落实基础电信业务经营者、接入服务提供者、互联网信息服务提供者、域名服务提供者的主体责任。创新管理方式，加强新技术新应用新业态研究应对和安全评估。完善信息服务管理，规范传播行为，维护移动互联网良好传播秩序。","level":1},{"name":"五、深化移动互联网国际交流合作","text":"18.拓展国际合作空间。围绕“一带一路”国家战略，推进网上丝绸之路国际合作，促进移动互联网基础设施互联互通，大力发展跨境移动电子商务。在第五代移动通信（5G）、下一代互联网、物联网、网络安全等关键技术和重要领域，积极参与国际标准制定和交流合作。支持移动互联网企业走出去，鼓励通过多种方式开拓国际市场，加大移动互联网应用、产品、服务海外推广力度，构建完善跨境产业链体系，不断拓展海外发展空间。\n19.参与全球移动互联网治理。全面参与全球移动互联网治理相关组织、机制和活动，加强各类双边、多边对话合作。深入参与、积极推动移动互联网领域规则和标准制定。充分发挥世界互联网大会等平台作用，大力宣介中国治网主张。建立健全信息共享机制，积极参与国际联合打击移动互联网违法犯罪行动。\n20.加强国际传播能力建设。深化中外人文交流，积极利用各类社交平台，有效运用各种传播渠道，采用融通中外的概念、范畴、表述，讲好中国故事，展现中国形象。打造具有较强影响力的国际传播媒体，创新开展多语种、跨平台互动传播，不断提升移动互联网国际传播影响力。","level":1},{"name":"六、加强组织领导和工作保障","text":"21.完善管理体制。在中央网络安全和信息化领导小组统一领导下，中央网信办要进一步强化移动互联网管理的统筹协调、督促检查，建立健全联席会议、工作例会等制度，研究处理各地区各部门移动互联网发展管理重大事项和情况，督促指导各地区各部门有效落实领导小组决定事项、工作部署和有关要求；工业和信息化、公安、文化、新闻出版广电等有关部门和军队要根据职责切实负起责任，依法加强对移动互联网相关业务的监督管理，制定出台支持和促进移动互联网技术、产业发展的政策措施。明确地方网信部门承担互联网信息内容的监督管理执法职责，健全中央、省、市三级管理体系，加大人员、经费、技术等保障力度。\n22.扩大社会参与。鼓励社会各界广泛参与移动互联网治理，加快移动互联网社会组织建设，支持中国互联网发展基金会、中国互联网协会等各方力量积极开展网络公益活动。引导广大移动互联网用户文明上网，积极参与净化网络环境、维护网络秩序。健全行业信用评价体系和服务评议制度，完善行业管理、企业自律、社会监督联动机制。\n23.推进人才队伍建设。加强网信战线人才培养体系建设，不断提升业务能力和综合素质，注重培养、选拔、任用熟悉移动互联网发展管理工作的领导干部。坚持先行先试，创新人才引进、评价、流动、激励机制，将各方面优秀人才凝聚到网信事业中来。着力打造高端智库群，为移动互联网发展管理工作提供智力支持。采取特殊政策，建立适应网信特点的人事制度和薪酬制度。\n24.强化法治保障。加快网络立法进程，完善依法监管措施，化解网络风险。全面贯彻实施网络安全法，加快推进电子商务法等基础性立法，制定修订互联网信息服务管理办法、关键信息基础设施安全保护条例、未成年人网络保护条例等行政法规。完善司法解释和政策解读，推动现有法律法规延伸适用于移动互联网管理。建立健全网络数据管理、个人信息保护等重点管理制度。完善移动互联网管理多部门执法协调机制，加快执法信息技术系统建设，提高对网络违法犯罪识别、取证、联动查处打击等能力。加强网络普法，强化网民法治观念，提升全民网络素养。","level":1}]},{"id":"r0506","sections":[{"name":"中共中央 国务院关于深化教育教学改革全面提高义务教育质量的意见","text":"中共中央 国务院关于深化教育教学改革全面提高义务教育质量的意见\n（2019年6月23日）","level":1},{"name":"","text":"义务教育质量事关亿万少年儿童健康成长，事关国家发展，事关民族未来。为深入贯彻党的十九大精神和全国教育大会部署，加快推进教育现代化，建设教育强国，办好人民满意的教育，现就深化教育教学改革、全面提高义务教育质量提出如下意见。","level":0},{"name":"一、坚持立德树人，着力培养担当民族复兴大任的时代新人","text":"1.指导思想。坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻党的教育方针，落实立德树人根本任务，遵循教育规律，强化教师队伍基础作用，围绕凝聚人心、完善人格、开发人力、培育人才、造福人民的工作目标，发展素质教育，培养德智体美劳全面发展的社会主义建设者和接班人。\n2.基本要求。树立科学的教育质量观，深化改革，构建德智体美劳全面培养的教育体系，健全立德树人落实机制，着力在坚定理想信念、厚植爱国主义情怀、加强品德修养、增长知识见识、培养奋斗精神、增强综合素质上下功夫。坚持德育为先，教育引导学生爱党爱国爱人民爱社会主义；坚持全面发展，为学生终身发展奠基；坚持面向全体，办好每所学校、教好每名学生；坚持知行合一，让学生成为生活和学习的主人。","level":1},{"name":"二、坚持“五育”并举，全面发展素质教育","text":"3.突出德育实效。完善德育工作体系，认真制定德育工作实施方案，深化课程育人、文化育人、活动育人、实践育人、管理育人、协同育人。大力开展理想信念、社会主义核心价值观、中华优秀传统文化、生态文明和心理健康教育。加强爱国主义、集体主义、社会主义教育，引导少年儿童听党话、跟党走。加强品德修养教育，强化学生良好行为习惯和法治意识养成。打造中小学生社会实践大课堂，充分发挥爱国主义、优秀传统文化等教育基地和各类公共文化设施与自然资源的重要育人作用，向学生免费或优惠开放。广泛开展先进典型、英雄模范学习宣传活动，积极创建文明校园。健全创作激励与宣传推介机制，提供寓教于乐的优秀儿童文化精品；强化对网络游戏、微视频等的价值引领与管控，创造绿色健康网上空间。突出政治启蒙和价值观塑造，充分发挥共青团、少先队组织育人作用。\n4.提升智育水平。着力培养认知能力，促进思维发展，激发创新意识。严格按照国家课程方案和课程标准实施教学，确保学生达到国家规定学业质量标准。充分发挥教师主导作用，引导教师深入理解学科特点、知识结构、思想方法，科学把握学生认知规律，上好每一堂课。突出学生主体地位，注重保护学生好奇心、想象力、求知欲，激发学习兴趣，提高学习能力。加强科学教育和实验教学，广泛开展多种形式的读书活动。各地要加强监测和督导，坚决防止学生学业负担过重。\n5.强化体育锻炼。坚持健康第一，实施学校体育固本行动。严格执行学生体质健康合格标准，健全国家监测制度。除体育免修学生外，未达体质健康合格标准的，不得发放毕业证书。开齐开足体育课，将体育科目纳入高中阶段学校考试招生录取计分科目。科学安排体育课运动负荷，开展好学校特色体育项目，大力发展校园足球，让每位学生掌握1至2项运动技能。广泛开展校园普及性体育运动，定期举办学生运动会或体育节。鼓励地方向学生免费或优惠开放公共运动场所。通过购买服务等方式，鼓励体育社会组织为学生提供高质量体育服务。精准实施农村义务教育学生营养改善计划。健全学生视力健康综合干预体系，保障学生充足睡眠时间。\n6.增强美育熏陶。实施学校美育提升行动，严格落实音乐、美术、书法等课程，结合地方文化设立艺术特色课程。广泛开展校园艺术活动，帮助每位学生学会1至2项艺术技能、会唱主旋律歌曲。引导学生了解世界优秀艺术，增强文化理解。鼓励学校组建特色艺术团队，办好中小学生艺术展演，推进中华优秀传统文化艺术传承学校建设。通过购买服务等方式，鼓励专业艺术人才到中小学兼职任教。支持艺术院校在中小学建立对口支援基地。\n7.加强劳动教育。充分发挥劳动综合育人功能，制定劳动教育指导纲要，加强学生生活实践、劳动技术和职业体验教育。优化综合实践活动课程结构，确保劳动教育课时不少于一半。家长要给孩子安排力所能及的家务劳动，学校要坚持学生值日制度，组织学生参加校园劳动，积极开展校外劳动实践和社区志愿服务。创建一批劳动教育实验区，农村地区要安排相应田地、山林、草场等作为学农实践基地，城镇地区要为学生参加农业生产、工业体验、商业和服务业实践等提供保障。","level":1},{"name":"三、强化课堂主阵地作用，切实提高课堂教学质量","text":"8.优化教学方式。坚持教学相长，注重启发式、互动式、探究式教学，教师课前要指导学生做好预习，课上要讲清重点难点、知识体系，引导学生主动思考、积极提问、自主探究。融合运用传统与现代技术手段，重视情境教学；探索基于学科的课程综合化教学，开展研究型、项目化、合作式学习。精准分析学情，重视差异化教学和个别化指导。各地要定期开展聚焦课堂教学质量的主题活动，注重培育、遴选和推广优秀教学模式、教学案例。\n9.加强教学管理。省级教育部门要分学科制定课堂教学基本要求，市县级教育部门要指导学校形成教学管理特色。学校要健全教学管理规程，统筹制定教学计划，优化教学环节；开齐开足开好国家规定课程，不得随意增减课时、改变难度、调整进度；严格按课程标准零起点教学，小学一年级设置过渡性活动课程，注重做好幼小衔接；坚持和完善集体备课制度，认真制定教案。各地各校要切实加强课程实施日常监督，不得有提前结课备考、超标教学、违规统考、考试排名和不履行教学责任等行为。\n10.完善作业考试辅导。统筹调控不同年级、不同学科作业数量和作业时间，促进学生完成好基础性作业，强化实践性作业，探索弹性作业和跨学科作业，不断提高作业设计质量。杜绝将学生作业变成家长作业或要求家长检查批改作业，不得布置惩罚性作业。教师要认真批改作业，强化面批讲解，及时做好反馈。从严控制考试次数，考试内容要符合课程标准、联系学生生活实际，考试成绩实行等级评价，严禁以任何方式公布学生成绩和排名。建立学有困难学生帮扶制度，为学有余力学生拓展学习空间。各地要完善政策支持措施，不断提高课后服务水平。\n11.促进信息技术与教育教学融合应用。推进“教育+互联网”发展，按照服务教师教学、服务学生学习、服务学校管理的要求，建立覆盖义务教育各年级各学科的数字教育资源体系。加快数字校园建设，积极探索基于互联网的教学。免费为农村和边远贫困地区学校提供优质学习资源，加快缩小城乡教育差距。加强信息化终端设备及软件管理，建立数字化教学资源进校园审核监管机制。","level":1},{"name":"四、按照“四有好老师”标准，建设高素质专业化教师队伍","text":"12.大力提高教育教学能力。以新时代教师素质要求和国家课程标准为导向，改革和加强师范教育，提高教师培养培训质量。实施全员轮训，突出新课程、新教材、新方法、新技术培训，强化师德教育和教学基本功训练，不断提高教师育德、课堂教学、作业与考试命题设计、实验操作和家庭教育指导等能力。进一步实施好“国培计划”，增加农村教师培训机会，加强紧缺学科教师培训。实施乡村优秀青年教师培养奖励计划，定期开展教学素养展示和教学名师评选活动，对教育教学业绩突出的教师予以表彰奖励。\n13.优化教师资源配置。各地要按照中小学教职工编制标准做好编制核定工作，并制定小规模学校编制核定标准和通过政府购买服务方式为寄宿制学校提供生活服务的实施办法。对符合条件的非在编教师要加快入编，不得产生新的代课教师。县级教育部门要按照班额、生源等情况，在核定的总量内，统筹调配各校编制和岗位数量，并向同级机构编制、人力资源社会保障和财政部门备案。制定符合教师职业特点的公开招聘办法，充分发挥教育部门和学校在教师招聘中的重要作用，严格教师资格准入制度。实行教师资格定期注册制度，对不适应教育教学的应及时调整。加大县域内城镇与乡村教师双向交流、定期轮岗力度，建立学区（乡镇）内教师走教制度。进一步实施好农村教师“特岗计划”和“银龄讲学计划”。完善教师岗位分级认定办法，适当提高教师中、高级岗位比例。\n14.依法保障教师权益和待遇。制定教师优待办法，保障教师享有健康体检、旅游、住房、落户等优待政策。坚持教育投入优先保障并不断提高教师待遇。完善义务教育绩效工资总量核定办法，建立联动增长机制，确保义务教育教师平均工资收入水平不低于当地公务员平均工资收入水平。完善绩效工资分配办法，绩效工资增量主要用于奖励性绩效工资分配；切实落实学校分配自主权，并向教学一线和教学实绩突出的教师倾斜。落实乡村教师乡镇工作补贴、集中连片特困地区生活补助和艰苦边远地区津贴等政策，有条件的地方对在乡村有教学任务的教师给予交通补助。加强乡村学校教师周转宿舍建设。制定实施细则，明确教师教育惩戒权。依法依规妥善处理涉及学校和教师的矛盾纠纷，坚决维护教师合法权益。\n15.提升校长实施素质教育能力。校长是学校提高教育质量的第一责任人，应经常深入课堂听课、参与教研、指导教学，努力提高教育教学领导力。尊重校长岗位特点，完善选任机制与管理办法，推行校长职级制，努力造就一支政治过硬、品德高尚、业务精湛、治校有方的高素质专业化校长队伍。加大校长特别是乡村学校校长培训力度，开展校长国内外研修。倡导教育家办学，支持校长大胆实践，创新教育理念、教育模式、教育方法，营造教育家脱颖而出的制度环境。","level":1},{"name":"五、深化关键领域改革，为提高教育质量创造条件","text":"16.加强课程教材建设。国家建立义务教育课程方案、课程标准修订和实施监测机制，完善教材管理办法。省级教育部门制定地方课程和校本课程开发与实施指南，并建立审议评估和质量监测制度。县级教育部门要加强校本课程监管，构建学校间共建共享机制。学校要提高校本课程质量，校本课程原则上不编写教材。严禁用地方课程、校本课程取代国家课程，严禁使用未经审定的教材。义务教育学校不得引进境外课程、使用境外教材。完善义务教育装备基本标准，有条件的地方可建设创新实验室、综合实验室。\n17.完善招生考试制度。推进义务教育学校免试就近入学全覆盖。健全联控联保机制，精准做好控辍保学工作。严禁以各类考试、竞赛、培训成绩或证书证明等作为招生依据，不得以面试、评测等名义选拔学生。民办义务教育学校招生纳入审批地统一管理，与公办学校同步招生；对报名人数超过招生计划的，实行电脑随机录取。高中阶段学校实行基于初中学业水平考试成绩、结合综合素质评价的招生录取模式，落实优质普通高中招生指标分配到初中政策，公办民办普通高中按审批机关统一批准的招生计划、范围、标准和方式同步招生。稳步推进初中学业水平考试省级统一命题，坚持以课程标准为命题依据，不得制定考试大纲，不断提高命题水平。\n18.健全质量评价监测体系。建立以发展素质教育为导向的科学评价体系，国家制定县域义务教育质量、学校办学质量和学生发展质量评价标准。县域教育质量评价突出考查地方党委和政府对教育教学改革的价值导向、组织领导、条件保障和义务教育均衡发展情况等。学校办学质量评价突出考查学校坚持全面培养、提高学生综合素质以及办学行为、队伍建设、学业负担、社会满意度等。学生发展质量评价突出考查学生品德发展、学业发展、身心健康、兴趣特长和劳动实践等。坚持和完善国家义务教育质量监测制度，强化过程性和发展性评价，建立监测平台，定期发布监测报告。\n19.发挥教研支撑作用。加强和改进新时代教研工作，理顺教研管理体制，完善国家、省、市、县、校教研体系，有条件的地方应独立设置教研机构。明确教研员工作职责和专业标准，健全教研员准入、退出、考核激励和专业发展机制。建立专兼结合的教研队伍，省、市、县三级教研机构应配齐所有学科专职教研员。完善区域教研、校本教研、网络教研、综合教研制度，建立教研员乡村学校联系点制度。鼓励高等学校、科研机构等参与教育教学研究与改革工作。\n20.激发学校生机活力。推进现代学校制度建设，落实学校办学自主权，保障学校自主设立内设机构，依法依规实施教育教学活动、聘用教师及其他工作人员、管理使用学校经费等。各地要完善统筹协调机制，严格控制面向义务教育学校的各类审批、检查验收、创建评比等活动，未经当地教育部门同意，任何单位不得到学校开展有关活动。发挥优质学校示范辐射作用，完善强校带弱校、城乡对口支援等办学机制，促进新优质学校成长。对提高教育质量成效显著和发挥示范辐射作用突出的学校，应给予支持和奖励。\n21.实施义务教育质量提升工程。保障义务教育财政经费投入，加大对教师队伍建设、教育教学改革、提高教育质量经费支持力度。实施优秀教学成果推广应用计划，整合建设国家中小学生网络学习平台。推进义务教育薄弱环节改善与能力提升，重点加强乡村小规模学校和乡镇寄宿制学校建设，打造“乡村温馨校园”；加快消除城镇大班额，逐步降低班额标准，促进县域义务教育从基本均衡向优质均衡发展。","level":1},{"name":"六、加强组织领导，开创新时代义务教育改革发展新局面","text":"22.坚持党的全面领导。各级党委和政府要把办好义务教育作为重中之重，全面加强党的领导，切实履行省级和市级政府统筹实施、县级政府为主管理责任。党政有关负责人要牢固树立科学教育观、正确政绩观，严禁下达升学指标或片面以升学率评价学校和教师。要选优配强教育部门领导干部，特别是县级教育局局长。县级党委和政府每年要至少听取1次义务教育工作汇报，及时研究解决有关重大问题。加强学校党的建设，充分发挥学校党组织领导作用，强化党建带团建、队建。将校园安全纳入社会治理，完善校园安全风险防控体系和依法处理机制，坚决杜绝“校闹”行为，维护正常教育教学秩序。\n23.落实部门职责。教育部门要会同有关部门为深化教育教学改革、提高义务教育质量提供保障条件，切实管好学校。组织部门要加强对党政领导班子及有关领导干部履行教育职责的考核，按照干部管理权限做好教育部门和单位领导干部选拔任用工作，指导学校做好党建工作。宣传部门要抓好正面宣传和舆论引导工作，营造教书育人良好氛围。机构编制部门要做好学校编制核定工作。发展改革部门要将义务教育发展纳入国民经济和社会发展规划。自然资源、住房城乡建设部门要配合做好学校布局规划，统筹做好土地供给和学校建设工作。财政部门要加大财政投入，优化支出结构，确保义务教育经费落实到位。人力资源社会保障部门要依法落实教师待遇，为学校招聘教师提供支持。民政部门要牵头做好农村留守儿童关爱保护工作。网信、文化和旅游部门要推动提供更多儿童优秀文化产品，净化网络文化环境。党委政法委要协调公安、司法行政等政法机关和有关部门，加强校园及周边综合治理，维护校园正常秩序和师生合法权益。市场监督管理部门要做好校外培训机构登记、收费、广告、反垄断等监管工作。共青团组织要积极开展思想政治引领和价值引领。妇联要加强社区家庭教育指导服务，少先队等群团组织和关心下一代工作委员会要做好少年儿童有关教育引导和关爱保护工作。\n24.重视家庭教育。加快家庭教育立法，强化监护主体责任。加强社区家长学校、家庭教育指导服务站点建设，为家长提供公益性家庭教育指导服务。充分发挥学校主导作用，密切家校联系。家长要树立科学育儿观念，切实履行家庭教育职责，加强与孩子沟通交流，培养孩子的好思想、好品行、好习惯，理性帮助孩子确定成长目标，克服盲目攀比，防止增加孩子过重课外负担。\n25.强化考核督导。各级党委和政府要把全面提高义务教育质量纳入党政领导干部考核督查范围，并将结果作为干部选任、表彰奖励的重要参考。强化教育教学督导，将其作为对省、市、县级政府履行教育职责督导评估的重要内容，把结果作为评价政府履职行为、学校办学水平、实施绩效奖励的重要依据。对办学方向、教育投入、学校建设、教师队伍、教育生态等方面存在严重问题的地方，要依法依规追究当地政府和主要领导责任；对违背党的教育方针、背离素质教育导向、不按国家课程方案和课程标准实施教学等行为，要依法依规追究教育行政部门、学校、教师和有关人员责任。\n26.营造良好生态。全党全社会都要关心支持深化教育教学改革、全面提高义务教育质量工作。新闻媒体要坚持正确舆论导向，做好党的教育方针、科学教育观念和教育教学改革典型经验宣传报道。坚决治理校外违规培训和竞赛行为。大力营造义务教育持续健康协调发展的良好氛围，更好发挥义务教育在实现中华民族伟大复兴中国梦中的奠基作用。\n延伸阅读\n义务教育阶段教育教学改革纲领性文件出炉","level":1}]},{"id":"r0507","sections":[{"name":"中共中央办公厅印发《关于推进“两学一做”学习教育常态化制度化的意见》","text":"近日，中共中央办公厅印发了《关于推进“两学一做”学习教育常态化制度化的意见》，并发出通知，要求各地区各部门认真贯彻落实。","level":1},{"name":"","text":"通知指出，推进“两学一做”学习教育常态化制度化，是坚持思想建党、组织建党、制度治党紧密结合的有力抓手，是不断加强党的思想政治建设的有效途径，是全面从严治党的战略性、基础性工程。推进“两学一做”学习教育常态化制度化，对于进一步用习近平总书记系列重要讲话精神武装全党，确保全党更加紧密地团结在以习近平同志为核心的党中央周围，不断开创中国特色社会主义事业新局面，具有重大而深远的意义。各级党组织要从讲政治的高度，充分认识推进“两学一做”学习教育常态化制度化的重大意义，始终把思想教育作为第一位的任务，坚持用党章党规规范党组织和党员行为，用习近平总书记系列重要讲话精神武装头脑、指导实践、推动工作，教育引导广大党员学思践悟、知行合一，不断增强政治意识、大局意识、核心意识、看齐意识，做到政治合格、执行纪律合格、品德合格、发挥作用合格，确保党的组织充分履行职能、发挥核心作用，确保党员领导干部忠诚干净担当、发挥表率作用，确保广大党员党性坚强、发挥先锋模范作用。\n通知强调，推进“两学一做”学习教育常态化制度化，要坚持全覆盖、常态化、重创新、求实效，坚持学做结合，依托党委（党组）理论学习中心组学习、党支部“三会一课”等基本制度，融入日常、抓在经常，防止形式主义，防止“两张皮”。要紧密联系本地区本部门本单位实际，联系党员思想工作实际，突出分类指导，组织党员、干部经常自省修身、打扫思想灰尘，有什么问题解决什么问题，什么问题突出重点解决什么问题。领导机关要带头学、带头做，党委（党组）理论学习中心组学习要把学党章党规、学系列讲话作为主要内容，党员领导干部要把自己摆进去，不断改造自己，提高思想政治觉悟。要把党支部建设作为最重要的基本建设，充分发挥党支部教育管理党员的主体作用，树立党的一切工作到支部的鲜明导向。各级党委（党组）要认真履行主体责任，每年要对开展“两学一做”学习教育情况进行评估总结，一级抓一级，层层抓落实，带动基层党组织和广大党员奋发有为、敢于担当、建功立业，更加紧密地团结在以习近平同志为核心的党中央周围，为统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局提供坚强组织保证。\n通知要求，各地区各部门各单位党委（党组）要根据意见要求，结合实际制定具体实施方案，认真抓好落实，重要情况和意见建议及时报告党中央。\n《关于推进“两学一做”学习教育常态化制度化的意见》全文如下。\n2016年在全体党员中开展的“学党章党规、学系列讲话，做合格党员”学习教育，以尊崇党章、遵守党规为基本要求，以用习近平总书记系列重要讲话精神武装全党为根本任务，坚持基础在学、关键在做，着力解决突出问题，推动党内教育从“关键少数”向广大党员拓展、从集中性教育向经常性教育延伸，取得显著成效，受到各级党组织和广大党员欢迎。为贯彻落实党的十八届六中全会精神，持续推动全面从严治党突出“关键少数”并向基层延伸，现就推进“两学一做”学习教育常态化制度化提出如下意见。","level":0},{"name":"一、从讲政治的高度充分认识推进“两学一做”学习教育常态化制度化的重大意义","text":"党章是管党治党的总章程，党规是党员思想和行为的具体遵循。习近平总书记系列重要讲话是中国特色社会主义理论体系最新成果，是当代中国马克思主义最新发展，是我们党推进具有许多新的历史特点的伟大斗争、党的建设新的伟大工程、中国特色社会主义伟大事业的强大思想武器，是各级党组织和全体党员必须始终坚持的行动指南。做合格党员是对每名党员的基本要求。实践证明，开展“两学一做”学习教育，是坚持思想建党、组织建党、制度治党紧密结合的有力抓手，是不断加强党的思想政治建设的有效途径，为新形势下落实全面从严治党要求积累了成功经验。推进“两学一做”学习教育常态化制度化，对于进一步用习近平总书记系列重要讲话精神武装全党，加强和规范党内政治生活，保持党的先进性和纯洁性，增强党的生机活力，确保全党更加紧密地团结在以习近平同志为核心的党中央周围，激励全党为实现崇高理想和宏伟目标而不懈奋斗，不断开创中国特色社会主义事业新局面，具有重大而深远的意义。","level":1},{"name":"二、明确基本目标要求","text":"推进“两学一做”学习教育常态化制度化，必须紧密联系本地区本部门本单位实际，把思想教育作为首要任务，坚持用党章党规规范党组织和党员行为，用习近平总书记系列重要讲话精神武装头脑、指导实践、推动工作，坚持学思践悟、知行合一，坚持全覆盖、常态化、重创新、求实效，不断增强党组织和党员政治意识、大局意识、核心意识、看齐意识，不断增强党内政治生活的政治性、时代性、原则性、战斗性，不断增强党自我净化、自我完善、自我革新、自我提高能力，确保党的组织充分履行职能、发挥核心作用，确保党员领导干部忠诚干净担当、发挥表率作用，确保广大党员党性坚强、发挥先锋模范作用，为统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局提供坚强组织保证。\n坚持融入日常、抓在经常。各级党委（党组）要以理论学习中心组学习、民主生活会等制度为主要抓手，组织党员领导干部定期开展集体学习；基层党组织要以“三会一课”为基本制度，以党支部为基本单位，把“两学一做”作为党员教育的基本内容，长期坚持、形成常态。突出问题导向，建立完善及时发现和解决问题的有效机制，推动各级党组织和党员依靠自身力量修正错误、改进提高；注重以上率下，严格和规范双重组织生活制度，充分发挥领导机关、领导干部带头示范作用，防止“灯下黑”；强化分类指导，针对不同层级不同领域不同行业明确工作要求，体现具体化、精准化、差异化；激发基层活力，充分调动党支部积极性主动性创造性，探索创新党内教育和组织生活的有效方法；选树先进典型，宣传践行“两学一做”优秀党员先进事迹，树立时代楷模，引导党员、干部见贤思齐；坚持常抓不懈，防止和克服紧一阵松一阵、表面化形式化、学习教育与思想工作实际“两张皮”等不良倾向。","level":1},{"name":"三、精心安排学习内容","text":"各级党组织要切实执行《关于在全体党员中开展“学党章党规、学系列讲话，做合格党员”学习教育方案》等规定要求。各级党委（党组）和基层党组织要按年度作出学习安排，党员领导干部要根据自身实际制定个人自学计划，每年完成规定的学习任务。\n坚持读原著、学原文、悟原理，联系实际学、带着问题学、不断跟进学，领会掌握基本精神、基本内容、基本要求，做到学而信、学而思、学而行。学习党章党规，要深刻认识党章是管党治党的总规矩总遵循，践行党内政治生活准则、党内监督条例和廉洁自律准则等党内法规要求。学习习近平总书记系列重要讲话，要深刻认识讲话的重大理论意义和实践意义，深刻理解讲话的时代背景、鲜明主题、科学体系，准确把握蕴含其中的治国理政新理念新思想新战略，领会掌握贯穿其中的马克思主义立场观点方法。要把学习习近平总书记系列重要讲话同学习马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观紧密结合起来。党员领导干部在学习上要有更高标准、更高要求。","level":1},{"name":"四、引导党员做到“四个合格”","text":"各级党组织要教育引导广大党员按照“四讲四有”标准，做到政治合格、执行纪律合格、品德合格、发挥作用合格。在政治合格方面，重点是坚定理想信念，正确把握政治方向，坚定站稳政治立场，坚决维护以习近平同志为核心的党中央权威，不断增强中国特色社会主义道路自信、理论自信、制度自信、文化自信。在执行纪律合格方面，重点是增强组织纪律性，执行党的决定，服从组织分配，严守党的纪律特别是政治纪律和政治规矩。在品德合格方面，重点是继承发扬党的优良传统和作风，大力弘扬忠诚老实、光明坦荡、公道正派、实事求是、艰苦奋斗、清正廉洁等共产党人价值观，带头践行社会主义核心价值观。在发挥作用合格方面，重点是牢记党的根本宗旨，爱岗敬业、履职尽责，服务群众、奉献社会，敢担当、敢负责、敢作为，在促进改革发展稳定中作表率、当先锋。","level":1},{"name":"五、联系思想工作实际经常查找解决问题","text":"各级党组织和广大党员要坚持学做结合，突出针对性，敢于直面问题，勇于自我革命，把查找解决问题作为“两学一做”学习教育的规定要求。党员要对照党章党规，对照系列讲话，对照先进典型，把自己摆进去，经常自省修身，打扫思想灰尘、进行“党性体检”，有什么问题解决什么问题，什么问题突出重点解决什么问题；要查找分析理想信念是否坚定、对党是否忠诚老实、大是大非面前是否旗帜鲜明、是否做到在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致，着力解决党的意识不强、组织观念不强、发挥作用不够等问题。各级党委（党组）要查找分析是否落实全面从严治党主体责任，是否坚决执行党的理论和路线方针政策，是否认真坚持民主集中制，着力解决党的领导弱化、党的建设缺失、管党治党宽松软等问题。党支部要查找分析组织生活是否经常、认真、严肃，党员教育管理监督是否严格、规范，团结教育服务群众是否有力、到位，着力解决政治功能不强、组织软弱涣散、从严治党缺位等问题。\n要把党的组织生活作为查找和解决问题的重要途径，注意听取群众的意见和反映，抓早抓小、防微杜渐。民主生活会和组织生活会要严肃认真开展批评和自我批评，坚持“团结－批评－团结”，严于自我解剖，热忱帮助同志。谈心谈话要经常，坦诚相见、交流思想，发现问题及时提醒。各级党委（党组）要把本地区本部门本单位严重违纪违法干部忏悔录作为反面教材，认真开展警示教育。主要负责同志要在民主生活会上通报班子成员受到谈话函询情况；被谈话函询的党员领导干部，存在错误的应当作出深刻检查，受到提醒的应当作出整改表态，没有问题的说明谈话函询情况即可。民主评议党员要客观公正评价党员表现，帮助引导党员自觉认识问题、自我改进提高，严格稳慎处置不合格党员。","level":1},{"name":"六、坚持领导机关、领导干部率先垂范","text":"各级党委（党组）要把学党章党规、学系列讲话作为理论学习中心组学习的主要内容，确定主题，加强研讨式、互动式、调研式学习，发挥引领示范作用。党员领导干部特别是省部级领导干部要把“两学一做”作为锤炼党性的基本功、必修课，加强政治能力训练，加强政治历练，自觉把讲政治贯穿于日常工作生活全过程、贯穿于党性锻炼全过程，时刻牢记自己第一身份是党员，无论职务高低，都要以普通党员身份参加党的组织生活。要带头学习，认真学习党章党规，知敬畏、存戒惧、守底线；学深悟透习近平总书记系列重要讲话精神，不断增强“四个意识”，始终坚定理想信念、坚定“四个自信”，真正做到思想认同、政治看齐、行动紧跟。要带头做合格党员、合格领导干部，时刻检视存在的差距和不足，自觉同特权思想和特权现象作斗争，不断改造自己，提高思想政治觉悟。要践行“三严三实”要求，履职尽责、奋发有为，敢于担当、建功立业，重实干、务实功、办实事、求实效，努力创造经得起实践、人民、历史检验的实绩。要严格执行中央八项规定精神，密切联系群众，切实改进作风，严格要求自己和身边工作人员，注重家庭、家教、家风，保持清正廉洁的政治本色。","level":1},{"name":"七、把“两学一做”学习教育纳入党支部“三会一课”等基本制度","text":"党支部是党最基本的组织，是党全部工作和战斗力的基础。要树立党的一切工作到支部的鲜明导向，注重把思想政治工作落到支部，把从严教育管理党员落到支部，把群众工作落到支部。各领域各行业党支部要充分发挥教育管理党员的主体作用，运用“三会一课”等制度抓好“两学一做”学习教育，真正成为教育党员的学校、团结群众的核心、攻坚克难的堡垒。\n党支部要组织党员按期参加党员大会、党小组会和上党课，定期召开支部委员会会议。坚持党员领导干部讲党课制度，各级党委（党组）书记每年至少为基层党员讲一次党课，党课内容要贴近党员、贴近实际，不搞照本宣科。“三会一课”要突出政治学习和教育，突出党性锻炼，坚决防止表面化、形式化、娱乐化、庸俗化。要以学习党章党规、学习习近平总书记系列重要讲话为主要内容，针对党员思想工作实际，确定“三会一课”的主题和具体方式，做到形式多样、氛围庄重。推广党支部主题党日，组织党员在主题党日开展“三会一课”、交纳党费、参加服务群众等活动。利用红色教育基地等开展开放式组织生活。党支部要制定年度“三会一课”计划并报上级党组织备案，如实记录“三会一课”开展情况，对没有正当理由长期不参加“三会一课”的党员，要进行批评教育，促其改正。上级党组织要对党支部执行“三会一课”情况进行指导检查，对不经常、不认真、不严肃的，要批评指正；情况严重的，要采取整顿等措施，进行组织处理。\n要把党支部建设作为最重要的基本建设。在各类基层单位中合理设置党支部，不断扩大党的组织和工作覆盖。指导党支部健全各项工作制度，按期进行换届，选好配强党支部班子，把优秀党员选拔到支部书记岗位。加强对党支部书记的培训，帮助其提高党务工作能力。建立党支部工作经常性督查指导机制，持续整顿软弱涣散党支部，为党支部开展工作和活动提供必要保障。","level":1},{"name":"八、层层推动工作落实","text":"各级党组织要把推进“两学一做”学习教育常态化制度化作为全面从严治党的战略性、基础性工程，高度重视，精心组织，抓常抓细抓长。党委（党组）要切实履行主体责任，每年要专门研究部署，一级抓一级，层层抓落实。组织部门要作出具体工作安排，加强督促指导。要发挥“两学一做”学习教育常态化制度化的带动效应，加强基层党建工作薄弱环节，每年梳理分析工作短板，研究确定若干重点任务，集中力量攻坚克难。\n把组织开展“两学一做”学习教育情况纳入各级党组织党建工作考核的重要内容，每年结合总结、述职进行检查和评估，作为评判党组织和党组织书记履行管党治党责任情况的重要依据，注重从党支部工作成效和党员作用发挥看效果、让党员群众作评价。要及时总结交流新鲜经验，发现和解决存在问题。对工作落实不力、搞形式走过场的，要严肃批评、追责问责。\n延伸阅读\n人民日报评论员：全面从严治党的战略性基础性工程——论推进“两学一做”学习教育常态化制度化\n一图读懂关于推进“两学一做”学习教育常态化制度化的意见","level":1}]},{"id":"r0508","sections":[{"name":"党委（党组）落实全面从严治党主体责任规定","text":"党委（党组）落实全面从严治党主体责任规定\n（2020年2月26日中共中央政治局常委会会议审议批准 2020年3月9日中共中央办公厅发布）","level":1},{"name":"第一章 总则","text":"第一条 为了全面落实党委（党组）全面从严治党主体责任，推动全面从严治党向纵深发展，根据《中国共产党章程》和有关党内法规，制定本规定。\n第二条 本规定适用于地方党委和按照《中国共产党党组工作条例》设立的党组（党委）。\n党的纪律检查机关、党的工作机关、党委直属事业单位在本单位落实全面从严治党主体责任，党的基层组织落实全面从严治党主体责任，参照本规定执行。\n第三条 党委（党组）必须深入贯彻习近平新时代中国特色社会主义思想，增强“四个意识”、坚定“四个自信”、做到“两个维护”，不忘初心、牢记使命，守责、负责、尽责，一以贯之、坚定不移全面从严治党，以伟大自我革命引领伟大社会革命，以科学理论引领全党理想信念，以“两个维护”引领全党团结统一，以正风肃纪反腐凝聚党心军心民心，永葆党的先进性和纯洁性，确保党始终成为中国特色社会主义事业的坚强领导核心。\n第四条 党委（党组）落实全面从严治党主体责任，应当遵循以下原则：\n（一）坚持紧紧围绕加强和改善党的全面领导；\n（二）坚持全面从严治党各领域各方面各环节全覆盖；\n（三）坚持真管真严、敢管敢严、长管长严；\n（四）坚持全面从严治党过程和效果相统一。\n第五条 中央和国家机关在全面从严治党中具有特殊地位和作用，必须在落实全面从严治党责任中走在前、作表率，全面提高机关党的建设质量，建设让党中央放心、让人民群众满意的模范机关，引领带动各地区各部门抓好全面从严治党。","level":1},{"name":"第二章 责任内容","text":"第六条 地方党委应当将党的建设与经济社会发展同谋划、同部署、同推进、同考核，加强对本地区全面从严治党各项工作的领导。主要包括：\n（一）坚决维护以习近平同志为核心的党中央权威和集中统一领导，坚决贯彻执行党中央决策部署以及上级党组织决定；\n（二）在本地区发挥总揽全局、协调各方的领导作用，在经济社会发展各项工作中坚持和加强党的全面领导，在同级各种组织中发挥领导作用；\n（三）把党的政治建设摆在首位，坚定政治信仰，强化政治领导，提高政治能力，净化政治生态，始终在政治立场、政治方向、政治原则、政治道路上同党中央保持高度一致；\n（四）把党的思想建设作为基础性建设来抓，坚定理想信念，用习近平新时代中国特色社会主义思想武装头脑、指导实践、推动工作，落实意识形态工作责任制；\n（五）贯彻新时代党的组织路线，坚持民主集中制，树立和坚持正确选人用人导向，建设忠诚干净担当的高素质专业化干部队伍，加强党的基层组织和党员队伍建设，做好人才工作，夯实党执政的组织基础；\n（六）持之以恒抓好党的作风建设，落实中央八项规定精神，持续整治“四风”特别是形式主义、官僚主义，反对特权思想和特权现象，密切党同人民群众的血肉联系；\n（七）加强党的纪律建设，重点强化政治纪律和组织纪律，带动廉洁纪律、群众纪律、工作纪律、生活纪律严起来；\n（八）落实制度治党、依规治党要求，加强本地区党内法规制度建设，严格落实党内法规执行责任制，确保党内法规制度落地见效；\n（九）落实党风廉政建设主体责任，深入推进反腐败斗争，一体推进不敢腐、不能腐、不想腐，巩固发展反腐败斗争压倒性胜利；\n（十）领导、支持和监督党的纪律检查机关、党的工作机关、党委直属事业单位、党组（党委）和下级地方党委、党的基层组织等落实全面从严治党主体责任，形成全面从严治党整体合力；\n（十一）加强对本地区统一战线工作和群团工作的领导，动员、组织所属党组织和广大党员，团结带领群众实现党的目标任务；\n（十二）勇于和善于结合本地区实际，切实解决影响全面从严治党的突出问题。\n第七条 党组（党委）应当坚持党建工作与业务工作同谋划、同部署、同推进、同考核，加强对本单位（本系统）全面从严治党各项工作的领导。主要包括：\n（一）坚决维护以习近平同志为核心的党中央权威和集中统一领导，坚决贯彻执行党中央决策部署以及上级党组织决定；\n（二）在本单位（本系统）发挥把方向、管大局、保落实的领导作用，推动党的主张和重大决策转化为法律法规、政策政令和社会共识，确保党的理论和路线方针政策在本单位（本系统）贯彻落实；\n（三）把党的政治建设摆在首位，提高政治站位，彰显政治属性，强化政治引领，增强政治能力，始终在政治立场、政治方向、政治原则、政治道路上同党中央保持高度一致，涵养良好的机关政治生态；\n（四）强化理论武装，学懂弄通做实习近平新时代中国特色社会主义思想，引导党员、干部坚定理想信念宗旨，落实意识形态工作责任制；\n（五）坚持民主集中制，贯彻党管干部、党管人才原则，加强忠诚干净担当的高素质专业化干部队伍建设，加强党的基层组织和党员队伍建设，着力提高党内活动和党的组织生活质量，做好人才工作；\n（六）加强和改进作风，落实中央八项规定精神，持续整治“四风”特别是形式主义、官僚主义，反对特权思想和特权现象；\n（七）加强党的纪律建设，履行党风廉政建设主体责任，支持纪检监察机关履行监督责任，一体推进不敢腐、不能腐、不想腐；\n（八）带头遵守党内法规制度，严格落实党内法规执行责任制，建立健全本单位（本系统）党建工作制度，不断提高制度执行力；\n（九）领导机关和直属单位党组织的工作，支持配合党的机关工委对本单位（本系统）党的工作的统一领导，自觉接受党的机关工委对其履行机关党建主体责任的指导督促，防止出现“灯下黑”；\n（十）加强对本单位（本系统）统一战线工作和群团工作的领导，重视对党外干部、人才的培养使用，团结带领党外干部和群众，凝聚各方面智慧力量，完成党中央以及上级党组织交给的任务；\n（十一）勇于和善于结合本单位（本系统）实际，切实解决影响全面从严治党的突出问题。\n第八条 党委（党组）领导班子成员应当强化责任担当，狠抓责任落实，增强落实全面从严治党责任的自觉和能力，带头遵守执行全面从严治党各项规定，自觉接受党组织、党员和群众监督，在全面从严治党中发挥示范表率作用。\n党委（党组）书记应当履行本地区本单位全面从严治党第一责任人职责，做到重要工作亲自部署、重大问题亲自过问、重点环节亲自协调、重要案件亲自督办；管好班子、带好队伍、抓好落实，支持、指导和督促领导班子其他成员、下级党委（党组）书记履行全面从严治党责任，发现问题及时提醒纠正。\n党委（党组）领导班子其他成员根据工作分工对职责范围内的全面从严治党工作负重要领导责任，按照“一岗双责”要求，领导、检查、督促分管部门和单位全面从严治党工作，对分管部门和单位党员干部从严进行教育管理监督。\n第九条 党的建设工作领导小组是党委抓全面从严治党的议事协调机构，应当加强对本地区党的建设工作的指导，定期听取工作汇报，及时研究解决重大问题。\n党的纪律检查机关在履行全面从严治党监督责任同时，应当通过重大事项请示报告、提出意见建议、监督推动党委（党组）决策落实等方式，协助党委（党组）落实全面从严治党主体责任。\n党委办公厅（室）、职能部门、办事机构等是党委抓全面从严治党的具体执行机关，应当在党委统一领导下充分发挥职能作用，在职责范围内抓好全面从严治党相关工作。\n党的机关工委作为党委派出机关，应当统一组织、规划、部署本级机关党的工作，指导机关开展党的各方面建设，指导机关各级党组织实施对党员特别是党员领导干部的监督和管理。\n部门和单位机关党委作为机关党建工作专责机构，应当聚焦主责主业，充分发挥职能作用，协助党组（党委）落实全面从严治党主体责任。","level":1},{"name":"第三章 责任落实","text":"第十条 党委（党组）每半年应当至少召开1次常委会会议（党组会议）专题研究全面从严治党工作，分析研判形势，研究解决瓶颈和短板，提出加强和改进的措施。\n第十一条 党委（党组）可以根据本规定，结合实际制定责任清单，具体明确党委（党组）及其书记和领导班子其他成员承担的全面从严治党责任。制定责任清单，应当坚持简便易行、务实管用。\n第十二条 党委（党组）每年年初应当根据党中央决策部署以及上级党组织决定，结合本地区本单位全面从严治党形势和任务，坚持问题导向，突出工作重点，制定本地区本单位落实全面从严治党主体责任的年度任务安排，明确责任分工和完成时限。\n第十三条 党委（党组）书记应当加强对全面从严治党的调查研究，了解工作推进情况，发现和解决实践中的突出问题。\n调查研究应当注重听取党的代表大会代表、党员、干部、基层党组织和群众关于全面从严治党的意见建议。\n第十四条 党委（党组）应当开展经常性的全面从严治党宣传教育，特别是党章党规和党性党风党纪教育，注重发挥正反典型的示范警示作用，在本地区本单位营造全面从严治党良好氛围。\n第十五条 党委（党组）及其领导班子成员应当将落实全面从严治党责任情况作为年度民主生活会对照检查内容，深入查摆存在的问题，开展严肃认真的批评和自我批评，提出务实管用的整改措施。\n本地区本单位发生重大违纪违法案件、严重“四风”问题，党委（党组）应当及时召开专题民主生活会，认真对照检查，深刻剖析反思，明确整改责任。\n第十六条 党委（党组）书记对领导班子其他成员、下一级党委（党组）书记，领导班子其他成员对分管部门和单位党组织书记，发现存在政治、思想、工作、生活、作风、纪律等方面苗头性、倾向性问题的，应当及时进行提醒谈话；发现落实全面从严治党责任不到位、管党治党问题较多、党员群众来信来访反映问题较多的，应当及时进行约谈，严肃批评教育，督促落实责任。\n第十七条 党委（党组）应当通过会议、文件等形式通报本地区本单位落实全面从严治党主体责任情况，及时通报因责任落实不力被问责的典型问题，采取组织调整或者组织处理、纪律处分方式问责的，应当以适当方式公开。\n第十八条 党委（党组）应当开展有针对性的教育培训，强化政治教育和政治训练，增强本地区本单位党组织和党员领导干部落实全面从严治党责任的意识，提高落实全面从严治党责任的能力和水平。","level":1},{"name":"第四章 监督追责","text":"第十九条 地方党委每年年初应当向上一级党委书面报告上一年度落实全面从严治党主体责任情况。地方党委常委会应当将落实全面从严治党主体责任情况作为向全会报告工作的一项重要内容。\n党组（党委）每年年初应当向批准其设立的党组织书面报告上一年度落实全面从严治党主体责任情况。\n第二十条 上级党组织应当加强对党委（党组）落实全面从严治党主体责任情况的监督检查和巡视巡察，着力发现和解决责任不明确、不全面、不落实等问题。\n监督检查和巡视巡察中，应当注重发挥党员、干部、基层党组织和群众、新闻媒体等的作用，推动形成监督合力。\n第二十一条 统筹党风廉政建设、意识形态工作、基层党建工作等方面考核，结合领导班子和领导干部考核，建立健全落实全面从严治党主体责任考核制度，在年度考核和相关考核工作中突出了解全面从严治党责任落实情况。\n考核结果在本地区本单位一定范围内公布。考核结果作为对领导班子总体评价和领导干部选拔任用、实绩评价、激励约束的重要依据。\n第二十二条 党委（党组）及其领导班子成员落实全面从严治党责任，有下列情形之一的，应当依规依纪追究责任：\n（一）贯彻执行党中央关于全面从严治党重大决策部署以及上级党组织有关决定不认真、不得力；\n（二）履行全面从严治党第一责任人职责、重要领导责任不担当、不作为；\n（三）本地区本单位政治意识淡化、党的领导弱化、党建工作虚化、责任落实软化，管党治党宽松软；\n（四）本地区本单位在管党治党方面出现重大问题或者造成严重后果；\n（五）其他应当追究责任的情形。","level":1},{"name":"第五章 附则","text":"第二十三条 中央军事委员会可以根据本规定，制定军队党委落实全面从严治党主体责任规定。\n第二十四条 本规定由中央办公厅负责解释。\n第二十五条 本规定自发布之日起施行。\n延伸阅读\n落实全面从严治党责任，有这些情形会被追责","level":1}]},{"id":"r0509","sections":[{"name":"司法机关内部人员过问案件的记录和责任追究规定","text":"中央政法委近日印发《司法机关内部人员过问案件的记录和责任追究规定》，规定全文如下：\n司法机关内部人员过问案件的记录和责任追究规定","level":1},{"name":"","text":"第一条 为贯彻落实《中共中央关于全面推进依法治国若干重大问题的决定》有关要求，防止司法机关内部人员干预办案，确保公正廉洁司法，根据宪法法律规定，结合司法工作实际，制定本规定。\n第二条 司法机关内部人员应当依法履行职责，严格遵守纪律，不得违反规定过问和干预其他人员正在办理的案件，不得违反规定为案件当事人转递涉案材料或者打探案情，不得以任何方式为案件当事人说情打招呼。\n第三条 司法机关办案人员应当恪守法律，公正司法，不徇私情。对于司法机关内部人员的干预、说情或者打探案情，应当予以拒绝；对于不依正当程序转递涉案材料或者提出其他要求的，应当告知其依照程序办理。\n第四条 司法机关领导干部和上级司法机关工作人员因履行领导、监督职责，需要对正在办理的案件提出指导性意见的，应当依照程序以书面形式提出，口头提出的，由办案人员记录在案。\n第五条 其他司法机关的工作人员因履行法定职责需要，向办案人员了解正在办理的案件有关情况的，应当依照法律程序或者工作程序进行。\n第六条 对司法机关内部人员过问案件的情况，办案人员应当全面、如实记录，做到全程留痕，有据可查。\n第七条 办案人员如实记录司法机关内部人员过问案件的情况，受法律和组织保护。\n司法机关内部人员不得对办案人员打击报复。办案人员非因法定事由，非经法定程序，不得被免职、调离、辞退或者给予降级、撤职、开除等处分。\n第八条 司法机关纪检监察部门应当及时汇总分析司法机关内部人员过问案件的情况，并依照以下方式对司法机关内部人员违反规定干预办案的线索进行处置：\n（一）机关内部人员违反规定干预办案的，由本机关纪检监察部门调查处理；\n（二）本机关领导干部违反规定干预办案的，向负有干部管理权限的机关纪检监察部门报告情况；\n（三）上级司法人员违反规定干预下级司法机关办案的，向干预人员所在司法机关纪检监察部门报告情况；\n（四）其他没有隶属关系的司法机关人员违反规定干预办案的，向干预人员所在司法机关纪检监察部门通报情况。\n干预人员所在司法机关纪检监察部门接到报告或者通报后，应当及时调查处理，并将结果通报办案单位所属司法机关纪检监察部门。\n第九条 司法机关内部人员有下列行为之一的，属于违反规定干预办案，负有干部管理权限的司法机关按程序报经批准后予以通报，必要时可以向社会公开：\n（一）在线索核查、立案、侦查、审查起诉、审判、执行等环节为案件当事人请托说情的；\n（二）邀请办案人员私下会见案件当事人或其辩护人、诉讼代理人、近亲属以及其他与案件有利害关系的人的；\n（三）违反规定为案件当事人或其辩护人、诉讼代理人、亲属转递涉案材料的；\n（四）违反规定为案件当事人或其辩护人、诉讼代理人、亲属打探案情、通风报信的；\n（五）其他影响司法人员依法公正处理案件的行为。\n第十条 司法机关内部人员有本规定第九条所列行为之一，构成违纪的，依照《中国共产党纪律处分条例》、《行政机关公务员处分条例》、《人民法院工作人员处分条例》、《检察人员纪律处分条例（试行）》、《公安机关人民警察纪律条令》等规定给予纪律处分；构成犯罪的，依法追究刑事责任。\n司法机关内部人员对如实记录过问案件情况的办案人员进行打击报复的，依照《中国共产党纪律处分条例》、《行政机关公务员处分条例》、《人民法院工作人员处分条例》、《检察人员纪律处分条例（试行）》、《公安机关人民警察纪律条令》等规定给予纪律处分；构成犯罪的，依法追究刑事责任。\n第十一条 办案人员不记录或者不如实记录司法机关内部人员过问案件情况的，予以警告、通报批评；两次以上不记录或者不如实记录的，依照《中国共产党纪律处分条例》、《行政机关公务员处分条例》、《人民法院工作人员处分条例》、《检察人员纪律处分条例（试行）》、《公安机关人民警察纪律条令》等规定给予纪律处分。主管领导授意不记录或者不如实记录的，依法依纪追究主管领导责任。\n第十二条 司法机关内部人员违反规定过问和干预办案的情况和办案人员记录司法机关内部人员过问案件的情况，应当纳入党风廉政建设责任制和政绩考核体系，作为考核干部是否遵守法律、依法办事、廉洁自律的重要依据。\n第十三条 本规定所称司法机关内部人员，是指在法院、检察院、公安机关、国家安全机关、司法行政机关工作的人员。\n司法机关离退休人员违反规定干预办案的，适用本规定。\n第十四条 最高人民法院、最高人民检察院、公安部、国家安全部、司法部应当结合工作实际，制定本规定的实施办法，确保有关规定落到实处。\n第十五条 本规定自下发之日起施行。\n延伸阅读：\n中央司法体制改革领导小组办公室负责人就《司法机关内部人员过问案件的记录和责任追究规定》答记者问","level":0}]},{"id":"r0510","sections":[{"name":"中共中央办公厅 国务院办公厅印发《育儿补贴制度实施方案》","text":"近日，中共中央办公厅、国务院办公厅印发了《育儿补贴制度实施方案》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《育儿补贴制度实施方案》主要内容如下。\n为贯彻落实党中央关于完善生育支持政策体系和激励机制的决策部署，推动建设生育友好型社会，制定本方案。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，坚持以人民为中心的发展思想，在发展中保障和改善民生，建立实施育儿补贴制度，营造生育友好社会氛围。\n工作中要做到：坚持改善民生、惠民利民，有效降低家庭生育养育成本；坚持统筹衔接、保障公平，与现行民生政策相衔接，确保符合条件的婴幼儿平等享受补贴；坚持尽力而为、量力而行，统筹考虑人口发展状况和经济社会发展水平，合理确定补贴范围和标准，确保财政可负担、政策可持续；坚持安全规范、简便易行，严格资格审核，规范发放流程，提高办事效率，确保资金安全，切实把好事办好。","level":1},{"name":"二、补贴对象和标准","text":"（一）补贴对象。从2025年1月1日起，对符合法律法规规定生育的3周岁以下婴幼儿发放补贴，至其年满3周岁。\n（二）补贴标准。育儿补贴按年发放，现阶段国家基础标准为每孩每年3600元。其中，对2025年1月1日之前出生、不满3周岁的婴幼儿，按应补贴月数折算计发补贴。对按照育儿补贴制度规定发放的育儿补贴免征个人所得税。在最低生活保障对象、特困人员等救助对象认定时，育儿补贴不计入家庭或个人收入。","level":1},{"name":"三、申领程序","text":"育儿补贴由婴幼儿的父母一方或其他监护人按规定向婴幼儿户籍所在地申领。具体程序如下。\n（一）申请。申领人填写有关信息，提供婴幼儿的出生医学证明、户口簿等材料，并对所提供信息及材料的真实性、完整性作出承诺。申领人主要通过育儿补贴信息管理系统线上申请，也可线下申请。\n（二）初审。婴幼儿户籍所在地乡镇政府（街道办事处）对申请信息进行初审，村（居）民委员会协助做好相关工作。\n（三）审核确认。县级卫生健康部门进行审核确认，并将相关信息提供给同级财政部门。\n（四）抽查。市级卫生健康部门按一定比例，对补贴对象信息进行抽查。省级卫生健康部门根据需要开展抽查，实行动态监管，确保资金安全。","level":1},{"name":"四、资金来源和补贴发放","text":"（一）财政分担比例。中央财政自2025年起设立共同财政事权转移支付项目“育儿补贴补助资金”，对发放国家基础标准育儿补贴所需资金，按比例对东部、中部、西部地区予以补助。地方提标部分所需资金由地方财政自行承担。\n（二）补贴发放时间。各省份结合实际确定具体发放时间，提高发放效率，确保补贴及时足额发放到位。\n（三）补贴发放渠道。发放渠道为申领人或婴幼儿的银行卡或其他金融账户，鼓励通过惠民惠农财政补贴资金“一卡通”或婴幼儿的社会保障卡发放。","level":1},{"name":"五、管理和监督","text":"（一）信息管理。建立全国统一的育儿补贴信息管理系统，结合“出生一件事”联办，强化地区间、部门间信息共享。建立信息管理制度，做好信息收集、处理和利用等工作，落实信息安全责任，保障个人信息安全。加强信息动态监测，定期开展数据汇总分析，为做好政策评估及调整优化提供支持。\n（二）全程监督。审计部门、财政部门要加强全过程监督检查。纪检监察机关要强化监督执纪问责，严肃查处损害群众利益的不正之风和腐败问题。育儿补贴制度实施情况主动接受社会监督。卫生健康部门、财政部门加强资金使用管理，适时组织开展绩效评价，切实提高资金使用效益。","level":1},{"name":"六、加强组织实施","text":"（一）加强组织领导。在党中央集中统一领导下，各地区各有关部门要精心组织安排，明确职责分工，确保责任到位、保障到位、落实到位。省级政府要加强统筹管理和财政承受能力评估，确保育儿补贴政策与本地区经济社会发展水平相协调、与同类地区保持大体平衡，确保本级财政和下级财政可承受、可持续。省级卫生健康部门、财政部门要根据本方案，结合本地区人口与发展实际，制定本省份实施方案，经省级政府同意后，报国家卫生健康委、财政部备案。育儿补贴制度有关管理规范由国家卫生健康委、财政部另行制定。\n（二）做好衔接规范。各省份在市级行政区域内执行统一的育儿补贴政策及标准，地区差异较小的省份也可在本省份内执行统一的育儿补贴政策及标准。县级以下政府不得自行出台育儿补贴政策或标准。省级或市级政府部门拟出台其他育儿补贴政策或提标的，应加强事前论证评估，并按照民生政策备案有关要求，报上一级主管部门备案。\n（三）增强实施效果。结合孕产妇保健、住院分娩和婴幼儿预防接种、健康管理、户籍登记、社会保障卡申领等，优化服务流程，做好政策宣传解读，提高群众知晓率。各地区各有关部门要深入调研，广泛听取意见建议，评估育儿补贴制度实施情况，及时总结经验做法、完善政策措施。","level":1}]},{"id":"r0511","sections":[{"name":"中共中央 国务院关于学习运用“千村示范、万村整治”工程经验有力有效推进乡村全面振兴的意见","text":"中共中央 国务院关于学习运用“千村示范、万村整治”工程经验有力有效推进乡村全面振兴的意见\n（2024年1月1日）","level":1},{"name":"","text":"推进中国式现代化，必须坚持不懈夯实农业基础，推进乡村全面振兴。习近平总书记在浙江工作时亲自谋划推动“千村示范、万村整治”工程（以下简称“千万工程”），从农村环境整治入手，由点及面、迭代升级，20年持续努力造就了万千美丽乡村，造福了万千农民群众，创造了推进乡村全面振兴的成功经验和实践范例。要学习运用“千万工程”蕴含的发展理念、工作方法和推进机制，把推进乡村全面振兴作为新时代新征程“三农”工作的总抓手，坚持以人民为中心的发展思想，完整、准确、全面贯彻新发展理念，因地制宜、分类施策，循序渐进、久久为功，集中力量抓好办成一批群众可感可及的实事，不断取得实质性进展、阶段性成果。\n做好2024年及今后一个时期“三农”工作，要以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的二十大和二十届二中全会精神，深入贯彻落实习近平总书记关于“三农”工作的重要论述，坚持和加强党对“三农”工作的全面领导，锚定建设农业强国目标，以学习运用“千万工程”经验为引领，以确保国家粮食安全、确保不发生规模性返贫为底线，以提升乡村产业发展水平、提升乡村建设水平、提升乡村治理水平为重点，强化科技和改革双轮驱动，强化农民增收举措，打好乡村全面振兴漂亮仗，绘就宜居宜业和美乡村新画卷，以加快农业农村现代化更好推进中国式现代化建设。","level":0},{"name":"一、确保国家粮食安全","text":"（一）抓好粮食和重要农产品生产。扎实推进新一轮千亿斤粮食产能提升行动。稳定粮食播种面积，把粮食增产的重心放到大面积提高单产上，确保粮食产量保持在1.3万亿斤以上。实施粮食单产提升工程，集成推广良田良种良机良法。巩固大豆扩种成果，支持发展高油高产品种。适当提高小麦最低收购价，合理确定稻谷最低收购价。继续实施耕地地力保护补贴和玉米大豆生产者补贴、稻谷补贴政策。完善农资保供稳价应对机制，鼓励地方探索建立与农资价格上涨幅度挂钩的动态补贴办法。扩大完全成本保险和种植收入保险政策实施范围，实现三大主粮全国覆盖、大豆有序扩面。鼓励地方发展特色农产品保险。推进农业保险精准投保理赔，做到应赔尽赔。完善巨灾保险制度。加大产粮大县支持力度。探索建立粮食产销区省际横向利益补偿机制，深化多渠道产销协作。扩大油菜面积，支持发展油茶等特色油料。加大糖料蔗种苗和机收补贴力度。加强“菜篮子”产品应急保供基地建设，优化生猪产能调控机制，稳定牛羊肉基础生产能力。完善液态奶标准，规范复原乳标识，促进鲜奶消费。支持深远海养殖，开发森林食品。树立大农业观、大食物观，多渠道拓展食物来源，探索构建大食物监测统计体系。\n（二）严格落实耕地保护制度。健全耕地数量、质量、生态“三位一体”保护制度体系，落实新一轮国土空间规划明确的耕地和永久基本农田保护任务。改革完善耕地占补平衡制度，坚持“以补定占”，将省域内稳定利用耕地净增加量作为下年度非农建设允许占用耕地规模上限。健全补充耕地质量验收制度，完善后续管护和再评价机制。加强退化耕地治理，加大黑土地保护工程推进力度，实施耕地有机质提升行动。严厉打击非法占用农用地犯罪和耕地非法取土。持续整治“大棚房”。分类稳妥开展违规占用耕地整改复耕，细化明确耕地“非粮化”整改范围，合理安排恢复时序。因地制宜推进撂荒地利用，宜粮则粮、宜经则经，对确无人耕种的支持农村集体经济组织多途径种好用好。\n（三）加强农业基础设施建设。坚持质量第一，优先把东北黑土地区、平原地区、具备水利灌溉条件地区的耕地建成高标准农田，适当提高中央和省级投资补助水平，取消各地对产粮大县资金配套要求，强化高标准农田建设全过程监管，确保建一块、成一块。鼓励农村集体经济组织、新型农业经营主体、农户等直接参与高标准农田建设管护。分区分类开展盐碱耕地治理改良，“以种适地”同“以地适种”相结合，支持盐碱地综合利用试点。推进重点水源、灌区、蓄滞洪区建设和现代化改造，实施水库除险加固和中小河流治理、中小型水库建设等工程。加强小型农田水利设施建设和管护。加快推进受灾地区灾后恢复重建。加强气象灾害短期预警和中长期趋势研判，健全农业防灾减灾救灾长效机制。推进设施农业现代化提升行动。\n（四）强化农业科技支撑。优化农业科技创新战略布局，支持重大创新平台建设。加快推进种业振兴行动，完善联合研发和应用协作机制，加大种源关键核心技术攻关，加快选育推广生产急需的自主优良品种。开展重大品种研发推广应用一体化试点。推动生物育种产业化扩面提速。大力实施农机装备补短板行动，完善农机购置与应用补贴政策，开辟急需适用农机鉴定“绿色通道”。加强基层农技推广体系条件建设，强化公益性服务功能。\n（五）构建现代农业经营体系。聚焦解决“谁来种地”问题，以小农户为基础、新型农业经营主体为重点、社会化服务为支撑，加快打造适应现代农业发展的高素质生产经营队伍。提升家庭农场和农民合作社生产经营水平，增强服务带动小农户能力。加强农业社会化服务平台和标准体系建设，聚焦农业生产关键薄弱环节和小农户，拓展服务领域和模式。支持农村集体经济组织提供生产、劳务等居间服务。\n（六）增强粮食和重要农产品调控能力。健全农产品全产业链监测预警机制，强化多品种联动调控、储备调节和应急保障。优化粮食仓储设施布局，提升储备安全水平。深化“一带一路”农业合作。加大农产品走私打击力度。加强粮食和重要农产品消费监测分析。\n（七）持续深化食物节约各项行动。弘扬节约光荣风尚，推进全链条节粮减损，健全常态化、长效化工作机制。挖掘粮食机收减损潜力，推广散粮运输和储粮新型装具。完善粮食适度加工标准。大力提倡健康饮食，健全部门监管、行业自律、社会监督相结合的监管体系，坚决制止餐饮浪费行为。","level":1},{"name":"二、确保不发生规模性返贫","text":"（八）落实防止返贫监测帮扶机制。压紧压实防止返贫工作责任，持续巩固提升“三保障”和饮水安全保障成果。对存在因灾返贫风险的农户，符合政策规定的可先行落实帮扶措施。加强农村高额医疗费用负担患者监测预警，按规定及时落实医疗保障和救助政策。加快推动防止返贫监测与低收入人口动态监测信息平台互联互通，加强跨部门信息整合共享。研究推动防止返贫帮扶政策和农村低收入人口常态化帮扶政策衔接并轨。\n（九）持续加强产业和就业帮扶。强化帮扶产业分类指导，巩固一批、升级一批、盘活一批、调整一批，推动产业提质增效、可持续发展。中央财政衔接推进乡村振兴补助资金用于产业发展的比例保持总体稳定，强化资金项目绩效管理。加强帮扶项目资产管理，符合条件的纳入农村集体资产统一管理。提升消费帮扶助农增收行动实效。推进防止返贫就业攻坚行动，落实东西部劳务协作帮扶责任，统筹用好就业帮扶车间、公益岗位等渠道，稳定脱贫劳动力就业规模。\n（十）加大对重点地区帮扶支持力度。将脱贫县涉农资金统筹整合试点政策优化调整至160个国家乡村振兴重点帮扶县实施，加强整合资金使用监管。国有金融机构加大对国家乡村振兴重点帮扶县金融支持力度。持续开展医疗、教育干部人才“组团式”帮扶和科技特派团选派。高校毕业生“三支一扶”计划向脱贫地区倾斜。支持易地扶贫搬迁安置区可持续发展。易地搬迁至城镇后因人口增长出现住房困难的家庭，符合条件的统筹纳入城镇住房保障范围。推动建立欠发达地区常态化帮扶机制。","level":1},{"name":"三、提升乡村产业发展水平","text":"（十一）促进农村一二三产业融合发展。坚持产业兴农、质量兴农、绿色兴农，加快构建粮经饲统筹、农林牧渔并举、产加销贯通、农文旅融合的现代乡村产业体系，把农业建成现代化大产业。鼓励各地因地制宜大力发展特色产业，支持打造乡土特色品牌。实施乡村文旅深度融合工程，推进乡村旅游集聚区（村）建设，培育生态旅游、森林康养、休闲露营等新业态，推进乡村民宿规范发展、提升品质。优化实施农村产业融合发展项目，培育农业产业化联合体。\n（十二）推动农产品加工业优化升级。推进农产品生产和初加工、精深加工协同发展，促进就近就地转化增值。推进农产品加工设施改造提升，支持区域性预冷烘干、储藏保鲜、鲜切包装等初加工设施建设，发展智能化、清洁化精深加工。支持东北地区发展大豆等农产品全产业链加工，打造食品和饲料产业集群。支持粮食和重要农产品主产区建设加工产业园。\n（十三）推动农村流通高质量发展。深入推进县域商业体系建设，健全县乡村物流配送体系，促进农村客货邮融合发展，大力发展共同配送。推进农产品批发市场转型升级。优化农产品冷链物流体系建设，加快建设骨干冷链物流基地，布局建设县域产地公共冷链物流设施。实施农村电商高质量发展工程，推进县域电商直播基地建设，发展乡村土特产网络销售。加强农村流通领域市场监管，持续整治农村假冒伪劣产品。\n（十四）强化农民增收举措。实施农民增收促进行动，持续壮大乡村富民产业，支持农户发展特色种养、手工作坊、林下经济等家庭经营项目。强化产业发展联农带农，健全新型农业经营主体和涉农企业扶持政策与带动农户增收挂钩机制。促进农村劳动力多渠道就业，健全跨区域信息共享和有组织劳务输出机制，培育壮大劳务品牌。开展农民工服务保障专项行动，加强农民工就业动态监测。加强拖欠农民工工资源头预防和风险预警，完善根治欠薪长效机制。加强农民工职业技能培训，推广订单、定向、定岗培训模式。做好大龄农民工就业扶持。在重点工程项目和农业农村基础设施建设领域积极推广以工代赈，继续扩大劳务报酬规模。鼓励以出租、合作开发、入股经营等方式盘活利用农村资源资产，增加农民财产性收入。","level":1},{"name":"四、提升乡村建设水平","text":"（十五）增强乡村规划引领效能。适应乡村人口变化趋势，优化村庄布局、产业结构、公共服务配置。强化县域国土空间规划对城镇、村庄、产业园区等空间布局的统筹。分类编制村庄规划，可单独编制，也可以乡镇或若干村庄为单元编制，不需要编制的可在县乡级国土空间规划中明确通则式管理规定。加强村庄规划编制实效性、可操作性和执行约束力，强化乡村空间设计和风貌管控。在耕地总量不减少、永久基本农田布局基本稳定的前提下，综合运用增减挂钩和占补平衡政策，稳妥有序开展以乡镇为基本单元的全域土地综合整治，整合盘活农村零散闲置土地，保障乡村基础设施和产业发展用地。\n（十六）深入实施农村人居环境整治提升行动。因地制宜推进生活污水垃圾治理和农村改厕，完善农民参与和长效管护机制。健全农村生活垃圾分类收运处置体系，完善农村再生资源回收利用网络。分类梯次推进生活污水治理，加强农村黑臭水体动态排查和源头治理。稳步推进中西部地区户厕改造，探索农户自愿按标准改厕、政府验收合格后补助到户的奖补模式。协同推进农村有机生活垃圾、粪污、农业生产有机废弃物资源化处理利用。\n（十七）推进农村基础设施补短板。从各地实际和农民需求出发，抓住普及普惠的事，干一件、成一件。完善农村供水工程体系，有条件的推进城乡供水一体化、集中供水规模化，暂不具备条件的加强小型供水工程规范化建设改造，加强专业化管护，深入实施农村供水水质提升专项行动。推进农村电网巩固提升工程。推动农村分布式新能源发展，加强重点村镇新能源汽车充换电设施规划建设。扎实推进“四好农村路”建设，完善交通管理和安全防护设施，加快实施农村公路桥梁安全“消危”行动。继续实施农村危房改造和农房抗震改造，巩固农村房屋安全隐患排查整治成果。持续实施数字乡村发展行动，发展智慧农业，缩小城乡“数字鸿沟”。实施智慧广电乡村工程。鼓励有条件的省份统筹建设区域性大数据平台，加强农业生产经营、农村社会管理等涉农信息协同共享。\n（十八）完善农村公共服务体系。优化公共教育服务供给，加强寄宿制学校建设，办好必要的乡村小规模学校。实施县域普通高中发展提升行动计划。加强乡镇卫生院和村卫生室服务能力建设，稳步提高乡村医生中具备执业（助理）医师资格的人员比例。持续提升农村传染病防控和应急处置能力。逐步提高县域内医保基金在乡村医疗卫生机构使用的比例，加快将村卫生室纳入医保定点管理。健全农村养老服务体系，因地制宜推进区域性养老服务中心建设，鼓励发展农村老年助餐和互助服务。健全城乡居民基本养老保险“多缴多得、长缴多得”激励机制。加强农村生育支持和婴幼儿照护服务，做好流动儿童、留守儿童、妇女、老年人、残疾人等关心关爱服务。实施产粮大县公共服务能力提升行动。\n（十九）加强农村生态文明建设。持续打好农业农村污染治理攻坚战，一体化推进乡村生态保护修复。扎实推进化肥农药减量增效，推广种养循环模式。整县推进农业面源污染综合防治。加强耕地土壤重金属污染源排查整治。加强食用农产品产地质量安全控制和产品检测，提升“从农田到餐桌”全过程食品安全监管能力。推进兽用抗菌药使用减量化行动。强化重大动物疫病和重点人畜共患病防控。持续巩固长江十年禁渔成效。加快推进长江中上游坡耕地水土流失治理，扎实推进黄河流域深度节水控水。推进水系连通、水源涵养、水土保持，复苏河湖生态环境，强化地下水超采治理。加强荒漠化综合防治，探索“草光互补”模式。全力打好“三北”工程攻坚战，鼓励通过多种方式组织农民群众参与项目建设。优化草原生态保护补奖政策，健全对超载过牧的约束机制。加强森林草原防灭火。实施古树名木抢救保护行动。\n（二十）促进县域城乡融合发展。统筹新型城镇化和乡村全面振兴，提升县城综合承载能力和治理能力，促进县乡村功能衔接互补、资源要素优化配置。优化县域产业结构和空间布局，构建以县城为枢纽、以小城镇为节点的县域经济体系，扩大县域就业容量。统筹县域城乡基础设施规划建设管护，推进城乡学校共同体、紧密型县域医共体建设。实施新一轮农业转移人口市民化行动，鼓励有条件的县（市、区）将城镇常住人口全部纳入住房保障政策范围。","level":1},{"name":"五、提升乡村治理水平","text":"（二十一）推进抓党建促乡村振兴。坚持大抓基层鲜明导向，强化县级党委抓乡促村责任，健全县乡村三级联动争创先进、整顿后进机制。全面提升乡镇领导班子抓乡村振兴能力，开展乡镇党政正职全覆盖培训和农村党员进党校集中轮训。建好建强农村基层党组织，健全村党组织领导的村级组织体系，推行村级议事协商目录制度。加强村干部队伍建设，健全选育管用机制，实施村党组织带头人后备力量培育储备三年行动。优化驻村第一书记和工作队选派管理。进一步整合基层监督执纪力量，推动完善基层监督体系，持续深化乡村振兴领域不正之风和腐败问题专项整治。加强乡镇对县直部门派驻机构及人员的管理职责，加大编制资源向乡镇倾斜力度，县以上机关一般不得从乡镇借调工作人员，推广“街乡吹哨、部门报到”等做法，严格实行上级部门涉基层事务准入制度，健全基层职责清单和事务清单，推动解决“小马拉大车”等基层治理问题。\n（二十二）繁荣发展乡村文化。推动农耕文明和现代文明要素有机结合，书写中华民族现代文明的乡村篇。改进创新农村精神文明建设，推动新时代文明实践向村庄、集市等末梢延伸，促进城市优质文化资源下沉，增加有效服务供给。深入开展听党话、感党恩、跟党走宣传教育活动。加强乡村优秀传统文化保护传承和创新发展。强化农业文化遗产、农村非物质文化遗产挖掘整理和保护利用，实施乡村文物保护工程。开展传统村落集中连片保护利用示范。坚持农民唱主角，促进“村BA”、村超、村晚等群众性文体活动健康发展。\n（二十三）持续推进农村移风易俗。坚持疏堵结合、标本兼治，创新移风易俗抓手载体，发挥村民自治作用，强化村规民约激励约束功能，持续推进高额彩礼、大操大办、散埋乱葬等突出问题综合治理。鼓励各地利用乡村综合性服务场所，为农民婚丧嫁娶等提供普惠性社会服务，降低农村人情负担。完善婚事新办、丧事简办、孝老爱亲等约束性规范和倡导性标准。推动党员干部带头承诺践诺，发挥示范带动作用。强化正向引导激励，加强家庭家教家风建设，推广清单制、积分制等有效办法。\n（二十四）建设平安乡村。坚持和发展新时代“枫桥经验”，完善矛盾纠纷源头预防、排查预警、多元化解机制。健全农村扫黑除恶常态化机制，持续防范和整治“村霸”，依法打击农村宗族黑恶势力及其“保护伞”。持续开展打击整治农村赌博违法犯罪专项行动，加强电信网络诈骗宣传防范。开展农村道路交通、燃气、消防、渔船等重点领域安全隐患治理攻坚。加强农村防灾减灾工程、应急管理信息化和公共消防设施建设，提升防灾避险和自救互救能力。加强法治乡村建设，增强农民法律意识。","level":1},{"name":"六、加强党对“三农”工作的全面领导","text":"（二十五）健全党领导农村工作体制机制。坚持把解决好“三农”问题作为全党工作重中之重，坚持农业农村优先发展，改革完善“三农”工作体制机制，全面落实乡村振兴责任制，压实五级书记抓乡村振兴责任，明确主攻方向，扎实组织推动。加强党委农村工作体系建设，强化统筹推进乡村振兴职责。巩固拓展学习贯彻习近平新时代中国特色社会主义思想主题教育成果。各级党政领导干部要落实“四下基层”制度，深入调查研究，推动解决农民群众反映强烈的问题。优化各类涉农督查检查考核，突出实绩实效，能整合的整合，能简化的简化，减轻基层迎检迎考负担。按规定开展乡村振兴表彰激励。讲好新时代乡村振兴故事。\n（二十六）强化农村改革创新。在坚守底线前提下，鼓励各地实践探索和制度创新，强化改革举措集成增效，激发乡村振兴动力活力。启动实施第二轮土地承包到期后再延长30年整省试点。健全土地流转价格形成机制，探索防止流转费用不合理上涨有效办法。稳慎推进农村宅基地制度改革。深化农村集体产权制度改革，促进新型农村集体经济健康发展，严格控制农村集体经营风险。对集体资产由村民委员会、村民小组登记到农村集体经济组织名下实行税收减免。持续深化集体林权制度改革、农业水价综合改革、农垦改革和供销合作社综合改革。\n（二十七）完善乡村振兴多元化投入机制。坚持将农业农村作为一般公共预算优先保障领域，创新乡村振兴投融资机制，确保投入与乡村振兴目标任务相适应。落实土地出让收入支农政策。规范用好地方政府专项债券等政策工具，支持乡村振兴重大工程项目建设。强化对信贷业务以县域为主的金融机构货币政策精准支持，完善大中型银行“三农”金融服务专业化工作机制，强化农村中小金融机构支农支小定位。分省分类推进农村信用社改革化险。创新支持粮食安全、种业振兴等重点领域信贷服务模式。发展农村数字普惠金融，推进农村信用体系建设。发挥全国农业信贷担保体系和政府投资基金等作用。强化财政金融协同联动，在不新增地方政府隐性债务的前提下，开展高标准农田和设施农业建设等涉农领域贷款贴息奖补试点。鼓励社会资本投资农业农村，有效防范和纠正投资经营中的不当行为。加强涉农资金项目监管，严厉查处套取、骗取资金等违法违规行为。\n（二十八）壮大乡村人才队伍。实施乡村振兴人才支持计划，加大乡村本土人才培养，有序引导城市各类专业技术人才下乡服务，全面提高农民综合素质。强化农业科技人才和农村高技能人才培养使用，完善评价激励机制和保障措施。加强高等教育新农科建设，加快培养农林水利类紧缺专业人才。发挥普通高校、职业院校、农业广播电视学校等作用，提高农民教育培训实效。推广医疗卫生人员“县管乡用、乡聘村用”，实施教师“县管校聘”改革。推广科技小院模式，鼓励科研院所、高校专家服务农业农村。\n让我们紧密团结在以习近平同志为核心的党中央周围，坚定信心、铆足干劲、苦干实干，推进乡村全面振兴不断取得新成效，向建设农业强国目标扎实迈进。\n延伸阅读\n2024年中央一号文件发布！要点速览\n推进乡村全面振兴不断取得新成效——中央农办负责人解读2024年中央一号文件\n中央一号文件提出一批有含金量的政策措施 推进乡村全面振兴不断取得新成效\n有力有效推进乡村全面振兴\n办一批农民可感可及的实事！中央一号文件“画重点”\n2024年中央一号文件：推进乡村全面振兴这么干\n《焦点访谈》推进乡村全面振兴取得新成效\n【抓党建促乡村振兴】","level":1}]},{"id":"r0512","sections":[{"name":"中共中央 国务院印发《成渝地区双城经济圈建设规划纲要》","text":"近日，中共中央、国务院印发了《成渝地区双城经济圈建设规划纲要》，并发出通知，要求各地区各部门结合实际认真贯彻落实。\n《成渝地区双城经济圈建设规划纲要》主要内容如下。\n党中央、国务院高度重视成渝地区发展。2020年1月3日，习近平总书记主持召开中央财经委员会第六次会议，作出推动成渝地区双城经济圈建设、打造高质量发展重要增长极的重大决策部署，为未来一段时期成渝地区发展提供了根本遵循和重要指引。\n成渝地区双城经济圈位于“一带一路”和长江经济带交汇处，是西部陆海新通道的起点，具有连接西南西北，沟通东亚与东南亚、南亚的独特优势。区域内生态禀赋优良、能源矿产丰富、城镇密布、风物多样，是我国西部人口最密集、产业基础最雄厚、创新能力最强、市场空间最广阔、开放程度最高的区域，在国家发展大局中具有独特而重要的战略地位。为加强顶层设计和统筹协调，加快推动成渝地区形成有实力、有特色的双城经济圈，编制本规划纲要。\n规划范围包括重庆市的中心城区及万州、涪陵、綦江、大足、黔江、长寿、江津、合川、永川、南川、璧山、铜梁、潼南、荣昌、梁平、丰都、垫江、忠县等27个区（县）以及开州、云阳的部分地区，四川省的成都、自贡、泸州、德阳、绵阳（除平武县、北川县）、遂宁、内江、乐山、南充、眉山、宜宾、广安、达州（除万源市）、雅安（除天全县、宝兴县）、资阳等15个市，总面积18.5万平方公里，2019年常住人口9600万人，地区生产总值近6.3万亿元，分别占全国的1.9%、6.9%、6.3%。\n本规划纲要是指导当前和今后一个时期成渝地区双城经济圈建设的纲领性文件，是制定相关规划和政策的依据。规划期至2025年，展望到2035年。\n第一章 规划背景\n“十三五”以来，成渝地区发展驶入快车道。中心城市辐射带动作用持续提升，中小城市加快发展，基础设施更加完备，产业体系日渐完善，科技实力显著增强，内需空间不断拓展，对外交往功能进一步强化。到2019年，地区生产总值年均增长8%以上，社会消费品零售总额年均增长10%以上，常住人口城镇化率超过60%，铁路密度达3.5公里/百平方公里，机场群旅客吞吐量超过1亿人次，常住人口规模、地区经济总量占全国比重持续上升，呈现出重庆和成都双核相向发展、联动引领区域高质量发展的良好态势，已经成为西部地区经济社会发展、生态文明建设、改革创新和对外开放的重要引擎。与此同时，成渝地区综合实力和竞争力仍与东部发达地区存在较大差距，特别是基础设施瓶颈依然明显，城镇规模结构不尽合理，产业链分工协同程度不高，科技创新支撑能力偏弱，城乡发展差距仍然较大，生态环境保护任务艰巨，民生保障还存在不少短板。\n当今世界正经历百年未有之大变局，新一轮科技革命和产业变革深入发展，国际分工体系面临系统性调整。我国已转向高质量发展阶段，共建“一带一路”、长江经济带发展、西部大开发等重大战略深入实施，供给侧结构性改革稳步推进，扩大内需战略深入实施，为成渝地区新一轮发展赋予了全新优势、创造了重大机遇。在这样的背景下，推动成渝地区双城经济圈建设，符合我国经济高质量发展的客观要求，是新形势下促进区域协调发展，形成优势互补、高质量发展区域经济布局的重大战略支撑，也是构建以国内大循环为主体、国内国际双循环相互促进新发展格局的一项重大举措，有利于在西部形成高质量发展的重要增长极，增强人口和经济承载力；有助于打造内陆开放战略高地和参与国际竞争的新基地，助推形成陆海内外联动、东西双向互济的对外开放新格局；有利于吸收生态功能区人口向城市群集中，使西部形成优势区域重点发展、生态功能区重点保护的新格局，保护长江上游和西部地区生态环境，增强空间治理和保护能力。\n第二章 总体要求\n加强顶层设计和统筹协调，牢固树立一体化发展理念，唱好“双城记”，共建经济圈，合力打造区域协作的高水平样板，在推进新时代西部大开发中发挥支撑作用，在共建“一带一路”中发挥带动作用，在推进长江经济带绿色发展中发挥示范作用。\n第一节 指导思想\n以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，坚持党中央集中统一领导，坚定不移贯彻新发展理念，坚持稳中求进工作总基调，以推动高质量发展为主题，以深化供给侧结构性改革为主线，立足构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，围绕推动形成优势互补、高质量发展的区域经济布局，强化重庆和成都中心城市带动作用，引领带动成渝地区统筹协同发展，促进产业、人口及各类生产要素合理流动和高效集聚，加快形成改革开放新动力，加快塑造创新发展新优势，加快构建与沿海地区协作互动新局面，加快拓展参与国际合作新空间，推动成渝地区形成有实力、有特色的双城经济圈，打造带动全国高质量发展的重要增长极和新的动力源。\n第二节 主要原则\n——双核引领，区域联动。提升重庆、成都中心城市综合能级和国际竞争力，处理好中心和区域的关系，强化协同辐射带动作用，以大带小、加快培育中小城市，以点带面、推动区域均衡发展，以城带乡、有效促进乡村振兴，形成特色鲜明、布局合理、集约高效的城市群发展格局。\n——改革开放，创新驱动。充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，强化改革的先导和突破作用，积极推动更高层次开放。强化体制创新，面向国内外集聚创新资源，推动科技创新应用与产业转型升级深度融合，构建协同创新体系。\n——生态优先，绿色发展。全面践行生态文明理念，强化长江上游生态大保护，严守生态保护红线、永久基本农田、城镇开发边界三条控制线，优化国土空间开发格局，提高用地、用水、用能效率，构建绿色低碳的生产生活方式和建设运营模式，实现可持续发展。\n——共享包容，改善民生。坚持以人民为中心的发展思想，增加优质公共产品和服务供给，持续改善民生福祉，构建多元包容的社会治理格局，让改革发展成果更多更公平惠及人民，提高人民群众获得感、幸福感、安全感。\n——统筹协同，合作共建。坚持“川渝一盘棋”思维，发挥优势、错位发展，优化整合区域资源，加强交通、产业、科技、环保、民生政策协同对接，做到统一谋划、一体部署、相互协作、共同实施，辐射带动周边地区发展，显著提升区域整体竞争力。\n第三节 战略定位\n尊重客观规律，发挥比较优势，把成渝地区双城经济圈建设成为具有全国影响力的重要经济中心、科技创新中心、改革开放新高地、高品质生活宜居地。\n具有全国影响力的重要经济中心。依托综合交通枢纽和立体开放通道，提高参与全球资源配置能力和整体经济效率，培育竞争优势突出的现代产业体系，发展富有巴蜀特色的多元消费业态，打造西部金融中心、国际消费目的地，共建全国重要的先进制造业基地和现代服务业高地。\n具有全国影响力的科技创新中心。紧抓新一轮科技革命机遇，发挥科教人才和特色产业优势，推动创新环境优化，加强创新开放合作，促进创新资源集成，激发各类创新主体活力，大力推进科技和经济发展深度融合，打造全国重要的科技创新和协同创新示范区。\n改革开放新高地。积极推进要素市场化配置、科研体制、跨行政区经济社会管理等重点领域改革。依托南向、西向、东向大通道，扩大全方位高水平开放，形成“一带一路”、长江经济带、西部陆海新通道联动发展的战略性枢纽，成为区域合作和对外开放典范。\n高品质生活宜居地。大力推进生态文明建设，筑牢长江上游生态屏障，在西部地区生态保护中发挥示范作用，促进社会事业共建共享，大幅改善城乡人居环境，打造世界级休闲旅游胜地和城乡融合发展样板区，建设包容和谐、美丽宜居、充满魅力的高品质城市群。\n第四节 发展目标\n到2025年，成渝地区双城经济圈经济实力、发展活力、国际影响力大幅提升，一体化发展水平明显提高，区域特色进一步彰显，支撑全国高质量发展的作用显著增强。\n——双城引领的空间格局初步形成。重庆、成都作为国家中心城市的发展能级显著提升，区域带动力和国际竞争力明显增强。都市圈同城化取得显著突破，中小城市和县城发展提速，大中小城市和小城镇优势互补、分工合理、良性互动、协调发展的城镇格局初步形成，常住人口城镇化率达到66%左右。\n——基础设施联通水平大幅提升。现代化多层次轨道交通网络初步建成，出渝出川四向通道基本形成，重庆、成都间1小时可达，铁路网总规模达到9000公里以上、覆盖全部20万以上人口城市，航空枢纽地位更加凸显，长江上游航运中心和物流中心基本建成，5G网络实现城镇和重点场景全覆盖，新型基础设施水平明显提高，能源保障能力进一步增强。\n——现代经济体系初步形成。区域协同创新体系基本建成，研发投入强度达到2.5%左右，科技进步贡献率达到63%，科技创新中心核心功能基本形成。优势产业区域内分工更加合理、协作效率大幅提升，初步形成相对完整的区域产业链供应链体系，呈现世界级先进制造业集群雏形，数字经济蓬勃发展，西部金融中心初步建成，现代服务业优势明显增强。\n——改革开放成果更加丰硕。制度性交易成本明显降低，跨行政区利益共享和成本共担机制不断创新完善，阻碍生产要素自由流动的行政壁垒和体制机制障碍基本消除，营商环境达到国内一流水平，统一开放的市场体系基本建立。重庆、四川自由贸易试验区等重大开放平台建设取得突破，协同开放水平显著提高，内陆开放战略高地基本建成，对共建“一带一路”支撑作用显著提升。\n——生态宜居水平大幅提高。生态安全格局基本形成，环境突出问题得到有效治理，生态环境协同监管和区域生态保护补偿机制更加完善，地级及以上城市空气质量优良天数比率达到88%，跨界河流断面水质达标率达到95%，河流主要断面生态流量满足程度达到90%以上，城市开发模式更加集约高效，公共服务便利共享水平明显提高，精细化治理能力显著增强。\n到2035年，建成实力雄厚、特色鲜明的双城经济圈，重庆、成都进入现代化国际都市行列，大中小城市协同发展的城镇体系更加完善，基础设施互联互通基本实现，具有全国影响力的科技创新中心基本建成，世界级先进制造业集群优势全面形成，现代产业体系趋于成熟，融入全球的开放型经济体系基本建成，人民生活品质大幅提升，对全国高质量发展的支撑带动能力显著增强，成为具有国际影响力的活跃增长极和强劲动力源。\n第三章 构建双城经济圈发展新格局\n以发挥优势、彰显特色、协同发展为导向，突出双城引领，强化双圈互动，促进两翼协同，统筹大中小城市和小城镇发展，促进形成疏密有致、集约高效的空间格局。\n第一节 提升双城发展能级\n面向新发展阶段、着眼现代化，优化重庆主城和成都功能布局，全面提升发展能级和综合竞争力，引领带动双城经济圈发展。\n重庆。以建成高质量发展高品质生活新范例为统领，在全面深化改革和扩大开放中先行先试，建设国际化、绿色化、智能化、人文化现代城市，打造国家重要先进制造业中心、西部金融中心、西部国际综合交通枢纽和国际门户枢纽，增强国家中心城市国际影响力和区域带动力。以长江、嘉陵江为主轴，沿三大平行槽谷组团式发展，高标准建设两江新区、西部（重庆）科学城等，重塑“两江四岸”国际化山水都市风貌。\n成都。以建成践行新发展理念的公园城市示范区为统领，厚植高品质宜居优势，提升国际国内高端要素运筹能力，构建支撑高质量发展的现代产业体系、创新体系、城市治理体系，打造区域经济中心、科技中心、世界文化名城和国际门户枢纽，提升国家中心城市国际竞争力和区域辐射力。高水平建设天府新区、西部（成都）科学城等，形成“一山连两翼”城市发展新格局。\n第二节 培育发展现代化都市圈\n把握要素流动和产业分工规律，围绕重庆主城和成都培育现代化都市圈，带动中心城市周边市地和区县加快发展。\n重庆都市圈。梯次推动重庆中心城区与渝西地区融合发展。畅通璧山、江津、长寿、南川联系中心城区通道，率先实现同城化。强化涪陵对渝东北、渝东南带动功能，支持永川建设现代制造业基地和西部职教基地，支持合川加快发展网络安全产业、推动建成区域性公共服务中心，推进綦江、万盛一体建设西部陆海新通道渝黔综合服务区和渝黔合作先行示范区，打造重庆中心城区辐射带动周边的战略支点。推进重庆向西发展，提升荣昌、铜梁、大足、潼南特色化功能，建设与成都相向发展的桥头堡。推动广安全面融入重庆都市圈，打造川渝合作示范区。\n成都都市圈。充分发挥成都带动作用和德阳、眉山、资阳比较优势，加快生产力一体化布局，促进基础设施同网、公共服务资源共享、政务事项通办、开放门户共建，创建成德眉资同城化综合试验区，建设经济发达、生态优良、生活幸福的现代化都市圈。推动成都、德阳共建重大装备制造基地，打造成德临港经济产业带。加快天府新区成都片区和眉山片区融合发展，打造成眉高新技术产业带。促进成都空港新城与资阳临空经济区协同发展，打造成资临空经济产业带。推动成都东进，以促进制造业高质量发展为重点将成都东部建成与重庆联动的重要支点。\n第三节 促进双圈互动两翼协同\n依托资源禀赋、人员往来、产业联系等方面优势，强化区域中心城市互动和毗邻地区协同，优化成渝地区双城经济圈协同发展格局。\n推动重庆、成都都市圈相向发展。依托成渝北线、中线和南线综合运输通道，夯实成渝主轴发展基础，强化重庆都市圈和成都都市圈互动。支持遂宁与潼南、资阳与大足等探索一体规划、成本共担、利益共享的建设模式。强化都市圈辐射作用，带动成都平原一体化发展，把绵阳、乐山打造为成都平原区域中心城市，支持雅安建设绿色发展示范市，支持黔江建设渝东南区域中心城市。\n推动渝东北、川东北地区一体化发展。支持万州建设渝东北区域中心城市，支持南充、达州建设川东北区域中心城市，发挥垫江、梁平、丰都、忠县、云阳节点作用，带动双城经济圈北翼发展。支持万州、达州、开州共建川渝统筹发展示范区，加强规划、政策、项目统筹，在产业发展、公共服务、生态环保等领域探索建立符合高质量发展要求的利益共享机制。\n推动川南、渝西地区融合发展。支持宜宾、泸州建设川南区域中心城市，推动内江、自贡同城化，带动双城经济圈南翼跨越发展。支持自贡、泸州、内江、宜宾、江津、永川、荣昌等共建川南渝西融合发展试验区，探索建立重大政策协同、重点领域协作、市场主体联动机制，协同建设承接产业转移创新发展示范区，打造西部陆海新通道和长江经济带物流枢纽。\n辐射带动川渝两省市全域发展。强化双城经济圈对重庆市、四川省其他地区特色产业发展、基础设施建设的引领带动，促进基本公共服务均等化，引导秦巴山区、武陵山区、乌蒙山区、涉藏州县、大小凉山等周边欠发达地区人口向双城经济圈集中，强化生态环境保护，切实巩固提升脱贫成果，促进城乡区域协调发展。\n第四节 分类推进大中小城市和县城发展\n分类指导、科学施策，推动公共资源在双城经济圈各级各类城市间合理配置，优化城市规模结构和功能布局。\n推动超大特大城市中心城区瘦身健体。统筹兼顾经济、生态、安全、健康等多元需求，推动重庆和成都中心城区功能升级，合理控制规模，优化开发格局，推动城市发展由外延扩张式向内涵提升式转变，防止城市“摊大饼”，积极破解“大城市病”，合理控制开发强度和人口密度。集聚创新要素，增强高端服务功能，率先形成以现代服务业为主体、先进制造业为支撑的产业结构。建设产城融合、职住平衡、生态宜居、交通便利的郊区新城，实现多中心、串联式、组团化发展。\n加快提升大中城市产业水平和功能品质。主动承接超大特大城市产业转移和功能疏解，夯实实体经济发展基础。立足特色资源和产业基础，推动制造业差异化、规模化、集群化发展，因地制宜打造先进制造业基地、商贸物流中心和区域专业服务中心。优化大中城市管辖范围和市辖区规模结构。支持三级医院和新建高校、高校新建校区在大中城市布局，增加医疗、文化、体育资源供给。优化市政设施功能，改善人居环境，营造现代时尚的消费场景，提升城市生活品质。\n推进县城城镇化补短板强弱项。加快县城城镇化建设，推动农业转移人口就地就近城镇化。推动重庆市郊区和四川省县城及县级市城区公共服务设施、环境卫生基础设施、市政公用设施、县域经济培育设施提级扩能，推动公共资源适当向县城（郊区、县级市城区）倾斜，补齐短板、补强弱项，提升县域经济发展能力。引导产业项目向资源环境承载力强、发展潜力大的县城（郊区、县级市城区）布局，培育壮大特色优势产业。推动具备条件的县有序改市。\n分类引导小城镇发展。切实放权赋能，支持位于都市圈范围内的重点镇加强与周边城市的规划统筹、功能配套，分担城市功能。通过规划引导、市场运作，将具有特色资源、区位优势的小城镇培育成为专业特色镇。引导一般小城镇完善基础设施和公共服务，增强服务农村、带动周边功能。\n第四章 合力建设现代基础设施网络\n以提升内联外通水平为导向，强化门户枢纽功能，加快完善传统和新型基础设施，构建互联互通、管理协同、安全高效的基础设施网络。\n第一节 构建一体化综合交通运输体系\n打造国际航空门户枢纽。高质量建成成都天府国际机场，打造国际航空枢纽，实施双流国际机场扩能改造，实现天府国际机场与双流国际机场“两场一体”运营。推进重庆江北国际机场改扩建，规划研究重庆新机场建设，提升重庆国际枢纽功能。布局建设乐山、阆中、遂宁、雅安等一批支线机场，研究广安机场建设。织密国际航线网络，提高与全球主要城市之间的通达性。推动两省市机场集团交叉持股，强化城市群机场协同运营，合力打造世界级机场群。优化空域结构，提升空域资源配置使用效率。深化低空空域管理改革，加快通用航空发展。\n共建轨道上的双城经济圈。科学规划干线铁路、城际铁路、都市圈市域（郊）铁路和城市轨道交通，完善多层次轨道交通网络体系。规划建设川藏铁路，适时推动引入成都枢纽的天府－朝阳湖铁路项目实施。加快建设成都至西宁、重庆至昆明、成都至自贡至宜宾、重庆至黔江、郑州至万州铁路襄阳至万州段等铁路项目，规划建设重庆至万州、成都至达州至万州、重庆至西安、重庆至宜昌、成渝中线等铁路项目，规划研究重庆至贵阳铁路，研究论证重庆至自贡至雅安铁路，拓展出渝出川客运大通道。推进叙永至毕节等铁路及铁路专用线等货运设施建设，逐步恢复沪汉蓉铁路货运功能，完善货运通道布局。研究规划重庆都市圈环线、成都外环、绵遂内等连接重庆中心城区、成都与周边城市的城际铁路和都市圈市域（郊）铁路，优先利用铁路资源开行城际、市域（郊）列车，基本建成中心城市间、中心城市与周边城市（镇）间1小时交通圈和通勤圈。有序推进重庆、成都城市轨道交通规划建设。\n完善双城经济圈公路体系。畅通对外高速公路通道，强化主要城市间快速联通，加快推进省际待贯通路段建设。提高既有路网通行能力，全面推动G318川藏公路升级改造，加快成渝、渝遂、渝泸、渝邻和成自泸赤等国家高速公路繁忙路段扩能改造，加强干线公路与城市道路有效衔接。优化城际快速路网，疏通主要节点城市进出通道，增强公路对客货运枢纽的集疏运服务能力，提升路网通达效率和安全水平。推动毗邻地区互联互通，建设重庆至合江至叙永、泸州至永川、大足至内江、铜梁至安岳、南充至潼南、大竹至垫江、开江至梁平等高速公路。\n推动长江上游航运枢纽建设。健全以长江干线为主通道、重要支流为骨架的航道网络，优化干支流水库群联合调度，研究优化长江上游分段通航标准，加快长江上游航道整治和梯级渠化，全面畅通岷江、嘉陵江、乌江、渠江等。推进利泽、白马、犍为、龙溪口、风洞子等航电枢纽建设。加强港口分工协作，构建结构合理、功能完善的港口群，打造要素集聚、功能完善的港航服务体系。组建长江上游港口联盟，加强与上海国际航运中心合作，推进港口企业加强合资合作，促进区域港口码头管理运营一体化。\n提升客货运输服务水平。推动多层次轨道交通网络运营管理衔接融合，研究建立一体化建设运营机制，推广交通“一卡通”服务和二维码“一码畅行”，加快实现运营公交化。加强机场与轨道交通衔接，完善机场集疏运体系，探索空铁联程联运新技术新模式。推进一体化综合客运枢纽和衔接高效的综合货运枢纽建设，提升枢纽运营智能化水平。推进铁路专用线进重要枢纽型港区、大型工矿企业和物流园区，加快发展铁水、公铁联运和“一单制”联运服务。支持高铁快运、电商快递班列、多式联运班列发展。\n第二节 强化能源保障\n优化区域电力供给。稳步推进金沙江、雅砻江、大渡河水电基地开发，优先建设具有调节能力的水库电站。统筹推进风光水多能互补能源基地建设，积极推广分布式能源发展，研究开展氢能运营试点示范，建设优质清洁能源基地。优化川渝电力资源配置，完善川渝电网主网架结构，优化重庆都市圈500千伏目标网架。研究论证疆电入渝工程。推进白鹤滩水电站留存部分电量在川渝电网消纳。培育发展电力现货市场和川渝一体化电力辅助服务市场。\n统筹油气资源开发。发挥长宁－威远、涪陵国家级页岩气示范区引领作用，推动页岩气滚动开发，建设天然气千亿立方米产能基地，打造中国“气大庆”。完善天然气管网布局。优化完善成品油储运设施，有序开展中航油西南战略储运基地、陕西入川渝成品油管道、沿江成品油管道等前期工作。发挥重庆石油天然气交易中心作用，形成具有影响力的价格基准。完善页岩气开发利益共享机制，有序放开油气勘探开发市场，加大安岳等地天然气勘探开发力度。\n第三节 加强水利基础设施建设\n研究推进跨区域重大蓄水、提水、调水工程建设，增强跨区域水资源调配能力，推动形成多源互补、引排得当的水网体系。推动大型水库及引水供水重点工程建设。有序推进引大济岷、涪江右岸、向家坝灌区二期、长征渠、渝南及重庆中部水资源配置、沱江团结等引水供水重大工程的研究论证。加强大中型灌区续建配套和现代化改造。加强饮用水水源地和备用水源建设，推进人口分散区域重点小型标准化供水设施建设，保障区域供水安全。推进防洪减灾设施建设，加强主要江河和中小河流防洪治理，实施防洪控制性水库联合调度。系统推进城市堤防、排水管渠、排涝除险、蓄水空间等设施建设，有效治理城市内涝问题。构建智慧水利平台，健全水资源监控体系，推进水利资源共享、调配、监管一体化。\n第五章 协同建设现代产业体系\n以全球新一轮科技革命和产业链重塑为契机，坚持市场主导、政府引导，强化机制创新，优化、稳定、提升产业链供应链，加快构建高效分工、错位发展、有序竞争、相互融合的现代产业体系。\n第一节 推动制造业高质量发展\n优化重大生产力布局。整合提升优势产业，加快补齐关键短板，增强全产业链优势，形成特色鲜明、相对完整、安全可靠的区域产业链供应链体系。提升重庆、成都产业创新发展能力，打造制造业高质量发展双引擎，推动都市圈外围地区加快发展电子信息、汽车等产业，形成研发在中心、制造在周边、链式配套、梯度布局的都市圈产业分工体系。强化双城经济圈北翼地区先进材料、汽摩配件等产业协作，南翼地区联动集聚食品饮料、装备制造、能源化工、节能环保等产业。\n培育具有国际竞争力的先进制造业集群。以智能网联和新能源为主攻方向，共建高水平汽车产业研发生产制造基地。聚焦航空航天、轨道交通、能源装备、工业机器人、仪器仪表、数控机床、摩托车等领域，培育世界级装备制造产业集群。整合白酒主产区优质资源，壮大健康食品、精品服饰、特色轻工等产业，培育特色消费品产业集群。深入推进国家战略性新兴产业集群发展工程，前瞻布局一批先导产业，壮大先进材料产业，协同发展生物医药、医疗器械、现代中药产业，共建西部大健康产业基地。\n大力承接产业转移。发挥要素成本、市场和通道优势，以更大力度、更高标准承接东部地区和境外产业链整体转移、关联产业协同转移，补齐建强产业链。积极发挥产业转移项目库作用，建立跨区域承接产业转移协调机制，完善信息对接、权益分享、税收分成等政策体系。布局产业转移集中承接地，继续安排中央预算内投资支持国家级新区、承接产业转移示范区重点园区的基础设施和公共服务平台建设，不断提升承接产业能力。研究以市场化方式设立区域产业协同发展投资基金，支持先导型、牵引性重大产业项目落地。\n整合优化重大产业平台。发挥重庆两江新区、四川天府新区旗舰作用，加快重庆经济技术开发区、海峡两岸产业合作区、成都国际铁路港经济开发区及其他国家级、省级开发区建设，推动成都天府临空经济区建设。鼓励涪陵、綦江、合川、资阳、遂宁、宜宾等创建国家高新技术产业开发区，打造一批国家新型工业化产业示范基地，推动建设广安－渝北等一批跨省市毗邻地区产业合作园区。支持自贡等老工业城市转型升级，建设新时代深化改革扩大开放示范城市。创新“一区多园”、“飞地经济”等建园方式，推动各类开发区和产业集聚区政策叠加、服务体系共建。\n第二节 大力发展数字经济\n布局完善新一代信息基础设施。加快5G网络建设，推进千兆光纤接入网络广泛覆盖，加快推进基于IPv6的下一代互联网部署，推动国家级互联网骨干直联点宽带扩容。统筹布局大型云计算和边缘计算数据中心。完善工业互联网标识解析国家顶级节点功能，加快建设二级节点。积极发展物联网，建设全面覆盖、泛在互联的城市智能感知网络。开展新一代移动通信网络试验验证，实施车联网试点示范建设工程。加快提升传统基础设施智能化水平。\n合力打造数字产业新高地。聚焦集成电路、新型显示、智能终端等领域，打造“云联数算用”要素集群和“芯屏器核网”全产业链，培育超高清视频、人工智能、区块链、数字文创等创新应用，联手打造具有国际竞争力的电子信息产业集群。大力发展数字经济，推动数字产业化、产业数字化，促进软件、互联网、大数据等信息技术与实体经济深度融合，加快重点领域数字化发展，引领产业转型升级。围绕产业发展需要，推动共建成渝工业互联网一体化发展示范区、区域协同公共服务平台和服务体系，构建全国领先的“5G+工业互联网”生态。支持联合建设国家数字经济创新发展试验区和国家数字服务出口基地，建设“智造重镇”和“智慧名城”。\n积极拓展数字化应用。探索建立统一标准、开放互通的公共应用平台，推动双城经济圈政务数据资源共享共用，推动地级以上城市全面建立数字化管理平台。推进城市基础设施、建筑楼宇等的数字化管理，稳步推进“数字+”与城市运营管理各领域深度融合。完善大数据辅助科学决策机制，加快提高治理数字化水平。适应数字技术全面融入社会交往和日常生活新趋势，促进公共服务、社会运行和治理方式创新，构筑全民畅享的数字生活。\n全面提升数字安全水平。加强通信网络、重要信息系统和数据资源保护，增强关键信息基础设施安全防护能力。深化网络安全等级保护制度和关键信息基础设施安全保护制度。完善重庆和成都重要数据灾备中心功能，建设联合异地灾备数据基地。建设网络安全产业基地，支持开展法定数字货币研究及移动支付创新应用。\n第三节 培育发展现代服务业\n推动先进制造业和服务业融合发展。引导制造企业延伸服务链条、发展服务环节，推动生产服务型企业创新服务供给，提升制造业服务化水平和全产业链价值。在研发设计、科技服务、商务咨询、人力资源服务等领域，联合打造一批服务品牌。依托优势企业培育发展工业设计中心，支持食品药品检测基地、重庆工业设计产业城等建设。支持在成渝地区建设国家检验检测高技术服务业集聚区。支持川渝毗邻地区建立人力资源服务产业园。鼓励重庆、成都等开展先进制造业和现代服务业融合发展试点。\n提升商贸物流发展水平。强化重庆、成都国家物流枢纽功能，合力建设国际货运中心。支持万州、涪陵、长寿、遂宁、达州、泸州、自贡等打造区域性物流中心。支持全货运航空公司在成渝地区设立基地，加快完善多式联运国际物流服务网络，打造多元化、国际化、高水平物流产业体系，培育发展龙头企业。围绕优势产业和主导产品，差异化建设一批内外贸相结合的专业市场。扎实推进跨境电子商务综合试验区建设。大力发展数字商务，探索建立反向定制（C2M）产业基地。强化会展经济对商贸物流的带动作用，联合打造一批专业会展品牌。\n共建西部金融中心。支持重庆开展区域性股权市场制度和业务创新。支持开展共建“一带一路”金融服务。开展本外币合一账户试点。支持跨境人民币业务创新，探索开展跨国企业集团本外币合一跨境资金池等试点业务，支持在自由贸易试验区设立人民币海外投贷基金。支持开展合格境内投资企业（QDIE）和合格境内有限合伙人（QDLP）试点。积极支持区域金融改革创新，开展绿色金融、金融科技等创新试点，在成都建设基于区块链技术的知识产权融资服务平台。推进金融市场和监管区域一体化，推动在担保、不良资产处置、创业投资和私募股权投资等领域跨区域合作。支持设立市场化征信机构，研发适合西部地区的征信产品，支持中外信用评级机构在成渝地区设立实体机构，推动信用融资产品和服务创新。设立破产法庭，健全金融审判体系。\n第四节 建设现代高效特色农业带\n推动农业高质量发展。支持川渝平坝和浅丘地区建设国家优质粮油保障基地，打造国家重要的生猪生产基地、渝遂绵优质蔬菜生产带、优质道地中药材产业带、长江上游柑橘产业带和安岳、潼南柠檬产区。推进特色农产品精深加工，打造全球泡（榨）菜出口基地、川菜产业和竹产业基地。发展都市农业，高质量打造成渝都市现代高效特色农业示范区。\n强化农业科技支撑。共建国家农业高新技术产业示范区。支持建设西南特色作物种质资源库、西部农业人工智能技术创新中心、国家现代农业产业科技创新中心等。推动畜禽遗传资源保护利用，建设区域性畜禽基因库、畜牧科技城、国家级重庆（荣昌）生猪大数据中心。\n大力拓展农产品市场。积极开展有机产品认证，健全农产品质量安全追溯体系。做强地理标志农产品，推广巴味渝珍、天府龙芽等特色品牌，打造川菜渝味等区域公用品牌。强化农产品分拣、加工、包装、预冷等一体化集配设施建设，大力建设自贡等国家骨干冷链物流基地。大力发展农村电商，建设一批重点网货生产基地和产地直播基地。建设国际农产品加工产业园。\n第六章 共建具有全国影响力的科技创新中心\n坚定实施创新驱动发展战略，瞄准突破共性关键技术尤其是“卡脖子”技术，强化战略科技力量，深化新一轮全面创新改革试验，增强协同创新发展能力，增进与“一带一路”沿线国家等创新合作，合力打造科技创新高地，为构建现代产业体系提供科技支撑。\n第一节 建设成渝综合性科学中心\n聚焦核能、航空航天、智能制造和电子信息等领域的战略性产品开发，在四川天府新区、重庆高新区集中布局建设若干重大科技基础设施和一批科教基础设施，引导地方、科研机构和企业建设系列交叉研究平台和科技创新基地，打造学科内涵关联、空间分布集聚的原始创新集群。发挥基础研究和原始创新的引领作用，吸引高水平大学、科研机构和创新型企业入驻，强化开放共享，促进科技成果转化，有效支撑成渝全域高水平创新活动。\n第二节 优化创新空间布局\n统筹天府国际生物城、未来科技城和成都高新区等资源，建设西部（成都）科学城。瞄准新兴产业设立开放式、国际化高端研发机构，建设重庆两江协同创新区。依托重庆大学城、重庆高新区等，夯实智能产业、生物医学发展基础，建设西部（重庆）科学城。高水平建设中国（绵阳）科技城，鼓励大院大所发展孵化器、产业园。以“一城多园”模式合作共建西部科学城。推动中国科学院等在双城经济圈布局科研平台。\n第三节 提升协同创新能力\n强化创新链产业链协同。坚持企业主体、市场导向，健全产学研用深度融合的科技创新体系，建设产业创新高地。鼓励有条件的企业组建面向行业共性基础技术、前沿引领技术开发的研究院，支持创新型领军企业联合行业上下游组建创新联合体。支持高校、科研机构和企业共建联合实验室或新型研究机构，共同承担科技项目、共享科技成果。建设一批产业创新中心、技术创新中心、制造业创新中心、工程研究中心等创新平台和综合性检验检测平台。\n推动区域协同创新。实施成渝科技创新合作计划，联合开展技术攻关，参与实施高分卫星、载人航天、大型飞机、长江上游生态环境修复等国家重大科技任务，积极申报航空发动机、网络空间安全等科技创新重大项目。鼓励共用科技创新平台和大型科研仪器设备，共建创业孵化、科技金融、成果转化平台，打造成渝地区一体化技术交易市场。完善区域知识产权快速协同保护机制，支持设立知识产权法庭。鼓励区域内高校、科研院所、企业共同参与国际大科学计划和大科学工程。\n第四节 营造鼓励创新的政策环境\n大力吸引创新人才。实施有吸引力的人才政策，引进和培养高水平创新人才队伍，鼓励科技人才在区域内自主流动、择业创业。支持在人才评价、外籍人才引进等政策创新方面先行先试。鼓励成渝地区大学面向全球招生，引进优秀博士后和青年学者。支持引进国内外顶尖高校和科研机构在成渝地区合作建设研究院和研发中心，设立长期、灵活、有吸引力的科研岗位。\n深化科技创新体制改革。深入推进职务科技成果所有权或长期使用权改革试点，探索高校和科研院所职务科技成果国有资产管理新模式。深化政府部门和科研单位项目资金管理制度改革，允许科研资金跨省市使用。探索建立两省市改革举措和支持政策异地同享机制。\n健全创新激励政策体系。加大对引进高水平研发机构和先进科技成果的支持力度。综合运用财政、金融等政策手段激励企业加大研发投入力度，引导创业投资机构投资早中期、初创期科技型企业，依法运用技术、能耗、环保等方面的标准促进企业技术改造和新技术应用。支持通过股权与债权相结合等方式，为企业创新活动提供融资服务。支持符合条件的创新型企业上市融资。\n第七章 打造富有巴蜀特色的国际消费目的地\n以高质量供给引领和创造市场新需求，坚持高端化与大众化并重、快节奏与慢生活兼具，激发市场消费活力，不断增强巴蜀消费知名度、美誉度、影响力。\n第一节 营造高品质消费空间\n打造城市消费品牌。支持重庆、成都塑造城市特色消费品牌，打造国际消费中心城市。推动涪陵、合川、乐山、雅安、南充等发展人文休闲、度假康养，打造成渝“后花园”。发挥宜宾、泸州白酒品牌优势。推动万州、江津、铜梁、自贡、内江等围绕特色美食、传统工艺产品、民俗节庆、自然遗迹等，建设特色消费聚集区。改造提升商业街区，集聚高端消费资源，打造世界知名商圈。建设一批人文气息浓厚的特色商业名镇。\n共建巴蜀文化旅游走廊。充分挖掘文化旅游资源，以文促旅、以旅彰文，讲好巴蜀故事，打造国际范、中国味、巴蜀韵的世界级休闲旅游胜地。打造贯通四川、重庆的文化遗产探秘、自然生态体验、红色文化体验等一批精品旅游线路，扩大长江三峡、九寨沟、武隆喀斯特、都江堰－青城山、峨眉山－乐山大佛、三星堆－金沙、三国文化、大足石刻、自贡彩灯等国际旅游品牌影响力。规划建设长征国家文化公园（重庆段、四川段）。打造绵竹熊猫谷和玫瑰谷，探索川西林盘、巴渝村寨保护性开发，依托特色自然风光、民俗风情、农事活动等，发展巴蜀乡村旅游。推动黔江与周边区县文旅融合发展，建设文化产业和旅游产业融合发展示范区。\n第二节 构建多元融合的消费业态\n推动消费供给升级。促进经典川菜、重庆火锅、盖碗茶等餐饮产品品牌化，创建美食地标。推动传统文化和全新科技元素融入创意设计产业，提升传媒影视、动漫游戏、音乐演艺等产业发展水平，支持举办有国际影响力的时装周、电影节、艺术节等文化展演活动。发展水上运动、山地户外运动、汽车摩托车运动、航空运动等，布局建设自驾游营地和野外露营地，发展乡村民宿，推出温泉、游轮、徒步、自驾等一批特色化、品质化旅游产品，大力发展“旅游+”产品。提升健康、养老、托育、家政服务等市场化供给质量，壮大社会服务消费。\n发展消费新场景。引导网络直播、短视频等新消费形态健康发展，促进直播电商、社交电商等线上新模式新业态发展，推动教育、医疗等服务线上线下交互融合。鼓励发展智慧门店、自助终端、智能机器人等“无接触”零售。发展更多参与式、体验式消费模式和业态。发展假日经济，丰富夜市、夜展、夜秀、夜游等夜间经济产品，建设一批夜间文旅消费集聚区，擦亮“两江游”、“街巷游”等夜间经济名片，展现国际时尚范、巴蜀慢生活。\n第三节 塑造安全友好的消费环境\n完善消费促进政策。规范发展消费金融，在风险可控、商业可持续前提下稳妥开发适应新消费趋势的金融产品和服务。拓展移动支付使用范围，提升境外人员在境内使用移动支付便利化水平。研究将闲置厂房、办公用房等改为商业用途的支持政策。支持符合条件的地区建设市内免税店、口岸免税店、离境提货点。优化离境退税服务，促进国际消费便利化。\n健全消费者权益保障制度。推动服务标准化建设，发布行业优质企业名录，鼓励企业开展消费体验评价并公开评价结果。对涉及安全、健康、环保等方面的产品依法实施强制性产品认证（CCC认证），建设针对食品、药品等重点产品的溯源公共服务平台，推动溯源信息资源稳妥有序向社会开放。加强重点领域广告监管。鼓励线下实体店自主承诺无理由退货，探索建立特色旅游商品无理由退货制度。健全消费领域信用监管体系，加强信用信息采集，开展消费投诉信息公示，强化社会监督。完善消费环节经营者首问责任制和赔偿先付制度。\n第八章 共筑长江上游生态屏障\n坚持共抓大保护、不搞大开发，把修复长江生态环境摆在压倒性位置，深入践行绿水青山就是金山银山理念，坚持山水林田湖草是一个生命共同体，深入实施主体功能区战略，全面加快生态文明建设，建立健全国土空间规划体系，形成人与自然和谐共生的格局。\n第一节 推动生态共建共保\n共建生态网络。构建以长江、嘉陵江、乌江、岷江、沱江、涪江为主体，其他支流、湖泊、水库、渠系为支撑的绿色生态廊道。依托龙门山、华蓥山、大巴山、明月山等，实施森林生态系统休养生息和矿区恢复治理，共筑绿色生态屏障。加大对重点流域、三峡库区“共抓大保护”项目支持力度，实施“两岸青山·千里林带”等生态治理工程。推动大熊猫国家公园建设，加强珍稀濒危动植物保护。加快各类自然保护地整合优化，强化重要生态空间保护。打造龙泉山城市森林公园。强化周边地区生态系统保护和治理，加强三峡库区小流域和坡耕地水土流失综合治理，实施三峡库区消落带治理和岩溶地区石漠化综合治理。\n共抓生态管控。统筹建立并实施双城经济圈及其周边地区“三线一单”生态环境分区管控制度。加强流域水资源统一管理和联合调度。建立跨流域跨区域横向生态保护补偿机制。加大国家和省级生态保护补偿资金对长江上游生态屏障建设支持力度。严格执行生态损害赔偿制度。试点推进生态敏感区生态搬迁。落实好长江十年禁渔，实施长江上游流域重点水域全面禁捕，严厉打击非法捕捞，建立禁捕长效机制。依法联合查处交界区域破坏生态环境的违法行为。\n第二节 加强污染跨界协同治理\n统一环保标准。制定统一的环保标准编制技术规范，联合开展现行环保标准差异分析评估，有序制定修订统一的大气、水、土壤以及危险废物、噪声等领域环保标准。坚持一张负面清单管川渝两地，严格执行长江经济带发展负面清单管理制度体系，建立健全生态环境硬约束机制。开展跨区域联合环境执法，统一管控对象的界定标准和管控尺度，共同预防和处置突发环境事件。完善重大基础设施建设项目环境影响评价制度。\n推进跨界水体环境治理。完善跨省市水体监测网络，建立上下游水质信息共享和异常响应机制。开展联合巡河，加强工业污染、畜禽养殖、入河排污口、环境风险隐患点等协同管理。加强三峡库区入库水污染联合防治，加快长江入河排污口整改提升，统筹规划建设港口船舶污染物接收、转运及处置设施，推进水域“清漂”联动。推动毗邻地区污水处理设施共建共享。支持在长江、嘉陵江一级支流开展水环境治理试点示范，深化沱江、龙溪河、岷江流域水环境综合治理与可持续发展试点。完善饮用水水源地风险联合防控体系。\n深化大气污染联防联控。建设跨省市空气质量信息交换平台，发挥西南区域空气质量预测预报中心作用，实施联合预报预警。建立重污染天气共同应对机制，推进应急响应一体联动。探索实施细颗粒物（PM2.5）和臭氧（O3）污染连片整治。实施“散乱污”企业清理整治，依法淘汰落后产能，加快淘汰老旧车辆，加强油品质量联合监督。创建清洁能源高质量发展示范区，提高清洁能源消费比例。\n加强土壤污染及固废危废协同治理。以沿江工业园区、矿山、受污染耕地、污染地块为重点开展修复与治理。推动固体废物区域转移合作，建立健全固体废物信息化监管体系。统筹规划建设工业固体废物资源回收基地和危险废物资源处置中心，加强尾矿库污染治理，推进毗邻地区处置设施共建共享。依法严厉打击危险废物非法跨界转移、倾倒等违法行为。推动地级以上城市医疗废物集中处置设施全覆盖，县级以上城市及县城医疗废物全收集、全处理，并逐步覆盖到建制镇。协同开展“无废城市”建设。\n（注：PM2.5为PM右下角加2.5，O3为O右下角加3）","level":1},{"name":"第三节 探索绿色转型发展新路径","text":"构建绿色产业体系。培育壮大节能环保、清洁生产、清洁能源产业，打造国家绿色产业示范基地。联合打造绿色技术创新中心和绿色工程研究中心，实施重大绿色技术研发与示范工程。实施政府绿色采购，推行绿色产品优先。鼓励国家绿色发展基金加大向双城经济圈投资力度。推行企业循环式生产、产业循环式组合、园区循环化改造，开展工业园区清洁生产试点。落实最严格的水资源管理制度，实施节水行动，加大节能技术、节能产品推广应用力度。深化跨省市排污权、水权、用能权、碳排放权等交易合作。\n倡导绿色生活方式。共建绿色城市标准化技术支撑平台，完善统一的绿色建筑标准及认证体系，推广装配式建筑、钢结构建筑和新型建材。推动可再生能源利用，支持能源互联网创新，统筹布局电动汽车充换电配套设施。加快推进垃圾分类，共建区域一体化垃圾分类回收网络体系。完善对汽车等的强制报废配套政策，统筹布局再生资源分拣中心，建设城市废弃资源循环利用基地。鼓励创建国家生态文明建设示范市县，深入开展爱国卫生运动。\n开展绿色发展试验示范。支持万州及渝东北地区探索三峡绿色发展新模式，在生态产品价值实现、生态保护和补偿、绿色金融等领域先行先试、尽快突破，引导人口和产业向城镇化地区集聚，走出整体保护与局部开发平衡互促新路径，保护好三峡库区和长江母亲河。支持四川天府新区在公园城市建设中先行先试，开展可持续发展创新示范，实施城市生态用地改革创新，探索建立公园城市规划导则、指标评价、价值转化等体系。支持重庆广阳岛开展长江经济带绿色发展示范。建设沱江绿色发展经济带。","level":2},{"name":"第九章 联手打造内陆改革开放高地","text":"以共建“一带一路”为引领，打造陆海互济、四向拓展、综合立体的国际大通道，加快建设内陆开放枢纽，深入推进制度型开放，聚焦要素市场化配置等关键领域，深化综合配套改革试验，全面提升市场活力，在西部改革开放中发挥示范带动作用。","level":1},{"name":"第一节 加快构建对外开放大通道","text":"合力建设西部陆海新通道。深化西部省区市协作，支持发挥重庆通道物流和运营组织中心、成都国家重要商贸物流中心作用，共同建设跨区域平台，统筹设置境内外枢纽和集货分拨节点。支持建立铁路运输市场化与政府购买服务相结合的定价机制，降低综合运价水平。对接21世纪海上丝绸之路，推动国际陆海贸易新通道合作，与新加坡合作推动东盟及相关国家共同参与通道建设，探讨衔接中国－中南半岛、孟中印缅等经济走廊和中欧班列建设合作。\n统筹完善亚欧通道。加强协调联动，推动中欧班列高质量发展，打造西向开放前沿高地，紧密对接丝绸之路经济带。统筹优化中欧班列（成渝）去回程线路和运力，推动集结点、代理、运输、仓储、信息等资源共建共享，强化多式联运衔接，探索国际贸易新规则，提高通关便利化水平，增强国际竞争力。完善跨境邮递体系，建设铁路口岸国际邮件互换中心。打造重庆兴隆场、成都北中欧班列枢纽节点。开拓中欧班列中、东通道，积极衔接中蒙俄经济走廊。\n优化畅通东向开放通道。依托长江黄金水道和沿江铁路，构建通江达海、首尾联动的东向国际开放通道，扩大与日韩、欧美等国家和地区经贸合作。加强陆水、港航联动，开通往返主要港口的“水上穿梭巴士”和铁水联运班列，建设统一运营品牌，提高进出口货物运输效率、降低运输成本。推进沿江省市港口、口岸合作，优化“沪渝直达快线”运行机制，提高通关效率。","level":2},{"name":"第二节 高水平推进开放平台建设","text":"建设川渝自由贸易试验区协同开放示范区。加大力度推进首创性、差异化改革，支持重庆、四川自由贸易试验区协同开放，试行有利于促进跨境贸易便利化的外汇管理政策。探索更加便利的贸易监管制度。在双城经济圈复制推广自由贸易试验区改革创新成果。扩大金融、科技、医疗、贸易和数字经济等领域开放。\n打造内陆开放门户。以重庆两江新区、四川天府新区为重点，优先布局国家重大战略项目、试点示范项目，创建内陆开放型经济试验区。扩大包括第五航权在内的国际航权开放，按规定积极扩大铁路、港口、机场以适当方式对外开放，合理规划发展综合保税区、保税物流中心（B型）。加快建设中德、中法、中瑞（士）、中意等双边合作园区。培育进口贸易促进创新示范区，建设“一带一路”进出口商品集散中心。\n高标准实施高层级开放合作项目。推进中新（重庆）战略性互联互通示范项目，合规有序发展供应链金融和特色跨境金融服务平台，依托贸易金融区块链平台，探索形成贸易金融区块链标准体系。推动建设中新金融科技、航空产业、跨境交易、多式联运等领域合作示范区，建设第三方飞机维修中心，共同打造国际数据港。开展中日（成都）城市建设和现代服务业开放合作示范项目，建设药物供应链服务中心、先进医疗服务中心，推动科技、金融等领域合作。\n共建“一带一路”对外交往中心。支持举办重要国际会议和赛事。支持共建“一带一路”科技创新合作区和国际技术转移中心，共同举办“一带一路”科技交流大会。高标准举办中国国际智能产业博览会、中国西部国际投资贸易洽谈会、中国西部国际博览会、中国（绵阳）科技城国际科技博览会等国际大型会展。深化文化、教育、医疗、体育等领域国际交流，高质量建设国家文化出口基地，支持川剧、彩灯等中国文化走出去。加强国际友好城市往来。支持建立境外专业人才执业制度，放宽境外人员参加各类职业资格（不包括医疗卫生人员资格）考试限制，支持为外籍高层次人才来华投资就业提供入出境和停居留便利。","level":2},{"name":"第三节 加强国内区域合作","text":"加强与西部地区协调联动。加强与关中平原、兰州－西宁城市群联动，深化能源、物流、产业等领域合作，辐射带动西北地区发展。加强与北部湾、滇中城市群协作，把出境出海通道优势转化为贸易和产业优势，促进西南地区全方位开放。深化与黔中城市群合作，带动黔北地区发展。\n有力支撑长江经济带发展。加强与长江中游和下游协作，共同推动长江经济带绿色发展。促进生态环境联防联治，加快建立长江流域常态化横向生态保护补偿机制。共同推进长江黄金水道、沿江铁路、成品油输送管道等建设。优化沿江经济布局，有序承接产业转移和人口迁移。\n深化与东部沿海地区交流互动。对接京津冀协同发展、粤港澳大湾区建设、长三角一体化发展等重大战略，加强科技创新合作与科技联合攻关。鼓励与东部沿海城市建立产业合作结对关系，共建跨区域产业园区，促进项目、技术、人才等高效配置。支持沿海港口在双城经济圈设立无水港。深化三峡库区对口支援工作。","level":2},{"name":"第四节 营造一流营商环境","text":"建设高标准市场体系。共建统一的市场规则、互联互通的市场基础设施，加快清理废除妨碍统一市场和公平竞争的各种规定和做法。打破行政区划对要素流动的不合理限制，推动要素市场一体化，探索以电子营业执照为基础，加快建立公共资源交易平台市场主体信息共享与互认机制。探索建立“市场准入异地同标”机制，推进双城经济圈内同一事项无差别受理、同标准办理。全面实施外商投资准入前国民待遇加负面清单管理制度。推动信用一体化建设，逐步形成统一的区域信用政策法规制度和标准体系，支持共同开发适应经济社会发展需求的信用产品。\n持续转变政府职能。深化“放管服”改革，对标国际一流水平，加快服务型政府建设，最大限度精简行政审批事项和环节，推行政务服务“最多跑一次”改革，发布“零跑腿”事项清单，加快实现区域内“一网通办”。推行企业简易注销登记，开展企业投资项目承诺制改革，深化工程建设项目审批制度改革。优化综合监管体系，建立健全行政执法联动响应和协作机制。","level":2},{"name":"第五节 增强市场主体活力","text":"深化国有企业改革。有力有序推进国有企业混合所有制改革，推动国有企业建立健全有效制衡的现代企业治理体制、高度市场化和灵活高效的现代企业经营机制、激励和约束并重的现代企业激励机制，推进国有企业经理层成员任期制和契约化管理，完善中国特色现代企业制度，切实激发国有企业发展活力和内生动力。支持开展区域性国资国企综合改革试验。支持以市场化方式设立成渝混合所有制改革产业基金，吸引更多资本参与国有企业改革。加快完善国资监管体制，充分发挥国有资本投资运营公司作用，推动国资监管从管企业向管资本转变，真正实现政企分开、政资分开，使国有企业真正成为独立市场主体。深化效率导向的国资经营评价制度改革。\n大力发展民营经济。建立规范化、常态化政商沟通机制，畅通民营企业反映问题和诉求的渠道。积极缓解民营企业和中小微企业发展难题，创建民营经济示范城市。搭建川商渝商综合服务平台，引导川渝两省市商（协）会和重点民营企业共同开展项目推介、银企对接，鼓励川商渝商回乡创业。支持举办川渝民营经济发展合作峰会。","level":2},{"name":"第六节 探索经济区与行政区适度分离改革","text":"支持在重庆都市圈、成都都市圈以及川渝统筹发展示范区、川南渝西融合发展试验区等地，率先探索建立统一编制、联合报批、共同实施的规划管理体制，试行建设用地指标、收储和出让统一管理机制，探索招商引资、项目审批、市场监管等经济管理权限与行政区范围适度分离。支持在合作园区共同组建平台公司，协作开发建设运营，建立跨行政区财政协同投入机制，允许合作园区内企业自由选择注册地。以市场化为原则、资本为纽带、平台为载体，推动两省市机场、港口、中欧班列、西部陆海新通道等领域企业采取共同出资、互相持股等模式促进资源整合和高效运营。允许能源、电信、医疗等行业有序提供跨行政区服务。探索经济统计分算方式，支持建立互利共赢的地方留存部分税收分享机制，推进税收征管一体化。","level":2},{"name":"第十章 共同推动城乡融合发展","text":"以缩小城乡区域发展差距为目标，推动要素市场化配置，破除体制机制弊端，加快建设国家城乡融合发展试验区，形成工农互促、城乡互补、协调发展、共同繁荣的新型工农城乡关系。","level":1},{"name":"第一节 推动城乡要素高效配置","text":"促进城乡人口有序流动。在重庆主城和成都加快取消对稳定就业居住3年以上农业转移人口等重点群体的落户限制，推动都市圈内实现户籍准入年限同城化累计互认、居住证互通互认，完善居民户籍迁移便利化政策措施。尽快实现公共资源按常住人口规模配置。完善集体经济组织人力资源培育和开发利用机制，探索农业职业经理人培育模式和多种人才引进方式。维护进城落户农民在农村的土地承包权、宅基地使用权、集体收益分配权，研究通过合资、合作、投资入股等方式保障新村民依法享有农村相关权益。健全统一的人力资源市场体系，加快建立衔接协调的劳动力流动政策体系和交流合作机制。\n深化城乡土地制度改革。探索工业项目标准地出让，探索建立国有土地使用权到期续期制度。深化土地用途转用模式探索，推进城镇低效用地再开发，探索混合产业用地供给和点状供地模式，允许不同产业用地类型依法合理转换。完善建设用地使用权分层管理、统筹开发利用制度，促进地下空间开发。\n增强城乡建设资金保障。鼓励发展基础设施领域不动产投资信托基金，在防范债务风险前提下，推动城市建设投资稳定增长。发挥中央预算内投资作用，支持引导工商资本在农村投资。依法积极拓宽农业农村抵质押物范围，鼓励创新开发适应农业农村发展、农民需求的金融产品。通过发行地方政府专项债券等支持乡村振兴、农村产业融合发展等领域建设项目。运用大数据、区块链等技术，提高涉农信贷风险管理水平，优化普惠金融发展环境。","level":2},{"name":"第二节 推动城乡公共资源均衡配置","text":"推动城乡一体规划。加快推进“多规合一”，统筹生产、生活、生态、安全需要，建立国土空间规划留白机制和动态调整机制，提高规划适应性。开展城市体检，查找城市规划建设管理存在的风险和问题，探索可持续的城市更新模式，有序推进老旧小区、老旧厂区、老旧街区及城中村改造。强化城市风貌管理，促进建筑物设计更加适用、经济、绿色、美观，推动天际线、街道立面、建筑色彩更加协调，严格控制超高层建筑建设。加强历史文化街区、古镇古村、全国重点文物保护单位等遗产遗迹的整体保护和合理利用，延续城市和乡村文脉，保护传统的山水城格局。严禁违背农民意愿和超越发展阶段撤村并居。\n推动城乡基础设施一体化。完善级配合理的城乡路网和衔接便利的公交网络。推进城市电力、通信、供水、燃气、污水收集等市政管网升级改造和向乡村延伸，合理建设城市地下综合管廊。开展国家数字乡村试点。大力推进生活垃圾分类处理及再生利用设施建设，全面改善城乡居民卫生环境。加强城乡无障碍设施建设和设施适老化改造。推进城市公共基础设施管护资源、模式和手段逐步向乡村延伸，明确乡村基础设施产权归属，合理确定管护标准和模式，以政府购买服务等方式引入专业化机构管理运行。优化应急避难场所布局，完善抗震、防洪、排涝、消防等安全设施。\n推动城乡基本公共服务均等化。建立城乡教育联合体和县域医共体。深化义务教育阶段教师“县管校聘”管理改革，鼓励招募优秀退休教师到乡村和基层学校支教讲学，动态调整乡村教师岗位生活补助标准，在职称评审和分配特级教师名额时适当向农村薄弱学校倾斜。加快基层医疗卫生机构标准化建设，提高医护人员专业技术水平，对在农村基层工作的卫生技术人员在职称晋升等方面给予政策倾斜，推动对符合条件的全科医生实行“乡管村用”。把防止返贫摆在重要位置。\n健全城乡基层治理体系。健全党组织领导的自治、法治、德治相结合的城乡基层治理体系，加强农村新型经济组织和社会组织的党建工作。培育专业化社会组织和社会工作者队伍，调动企业履行社会责任积极性，畅通公众参与城乡治理渠道，推动政府、社会、企业、居民多方共治。推动基层治理重心下沉，完善社区网格化管理体系和便民服务体系，显著提升社区在流动人口服务管理、公共服务提供、社情民意收集等方面的作用。积极运用现代化手段，推动实现智慧化治理。妥善解决村改社区遗留问题。加强交界地带管理联动，建立重大工程项目选址协商制度，充分征求毗邻地区意见。","level":2},{"name":"第三节 推动城乡产业协同发展","text":"依托相应公共资源交易平台，推动农村集体经营性建设用地、承包地经营权、宅基地使用权、集体林权等依法流转和高效配置，盘活农村闲置资源资产。培育高品质特色小镇，着力发展优势主导特色产业。优化提升美丽乡村和各类农业园区，创建一批城乡融合发展典型项目，打造城乡产业协同发展先行区。","level":2},{"name":"第十一章 强化公共服务共建共享","text":"以更好满足人民群众美好生活需要为目标，扩大民生保障覆盖面，提升公共服务质量和水平，不断增强人民群众获得感、幸福感、安全感。","level":1},{"name":"第一节 推进基本公共服务标准化便利化","text":"建立基本公共服务标准体系。实施基本公共服务标准化管理，以标准化促进均等化、普惠化、便利化。联合制定基本公共服务标准，建立标准动态调整机制，合理增加保障项目，稳妥提高保障标准。创新政府公共服务投入机制，鼓励社会力量参与公共服务供给。加大双城经济圈对周边地区支持力度，保障基本公共服务全覆盖。\n提升基本公共服务便利化水平。共建公共就业综合服务平台，打造“智汇巴蜀”、“才兴川渝”人力资源品牌。重庆市和四川省互设劳务办事机构，推动农民工劳务企业规范化发展。支持探索发展灵活共享就业方式，强化对灵活就业人员的就业服务和权益保障。加快实现双城经济圈社会保险关系无障碍转移接续，推动养老金领取资格核查互认，加快推进全国统一医保信息平台跨省异地就医管理子系统建设，推进跨省市异地就医门急诊医疗直接结算，推进工伤认定和保险待遇政策统一。建设统一的社会保险公共服务平台，推广以社会保障卡为载体的“一卡通”服务管理模式。将常住人口纳入城镇公共租赁住房保障范围，逐步实现住房公积金转移接续和异地贷款信息共享、政策协同。","level":2},{"name":"第二节 共享教育文化体育资源","text":"推动教育合作发展。扩大普惠性幼儿园供给，加大对社会力量开展托育服务的支持力度。鼓励有条件的中小学集团化办学、开展对口帮扶，完善进城务工人员随迁子女就学和在流入地升学考试的政策措施。统筹职业教育布局和专业设置，扩大招生规模，打造一批职业教育基地。建设一批实训基地和国家级创业孵化基地，联手打造“巴蜀工匠”职业技能大赛品牌，打造有区域特色的产教融合行业、企业和院校。组建双城经济圈高校联盟，联手开展世界一流大学和一流学科建设，支持高校向区域性中心城市布局。建设城乡义务教育一体化发展试验区。支持引进境外高水平大学开展中外合作办学，允许外国教育机构、其他组织和个人在自由贸易试验区内单独设立非学制类职业培训机构、学制类职业教育机构，支持建设国际合作教育园区。\n构建现代公共文化服务体系。构建“书香成渝”全民阅读服务体系，鼓励博物馆、美术馆、文化馆等建立合作联盟，实现公共文化资源共享。建设三星堆国家文物保护利用示范区。推动出版、影视、舞台艺术发展，共同打造“成渝地·巴蜀情”等文化品牌。放宽文化演艺准入，研究建设文化艺术品和文物拍卖中心。建立非物质文化遗产保护协调机制，支持川剧、蜀锦、羌绣、夏布等非物质文化遗产的保护传承发展，研究建设巴蜀非遗文化产业园。\n共同推进体育事业发展。促进全民健身，推动公共体育场馆、全民健身活动中心、体育公园、社区体育场地等资源设施建设和开放共享，支持公办中小学校和高校的体育场馆、附属设施向社会分时段开放。建立成渝体育产业联盟，支持建设国家级足球竞训基地等专业场地，推动体育项目合作和竞技人才交流培养，协同申办国际国内高水准大型体育赛事。","level":2},{"name":"第三节 推动公共卫生和医疗养老合作","text":"构建强大公共卫生服务体系。增强公共卫生早期监测预警能力。健全重大突发公共卫生事件医疗救治体系，建设省级和市地级重大疫情救治基地、公共卫生综合临床中心。分级推动城市传染病救治体系建设，实现地级市传染病医院全覆盖，加强县级医院感染疾病科和相对独立的传染病区建设。提高公共卫生应急能力，完善联防联控常态机制。加强公共卫生应急物资储备，提升应急物资生产动员能力。\n优化医疗资源配置。依托四川大学华西医院、重庆医科大学附属医院等优质医疗资源，加快建设国家医学中心。支持共建区域医疗中心和国家临床重点专科群。推进国家老年疾病临床医学研究中心创新基地建设，支持重庆整合有关资源建设国家儿童区域医疗中心，推进四川省儿童医学中心建设。深化中医药创新协作。推动优质医疗资源下沉，支持医联体建设和跨区办医，推动中心城市三甲医院异地设置医疗机构。加强基层医疗卫生服务体系和全科医生队伍建设，构建更加成熟定型的分级诊疗制度。发展在线医疗，建立区域专科联盟和远程医疗协作体系，实现会诊、联网挂号等远程医疗服务。完善二级以上医疗机构医学检验结果互认和双向转诊合作机制。\n推进养老服务体系共建共享。开展普惠养老城企联动专项行动，发展居家养老、社区养老、机构养老，构建综合连续、覆盖城乡的老年健康服务体系。支持以市场化方式稳妥设立养老产业发展引导基金，制定产业资本和品牌机构进入养老市场指引，支持民营养老机构品牌化、连锁化发展。推动老年人照护需求评估、老年人入住评估等互通互认。鼓励养老设施跨区域共建。统筹医疗卫生和养老服务资源，促进医养融合。推动人口信息互通共享，率先建立人口发展监测分析系统，开展积极应对人口老龄化综合创新试点。","level":2},{"name":"第四节 健全应急联动机制","text":"健全公共安全风险防控标准和规划体系。强化防灾备灾体系和能力建设，完善重大灾害事件预防处理和紧急救援联动机制，加快建设国家西南区域应急救援中心以及物资储备中心，打造2小时应急救援圈，推进防灾减灾救灾一体化。建立健全安全生产责任体系和联动长效机制，有效防范和坚决遏制重特大安全生产事故发生。推广实施公共设施平急两用改造，提升平急转换能力。在跨界毗邻地区，按可达性统筹120、110等服务范围。","level":2},{"name":"第十二章 推进规划实施","text":"加强党对成渝地区双城经济圈建设的领导，明确各级党委和政府职责，细化各项政策措施，建立健全协同实施机制，确保规划纲要主要目标和任务顺利实现。","level":1},{"name":"第一节 加强党的集中统一领导","text":"坚定不移加强党的全面领导，增强“四个意识”，坚定“四个自信”，做到“两个维护”。充分发挥党总揽全局、协调各方的领导核心作用，把党的领导始终贯穿成渝地区双城经济圈建设重大事项决策、重大规划制定调整等各方面全过程。充分发挥党的各级组织在推进成渝地区双城经济圈建设中的领导作用和战斗堡垒作用，激励干部锐意进取、担当作为，组织动员全社会力量落实规划纲要，形成强大合力。","level":2},{"name":"第二节 强化组织实施","text":"重庆市、四川省作为成渝地区双城经济圈建设的责任主体，要明确工作分工，完善工作机制，共同研究制定年度工作计划，落实工作责任，把规划纲要确定的各项任务落到实处。中央有关部门要按照职责分工，加强对规划纲要实施的指导，在规划编制、体制创新、政策制定、项目安排等方面给予积极支持。国家发展改革委要依托城镇化工作暨城乡融合发展工作部际联席会议制度，加强对规划纲要实施的统筹指导，协调解决规划纲要实施中面临的突出问题，督促落实重大事项，适时组织开展评估，及时总结经验做法。重大规划、重大政策、重大项目按程序报批，重大问题及时向党中央、国务院请示报告。","level":2},{"name":"第三节 完善配套政策体系","text":"中央有关部门要加强与重庆市、四川省沟通衔接，负责编制印发实施成渝地区双城经济圈国土空间规划以及多层次轨道交通体系、综合交通发展、西部金融中心建设、科技创新中心建设、生态环境保护、巴蜀文化旅游走廊等规划或实施方案，指导编制践行新发展理念的公园城市示范区、川渝统筹发展示范区、川南渝西融合发展试验区等建设方案，研究出台产业、人才、土地、投资、财政、金融等领域配套政策和综合改革措施。重庆市、四川省编制出台重庆都市圈、成都都市圈发展规划，共同推动形成规划和政策体系，不改变不减弱对三峡库区等周边地区的支持政策。","level":2},{"name":"第四节 健全合作机制","text":"健全推动成渝地区双城经济圈建设重庆四川党政联席会议机制，研究落实重点任务、重大改革、重大项目等，压茬推进各项任务。建立交通、产业、创新、市场、资源环境、公共服务等专项合作机制，分领域策划和推进具体合作事项及项目。培育合作文化，鼓励两省市地方建立合作协同机制。推动与东部地区开展干部人才双向交流、挂职任职。广泛听取社会各界意见和建议，营造全社会共同推动成渝地区双城经济圈建设的良好氛围。\n延伸阅读\n推动成渝地区双城经济圈建设 打造高质量发展重要增长极","level":2}]},{"id":"r0513","sections":[{"name":"中共中央印发《法治中国建设规划（2020—2025年）》","text":"近日，中共中央印发了《法治中国建设规划（2020－2025年）》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《法治中国建设规划（2020－2025年）》主要内容如下。\n法治是人类文明进步的重要标志，是治国理政的基本方式，是中国共产党和中国人民的不懈追求。法治兴则国兴，法治强则国强。为统筹推进法治中国建设各项工作，制定本规划。","level":0},{"name":"一、坚定不移走中国特色社会主义法治道路，奋力建设良法善治的法治中国","text":"党的十八大以来，以习近平同志为核心的党中央从坚持和发展中国特色社会主义的全局和战略高度定位法治、布局法治、厉行法治，将全面依法治国纳入“四个全面”战略布局，加强党对全面依法治国的集中统一领导，全面推进科学立法、严格执法、公正司法、全民守法，形成了习近平法治思想，开创了全面依法治国新局面，为在新的起点上建设法治中国奠定了坚实基础。\n当今世界正经历百年未有之大变局，我国正处于实现中华民族伟大复兴关键时期，改革发展稳定任务艰巨繁重，全面对外开放深入推进，人民群众在民主、法治、公平、正义、安全、环境等方面的要求日益增长，需要更好发挥法治固根本、稳预期、利长远的保障作用。在统揽伟大斗争、伟大工程、伟大事业、伟大梦想，全面建设社会主义现代化国家新征程上，必须把全面依法治国摆在全局性、战略性、基础性、保障性位置，向着全面建成法治中国不断前进。\n（一）指导思想\n高举中国特色社会主义伟大旗帜，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，全面贯彻习近平法治思想，增强“四个意识”、坚定“四个自信”、做到“两个维护”，坚持党的领导、人民当家作主、依法治国有机统一，坚定不移走中国特色社会主义法治道路，培育和践行社会主义核心价值观，以解决法治领域突出问题为着力点，建设中国特色社会主义法治体系，建设社会主义法治国家，在法治轨道上推进国家治理体系和治理能力现代化，提高党依法治国、依法执政能力，为全面建设社会主义现代化国家、实现中华民族伟大复兴的中国梦提供有力法治保障。\n（二）主要原则\n——坚持党的集中统一领导。牢牢把握党的领导是社会主义法治最根本的保证，坚持党领导立法、保证执法、支持司法、带头守法，充分发挥党总揽全局、协调各方的领导核心作用，确保法治中国建设的正确方向。\n——坚持贯彻中国特色社会主义法治理论。深入贯彻习近平法治思想，系统总结运用新时代中国特色社会主义法治建设的鲜活经验，不断推进理论和实践创新发展。\n——坚持以人民为中心。坚持法治建设为了人民、依靠人民，促进人的全面发展，努力让人民群众在每一项法律制度、每一个执法决定、每一宗司法案件中都感受到公平正义，加强人权法治保障，非因法定事由、非经法定程序不得限制、剥夺公民、法人和其他组织的财产和权利。\n——坚持统筹推进。坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设，坚持依法治国和以德治国相结合，坚持依法治国和依规治党有机统一，全面推进科学立法、严格执法、公正司法、全民守法。\n——坚持问题导向和目标导向。聚焦党中央关注、人民群众反映强烈的突出问题和法治建设薄弱环节，着眼推进国家治理体系和治理能力现代化，固根基、扬优势、补短板、强弱项，切实增强法治中国建设的时代性、针对性、实效性。\n——坚持从中国实际出发。立足我国基本国情，统筹考虑经济社会发展状况、法治建设总体进程、人民群众需求变化等综合因素，汲取中华法律文化精华，借鉴国外法治有益经验，循序渐进、久久为功，确保各项制度设计行得通、真管用。\n（三）总体目标\n建设法治中国，应当实现法律规范科学完备统一，执法司法公正高效权威，权力运行受到有效制约监督，人民合法权益得到充分尊重保障，法治信仰普遍确立，法治国家、法治政府、法治社会全面建成。\n到2025年，党领导全面依法治国体制机制更加健全，以宪法为核心的中国特色社会主义法律体系更加完备，职责明确、依法行政的政府治理体系日益健全，相互配合、相互制约的司法权运行机制更加科学有效，法治社会建设取得重大进展，党内法规体系更加完善，中国特色社会主义法治体系初步形成。\n到2035年，法治国家、法治政府、法治社会基本建成，中国特色社会主义法治体系基本形成，人民平等参与、平等发展权利得到充分保障，国家治理体系和治理能力现代化基本实现。","level":1},{"name":"二、全面贯彻实施宪法，坚定维护宪法尊严和权威","text":"建设法治中国，必须高度重视宪法在治国理政中的重要地位和作用，坚持依宪治国、依宪执政，把全面贯彻实施宪法作为首要任务，健全保证宪法全面实施的体制机制，将宪法实施和监督提高到新水平。\n（四）坚持把宪法作为根本活动准则。全国各族人民、一切国家机关和武装力量、各政党和各社会团体、各企业事业组织，都负有维护宪法尊严、保证宪法实施的职责，都不得有超越宪法法律的特权。坚持宪法法律至上，维护国家法制统一、尊严、权威，一切法律法规规章规范性文件都不得同宪法相抵触，一切违反宪法法律的行为都必须予以追究。党带头尊崇和执行宪法，把党领导人民制定和实施宪法法律同党坚持在宪法法律范围内活动统一起来，保障宪法法律的有效实施。\n（五）加强宪法实施和监督。全国人大及其常委会要切实担负起宪法监督职责，加强宪法实施和监督，并将其作为全国人大常委会年度工作报告的重要事项。全国人大及其常委会通过的法律和作出的决定决议，应当确保符合宪法规定、宪法精神。推进合宪性审查工作，健全合宪性审查制度，明确合宪性审查的原则、内容、程序。建立健全涉及宪法问题的事先审查和咨询制度，有关方面拟出台的行政法规、军事法规、监察法规、地方性法规、经济特区法规、自治条例和单行条例、部门规章、地方政府规章、司法解释以及其他规范性文件和重要政策、重大举措，凡涉及宪法有关规定如何理解、实施、适用问题的，都应当依照有关规定向全国人大常委会书面提出合宪性审查请求。在备案审查工作中，应当注重审查是否存在不符合宪法规定和宪法精神的内容。加强宪法解释工作，落实宪法解释程序机制，回应涉及宪法有关问题的关切。\n（六）推进宪法学习宣传教育。在全社会深入开展尊崇宪法、学习宪法、遵守宪法、维护宪法、运用宪法的宪法学习宣传教育活动，普及宪法知识，弘扬宪法精神。抓住领导干部这个“关键少数”，把宪法法律学习列为党委（党组）理论学习中心组学习的重要内容，纳入党和国家工作人员培训教育体系。全面落实宪法宣誓制度。加强青少年宪法法律教育，增强青少年的规则意识、法治观念。在“五四宪法”历史资料陈列馆基础上建设国家宪法宣传教育馆。加强宪法理论研究和教材编写、修订、使用，凝练我国宪法的时代特色和实践特色，形成中国特色社会主义宪法理论和宪法话语体系。","level":1},{"name":"三、建设完备的法律规范体系，以良法促进发展、保障善治","text":"建设法治中国，必须加强和改进立法工作，深入推进科学立法、民主立法、依法立法，不断提高立法质量和效率，以高质量立法保障高质量发展、推动全面深化改革、维护社会大局稳定。\n（七）完善立法工作格局。加强党对立法工作的领导，完善党委领导、人大主导、政府依托、各方参与的立法工作格局。党中央领导全国立法工作、研究决定国家立法工作中的重大问题，有立法权地方的党委按照党中央大政方针领导本地区立法工作。\n完善人大主导立法工作的体制机制。加强人大对立法工作的组织协调，发挥人大及其常委会的审议把关作用。健全全国人大相关专门委员会、全国人大常委会工作机构牵头起草重要法律草案机制。更好发挥人大代表在起草和修改法律法规中的作用，人民代表大会会议一般都应当安排审议法律法规案。研究完善人大常委会会议制度，探索增加人大常委会审议法律法规案的会次安排。充分发挥人大常委会组成人员在立法中的作用，逐步提高人大常委会专职委员特别是有法治实践经验的专职委员比例。\n注重发挥政府在立法工作中的重要作用。做好有关法律、地方性法规草案的起草工作，加强政府部门间立法协调。严格按照法定权限和程序制定行政法规、规章，保证行政法规、规章质量。\n拓宽社会各方有序参与立法的途径和方式。加强立法协商，充分发挥政协委员、民主党派、工商联、无党派人士、人民团体、社会组织在立法协商中的作用。\n（八）坚持立改废释并举。加强重点领域、新兴领域、涉外领域立法。推动贯彻新发展理念、构建新发展格局，加快完善深化供给侧结构性改革、促进创新驱动发展、防范化解金融风险等急需的法律法规。加强对权力运行的制约和监督，健全规范共同行政行为的法律法规，研究制定行政程序法。围绕加强社会主义文化建设，完善发展文化事业和文化产业、保护知识产权等方面的法律法规。加强保障和改善民生、创新社会治理方面的法律制度建设，为推进教育现代化、实施健康中国战略、维护社会治安等提供有力保障。加强疫情防控相关立法和配套制度建设，完善有关处罚程序，强化公共安全保障，构建系统完备、科学规范、运行有效的突发公共卫生事件应对法律体系。加强同民法典相关联、相配套的法律制度建设。加强国家安全领域立法。健全军民融合发展法律制度。加强信息技术领域立法，及时跟进研究数字经济、互联网金融、人工智能、大数据、云计算等相关法律制度，抓紧补齐短板。加强区域协调发展法律制度建设。制定和修改法律法规要着力解决违法成本过低、处罚力度不足问题。统筹解决食品药品、生态环境、安全生产等领域法律法规存在的该硬不硬、该严不严、该重不重问题。\n针对法律规定之间不一致、不协调、不适应问题，及时组织清理。对某一领域有多部法律的，条件成熟时进行法典编纂。加强立法的协同配套工作，实行法律草案与配套规定同步研究、同步起草，增强法律规范整体功效。加强立法评估论证工作。加强法律法规解释工作。建设全国统一的法律、法规、规章、行政规范性文件、司法解释和党内法规信息平台。\n坚持立法和改革相衔接相促进，做到重大改革于法有据，充分发挥立法的引领和推动作用。对改革急需、立法条件成熟的，抓紧出台；对立法条件还不成熟、需要先行先试的，依法及时作出授权决定或者改革决定。授权决定或者改革决定涉及的改革举措，实践证明可行的，及时按照程序制定修改相关法律法规。\n完善弘扬社会主义核心价值观的法律政策体系，把社会主义核心价值观要求融入法治建设和社会治理。\n加强京津冀协同发展、长江经济带发展、粤港澳大湾区建设、长三角一体化发展、黄河流域生态保护和高质量发展、推进海南全面深化改革开放等国家重大发展战略的法治保障。\n（九）健全立法工作机制。健全立法立项、起草、论证、协调、审议机制，提高立法的针对性、及时性、系统性、可操作性。健全立法规划计划编制制度，充分发挥立法规划计划的统筹引领作用。健全立法征求意见机制，扩大公众参与的覆盖面和代表性，增强立法透明度。对与企业生产经营密切相关的立法项目，充分听取有关企业和行业协会商会意见。健全立法征求公众意见采纳反馈机制，对相对集中的意见未予采纳的，应当进行说明。充分利用大数据分析，为立法中的重大事项提供统计分析和决策依据。对立法涉及的重大利益调整事项加强论证咨询，推进对争议较大的重要立法事项引入第三方评估工作。建立健全重要立法争议事项协调机制，防止立法项目久拖不决。完善立法技术规范，加强立法指引。\n（十）加强地方立法工作。有立法权的地方应当紧密结合本地发展需要和实际，突出地方特色和针对性、实效性，创造性做好地方立法工作。健全地方立法工作机制，提高立法质量，确保不与上位法相抵触，切实避免越权立法、重复立法、盲目立法。建立健全区域协同立法工作机制，加强全国人大常委会对跨区域地方立法的统一指导。2025年年底前，完成对全国地方立法工作人员的轮训。","level":1},{"name":"四、建设高效的法治实施体系，深入推进严格执法、公正司法、全民守法","text":"建设法治中国，必须深入推进严格执法、公正司法、全民守法，健全社会公平正义法治保障制度，织密法治之网，强化法治之力，不断增强人民群众的获得感、幸福感、安全感。\n（十一）构建职责明确、依法行政的政府治理体系。各级政府必须坚持依法行政，恪守法定职责必须为、法无授权不可为，把政府活动全面纳入法治轨道。\n依法全面履行政府职能，着力厘清政府和市场、政府和社会的关系，更加注重用法律和制度遏制不当干预经济活动的行为。深入推进简政放权，持续整治变相设置行政许可事项的违法违规行为。大力推行清单制度并实行动态管理，编制完成并公布中央层面设定的行政许可事项清单、备案管理事项清单，国务院部门权责清单于2022年上半年前编制完成并公布。\n严格落实重大行政决策程序制度，切实防止违法决策、不当决策、拖延决策。充分发挥法律顾问、公职律师在重大行政决策中的作用。建立健全重大行政决策跟踪反馈和评估制度。全面推行行政规范性文件合法性审核机制，凡涉及公民、法人或其他组织权利和义务的行政规范性文件均应经过合法性审核。\n深化行政执法体制改革，统筹配置行政执法职能和执法资源，最大限度减少不必要的行政执法事项。进一步整合行政执法队伍，继续探索实行跨领域跨部门综合执法。推动执法重心向市县两级政府下移，加大执法人员、经费、资源、装备等向基层倾斜力度。健全事前事中事后监管有效衔接、信息互联互通共享、协同配合工作机制。完善行政执法权限协调机制。健全行政执法和刑事司法衔接机制，全面推进“两法衔接”信息平台建设和应用。完善行政强制执行体制机制。建立健全军地联合执法机制。\n坚持严格规范公正文明执法，全面推行行政执法公示制度、执法全过程记录制度、重大执法决定法制审核制度。加大食品药品、公共卫生、生态环境、安全生产、劳动保障、野生动物保护等关系群众切身利益的重点领域执法力度。推进统一的行政执法人员资格和证件管理、行政执法文书基本标准、行政执法综合管理监督信息系统建设。全面推行行政裁量权基准制度，规范执法自由裁量权。改进和创新执法方式，加强行政指导、行政奖励、行政和解等非强制行政手段的运用。建立行政执法案例指导制度。建立健全行政执法风险防控机制。严格执行突发事件应对有关法律法规，依法实施应急处置措施，全面提高依法应对突发事件能力和水平。\n加强和创新事中事后监管，推进“双随机、一公开”跨部门联合监管，强化重点领域重点监管，探索信用监管、大数据监管、包容审慎监管等新型监管方式，努力形成全覆盖、零容忍、更透明、重实效、保安全的事中事后监管体系。持续开展“减证便民”行动，推行证明事项告知承诺制。\n持续营造法治化营商环境，实施统一的市场准入负面清单制度，清理破除隐性准入壁垒，普遍落实“非禁即入”。全面清理、废止对非公有制经济的各种形式不合理规定，坚决纠正滥用行政权力排除、限制竞争行为。全面清理违法违规的涉企收费、检查、摊派事项和评比达标表彰活动。加强政务诚信建设，重点治理政府失信行为，加大惩处和曝光力度。实行知识产权侵权惩罚性赔偿制度，激励和保护科技创新。\n加快推进“互联网+政务服务”，政务服务重点领域和高频事项基本实现“一网、一门、一次”。2022年年底前建成全国一体化政务服务平台，除法律法规另有规定或涉及国家秘密等外，政务服务事项全部纳入平台办理，全面实现“一网通办”。\n（十二）建设公正高效权威的中国特色社会主义司法制度。紧紧抓住影响司法公正、制约司法能力的深层次问题，坚持符合国情和遵循司法规律相结合，坚持和加强党对司法工作的绝对领导。健全公安机关、检察机关、审判机关、司法行政机关各司其职，侦查权、检察权、审判权、执行权相互配合、相互制约的体制机制。深化司法体制综合配套改革，全面落实司法责任制。\n明确四级法院职能定位，充分发挥审级监督功能。完善民事再审程序，探索将具有普遍法律适用指导意义、关乎社会公共利益的案件交由较高层级法院审理。完善最高人民法院巡回法庭工作机制，健全综合配套措施。完善知识产权、金融、海事等专门法院建设，加强互联网法院建设。深化与行政区划适当分离的司法管辖制度改革。健全未成年人司法保护体系。\n坚持“让审理者裁判、由裁判者负责”，依法赋权独任庭、合议庭。健全重大、疑难、复杂案件由院庭长直接审理机制。坚持“谁办案谁负责、谁决定谁负责”，落实检察官办案主体地位。健全担任领导职务的检察官直接办案制度。加强办案团队建设，推动司法人员专业化分工、类案专业化办理。健全专业法官会议、检察官联席会议制度，切实发挥为办案组织提供法律咨询的功能。加强和完善指导性案例制度，确保法律适用统一。\n深化以审判为中心的刑事诉讼制度改革。健全侦查机关调查收集证据制度，规范补充侦查、不起诉、撤回起诉制度。完善庭前会议、非法证据排除制度，规范法庭调查和庭审量刑程序，落实证人、鉴定人、侦查人员出庭作证制度，完善技术侦查证据的法庭调查和使用规则。完善认罪认罚从宽制度，落实宽严相济刑事政策。改革刑事申诉制度，对不服司法机关生效裁判和决定的申诉，逐步实行由律师代理制度。健全落实法律援助值班律师制度，实现刑事案件律师辩护、法律帮助全覆盖。健全有关工作机制，依法从严从快惩处妨碍突发事件应对的违法犯罪行为。\n完善民事诉讼制度体系。探索扩大小额诉讼程序适用范围，完善其与简易程序、普通程序的转换适用机制。探索扩大独任制适用范围。优化司法确认程序适用。改革诉讼收费制度。全面建设集约高效、多元解纷、便民利民、智慧精准、开放互动、交融共享的现代化诉讼服务体系。加快推进跨域立案诉讼服务改革，2022年年底前实现诉讼服务就近能办、同城通办、异地可办。\n深化执行体制改革，加强执行难综合治理、源头治理。深入推进审执分离，优化执行权配置，落实统一管理、统一指挥、统一协调的执行工作机制。完善刑罚执行制度，统一刑罚执行体制。深化监狱体制机制改革，实行罪犯分类、监狱分级制度。完善社区矫正制度。完善监狱、看守所与社区矫正和安置帮教机构之间的工作对接机制。\n（十三）深入推进全民守法。全面依法治国需要全社会共同参与，必须大力弘扬社会主义法治精神，建设社会主义法治文化，引导全体人民做社会主义法治的忠实崇尚者、自觉遵守者、坚定捍卫者。\n改进创新普法工作，加大全民普法力度，增强全民法治观念。建立健全立法工作宣传报道常态化机制，对立法热点问题主动发声、解疑释惑。全面落实“谁执法谁普法”普法责任制。深入开展法官、检察官、行政复议人员、行政执法人员、律师等以案释法活动。加强突发事件应对法治宣传教育和法律服务。\n广泛推动人民群众参与社会治理，打造共建共治共享的社会治理格局。完善群众参与基层社会治理的制度化渠道。加快推进市域社会治理现代化。健全社会治理规范体系。发挥工会、共青团、妇联等群团组织引领联系群众参与社会治理的作用。加快推进社会信用立法，完善失信惩戒机制。规范失信惩戒对象名单制度，依法依规明确制定依据、适用范围、惩治标准和救济机制，在加强失信惩戒的同时保护公民、企业合法权益。加强对产权的执法司法保护，健全涉产权错案甄别纠正机制。完善对暴力袭警行为的刑事责任追究制度。加大对暴力伤害医务人员犯罪行为打击力度。\n紧紧围绕人民日益增长的美好生活需要加强公共法律服务，加快整合律师、公证、调解、仲裁、法律援助、司法鉴定等公共法律服务资源，到2022年基本形成覆盖城乡、便捷高效、均等普惠的现代公共法律服务体系。构建公共法律服务评价指标体系，以群众满意度来检验公共法律服务工作成效。推动建设一支高素质涉外法律服务队伍、建设一批高水平涉外法律服务机构。\n积极引导人民群众依法维权和化解矛盾纠纷，坚持和发展新时代“枫桥经验”。充分发挥人民调解的第一道防线作用，完善人民调解、行政调解、司法调解联动工作体系。全面开展律师调解工作。完善调解、信访、仲裁、行政裁决、行政复议、诉讼等社会矛盾纠纷多元预防调处化解综合机制，整合基层矛盾纠纷化解资源和力量，充分发挥非诉纠纷解决机制作用。深化法律援助制度改革，扩大法律援助覆盖面。有序推进行政裁决工作，探索扩大行政裁决适用范围。","level":1},{"name":"五、建设严密的法治监督体系，切实加强对立法、执法、司法工作的监督","text":"建设法治中国，必须抓紧完善权力运行制约和监督机制，规范立法、执法、司法机关权力行使，构建党统一领导、全面覆盖、权威高效的法治监督体系。\n（十四）推进对法治工作的全面监督。加强党对法治监督工作的集中统一领导，把法治监督作为党和国家监督体系的重要内容，保证行政权、监察权、审判权、检察权得到依法正确行使，保证公民、法人和其他组织合法权益得到切实保障。加强国家机关监督、民主监督、群众监督和舆论监督，形成法治监督合力，发挥整体监督效能。推进执纪执法贯通、有效衔接司法。完善人民监督员制度。坚持以公开为常态、不公开为例外，全面推进立法公开、执法公开、司法公开，逐步扩大公开范围，提升公开服务水平，主动接受新闻媒体舆论监督和社会监督。党委政法委应当指导、推动政法单位建立健全与执法司法权运行机制相适应的制约监督体系，构建权责清晰的执法司法责任体系，健全政治督察、综治督导、执法监督、纪律作风督查巡查等制度机制。\n（十五）加强立法监督工作。建立健全立法监督工作机制，完善监督程序。推进法律法规规章起草征求人大代表、政协委员意见工作。依法处理国家机关和社会团体、企业事业组织、公民对法规规章等书面提出的审查要求或者审查建议。\n加强备案审查制度和能力建设，实现有件必备、有备必审、有错必纠。完善备案审查程序，明确审查范围、标准和纠正措施。强化对地方各级政府和县级以上政府部门行政规范性文件、地方各级监察委员会监察规范性文件的备案审查。加强对司法解释的备案监督。将地方法院、检察院制定的规范性文件纳入本级人大常委会备案审查范围。加快建立全国统一的备案审查信息平台。建立健全党委、人大常委会、政府、军队等之间的备案审查衔接联动机制。建立健全备案审查工作年度报告制度。\n（十六）加强对执法工作监督。加强省市县乡四级全覆盖的行政执法协调监督工作体系建设，强化全方位、全流程监督，提高执法质量。加大对执法不作为、乱作为、选择性执法、逐利执法等有关责任人的追责力度，落实行政执法责任制和责任追究制度。完善行政执法投诉举报和处理机制。\n加强和改进行政复议工作，强化行政复议监督功能，加大对违法和不当行政行为的纠错力度。推进行政复议体制改革，整合行政复议职责，畅通行政复议渠道，2022年前基本形成公正权威、统一高效的行政复议工作体制。健全行政复议案件审理机制，加强行政复议规范化、专业化、信息化建设。规范和加强行政应诉工作。\n（十七）加强对司法活动监督。健全对法官、检察官办案的制约和监督制度，促进司法公正。全面推行法官、检察官办案责任制，统一规范法官、检察官办案权限。加强审判权、检察权运行监督管理，明确法院院长、庭长和检察院检察长、业务部门负责人监督管理权力和责任，健全审判人员、检察人员权责清单。完善对担任领导职务的法官、检察官办案情况的考核监督机制，配套建立内部公示、定期通报机制。健全落实司法机关内部人员过问案件记录追责、规范司法人员与律师和当事人等接触交往行为的制度。构建科学合理的司法责任认定和追究制度。完善司法人员惩戒制度，明确惩戒情形和程序。\n完善民事、行政检察监督和检察公益诉讼案件办理机制。健全对最高人民法院巡回法庭、知识产权法院、金融法院、互联网法院等的法律监督机制。拓展公益诉讼案件范围，完善公益诉讼法律制度，探索建立民事公益诉讼惩罚性赔偿制度。完善检察建议制度。\n完善刑事立案监督和侦查监督工作机制。健全刑事案件统一审核、统一出口工作机制，规范证据审查判断与运用。健全侦查机关办理重大案件听取检察机关意见建议制度。完善对查封、扣押、冻结等侦查措施的监督机制。健全刑事申诉案件受理、移送、复查机制。推动在市县公安机关建设执法办案管理中心。\n加强人权司法保障。建立重大案件侦查终结前对讯问合法性进行核查制度。健全讯问犯罪嫌疑人、听取辩护人意见工作机制。建立对监狱、看守所的巡回检察制度。完善看守所管理制度。完善有效防范和及时发现、纠正冤假错案工作机制。健全辩护人、诉讼代理人行使诉讼权利保障机制。","level":1},{"name":"六、建设有力的法治保障体系，筑牢法治中国建设的坚实后盾","text":"建设法治中国，必须加强政治、组织、队伍、人才、科技、信息等保障，为全面依法治国提供重要支撑。\n（十八）加强政治和组织保障。各级党委（党组）和领导干部要支持立法、执法、司法机关开展工作，支持司法机关依法独立公正行使职权。党的各级组织部门等要发挥职能作用，保障推进法治中国建设。中央和省级党政部门要明确负责本部门法治工作的机构。各级立法、执法、司法机关党组（党委）要加强领导、履职尽责，机关基层党组织和党员要充分发挥战斗堡垒和先锋模范作用，保障宪法法律实施。严格执行《领导干部干预司法活动、插手具体案件处理的记录、通报和责任追究规定》。\n（十九）加强队伍和人才保障。牢牢把握忠于党、忠于国家、忠于人民、忠于法律的总要求，大力提高法治工作队伍思想政治素质、业务工作能力、职业道德水准，努力建设一支德才兼备的高素质法治工作队伍。\n建设革命化、正规化、专业化、职业化的法治专门队伍。坚持把政治标准放在首位，加强科学理论武装，深入开展理想信念教育。完善法律职业准入、资格管理制度，建立法律职业人员统一职前培训制度和在职法官、检察官、警官、律师同堂培训制度。完善从符合条件的律师、法学专家中招录立法工作者、法官、检察官、行政复议人员制度。加强立法工作队伍建设。建立健全立法、执法、司法部门干部和人才常态化交流机制，加大法治专门队伍与其他部门具备条件的干部和人才交流力度。加强边疆地区、民族地区和基层法治专门队伍建设。健全法官、检察官员额管理制度，规范遴选标准、程序。加强执法司法辅助人员队伍建设。建立健全符合职业特点的法治工作人员管理制度，完善职业保障体系。健全执法司法人员依法履职免责、履行职务受侵害保障救济、不实举报澄清等制度。加强法治专门队伍教育培训。\n加快发展律师、公证、司法鉴定、仲裁、调解等法律服务队伍。健全职业道德准则、执业行为规范，完善职业道德评价机制。把拥护中国共产党领导、拥护我国社会主义法治作为法律服务人员从业的基本要求。坚持和加强党对律师工作的领导，推动律师行业党的建设。完善律师执业权利保障制度机制。健全法官、检察官、律师等法律职业人员惩戒机制，建立律师不良执业信息记录披露和查询制度。发展公职律师、公司律师和党政机关、企事业单位、村（居）法律顾问队伍。\n构建凸显时代特征、体现中国特色的法治人才培养体系。坚持以习近平新时代中国特色社会主义思想为指导，坚持立德树人、德法兼修，解决好为谁教、教什么、教给谁、怎样教的问题。推动以马克思主义为指导的法学学科体系、学术体系、教材体系、话语体系建设。深化高等法学教育改革，优化法学课程体系，强化法学实践教学，培养信念坚定、德法兼修、明法笃行的高素质法治人才。推进教师队伍法治教育培训。加强法学专业教师队伍建设。完善高等学校涉外法学专业学科设置。加大涉外法治人才培养力度，创新涉外法治人才培养模式。建立健全法学教育、法学研究工作者和法治实践工作者之间双向交流机制。\n（二十）加强科技和信息化保障。充分运用大数据、云计算、人工智能等现代科技手段，全面建设“智慧法治”，推进法治中国建设的数据化、网络化、智能化。优化整合法治领域各类信息、数据、网络平台，推进全国法治信息化工程建设。加快公共法律服务实体平台、热线平台、网络平台有机融合，建设覆盖全业务、全时空的公共法律服务网络。","level":1},{"name":"七、建设完善的党内法规体系，坚定不移推进依规治党","text":"建设法治中国，必须坚持依法治国和依规治党有机统一，加快形成覆盖党的领导和党的建设各方面的党内法规体系，增强党依法执政本领，提高管党治党水平，确保党始终成为中国特色社会主义事业的坚强领导核心。\n（二十一）健全党内法规体系。坚持和加强党的全面领导，坚持党要管党、全面从严治党，以党章为根本，以民主集中制为核心，不断完善党的组织法规、党的领导法规、党的自身建设法规、党的监督保障法规，构建内容科学、程序严密、配套完备、运行有效的党内法规体系。坚持立改废释并举，与时俱进做好党内法规制定修订工作，完善清理工作机制，加大解释力度，提高党内法规质量。健全党内法规备案审查制度，坚持有件必备、有备必审、有错必纠，维护党内法规体系统一性和权威性。注重党内法规同国家法律的衔接和协调，努力形成国家法律和党内法规相辅相成、相互促进、相互保障的格局。\n（二十二）抓好党内法规实施。把提高党内法规执行力摆在更加突出位置，把抓“关键少数”和管“绝大多数”统一起来，以各级领导机关和党员领导干部带头尊规学规守规用规，带动全党遵规守纪。加强学习教育，把重要党内法规列为党委（党组）理论学习中心组学习的重要内容，列为党校（行政学院）、干部学院重要教学内容，列入法治宣传教育规划重要任务。加大党内法规公开力度，提高党内法规的普及度和知晓率。落实党内法规执行责任制，做到有规必执、执规必严。开展党内法规实施评估工作，推动党内法规实施。强化监督检查和追责问责，将党内法规执行情况作为各级党委督促检查、巡视巡察重要内容，严肃查处违反党内法规的各种行为。\n（二十三）强化党内法规制度建设保障。加强党内法规专门工作队伍建设，突出政治标准，加强专业化建设，充实各级党内法规工作机构人员力量。加快补齐党内法规理论研究方面短板，重点建设一批党内法规研究高端智库和研究教育基地，推动形成一批高质量研究成果，引领和聚集一批党内法规研究人才。健全后备人才培养机制，继续推进在部分高校开展党内法规研究方向的研究生教育，加强学科建设，为党内法规事业持续发展提供人才支撑。","level":1},{"name":"八、紧紧围绕新时代党和国家工作大局，依法维护国家主权、安全、发展利益","text":"建设法治中国，必须高度重视依法保障“一国两制”实践、巩固和深化两岸关系和平发展，运用法治思维和法治方式处理好国际经济、政治、社会事务，深入推进依法治军从严治军，更好维护和实现我国和平发展的战略目标。\n（二十四）依法保障“一国两制”实践和推进祖国统一。坚持宪法的最高法律地位和最高法律效力，坚定不移并全面准确贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治的方针，坚持依法治港治澳，维护宪法和基本法确定的特别行政区宪制秩序，把维护中央对特别行政区全面管治权和保障特别行政区高度自治权有机统一起来，完善特别行政区同宪法和基本法实施相关的制度和机制。支持特别行政区行政长官和政府依法施政、积极作为，履行维护国家主权、安全、发展利益的宪制责任。健全落实特别行政区维护国家安全的法律制度和执行机制，确保“一国两制”行稳致远。防范和反对外部势力干预香港、澳门事务，保持香港、澳门长期繁荣稳定。\n探索“一国两制”台湾方案，推进祖国和平统一进程。推动两岸就和平发展达成制度性安排，完善促进两岸交流合作、深化两岸融合发展、保障台湾同胞福祉的制度安排和政策措施。支持两岸法学法律界交流交往。运用法治方式捍卫一个中国原则、坚决反对“台独”，坚定维护国家主权、安全、发展利益。\n依法保护港澳同胞、台湾同胞权益。全面推进内地同香港、澳门互利合作，完善便利香港、澳门居民在内地发展的政策措施。加强内地同香港和澳门、大陆同台湾的执法合作和司法协助，共同打击跨境违法犯罪活动。\n（二十五）加强涉外法治工作。适应高水平对外开放工作需要，完善涉外法律和规则体系，补齐短板，提高涉外工作法治化水平。\n积极参与国际规则制定，推动形成公正合理的国际规则体系。加快推进我国法域外适用的法律体系建设。围绕促进共建“一带一路”国际合作，推进国际商事法庭建设与完善。推动我国仲裁机构与共建“一带一路”国家仲裁机构合作建立联合仲裁机制。强化涉外法律服务，维护我国公民、法人在海外及外国公民、法人在我国的正当权益。建立涉外工作法务制度。引导对外经贸合作企业加强合规管理，提高法律风险防范意识。建立健全域外法律查明机制。推进对外法治宣传，讲好中国法治故事。加强国际法研究和运用。\n加强多双边法治对话，推进对外法治交流。深化国际司法交流合作。完善我国司法协助体制机制，推进引渡、遣返犯罪嫌疑人和被判刑人移管等司法协助领域国际合作。积极参与执法安全国际合作，共同打击暴力恐怖势力、民族分裂势力、宗教极端势力和贩毒走私、跨国有组织犯罪。加强反腐败国际合作，加大海外追逃追赃、遣返引渡力度。\n（二十六）深入推进依法治军从严治军。深入贯彻习近平强军思想，坚持党对人民军队绝对领导，全面深入贯彻军委主席负责制，围绕实现党在新时代的强军目标，加快构建完善的中国特色军事法治体系，推动治军方式根本性转变。\n加快推进改革急需、备战急用、官兵急盼重点立法项目。有力有序推进军事政策制度改革。完善军事立法计划管理制度。健全军事规范性文件审查和备案制度。完善军事法规制度定期清理机制。推动军事法制信息化建设，推进法规制度建设集成化、军事法规法典化。2020年年底前，完成国防和军队建设各系统各领域主干法规制度改革，构建起中国特色社会主义军事法规制度体系基本框架；到2022年，健全各领域配套法规制度，构建起比较完备的中国特色社会主义军事法规制度体系。\n明确军事法规执行责任和程序，落实执法责任制。强化官兵法治信仰和法治思维，深化法治军营创建活动。持续实施军事法治理论研究工程，组织编写全军统一的军事法治理论教材。加强军事法治国际交流，积极参与国际军事规则创制。综合运用党内监督、层级监督、专门监督等方式，构建常态化规范化军事法治监督体系。\n构建依法治军组织领导体系，成立军委依法治军组织领导机构及其办事机构。健全军事法制工作体制，建立和调整完善专门的军事法制工作机构。建立军事法律顾问制度。健全党领导军队政法工作机制，强化军委政法委功能作用。完善军事司法制度。\n九、加强党对法治中国建设的集中统一领导，充分发挥党总揽全局、协调各方的领导核心作用\n建设法治中国，必须始终把党的领导作为社会主义法治最根本的保证，把加强党的领导贯彻落实到全面依法治国全过程和各方面。\n（二十七）深入学习宣传贯彻习近平法治思想。习近平法治思想是全面依法治国的根本遵循和行动指南。要加强部署安排，持续推动广大干部群众深入学习贯彻习近平法治思想，深刻领会蕴含其中的马克思主义立场观点方法，全面准确把握精神实质、丰富内涵和核心要义，增强学习贯彻的自觉性和坚定性。各级党委（党组）理论学习中心组要将习近平法治思想作为重点内容，党校（行政学院）和干部学院要作为重点课程。各地区各部门要组织党员、干部进行系统学习和培训。法治工作部门要开展全战线、全覆盖的培训轮训。要把习近平法治思想融入学校教育，纳入高校法治理论教学体系，做好进教材、进课堂、进头脑工作。要开展深入研究和宣传，拓展学习宣传的广度深度。运用新媒体新技术，加强网上宣讲。\n（二十八）推进依法执政。健全党的全面领导制度。推进党的领导入法入规，着力实现党的领导制度化、法治化。完善党领导人大、政府、政协、监察机关、审判机关、检察机关、武装力量、人民团体、企事业单位、基层群众自治组织、社会组织等制度。将坚持党的全面领导的要求载入国家机构组织法，载入政协、民主党派、工商联、人民团体、国有企业、高等学校、有关社会组织等的章程。完善党委依法决策机制，健全议事规则和决策程序。\n建立领导干部应知应会法律法规清单制度，推动领导干部做尊法学法守法用法的模范。把法治素养和依法履职情况纳入考核评价干部的重要内容。各级领导干部要全面提高运用法治思维和法治方式深化改革、推动发展、化解矛盾、维护稳定、应对风险能力，绝不允许以言代法、以权压法、逐利违法、徇私枉法。\n（二十九）加强中国特色社会主义法治理论研究，加快中国特色社会主义法治体系建设。立足我国国情和实际，加强对社会主义法治建设的理论研究，尽快构建体现我国社会主义性质，具有鲜明中国特色、实践特色、时代特色的法治理论体系和话语体系。坚持和发展我国法律制度建设的显著优势，深入研究和总结我国法律制度体系建设的成功经验，推进中国特色社会主义法治体系创新发展。挖掘和传承中华优秀传统法律文化，研究、总结和提炼党领导人民推进法治建设实践和理论成果。组织和推动高等学校、科研院所以及法学专家学者加强中国特色社会主义法治理论研究，为建设法治中国提供学理支撑。\n（三十）加强党对全面依法治国的统一领导、统一部署、统筹协调。健全党领导立法、保证执法、支持司法、带头守法的制度机制。党政主要负责人要切实履行推进法治建设第一责任人职责，将履行推进法治建设第一责任人职责情况列入年终述职内容。各级党委要将法治建设与经济社会发展同部署、同推进、同督促、同考核、同奖惩。研究制定法治建设指标体系和考核标准。加强对重大法治问题的法治督察。\n中央全面依法治国委员会做好法治中国建设的顶层设计、总体布局、统筹协调、整体推进、督促落实，实现集中领导、高效决策、统一部署。地方各级党委法治建设议事协调机构要加强对本地区法治建设的牵头抓总、运筹谋划、督促落实等工作。\n各地区各部门要全面准确贯彻落实本规划精神和要求，结合实际制定实施方案，明确分工、压实责任，狠抓落实、务求实效，力戒形式主义、官僚主义。中央依法治国办要强化统筹协调，加强督办、推进落实，确保规划各项任务措施落到实处。\n延伸阅读\n新时代推进全面依法治国的纲领性文件——中央依法治国办负责同志就《法治中国建设规划（2020-2025年）》答记者问","level":1}]},{"id":"r0514","sections":[{"name":"深化农村改革综合性实施方案","text":"近日，中共中央办公厅、国务院办公厅印发了《深化农村改革综合性实施方案》，并发出通知，要求各地区各部门结合实际认真贯彻执行。","level":1},{"name":"","text":"《深化农村改革综合性实施方案》主要内容如下。\n农村改革是全面深化改革的重要内容。根据党中央、国务院的决策部署，农村各项改革正在扎实开展，一些重要改革事项试点工作正在有序推进。当前，我国经济发展进入新常态，新型工业化、信息化、城镇化、农业现代化持续推进，农村经济社会深刻变革，农村改革涉及的利益关系更加复杂、目标更加多元、影响因素更加多样、任务也更加艰巨。农村改革综合性强，靠单兵突进难以奏效，必须树立系统性思维，做好整体谋划和顶层设计，找准牵一发而动全身的牛鼻子和主要矛盾，进一步提高农村改革决策的科学性。要从总体上把握好农村改革的方向，提出深化农村改革总的目标、大的原则、基本任务、重要路径，从全局上更好地指导和协调农村各项改革，加强各项改革之间的衔接配套，最大限度释放改革的综合效应。\n根据中央统一部署，从提高农村改革的系统性、整体性、协同性出发，特制定深化农村改革综合性实施方案。","level":0},{"name":"一、总体要求","text":"（一）指导思想。全面贯彻党的十八大和十八届二中、三中、四中全会精神，以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神，认真落实党中央、国务院的决策部署，主动适应经济发展新常态，紧紧围绕全面建成小康社会、全面深化改革、全面依法治国、全面从严治党的战略布局，不断巩固和完善中国特色社会主义农村基本经济制度，加快农业发展方式转变，健全保障国家粮食安全、促进农业可持续发展和农民持续增收的体制机制，着力破除城乡二元结构的体制障碍，为加快推进中国特色农业农村现代化提供制度保障，为实现“两个一百年”奋斗目标和中华民族伟大复兴的中国梦奠定坚实基础。\n（二）目标任务。到2020年，农村各类所有制经济尤其是农村集体资产所有权、农户土地承包经营权和农民财产权的保护制度更加完善，新型农业经营体系、农业支持保护体系、农业社会化服务体系、农业科技创新体系、适合农业农村特点的农村金融体系更加健全，城乡经济社会发展一体化体制机制基本建立，农村社会治理体系和农村基层组织制度更加完善，农民民主权利得到更好保障，农业农村法律法规进一步完善并加强，农村基层法治水平进一步提高，农业现代化水平和农民生活水平进一步提升，农村经济社会发展更具活力。\n（三）基本原则\n1.坚持农村多种所有制经济共同发展。在坚持土地公有制性质基础上，加强对农村各种所有制经济组织和农民家庭合法财产权益的保护，赋予农村各种所有制经济组织同等的市场主体地位，保证其依法公平参与市场竞争、同等受到法律保护，促进农村集体经济、农户家庭经济、农民合作经济、各种私人和股份制经济、供销合作社经济以及国有农场林场等国有经济共同发展。\n2.坚持和完善农村基本经营制度。把握好土地集体所有制和家庭承包经营的关系，现有农村土地承包关系保持稳定并长久不变，落实集体所有权，稳定农户承包权，放活土地经营权，实行“三权分置”。坚持家庭经营在农业中的基础性地位，创新农业经营组织方式，推进家庭经营、集体经营、合作经营、企业经营等共同发展。\n3.坚持社会主义市场经济改革方向。调整不适应农村社会生产力发展要求的生产关系，健全符合社会主义市场经济要求的农村经济体制，充分发挥市场在资源配置中的决定性作用，加强国家对农业的支持保护，促进农业尽快转到数量质量效益并重、注重提高竞争力、注重农业技术创新、注重可持续的集约发展上来。\n4.坚持保障农民权益。把实现好、维护好、发展好广大农民的根本利益作为深化农村改革的出发点和落脚点，切实保障农民合法经济利益，尊重农民民主权利。\n5.坚持统筹兼顾。统筹考虑农业和农村发展，统筹考虑城乡改革发展，统筹考虑公平和效率。\n6.坚持循序渐进、试点先行。发挥好基层和群众首创精神，在把握方向、坚守底线前提下，鼓励积极探索、大胆创新，允许采取差异性、过渡性的制度和政策安排。认真组织好农村改革试点工作，及时总结可复制、可推广的经验。对突破现行法律法规的重大改革，要按程序报批，取得授权，在一定范围内开展试点。\n7.坚持党对“三农”工作的领导。必须始终把加强党对“三农”工作的领导作为推进农村改革发展的政治保证，提高依法做好“三农”工作的能力和水平。在中央的统一领导下，积极稳妥深化农村各项改革。","level":1},{"name":"二、关键领域和重大举措","text":"全面深化农村改革涉及经济、政治、文化、社会、生态文明和基层党建等领域，涉及农村多种所有制经济主体。当前和今后一个时期，深化农村改革要聚焦农村集体产权制度、农业经营制度、农业支持保护制度、城乡发展一体化体制机制和农村社会治理制度等5大领域。对这5大领域改革的核心问题，要明确大的方向、主要内容和重大方针对策，进一步理清改革思路。\n（一）深化农村集体产权制度改革\n以土地集体所有为基础的农村集体所有制，是社会主义公有制的重要形式，是实现农民共同富裕的制度保障。在土地集体所有基础上建立的农村集体经济组织制度，与村民自治组织制度相交织，构成了我国农村治理的基本框架，为中国特色农业农村现代化提供了基本的制度支撑。建立健全符合社会主义市场经济体制要求和社会主义初级阶段实际的农村集体产权制度，必须以保护农民集体经济组织成员权利为核心，以明晰农村集体产权归属、赋予农民更多财产权利为重点，探索社会主义市场经济条件下农村集体所有制经济的有效组织形式和经营方式，确保集体经济发展成果惠及本集体所有成员，进一步发挥集体经济优越性，进一步调动集体经济组织成员积极性。\n1.深化农村土地制度改革。坚守土地公有性质不改变、耕地红线不突破、农民利益不受损“三条底线”，防止犯颠覆性错误。深化农村土地制度改革的基本方向是：落实集体所有权，稳定农户承包权，放活土地经营权。落实集体所有权，就是落实“农民集体所有的不动产和动产，属于本集体成员集体所有”的法律规定，明确界定农民的集体成员权，明晰集体土地产权归属，实现集体产权主体清晰。稳定农户承包权，就是要依法公正地将集体土地的承包经营权落实到本集体组织的每个农户。放活土地经营权，就是允许承包农户将土地经营权依法自愿配置给有经营意愿和经营能力的主体，发展多种形式的适度规模经营。\n一是开展农村土地征收、集体经营性建设用地入市、宅基地制度改革试点。及时总结经验、不断完善，形成可复制、可推广的改革成果。农村土地征收制度改革的基本思路是：缩小土地征收范围，规范土地征收程序，完善对被征地农民合理、规范、多元保障机制，建立兼顾国家、集体、个人的土地增值收益分配机制，合理提高个人收益。集体经营性建设用地制度改革的基本思路是：允许土地利用总体规划和城乡规划确定为工矿仓储、商服等经营性用途的存量农村集体建设用地，与国有建设用地享有同等权利，在符合规划、用途管制和依法取得的前提下，可以出让、租赁、入股，完善入市交易规则、服务监管制度和土地增值收益的合理分配机制。宅基地制度改革的基本思路是：在保障农户依法取得的宅基地用益物权基础上，改革完善农村宅基地制度，探索农民住房保障新机制，对农民住房财产权作出明确界定，探索宅基地有偿使用制度和自愿有偿退出机制，探索农民住房财产权抵押、担保、转让的有效途径。\n二是深化农村土地承包经营制度改革。抓紧修改有关法律，落实中央关于稳定农村土地承包关系并保持长久不变的重大决策，适时就二轮承包期满后耕地延包办法、新的承包期限等内容提出具体方案。在基本完成农村集体土地所有权确权登记颁证的基础上，按照不动产统一登记原则，加快推进宅基地和集体建设用地使用权确权登记颁证工作。明确和提升农村土地承包经营权确权登记颁证的法律效力，扩大整省推进试点范围，总体上要确地到户，从严掌握确权确股不确地的范围。出台农村承包土地经营权抵押、担保试点指导意见。在有条件的地方开展农民土地承包经营权有偿退出试点。制定出台完善草原承包经营制度的文件，规范草原承包行为和管理方式，充分调动广大牧民保护和建设草原的积极性。引导农村集体所有的荒山、荒沟、荒丘、荒滩使用权有序流转。\n三是健全耕地保护和补偿制度。严格实施土地利用总体规划，加强耕地保护，全面开展永久基本农田划定工作，实行特殊保护。完善土地复垦制度，盘活土地存量，建立土地复垦激励约束机制，落实生产建设毁损耕地的复垦责任。加大中低产田改造力度，以增加高产稳产基本农田、改善农业生产条件和生态环境为目标，完善农村土地整治办法。依法加强耕地占补平衡规范管理，强化耕地占补平衡的法定责任，完善占补平衡补充耕地质量评价体系，确保补充耕地数量到位、质量到位。完善耕地和基本农田保护补偿机制。采取更有力的措施，加强对耕地占补平衡的监管，坚决防止占多补少、占优补劣、占水田补旱田现象，杜绝违规占用林地、湿地补充耕地。进一步落实耕地保护政府领导干部离任审计制度。按照有关法律法规，完善和拓展城乡建设用地增减挂钩、“地票”等试点，推动利用城乡建设用地增减挂钩政策支持易地扶贫搬迁。\n2.分类推进农村集体资产确权到户和股份合作制改革。在确认农村集体经济组织成员身份、全面核实农村集体资产基础上，对土地等资源性资产，重点是抓紧抓实土地承包经营权确权登记颁证工作；对非经营性资产，重点是探索有利于提高公共服务能力的集体统一运营管理有效机制；对经营性资产，重点是将资产折股量化到本集体经济组织成员，赋予农民对集体资产更多权能，发展多种形式的股份合作。健全农村集体“三资”管理监督和收益分配制度。明确集体经济组织市场主体地位。建立符合实际需求的农村产权流转交易市场，保障农村产权依法自愿公开公正有序交易。现阶段农村集体产权制度改革严格限定在本集体经济组织内部进行，切实防止集体经济组织内部少数人侵占、支配集体资产，防止外部资本侵吞、控制集体资产。\n3.深化林业和水利改革。实行最严格的林地用途管制制度。以放活经营权、落实处置权、保障收益权为重点，深化配套改革，完善集体林权制度。实行森林分类经营管理，完善林木采伐权，管好公益林、放活商品林，调动林农和社会力量发展林业的积极性。稳步推进国有林场和国有林区改革。研究提出加强天然林资源保护的指导意见，有序停止天然林商业性采伐。开展小型水利工程管理体制改革，明确工程所有权和使用权，落实管护主体，促进水利工程良性运行。\n（二）加快构建新型农业经营体系\n发展多种形式的农业适度规模经营是农业现代化的必由之路，必须以提高土地产出率、资源利用率、劳动生产率为核心，加快培育家庭农场、专业大户、农民合作社、农业产业化龙头企业等新型农业经营主体，构建符合国情和发展阶段的以农户家庭经营为基础、合作与联合为纽带、社会化服务为支撑的立体式、复合型现代农业经营体系，提高农业经营集约化、规模化、组织化、社会化、产业化水平。\n4.推动土地经营权规范有序流转。在农村耕地实行所有权、承包权、经营权“三权分置”的基础上，按照依法自愿有偿原则，引导农民以多种方式流转承包土地的经营权，以及通过土地经营权入股、托管等方式，发展多种形式的适度规模经营。把握好土地经营权流转、集中和规模经营的度，不片面追求超大规模经营，不搞大跃进，不搞强迫命令，不搞行政瞎指挥，使适度规模经营与农村劳动力转移、农业科技进步、农业社会化服务水平相适应。提升农户家庭经营能力和水平，重点发展以家庭成员为主要劳动力、以农业为主要收入来源、从事专业化集约化农业生产的规模适度的农户家庭农场，使之成为发展现代农业的有生力量。适时提出促进家庭农场发展的相关立法建议。\n5.加强农民合作社规范化建设。加强农民专业合作社和土地股份合作社规范化建设，深入推进示范社建设行动。鼓励农民合作社发展农产品加工业务，创新农业产业链组织形式和利益联接机制，构建农户、合作社、企业之间互利共赢的合作模式，让农民更多分享产业链增值收益。进一步创新财政支持农民合作社发展机制，允许政府项目直接投向符合条件的合作社。完善农民以承包土地经营权入股发展农业产业化经营的政策。\n6.创新农业社会化服务机制。家庭经营在相当时期内仍是农业生产的基本力量，要通过周到便利的社会化服务，把农户经营引入现代农业发展轨道。充分发挥农业公益性服务机构作用，大力培育多种形式的农业经营性服务组织，健全覆盖全程、综合配套、便捷高效的社会化服务体系。开展政府向农业经营性服务组织购买公益性服务机制创新试点。\n7.培养职业农民队伍。制定专门规划和切实可行的政策，吸引年轻人务农，培育新型职业农民，造就高素质的新型农业生产经营者队伍。扶持有技能和经营能力的农民工返乡创办家庭农场、领办农民合作社，创立农产品加工、营销企业和农业社会化服务组织。\n8.健全工商资本租赁农地的监管和风险防范机制。对工商资本租赁农户承包地作出明确规定，建立严格的资格审查、项目监管和定期督查机制，禁止以农业为名圈占土地从事非农建设，防止“非粮化”现象蔓延。鼓励和支持工商企业发展适合企业化经营的现代种养业、农产品加工流通和农业社会化服务，向农业输入现代生产要素和经营模式。探索建立工商资本农地租赁风险保障金制度。\n9.推进农垦改革发展和全面深化供销合作社综合改革。研究出台推进农垦改革发展的政策措施，深化垦区集团化、农场企业化改革，创新行业指导管理体制、企业市场化经营体制、农场经营管理体制，明晰农垦国有资产权属关系，建立符合农垦特点的国有资产监管体制，进一步推进农垦办社会职能改革。按照为农服务的宗旨和政事分开、社企分开的方向，因地制宜推进体制改革和机制创新，把供销合作社打造成为与农民利益联结更紧密、为农服务功能更完备、市场化运作更高效的合作经济组织体系，使之成为服务农民生产生活的生力军和综合平台。\n（三）健全农业支持保护制度\n对农业实行必要的支持保护是发展现代农业的客观需要，要坚持多予少取放活的基本方针，以保障主要农产品供给、促进农民增收、实现农业可持续发展为重点，加大农业支持保护力度，提高农业支持保护效能，完善农业生产激励机制，加快形成覆盖全面、指向明确、重点突出、措施配套、操作简便的农业支持保护制度。\n10.建立农业农村投入稳定增长机制。把农业农村作为财政支出的优先保障领域，中央预算内投资继续向农业农村倾斜，确保农业农村投入只增不减。进一步优化财政支农支出结构，转换财政资金投入方式，通过政府与社会资本合作、政府购买服务、担保贴息、以奖代补、民办公助、风险补偿等措施，带动金融和社会资本投向农业农村，发挥财政资金的引导和杠杆作用。大力清理、整合、规范涉农转移支付资金，对“小、散、乱”及效果不明显的涉农专项资金要坚决整治；对目标接近、投入方向类同的涉农专项资金予以整合；对地方具有管理信息优势的涉农支出，划入一般性转移支付切块下达，由地方统筹支配，落实监管责任。建立规范透明的管理制度，杜绝任何形式的挤占挪用、层层截留、虚报冒领，切实提高涉农资金投入绩效。合理划分中央与地方支农事权，明确政府间应承担和分担的支出责任，推进各级政府支农事权规范化、法律化。\n11.完善农产品价格形成机制和农产品市场调控制度。根据各类主要农产品在国计民生中的重要程度，采取“分品种施策、渐进式推进”的办法，完善农产品价格形成机制。改进并继续执行稻谷、小麦最低收购价政策。按照“价补分离”的思路，继续实施棉花和大豆目标价格改革试点，完善补贴发放办法。改革、完善玉米收储政策。改进农产品市场调控方式，避免政府过度干预，搞活市场流通，增强市场活力。完善农产品收储政策，坚持按贴近市场和保障农民合理收益的原则确定收储价格，降低储备成本，提高储备效率。加强粮食现代仓储物流设施建设，积极鼓励引导流通、加工等各类企业主体参与粮食仓容建设和农产品收储，规范收储行为，培育多元化市场主体。创新农产品流通方式，强化以信息化为支撑的农产品现代流通体系建设，大力发展农产品流通新型业态，发挥电子商务平台在联结农户和市场方面的作用。\n12.完善农业补贴制度。保持农业补贴政策连续性和稳定性，调整改进“黄箱”支持政策，逐步扩大“绿箱”支持政策实施规模和范围，提高农业补贴政策效能。开展农业补贴改革试点，将现行的“三项补贴”（农作物良种补贴、种粮直补、农资综合补贴）合并为“农业支持保护补贴”，优化补贴支持方向，突出耕地保护和粮食安全。保持与现有政策的衔接，调整部分存量资金和新增补贴资金向各类适度规模经营的新型农业经营主体倾斜，合理确定支持力度，不人为“垒大户”。进一步拓宽财政支农资金的渠道，突出财政对农业的支持重点，持续增加农业基础设施建设、农业综合开发投入，完善促进农业科技进步、加强农民技能培训的投入机制，强化对农业结构调整的支持，加大对农业投入品、农机具购置等的支持力度。健全粮食主产区利益补偿机制。健全快捷高效的补贴资金发放办法，鼓励有条件的地方探索对农民收入补贴的办法。\n13.建立农田水利建设管理新机制。积极推进农业水价综合改革，对农业用水实行总量控制和定额管理，配套完善供水计量设施，建立有利于节水的农业水价形成机制。建立农业用水精准补贴制度和节水激励机制。鼓励社会资本参与农田水利工程建设和运营维护。\n14.深化农业科技体制改革。坚持科技兴农、人才强农，推进农业科研院所改革，打破部门条块分割，有效整合科技资源，建立协同创新机制，促进产学研、农科教紧密结合。完善科研立项和成果转化评价机制，强化对科技人员的激励机制，促进农业科研成果转化。扶持种业发展，做强一批“育繁推”一体化的大型骨干种子企业。完善基层农技推广服务体系，探索公益性农技推广服务的多种实现形式。\n15.建立农业可持续发展机制。推广减量化和清洁化农业生产模式，健全农业标准化生产制度，完善农业投入品减量提效补偿机制。发展生态循环农业，构建农业废弃物资源化利用激励机制。实施耕地质量保护与提升行动，加强重金属污染耕地治理和东北黑土地保护。深入推进退耕还林还草、还湿还湖、限牧限渔。完善森林、草原、湿地、水源、水土保持等生态保护补偿制度。建立健全生态保护补偿资金稳定投入机制。\n16.加快农村金融制度创新。坚持商业性金融、合作性金融、政策性金融相结合，健全政策支持、公平准入和差异化监管制度，扩大农村金融服务规模和覆盖面，创新农村金融服务模式，全面提升农村金融服务水平，促进普惠金融发展，加快建立多层次、广覆盖、可持续、竞争适度、风险可控的现代农村金融体系。健全金融机构农村存款主要用于农业农村的制度，完善政策性金融支持农业开发和农村建设的制度。进一步完善中国农业银行“三农金融事业部”的管理体制和运行机制，全面提升服务“三农”和县域经济的能力和水平。稳定农村信用社县域法人地位，完善治理结构。鼓励邮政储蓄银行拓展农村金融业务。鼓励组建政府出资为主、重点开展涉农担保业务的县域融资担保机构或担保基金。完善农村信贷损失补偿机制，探索建立地方财政出资的涉农信贷风险补偿基金。稳妥开展农村承包土地的经营权和农民住房财产权抵押贷款试点，创新和完善林权抵押贷款机制，拓宽“三农”直接融资渠道。坚持社员制、封闭性原则，在不对外吸储放贷、不支付固定回报的前提下，以具备条件的农民合作社为依托，稳妥开展农民合作社内部资金互助试点，引导其向“生产经营合作+信用合作”延伸。金融监管部门负责制定农村信用合作组织业务经营规则和监管规则，地方政府切实承担监管职责和风险处置责任。完善地方农村金融管理体制，推动地方建立市场化风险补偿机制，有效防范和化解地方金融风险。推进农村信用体系建设，开展新型农业经营主体信用评级与授信。完善农业保险制度，支持有条件的地区成立农业互助保险组织，扩大农业保险覆盖面，开发适合新型农业经营主体需求的保险品种，提高保障水平。深入开展农产品目标价格保险试点。研究完善农业保险大灾风险分散机制。\n（四）健全城乡发展一体化体制机制\n城乡发展一体化是解决我国“三农”问题的根本途径，必须坚持工业反哺农业、城市支持农村的基本方针，协调推进城镇化和新农村建设，加快形成以工促农、以城带乡、工农互惠、城乡一体的新型工农城乡关系，努力缩小城乡发展差距。\n17.完善城乡发展一体化的规划体制。加快规划体制改革，构建适应我国城乡统筹发展的规划编制体系，完善各类规划编制、审批和实施监管制度，健全县市域空间规划衔接协调机制。尽快修订完善县域乡村建设规划和镇、乡、村庄规划，在乡镇土地利用总体规划控制下，探索编制村土地利用规划，提高规划科学性和前瞻性，强化规划约束力和引领作用。\n18.完善农村基础设施建设投入和建管机制。进一步加大公共财政对农村基础设施建设的投入力度。加快基础设施向农村延伸，探索建立城乡基础设施和公共服务设施互联互通、共建共享的机制。创新农村基础设施和公共服务设施决策、投入、建设和运行管护机制，建立自下而上的民主决策机制，通过村民自选、自建、自管、自用等方式，更好地发挥农民主体作用。积极引导社会资本参与农村公益性基础设施建设、管护和运营。\n19.推进形成城乡基本公共服务均等化的体制机制。完善县域城乡义务教育资源均衡配置的机制。建立城乡统筹的公共文化服务体系建设协调机制。建立覆盖城乡的基本医疗卫生制度，整合城乡居民基本医疗保险制度。健全全国统一的城乡居民基本养老保险制度，完善待遇确定和正常调整机制。推进最低生活保障制度城乡统筹发展。加强农村留守儿童、妇女、老人关爱服务体系建设。规范基本公共服务标准体系，促进城乡区域标准水平统一衔接可持续，完善综合监测评估制度。鼓励地方开展统筹城乡的基本公共服务制度改革试点。\n20.加快推进户籍制度改革。充分考虑各类城镇的经济社会发展水平、综合承载能力和提供基本公共服务能力，细化完善和实施差别化落户政策，促进有能力在城镇稳定就业和生活的常住人口有序实现市民化。加快建立和实施居住证制度，以居住证为载体，逐步实现基本公共服务对常住人口的全覆盖。构建政府、企业、个人共同参与的农业转移人口市民化成本分担机制，明确各级政府承担的相应支出责任，增强吸纳农业转移人口较多地区政府公共服务保障能力。切实维护进城落户农民的土地承包权、宅基地使用权、集体收益分配权。\n21.完善城乡劳动者平等就业制度。进一步清理针对农民工就业的歧视性规定，保障城乡劳动者平等就业的权利。加强覆盖城乡的公共就业创业服务体系建设。完善就业失业登记管理制度。落实鼓励农村劳动力创业政策。落实农民工与城镇职工同工同酬原则，突出解决好农民工工资拖欠问题。扩大农民工参加城镇社会保障覆盖面，把进城落户的农业转移人口完全纳入城镇社会保障体系。完善社会保障关系转移接续政策。\n（五）加强和创新农村社会治理\n随着市场化、工业化、城镇化的快速推进，农村社会治理面临新挑战，必须坚持党政主导、农民主体、社会协同，围绕提高农村基层治理水平，加强乡镇服务型政府建设，发挥好基层党组织在农村各类经济、社会组织中的领导核心作用，完善村民自治组织民主制度，形成规范有序、充满活力的乡村治理机制。\n22.加强农村基层党组织建设。认真贯彻党要管党、从严治党的要求，始终坚持农村基层党组织领导核心地位不动摇，深入整顿软弱涣散村党组织，把农村基层党组织建设成坚强的战斗堡垒，不断夯实党在农村基层执政的组织基础。创新完善农村基层党组织设置和活动方式，扩大组织覆盖和工作覆盖。加强乡村两级党组织班子建设，选好用好管好带头人，向软弱涣散村党组织和贫困村党组织选派第一书记。严肃农村基层党内政治生活，用严以修身、严以用权、严以律己和谋事要实、创业要实、做人要实的要求，加强党员日常教育管理，做好农村发展党员工作，发挥党员先锋模范作用。严肃处理违反党纪党规的行为，坚决查处挤占挪用惠农资金、侵占征地补偿款、侵吞集体资产等发生在农民身边的腐败行为，建立健全党组织领导下的村务监督机制，保持农村基层党组织的纯洁性和凝聚力。进一步加强农村基层服务型党组织建设，强化县乡村三级便民服务网络建设，多为群众办实事，贴近群众、团结群众、引导群众、赢得群众，带领群众共同脱贫致富奔小康。严格落实农村基层党建责任制，发挥县级党委“一线指挥部”作用，加大抓乡促村工作力度。\n23.健全农村基层民主管理制度。以扩大有序参与、推进信息公开、健全议事协商、强化权力监督为重点，健全村党组织领导的充满活力的村民自治机制，探索村民自治的有效实现形式。在有实际需要的地方，依托土地等集体资产所有权关系和乡村传统社会治理资源，开展以村民小组或自然村为基本单元的村民自治试点；在已经建立新型农村社区的地方，开展以农村社区为基本单元的村民自治试点。探索以村民会议、村民代表会议为载体，创新村民议事形式，完善议事决策主体和程序，落实群众知情权和决策权。建立务实管用的村务监督机制，理顺村务监督机构与其他村级组织的关系，切实发挥村务监督机构作用，落实群众监督权。积极探索村民议事会、村民理事会等协商形式，重视吸纳利益相关方、社会组织、驻村单位参加协商。研究明确村党组织、村民委员会、村务监督机构、农村集体经济组织的职能定位及相互关系。在进行农村集体产权制度改革、组建农村股份合作经济组织的地区，探索剥离村“两委”对集体资产经营管理的职能，开展实行“政经分开”试验，完善农村基层党组织领导的村民自治组织和集体经济组织运行机制。\n24.加强农村精神文明建设。加大农村思想道德建设力度，有针对性地开展社会主义核心价值观教育，提高农民综合素质，提升农村社会文明水平。开展文明村镇创建活动，修订乡规民约。充分发挥公共文化服务在农村精神文明建设中的平台和支撑作用，加强农村基层公共文化体育资源的整合利用，提高设施利用效能。建立广播电视村村通、文化信息资源共享、乡镇综合文化站、农村电影放映、农家书屋、体育健身等重点文化体育工程有效合作机制。采取政府购买、项目补贴、定向资助等方式，支持社会各类文化组织和机构参与农村公共文化服务。抓好农村业余文化骨干队伍建设，加强农村题材文艺作品的创作生产。保护和传承具有民族特色的农耕文明，加强农村地区的文化遗产保护。广泛开展具有乡土特色的文化活动，推动文化与特色农业有机结合，提升农产品文化附加值。引导和组织农民成立村民议事会、道德评议会、禁赌禁毒会、红白理事会，发挥乡规民约的积极作用。\n25.创新农村扶贫开发体制机制。着眼全面建成小康社会、不让农村贫困人口掉队的要求，分类施策，加快健全精准扶贫工作机制，完善贫困县考核机制，完善干部驻村帮扶机制，完善扶贫资金管理机制，完善金融服务机制，创新社会参与机制，建立扶贫对象动态调整机制，完善扶贫开发与农村低保有效衔接的机制。完善片区联系工作机制，推动片区规划实施与减少贫困人口的目标相结合，将政策、项目等落到实处。抓紧研究制定扶贫开发的重大举措，确保在既定时间节点打赢扶贫开发攻坚战，加快贫困群众脱贫致富、贫困地区全面建成小康社会步伐。\n26.深化农村行政执法体制改革。加强农村基层执法力量，推行对食品药品安全、工商质检、公共卫生、安全生产、文化旅游、资源环境、农林水利、交通运输、城乡建设、海洋渔业等领域的综合执法，确保有关法律法规执行，依法维护农村生产生活秩序，提高农村基层法治水平。","level":1},{"name":"三、（略）","text":"","level":1},{"name":"四、加强组织领导","text":"各级党委和政府要按照党中央、国务院的总体部署，切实增强领导、组织、监督农村改革工作的主动性和自觉性。要坚持问题导向，下大力气解决好农民群众最关心最直接最现实的利益问题。要完善各级党委和政府推进农村改革的领导体制和工作机制，健全和落实责任制度。主要负责同志要亲自抓农村改革工作，把握好方向和路径，加强对农村改革工作的指导，确保各项农村改革措施落到实处。\n延伸阅读\n新华社特约评论员：做好农村改革的整体谋划和顶层设计——一论学习贯彻《深化农村改革综合性实施方案》\n中财办副主任、中农办副主任：做好农村改革的整体谋划和顶层设计\n深化农村改革综合性实施方案解读①：实现农民共同富裕的制度保障","level":1}]},{"id":"r0515","sections":[{"name":"党史学习教育领导小组印发《关于〈“我为群众办实事”实践活动工作方案〉的通知》","text":"近日，党史学习教育领导小组印发《关于〈“我为群众办实事”实践活动工作方案〉的通知》，就开展“我为群众办实事”实践活动作出安排部署。","level":1},{"name":"","text":"《通知》指出，开展“我为群众办实事”实践活动，要以习近平新时代中国特色社会主义思想为指导，把学习党史同总结经验、观照现实、推动工作结合起来，弘扬党的光荣传统、优良作风，践行党的初心使命、根本宗旨，强化公仆意识、为民情怀，发挥基层党组织战斗堡垒作用、党员先锋模范作用和党员领导干部表率作用，结合各行各业实际，立足本职岗位为人民服务，从最困难的群众入手，从最突出的问题抓起，从最现实的利益出发，用心用情用力解决基层的困难事、群众的烦心事，增强人民群众的获得感幸福感安全感，激励全党全国各族人民以昂扬姿态奋力开启全面建设社会主义现代化国家新征程。\n《通知》强调，要聚焦聚力重点任务，着力贯彻新发展理念办实事，让群众分享高质量发展成果、共享高品质幸福生活；着力巩固拓展脱贫攻坚成果办实事，建设美丽宜人、业兴人和的社会主义新乡村；着力保障基层民生需求办实事，推动幼有所育、学有所教、劳有所得、病有所医、老有所养、住有所居、弱有所扶取得新进展；着力深化政务服务改革便民利民办实事，完善办事流程、规范审批行为、提高办事效率；着力推进基层治理体系和治理能力现代化办实事，将矛盾纠纷化解在基层，将和谐稳定创建在基层。\n《通知》强调，要把察民情访民意作为“我为群众办实事”的第一步，组织党员干部深入基层群众、深入生产一线、深入下属单位、深入工作服务对象，广泛听取意见、了解民生需求。要聚焦群众反映集中的共性需求和存在的普遍性问题，聚焦发展亟待解决的痛点难点问题，聚焦长期未能解决的民生历史遗留问题，研究提出和实施“我为群众办实事”重点项目。集中出台一批有利于巩固拓展脱贫攻坚成果、全面推进乡村振兴的政策举措，推出一批为民惠民便民的实招硬招，实施一批直接造福于民的项目工程，解决一批损害群众利益的矛盾纠纷。要深化岗位建功和志愿服务活动，带动社会力量和广大群众积极参与，提升数字化智能化服务水平，推动形成各级党组织聚焦聚力、广大党员积极行动、社会各界和人民群众踊跃参与的良好局面。\n《通知》要求，各级党组织要加强组织领导，研究确定重点民生项目清单，协调推进重点工作任务；要注重分类分层次实施，针对不同地区、不同领域、不同层级党组织分别提出要求；要加强宣传引导，深入报道党中央决策部署和工作要求，充分反映基层的经验做法和实际成效；要坚持从实际出发，尽力而为、量力而行，科学安排为群众办实事项目。要力戒形式主义、官僚主义，注意为基层减负，切实把好事办实，把实事办好，办到群众心坎上。\n党史学习教育专题","level":0}]},{"id":"r0516","sections":[{"name":"抗震救灾款物管理使用违法违纪行为处分规定","text":"为贯彻落实党中央、国务院抗震救灾的重大决策部署，加强对抗震救灾款物管理使用的监督，防止抗震救灾款物管理使用违法违纪行为的发生，严厉惩处违法违纪行为，保证抗震救灾款物及时用于灾民救助和群众基本生活，尽快恢复生产、重建家园，确保抗震救灾工作有力有序有效进行，根据《中国共产党纪律处分条例》等党内法规和《中华人民共和国防震减灾法》、《行政机关公务员处分条例》、《财政违法行为处罚处分条例》等国家法律法规，作如下规定。","level":1},{"name":"","text":"一、严格禁止并严肃查处以赈灾、募捐名义诈骗、敛取不义之财行为。\n有关机关、企业事业单位、社会团体、城乡基层群众自治组织开展抗震救灾款物的募集活动要严格按照有关规定进行，应当公开名称、地址、银行账号及接收捐赠情况，并将全部捐赠款物及时通过正规渠道送往灾区。对打着赈灾、募捐旗号，非法募捐，诈骗民众钱财，敛取不义之财的，党内给予开除党籍处分，行政给予开除处分。\n二、严格禁止并严肃查处截留、挤占或者无故迟滞拨付、发放抗震救灾款物行为。\n各地区各部门要加强协作、积极配合，提高抗震救灾款物运行效率和使用效益，不得截留、挤占或者无故迟滞拨付、发放抗震救灾款物。违反规定的，对有关责任人员党内给予严重警告或者撤销党内职务处分，行政给予记大过、降级或者撤职处分；情节严重的，党内给予留党察看或者开除党籍处分，行政给予开除处分。\n三、严格禁止并严肃查处虚报、冒领抗震救灾款物行为。\n各地区各部门应当如实上报人员伤亡、财产损失等受灾情况，不得虚报灾情或者骗取、冒领抗震救灾款物。违反规定的，对有关责任人员党内给予严重警告或者撤销党内职务处分，行政给予记大过、降级或者撤职处分；情节严重的，党内给予留党察看或者开除党籍处分，行政给予开除处分。\n四、严格禁止并严肃查处利用职权为自己、亲友和有关单位徇私发放或者有偿发放抗震救灾款物行为。\n各地区各部门在抗震救灾款物分配使用过程中，要规范管理，保证抗震救灾款物的分配使用公平、公正。不得利用职权为自己、亲友和有关单位徇私发放或者有偿发放抗震救灾款物。违反规定的，对有关责任人员党内给予严重警告或者撤销党内职务处分，行政给予记大过、降级或者撤职处分；情节严重的，党内给予留党察看或者开除党籍处分，行政给予开除处分。\n五、严格禁止并严肃查处擅自改变抗震救灾款物用途，挪作他用行为。\n各地区各部门应当坚持专款专用、专项专用、重点使用、合理分配，定向捐赠的抗震救灾款物要尊重捐赠人的意愿。不得向非灾区拨款；不得用于弥补救灾之外的其他社会救济费的不足；不得擅自扩大抗震救灾款物使用范围，用于地方其他事业费和任何行政经费开支。违反规定的，对有关责任人员党内给予警告、严重警告处分，行政给予记大过或者降级处分；情节严重的，党内给予撤销党内职务、留党察看或者开除党籍处分，行政给予撤职或者开除处分。\n挪用抗震救灾款物归个人使用的，党内给予撤销党内职务或者留党察看处分，行政给予降级或者撤职处分；情节严重的，党内给予开除党籍处分，行政给予开除处分。\n六、严格禁止并严肃查处擅自变卖抗震救灾物资行为。\n对灾区不适用的境内救灾捐赠物资，经捐赠人书面同意，报县级以上地方人民政府民政部门批准后可以变卖。对灾区不适用的境外救灾捐赠物资以及无法取得捐赠人同意的救灾捐赠物资，应当报省级人民政府民政部门批准后变卖。变卖救灾捐赠物资应当由县级以上地方人民政府民政部门依照有关规定统一组织实施。违反规定的，对有关责任人员党内给予警告或者严重警告处分，行政给予警告、记过或者记大过处分；情节严重的，党内给予撤销党内职务或者留党察看处分，行政给予降级或者撤职处分。\n变卖抗震救灾捐赠物资所得款项，应当作为抗震救灾捐赠款管理、使用。\n七、严格禁止并严肃查处故意违背政府应急救助和灾后重建规划使用抗震救灾款物行为。\n各地区各部门对抗震救灾款物要依法管理、合理安排、科学调度，按照政府应急救助和灾后重建规划使用抗震救灾款物。故意违反规定的，对有关责任人员党内给予警告、严重警告处分，行政给予记大过或者降级处分；情节严重的，党内给予撤销党内职务或者留党察看处分，行政给予撤职处分。\n八、严格禁止并严肃查处伪造、变造和毁损抗震救灾款物原始登记资料及相关账簿行为。\n各地区各部门应当按照规定设立抗震救灾款物账户和登记制度，做到账目清楚、手续完备。不得伪造、变造、私设抗震救灾款物会计账簿或者在非紧急情况下，不登记、不如实登记捐赠款物；不得违反规定填制、取得原始凭证；不得违反规定保管抗震救灾款物原始登记资料，致使其毁损、灭失。违反规定的，对有关责任人员党内给予警告、严重警告或者撤销党内职务处分，行政给予记大过、降级或者撤职处分；情节严重的，党内给予留党察看或者开除党籍处分，行政给予开除处分。\n故意毁损、灭失抗震救灾款物原始登记资料及相关账簿的，从重处分。\n九、严格禁止并严肃查处隐瞒抗震救灾款物管理使用分配信息，依照规定应当公开而不公开的行为。\n各地区各单位要主动公开抗震救灾款物的来源、数量、种类和去向。市、县两级要重点公开抗震救灾款物的管理、使用和分配情况。乡镇要重点公开抗震救灾款物的发放情况。村民委员会、居民委员会要公开发放的对象和原则；公开上级拨来的抗震救灾款物数量；公开得款户、得物户的名单和数量。违反规定的，对有关责任人员党内给予警告或者严重警告处分，行政给予警告、记过或者记大过处分；情节严重的，党内给予撤销党内职务或者留党察看处分，行政给予降级或者撤职处分。\n十、严肃查处在抗震救灾款物管理使用中玩忽职守、贻误工作行为。\n有关部门和人员在抗震救灾款物管理使用过程中，应当忠于职守、勤勉尽责，不得敷衍塞责、消极懈怠。对疏于管理，致使抗震救灾款物被贪污、挪用、毁损、灭失或者浪费严重的，对有关责任人员党内给予警告或者严重警告处分，行政给予警告、记过或者记大过处分；情节严重的，党内给予撤销党内职务、留党察看或者开除党籍处分，行政给予降级、撤职或者开除处分。\n对因失职渎职影响灾民生活或者造成其他严重后果的，加重或者从重处分。\n十一、严肃查处贪污、私分抗震救灾款物行为。\n经手管理使用抗震救灾款物应当手续完备、专款专用、专人负责、独立核算、账目清楚。对贪污抗震救灾款物的，党内给予撤销党内职务或者留党察看处分，行政给予降级或者撤职处分；情节严重的，党内给予开除党籍处分，行政给予开除处分。\n以集体名义将抗震救灾款物私分给个人的，对有关责任人员党内给予撤销党内职务或者留党察看处分，行政给予降级或者撤职处分；情节严重的，党内给予开除党籍处分，行政给予开除处分。\n少数人私分抗震救灾款物的，以贪污论。\n十二、有违反抗震救灾款物管理使用有关规定行为的单位，其负有责任的领导人员和直接责任人员，以及有违反抗震救灾款物管理使用有关规定行为的个人，应当承担纪律责任。属于下列人员，按照本规定给予党纪政纪处分：\n（一）党员；\n（二）行政机关公务员；\n（三）法律、法规授权的具有公共事务管理职能的组织中除工勤人员以外的工作人员；\n（四）行政机关依法委托的组织中除工勤人员以外的工作人员；\n（五）企业、事业单位、社会团体中由行政机关任命的人员；\n（六）村民委员会、居民委员会的组成人员。\n十三、对违反上述规定的单位和个人，要依法依纪从快、从严查处。涉嫌犯罪的，移送司法机关依法处理。对违反上述规定的案件隐瞒不报、压案不查、包庇袒护的，一经发现，严肃追究有关责任人员的责任。\n十四、本规定所称抗震救灾款物，是指各级财政投入、拨付的和社会捐赠的用于抗震救灾的资金、物资。\n十五、本规定自发布之日起施行。\n本规定发布前，有抗震救灾款物管理使用违法违纪行为，造成严重后果或者恶劣影响的，依照本规定处理。","level":0}]},{"id":"r0517","sections":[{"name":"关于加强金融服务民营企业的若干意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于加强金融服务民营企业的若干意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于加强金融服务民营企业的若干意见》全文如下。\n民营经济是社会主义市场经济的重要组成部分，在稳定增长、促进创新、增加就业、改善民生等方面发挥着不可替代的作用。党中央、国务院始终高度重视金融服务民营企业工作。各地区各部门及各金融机构认真落实，出台措施，积极支持民营企业融资，取得一定成效，但部分民营企业融资难融资贵问题仍然比较突出。为深入贯彻落实党中央、国务院决策部署，切实加强对民营企业的金融服务，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，落实中央经济工作会议和全国金融工作会议要求，坚持基本经济制度，坚持稳中求进工作总基调，围绕全面建成小康社会目标和高质量发展要求，毫不动摇地巩固和发展公有制经济，毫不动摇地鼓励、支持、引导非公有制经济发展，平等对待各类所有制企业，有效缓解民营企业融资难融资贵问题，增强微观主体活力，充分发挥民营企业对经济增长和创造就业的重要支撑作用，促进经济社会平稳健康发展。\n（二）基本原则\n——公平公正。坚持对各类所有制经济一视同仁，消除对民营经济的各种隐性壁垒，不断深化金融改革，完善金融服务体系，按照市场化、法治化原则，推动金融资源配置与民营经济在国民经济中发挥的作用更加匹配，保证各类所有制经济依法公平参与市场竞争。\n——聚焦难点。坚持问题导向，着力疏通货币政策传导机制，重点解决金融机构对民营企业“不敢贷、不愿贷、不能贷”问题，增强金融机构服务民营企业特别是小微企业的意识和能力，扩大对民营企业的有效金融供给，完善对民营企业的纾困政策措施，支持民营企业持续健康发展，促进实现“六稳”目标。\n——压实责任。金融管理部门要切实承担监督、指导责任，财政部门要充分发挥财税政策作用并履行好国有金融资本出资人职责，各相关部门要加强政策支持，督促和引导金融机构不断加强和改进对民营企业的金融服务。各省（自治区、直辖市）政府要认真落实属地管理责任，因地制宜采取措施，促进本地区金融服务民营企业水平进一步提升。金融机构要切实履行服务民营企业第一责任人的职责，让民营企业有实实在在的获得感。\n——标本兼治。在有效缓解当前融资痛点、堵点的同时，精准分析民营企业融资难融资贵背后的制度性、结构性原因，注重优化结构性制度安排，建立健全长效机制，持续提升金融服务民营企业质效。\n（三）主要目标。通过综合施策，实现各类所有制企业在融资方面得到平等待遇，确保对民营企业的金融服务得到切实改善，融资规模稳步扩大，融资效率明显提升，融资成本逐步下降并稳定在合理水平，民营企业特别是小微企业融资难融资贵问题得到有效缓解，充分激发民营经济的活力和创造力。","level":1},{"name":"二、加大金融政策支持力度，着力提升对民营企业金融服务的针对性和有效性","text":"（四）实施差别化货币信贷支持政策。合理调整商业银行宏观审慎评估参数，鼓励金融机构增加民营企业、小微企业信贷投放。完善普惠金融定向降准政策。增加再贷款和再贴现额度，把支农支小再贷款和再贴现政策覆盖到包括民营银行在内的符合条件的各类金融机构。加大对民营企业票据融资支持力度，简化贴现业务流程，提高贴现融资效率，及时办理再贴现。加快出台非存款类放贷组织条例。支持民营银行和其他地方法人银行等中小银行发展，加快建设与民营中小微企业需求相匹配的金融服务体系。深化联合授信试点，鼓励银行与民营企业构建中长期银企关系。\n（五）加大直接融资支持力度。积极支持符合条件的民营企业扩大直接融资。完善股票发行和再融资制度，加快民营企业首发上市和再融资审核进度。深化上市公司并购重组体制机制改革。结合民营企业合理诉求，研究扩大定向可转债适用范围和发行规模。扩大创新创业债试点，支持非上市、非挂牌民营企业发行私募可转债。抓紧推进在上海证券交易所设立科创板并试点注册制。稳步推进新三板发行与交易制度改革，促进新三板成为创新型民营中小微企业融资的重要平台。支持民营企业债券发行，鼓励金融机构加大民营企业债券投资力度。\n（六）提高金融机构服务实体经济能力。支持金融机构通过资本市场补充资本。加快商业银行资本补充债券工具创新，支持通过发行无固定期限资本债券、转股型二级资本债券等创新工具补充资本。从宏观审慎角度对商业银行储备资本等进行逆周期调节。把民营企业、小微企业融资服务质量和规模作为中小商业银行发行股票的重要考量因素。研究取消保险资金开展财务性股权投资行业范围限制，规范实施战略性股权投资。聚焦民营企业融资增信环节，提高信用保险和债券信用增进机构覆盖范围。引导和支持银行加快处置不良资产，将盘活资金重点投向民营企业。","level":1},{"name":"三、强化融资服务基础设施建设，着力破解民营企业信息不对称、信用不充分等问题","text":"（七）从战略高度抓紧抓好信息服务平台建设。依法开放相关信息资源，在确保信息安全前提下，推动数据共享。地方政府依托国家数据共享交换平台体系，抓紧构建完善金融、税务、市场监管、社保、海关、司法等大数据服务平台，实现跨层级跨部门跨地域互联互通。健全优化金融机构与民营企业信息对接机制，实现资金供需双方线上高效对接，让信息“多跑路”，让企业“少跑腿”。发展各类信用服务机构，鼓励信用服务产品开发和创新。支持征信机构、信用评级机构利用公共信息为民营企业提供信用产品及服务。加大守信激励和失信惩戒力度。\n（八）采取多种方式健全地方增信体系。发挥国家融资担保基金引领作用，推动各地政府性融资担保体系建设和业务合作。政府出资的融资担保机构应坚持准公共定位，不以营利为目的，逐步减少反担保等要求，对符合条件的可取消反担保。对民营企业和小微企业贷款规模增长快、户数占比高的商业银行，可提高风险分担比例和贷款合作额度。鼓励有条件的地方设立民营企业和小微企业贷款风险补偿专项资金、引导基金或信用保证基金，重点为首贷、转贷、续贷等提供增信服务。研究探索融资担保公司接入人民银行征信系统。\n（九）积极推动地方各类股权融资规范发展。积极培育投资于民营科创企业的天使投资、风险投资等早期投资力量，抓紧完善进一步支持创投基金发展的税收政策。规范发展区域性股权市场，构建多元融资、多层细分的股权融资市场。鼓励地方政府大力开展民营企业股权融资辅导培训。","level":1},{"name":"四、完善绩效考核和激励机制，着力疏通民营企业融资堵点","text":"（十）抓紧建立“敢贷、愿贷、能贷”长效机制。商业银行要推动基层分支机构下沉工作重心，提升服务民营企业的内生动力。尽快完善内部绩效考核机制，制定民营企业服务年度目标，加大正向激励力度。对服务民营企业的分支机构和相关人员，重点对其服务企业数量、信贷质量进行综合考核。建立健全尽职免责机制，提高不良贷款考核容忍度。设立内部问责申诉通道，为尽职免责提供机制保障。授信中不得附加以贷转存等任何不合理条件，对相关违规行为一经查实，严肃处理。严厉打击金融信贷领域强行返点等行为，对涉嫌违法犯罪的机构和个人，及时移送司法机关等有关机关依法查处。\n（十一）有效提高民营企业融资可获得性。新发放公司类贷款中，民营企业贷款比重应进一步提高。贷款审批中不得对民营企业设置歧视性要求，同等条件下民营企业与国有企业贷款利率和贷款条件保持一致。金融监管部门按法人机构实施差异化考核，形成贷款户数和金额并重的考核机制。发现数据造假的，依法严肃处理相关机构和责任人员。国有控股大型商业银行要主动作为，加强普惠金融事业部建设，落实普惠金融领域专门信贷政策，完善普惠金融业务专项评价机制和绩效考核制度，在提高民营企业融资可获得性和金融服务水平等方面积极发挥“头雁”作用。\n（十二）减轻对抵押担保的过度依赖。商业银行要坚持审核第一还款来源，把主业突出、财务稳健、大股东及实际控制人信用良好作为授信主要依据，合理提高信用贷款比重。商业银行要依托产业链核心企业信用、真实交易背景和物流、信息流、资金流闭环，为上下游企业提供无需抵押担保的订单融资、应收应付账款融资。\n（十三）提高贷款需求响应速度和审批时效。商业银行要积极运用金融科技支持风险评估与信贷决策，提高授信审批效率。对于贷款到期有续贷需求的，商业银行要提前主动对接。鼓励商业银行开展线上审批操作，各商业银行应结合自身实际，将一定额度信贷业务审批权下放至分支机构；确需集中审批的，要明确内部时限，提高时效。\n（十四）增强金融服务民营企业的可持续性。商业银行要遵循经济金融规律，依法合规审慎经营，科学设定信贷计划，不得组织运动式信贷投放。健全信用风险管控机制，不断提升数据治理、客户评级和贷款风险定价能力，强化贷款全生命周期的穿透式风险管理，在有效防范风险前提下加大对民营企业支持力度。加强享受优惠政策低成本资金使用管理，严格监控资金流向，防止被个别机构或个人截留、挪用甚至转手套利，有效防范道德风险。加强金融监管与指导，处理好支持民营企业发展与防范金融风险之间关系。","level":1},{"name":"五、积极支持民营企业融资纾困，着力化解流动性风险并切实维护企业合法权益","text":"（十五）从实际出发帮助遭遇风险事件的企业摆脱困境。加快实施民营企业债券融资支持工具和证券行业支持民营企业发展集合资产管理计划。研究支持民营企业股权融资，鼓励符合条件的私募基金管理人发起设立民营企业发展支持基金。支持资管产品、保险资金依法合规通过监管部门认可的私募股权基金等机构，参与化解处置民营上市公司股票质押风险。对暂时遇到困难的民营企业，金融机构要按照市场化、法治化原则，区别对待，分类采取支持处置措施。\n（十六）加快清理拖欠民营企业账款。坚持边界清晰、突出重点、源头治理、循序渐进，运用市场化、法治化手段，抓紧清理政府部门及其所属机构（包括所属事业单位）、大型国有企业（包括政府平台公司）因业务往来与民营企业形成的逾期欠款，确保民营企业有明显获得感。政府部门、大型国有企业特别是中央企业要做重合同、守信用的表率，认真组织清欠，依法依规及时支付各类应付未付账款。要加强政策支持，完善长效机制，严防新增拖欠，切实维护民营企业合法权益。\n（十七）企业要主动创造有利于融资的条件。民营企业要依法合规经营，珍惜商业信誉和信用记录。严格区分个人家庭收支与企业生产经营收支，规范会计核算制度，主动做好信息披露。加强自身财务约束，科学安排融资结构，规范关联交易管理。不逃废金融债务，为金融支持提供必要基础条件。\n（十八）加强对落地实施的监督检查。各地区各部门及各金融机构要树牢“四个意识”，坚定“四个自信”，坚决做到“两个维护”，坚持问题导向，明确责任，确定时限，狠抓落实。推动第三方机构开展金融服务民营企业政策落实情况评估，提高政策落实透明度。及时总结并向各地提供可复制易推广的成功案例和有效做法。对贯彻执行不力的，要依法依规予以严肃问责，确保各项政策落地落细落实。","level":1}]},{"id":"r0518","sections":[{"name":"中国共产党党校（行政学院）工作条例","text":"近日，中共中央印发了修订后的《中国共产党党校（行政学院）工作条例》（以下简称《条例》），并发出通知，要求各地区各部门认真遵照执行。\n通知指出，《条例》以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，进一步健全党校（行政学院）培训体系和工作机制，发挥党校（行政学院）教育培训干部和党员的主渠道、党的思想理论建设的重要阵地作用，对于坚持不懈用习近平新时代中国特色社会主义思想凝心铸魂，用党的创新理论武装全党，培养造就堪当民族复兴重任的执政骨干队伍，具有重要意义。\n通知要求，各级党委要认真落实办党校（行政学院）、管党校（行政学院）、建党校（行政学院）的主体责任，抓好《条例》学习宣传、贯彻落实和督促检查，确保党中央关于党校（行政学院）工作的决策部署落到实处。各级党校（行政学院）要认真贯彻落实《条例》，坚持党校姓党根本原则，自觉服务党和国家工作大局，更好为党育才、为党献策，推动新时代党校（行政学院）事业高质量发展。各地区各部门在执行《条例》中的重要情况和建议，要及时报告党中央。\n《条例》全文如下。\n中国共产党党校（行政学院）工作条例\n（2019年9月24日中共中央政治局会议审议批准 2019年10月25日中共中央发布 2025年7月10日中共中央政治局常委会会议修订 2025年8月3日中共中央发布）","level":1},{"name":"第一章 总则","text":"第一条 为了坚持和加强党对党校（行政学院）工作的全面领导，提高新时代党校（行政学院）工作科学化、制度化、规范化水平，根据《中国共产党章程》，制定本条例。\n第二条 党校（行政学院）是党领导的培养党的领导干部的学校，是党委的重要部门，是教育培训干部和党员的主渠道，是党的思想理论建设的重要阵地，是党和国家的哲学社会科学研究机构和重要智库。\n第三条 党校（行政学院）工作必须高举中国特色社会主义伟大旗帜，坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，落实新时代党的建设总要求，自觉服务党和国家工作大局，为党育才、为党献策，培养造就堪当民族复兴重任的执政骨干队伍，当好党的思想理论建设的生力军，为新时代坚持和发展中国特色社会主义，以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。\n第四条 党校（行政学院）工作遵循下列原则：\n（一）坚持党校姓党，把旗帜鲜明讲政治融入党校（行政学院）工作全过程各方面，牢牢把握正确办学方向；\n（二）坚持实事求是，注重理论联系实际，强化问题导向，做到学思用贯通、知信行统一；\n（三）坚持质量立校，积极探索和遵循党校（行政学院）教育规律、干部成长规律，提高教学、科研、决策咨询、人才培养引进、管理和服务水平；\n（四）坚持守正创新，继承和发扬办学治校的光荣传统，不断完善体制机制，增强办学活力；\n（五）坚持从严治校，大力弘扬学习之风、朴素之风、清朗之风；\n（六）坚持系统观念，注重统筹谋划、整合资源，不断增强工作的整体性和协同性。\n第五条 党校（行政学院）的基本任务是：\n（一）培训党政领导干部、公务员（含参照公务员法管理人员）、国有企业领导人员、事业单位领导人员、年轻干部、理论宣传骨干、高层次人才、基层干部、党员，开展党校（行政学院）师资培训；\n（二）加强马克思主义基本理论研究，重点研究宣传阐释习近平新时代中国特色社会主义思想；\n（三）承办党委和政府以及有关部门举办的专题研讨班；\n（四）开展重大理论和现实问题研究，为党委和政府提供决策咨询服务，为构建中国哲学社会科学自主知识体系贡献力量；\n（五）以培养马克思主义理论人才为主要目标，在国家批准的学科和专业学位类别内开展学位研究生教育；\n（六）开展同国（境）内外有关机构和组织的合作与交流；\n（七）参与党委关于党校（行政学院）工作政策以及干部培训计划的制定工作；\n（八）完成党委和政府交办的其他任务。\n第六条 党校（行政学院）对学员的教育培训目标是：\n（一）坚持对党忠诚，深刻领悟“两个确立”的决定性意义，坚决做到“两个维护”，锻造过硬党性，自觉在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致；\n（二）提升马克思主义理论水平和运用能力，学懂弄通做实习近平新时代中国特色社会主义思想，树立正确的世界观、人生观、价值观，不忘初心、牢记使命，做共产主义远大理想和中国特色社会主义共同理想的坚定信仰者和忠实实践者；\n（三）坚持以人民为中心，增强立党为公、执政为民的意识，践行全心全意为人民服务的根本宗旨，树立正确的权力观、政绩观、事业观；\n（四）敢于担当作为，勇于开拓创新，发扬斗争精神，增强斗争本领，善于分析解决改革发展稳定中的重大问题；\n（五）全面提高履职能力，增强适应新时代中国特色社会主义事业发展要求、推进中国式现代化建设的本领；\n（六）严格遵守党章党规党纪和宪法法律法规，知敬畏、存戒惧、守底线，坚决反对形式主义、官僚主义、享乐主义和奢靡之风，反对特权思想和特权现象，反对任何滥用职权、谋求私利的行为，永葆清正廉洁的政治本色。","level":1},{"name":"第二章 设置和体制","text":"第七条 党的中央委员会和地方各级委员会分别设立中央党校（国家行政学院）、省（自治区、直辖市）委党校（行政学院）、市（地、州、盟）委党校（行政学院）、县（市、区、旗）委党校（行政学校）。新疆生产建设兵团党委、各师（市）党委设立党校（行政学院）。有条件的乡镇（街道）党（工）委，可以设立党校。\n国家举办的普通高等学校党委应当设立党校。\n第八条 坚持全党办党校。各级党委是办党校（行政学院）、管党校（行政学院）、建党校（行政学院）的主体，党委书记是第一责任人，兼任党校（行政学院）校长（院长）的党委负责同志是主要责任人。党委应当加强对党校（行政学院）工作的领导：\n（一）把党校（行政学院）工作纳入党委整体工作部署，根据工作需要及时研究党校（行政学院）工作；\n（二）制定党的各级领导干部参加党校（行政学院）培训的规划和政策，把干部的培训和使用结合起来，将干部接受教育培训情况作为干部考核的内容和任职、晋升的重要依据；\n（三）选优配强党校（行政学院）领导班子，把优秀干部充实到班子中来；\n（四）建立健全党政领导干部到党校（行政学院）讲课、作报告和与学员座谈的制度，每学期领导干部讲课总课时占各级党校（行政学院）主体班次总课时的比例不低于20%；\n（五）加强党校（行政学院）人才培养、经费保障、基础设施建设等，支持党校（行政学院）实施综合性的教学、科研、决策咨询、管理和服务创新；\n（六）定期召开党校（行政学院）工作会议，总结经验，部署工作；\n（七）将党校（行政学院）工作纳入党委党的建设工作年度目标考核，列入落实党建工作责任制情况述职内容。\n第九条 党校（行政学院）实行校（院）务委员会〔以下简称校（院）委会〕领导体制。校（院）委会全面领导校（院）工作，委员由同级党委（政府）任命。校（院）委会工作由校长（院长）或者分管日常工作的副校长（副院长）主持。\n第十条 党校（行政学院）校长（院长）一般由同级党委书记、副书记或者组织部部长兼任。分管日常工作的副校长（副院长）按照同级党委部门正职领导干部选配并一般作为同级党委成员提名人选。主管教学、科研的副校长（副院长）一般应当具有教学、科研工作经历。\n第十一条 上级党校（行政学院）应当加强对下级党校（行政学院）的业务指导：\n（一）对下级党校（行政学院）贯彻落实党中央关于党校（行政学院）办学治校方针政策和重大决策部署的情况进行调研，提出指导性意见；\n（二）对下级党校（行政学院）教学、科研、师资培训等工作进行调研，提出改进意见和建议；\n（三）制定科学的办学质量评估指标体系和办法，指导下级党校（行政学院）开展评估工作；\n（四）市（地）级以上党校（行政学院）牵头制定本行政区域内党校（行政学院）业务工作规划；\n（五）中央党校（国家行政学院）和省（自治区、直辖市）委党校（行政学院）对下级党校（行政学院）的课程设置与开发、教材编写、学科建设、科研管理等工作进行指导和协调。\n第十二条 县级党校（行政学校）应当成为培训党的基层干部和普通党员的主渠道、主阵地。省（自治区、直辖市）党委应当统筹推进县级党校（行政学校）分类建设，深化办学体制改革和办学模式创新。\n整合县域教育培训资源，统筹用好党校（行政学院）资源，提升县级党校（行政学校）办学水平。基础薄弱、办学条件差的县级党校（行政学校），可以通过加挂市（地）级党校（行政学院）分校牌子等方式，多措并举开展办学。\n第十三条 党校（行政学院）应当加强对所设立分校的业务指导和工作统筹，帮助提高办学质量。\n第十四条 各级党校（行政学院）之间应当加强在教学、科研、决策咨询、管理和服务等方面的交流合作，建立资源共建共享机制，发挥整体优势。","level":1},{"name":"第三章 班次和学制","text":"第十五条 党校（行政学院）根据常态化培训特别是基本培训要求，开展好基本培训和其他重要培训。开展基本培训应当落实下列要求：\n（一）科学制定培训方案，明确培训的对象、内容、方式、学制、周期等关键要素；\n（二）坚持应训尽训，尽量扩大受益面，努力做到全覆盖，避免重复培训、多头调训和多年不训；\n（三）充分利用现代信息技术，运用线上线下、直播录播相结合等方式，推动优质培训资源向基层延伸；\n（四）坚持集中学习，有条件的党校（行政学院）应当做到集中住校培训，严格规范管理；\n（五）健全基本培训机制，持续提升各级党校（行政学院）教育培训质量。\n第十六条 党校（行政学院）根据常态化培训特别是基本培训对象设置培训班次和学制，主要开设进修班、培训班、专题研讨班、理论研修班和师资培训班等。\n第十七条 各级党校（行政学院）根据干部培训计划举办进修班。\n中央党校（国家行政学院）进修班主要培训中管干部、厅局级干部、县（市、区、旗）委书记等。主要开设中管干部进修班、厅局级干部进修班，学制一般不少于2个月；市（地）党政主要领导干部进修班、厅局级正职任职进修班、县委书记进修班，学制一般不少于3周。\n省（自治区、直辖市）委党校（行政学院）进修班主要培训厅局级干部、县处级干部、乡镇（街道）党（工）委书记等。主要开设厅局级干部进修班、县处级干部进修班，学制一般不少于1个月；厅局级副职任职进修班、县处级正职任职进修班、乡镇（街道）党（工）委书记进修班，学制一般不少于3周。\n市（地、州、盟）委党校（行政学院）进修班主要培训县处级干部、乡科级干部、乡镇长（街道办事处主任）等。主要开设县处级干部进修班、乡科级干部进修班，学制一般不少于1个月；县处级副职任职进修班、乡科级正职任职进修班、乡镇长（街道办事处主任）进修班，学制一般不少于2周。\n县（市、区、旗）委党校（行政学校）进修班主要培训乡科级干部、基层党组织负责人、党员等。主要开设乡科级干部进修班，学制一般不少于3周；乡科级副职任职进修班，学制一般不少于2周；基层党组织书记进修班，学制一般5天。有条件的还可以举办基层党组织班子成员进修班。培训党员的班次、学制由各地根据实际情况设置。\n第十八条 各级党校（行政学院）根据干部培训计划开设中青年干部培训班。\n中央党校（国家行政学院）主要培训厅局级和部分县处级正职中青年干部。学制一般不少于4个月。\n省（自治区、直辖市）委党校（行政学院）主要培训厅局级、县处级和部分乡科级正职中青年干部。学制一般不少于3个月。\n市（地、州、盟）委党校（行政学院）主要培训乡科级中青年干部。学制一般不少于2个月。\n县（市、区、旗）委党校（行政学校）主要培训基层中青年干部。学制一般不少于1个月。\n第十九条 围绕学习贯彻党的全国代表大会精神、中央全会精神和党中央有关决策部署，根据党委和政府的工作需要，在党校（行政学院）举办各类专题研讨班。学制一般为3－5天。\n第二十条 中央党校（国家行政学院）可以开设相应的民族干部班次。\n第二十一条 中央党校（国家行政学院）和省（自治区、直辖市）委党校（行政学院）可以举办主要以从事理论研究、宣传、教育工作的厅局级、县处级干部和哲学社会科学教研骨干为对象的理论研修班，以党校（行政学院）教学、科研和管理骨干为对象的师资培训班。\n第二十二条 各级党校（行政学院）根据公务员主管部门、事业单位人事综合管理部门等的培训规划和年度培训计划，举办相关培训。\n第二十三条 党校（行政学院）可以与有关单位联合举办视频培训班，合理配置和有效利用全国党校（行政学院）的培训资源。\n第二十四条 中央党校（国家行政学院）和具备条件的省（自治区、直辖市）委党校（行政学院），依法取得硕士、博士学位授予资格，并经国务院教育行政部门同意后，可以招收攻读硕士、博士学位的研究生，纳入国民教育体系管理。","level":1},{"name":"第四章 教学工作","text":"第二十五条 教学是党校（行政学院）的中心工作。党校（行政学院）教学布局应当坚持以学习习近平新时代中国特色社会主义思想为中心内容和首要任务，着眼于提高党的领导干部的政治觉悟、政治能力和执政本领，以掌握党的理论创新最新成果为重点夯实学员的理论基础，以坚定理想信念、增强宗旨观念和改进作风为重点加强学员的党性修养，以全面提高社会主义现代化建设能力为重点增长学员的履职本领。根据形势和任务的要求，不断充实和创新教学内容，优化党校（行政学院）教学布局，地方党校（行政学院）可以开设体现地方特色的教学课程。\n第二十六条 党校（行政学院）教学应当突出党的理论教育和党性教育的主业主课地位，加强履职能力培训。\n党的理论教育应当加强马克思主义理论教育培训，重点抓好用马克思主义中国化时代化最新成果统一思想、统一意志、统一行动，坚持不懈用习近平新时代中国特色社会主义思想凝心铸魂。\n党性教育应当深入开展理想信念、党的宗旨、党史、新中国史、改革开放史、社会主义发展史、革命传统、铸牢中华民族共同体意识和推进中华民族共同体建设、中华民族传统美德、正确政绩观、党风廉政等教育，把党章党规党纪学习教育作为党性教育的重要内容，运用典型案例开展警示教育。\n履职能力培训应当围绕党中央重大决策部署和国家重大战略需求开展，重点提升推动高质量发展本领、服务群众本领、防范化解风险本领。\n市（地）级以上党校（行政学院）总体教学安排中，党的理论教育和党性教育课程的比重不低于每学期总课时的70%。各级党校（行政学院）的主体班次都应当设置党性教育课程，党性教育课程的比重不低于每学期总课时的20%，1个月以上的班次应当安排学员进行党性分析。各级党校（行政学院）举办的党性教育培训班次中，课堂教学的比重不低于总课时的50%。\n第二十七条 党校（行政学院）应当不断提高教学质量，提升教学的政治水平、政策水平、学术水平、专业水平，增强针对性和实效性。\n第二十八条 党校（行政学院）应当努力创新教学方式，大力推行研究式教学，综合运用讲授式和研讨式、案例式、模拟式、体验式、访谈式等互动式教学方法，加大案例教学力度，推进案例库建设。加强网络培训平台建设，用好网络直播课堂、在线课堂等教学模式。省级以上党校（行政学院）应当有针对性地开发一批精品网络课程，推动优质资源直达基层。\n第二十九条 党校（行政学院）应当加强教学的组织管理，建立健全规章制度，形成职责明确、分工协作的教学实施和运行机制，建立和完善学习考核体系和教学效果评估体系。\n第三十条 学科建设是党校（行政学院）提高教学科研质量、提升师资水平的基本建设。党校（行政学院）应当重点建设以习近平新时代中国特色社会主义思想为主的马克思主义理论学科，加强中共党史党建学学科以及党性教育相关学科建设，积极扶持教学急需且相对薄弱学科，逐步形成突出党校（行政学院）特色、满足党员干部培训需要的学科体系。\n第三十一条 中央党校（国家行政学院）和省（自治区、直辖市）委党校（行政学院）应当制定学科建设规划。加强各级党校（行政学院）学科建设的协作，优化资源配置，推进学科建设。\n第三十二条 教材建设是教学的基础工程。党校（行政学院）应当根据教学需要组织编写充分体现马克思主义中国化时代化最新成果、具有党校（行政学院）特点的教学大纲和系列教材，建立与教育培训目标、教学布局相适应的党校（行政学院）教材体系。","level":1},{"name":"第五章 科研和决策咨询工作","text":"第三十三条 科研是党校（行政学院）的基础工作。党校（行政学院）科研工作应当密切关注国内外形势的发展变化，加强理论研究、对策研究，重点加强对习近平新时代中国特色社会主义思想的体系化、学理化研究阐释，加强重大现实问题研究，为提高教学质量服务，为推进党的理论创新服务，为党委和政府决策服务。\n第三十四条 中央党校（国家行政学院）习近平新时代中国特色社会主义思想研究中心和中国特色社会主义理论体系研究中心，经批准设立的地方党校（行政学院）习近平新时代中国特色社会主义思想研究基地和中国特色社会主义理论体系研究中心，应当在推进当代中国马克思主义、21世纪马克思主义的学习研究宣传阐释中走在前列。\n第三十五条 党校（行政学院）决策咨询工作应当聚焦党和国家中心工作、党委和政府重大决策部署、社会热点难点问题进行调查研究，及时反映重要思想理论动态，提出有价值的对策建议，推动教学、科研与决策咨询相互促进、协同发展，发挥好智库作用。\n第三十六条 党校（行政学院）科研和决策咨询工作应当全面贯彻党的基本理论、基本路线、基本方略，坚持政治立场坚定性和科学探索创新性的有机统一，严明政治纪律和政治规矩，恪守学术道德，加强科研诚信建设。党校（行政学院）应当制定体现党校（行政学院）特色的学术规范。\n第三十七条 党校（行政学院）应当加强有组织科研，创新管理服务工作，建立健全符合党校（行政学院）特点的管理体制和激励机制，鼓励教职工、学员参与决策咨询工作，统筹优化科研和决策咨询成果的考核和评价，推动决策咨询成果的转化应用。\n第三十八条 党校（行政学院）科研和决策咨询工作应当面向社会，加强与党委和政府部门、高等学校、科研院所等的合作交流。\n第三十九条 各级党校（行政学院）应当制定科研和决策咨询工作规划，并认真组织实施。\n第四十条 党校（行政学院）是党的意识形态工作的重要前沿阵地。应当坚持正确的政治方向、舆论导向、价值取向，创新思想文化宣传方式方法，用好图书、报刊、新媒体等传播媒介，积极发声、正确发声，切实发挥思想引领作用，当好党的创新理论的积极宣讲者、马克思主义在意识形态领域指导地位的坚定维护者、用党的意识形态引导社会思潮的可靠排头兵。","level":1},{"name":"第六章 开放办学","text":"第四十一条 开放办学是提高党校（行政学院）办学水平的重要途径。党校（行政学院）应当服从服务于党和国家对外工作大局，增强国家安全意识，遵循以我为主、为我所用、互学互鉴原则，统筹各方面资源，发展对外开放办学，在国际传播工作中积极发挥作用。\n第四十二条 党校（行政学院）以多种方式开展同国（境）外学术研究机构、智库、政党等的学术交流与合作，加强同发展中国家交流与合作，构建具有党校（行政学院）特色的治国理政经验交流、学术理论传播、文明交流互鉴和国际合作平台。\n第四十三条 党校（行政学院）通过选派教学、科研和管理人员等赴国（境）外学习、讲学、开展学术交流与合作，邀请国（境）外学者和知名人士到党校（行政学院）访问、讲学、开展学术交流与合作，举办或者参加国际会议、论坛等方式，加强对外合作交流。\n第四十四条 开展国际和港澳培训工作，创新培训机制和方式，完善培训课程体系，编制培训教材，提高培训实效。\n第四十五条 积极参与对外话语体系建设，注重用中国话语和中国叙事体系讲好中国故事、中国共产党故事，宣介好习近平新时代中国特色社会主义思想。组织开展国际传播知识培训，提高国际传播理论研究水平。","level":1},{"name":"第七章 学员管理","text":"第四十六条 学员管理是实现党校（行政学院）培养目标的重要环节。党校（行政学院）应当加强领导、强化培训、严格管理、注重实效，坚持从严要求，健全管理制度，改进管理方式，提高管理效果。\n第四十七条 学员管理包括党性教育、学习管理、组织管理和生活管理。党性教育应当贯穿学员管理全过程。学习管理应当加强导学、促学、督学，引导学员完成学习任务。组织管理应当严肃培训期间党内政治生活，完善并且严格学籍、考勤等制度，注重发挥学员临时党支部和班委会作用。生活管理应当严格执行校规校纪，开展健康文体活动。\n第四十八条 党校（行政学院）各个班次设专职组织员或者班主任，负责学员日常管理工作。组织员或者班主任由相应级别的干部担任。\n第四十九条 党校（行政学院）各个班次一般应当成立学员临时党支部。在校（院）委会领导下和学员管理部门指导下，组织学员开展政治学习，对学员进行教育、管理、监督和服务。\n第五十条 党校（行政学院）应当加强与党委组织部门、学员派出单位的协调配合，形成严格管理、有效监督的制度和机制。\n第五十一条 党校（行政学院）应当加强对学员培训情况的考核，全面考核评价学员的学习态度和表现，理论、知识掌握程度，党性修养、作风养成和遵规守纪情况以及解决实际问题的能力等。考核情况按照干部管理权限向组织人事部门反馈。\n学员在校期间违反有关规定和纪律的，由党校（行政学院）视情节轻重，商组织人事部门，给予约谈提醒、通报批评、责令退学等处理；情节严重的，由有关部门给予组织处理、党纪政务处分。\n第五十二条 党校（行政学院）应当严格执行学员请销假制度。学员在培训期间，一般不承担所在单位的日常工作、出国（境）考察等任务。因特殊情况确需请假的，必须严格履行手续，累计请假时间原则上不得超过总学时的1/7，超过的应予退学。\n第五十三条 党校（行政学院）学业证书是学员在校学绩的凭证。学员按照教学计划要求完成学习任务、经考核合格的，取得学业证书。因故未按照规定参加党校（行政学院）培训或者未达到培训要求的，应当及时补训。补训合格的，取得学业证书。","level":1},{"name":"第八章 队伍建设","text":"第五十四条 队伍建设是党校（行政学院）事业发展的关键。党校（行政学院）应当适应新时代干部教育培训要求，根据教学、科研、管理和服务工作的需要，统筹加强教师、管理和服务人员队伍建设，培养造就一批政治强、信念坚、业务精、作风正的高素质人才队伍。\n第五十五条 党校（行政学院）应当坚持人才强校战略，深入实施“名师工程”，突出抓好教师队伍建设。党校（行政学院）教师应当做到：\n（一）具有共产主义远大理想和中国特色社会主义坚定信念，忠诚于马克思主义，热爱党校（行政学院）事业，严格遵守政治纪律和政治规矩，增强党性修养，自觉在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致；\n（二）马克思主义理论功底扎实，熟悉党的路线方针政策，专业基础知识深厚，注重调查研究，勇于理论创新，坚持教研与实践相贯通，具有较强的教学、科研与决策咨询能力；\n（三）学风严谨，品德高尚，学为人师，行为世范，遵规守纪。\n第五十六条 按照专职为主、专兼结合的原则，加强党校（行政学院）教师队伍建设。专职教师占校（院）职工总数的比例一般不低于40%。加强对教师的马克思主义理论教育、党性教育和业务培训，完善教师知识更新、实践锻炼等机制，突出做好青年教师全链条培养；营造在教学方式方法和理论研究上积极探索、大胆创新的良好环境；主动引进政治素质好的高水平专家学者等；选聘思想政治素质过硬、实践经验丰富、理论水平较高、善于课堂讲授的领导干部、专家学者和先进模范人物、优秀基层干部按照规定担任兼职教师，建立健全兼职教师管理制度。\n第五十七条 建设既区别于公务员又不同于普通事业单位，符合党校（行政学院）发展特点的教师管理体系。突出政治素质考察考核，把政治要求贯穿党校（行政学院）教师管理始终。建立健全师资招聘、教师授课等方面的准入机制，建立健全符合干部教育培训特点、具有党校（行政学院）特色的教师考核评价体系、职称评审和岗位聘用制度、师资退出机制，有序推行教师竞聘上岗，形成有效的激励机制。党校（行政学院）教师纳入符合规定的有关人才政策支持范畴，享受国家规定的同级国民教育教师有关的各种待遇。落实事业单位绩效工资制度，建立健全与教学、科研等岗位职责目标相适应的党校（行政学院）工作人员绩效工资分配激励机制。\n第五十八条 各级党委应当支持和帮助党校（行政学院）做好优秀教师和管理人员选调工作，建立党校（行政学院）教师和管理人员内外交流制度。各级组织人事部门应当为党校（行政学院）输送和引进人才提供条件。","level":1},{"name":"第九章 校风、教风和学风建设","text":"第五十九条 良好的校风、教风和学风是党校（行政学院）事业健康发展的基本保证。党校（行政学院）应当坚持严以治校、严以治教、严以治学，把从严治校的要求贯彻到党校（行政学院）工作全过程各方面，不断健全各项管理制度，强化校规校纪，严格落实党中央关于党校（行政学院）办学治校的原则和要求，严格落实中央八项规定及其实施细则精神，严格落实意识形态工作责任制。\n第六十条 党校（行政学院）教师承担着教育培训领导干部和党员的重要责任，应当坚持教育者首先受教育，严格要求自己，坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护以习近平同志为核心的党中央权威和集中统一领导，弘扬教育家精神，自觉做到潜心治学、虔诚问道、悉心育人，用实际行动影响和带动学员。对师德师风不良或者不适宜从事党校（行政学院）工作的，调整工作岗位或者调离党校（行政学院）。\n第六十一条 弘扬理论联系实际的马克思主义学风，倡导崇尚学习、勤奋学习的风气。聚焦党和国家事业发展的重大理论和实践问题，鼓励教师与学员之间、学员相互之间切磋交流，实现教学相长、学学相长。","level":1},{"name":"第十章 机关党的建设","text":"第六十二条 党校（行政学院）建立机关基层党组织。机关基层党组织在上级党的机关工作委员会和校（院）委会领导下，以党的政治建设为统领，全面提高机关党的建设质量，推动实现党建工作与教学、科研等业务工作深度融合，为党校（行政学院）事业发展提供坚强保证。\n第六十三条 党校（行政学院）党的基层委员会和不设党的基层委员会的总支部委员会的书记应当由本单位党员负责人担任。党员人数和所属单位较多的机关党的基层委员会，设专职副书记。党支部书记原则上由本单位党员主要负责人担任。\n第六十四条 校（院）委会应当认真履行全面从严治党主体责任，主要负责人是机关党建工作第一责任人，各级党组织书记是机关党建工作直接责任人，其他班子成员落实“一岗双责”，抓好职责范围内的党建工作。","level":1},{"name":"第十一章 办学保障","text":"第六十五条 行政管理和后勤服务是党校（行政学院）各项工作运转的重要保障。党校（行政学院）应当按照管理科学化和服务规范化的要求深化改革创新，坚持勤俭办学、力戒铺张浪费，提高管理水平、服务质量和保障能力。\n第六十六条 党校（行政学院）工作所需必要经费，列入各级政府年度预算。做好基层干部教育培训经费保障，具备条件的地方党委可以使用留存的党费，对党校（行政学院）开展基层党员培训进行适当补充。\n第六十七条 各级党委和政府应当重视党校（行政学院）的教室、图书馆（室）、宿舍、食堂、信息化设施等干部教育培训必需的基础设施建设，按照实用、安全、有效、节约的原则改善办学条件。\n第六十八条 党校（行政学院）应当做好网络安全和信息化工作，提高教学、科研、管理和服务的数字化水平。\n第六十九条 党校（行政学院）应当加强图书馆（室）建设，做好纸质文献和数字资源的采集、整理、保护和开发，积极推进数字资源建设工作。\n第七十条 党校（行政学院）应当加强校（院）文化建设，用好红色资源，开展形式多样、具有党校（行政学院）特色、突出党性教育主题的文化活动。","level":1},{"name":"第十二章 执行与监督","text":"第七十一条 各级党委和政府以及有关部门、各级党校（行政学院）、学员所在单位和学员本人，应当严格执行和遵守本条例，自觉接受党内监督、社会监督和群众监督。\n第七十二条 各级党委应当对本条例执行情况进行监督检查。对于违反本条例的，依规依纪依法追究有关单位、人员的责任。","level":1},{"name":"第十三章 附则","text":"第七十三条 中央党校（国家行政学院）和地方党校（行政学院）设立的分校，按照本条例执行。党政部门、国有企业、普通高等学校、科研院所党组织设立的党校，参照本条例执行。具有党校（行政学院）性质的其他培训机构，可以参照本条例执行。\n第七十四条 本条例由中央党校（国家行政学院）负责解释。\n第七十五条 本条例自发布之日起施行。\n延伸阅读\n为新时代党校（行政学院）事业高质量发展提供制度保障——中央党校（国家行政学院）负责人就修订颁布《中国共产党党校（行政学院）工作条例》答记者问","level":1}]},{"id":"r0519","sections":[{"name":"新录用公务员任职定级规定","text":"第一条 为了合理确定新录用公务员职务和级别，规范新录用公务员任职定级工作，根据公务员法和相关法规，制定本规定。","level":1},{"name":"","text":"第二条 新录用公务员任职定级，应当在规定的机构规格、编制、职数限额以及主任科员以下及其他相当职务层次的非领导职务范围内，按照拟任职务及其对应的级别进行。\n第三条 新录用公务员试用期满三十日内，应根据拟任职务的要求，按照公务员的条件、义务和纪律要求，对新录用公务员进行任职考核。\n第四条 考核合格的新录用公务员，按以下规定任职定级：\n（一）直接从各类学校毕业生中录用的、没有工作经历的公务员：高中和中专毕业生，任命为办事员，定为二十七级；大学专科毕业生，任命为科员，定为二十六级；大学本科毕业生、获得双学士学位的大学本科毕业生（含学制为六年以上的大学本科毕业生）、研究生班毕业和未获得硕士学位的研究生，任命为科员，定为二十五级；获得硕士学位的研究生，任命为副主任科员，定为二十四级；获得博士学位的研究生，任命为主任科员，定为二十二级。\n（二）其他新录用的公务员：原具有公务员身份的，可参考其原任职务与级别，比照本机关同等条件人员，确定职务与级别。其他具有工作经历的，可根据其资历和工龄，比照本机关同等条件人员，确定职务与级别。\n新录用公务员任职时间从试用期满之日起计算。\n第五条 新录用公务员任职定级，按以下程序进行：\n（一）本人对试用期间的德、能、勤、绩、廉情况进行总结。\n（二）所在机关对拟任职定级人员进行全面考核，提出拟任职务和拟定级别的意见。\n（三）任免机关审批，下发新录用公务员任职定级决定。\n新录用公务员任职定级后，按照有关规定进行公务员登记。\n第六条 新录用公务员在机关最低服务年限为五年（含试用期）。\n第七条 对有下列违反本规定情形的，由县级以上领导机关或者公务员主管部门按照管理权限，区别不同情况，分别予以责令纠正或者宣布无效；对负有责任的领导人员和直接责任人员，根据情节轻重作出处理：\n（一）突破机构规格、超职数进行新录用公务员任职定级的；\n（二）不按规定条件、程序进行新录用公务员任职定级的；\n（三）把试用期计入任职年限的；\n（四）违反法律、法规规定的其他情形。\n第八条 本规定适用于综合管理类新录用公务员的任职定级。\n在国家有关规定出台前，其他类别新录用公务员的任职定级，按照本规定办理。\n第九条 参照公务员法管理的机关（单位）中除工勤人员以外的新录用人员的任职定级工作，参照本规定执行。\n第十条 本规定由中共中央组织部、人力资源和社会保障部负责解释。\n第十一条 本规定自发布之日起施行。1997年3月28日发布的《新录用国家公务员任职定级暂行规定》同时废止。","level":0}]},{"id":"r0520","sections":[{"name":"中共中央办公厅 国务院办公厅关于健全社会信用体系的意见","text":"中共中央办公厅 国务院办公厅关于健全社会信用体系的意见\n（2025年3月21日）","level":1},{"name":"","text":"社会信用制度是市场经济基础制度。为健全社会信用体系，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，坚持和加强党的领导，坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，坚持政府引导、市场驱动、社会共建，坚持弘扬诚信文化，坚持公共信用信息和市场信用信息相互融合，坚持信用奖惩合理合法，构建覆盖各类主体、制度规则统一、共建共享共用的社会信用体系，推动社会信用体系与经济社会发展各方面各环节深度融合，为加快建设全国统一大市场、维护公平有序竞争市场秩序、推动高质量发展提供有力支撑。","level":1},{"name":"二、构建覆盖各类主体的社会信用体系","text":"（一）深化政务信用建设。健全政府诚信履约机制，开展政务诚信评价，完善政府失信行为认定标准和失信惩戒措施，政府及其部门（含下属单位）在公共资源交易、招商引资、人才引进、政府与社会资本合作、产业扶持、投资融资、涉企收费等领域出现失信行为的，按规定将其纳入信用记录，限制其申请各类财政性资金和项目、试点示范、评先评优。有效发挥事业单位异常名录作用，提升事业单位诚信自律水平。加强公职人员诚信管理和教育。\n（二）加强经营主体信用建设。强化经营主体信用管理，支持经营主体完善合规经营制度、管控信用风险，引导经营主体诚信经营、守信践诺。以公共信用综合评价为基础，建立企业信用状况综合评价体系。在确保保密和敏感信息安全前提下，加强国有企业信用状况披露。鼓励经营主体主动向信用服务机构提供信用信息，不断健全信用记录。\n（三）加快社会组织信用建设。加强社会组织信用信息管理、共享、公开，强化社会组织信用监管，引导社会组织诚信自律，提升内部治理水平。行业主管部门和业务主管单位要推动行业协会商会加强诚信建设，指导行业协会商会依法依规开展信用评价等活动，发挥其对成员的行为导引、规则约束、权益维护等作用。\n（四）有序推进自然人信用建设。依法依规建立健全自然人信用记录。加快推进法律、金融、会计、审计、医疗、教育、家政、工程建设、生态环境、平台经济等领域从业人员和取得国家职业资格人员等重点职业人群的信用管理制度建设。有条件的地方和部门可以开展自然人信用评价，用作为守信主体提供激励政策的参考，严禁将非信用信息和个人私密信息纳入信用评价。\n（五）全面强化司法执法体系信用建设。加强法院、检察院司法公信建设，提高司法公信力。依法加大司法公开力度，保障人民群众知情权。加强司法执法人员信用建设，建立执法人员信用记录和信用承诺制度。提高虚假诉讼违法失信成本。严格失信被执行人认定程序，优化相关失信惩戒措施。","level":1},{"name":"三、夯实社会信用体系数据基础","text":"（六）建立全面完整准确的信用记录。严格界定公共信用信息范围，行业主管部门要根据法律、行政法规、地方性法规或党中央、国务院政策性文件确定本领域公共信用信息并形成行业信用记录，其中属于失信信息的，要分类明确其失信严重程度。对公共信用信息统一实行目录管理，国家发展改革委汇总建立相关主体的完整信用记录。\n（七）强化信用信息归集共享。强化全国信用信息共享平台信用信息归集共享“总枢纽”功能，坚持以共享为原则、不共享为例外，统一归集各领域信用信息，根据需求按规定向有关部门提供信用信息服务，定期开展归集共享质效评估。推动全国信用信息共享平台与行业信用信息系统深度联通、数据共享。研究加强区块链等技术在信用信息管理等方面的应用，在保障信用主体合法权益和信息安全的前提下，提升商业合同信息、产业链信息、交易信息等共享水平。\n（八）建立公共信用信息统一公示制度。建立统一的公共信用信息公示标准规则。“信用中国”网站集中公示各类公共信用信息，行业主管部门原则上不再公示本部门业务领域之外的公共信用信息。“信用中国”网站按照公益性原则向社会公众提供公共信用信息查询服务。对已在“信用中国”网站公示的公共信用信息，信用服务机构应当确保使用的信用信息与公示内容相同、期限一致。\n（九）有序推动公共信用信息开放流通。制定公共信用信息授权运营管理办法，支持符合条件的运营机构依授权开展公共信用信息资源开发、产品经营和技术服务，严禁未经授权、超范围使用公共信用信息。建立公共信用信息流通准入标准规则。鼓励经营主体依法依规依托公共信用信息提供公益服务。探索建立公共信用信息价值收益合理分享机制，依法依规维护公共信用信息资产权益。鼓励区域间公共信用信息共享、信用评价互认、信用奖惩协同。\n（十）加强信用信息安全保护。建立信用信息安全管理追溯和侵权责任追究机制，明确信息传输链条各环节安全责任。严格落实安全保护责任，规范信用信息处理程序。提高信用信息基础设施安全管理水平。建立健全信用信息安全应急处理机制。","level":1},{"name":"四、健全守信激励和失信惩戒机制","text":"（十一）强化对守信行为的激励。构建全方位的信用激励政策环境，为守信主体在公共服务中提供便利或优惠。鼓励平台企业用好大数据资源，为守信主体精准提供市场化、社会化激励。支持金融机构深入挖掘信用信息价值，持续提升守信主体融资便利化水平。\n（十二）依法依规开展失信惩戒。规范设定失信惩戒措施，依法依规合理确定惩戒范围和力度。设定失信惩戒措施、确定严重失信主体名单的设列领域必须以法律、行政法规、地方性法规或党中央、国务院政策性文件为依据，其中涉及设定对信用主体减损权利或增加义务的措施，必须以法律、行政法规、地方性法规为依据。行业主管部门应当以部门规章形式明确严重失信主体名单列入和退出的条件、程序。对被列入严重失信主体名单的，在申请政府资金、享受税收优惠、参与公共资源交易活动、股票债券发行、评先评优、公务员录用遴选调任聘任、事业单位公开招聘等方面，依法依规予以限制或禁止。在房地产市场、互联网、人力资源市场、能源中长期合同领域增设严重失信主体名单。对失信惩戒措施和严重失信主体名单实行清单化统一管理。\n（十三）完善统一的信用修复制度。建立健全统一规范、协同共享、科学高效的信用修复制度，鼓励失信主体主动纠正失信行为。国家发展改革委牵头统一信用信息公示和修复的渠道，优化信用修复规则，加强司法机关、行业主管部门、信用服务机构等修复协同。对完成修复的信用主体，应当及时停止公示其失信信息、将其移出相关失信名单，并依法依规解除相关失信惩戒措施。","level":1},{"name":"五、健全以信用为基础的监管和治理机制","text":"（十四）以信用评价为基础实施分级分类监管。国家发展改革委牵头完善信用评价体系，各地区各行业主管部门以公共信用综合评价为基础健全本地区本行业信用评价机制，根据评价结果优化监管方式，对不同类型信用主体实施差异化监管。\n（十五）建立健全信用承诺制。在行政审批、证明事项、信用修复等领域推行信用承诺制。办理适用信用承诺制的事项时，申请人部分申报材料不齐备但信用状况较好且书面承诺在规定期限内提供材料的，应先行受理。建立信用承诺践诺跟踪机制。引导信用主体主动向社会作出信用承诺。\n（十六）推进信用报告深度应用。推动在市场准入、行政审批、政府采购、招商引资、资质审核等公共管理领域充分使用信用报告。大力推行以专项信用报告替代有无违法违规记录的证明。鼓励在招标投标、融资授信、商业往来等市场交易活动中使用信用报告。\n（十七）加强对政府签订、指导签订合同等履约信用监管。强化合同履约跟踪核实，及时将政府签订的合同、政府指导签订的合同等履约情况归集至全国信用信息共享平台，国家发展改革委将经核实的合同履约情况纳入相关主体信用记录，切实提高合同履约水平。\n（十八）推动信用赋能基层治理。加强农村信用体系建设，加强涉农信用信息归集共享，明确采集责任，优化精简采集指标和评价规则，提升对农户和新型农业经营主体的信用评价水平。推动信用赋能社区治理，支持信用园区、街区建设。\n（十九）完善社会信用体系法律法规制度。完善统一社会信用代码制度，进一步明确各类主体的赋码部门，健全赋码数据共享与校核机制。制定全国统一的信用信息管理标准。推动出台社会信用建设法，推动将信用规则纳入相关专项法律法规。加强信用政策出台前的综合评估，防止信用管理措施泛化滥用。","level":1},{"name":"六、提高社会信用体系市场化社会化水平","text":"（二十）大力培育信用服务市场。创新信用评价、信用评级、信用评分、信用报告、信用核查、信用管理、信用咨询以及环境、社会和治理评价等业务模式，有效支撑信用经济发展。规范信用服务机构参与社会信用体系建设行为。支持金融信用信息基础数据库依法采集金融领域信用信息，提供更加便捷优质的基础征信服务。优化个人征信市场布局，增加个人征信产品和服务供给。做优做精企业征信市场，探索发展聚焦细分领域的企业征信机构。全面加强征信监管，促进征信行业规范健康发展。\n（二十一）深入推进信用融资和信用交易。依托全国一体化融资信用服务平台网络，按照实际应用需求扩大信用信息归集共享范围，完善以信用信息为基础的企业融资增信制度，有效提升中小微企业信用贷款比重，支持符合条件的征信机构参与融资信用服务平台运营。鼓励信用服务机构依法依规采集商业合同履约信息，支持有序推广赊销、分期付款、融资租赁等信用销售模式。强化商业汇票信息披露，完善票据市场信用约束机制。将恶意逃废债经营主体依法依规纳入相关严重失信主体名单。\n（二十二）加强平台经济领域信用建设。加强公共信用信息和平台企业经营信息的共享，引导平台企业建立平台内信用管理制度和平台间失信联合约束制度，根据平台内商户信用状况实施差别化的管理和服务，为守法诚信经营主体提供更多优惠便利，对违法失信经营主体在平台规则内予以限制。加强对网络主播、自媒体、网络信息内容多渠道分发服务机构（MCN机构）等信用监管。\n（二十三）服务高水平对外开放。在确保安全的前提下，依法依规推进信用信息数据跨境流通，有序开展跨境信用合作，推动信用评价、信用报告等信用产品跨境互认。支持国内信用服务机构与共建“一带一路”国家、金砖国家开展独立、公正的第三方信用服务合作。加强国际征信交流，积极培育具有国际竞争力和影响力的征信机构。推动国内信用评级机构国际化发展。","level":1},{"name":"七、加强组织实施","text":"各地区各有关部门要在党中央集中统一领导下，结合实际抓好本意见贯彻落实，形成上下联动、各司其职、齐抓共管的工作格局。国家发展改革委、中国人民银行要加强统筹协调，各有关部门要切实履行本领域信用建设责任，形成工作合力。统筹做好全国社会信用体系建设示范区创建工作，建立健全示范区后评价机制。持续开展城市信用监测。弘扬诚信文化，普及诚信教育，依法依规加大对严重失信行为的曝光力度，支持新闻媒体开展诚信宣传和舆论监督。充分发挥诚信典型的引领作用，持续开展“诚信之星”宣传和“诚信兴商宣传月”活动，推动形成守信践诺的良好社会风尚。及时总结推广典型经验做法。重大事项及时按程序向党中央、国务院请示报告。","level":1}]},{"id":"r0521","sections":[{"name":"关于完善农村土地所有权承包权经营权分置办法的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于完善农村土地所有权承包权经营权分置办法的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于完善农村土地所有权承包权经营权分置办法的意见》主要内容如下。\n为进一步健全农村土地产权制度，推动新型工业化、信息化、城镇化、农业现代化同步发展，现就完善农村土地所有权、承包权、经营权分置（以下简称“三权分置”）办法提出以下意见。","level":0},{"name":"一、重要意义","text":"改革开放之初，在农村实行家庭联产承包责任制，将土地所有权和承包经营权分设，所有权归集体，承包经营权归农户，极大地调动了亿万农民积极性，有效解决了温饱问题，农村改革取得重大成果。现阶段深化农村土地制度改革，顺应农民保留土地承包权、流转土地经营权的意愿，将土地承包经营权分为承包权和经营权，实行所有权、承包权、经营权（以下简称“三权”）分置并行，着力推进农业现代化，是继家庭联产承包责任制后农村改革又一重大制度创新。“三权分置”是农村基本经营制度的自我完善，符合生产关系适应生产力发展的客观规律，展现了农村基本经营制度的持久活力，有利于明晰土地产权关系，更好地维护农民集体、承包农户、经营主体的权益；有利于促进土地资源合理利用，构建新型农业经营体系，发展多种形式适度规模经营，提高土地产出率、劳动生产率和资源利用率，推动现代农业发展。各地区各有关部门要充分认识“三权分置”的重要意义，妥善处理“三权”的相互关系，正确运用“三权分置”理论指导改革实践，不断探索和丰富“三权分置”的具体实现形式。","level":1},{"name":"二、总体要求","text":"（一）指导思想。全面贯彻党的十八大和十八届三中、四中、五中全会精神，深入学习贯彻习近平总书记系列重要讲话精神，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，牢固树立新发展理念，认真落实党中央、国务院决策部署，围绕正确处理农民和土地关系这一改革主线，科学界定“三权”内涵、权利边界及相互关系，逐步建立规范高效的“三权”运行机制，不断健全归属清晰、权能完整、流转顺畅、保护严格的农村土地产权制度，优化土地资源配置，培育新型经营主体，促进适度规模经营发展，进一步巩固和完善农村基本经营制度，为发展现代农业、增加农民收入、建设社会主义新农村提供坚实保障。\n（二）基本原则\n——尊重农民意愿。坚持农民主体地位，维护农民合法权益，把选择权交给农民，发挥其主动性和创造性，加强示范引导，不搞强迫命令、不搞一刀切。\n——守住政策底线。坚持和完善农村基本经营制度，坚持农村土地集体所有，坚持家庭经营基础性地位，坚持稳定土地承包关系，不能把农村土地集体所有制改垮了，不能把耕地改少了，不能把粮食生产能力改弱了，不能把农民利益损害了。\n——坚持循序渐进。充分认识农村土地制度改革的长期性和复杂性，保持足够历史耐心，审慎稳妥推进改革，由点及面开展，不操之过急，逐步将实践经验上升为制度安排。\n——坚持因地制宜。充分考虑各地资源禀赋和经济社会发展差异，鼓励进行符合实际的实践探索和制度创新，总结形成适合不同地区的“三权分置”具体路径和办法。","level":1},{"name":"三、逐步形成“三权分置”格局","text":"完善“三权分置”办法，不断探索农村土地集体所有制的有效实现形式，落实集体所有权，稳定农户承包权，放活土地经营权，充分发挥“三权”的各自功能和整体效用，形成层次分明、结构合理、平等保护的格局。\n（一）始终坚持农村土地集体所有权的根本地位。农村土地农民集体所有，是农村基本经营制度的根本，必须得到充分体现和保障，不能虚置。土地集体所有权人对集体土地依法享有占有、使用、收益和处分的权利。农民集体是土地集体所有权的权利主体，在完善“三权分置”办法过程中，要充分维护农民集体对承包地发包、调整、监督、收回等各项权能，发挥土地集体所有的优势和作用。农民集体有权依法发包集体土地，任何组织和个人不得非法干预；有权因自然灾害严重毁损等特殊情形依法调整承包地；有权对承包农户和经营主体使用承包地进行监督，并采取措施防止和纠正长期抛荒、毁损土地、非法改变土地用途等行为。承包农户转让土地承包权的，应在本集体经济组织内进行，并经农民集体同意；流转土地经营权的，须向农民集体书面备案。集体土地被征收的，农民集体有权就征地补偿安置方案等提出意见并依法获得补偿。通过建立健全集体经济组织民主议事机制，切实保障集体成员的知情权、决策权、监督权，确保农民集体有效行使集体土地所有权，防止少数人私相授受、谋取私利。\n（二）严格保护农户承包权。农户享有土地承包权是农村基本经营制度的基础，要稳定现有土地承包关系并保持长久不变。土地承包权人对承包土地依法享有占有、使用和收益的权利。农村集体土地由作为本集体经济组织成员的农民家庭承包，不论经营权如何流转，集体土地承包权都属于农民家庭。任何组织和个人都不能取代农民家庭的土地承包地位，都不能非法剥夺和限制农户的土地承包权。在完善“三权分置”办法过程中，要充分维护承包农户使用、流转、抵押、退出承包地等各项权能。承包农户有权占有、使用承包地，依法依规建设必要的农业生产、附属、配套设施，自主组织生产经营和处置产品并获得收益；有权通过转让、互换、出租（转包）、入股或其他方式流转承包地并获得收益，任何组织和个人不得强迫或限制其流转土地；有权依法依规就承包土地经营权设定抵押、自愿有偿退出承包地，具备条件的可以因保护承包地获得相关补贴。承包土地被征收的，承包农户有权依法获得相应补偿，符合条件的有权获得社会保障费用等。不得违法调整农户承包地，不得以退出土地承包权作为农民进城落户的条件。\n（三）加快放活土地经营权。赋予经营主体更有保障的土地经营权，是完善农村基本经营制度的关键。土地经营权人对流转土地依法享有在一定期限内占有、耕作并取得相应收益的权利。在依法保护集体所有权和农户承包权的前提下，平等保护经营主体依流转合同取得的土地经营权，保障其有稳定的经营预期。在完善“三权分置”办法过程中，要依法维护经营主体从事农业生产所需的各项权利，使土地资源得到更有效合理的利用。经营主体有权使用流转土地自主从事农业生产经营并获得相应收益，经承包农户同意，可依法依规改良土壤、提升地力，建设农业生产、附属、配套设施，并依照流转合同约定获得合理补偿；有权在流转合同到期后按照同等条件优先续租承包土地。经营主体再流转土地经营权或依法依规设定抵押，须经承包农户或其委托代理人书面同意，并向农民集体书面备案。流转土地被征收的，地上附着物及青苗补偿费应按照流转合同约定确定其归属。承包农户流转出土地经营权的，不应妨碍经营主体行使合法权利。加强对土地经营权的保护，引导土地经营权流向种田能手和新型经营主体。支持新型经营主体提升地力、改善农业生产条件、依法依规开展土地经营权抵押融资。鼓励采用土地股份合作、土地托管、代耕代种等多种经营方式，探索更多放活土地经营权的有效途径。\n（四）逐步完善“三权”关系。农村土地集体所有权是土地承包权的前提，农户享有承包经营权是集体所有的具体实现形式，在土地流转中，农户承包经营权派生出土地经营权。支持在实践中积极探索农民集体依法依规行使集体所有权、监督承包农户和经营主体规范利用土地等的具体方式。鼓励在理论上深入研究农民集体和承包农户在承包土地上、承包农户和经营主体在土地流转中的权利边界及相互权利关系等问题。通过实践探索和理论创新，逐步完善“三权”关系，为实施“三权分置”提供有力支撑。","level":1},{"name":"四、确保“三权分置”有序实施","text":"完善“三权分置”办法涉及多方权益，是一个渐进过程和系统性工程，要坚持统筹谋划、稳步推进，确保“三权分置”有序实施。\n（一）扎实做好农村土地确权登记颁证工作。确认“三权”权利主体，明确权利归属，稳定土地承包关系，才能确保“三权分置”得以确立和稳步实施。要坚持和完善土地用途管制制度，在集体土地所有权确权登记颁证工作基本完成的基础上，进一步完善相关政策，及时提供确权登记成果，切实保护好农民的集体土地权益。加快推进农村承包地确权登记颁证，形成承包合同网签管理系统，健全承包合同取得权利、登记记载权利、证书证明权利的确权登记制度。提倡通过流转合同鉴证、交易鉴证等多种方式对土地经营权予以确认，促进土地经营权功能更好实现。\n（二）建立健全土地流转规范管理制度。规范土地经营权流转交易，因地制宜加强农村产权交易市场建设，逐步实现涉农县（市、区、旗）全覆盖。健全市场运行规范，提高服务水平，为流转双方提供信息发布、产权交易、法律咨询、权益评估、抵押融资等服务。加强流转合同管理，引导流转双方使用合同示范文本。完善工商资本租赁农地监管和风险防范机制，严格准入门槛，确保土地经营权规范有序流转，更好地与城镇化进程和农村劳动力转移规模相适应，与农业科技进步和生产手段改进程度相适应，与农业社会化服务水平相适应。加强农村土地承包经营纠纷调解仲裁体系建设，完善基层农村土地承包调解机制，妥善化解土地承包经营纠纷，有效维护各权利主体的合法权益。\n（三）构建新型经营主体政策扶持体系。完善新型经营主体财政、信贷保险、用地、项目扶持等政策。积极创建示范家庭农场、农民专业合作社示范社、农业产业化示范基地、农业示范服务组织，加快培育新型经营主体。引导新型经营主体与承包农户建立紧密利益联结机制，带动普通农户分享农业规模经营收益。支持新型经营主体相互融合，鼓励家庭农场、农民专业合作社、农业产业化龙头企业等联合与合作，依法组建行业组织或联盟。依托现代农业人才支撑计划，健全新型职业农民培育制度。\n（四）完善“三权分置”法律法规。积极开展土地承包权有偿退出、土地经营权抵押贷款、土地经营权入股农业产业化经营等试点，总结形成可推广、可复制的做法和经验，在此基础上完善法律制度。加快农村土地承包法等相关法律修订完善工作。认真研究农村集体经济组织、家庭农场发展等相关法律问题。研究健全农村土地经营权流转、抵押贷款和农村土地承包权退出等方面的具体办法。\n实施“三权分置”是深化农村土地制度改革的重要举措。各地区各有关部门要认真贯彻本意见要求，研究制定具体落实措施。加大政策宣传力度，统一思想认识，加强干部培训，提高执行政策能力和水平。坚持问题导向，对实践中出现的新情况新问题要密切关注，及时总结，适时调整完善措施。加强工作指导，建立检查监督机制，督促各项任务稳步开展。农业部、中央农办要切实承担起牵头责任，健全沟通协调机制，及时向党中央、国务院报告工作进展情况。各相关部门要主动支持配合，形成工作合力，更好推动“三权分置”有序实施。","level":1}]},{"id":"r0522","sections":[{"name":"关于划定并严守生态保护红线的若干意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于划定并严守生态保护红线的若干意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于划定并严守生态保护红线的若干意见》全文如下。\n生态空间是指具有自然属性、以提供生态服务或生态产品为主体功能的国土空间，包括森林、草原、湿地、河流、湖泊、滩涂、岸线、海洋、荒地、荒漠、戈壁、冰川、高山冻原、无居民海岛等。生态保护红线是指在生态空间范围内具有特殊重要生态功能、必须强制性严格保护的区域，是保障和维护国家生态安全的底线和生命线，通常包括具有重要水源涵养、生物多样性维护、水土保持、防风固沙、海岸生态稳定等功能的生态功能重要区域，以及水土流失、土地沙化、石漠化、盐渍化等生态环境敏感脆弱区域。党中央、国务院高度重视生态环境保护，作出一系列重大决策部署，推动生态环境保护工作取得明显进展。但是，我国生态环境总体仍比较脆弱，生态安全形势十分严峻。划定并严守生态保护红线，是贯彻落实主体功能区制度、实施生态空间用途管制的重要举措，是提高生态产品供给能力和生态系统服务功能、构建国家生态安全格局的有效手段，是健全生态文明制度体系、推动绿色发展的有力保障。现就划定并严守生态保护红线提出以下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。全面贯彻党的十八大和十八届三中、四中、五中、六中全会精神，深入贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，牢固树立新发展理念，认真落实党中央、国务院决策部署，以改善生态环境质量为核心，以保障和维护生态功能为主线，按照山水林田湖系统保护的要求，划定并严守生态保护红线，实现一条红线管控重要生态空间，确保生态功能不降低、面积不减少、性质不改变，维护国家生态安全，促进经济社会可持续发展。\n（二）基本原则\n——科学划定，切实落地。落实环境保护法等相关法律法规，统筹考虑自然生态整体性和系统性，开展科学评估，按生态功能重要性、生态环境敏感性与脆弱性划定生态保护红线，并落实到国土空间，系统构建国家生态安全格局。\n——坚守底线，严格保护。牢固树立底线意识，将生态保护红线作为编制空间规划的基础。强化用途管制，严禁任意改变用途，杜绝不合理开发建设活动对生态保护红线的破坏。\n——部门协调，上下联动。加强部门间沟通协调，国家层面做好顶层设计，出台技术规范和政策措施，地方党委和政府落实划定并严守生态保护红线的主体责任，上下联动、形成合力，确保划得实、守得住。\n（三）总体目标。2017年年底前，京津冀区域、长江经济带沿线各省（直辖市）划定生态保护红线；2018年年底前，其他省（自治区、直辖市）划定生态保护红线；2020年年底前，全面完成全国生态保护红线划定，勘界定标，基本建立生态保护红线制度，国土生态空间得到优化和有效保护，生态功能保持稳定，国家生态安全格局更加完善。到2030年，生态保护红线布局进一步优化，生态保护红线制度有效实施，生态功能显著提升，国家生态安全得到全面保障。","level":1},{"name":"二、划定生态保护红线","text":"依托“两屏三带”为主体的陆地生态安全格局和“一带一链多点”的海洋生态安全格局，采取国家指导、地方组织，自上而下和自下而上相结合，科学划定生态保护红线。\n（四）明确划定范围。环境保护部、国家发展改革委会同有关部门，于2017年6月底前制定并发布生态保护红线划定技术规范，明确水源涵养、生物多样性维护、水土保持、防风固沙等生态功能重要区域，以及水土流失、土地沙化、石漠化、盐渍化等生态环境敏感脆弱区域的评价方法，识别生态功能重要区域和生态环境敏感脆弱区域的空间分布。将上述两类区域进行空间叠加，划入生态保护红线，涵盖所有国家级、省级禁止开发区域，以及有必要严格保护的其他各类保护地等。\n（五）落实生态保护红线边界。按照保护需要和开发利用现状，主要结合以下几类界线将生态保护红线边界落地：自然边界，主要是依据地形地貌或生态系统完整性确定的边界，如林线、雪线、流域分界线，以及生态系统分布界线等；自然保护区、风景名胜区等各类保护地边界；江河、湖库，以及海岸等向陆域（或向海）延伸一定距离的边界；全国土地调查、地理国情普查等明确的地块边界。将生态保护红线落实到地块，明确生态系统类型、主要生态功能，通过自然资源统一确权登记明确用地性质与土地权属，形成生态保护红线全国“一张图”。在勘界基础上设立统一规范的标识标牌，确保生态保护红线落地准确、边界清晰。\n（六）有序推进划定工作。环境保护部、国家发展改革委会同有关部门提出各省（自治区、直辖市）生态保护红线空间格局和分布意见，做好跨省域的衔接与协调，指导各地划定生态保护红线；明确生态保护红线可保护的湿地、草原、森林等生态系统数量，并与生态安全预警监测体系做好衔接。各省（自治区、直辖市）要按照相关要求，建立划定生态保护红线责任制和协调机制，明确责任部门，组织专门力量，制定工作方案，全面论证、广泛征求意见，有序推进划定工作，形成生态保护红线。环境保护部、国家发展改革委会同有关部门组织对各省（自治区、直辖市）生态保护红线进行技术审核并提出意见，报国务院批准后由各省（自治区、直辖市）政府发布实施。在各省（自治区、直辖市）生态保护红线基础上，环境保护部、国家发展改革委会同有关部门进行衔接、汇总，形成全国生态保护红线，并向社会发布。鉴于海洋国土空间的特殊性，国家海洋局根据本意见制定相关技术规范，组织划定并审核海洋国土空间的生态保护红线，纳入全国生态保护红线。","level":1},{"name":"三、严守生态保护红线","text":"落实地方各级党委和政府主体责任，强化生态保护红线刚性约束，形成一整套生态保护红线管控和激励措施。\n（七）明确属地管理责任。地方各级党委和政府是严守生态保护红线的责任主体，要将生态保护红线作为相关综合决策的重要依据和前提条件，履行好保护责任。各有关部门要按照职责分工，加强监督管理，做好指导协调、日常巡护和执法监督，共守生态保护红线。建立目标责任制，把保护目标、任务和要求层层分解，落到实处。创新激励约束机制，对生态保护红线保护成效突出的单位和个人予以奖励；对造成破坏的，依法依规予以严肃处理。根据需要设置生态保护红线管护岗位，提高居民参与生态保护积极性。\n（八）确立生态保护红线优先地位。生态保护红线划定后，相关规划要符合生态保护红线空间管控要求，不符合的要及时进行调整。空间规划编制要将生态保护红线作为重要基础，发挥生态保护红线对于国土空间开发的底线作用。\n（九）实行严格管控。生态保护红线原则上按禁止开发区域的要求进行管理。严禁不符合主体功能定位的各类开发活动，严禁任意改变用途。生态保护红线划定后，只能增加、不能减少，因国家重大基础设施、重大民生保障项目建设等需要调整的，由省级政府组织论证，提出调整方案，经环境保护部、国家发展改革委会同有关部门提出审核意见后，报国务院批准。因国家重大战略资源勘查需要，在不影响主体功能定位的前提下，经依法批准后予以安排勘查项目。\n（十）加大生态保护补偿力度。财政部会同有关部门加大对生态保护红线的支持力度，加快健全生态保护补偿制度，完善国家重点生态功能区转移支付政策。推动生态保护红线所在地区和受益地区探索建立横向生态保护补偿机制，共同分担生态保护任务。\n（十一）加强生态保护与修复。实施生态保护红线保护与修复，作为山水林田湖生态保护和修复工程的重要内容。以县级行政区为基本单元建立生态保护红线台账系统，制定实施生态系统保护与修复方案。优先保护良好生态系统和重要物种栖息地，建立和完善生态廊道，提高生态系统完整性和连通性。分区分类开展受损生态系统修复，采取以封禁为主的自然恢复措施，辅以人工修复，改善和提升生态功能。选择水源涵养和生物多样性维护为主导生态功能的生态保护红线，开展保护与修复示范。有条件的地区，可逐步推进生态移民，有序推动人口适度集中安置，降低人类活动强度，减小生态压力。按照陆海统筹、综合治理的原则，开展海洋国土空间生态保护红线的生态整治修复，切实强化生态保护红线及周边区域污染联防联治，重点加强生态保护红线内入海河流综合整治。\n（十二）建立监测网络和监管平台。环境保护部、国家发展改革委、国土资源部会同有关部门建设和完善生态保护红线综合监测网络体系，充分发挥地面生态系统、环境、气象、水文水资源、水土保持、海洋等监测站点和卫星的生态监测能力，布设相对固定的生态保护红线监控点位，及时获取生态保护红线监测数据。建立国家生态保护红线监管平台。依托国务院有关部门生态环境监管平台和大数据，运用云计算、物联网等信息化手段，加强监测数据集成分析和综合应用，强化生态气象灾害监测预警能力建设，全面掌握生态系统构成、分布与动态变化，及时评估和预警生态风险，提高生态保护红线管理决策科学化水平。实时监控人类干扰活动，及时发现破坏生态保护红线的行为，对监控发现的问题，通报当地政府，由有关部门依据各自职能组织开展现场核查，依法依规进行处理。2017年年底前完成国家生态保护红线监管平台试运行。各省（自治区、直辖市）应依托国家生态保护红线监管平台，加强能力建设，建立本行政区监管体系，实施分层级监管，及时接收和反馈信息，核查和处理违法行为。\n（十三）开展定期评价。环境保护部、国家发展改革委会同有关部门建立生态保护红线评价机制。从生态系统格局、质量和功能等方面，建立生态保护红线生态功能评价指标体系和方法。定期组织开展评价，及时掌握全国、重点区域、县域生态保护红线生态功能状况及动态变化，评价结果作为优化生态保护红线布局、安排县域生态保护补偿资金和实行领导干部生态环境损害责任追究的依据，并向社会公布。\n（十四）强化执法监督。各级环境保护部门和有关部门要按照职责分工加强生态保护红线执法监督。建立生态保护红线常态化执法机制，定期开展执法督查，不断提高执法规范化水平。及时发现和依法处罚破坏生态保护红线的违法行为，切实做到有案必查、违法必究。有关部门要加强与司法机关的沟通协调，健全行政执法与刑事司法联动机制。\n（十五）建立考核机制。环境保护部、国家发展改革委会同有关部门，根据评价结果和目标任务完成情况，对各省（自治区、直辖市）党委和政府开展生态保护红线保护成效考核，并将考核结果纳入生态文明建设目标评价考核体系，作为党政领导班子和领导干部综合评价及责任追究、离任审计的重要参考。\n（十六）严格责任追究。对违反生态保护红线管控要求、造成生态破坏的部门、地方、单位和有关责任人员，按照有关法律法规和《党政领导干部生态环境损害责任追究办法（试行）》等规定实行责任追究。对推动生态保护红线工作不力的，区分情节轻重，予以诫勉、责令公开道歉、组织处理或党纪政纪处分，构成犯罪的依法追究刑事责任。对造成生态环境和资源严重破坏的，要实行终身追责，责任人不论是否已调离、提拔或者退休，都必须严格追责。","level":1},{"name":"四、强化组织保障","text":"（十七）加强组织协调。建立由环境保护部、国家发展改革委牵头的生态保护红线管理协调机制，明确地方和部门责任。各地要加强组织协调，强化监督执行，形成加快划定并严守生态保护红线的工作格局。\n（十八）完善政策机制。加快制定有利于提升和保障生态功能的土地、产业、投资等配套政策。推动生态保护红线有关立法，各地要因地制宜，出台相应的生态保护红线管理地方性法规。研究市场化、社会化投融资机制，多渠道筹集保护资金，发挥资金合力。\n（十九）促进共同保护。环境保护部、国家发展改革委会同有关部门定期发布生态保护红线监控、评价、处罚和考核信息，各地及时准确发布生态保护红线分布、调整、保护状况等信息，保障公众知情权、参与权和监督权。加大政策宣传力度，发挥媒体、公益组织和志愿者作用，畅通监督举报渠道。\n本意见实施后，其他有关生态保护红线的政策规定要按照本意见要求进行调整或废止。各地要抓紧制定实施方案，明确目标任务、责任分工和时间要求，确保各项要求落到实处。\n延伸阅读\n环境保护部部长 陈吉宁：划定并严守生态保护红线 为子孙后代留下天蓝地绿水清的家园","level":1}]},{"id":"r0523","sections":[{"name":"关于印发《习近平新时代中国特色社会主义思想学习纲要》的通知","text":"近日，中共中央发出关于印发《习近平新时代中国特色社会主义思想学习纲要》的通知。全文如下：","level":1},{"name":"","text":"党的十九大把习近平新时代中国特色社会主义思想确立为党必须长期坚持的指导思想并写入党章，十三届全国人大一次会议通过的宪法修正案把习近平新时代中国特色社会主义思想载入宪法，实现了党和国家指导思想的与时俱进。习近平新时代中国特色社会主义思想，是对马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观的继承和发展，是马克思主义中国化最新成果，是党和人民实践经验和集体智慧的结晶，是中国特色社会主义理论体系的重要组成部分，是全党全国人民为实现中华民族伟大复兴而奋斗的行动指南，必须长期坚持并不断发展。\n为把学习贯彻习近平新时代中国特色社会主义思想进一步引向深入，根据党中央要求，中央宣传部组织编写了《习近平新时代中国特色社会主义思想学习纲要》（以下简称《纲要》）。党中央认为，《纲要》对习近平新时代中国特色社会主义思想作了全面系统阐述，有助于更好地理解把握这一思想的基本精神、基本内容、基本要求。党中央同意印发《纲要》（由中央宣传部统一印发），作为广大干部群众深入学习领会习近平新时代中国特色社会主义思想的重要辅助读物。\n各级党委（党组）要坚持不懈用习近平新时代中国特色社会主义思想武装头脑、指导实践、推动工作。要组织全体党员认真读原著、学原文、悟原理，并紧密结合“不忘初心、牢记使命”主题教育，把《纲要》纳入学习计划，作出周密安排，开展多形式、分层次、全覆盖的学习培训。要在多思多想、学深悟透上下功夫，深入学习领会这一思想的时代意义、理论意义、实践意义、世界意义，深刻理解其核心要义、精神实质、丰富内涵、实践要求；在系统全面、融会贯通上下功夫，深刻把握这一思想贯穿的马克思主义立场观点方法，知其然又知其所以然，不断提高马克思主义理论水平；在知行合一、学以致用上下功夫，大力弘扬理论联系实际的优良学风，更加自觉用这一思想指导解决实际问题，切实把学习成效转化为做好本职工作、推动事业发展的生动实践。\n要通过广泛的学习宣传阐释工作，推动习近平新时代中国特色社会主义思想进一步深入人心、落地生根，引导广大干部群众增强“四个意识”、坚定“四个自信”、做到“两个维护”，在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致，为决胜全面建成小康社会、夺取新时代中国特色社会主义伟大胜利、实现中华民族伟大复兴的中国梦不懈奋斗。\n延伸阅读\n“不忘初心、牢记使命”主题教育中央通知文件\n学习《习近平新时代中国特色社会主义思想学习纲要》","level":0}]},{"id":"r0524","sections":[{"name":"关于依法处理涉法涉诉信访问题的意见","text":"点击此处观看视频","level":1},{"name":"","text":"中共中央办公厅、国务院办公厅近日印发了《关于依法处理涉法涉诉信访问题的意见》，并发出通知，要求各地区各部门切实加强协调配合，健全涉法涉诉信访工作机制，努力形成依法解决涉法涉诉信访问题的合力。\n《意见》包括充分认识依法处理涉法涉诉信访问题的重要意义、改革涉法涉诉信访工作机制、进一步提高执法司法公信力、依法维护涉法涉诉信访秩序、加强和改进对依法处理涉法涉诉信访问题的组织领导等5个部分。\n《意见》指出，依法处理涉法涉诉信访问题，事关最广大人民群众根本利益，事关国家法制统一、尊严、权威，事关党执政地位巩固和国家长治久安。改革涉法涉诉信访工作机制，依法处理涉法涉诉信访问题，既是贯彻落实党的十八大和十八届三中全会精神的要求，又是贯彻实施修改后的刑事诉讼法、民事诉讼法的实际行动；既是全面推进依法治国的需要，又是维护人民群众合法权益的具体体现。\n《意见》强调，改革涉法涉诉信访工作机制、依法处理涉法涉诉信访问题的总体思路是：改变经常性集中交办、过分依靠行政推动、通过信访启动法律程序的工作方式，把解决涉法涉诉信访问题纳入法治轨道，由政法机关依法按程序处理，依法纠正执法差错，依法保障合法权益，依法维护公正结论，保护合法信访、制止违法闹访。努力实现案结事了、息诉息访，实现维护人民群众合法权益与维护司法权威的统一。\n《意见》提出，实行诉讼与信访分离制度。把涉及民商事、行政、刑事等诉讼权利救济的信访事项从普通信访体制中分离出来，由政法机关依法处理。各级信访部门对到本部门上访的涉诉信访群众，应当引导其到政法机关反映问题；对按规定受理的涉及公安机关、司法行政机关的涉法涉诉信访事项，收到的群众涉法涉诉信件，应当转同级政法机关依法处理。\n《意见》要求，建立涉法涉诉信访事项导入司法程序机制。对涉法涉诉信访事项，各级政法机关要及时审查、甄别。对于正在法律程序中的，继续依法按程序办理；对于已经结案，但符合复议、复核、再审条件的，依法转入相应法律程序办理；对于已经结案，不符合复议、复核、再审条件的，做好不予受理的解释说明工作；对于不服有关行政机关依法作出的行政复议决定，经释法明理仍不服的，可引导其向人民法院提起行政诉讼。有关处理程序和结果，应当严格按照规定的期限和方式，及时告知当事人。\n《意见》指出，严格落实依法按程序办理制度。各级政法机关对于已经进入法律程序处理的案件，应当依法按程序在法定时限内公正办结。对经复议、审理、复核，确属错案、瑕疵案的，依法纠正错误、补正瑕疵；属于国家赔偿范围的，依照国家赔偿法的有关规定办理。对经复议、审理、复核，未发现错误的，依法维持原裁决，并按照有关规定及时告知当事人。\n《意见》强调，建立涉法涉诉信访依法终结制度。中央政法机关按照修改后的刑事诉讼法、民事诉讼法和相关法律法规，修改完善涉法涉诉信访终结办法。对涉法涉诉信访事项，已经穷尽法律程序的，依法作出的判决、裁定为终结决定。对在申诉时限内反复缠访缠诉，经过案件审查、评查等方式，并经中央或省级政法机关审核，认定其反映问题已经得到公正处理的，除有法律规定的情形外，依法不再启动复查程序。各级各有关部门不再统计、交办、通报，重点是做好对信访人的解释、疏导工作。\n《意见》要求，健全国家司法救助制度。各级政法机关要在党委和政府的领导和支持下，统筹解决信访群众的法律问题和实际困难。对于因执法问题给当事人造成伤害或损失的，依法予以纠错、补偿。对于因遭受犯罪侵害或民事侵权，无法经过诉讼获得有效赔偿，造成当事人生活困难，符合救助规定的，及时给予司法救助。对于给予司法救助后仍然存在实际困难的，通过民政救济、社会救助等方式帮助解决实际困难。\n《意见》要求，进一步提高执法司法公信力。各级政法机关要严格依照法定权限和程序履行职责、行使权力，确保每一起案件的处理做到实体公正、程序公正、规范高效，经得起检验；要依法加大内部监督力度，促使执法办案中存在的问题依法及时得到解决，对于执法不严、裁判不公、徇私枉法等突出问题，要组织开展专项整治；要完善执法司法责任制，严格落实办案质量终身负责制，健全执法过错发现、调查、问责机制，严格倒查执法办案中存在问题的原因和责任，严肃查处错案背后的执法不公、不廉等问题；要把加强执法公开、扩大群众参与、接受群众监督作为依法处理涉法涉诉信访问题的重要内容，以公开确保公正、促进息诉。\n《意见》强调，畅通信访渠道。各级政法机关要转变观念，把做好涉法涉诉信访工作作为倾听群众意见、改进执法工作的有效途径。进一步规范依法处理涉法涉诉信访工作，坚决杜绝一切“拦卡堵截”正常上访人员的错误做法；坚决杜绝违法限制或变相限制上访人员人身自由的行为。坚持政法机关领导接待来访群众和阅批群众来信制度。采取热线电话、网上信访、视频接访、开通绿色通道等措施，健全来信、来访、网上信访、电话信访一体化接访网络，为涉法涉诉信访群众反映问题提供畅通便捷的渠道。要依法规范群众信访行为，引导上访人员依法理性表达诉求，严肃处理违法上访行为。\n《意见》强调，完善领导体制机制。各级党委政法委要进一步明确在依法处理涉法涉诉信访问题中的职能定位，重点抓好政策指导、执法监督、宏观协调等工作。各级政法机关作为依法处理涉法涉诉信访问题的责任主体，要调整充实工作力量，建立健全工作制度，严格落实工作责任，增强政法干警依法处理涉法涉诉信访问题的责任感，进一步转变执法作风，提高群众工作能力，做到严格规范公正文明廉洁执法。建立健全科学合理的考评指标体系，改变简单以信访数量为主要指标的考评办法，坚决纠正重程序轻解决、重稳控轻化解的倾向，引导政法干警在日常执法办案中自觉预防、主动化解涉法涉诉信访问题。\n延伸阅读：\n中央司法体制改革领导小组办公室负责人就《关于依法处理涉法涉诉信访问题的意见》答记者问\n人民日报评论员：用法治方式化解信访难题","level":0}]},{"id":"r0525","sections":[{"name":"中共中央 国务院印发《新时代爱国主义教育实施纲要》","text":"近日，中共中央、国务院印发了《新时代爱国主义教育实施纲要》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《新时代爱国主义教育实施纲要》全文如下。\n爱国主义是中华民族的民族心、民族魂，是中华民族最重要的精神财富，是中国人民和中华民族维护民族独立和民族尊严的强大精神动力。爱国主义精神深深植根于中华民族心中，维系着中华大地上各个民族的团结统一，激励着一代又一代中华儿女为祖国发展繁荣而自强不息、不懈奋斗。中国共产党是爱国主义精神最坚定的弘扬者和实践者，90多年来，中国共产党团结带领全国各族人民进行的革命、建设、改革实践是爱国主义的伟大实践，写下了中华民族爱国主义精神的辉煌篇章。党的十八大以来，以习近平同志为核心的党中央高度重视爱国主义教育，固本培元、凝心铸魂，作出一系列重要部署，推动爱国主义教育取得显著成效。当前，中国特色社会主义进入新时代，中华民族伟大复兴正处于关键时期。新时代加强爱国主义教育，对于振奋民族精神、凝聚全民族力量，决胜全面建成小康社会，夺取新时代中国特色社会主义伟大胜利，实现中华民族伟大复兴的中国梦，具有重大而深远的意义。","level":0},{"name":"一、总体要求","text":"1．指导思想。坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，增强“四个意识”，坚定“四个自信”，做到“两个维护”，着眼培养担当民族复兴大任的时代新人，始终高扬爱国主义旗帜，着力培养爱国之情、砥砺强国之志、实践报国之行，使爱国主义成为全体中国人民的坚定信念、精神力量和自觉行动。\n2．坚持把实现中华民族伟大复兴的中国梦作为鲜明主题。伟大事业需要伟大精神，伟大精神铸就伟大梦想。要把国家富强、民族振兴、人民幸福作为不懈追求，着力扎紧全国各族人民团结奋斗的精神纽带，厚植家国情怀，培育精神家园，引导人们坚持中国道路、弘扬中国精神、凝聚中国力量，为实现中华民族伟大复兴的中国梦提供强大精神动力。\n3．坚持爱党爱国爱社会主义相统一。新中国是中国共产党领导的社会主义国家，祖国的命运与党的命运、社会主义的命运密不可分。当代中国，爱国主义的本质就是坚持爱国和爱党、爱社会主义高度统一。要区分层次、区别对象，引导人们深刻认识党的领导是中国特色社会主义最本质特征和最大制度优势，坚持党的领导、坚持走中国特色社会主义道路是实现国家富强的根本保障和必由之路，以坚定的信念、真挚的情感把新时代中国特色社会主义一以贯之进行下去。\n4．坚持以维护祖国统一和民族团结为着力点。国家统一和民族团结是中华民族根本利益所在。要始终不渝坚持民族团结是各族人民的生命线，巩固和发展平等团结互助和谐的社会主义民族关系，引导全国各族人民像爱护自己的眼睛一样珍惜民族团结，维护全国各族人民大团结的政治局面，巩固和发展最广泛的爱国统一战线，不断增强对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的认同，坚决维护国家主权、安全、发展利益，旗帜鲜明反对分裂国家图谋、破坏民族团结的言行，筑牢国家统一、民族团结、社会稳定的铜墙铁壁。\n5．坚持以立为本、重在建设。爱国主义是中华儿女最自然、最朴素的情感。要坚持从娃娃抓起，着眼固本培元、凝心铸魂，突出思想内涵，强化思想引领，做到润物无声，把基本要求和具体实际结合起来，把全面覆盖和突出重点结合起来，遵循规律、创新发展，注重落细落小落实、日常经常平常，强化教育引导、实践养成、制度保障，推动爱国主义教育融入贯穿国民教育和精神文明建设全过程。\n6．坚持立足中国又面向世界。一个国家、一个民族，只有开放兼容，才能富强兴盛。要把弘扬爱国主义精神与扩大对外开放结合起来，尊重各国历史特点、文化传统，尊重各国人民选择的发展道路，善于从不同文明中寻求智慧、汲取营养，促进人类和平与发展的崇高事业，共同推动人类文明发展进步。","level":1},{"name":"二、基本内容","text":"7．坚持用习近平新时代中国特色社会主义思想武装全党、教育人民。习近平新时代中国特色社会主义思想是马克思主义中国化最新成果，是党和人民实践经验和集体智慧的结晶，是中国特色社会主义理论体系的重要组成部分，是全党全国人民为实现中华民族伟大复兴而奋斗的行动指南，必须长期坚持并不断发展。要深刻理解习近平新时代中国特色社会主义思想的核心要义、精神实质、丰富内涵、实践要求，不断增强干部群众的政治意识、大局意识、核心意识、看齐意识，坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导。要紧密结合人们生产生活实际，推动习近平新时代中国特色社会主义思想进企业、进农村、进机关、进校园、进社区、进军营、进网络，真正使党的创新理论落地生根、开花结果。要在知行合一、学以致用上下功夫，引导干部群众坚持以习近平新时代中国特色社会主义思想为指导，展现新气象、激发新作为，把学习教育成果转化为爱国报国的实际行动。\n8．深入开展中国特色社会主义和中国梦教育。中国特色社会主义集中体现着国家、民族、人民根本利益。要高举中国特色社会主义伟大旗帜，广泛开展理想信念教育，用党领导人民进行伟大社会革命的成果说话，用改革开放以来社会主义现代化建设的伟大成就说话，用新时代坚持和发展中国特色社会主义的生动实践说话，用中国特色社会主义制度的优势说话，在历史与现实、国际与国内的对比中，引导人们深刻认识中国共产党为什么“能”、马克思主义为什么“行”、中国特色社会主义为什么“好”，牢记红色政权是从哪里来的、新中国是怎么建立起来的，倍加珍惜我们党开创的中国特色社会主义，不断增强道路自信、理论自信、制度自信、文化自信。要深入开展中国梦教育，引导人们深刻认识中国梦是国家的梦、民族的梦，也是每个中国人的梦，深刻认识中华民族伟大复兴绝不是轻轻松松、敲锣打鼓就能实现的，要付出更为艰巨、更为艰苦的努力，争做新时代的奋斗者、追梦人。\n9．深入开展国情教育和形势政策教育。要深入开展国情教育，帮助人们了解我国发展新的历史方位、社会主要矛盾的变化，引导人们深刻认识到，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界上最大发展中国家的国际地位没有变，始终准确把握基本国情，既不落后于时代，也不脱离实际、超越阶段。要深入开展形势政策教育，帮助人们树立正确的历史观、大局观、角色观，了解世界正经历百年未有之大变局，我国仍处于发展的重要战略机遇期，引导人们清醒认识国际国内形势发展变化，做好我们自己的事情。要发扬斗争精神，增强斗争本领，引导人们充分认识伟大斗争的长期性、复杂性、艰巨性，敢于直面风险挑战，以坚忍不拔的意志和无私无畏的勇气战胜前进道路上的一切艰难险阻，在进行伟大斗争中更好弘扬爱国主义精神。\n10．大力弘扬民族精神和时代精神。以爱国主义为核心的民族精神和以改革创新为核心的时代精神，是凝心聚力的兴国之魂、强国之魂。要聚焦培养担当民族复兴大任的时代新人，培育和践行社会主义核心价值观，广泛开展爱国主义、集体主义、社会主义教育，提高人们的思想觉悟、道德水准和文明素养。要唱响人民赞歌、展现人民风貌，大力弘扬中国人民在长期奋斗中形成的伟大创造精神、伟大奋斗精神、伟大团结精神、伟大梦想精神，生动展示人民群众在新时代的新实践、新业绩、新作为。\n11．广泛开展党史、国史、改革开放史教育。历史是最好的教科书，也是最好的清醒剂。要结合中华民族从站起来、富起来到强起来的伟大飞跃，引导人们深刻认识历史和人民选择中国共产党、选择马克思主义、选择社会主义道路、选择改革开放的历史必然性，深刻认识我们国家和民族从哪里来、到哪里去，坚决反对历史虚无主义。要继承革命传统，弘扬革命精神，传承红色基因，结合新的时代特点赋予新的内涵，使之转化为激励人民群众进行伟大斗争的强大动力。要加强改革开放教育，引导人们深刻认识改革开放是党和人民大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招，凝聚起将改革开放进行到底的强大力量。\n12．传承和弘扬中华优秀传统文化。对祖国悠久历史、深厚文化的理解和接受，是爱国主义情感培育和发展的重要条件。要引导人们了解中华民族的悠久历史和灿烂文化，从历史中汲取营养和智慧，自觉延续文化基因，增强民族自尊心、自信心和自豪感。要坚持古为今用、推陈出新，不忘本来、辩证取舍，深入实施中华优秀传统文化传承发展工程，推动中华文化创造性转化、创新性发展。要坚守正道、弘扬大道，反对文化虚无主义，引导人们树立和坚持正确的历史观、民族观、国家观、文化观，不断增强中华民族的归属感、认同感、尊严感、荣誉感。\n13．强化祖国统一和民族团结进步教育。实现祖国统一、维护民族团结，是中华民族的不懈追求。要加强祖国统一教育，深刻揭示维护国家主权和领土完整、实现祖国完全统一是大势所趋、大义所在、民心所向，增进广大同胞心灵契合、互信认同，与分裂祖国的言行开展坚决斗争，引导全体中华儿女为实现民族伟大复兴、推进祖国和平统一而共同奋斗。深化民族团结进步教育，铸牢中华民族共同体意识，加强各民族交往交流交融，引导各族群众牢固树立“三个离不开”思想，不断增强“五个认同”，使各民族同呼吸、共命运、心连心的光荣传统代代相传。\n14．加强国家安全教育和国防教育。国家安全是安邦定国的重要基石。要加强国家安全教育，深入学习宣传总体国家安全观，增强全党全国人民国家安全意识，自觉维护政治安全、国土安全、经济安全、社会安全、网络安全和外部安全。要加强国防教育，增强全民国防观念，使关心国防、热爱国防、建设国防、保卫国防成为全社会的思想共识和自觉行动。要深入开展增强忧患意识、防范化解重大风险的宣传教育，引导广大干部群众强化风险意识，科学辨识风险、有效应对风险，做到居安思危、防患未然。","level":1},{"name":"三、新时代爱国主义教育要面向全体人民、聚焦青少年","text":"15．充分发挥课堂教学的主渠道作用。培养社会主义建设者和接班人，首先要培养学生的爱国情怀。要把青少年作为爱国主义教育的重中之重，将爱国主义精神贯穿于学校教育全过程，推动爱国主义教育进课堂、进教材、进头脑。在普通中小学、中职学校，将爱国主义教育内容融入语文、道德与法治、历史等学科教材编写和教育教学中，在普通高校将爱国主义教育与哲学社会科学相关专业课程有机结合，加大爱国主义教育内容的比重。创新爱国主义教育的形式，丰富和优化课程资源，支持和鼓励多种形式开发微课、微视频等教育资源和在线课程，开发体现爱国主义教育要求的音乐、美术、书法、舞蹈、戏剧作品等，进一步增强吸引力感染力。\n16．办好学校思想政治理论课。思想政治理论课是爱国主义教育的主阵地。要紧紧抓住青少年阶段的“拔节孕穗期”，理直气壮开好思想政治理论课，引导学生把爱国情、强国志、报国行自觉融入坚持和发展中国特色社会主义事业、建设社会主义现代化强国、实现中华民族伟大复兴的奋斗之中。按照政治强、情怀深、思维新、视野广、自律严、人格正的要求，加强思想政治理论课教师队伍建设，让有信仰的人讲信仰，让有爱国情怀的人讲爱国。推动思想政治理论课改革创新，发挥学生主体作用，采取互动式、启发式、交流式教学，增强思想性理论性和亲和力针对性，在教育灌输和潜移默化中，引导学生树立国家意识、增进爱国情感。\n17．组织推出爱国主义精品出版物。针对不同年龄、不同成长阶段，坚持精品标准，加大创作力度，推出反映爱国主义内容的高质量儿童读物、教辅读物，让广大青少年自觉接受爱国主义熏陶。积极推荐爱国主义主题出版物，大力开展爱国主义教育读书活动。结合青少年兴趣点和接受习惯，大力开发并积极推介体现中华文化精髓、富有爱国主义气息的网络文学、动漫、有声读物、网络游戏、手机游戏、短视频等。\n18．广泛组织开展实践活动。大中小学的党组织、共青团、少先队、学生会、学生社团等，要把爱国主义内容融入党日团日、主题班会、班队会以及各类主题教育活动之中。广泛开展文明校园创建，强化校训校歌校史的爱国主义教育功能，组织开展丰富多彩的校园文化活动。组织大中小学生参观纪念馆、展览馆、博物馆、烈士纪念设施，参加军事训练、冬令营夏令营、文化科技卫生“三下乡”、学雷锋志愿服务、创新创业、公益活动等，更好地了解国情民情，强化责任担当。密切与城市社区、农村、企业、部队、社会机构等的联系，丰富拓展爱国主义教育校外实践领域。\n19．在广大知识分子中弘扬爱国奋斗精神。我国知识分子历来有浓厚的家国情怀和强烈的社会责任感。深入开展“弘扬爱国奋斗精神、建功立业新时代”活动，弘扬“两弹一星”精神、载人航天精神等，大力组织优秀知识分子学习宣传，引导新时代知识分子把自己的理想同祖国的前途、把自己的人生同民族的命运紧密联系在一起，立足本职、拼搏奋斗、创新创造，在新时代作出应有的贡献。广泛动员和组织知识分子深入改革开放前沿、经济发展一线和革命老区、民族地区、边疆地区、贫困地区，开展调研考察和咨询服务，深入了解国情，坚定爱国追求。\n20．激发社会各界人士的爱国热情。社会各界的代表性人士具有较强示范效应。要坚持信任尊重团结引导，增进和凝聚政治共识，夯实共同思想政治基础，不断扩大团结面，充分调动社会各界人士的爱国热情和社会担当。通过开展职业精神职业道德教育、建立健全相关制度规范、发挥行业和舆论监督作用等，引导社会各界人士增强道德自律、履行社会责任。坚持我国宗教的中国化方向，加强宗教界人士和信教群众的爱国主义教育，引导他们热爱祖国、拥护社会主义制度、拥护中国共产党的领导，遵守国家法律法规和方针政策。加强“一国两制”实践教育，引导人们包括香港特别行政区同胞、澳门特别行政区同胞、台湾同胞和海外侨胞增强对国家的认同，自觉维护国家统一和民族团结。","level":1},{"name":"四、丰富新时代爱国主义教育的实践载体","text":"21．建好用好爱国主义教育基地和国防教育基地。各级各类爱国主义教育基地，是激发爱国热情、凝聚人民力量、培育民族精神的重要场所。要加强内容建设，改进展陈方式，着力打造主题突出、导向鲜明、内涵丰富的精品陈列，强化爱国主义教育和红色教育功能，为社会各界群众参观学习提供更好服务。健全全国爱国主义教育示范基地动态管理机制，进一步完善落实免费开放政策和保障机制，根据实际情况，对爱国主义教育基地免费开放财政补助进行重新核定。依托军地资源，优化结构布局，提升质量水平，建设一批国防特色鲜明、功能设施配套、作用发挥明显的国防教育基地。\n22．注重运用仪式礼仪。认真贯彻执行国旗法、国徽法、国歌法，学习宣传基本知识和国旗升挂、国徽使用、国歌奏唱礼仪。在全社会广泛开展“同升国旗、同唱国歌”活动，让人们充分表达爱国情感。各级广播电台、电视台每天定时在主频率、主频道播放国歌。国庆期间，各级党政机关、人民团体、大型企事业单位、全国城乡社区和爱国主义教育基地等，要组织升国旗仪式并悬挂国旗。鼓励居民家庭在家门前适当位置悬挂国旗。认真组织宪法宣誓仪式、入党入团入队仪式等，通过公开宣誓、重温誓词等形式，强化国家意识和集体观念。\n23．组织重大纪念活动。充分挖掘重大纪念日、重大历史事件蕴含的爱国主义教育资源，组织开展系列庆祝或纪念活动和群众性主题教育。抓住国庆节这一重要时间节点，广泛开展“我和我的祖国”系列主题活动，通过主题宣讲、大合唱、共和国故事汇、快闪、灯光秀、游园活动等形式，引导人们歌唱祖国、致敬祖国、祝福祖国，使国庆黄金周成为爱国活动周。充分运用“七一”党的生日、“八一”建军节等时间节点，广泛深入组织各种纪念活动，唱响共产党好、人民军队好的主旋律。在中国人民抗日战争胜利纪念日、烈士纪念日、南京大屠杀死难者国家公祭日期间，精心组织公祭、瞻仰纪念碑、祭扫烈士墓等，引导人们牢记历史、不忘过去，缅怀先烈、面向未来，激发爱国热情、凝聚奋进力量。\n24．发挥传统和现代节日的涵育功能。大力实施中国传统节日振兴工程，深化“我们的节日”主题活动，利用春节、元宵、清明、端午、七夕、中秋、重阳等重要传统节日，开展丰富多彩、积极健康、富有价值内涵的民俗文化活动，引导人们感悟中华文化、增进家国情怀。结合元旦、“三八”国际妇女节、“五一”国际劳动节、“五四”青年节、“六一”国际儿童节和中国农民丰收节等，开展各具特色的庆祝活动，激发人们的爱国主义和集体主义精神。\n25．依托自然人文景观和重大工程开展教育。寓爱国主义教育于游览观光之中，通过宣传展示、体验感受等多种方式，引导人们领略壮美河山，投身美丽中国建设。系统梳理传统文化资源，加强考古发掘和整理研究，保护好文物古迹、传统村落、民族村寨、传统建筑、农业遗迹、灌溉工程遗产、工业遗迹，推动遗产资源合理利用，健全非物质文化遗产保护制度，推进国家文化公园建设。推动文化和旅游融合发展，提升旅游质量水平和文化内涵，深入挖掘旅游资源中蕴含的爱国主义内容，防止过度商业行为和破坏性开发。推动红色旅游内涵式发展，完善全国红色旅游经典景区体系，凸显教育功能，加强对讲解员、导游等从业人员的管理培训，加强对解说词、旅游项目等的规范，坚持正确的历史观和历史标准。依托国家重大建设工程、科学工程等，建设一批展现新时代风采的主题教育基地。","level":1},{"name":"五、营造新时代爱国主义教育的浓厚氛围","text":"26．用好报刊广播影视等大众传媒。各级各类媒体要聚焦爱国主义主题，创新方法手段，适应分众化、差异化传播趋势，使爱国主义宣传报道接地气、有生气、聚人气，有情感、有深度、有温度。把爱国主义主题融入贯穿媒体融合发展，打通网上网下、版面页面，推出系列专题专栏、新闻报道、言论评论以及融媒体产品，加强县级融媒体中心建设，生动讲好爱国故事、大力传播主流价值观。制作刊播爱国主义优秀公益广告作品，在街头户外张贴悬挂展示标语口号、宣传挂图，生动形象做好宣传。坚持正确舆论导向，对虚无历史、消解主流价值的错误思想言论，及时进行批驳和辨析引导。\n27．发挥先进典型的引领作用。大力宣传为中华民族和中国人民作出贡献的英雄，宣传革命、建设、改革时期涌现出的英雄烈士和模范人物，宣传时代楷模、道德模范、最美人物和身边好人，宣传具有爱国情怀的地方先贤、知名人物，以榜样的力量激励人、鼓舞人。广泛开展向先进典型学习活动，引导人们把敬仰和感动转化为干事创业、精忠报国的实际行动。做好先进模范人物的关心帮扶工作，落实相关待遇和礼遇，在全社会大力营造崇尚英雄、学习英雄、捍卫英雄、关爱英雄的浓厚氛围。\n28．创作生产优秀文艺作品。把爱国主义作为常写常新的主题，加大现实题材创作力度，为时代画像、为时代立传、为时代明德，不断推出讴歌党、讴歌祖国、讴歌人民、讴歌劳动、讴歌英雄的精品力作。深入实施中国当代文学艺术创作工程、重大历史题材创作工程等，加大对爱国主义题材文学创作、影视创作、词曲创作等的支持力度，加强对经典爱国歌曲、爱国影片的深入挖掘和创新传播，唱响爱国主义正气歌。文艺创作和评论评奖要具有鲜明爱国主义导向，倡导讲品位、讲格调、讲责任，抵制低俗、庸俗、媚俗，坚决反对亵渎祖先、亵渎经典、亵渎英雄，始终保持社会主义文艺的爱国底色。\n29．唱响互联网爱国主义主旋律。加强爱国主义网络内容建设，广泛开展网上主题教育活动，制作推介体现爱国主义内容、适合网络传播的音频、短视频、网络文章、纪录片、微电影等，让爱国主义充盈网络空间。实施爱国主义数字建设工程，推动爱国主义教育基地、红色旅游与网络传播有机结合。创新传播载体手段，积极运用微博微信、社交媒体、视频网站、手机客户端等传播平台，运用虚拟现实、增强现实、混合现实等新技术新产品，生动活泼开展网上爱国主义教育。充分发挥“学习强国”学习平台在爱国主义宣传教育中的作用。加强网上舆论引导，依法依规进行综合治理，引导网民自觉抵制损害国家荣誉、否定中华优秀传统文化的错误言行，汇聚网上正能量。\n30．涵养积极进取开放包容理性平和的国民心态。加强宣传教育，引导人们正确把握中国与世界的发展大势，正确认识中国与世界的关系，既不妄自尊大也不妄自菲薄，做到自尊自信、理性平和。爱国主义是世界各国人民共有的情感，实现世界和平与发展是各国人民共同的愿望。一方面要弘扬爱国主义精神，另一方面要培养海纳百川、开放包容的胸襟，大力宣传坚持和平发展合作共赢、构建人类命运共同体、共建“一带一路”等重要理念和倡议，激励广大人民同各国人民一道共同创造美好未来。对每一个中国人来说，爱国是本分，也是职责，是心之所系、情之所归。倡导知行合一，推动爱国之情转化为实际行动，使人们理性表达爱国情感，反对极端行为。\n31．强化制度和法治保障。把爱国主义精神融入相关法律法规和政策制度，体现到市民公约、村规民约、学生守则、行业规范、团体章程等的制定完善中，发挥指引、约束和规范作用。在全社会深入学习宣传宪法、英雄烈士保护法、文物保护法等，广泛开展法治文化活动，使普法过程成为爱国主义教育过程。严格执法司法、推进依法治理，综合运用行政、法律等手段，对不尊重国歌国旗国徽等国家象征与标志，对侵害英雄烈士姓名、肖像、名誉、荣誉等行为，对破坏污损爱国主义教育场所设施，对宣扬、美化侵略战争和侵略行为等，依法依规进行严肃处理。依法严惩暴力恐怖、民族分裂等危害国家安全和社会稳定的犯罪行为。","level":1},{"name":"六、加强对新时代爱国主义教育的组织领导","text":"32．各级党委和政府要承担起主体责任。各级党委和政府要负起政治责任和领导责任，把爱国主义教育摆上重要日程，纳入意识形态工作责任制，加强阵地建设和管理，抓好各项任务落实。进一步健全党委统一领导、党政齐抓共管、宣传部门统筹协调、有关部门各负其责的工作格局，建立爱国主义教育联席会议制度，加强工作指导和沟通协调，及时研究解决工作中的重要事项和存在问题。广大党员干部要以身作则，牢记初心使命，勇于担当作为，发挥模范带头作用，做爱国主义的坚定弘扬者和实践者，同违背爱国主义的言行作坚决斗争。\n33．调动广大人民群众的积极性主动性。爱国主义教育是全民教育，必须突出教育的群众性。各级工会、共青团、妇联和文联、作协、科协、侨联、残联以及关工委等人民团体和群众组织，要发挥各自优势，面向所联系的领域和群体广泛开展爱国主义教育。组织动员老干部、老战士、老专家、老教师、老模范等到广大群众特别是青少年中讲述亲身经历，弘扬爱国传统。坚持热在基层、热在群众，结合人们生产生活，把爱国主义教育融入到新时代文明实践中心建设、学雷锋志愿服务、精神文明创建之中，体现到百姓宣讲、广场舞、文艺演出、邻居节等群众性活动之中，引导人们自我宣传、自我教育、自我提高。\n34．求真务实注重实效。爱国主义教育是思想的洗礼、精神的熏陶。要坚持目标导向、问题导向、效果导向，坚持虚功实做、久久为功，在深化、转化上下功夫，在具象化、细微处下功夫，更好地体现时代性、把握规律性、富于创造性。坚持从实际出发，务实节俭开展教育、组织活动，杜绝铺张浪费，不给基层和群众增加负担，坚决反对形式主义、官僚主义。\n各地区各部门要根据本纲要制定贯彻落实的具体措施，确保爱国主义教育各项任务要求落到实处。\n中国人民解放军和中国人民武装警察部队按照本纲要总的要求，结合部队实际制定具体规划、作出安排部署。\n延伸阅读\n凝聚奋进新时代实现民族复兴的磅礴伟力——中央宣传部负责人就《新时代爱国主义教育实施纲要》答记者问\n人民日报评论员：让爱国主义精神牢牢扎根","level":1}]},{"id":"r0526","sections":[{"name":"关于加强和改进乡村治理的指导意见","text":"近日，中共中央办公厅、国务院办公厅印发《关于加强和改进乡村治理的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于加强和改进乡村治理的指导意见》全文如下。\n实现乡村有效治理是乡村振兴的重要内容。为深入贯彻落实党的十九大精神和《中共中央、国务院关于实施乡村振兴战略的意见》部署要求，推进乡村治理体系和治理能力现代化，夯实乡村振兴基层基础，现就加强和改进乡村治理提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，按照实施乡村振兴战略的总体要求，坚持和加强党对乡村治理的集中统一领导，坚持把夯实基层基础作为固本之策，坚持把治理体系和治理能力建设作为主攻方向，坚持把保障和改善农村民生、促进农村和谐稳定作为根本目的，建立健全党委领导、政府负责、社会协同、公众参与、法治保障、科技支撑的现代乡村社会治理体制，以自治增活力、以法治强保障、以德治扬正气，健全党组织领导的自治、法治、德治相结合的乡村治理体系，构建共建共治共享的社会治理格局，走中国特色社会主义乡村善治之路，建设充满活力、和谐有序的乡村社会，不断增强广大农民的获得感、幸福感、安全感。\n（二）总体目标。到2020年，现代乡村治理的制度框架和政策体系基本形成，农村基层党组织更好发挥战斗堡垒作用，以党组织为领导的农村基层组织建设明显加强，村民自治实践进一步深化，村级议事协商制度进一步健全，乡村治理体系进一步完善。到2035年，乡村公共服务、公共管理、公共安全保障水平显著提高，党组织领导的自治、法治、德治相结合的乡村治理体系更加完善，乡村社会治理有效、充满活力、和谐有序，乡村治理体系和治理能力基本实现现代化。","level":1},{"name":"二、主要任务","text":"（一）完善村党组织领导乡村治理的体制机制。建立以基层党组织为领导、村民自治组织和村务监督组织为基础、集体经济组织和农民合作组织为纽带、其他经济社会组织为补充的村级组织体系。村党组织全面领导村民委员会及村务监督委员会、村集体经济组织、农民合作组织和其他经济社会组织。村民委员会要履行基层群众性自治组织功能，增强村民自我管理、自我教育、自我服务能力。村务监督委员会要发挥在村务决策和公开、财产管理、工程项目建设、惠农政策措施落实等事项上的监督作用。集体经济组织要发挥在管理集体资产、合理开发集体资源、服务集体成员等方面的作用。农民合作组织和其他经济社会组织要依照国家法律和各自章程充分行使职权。村党组织书记应当通过法定程序担任村民委员会主任和村级集体经济组织、合作经济组织负责人，村“两委”班子成员应当交叉任职。村务监督委员会主任一般由党员担任，可以由非村民委员会成员的村党组织班子成员兼任。村民委员会成员、村民代表中党员应当占一定比例。健全村级重要事项、重大问题由村党组织研究讨论机制，全面落实“四议两公开”。加强基本队伍、基本活动、基本阵地、基本制度、基本保障建设，实施村党组织带头人整体优化提升行动，持续整顿软弱涣散村党组织，整乡推进、整县提升，发展壮大村级集体经济。全面落实村“两委”换届候选人县级联审机制，坚决防止和查处以贿选等不正当手段影响、控制村“两委”换届选举的行为，严厉打击干扰破坏村“两委”换届选举的黑恶势力、宗族势力。坚决把受过刑事处罚、存在“村霸”和涉黑涉恶、涉邪教等问题的人清理出村干部队伍。坚持抓乡促村，落实县乡党委抓农村基层党组织建设和乡村治理的主体责任。落实乡镇党委直接责任，乡镇党委书记和党委领导班子成员等要包村联户，村“两委”成员要入户走访，及时发现并研究解决农村基层党组织建设、乡村治理和群众生产生活等问题。健全以财政投入为主的稳定的村级组织运转经费保障制度。\n（二）发挥党员在乡村治理中的先锋模范作用。组织党员在议事决策中宣传党的主张，执行党组织决定。组织开展党员联系农户、党员户挂牌、承诺践诺、设岗定责、志愿服务等活动，推动党员在乡村治理中带头示范，带动群众全面参与。密切党员与群众的联系，了解群众思想状况，帮助解决实际困难，加强对贫困人口、低保对象、留守儿童和妇女、老年人、残疾人、特困人员等人群的关爱服务，引导农民群众自觉听党话、感党恩、跟党走。\n（三）规范村级组织工作事务。清理整顿村级组织承担的行政事务多、各种检查评比事项多问题，切实减轻村级组织负担。各种政府机构原则上不在村级建立分支机构，不得以行政命令方式要求村级承担有关行政性事务。交由村级组织承接或协助政府完成的工作事项，要充分考虑村级组织承接能力，实行严格管理和总量控制。从源头上清理规范上级对村级组织的考核评比项目，鼓励各地实行目录清单、审核备案等管理方式。规范村级各种工作台账和各类盖章证明事项。推广村级基础台账电子化，建立统一的“智慧村庄”综合管理服务平台。\n（四）增强村民自治组织能力。健全党组织领导的村民自治机制，完善村民（代表）会议制度，推进民主选举、民主协商、民主决策、民主管理、民主监督实践。进一步加强自治组织规范化建设，拓展村民参与村级公共事务平台，发展壮大治保会等群防群治力量，充分发挥村民委员会、群防群治力量在公共事务和公益事业办理、民间纠纷调解、治安维护协助、社情民意通达等方面的作用。\n（五）丰富村民议事协商形式。健全村级议事协商制度，形成民事民议、民事民办、民事民管的多层次基层协商格局。创新协商议事形式和活动载体，依托村民会议、村民代表会议、村民议事会、村民理事会、村民监事会等，鼓励农村开展村民说事、民情恳谈、百姓议事、妇女议事等各类协商活动。\n（六）全面实施村级事务阳光工程。完善党务、村务、财务“三公开”制度，实现公开经常化、制度化和规范化。梳理村级事务公开清单，及时公开组织建设、公共服务、脱贫攻坚、工程项目等重大事项。健全村务档案管理制度。推广村级事务“阳光公开”监管平台，支持建立“村民微信群”、“乡村公众号”等，推进村级事务即时公开，加强群众对村级权力有效监督。规范村级会计委托代理制，加强农村集体经济组织审计监督，开展村干部任期和离任经济责任审计。\n（七）积极培育和践行社会主义核心价值观。坚持教育引导、实践养成、制度保障三管齐下，推动社会主义核心价值观落细落小落实，融入文明公约、村规民约、家规家训。通过新时代文明实践中心、农民夜校等渠道，组织农民群众学习习近平新时代中国特色社会主义思想，广泛开展中国特色社会主义和实现中华民族伟大复兴的中国梦宣传教育，用中国特色社会主义文化、社会主义思想道德牢牢占领农村思想文化阵地。完善乡村信用体系，增强农民群众诚信意识。推动农村学雷锋志愿服务制度化常态化。加强农村未成年人思想道德建设。\n（八）实施乡风文明培育行动。弘扬崇德向善、扶危济困、扶弱助残等传统美德，培育淳朴民风。开展好家风建设，传承传播优良家训。全面推行移风易俗，整治农村婚丧大操大办、高额彩礼、铺张浪费、厚葬薄养等不良习俗。破除丧葬陋习，树立殡葬新风，推广与保护耕地相适应、与现代文明相协调的殡葬习俗。加强村规民约建设，强化党组织领导和把关，实现村规民约行政村全覆盖。依靠群众因地制宜制定村规民约，提倡把喜事新办、丧事简办、弘扬孝道、尊老爱幼、扶残助残、和谐敦睦等内容纳入村规民约。以法律法规为依据，规范完善村规民约，确保制定过程、条文内容合法合规，防止一部分人侵害另一部分人的权益。建立健全村规民约监督和奖惩机制，注重运用舆论和道德力量促进村规民约有效实施，对违背村规民约的，在符合法律法规前提下运用自治组织的方式进行合情合理的规劝、约束。发挥红白理事会等组织作用。鼓励地方对农村党员干部等行使公权力的人员，建立婚丧事宜报备制度，加强纪律约束。\n（九）发挥道德模范引领作用。深入实施公民道德建设工程，加强社会公德、职业道德、家庭美德和个人品德教育。大力开展文明村镇、农村文明家庭、星级文明户、五好家庭等创建活动，广泛开展农村道德模范、最美邻里、身边好人、新时代好少年、寻找最美家庭等选树活动，开展乡风评议，弘扬道德新风。\n（十）加强农村文化引领。加强基层文化产品供给、文化阵地建设、文化活动开展和文化人才培养。传承发展提升农村优秀传统文化，加强传统村落保护。结合传统节日、民间特色节庆、农民丰收节等，因地制宜广泛开展乡村文化体育活动。加快乡村文化资源数字化，让农民共享城乡优质文化资源。挖掘文化内涵，培育乡村特色文化产业，助推乡村旅游高质量发展。加强农村演出市场管理，营造健康向上的文化环境。\n（十一）推进法治乡村建设。规范农村基层行政执法程序，加强乡镇行政执法人员业务培训，严格按照法定职责和权限执法，将政府涉农事项纳入法治化轨道。大力开展“民主法治示范村”创建，深入开展“法律进乡村”活动，实施农村“法律明白人”培养工程，培育一批以村干部、人民调解员为重点的“法治带头人”。深入开展农村法治宣传教育。\n（十二）加强平安乡村建设。推进农村社会治安防控体系建设，落实平安建设领导责任制，加强基础性制度、设施、平台建设。加强农村警务工作，大力推行“一村一辅警”机制，扎实开展智慧农村警务室建设。加强对社区矫正对象、刑满释放人员等特殊人群的服务管理。深入推进扫黑除恶专项斗争，健全防范打击长效机制。加强农民群众拒毒防毒宣传教育，依法打击整治毒品违法犯罪活动。依法加大对农村非法宗教活动、邪教活动打击力度，制止利用宗教、邪教干预农村公共事务，大力整治农村乱建宗教活动场所、滥塑宗教造像。推进农村地区技防系统建设，加强公共安全视频监控建设联网应用工作。健全农村公共安全体系，强化农村安全生产、防灾减灾救灾、食品、药品、交通、消防等安全管理责任。\n（十三）健全乡村矛盾纠纷调处化解机制。坚持发展新时代“枫桥经验”，做到“小事不出村、大事不出乡”。健全人民调解员队伍，加强人民调解工作。完善调解、仲裁、行政裁决、行政复议、诉讼等有机衔接、相互协调的多元化纠纷解决机制。发挥信息化支撑作用，探索建立“互联网+网格管理”服务管理模式，提升乡村治理智能化、精细化、专业化水平。强化乡村信息资源互联互通，完善信息收集、处置、反馈工作机制和联动机制。广泛开展平安教育和社会心理健康服务、婚姻家庭指导服务。推动法院跨域立案系统、检察服务平台、公安综合窗口、人民调解组织延伸至基层，提高响应群众诉求和为民服务能力水平。\n（十四）加大基层小微权力腐败惩治力度。规范乡村小微权力运行，明确每项权力行使的法规依据、运行范围、执行主体、程序步骤。建立健全小微权力监督制度，形成群众监督、村务监督委员会监督、上级部门监督和会计核算监督、审计监督等全程实时、多方联网的监督体系。织密农村基层权力运行“廉政防护网”，大力开展农村基层微腐败整治，推进农村巡察工作，严肃查处侵害农民利益的腐败行为。\n（十五）加强农村法律服务供给。充分发挥人民法庭在乡村治理中的职能作用，推广车载法庭等巡回审判方式。加强乡镇司法所建设。整合法学专家、律师、政法干警及基层法律服务工作者等资源，健全乡村基本公共法律服务体系。深入推进公共法律服务实体、热线、网络平台建设，鼓励乡镇党委和政府根据需要设立法律顾问和公职律师，鼓励有条件的地方在村民委员会建立公共法律服务工作室，进一步加强村法律顾问工作，完善政府购买服务机制，充分发挥律师、基层法律服务工作者等在提供公共法律服务、促进乡村依法治理中的作用。\n（十六）支持多方主体参与乡村治理。加强妇联、团支部、残协等组织建设，充分发挥其联系群众、团结群众、组织群众参与民主管理和民主监督的作用。积极发挥服务性、公益性、互助性社区社会组织作用。坚持专业化、职业化、规范化，完善培养选拔机制，拓宽农村社工人才来源，加强农村社会工作专业人才队伍建设，着力做好老年人、残疾人、青少年、特殊困难群体等重点对象服务工作。探索以政府购买服务等方式，支持农村社会工作和志愿服务发展。\n（十七）提升乡镇和村为农服务能力。充分发挥乡镇服务农村和农民的作用，加强乡镇政府公共服务职能，加大乡镇基本公共服务投入，使乡镇成为为农服务的龙头。推进“放管服”改革和“最多跑一次”改革向基层延伸，整合乡镇和县级部门派驻乡镇机构承担的职能相近、职责交叉工作事项，建立集综合治理、市场监管、综合执法、公共服务等于一体的统一平台。构建县乡联动、功能集成、反应灵敏、扁平高效的综合指挥体系，着力增强乡镇统筹协调能力，发挥好乡镇服务、带动乡村作用。大力推进农村社区综合服务设施建设，引导管理服务向农村基层延伸，为农民提供“一门式办理”、“一站式服务”，构建线上线下相结合的乡村便民服务体系。将农村民生和社会治理领域中属于政府职责范围且适合通过市场化方式提供的服务事项，纳入政府购买服务指导性目录。推动各级投放的公共服务资源以乡镇、村党组织为主渠道落实。","level":1},{"name":"三、组织实施","text":"（一）加强组织领导。各级党委和政府要充分认识加强和改进乡村治理的重要意义，把乡村治理工作摆在重要位置，纳入经济社会发展总体规划和乡村振兴战略规划，开展乡村治理试点示范，及时研究解决工作中遇到的重大问题。将加强和改进乡村治理工作纳入乡村振兴考核。将党组织领导的乡村治理工作作为每年市县乡党委书记抓基层党建述职评议考核的重要内容，推动层层落实责任。各省（自治区、直辖市）党委和政府要抓好本意见贯彻落实，每年向党中央、国务院报告推进实施乡村振兴战略进展情况时，要将乡村治理工作情况作为重要内容。\n（二）建立协同推进机制。严格落实责任，加强部门联动，建立乡村治理工作协同运行机制。党委农村工作部门要发挥牵头抓总作用，强化统筹协调、具体指导和督促落实，对乡村治理工作情况开展督导，对乡村治理政策措施开展评估。组织、宣传、政法、民政、司法行政、公安等相关部门要按照各自职责，强化政策、资源和力量配备，加强工作指导，做好协同配合，形成工作合力。\n（三）强化各项保障。各级党委和政府要加强乡村治理人才队伍建设，充实基层治理力量，指导驻村第一书记、驻村干部等围绕乡村治理主要任务开展工作，聚合各类人才资源，引导农村致富能手、外出务工经商人员、高校毕业生、退役军人等在乡村治理中发挥积极作用。加强乡村社会治安综合治理设施装备保障，落实乡村治理经费。切实保障村干部基本报酬，建立健全与绩效考核相挂钩的报酬兑现机制。有计划、分层次开展村干部培训。坚决整治形式主义、官僚主义，让基层干部从繁文缛节、文山会海、迎来送往中解脱出来。进一步激励干部新时代新担当新作为，鼓励各地创新乡村治理机制。组织开展乡村治理示范村镇创建活动，大力选树宣传乡村治理各类先进典型，营造良好舆论氛围。\n（四）加强分类指导。各级党委和政府要结合本地实际，围绕加强和改进乡村治理的主要任务，分类确定落实举措。对于需要普遍执行和贯彻落实的政策措施，要加大工作力度，逐级压实责任，明确时间进度，尽快取得实效。对于需要继续探索的事项，要组织开展改革试点，勇于探索创新，及时总结一批可复制可推广的经验做法，加快在面上推广。对于鼓励提倡的做法，要有针对性地借鉴吸收，形成适合本地的乡村治理机制。","level":1}]},{"id":"r0527","sections":[{"name":"中共中央办公厅印发《关于在推进事业单位改革中加强和改进党的建设工作的意见》","text":"近日，中共中央办公厅印发了《关于在推进事业单位改革中加强和改进党的建设工作的意见》，并发出通知，要求各地区各部门结合实际认真贯彻执行。","level":1},{"name":"","text":"《关于在推进事业单位改革中加强和改进党的建设工作的意见》全文如下。\n认真落实《中共中央、国务院关于分类推进事业单位改革的指导意见》精神，积极稳妥推进事业单位改革，促进公益事业更好更快发展，必须坚持和加强党的领导，全面加强党的建设，充分发挥党组织在事业单位中的政治、思想、组织保证作用。现就在推进事业单位改革中加强和改进党的建设工作提出如下意见。\n一、准确把握在推进事业单位改革中加强和改进党的建设工作的总体要求与目标任务\n1.总体要求。高举中国特色社会主义伟大旗帜，以邓小平理论和“三个代表”重要思想为指导，深入贯彻落实科学发展观，紧紧围绕加强党的执政能力建设和先进性建设，以确保事业单位改革正确方向、推动事业单位健康发展为目标，以改革创新为动力，全面加强事业单位党的思想、组织、作风、制度和反腐倡廉建设，着力健全事业单位党的领导体制和工作机制，不断提高事业单位党的建设科学化水平，保证党的路线方针政策在事业单位全面贯彻落实。\n2.目标任务。把党的建设工作与事业单位改革发展紧密结合起来，同步规划，同步推进。围绕分类推进事业单位改革阶段性目标要求，对承担行政职能的事业单位和从事生产经营活动的事业单位，已转为行政机构或企业的，要分别按照机关党建工作和企业党建工作的要求，及时调整和优化党组织设置，理顺隶属关系，开展党组织活动，实现党建工作平稳过渡、有序衔接；已明确转为行政机构或企业但尚未调整到位的，以及明确予以撤销或调整的单位，在过渡期内要继续按照现有规定和要求抓好党建工作，确保党的工作不间断、党组织作用不削弱，党员先锋模范作用得到充分发挥。对继续保留、从事公益服务的事业单位，要根据不同行业、不同类型、不同管理体制的特点和要求，进一步加强和改进党的建设工作，使党组织体系健全、设置合理、制度完善、机制灵活，领导班子和人才队伍充满活力，基层党组织和党员队伍作用充分发挥，形成与中国特色公益服务体系相适应的事业单位党建工作新格局。\n二、进一步明确事业单位党组织的职责要求\n3.实行党委领导下的行政领导人负责制的事业单位，党组织发挥领导核心作用。认真履行党章和有关规定明确的职责任务，按照把方向、议大事、管全局的要求，统一领导本单位工作。坚持和完善民主集中制，改进领导方式和工作方式，健全议事规则和决策程序，坚持重大问题集体讨论决定，不断提高科学决策、民主决策、依法决策水平。健全集体领导和个人分工负责相结合制度，正确处理党政关系，既充分发挥党组织的领导核心作用，又切实保证行政领导人充分行使职权。党组织特别是书记要把抓班子带队伍、抓党建强基础摆在突出位置，切实做好党的建设各项工作。行政领导人要自觉接受党组织领导，认真贯彻党组织决议、决定，按照分工抓好集体决策事项的组织实施。设立党组的事业单位，党组要按照党章和其他党内法规的有关规定，充分发挥领导核心作用。\n4.实行行政领导人负责制的事业单位，党组织发挥政治核心作用。认真履行党章和有关规定明确的职责任务，按照参与决策、推动发展、监督保障的要求，会同行政领导班子共同做好本单位工作。凡涉及本单位改革发展稳定和事关职工群众切身利益的重大决策、重要人事任免、重大项目安排、大额度资金使用事项，党组织必须参与决策。决策前，党政主要领导对决策议题要充分酝酿、沟通协调，党组织要及时召开会议研究讨论，形成集体意见；决策时，参加会议的党组织领导成员要认真履行职责，保证党组织的意见得到充分表达和体现；决策后，党组织要发动党员团结带领职工保证决策顺利实施。各单位要将党组织参与重大问题决策的内容和程序具体化、制度化。采取党政联席会议等方式对本单位重大问题进行决策的，要在实践中不断完善联席会议运行机制。坚持党管干部原则，在选人用人中发挥党组织的主导作用，按照干部管理权限切实履行把握用人条件、提出推荐人选、做好组织考察、加强管理监督、培养后备人才等职责。围绕确保党的路线方针政策和国家法律法规在本单位贯彻执行，完善相关制度和措施，积极发挥监督保障作用。行政领导人要强化组织观念和纪律意识，坚持民主决策，定期向党组织通报有关工作，紧紧依靠党组织和广大职工群众共同做好单位改革发展稳定工作。对不符合党的路线方针政策、国家法律法规或不按程序进行决策的做法，党组织要及时提出意见或向上级党组织报告。\n三、不断提高事业单位领导班子和领导人员推动科学发展、做好公益服务的能力水平\n5.着力选好配强事业单位领导班子。坚持五湖四海、任人唯贤，坚持德才兼备、以德为先，坚持民主、公开、竞争、择优，进一步深化事业单位人事制度改革，大力选拔政治坚定、业务过硬、敢抓善管、廉洁奉公、实绩突出、群众公认的优秀人才进入领导班子。根据不同行业、不同类型事业单位的特点和改革发展稳定的要求，选好配强党组织书记和行政主要领导人，优化班子结构，增强整体功能。实行党委领导下的行政领导人负责制的事业单位，应配备党组织专职书记和副书记，党员行政主要领导人一般应担任党组织领导职务。实行行政领导人负责制的事业单位，党组织书记和行政主要领导由同一人担任的，一般应配备1名专职副书记；党组织书记和行政主要领导分开任职的，党组织书记一般应兼任行政副职，党员行政主要领导人一般应进入党组织领导班子。建立法人治理结构的事业单位，要健全“双向进入、交叉任职”配备方式，党组织领导班子成员按照事业单位章程进入理事会和管理层，理事会和管理层中的党员领导人员按照党内有关规定进入党组织领导班子。理事会和管理层成员的任用与管理，按照干部管理权限和事业单位章程办理。\n6.加强事业单位领导班子思想政治建设。加强中国特色社会主义理论体系学习教育，引导领导班子成员增强政治意识、大局意识、责任意识，树立正确的世界观、权力观、事业观，加强自我修养，带头践行社会主义核心价值体系。加强群众观点和群众路线学习教育，引导领导班子成员从群众利益出发，强化服务意识，改进工作作风，克服短期行为，提高为人民群众做好公益服务的水平。加强民主集中制学习教育，引导领导班子成员发扬民主、坚持原则，顾大局、守纪律、讲团结，严格按制度和规定办事，增强领导班子的凝聚力和战斗力。完善领导班子中心组学习等制度，加强对学习情况的督促、检查和考核，不断提高领导班子成员的思想政治素质。\n7.加强对事业单位领导人员的管理。抓紧研究制定符合不同行业特点的事业单位领导人员管理办法和综合考核评价办法，明确要求，规范程序，改进方法，严肃纪律，强化管理。结合事业单位特点，有针对性地开展领导人员在职岗位培训、任职培训和专业培训。建立健全交流制度，大力推进事业单位与党政机关、国有企业之间领导人员的合理流动和优化配置。认真执行民主生活会、组织生活会、述职述廉、诫勉谈话、函询、巡视等制度，建立健全领导班子民主决策制度和领导人员责任追究制度，充分发挥党内监督、专门机关监督、群众监督和舆论监督作用，防止权力滥用。完善惩治和预防腐败体系，认真抓好领导人员廉洁自律工作，严肃查办各类违纪违法案件，扎实推进反腐倡廉建设。\n8.加强事业单位人才队伍建设。完善政策措施，整合工作力量，营造良好环境，加强和改进党对事业单位人才工作的领导。深入贯彻落实《国家中长期人才发展规划纲要（2010—2020年）》，制定并实施行业人才队伍建设规划，突出培养社会事业各行业、各领域领军人才和创新人才，大力开发紧缺人才和专门人才，重视培养和大胆使用青年人才，统筹推进各类人才队伍建设。针对各行业、各领域人才的不同特点和成长规律，完善育才、引才、聚才、用才工作机制，建立健全与教育、科技、文化、卫生等社会事业发展要求相适应的人才管理制度。事业单位党组织要紧紧围绕人才培养、吸引、使用等关键环节，改进人才管理和服务方式，不断激发人才干事创业活力，使各类人才在推动公益事业发展中充分施展才干。\n四、着力增强事业单位基层党组织创造力、凝聚力和战斗力\n9.积极推进事业单位基层党组织工作创新。适应事业单位改革发展要求，进一步增强基层党组织服务功能，通过为本单位中心工作服务、为广大党员服务、为职工群众服务，把党建工作的成效体现到推动发展、服务群众、凝聚人心、促进和谐上来。大力推进学习型党组织建设，积极拓展学习内容、途径和渠道，不断在武装头脑、指导实践、推动工作上取得新进展。把党的建设与推动社会主义文化大发展大繁荣紧密结合起来，努力建设和弘扬先进文化，自觉抵制各种错误思想影响，切实增强文化自觉和文化自信，为事业单位改革发展提供精神动力。加强党内基层民主建设，推进党务公开，建立健全党内情况通报等制度，扩大党员对党内事务的了解和参与，切实保障党员的民主权利。充分运用网络、手机等手段，推进基层党建工作信息化，构建开放互动的基层党组织活动平台。\n10.改进事业单位党员教育、管理、服务和发展党员工作。以增强党性、提高素质为目标，建立和完善党员轮训制度，拓宽党员培训渠道，加强对党员的党性教育和业务培训。严格党的组织生活，落实“三会一课”制度，建立和完善党员党性定期分析制度，做好民主评议党员工作，及时处置不合格党员，保持党员队伍纯洁性。健全党内激励、关怀、帮扶机制，注意发现、培养和树立先进典型，加强对老党员、生活困难党员的关怀帮扶，进一步做好流动党员服务管理工作。严格标准、注重质量，加大在青年岗位能手、优秀青年知识分子中发展党员力度，重视在学科带头人、业务骨干中发展党员，不断优化党员队伍结构。\n11.加强和改进事业单位思想政治工作。事业单位党组织要从本单位实际出发，创新思想政治工作内容、方法和载体，增强针对性和实效性。围绕推进事业单位改革，加强学习宣传和思想教育，有针对性地做好解疑释惑工作，引导党员、职工正确认识、大力支持、积极参与改革。紧密联系工作实际，深入开展社会主义核心价值体系教育，大力加强职业道德建设和作风建设，不断增强党员、职工服务社会、服务群众的责任感。重视党员、职工提出的合理要求，及时做好矛盾化解和情绪疏导等工作，切实维护他们的合法权益。积极发挥基层党组织在加强和创新社会管理中的重要作用，主动了解掌握社会和群众对公益服务的意见建议，努力为群众办实事、做好事、解难事，不断增强党组织的感召力和影响力。充分发挥工会、共青团等群众组织的桥梁和纽带作用，共同做好经常性思想政治工作。\n12.深入开展创先争优活动。根据事业单位特点找准为民服务的着力点，不断深化和拓展创先争优活动。围绕增强服务意识、提高服务水平，精心设计贴近实际、特色鲜明的争创主题和形式多样、务实管用的活动载体，充分发挥基层党组织战斗堡垒作用和党员先锋模范作用，带动所在单位和职工努力做好服务社会、服务群众工作。完善公开承诺、群众评议、党员互评、领导点评等制度，建立健全激发创先争优内生动力的长效机制，使为民服务创先争优成为广大党员、职工的共同价值追求。\n五、加强对事业单位党的建设工作的领导\n13.全面落实事业单位党建工作责任制。地方各级党委和行业主管部门党组（党委）要把事业单位党建工作摆上重要位置，健全党委统一领导、组织部门牵头协调、主管部门具体负责、有关方面齐抓共管的领导体制和工作格局，一级抓一级，层层抓落实。各地区、各行业主管部门要结合各自实际，制定本地区、本行业加强和改进事业单位党建工作实施意见。事业单位党组织要全面抓好党建工作各项任务落实，党组织书记要切实履行党建工作第一责任人职责，担任党内职务的行政领导人要落实“一岗双责”要求，积极做好党建工作。\n14.建设一支政治坚定、素质优良、精干高效的党务工作队伍。根据单位规模和党员人数，健全党组织工作机构，配备必要工作人员，保证专职党务工作人员编制和职级待遇，为他们开展工作和成长进步创造良好条件。加强对党务工作人员教育培训和实践锻炼，努力使他们成为既精通党务和思想政治工作、又熟悉业务和管理工作的复合型人才。把党务工作岗位作为培养人才的重要平台，注重选拔有党务工作经历的同志担任行政领导人，注重从业务骨干中选拔优秀人才充实党务工作队伍。\n15.为事业单位党建工作创造良好条件。加大党建工作投入，将党建工作经费列入事业单位年度经费预算，保障党组织工作和活动正常开展，具体额度根据实际情况确定。强化阵地建设，通过单独建、联合建等方式健全党员学习和活动场所。尊重和鼓励事业单位党组织勇于实践、积极探索，及时总结和推广事业单位党建工作的好经验好做法，定期评选和表彰事业单位先进党组织和党务工作者，充分发挥典型示范带动作用，促进整体工作水平提高。根据不同行业、不同类型事业单位的特点和实际，加强调查研究，实施分类指导，有针对性地提出加强和改进党建工作的意见和措施，使党的建设在改革中不断加强、在创新中不断发展。","level":0}]},{"id":"r0528","sections":[{"name":"中共中央办公厅印发《2019—2023年全国党员教育培训工作规划》","text":"近日，中共中央办公厅印发了《2019—2023年全国党员教育培训工作规划》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《2019—2023年全国党员教育培训工作规划》全文如下。\n为深入学习贯彻习近平新时代中国特色社会主义思想和党的十九大精神，切实提高党员教育培训工作质量，推进马克思主义学习型政党建设，根据《中国共产党章程》和有关党内法规，制定本规划。","level":0},{"name":"一、总体要求","text":"党员教育培训工作，以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，认真落实新时代党的建设总要求，把学习贯彻习近平新时代中国特色社会主义思想作为首要政治任务，以坚定信仰、增强党性、提高素质为重点，坚持思想建党、理论强党、从严治党，坚持围绕中心、服务大局，坚持分类指导、按需施教，坚持联系实际、继承创新，坚持简便易行、务实管用，不断增强针对性和有效性，引导党员增强“四个意识”、坚定“四个自信”、做到“两个维护”，努力建设政治合格、执行纪律合格、品德合格、发挥作用合格的党员队伍。\n从2019年开始，用5年时间，有计划分层次高质量开展党员教育培训，把全体党员普遍轮训一遍，实现以下工作目标。\n——习近平新时代中国特色社会主义思想学习教育更加扎实深入，党的创新理论更加入脑入心，广大党员自觉践行新思想、适应新时代、展现新作为，在习近平新时代中国特色社会主义思想指引下，统一意志、统一行动、步调一致向前进。\n——教育培训效果更加显著，广大党员理想信念进一步坚定、党性观念进一步增强、宗旨意识进一步强化、能力素质进一步提升、纪律作风进一步过硬、先锋模范作用进一步发挥。\n——新时代党员教育培训体系更加健全，集中培训逐步走向常态，日常教育更加规范，推动形成教育和管理、监督、服务有机结合的党员队伍建设工作链条。","level":1},{"name":"二、习近平新时代中国特色社会主义思想教育培训","text":"（一）把学习贯彻习近平新时代中国特色社会主义思想作为首要政治任务。各级党组织要将习近平新时代中国特色社会主义思想学习教育摆在党员教育培训最突出位置，县级以上党委每年制定学习计划，列出必读书目和篇目，明确学习要求，基层党组织要结合党员日常教育管理认真抓好落实。党员教育培训机构要将习近平新时代中国特色社会主义思想作为主课，全面纳入教学计划和教学布局。党员要把习近平新时代中国特色社会主义思想作为必修课，读原著、学原文、悟原理，深刻理解习近平新时代中国特色社会主义思想的重大意义、科学体系、丰富内涵、精神实质、实践要求，掌握贯穿其中的马克思主义立场观点方法，增强政治自觉、理论自信、情感融入，做到真学真懂真信真用。\n（二）建立健全习近平新时代中国特色社会主义思想学习教育长效机制。以习近平新时代中国特色社会主义思想为中心内容，建立较为完备的课程体系。加强理论教育特点和规律的研究，开发一批学习贯彻习近平新时代中国特色社会主义思想的教学案例和现场教学点。通过专题讲座、报告会、学习论坛等多种形式进行深入浅出的解读阐述，领导干部要结合分管领域、分管工作带头宣讲。发挥“两微一端”等新媒体优势，组织党员在线学习。注重发挥党支部直接教育党员的作用，落实“三会一课”等制度，对党员开展经常性教育。健全理论学习考核评估制度，采取有效措施激发党员学习热情，推动学习教育往深里走、往心里走、往实里走。\n（三）引导党员自觉做习近平新时代中国特色社会主义思想坚定信仰者和忠实实践者。弘扬理论联系实际的马克思主义学风，引导党员把自己摆进去、把职责摆进去、把工作摆进去，对照习近平新时代中国特色社会主义思想检视思想言行，做到学思用贯通、知信行统一。引导党员结合岗位职责，认真学习贯彻习近平总书记关于本部门本行业本领域工作的重要论述和重要指示批示精神，提高运用科学理论解决实际问题能力，更好推动事业发展。大力选树和宣传学懂弄通做实的先进典型，引导党员自觉用习近平新时代中国特色社会主义思想武装头脑、指导实践、推动工作。党员领导干部应当坚持更高标准、更严要求，带头学习实践习近平新时代中国特色社会主义思想。","level":1},{"name":"三、党员教育培训主要内容","text":"（一）聚焦基本任务。根据《中国共产党党员教育管理工作条例》，适应新时代党员队伍建设需要，突出政治功能，切实抓好习近平新时代中国特色社会主义思想教育培训，全面落实政治理论教育、政治教育和政治训练、党章党规党纪教育、党的宗旨教育、革命传统教育、形势政策教育、知识技能教育等7个方面基本任务，把党性教育和理想信念教育贯穿始终，以坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化为目标，对党员进行系统教育培训。\n（二）围绕中心工作。着眼统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，紧扣今后5年党和国家重大决策部署、重要会议活动、重要时间节点，有针对性地开展党员教育培训。结合“不忘初心、牢记使命”主题教育，重点加强党的创新理论、理想信念、政治纪律和政治规矩等教育培训；围绕贯彻落实新发展理念、实施七大战略、打好三大攻坚战等，重点加强党的路线方针政策、世情国情党情、总体国家安全观等教育培训；聚焦全面建成小康社会、中国共产党成立100周年，重点加强党史、新中国史，党的优良传统、中华优秀传统文化，社会主义核心价值观、爱国主义等教育培训，引导党员把思想和行动统一到党中央决策部署上来，始终保持奋斗精神和革命精神，敢于斗争、善于斗争，在时代大潮中建功立业。\n（三）体现不同领域和群体特点。在农村，重点围绕贯彻落实习近平总书记关于“三农”工作的重要论述、打赢脱贫攻坚战、实施乡村振兴战略、推进农业农村现代化开展党员教育培训。在街道社区，重点围绕巩固党在城市执政基础、加强城市治理、服务社区群众、建设美好家园开展党员教育培训。在机关，重点围绕建设让党中央放心、让人民群众满意的模范机关开展党员教育培训。在事业单位，重点围绕深化改革、提高绩效、促进事业发展开展党员教育培训，学校重点围绕坚持马克思主义指导地位、落实立德树人根本任务、培养社会主义建设者和接班人开展党员教育培训。在国有企业，重点围绕加强党对国有企业的领导、深化国有企业改革、实现国有资产保值增值开展党员教育培训。在非公有制经济组织，重点围绕贯彻党的方针政策、严格遵守国家法律法规、团结凝聚职工群众、维护各方合法权益、促进企业健康发展开展党员教育培训。在社会组织，重点围绕坚持正确政治方向、有序参与社会治理、提供公共服务、承担社会责任开展党员教育培训。民族地区要重点围绕贯彻党的民族政策、做好民族工作，对党员加强党的意识、中华民族共同体意识和马克思主义国家观、历史观、民族观、文化观、宗教观等教育培训。\n对基层党组织书记，重点开展党的创新理论、党建工作实务、群众工作、基层治理等教育培训，努力建设一支守信念、讲奉献、有本领、重品行的基层党组织带头人队伍。对新党员，重点开展党的基本知识、党性党风党纪、党的优良传统等教育培训，强化思想入党，提升他们的政治觉悟和理论素养。对青年党员，要进行系统理论教育和严格党性锻炼，引导他们传承红色基因、培养奋斗精神、练就过硬本领。对老年党员，重点开展党的创新理论、形势政策等教育培训，引导他们保持革命本色、发挥传帮带作用。对流动党员，重点开展党员意识、组织观念、纪律规矩等教育培训，引导他们主动接受党组织的教育管理，自觉参加组织生活，充分发挥作用。对下岗失业人员中的党员，要将党的理论教育和党性教育与开展政策学习和技能培训结合起来，帮助他们增强就业创业信心和能力。","level":1},{"name":"四、党员教育培训方式方法","text":"（一）完善组织形式。坚持集中培训、集体学习、个人自学和组织生活、实践锻炼有机结合，增强党员教育培训工作的规范性、针对性、系统性。要结合实际，研究确定重点项目、对象和专题，采取省级示范培训、市级重点培训、县级普遍培训、基层党委兜底培训的形式，开展党员集中培训。中央组织部要会同有关部门每年举办全国党员教育培训示范班。各级党组织要通过理论学习中心组学习、“三会一课”、主题党日等，抓实集体学习。党员领导干部要定期为基层党员讲党课。引导党员根据自身实际和工作需要，利用业余时间开展自学。坚持民主生活会和组织生活会、民主评议党员、谈心谈话等制度，认真开展批评和自我批评，咬耳扯袖、红脸出汗，让党的组织生活真正起到教育提高党员的作用。通过设岗定责、承诺践诺，引导党员立足岗位、创先争优。鼓励和引导党员参与结对帮扶、志愿服务等，为党员搭建实践锻炼平台。注重心理疏导和人文关怀，帮助解决实际问题，增强党员政治荣誉感、组织归属感。\n（二）丰富教学方式。灵活运用讲授式、研讨式、模拟式、互动式、观摩式、体验式等教学方法，探索“课堂+基地”实训模式，增强教育培训的吸引力感染力。加强案例培训，选好用好各条战线各个领域各个行业的生动鲜活案例。开展典型教育，引导党员学习重大先进典型和身边榜样，运用反面教材加强警示教育。组织党员就近就便到红色基地学习、重温入党誓词、过“政治生日”。\n（三）创新运用信息化手段。推动党员教育信息化平台一体化建设，完善学用功能，构建更为便捷高效的网络学习阵地。建设全国党员教育资源库，建立党性教育基地网上平台，发挥全国党建网站联盟作用，用好“共产党员”教育平台、“学习强国”学习平台等载体。依托全国党员管理信息化工程，探索建立党员学习电子档案。注重党员教育信息化建设整体设计，避免重复建设。坚持线上线下相结合，探索适应信息化发展趋势和受众特点的教育培训有效方式，注重运用大数据对党员学习情况进行动态分析，精准推送教育内容，引导党员主动学网用网。中央组织部要研究制定加强新时代党员教育信息化建设的指导意见，统筹推进远程教育、电化教育、网络新媒体平台教育，提高党员教育培训现代化水平。\n（四）健全培训制度。完善需求调研制度，通过问卷调查、谈心谈话、走访调研、大数据分析等方式，精准掌握党员学习需求和参训意愿。坚持集中轮训制度，各级党委（党组）每年就党员集中轮训工作作出安排，分期分批组织实施；组织基层党组织书记每年至少参加1次县级以上党委举办的集中轮训，对新任基层党组织书记一般应在半年内进行任职培训；预备党员在预备期内和转正后1年内一般要各参加1次由上级党组织组织的集中培训；大力实施农村党员春训冬训。落实学时制度，党员每年参加集中培训和集体学习时间一般不少于32学时，基层党组织书记和班子成员每年参加集中培训和集体学习时间不少于56学时、至少参加1次集中培训。党员领导干部除执行干部教育培训有关规定外，要带头参加所在单位的党员教育培训。","level":1},{"name":"五、组织领导和基础保障","text":"（一）落实领导责任。各级党委（党组）要认真履行党建主体责任，党委（党组）书记要履行第一责任人职责，加强对党员教育培训工作的组织领导。党支部要落实抓党员日常教育工作的直接责任。各级党员教育管理工作协调机构要落实党员教育培训联席会议制度，组织部门要发挥牵头抓总作用，相关职能部门要密切配合，形成工作合力。\n（二）夯实基础保障。各级组织部门和党员教育培训机构要建立开放式党员教育培训师资库。落实党员教育讲师聘任制，县级以上党委选聘一批政治素质过硬、实践经验丰富、理论水平较高的党员教育讲师，实行动态管理，注重发挥党员教育讲师的积极性、主动性、创造性。鼓励建立党员教育培训志愿者讲师队伍。抓好党员教育工作者专业化能力培训。充分发挥各级党校（行政学院）在党员教育培训中的主渠道、主阵地作用，县级党校（行政学校）要将党员集中培训作为重要任务。加强和规范乡镇、街道等基层党校和党员教育培训基地、现场教学点建设。利用党员活动室、党群服务中心、远程教育站点、新时代文明实践中心等开展党员日常教育培训。中央组织部要联合有关部门加强全国党员教育培训教材建设规划，组织编写新时代党员教育培训基本教材，摄制重大题材专题教育电视片，定期开展党员教育培训教材展示交流活动。各地区各部门各单位党委（党组）可结合实际，开发各具特色、务实管用的党员教育培训教材。抓好少数民族语言教材的制作和译制工作，开发民族地区党员教育培训双语教材。各级党组织要为党员推荐学习书目，提供学习资料。严格按照《中国共产党党员教育管理工作条例》有关规定，落实党员教育培训经费，保证工作需要。加大对革命老区、民族地区、边疆地区、贫困地区党员教育培训工作支持力度。\n（三）加强学风建设。各级党组织要认真落实党中央关于加强学风建设的要求，加强指导和监督，严肃工作纪律，力戒形式主义、官僚主义，防止教育培训表面化、程式化、庸俗化，防止学用脱节、空洞说教，防止不分层次对象“一刀切”、“一锅煮”，防止多头调训、重复培训、长期不训，防止检查过多、过度留痕。党员教育培训机构要坚持从严治校、从严治教、从严治学。党员要端正学习态度，严守培训纪律。党员领导干部要先学一步、学深一层，发挥示范表率作用。\n（四）严格考核评估。要将党员教育培训工作作为党委（党组）书记抓基层党建工作述职评议考核的重要内容。结合组织生活会、民主评议党员等，组织党员述学评学。将党员教育培训考核结果，作为党组织和党员评先评优的重要依据。各地区各部门各单位党委（党组）要结合实际抓好本规划的贯彻落实。中央组织部要对本规划实施情况开展中期和5年总结评估工作。\n中国人民解放军和中国人民武装警察部队的党员教育培训工作，由中央军委根据本规划精神制定实施意见。\n延伸阅读\n《中国共产党章程》\n《中国共产党党员教育管理工作条例》","level":1}]},{"id":"r0529","sections":[{"name":"中共中央印发《关于加快构建中国特色哲学社会科学的意见》","text":"近日，中共中央印发了《关于加快构建中国特色哲学社会科学的意见》（以下简称《意见》）。《意见》强调，坚持和发展中国特色社会主义，必须加快构建中国特色哲学社会科学。要高举中国特色社会主义伟大旗帜，深入贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，坚持为人民服务、为社会主义服务，坚持百花齐放、百家争鸣，立足中国、借鉴国外，挖掘历史、把握当代，关怀人类、面向未来，充分体现继承性、民族性、原创性、时代性、系统性、专业性，创新发展哲学社会科学，为实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦提供强大思想理论支撑。","level":1},{"name":"","text":"《意见》指出，站在新的历史起点上，更好进行具有许多新的历史特点的伟大斗争、推进中国特色社会主义伟大事业，需要充分发挥哲学社会科学的作用，需要哲学社会科学工作者立时代潮头、发思想先声，积极为党和人民述学立论、建言献策。\n《意见》指出，要坚持马克思主义在哲学社会科学领域的指导地位。把马克思主义理论作为必修课，组织广大党员、干部特别是领导干部学习和研读经典著作，推进经典著作编译、导读工作，加强教育教学。加强对党的十八大以来理论创新成果的学习研究，不断深化习近平总书记系列重要讲话精神和治国理政新理念新思想新战略的学习，梳理总结好新探索新实践，在理论上不断拓展新视野、作出新概括。推进马克思主义中国化、时代化、大众化，发展21世纪马克思主义、当代中国马克思主义，把中国特色社会主义理论体系贯穿到学科建设、人才培养、科学研究、课程设置、教材编写、学术评价等各环节。\n《意见》指出，要加快构建中国特色哲学社会科学学科体系。巩固马克思主义理论一级学科基础地位，加强哲学社会科学各学科领域马克思主义相关学科建设，实施高校思想政治理论课建设体系创新计划，发展中国特色社会主义政治经济学，丰富发展马克思主义哲学、政治经济学、科学社会主义。努力构建全方位、全领域、全要素的哲学社会科学体系，加快完善对哲学社会科学具有支撑作用的学科，重点布局一批对文明传承有重大影响、同经济社会发展密切相关的学科，发展具有重要现实意义的新兴学科和交叉学科，支持具有重要文化价值和传承意义的濒危学科、冷门学科。加强教材建设规划，建立健全高校教材编审机制，创新教材编写、推广、使用的体制机制，调动学者、学校、出版机构积极性。\n《意见》指出，要加快构建中国特色哲学社会科学学术体系。扎根中国大地，突出时代特色，树立国际视野，继承和弘扬中华优秀传统文化，积极吸收借鉴国外有益的理论观点和学术成果，融通各种资源，不断推进知识创新、理论创新、方法创新，提升学术原创能力和水平，推动学术理论中国化。建立激发科研活力的体制机制，落实社会科学领域财政科研项目资金管理改革政策，统筹管理好重要人才、重要阵地、重大研究规划、重大研究项目、重大资金分配，加强学术共同体建设、哲学社会科学基础设施和信息化建设，鼓励社会资金通过捐赠、设立学术基金会等方式支持科研工作。构建具有自身特质的学术评价体系，坚持正确的学术导向，以学术质量、社会影响、实际效果为衡量标准，建立科研信用管理、评价结果公布等制度，建立健全分类评价机制，科学设置考核周期，引导教学研究人员潜心钻研、铸造精品。\n《意见》指出，要加快构建中国特色哲学社会科学话语体系。深化党的理论创新成果的学理阐释，将党的理论创新成果的核心思想、关键话语体现到各学科领域。推动哲学社会科学研究成果向决策咨询、教育教学转化，更好地服务社会、服务大众，开展形式多样的普及活动。坚持用中国理论阐释中国实践，用中国实践升华中国理论，创新对外话语表达方式，提升国际话语权。\n《意见》指出，要建设种类齐全、梯队衔接的哲学社会科学人才队伍。深化人才发展体制机制改革，规范完善职称评定制度、岗位聘用制度，以增加知识价值为导向，完善收入分配激励机制。推动形成崇尚精品、严谨治学、注重诚信、讲求责任的优良学风，营造风清气正、互学互鉴、积极向上的学术生态，教育引导哲学社会科学工作者树立良好学术道德，遵守学术规范。\n《意见》强调，要加强和改善党对哲学社会科学工作的领导。各级党委（党组）要把哲学社会科学工作摆在重要位置，加强政治领导和工作指导，及时解决实际问题。统筹推进各类智库协调发展，大力提高智库建设水平。领导干部要以科学的态度对待哲学社会科学，尊重哲学社会科学工作者的辛勤付出和研究成果，主动同专家学者打交道、交朋友，认真贯彻党的知识分子政策，加强哲学社会科学优秀人才使用。加强相关领域立法，加大宣传力度，营造尊重学术、尊重人才、崇尚科学、追求真理的良好氛围。\n延伸阅读\n习近平在哲学社会科学工作座谈会上的讲话\n深入理解哲学社会科学的“中国特色”","level":0}]},{"id":"r0530","sections":[{"name":"关于加强和改进中央和国家机关党的建设的意见","text":"近日，中共中央印发了《关于加强和改进中央和国家机关党的建设的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于加强和改进中央和国家机关党的建设的意见》全文如下。\n中央和国家机关在党和国家治理体系中处于特殊重要位置，是推动党中央治国理政、管党治党决策部署贯彻落实的领导机关。中央和国家机关党的建设关系党中央权威和集中统一领导，关系党中央决策部署的贯彻落实，关系最广大人民根本利益的实现。推进新时代党的建设新的伟大工程，中央和国家机关必须走在前、作表率。为深入学习贯彻习近平新时代中国特色社会主义思想和党的十九大精神，认真落实新时代党的建设总要求和党的组织路线，推动中央和国家机关全面从严治党向纵深发展，现提出如下意见。","level":0},{"name":"一、总体要求和主要原则","text":"（一）总体要求。以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，树牢“四个意识”，坚定“四个自信”，带头做到“两个维护”，以党的政治建设为统领，着力深化理论武装，着力夯实基层基础，着力推进正风肃纪，着力解决和防止“灯下黑”问题，全面提高中央和国家机关党的建设质量，切实在深入学习贯彻习近平新时代中国特色社会主义思想上作表率，在始终同以习近平同志为核心的党中央保持高度一致上作表率，在坚决贯彻落实党中央各项决策部署上作表率，建设让党中央放心、让人民群众满意的模范机关，为推动中央和国家机关各项事业发展提供坚强保证。\n（二）主要原则。坚持和加强党的全面领导，坚持党要管党、全面从严治党；坚持围绕中心、建设队伍、服务群众，推动机关党建和业务工作深度融合、相互促进；坚持以上率下、以机关带系统，充分发挥领导机关和领导干部示范引领作用；坚持问题导向，加强分类指导，注重精准施策；坚持求真务实、改革创新，把握特点规律，切实增强机关党建工作的针对性、实效性。","level":1},{"name":"二、把党的政治建设摆在首位","text":"（三）带头做到“两个维护”。中央和国家机关首先是政治机关，必须旗帜鲜明讲政治，坚定不移向党中央看齐，向党的理论和路线方针政策看齐，向党中央决策部署看齐，把准政治方向，认真对标对表，及时校正偏差，自觉在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致。部门党组（党委，包括不设党组、党委的部门领导班子，下同）要结合实际，把党中央关于加强党的政治建设的部署要求细化为具体措施，贯彻到机关党建全过程和事业发展各方面。坚决贯彻党的基本理论、基本路线、基本方略，坚决落实党中央决策部署和习近平总书记对本部门本领域的重要指示批示精神，做到不折不扣、令行禁止。严格执行重大事项向党中央请示报告制度。开展“让党中央放心、让人民群众满意的模范机关”创建工作。\n（四）严明党的政治纪律和政治规矩。把学习和遵守党章作为基础性经常性工作来抓，做到深学细照笃行。中央和国家机关广大党员、干部必须在严守党的政治纪律和政治规矩上作表率，强化自我约束，特别要自觉规范工作时间之外的政治言行，不准散布违背党的理论和路线方针政策的言论，不准妄议中央，不准制造、传播政治谣言及丑化党和国家形象的言论，不准拉帮结派、搞团团伙伙，不准搞两面派、做两面人。各级党组织要加强教育警示，引导党员、干部始终做政治上的明白人、老实人。对违反党的政治纪律和政治规矩的言行要坚决批评制止，问题严重的要严肃处理。对推进党的政治建设特别是遵守党的政治纪律和政治规矩情况进行监督检查。\n（五）严肃党内政治生活。经常学习、严格执行新形势下党内政治生活若干准则，切实提高民主生活会、组织生活会质量，党员、干部应当在会上把群众反映、巡视反馈、组织约谈函询、个人需报告的重大事项和有关问题说清楚。贯彻民主集中制，坚持集体领导和个人分工负责相结合，各级党组织主要负责人带头发扬民主、善于集中、敢于负责。制定中央和国家机关严格党的组织生活制度的若干规定。高级干部要带头过好双重组织生活，并督促身边工作人员参加所在党组织的政治学习和组织生活。坚持党员领导干部讲党课制度。完善重温入党誓词、入党志愿书以及党员过“政治生日”等政治仪式。\n（六）培育积极健康的党内政治文化。充分利用中央和国家机关的光荣历史和红色资源，传承红色基因，加强党性锻炼，扎实推进对党忠诚教育，深入开展优良传统作风教育。注重发挥身边榜样的示范带头作用，探索总结既符合党中央要求又接地气的价值理念、职业操守等，打造体现部门特色的党内政治文化品牌，涵养风清气正的机关政治生态。\n（七）提高党员、干部政治能力。教育引导党员、干部善于从政治上认识和处理问题，自觉在党和国家工作大局下想问题、做工作，切实提高辨别政治是非、保持政治定力、防范政治风险的能力。积极组织党员领导干部政治能力专题培训。加强政治历练，注重在贯彻落实党中央决策部署、应对重大斗争和突发事件、完成急难险重任务中提高政治能力。坚持守土有责、守土尽责，及时发现、有效防控、果断处置政治风险。","level":1},{"name":"三、带头做深入学习贯彻习近平新时代中国特色社会主义思想的表率","text":"（八）坚持不懈推进理论武装。把系统掌握马克思主义理论作为看家本领，把深入学习贯彻习近平新时代中国特色社会主义思想作为首要政治任务。持续开展大学习、大培训，着力在学懂弄通做实上下功夫，推动学用结合，教育引导广大党员、干部切实用习近平新时代中国特色社会主义思想武装头脑、指导实践、推动工作。紧密结合部门、岗位职责任务，学好用好习近平总书记关于本部门本领域工作的重要论述。推进“两学一做”学习教育常态化制度化。按照党中央统一部署，扎实开展党内集中学习教育。办好学习贯彻习近平新时代中国特色社会主义思想系列辅导讲座，开展学用习近平新时代中国特色社会主义思想经验交流。提高部门党组（党委）理论学习中心组学习质量效果，充分发挥领学促学作用。实施青年理论学习提升工程，加强专题培训，成立青年理论学习小组，评选青年学习标兵。充分发挥中央和国家机关各级党校的阵地作用，推动习近平新时代中国特色社会主义思想进教材、进课堂、进头脑。\n（九）深化理想信念教育。加强中国特色社会主义和中国梦宣传教育。开展党史、国史、改革开放史和社会主义发展史教育。加大政策宣传、成就宣传和形势教育力度。建立中央领导同志、部门党组（党委）负责人定期为中央和国家机关党员、干部作形势报告制度。弘扬和践行社会主义核心价值观，开展机关精神文明创建活动。加强宪法和法治宣传教育，引导党员、干部做尊法学法守法用法的模范。加强道德建设，选树中央和国家机关道德模范。\n（十）严格落实意识形态工作责任制。部门党组（党委）要加强对意识形态工作的领导，及时了解掌握动态，加强舆情研判，敢于发声亮剑，引导党员、干部明辨是非、澄清模糊认识，坚决反对和抵制各种错误思潮和负面言论。落实主管主办责任，加强本部门本领域意识形态阵地建设和管理，积极稳妥做好重大突发事件和热点敏感问题的舆论引导。\n（十一）加强和改进思想政治工作。认真落实思想政治工作定期分析报告制度，针对干部职工思想状况，及时有效加以引导。建立健全重大情况党内通报制度。坚持并完善谈心谈话制度，领导班子成员之间、班子成员和干部职工之间要开展经常性的谈心谈话。基层党组织负责人要经常、主动和干部职工谈心谈话。善于利用重要节点开展谈心谈话，做到岗位变动必谈、组织处理必谈、发生家庭变故必谈、发现苗头性问题必谈。不断提高思想政治工作水平，防止简单以政治学习和集体谈话代替一对一的思想政治工作。","level":1},{"name":"四、推动基层党组织全面进步全面过硬","text":"（十二）强化基层党组织功能。以提升组织力为重点，突出政治功能，全面激发基层党组织生机活力。紧紧围绕贯彻落实党中央决策部署推进基层党建工作，为完成本部门中心任务提供坚强保证。健全基层党组织，优化基层党组织设置。制定加强部门所属事业单位、企业等基层党组织建设的分类指导意见。巩固和深化社会组织党的组织和党的工作覆盖，加强党务工作力量，拓展党组织和党员发挥作用的途径。严格执行基层党组织按期换届规定。注重探索创新，积极推进机关党建信息化建设。\n（十三）建强抓实党支部。以落实党支部工作条例为抓手，突出中央和国家机关特点，扎实推进党支部标准化、规范化建设。严格执行“三会一课”等制度，确保质量和效果。积极推动党支部活动方式创新。为执行某项任务临时组建的机构，党员组织关系不转接的，经上级党组织批准，应成立临时党支部。选好配强党支部书记和委员，党支部书记原则上由本部门本单位党员主要负责人担任，履行第一责任人职责。建立党支部委员履职培训制度，新任党支部书记须在任职6个月内接受集中培训。充分发挥党支部在选人用人中的监督作用，党员、干部选拔任用、评优评先应听取所在党支部意见。选树先进党支部和优秀党支部书记典型，坚持以先进带中间、督后进，用3年左右时间有效解决一些基层党组织弱化、虚化、边缘化问题。制定中央和国家机关党小组工作规则，切实发挥党小组作用。\n（十四）加强党员教育管理监督。强化党员教育培训和实践锻炼，着力打造高素质党员队伍。通过佩戴党员徽章、设立党费集中交纳日、创建党员先锋岗、党员民主评议等措施，引导党员增强党员意识、发挥主体作用。坚持严管和厚爱相结合，落实党内激励关怀帮扶制度。提高发展党员质量，稳妥处置不合格党员。有针对性地加强对青年党员、派驻国（境）外机构工作党员、离退休干部职工党员、流动党员的分类管理。加强基层党组织对党员的日常监督管理，探索党员发挥先锋模范作用的有效机制。","level":1},{"name":"五、持之以恒强化正风肃纪","text":"（十五）持续整治“四风”问题。带头转作风、纠“四风”，防止享乐主义和奢靡之风反弹，坚决整治形式主义、官僚主义特别是表态多调门高、行动少落实差等突出问题，改进文风会风，防止和纠正不作为、慢作为等机关不良风气。坚决反对特权思想和特权现象，防止利用中央和国家机关的权力和影响力谋取个人利益。对贯彻执行中央八项规定及其实施细则精神情况开展督促检查。\n（十六）密切联系群众。完善和落实党员、干部直接联系群众制度。鼓励基层党组织开展结对帮扶、联学联建等活动。认真落实党员领导干部定期接待群众来访制度。坚持重大决策调研先行，广泛听取群众意见，提倡蹲点调研、“解剖麻雀”。鼓励党员、干部到社区、农村、企业、学校等开展形式多样的志愿服务。认真落实定点扶贫政治责任，助力脱贫攻坚。\n（十七）严明党的各项纪律。将党规党纪学习作为理论学习中心组学习、党支部学习和干部教育培训重要内容。对新入职党员、干部及时开展纪律和廉政教育，对新任职党员领导干部进行廉政谈话。坚持执纪必严、违纪必究，深化运用监督执纪“四种形态”，注重抓早抓小、防微杜渐。定期开展对执纪审查工作情况的检查考核。重点强化政治纪律和组织纪律，带动廉洁纪律、群众纪律、工作纪律、生活纪律严起来，使铁的纪律成为广大党员、干部日常习惯和自觉遵循。\n（十八）深入推进反腐败斗争。深化标本兼治，强化不敢腐的震慑，扎牢不能腐的笼子，增强不想腐的自觉，建设风清气正的政治机关。认真排查廉政风险隐患，健全防控机制，建立党员干部廉政档案。紧盯权力资源集中、廉政风险较高的重点部门、关键岗位等，开展内部巡视，强化监管措施。加大对在同一个部门、同一个岗位上任职时间较长的干部的交流轮岗力度。对发生严重违纪问题的部门，坚持“一案双查”，严肃追究主体责任和监督责任。加强警示教育，定期召开警示教育大会。凡查结严重违纪违法案件，须在本部门组织开展警示教育。领导干部要注重家庭家教家风，教育引导亲属坚决听党话跟党走，立德修身、遵纪守法、廉洁从业。","level":1},{"name":"六、不断提高党的群团工作水平","text":"（十九）充分发挥群团组织桥梁纽带作用。部门党组（党委）要定期研究部署群团工作。机关党委要协助部门党组（党委）加强对机关工会、共青团、妇女组织等群团组织的领导，完善党建带群建制度机制，推动群团组织依法依章程开展工作、发挥作用。深化群团改革，创新机关群团工作方式方法，增强群团组织的政治性、先进性、群众性。立足本职工作开展岗位建功、技能竞赛、巾帼建功等活动。完善帮扶生活困难干部职工机制。关心干部职工身心健康，开展丰富多彩的文体活动，营造团结和谐、严肃活泼、积极向上的机关氛围。\n（二十）教育引领机关青年成长成才。加强政治引领，推动青年干部坚定理想信念、培养家国情怀。坚持以老带新，搞好传帮带，积极为青年干部健康成长引路搭桥、排忧解难。创造条件推动青年干部到基层一线、吃劲岗位、艰苦地区经受锻炼。持续抓好中央和国家机关青年支教扶贫、“根在基层”调研等多种形式的实践锻炼活动。","level":1},{"name":"七、加强对中央和国家机关党的建设的领导","text":"（二十一）健全领导体制机制。党中央集中统一领导中央和国家机关党的建设。中央党的建设工作领导小组加强对中央和国家机关党建工作的指导，定期听取工作情况汇报，及时研究解决重大问题。中央和国家机关工委要认真履职尽责，指导督促部门党组（党委）履行机关党建主体责任，和有关部门密切协作，推动形成抓机关党建的强大合力。\n（二十二）落实机关党建工作责任制。部门党组（党委）要认真履行全面从严治党主体责任，经常研究机关党建工作，做到机关党建工作和中心工作一起谋划、一起部署、一起检查、一起考核，定期向党中央报告履责情况。结合实际建立健全党建工作领导小组等有效机制。研究制定机关党建工作责任清单。部门党组（党委）主要负责人要自觉扛起抓机关党建第一责任人职责，其他班子成员落实“一岗双责”，抓好职责范围内的党建工作。机关党委作为部门机关党建工作专责机构，在中央和国家机关工委、部门党组（党委）领导下，负责组织推动本部门机关党建任务落实。机关党委书记要聚焦机关党建主责主业，切实担当作为，不做“挂名书记”。坚持一级抓一级、一严到底，层层压实机关党建主体责任。\n（二十三）完善督促推动机关党建工作落实的机制。中央和国家机关工委要定期开展对部门党组（党委）履行机关党建主体责任、落实机关党建重点工作和重要制度情况的督查，重要情况及时向党中央报告。与中央巡视对接，推动被巡视部门机关党建突出问题整改。积极稳妥开展对各部门机关党建工作的考核。部门党组（党委）每年在本部门一定范围内通报抓机关党建工作情况、接受评议。机关党委书记每年向中央和国家机关工委、部门党组（党委）述职。基层党组织书记向上一级党组织述职并接受评议考核。各部门在领导班子和领导干部年度考核中，应加大抓党建工作的权重，对党组织负责人履行党建责任情况形成评价意见，作为确定考核等次的重要依据。开展绩效考核的部门要把党建工作情况列入考核重要内容。\n（二十四）加强党务干部队伍建设。各部门应按照全面从严治党的实际需要，切实配强机关专职党务工作人员。机关党建任务较重、工作力量不足的，应在现有基础上适当增加人员。机关党委书记应由政治过硬、熟悉党务工作的部门党组（党委）成员担任。机关党委常务副书记按本部门内设机构正职干部配备，机关党委副书记、机关纪委书记根据实际情况按本部门内设机构正职或副职干部配备。新任机关党委、机关纪委负责人年龄一般应能任满一届，连续任职一般不超过两届。机关党委、机关纪委负责人出缺，应在6个月内补齐。建立新任党组织书记任职谈话制度。机关党委常务副书记列席部门党组（党委）民主生活会、理论学习中心组学习会等有关会议。加强和改进专兼职党务干部教育培训。有计划地安排党务干部同行政、业务干部之间的交流。专兼职党务工作经历纳入干部履历。严把党务干部入口关，把政治上强、综合素质高的优秀干部放到党务岗位培养锻炼，工作业绩突出的注重提拔使用。\n（二十五）加强党建工作保障。坚持依规治党，着力推动全面从严治党法规制度贯彻执行，构建务实管用、符合中央和国家机关特点的党建工作制度体系。严格按照规定保障机关党建工作经费。推进中央和国家机关同地方机关党建工作交流，加强机关党建理论研究。\n中央和国家机关各部门根据本意见，结合实际制定实施措施，贯彻落实情况要及时报告党中央。\n延伸阅读\n人民日报评论员：推动新时代中央和国家机关党的建设高质量发展","level":1}]},{"id":"r0531","sections":[{"name":"公务员录用违规违纪行为处理办法","text":"公务员录用违规违纪行为处理办法\n（2009年11月9日中共中央组织部、人力资源社会保障部制定 2016年9月6日中共中央组织部、人力资源社会保障部、国家公务员局修订 2021年8月25日中共中央组织部部务会会议修订 2021年9月18日中共中央组织部、人力资源社会保障部发布）","level":1},{"name":"第一章 总 则","text":"第一条 为规范公务员录用违规违纪行为的认定与处理，维护公务员录用工作的公平公正，严把公务员队伍入口关，根据《中华人民共和国公务员法》和《公务员录用规定》等有关法律法规，制定本办法。\n第二条 本办法适用于公务员录用中报考者和工作人员违规违纪行为的认定与处理。\n第三条 公务员录用违规违纪行为的认定与处理，应当事实清楚、证据确凿、程序规范、适用规定准确。\n第四条 公务员主管部门、招录机关和考试机构以及其他相关单位按照规定的职责权限，对违规违纪行为进行认定与处理。","level":1},{"name":"第二章 报考者违规违纪行为处理","text":"第五条 报考者提交的涉及报考资格的申请材料或者信息不实的，负责资格审查工作的招录机关或者公务员主管部门应当认定其报名无效，终止其录用程序；有恶意注册报名信息，扰乱报名秩序或者伪造、变造有关材料骗取报考资格等行为的，由设区的市级以上公务员主管部门给予其取消本次报考资格并五年内限制报考公务员的处理。\n第六条 报考者在考试过程中有下列行为之一的，由具体组织实施考试的考试机构、招录机关或者公务员主管部门给予其所涉科目（场次）考试成绩为零分的处理：\n（一）将规定以外的物品带入考场，经提醒仍未按要求放在指定位置的；\n（二）参加考试时未按规定时间入场、离场的；\n（三）未在指定座位参加考试，或者擅自离开座位、出入考场的；\n（四）未按规定填写（填涂）、录入本人或者考试相关信息，以及在规定以外的位置标注本人信息或者其他特殊标记的；\n（五）故意损坏本人试卷、答题卡（答题纸）等考场配发材料或者本人使用的考试机等设施设备的；\n（六）在考试开始信号发出前答题的，或者在考试结束信号发出后继续答题的；\n（七）其他情节较轻的违规违纪行为。\n第七条 报考者在考试过程中有下列行为之一的，由设区的市级以上公务员主管部门给予其取消本次考试资格并五年内限制报考公务员的处理：\n（一）抄袭他人答题信息或者协助他人抄袭答题信息的；\n（二）查看、偷听违规带入考场与考试有关的文字、视听资料的；\n（三）使用禁止携带的通讯设备或者具有计算、存储功能电子设备的；\n（四）携带具有避开或者突破考场防范作弊的安全管理措施，获取、记录、传递、接收、存储考试试题、答案等功能的程序、工具，以及专门用于作弊的程序、工具（以下简称作弊器材）的；\n（五）抢夺、故意损坏他人试卷、答题卡（答题纸）、草稿纸等考场配发材料或者他人使用的考试机等设施设备的；\n（六）违反规定将试卷、答题卡（答题纸）等考场配发材料带出考场的；\n（七）其他情节严重、影响恶劣的违规违纪行为。\n第八条 报考者在考试过程中有下列行为之一的，由省级以上公务员主管部门给予其取消本次考试资格并终身限制报考公务员的处理：\n（一）使用伪造、变造或者盗用他人的居民身份证、准考证以及其他证明材料参加考试的；\n（二）3人以上串通作弊或者参与有组织作弊的；\n（三）代替他人或者让他人代替自己参加考试的；\n（四）使用本办法第七条第四项所列作弊器材的；\n（五）非法侵入考试信息系统或者非法获取、删除、修改、增加系统数据的；\n（六）其他情节特别严重、影响特别恶劣的违规违纪行为。\n第九条 在阅卷过程中发现报考者之间同一科目作答内容雷同，并经阅卷专家组确认的，由具体组织实施考试的考试机构给予其该科目（场次）考试成绩为零分的处理，录用程序终止。作答内容雷同的认定方法和标准由省级以上考试机构确定。\n报考者之间同一科目作答内容雷同，并有其他相关证据证明其作弊行为成立的，视具体情形按照本办法第七条、第八条的规定处理。\n第十条 报考者有隐瞒影响录用的疾病或者病史以及其他妨碍体检工作正常进行的行为，情节较轻的，负责组织体检的招录机关或者公务员主管部门应当终止其录用程序；有交换、替换检验样本等情节严重、影响恶劣行为的，由设区的市级以上公务员主管部门给予其取消本次考试资格并五年内限制报考公务员的处理；有串通作弊、让他人顶替体检等情节特别严重、影响特别恶劣行为的，由省级以上公务员主管部门给予其取消本次考试资格并终身限制报考公务员的处理。\n第十一条 报考者在考察、体能测评、心理素质测评等环节有弄虚作假、隐瞒事实真相以及其他妨碍相关工作正常进行的行为，情节较轻的，负责组织实施的招录机关或者公务员主管部门应当终止其录用程序；情节严重、影响恶劣的，由设区的市级以上公务员主管部门给予其取消本次考试资格并五年内限制报考公务员的处理；情节特别严重、影响特别恶劣的，由省级以上公务员主管部门给予其取消本次考试资格并终身限制报考公务员的处理。\n第十二条 报考者应当自觉维护公务员录用工作秩序，有下列行为之一的，应当终止其录用程序；情节严重、影响恶劣的，由设区的市级以上公务员主管部门给予其取消本次考试资格并五年内限制报考公务员的处理；情节特别严重、影响特别恶劣的，由省级以上公务员主管部门给予其取消本次考试资格并终身限制报考公务员的处理：\n（一）故意扰乱考点、考场等工作场所秩序的；\n（二）拒绝、妨碍工作人员履行管理职责的；\n（三）威胁、侮辱、诽谤、诬陷、殴打工作人员或者其他报考者的；\n（四）通过搞利益输送或者利益交换，谋取考试资格、录用机会、经济利益以及其他不当利益的；\n（五）购买本办法第七条第四项所列作弊器材的；\n（六）其他扰乱公务员录用工作秩序的行为。\n第十三条 报考者在公务员录用中有违规违纪行为，涉嫌违法犯罪的，移送有关国家机关依法处理。\n报考者为国家公职人员的，应当将其违规违纪行为和处理结果通报所在单位。\n第十四条 试用期间查明报考者有本办法所列违规违纪行为的，应当取消录用并按照本办法的有关规定给予其相应的处理。\n任职定级后查明有本办法所列违规违纪行为的，按照有关规定给予其相应的处理。\n第十五条 报考者有情节严重、影响恶劣或者情节特别严重、影响特别恶劣的违规违纪行为的，应当记入公务员录用诚信档案库，并按照有关规定进行信用信息共享等管理。","level":1},{"name":"第三章 工作人员违规违纪行为处理","text":"第十六条 有下列情形之一的，根据情节轻重，依规依纪依法追究负有责任的领导人员和直接责任人员责任；涉嫌违法犯罪的，移送有关国家机关依法处理：\n（一）不按照规定的编制限额和职位要求进行录用的；\n（二）不按照规定的任职资格条件和程序录用的；\n（三）未经授权，擅自出台、变更录用政策，造成不良影响的；\n（四）录用工作中徇私舞弊的；\n（五）发生泄露试题、违反考场纪律以及其他影响公平、公正行为的。\n第十七条 工作人员有下列情形之一的，根据情节轻重，依规依纪依法追究责任；涉嫌违法犯罪的，移送有关国家机关依法处理：\n（一）泄露试题和其他录用秘密信息的；\n（二）利用工作便利，伪造考试成绩或者其他录用工作有关资料的；\n（三）利用工作便利，协助报考者作弊的；\n（四）因工作失职，影响录用工作正常进行的；\n（五）其他违反录用工作纪律的行为。","level":1},{"name":"第四章 违规违纪行为处理程序","text":"第十八条 报考者的违规违纪行为被当场发现的，工作人员应当予以制止，并收集、保存相应证据材料，如实记录违规违纪事实和现场处置情况，由2名以上工作人员签字，报送负责组织有关工作的公务员主管部门、招录机关或者考试机构。\n第十九条 对报考者违规违纪行为作出处理决定前，应当告知报考者拟作出的处理决定以及相关事实、理由和依据，并告知报考者依法享有陈述和申辩的权利。作出处理决定的公务员主管部门、招录机关或者考试机构对报考者提出的事实、理由和证据，应当进行复核。\n第二十条 对报考者违规违纪行为作出处理决定的，应当制作公务员录用违规违纪行为处理决定书，采取直接送达、委托送达、邮寄送达或者公告等方式送达。\n对给予五年内限制报考公务员或者终身限制报考公务员处理的报考者，限制报考的日期自作出处理决定之日起计算。\n第二十一条 报考者对违规违纪行为处理决定不服的，可以依法申请行政复议或者提起行政诉讼。\n第二十二条 对工作人员违规违纪行为的处理，由相关单位按照职责权限和程序办理。\n工作人员对违规违纪行为处理不服的，可以按照规定申请复核或者提出申诉等。","level":1},{"name":"第五章 附 则","text":"第二十三条 报考者和工作人员以外的其他人员，有干扰公务员录用秩序等行为的，依据有关法律法规处理。\n第二十四条 参照公务员法管理的机关（单位）中除工勤人员以外的工作人员录用中违规违纪行为的认定与处理，参照本办法执行。\n第二十五条 本办法由中共中央组织部、人力资源社会保障部负责解释。\n第二十六条 本办法自发布之日起施行。\n附件：公务员录用违规违纪行为处理决定书（样式）\n[点击下载]","level":1}]},{"id":"r0532","sections":[{"name":"中共中央办公厅 国务院办公厅印发《国家信息化发展战略纲要》","text":"近日，中共中央办公厅、国务院办公厅印发了《国家信息化发展战略纲要》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《国家信息化发展战略纲要》全文如下。\n当今世界，信息技术创新日新月异，以数字化、网络化、智能化为特征的信息化浪潮蓬勃兴起。没有信息化就没有现代化。适应和引领经济发展新常态，增强发展新动力，需要将信息化贯穿我国现代化进程始终，加快释放信息化发展的巨大潜能。以信息化驱动现代化，建设网络强国，是落实“四个全面”战略布局的重要举措，是实现“两个一百年”奋斗目标和中华民族伟大复兴中国梦的必然选择。\n本战略纲要是根据新形势对《2006-2020年国家信息化发展战略》的调整和发展，是规范和指导未来10年国家信息化发展的纲领性文件，是国家战略体系的重要组成部分，是信息化领域规划、政策制定的重要依据。","level":0},{"name":"一、国家信息化发展的基本形势","text":"(一)人类社会经历了农业革命、工业革命，正在经历信息革命。当前，以信息技术为代表的新一轮科技革命方兴未艾，互联网日益成为创新驱动发展的先导力量。信息技术与生物技术、新能源技术、新材料技术等交叉融合，正在引发以绿色、智能、泛在为特征的群体性技术突破。信息、资本、技术、人才在全球范围内加速流动，互联网推动产业变革，促进工业经济向信息经济转型，国际分工新体系正在形成。网信事业代表新的生产力、新的发展方向，推动人类认识世界、改造世界的能力空前提升，正在深刻改变着人们的生产生活方式，带来生产力质的飞跃，引发生产关系重大变革，成为重塑国际经济、政治、文化、社会、生态、军事发展新格局的主导力量。全球信息化进入全面渗透、跨界融合、加速创新、引领发展的新阶段。\n随着世界多极化、经济全球化、文化多样化、社会信息化深入发展，全球治理体系深刻变革，谁在信息化上占据制高点，谁就能够掌握先机、赢得优势、赢得安全、赢得未来。发达国家持续推动信息技术创新，不断加快经济社会数字化进程，全力巩固领先优势。发展中国家抢抓产业链重组和调整机遇，以信息化促转型发展，积极谋求掌握发展主动权。世界各国加快网络空间战略布局，围绕关键资源获取、国际规则制定的博弈日趋尖锐复杂。加快信息化发展，建设数字国家已经成为全球共识。\n(二)进入新世纪特别是党的十八大以来，我国信息化取得长足进展，但与全面建成小康社会、加快推进社会主义现代化的目标相比还有差距，坚持走中国特色信息化发展道路，以信息化驱动现代化，建设网络强国，迫在眉睫、刻不容缓。目前，我国网民数量、网络零售交易额、电子信息产品制造规模已居全球第一，一批信息技术企业和互联网企业进入世界前列，形成了较为完善的信息产业体系。信息技术应用不断深化，“互联网+”异军突起，经济社会数字化网络化转型步伐加快，网络空间正能量进一步汇聚增强，信息化在现代化建设全局中引领作用日益凸显。同时，我国信息化发展也存在比较突出的问题，主要是：核心技术和设备受制于人，信息资源开发利用不够，信息基础设施普及程度不高，区域和城乡差距比较明显，网络安全面临严峻挑战，网络空间法治建设亟待加强，信息化在促进经济社会发展、服务国家整体战略布局中的潜能还没有充分释放。\n我国综合国力、国际影响力和战略主动地位持续增强，发展仍处于可以大有作为的重要战略机遇期。从国内环境看，我国已经进入新型工业化、信息化、城镇化、农业现代化同步发展的关键时期，信息革命为我国加速完成工业化任务、跨越“中等收入陷阱”、构筑国际竞争新优势提供了历史性机遇，也警示我们面临不进则退、慢进亦退、错失良机的巨大风险。站在新的历史起点，我们完全有能力依托大国优势和制度优势，加快信息化发展，推动我国社会主义现代化事业再上新台阶。","level":1},{"name":"二、指导思想、战略目标和基本方针","text":"(一)指导思想。高举中国特色社会主义伟大旗帜，全面贯彻落实党的十八大和十八届三中、四中、五中全会精神，以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入学习贯彻习近平总书记系列重要讲话精神，紧紧围绕“五位一体”总体布局和“四个全面”战略布局，牢固树立创新、协调、绿色、开放、共享的发展理念，贯彻以人民为中心的发展思想，统筹国内国际两个大局，统筹发展安全两件大事，坚持走中国特色信息化发展道路，坚持与实现“两个一百年”奋斗目标同步推进，以信息化驱动现代化为主线，以建设网络强国为目标，着力增强国家信息化发展能力，着力提高信息化应用水平，着力优化信息化发展环境，推进国家治理体系和治理能力现代化，努力在践行新发展理念上先行一步，让信息化造福社会、造福人民，为实现中华民族伟大复兴的中国梦奠定坚实基础。\n(二)战略目标\n到2020年，固定宽带家庭普及率达到中等发达国家水平，第三代移动通信(3G)、第四代移动通信(4G)网络覆盖城乡，第五代移动通信(5G)技术研发和标准取得突破性进展。信息消费总额达到6万亿元，电子商务交易规模达到38万亿元。核心关键技术部分领域达到国际先进水平，信息产业国际竞争力大幅提升，重点行业数字化、网络化、智能化取得明显进展，网络化协同创新体系全面形成，电子政务支撑国家治理体系和治理能力现代化坚实有力，信息化成为驱动现代化建设的先导力量。\n互联网国际出口带宽达到20太比特/秒(Tbps)，支撑“一带一路”建设实施，与周边国家实现网络互联、信息互通，建成中国-东盟信息港，初步建成网上丝绸之路，信息通信技术、产品和互联网服务的国际竞争力明显增强。\n到2025年，新一代信息通信技术得到及时应用，固定宽带家庭普及率接近国际先进水平，建成国际领先的移动通信网络，实现宽带网络无缝覆盖。信息消费总额达到12万亿元，电子商务交易规模达到67万亿元。根本改变核心关键技术受制于人的局面，形成安全可控的信息技术产业体系，电子政务应用和信息惠民水平大幅提高。实现技术先进、产业发达、应用领先、网络安全坚不可摧的战略目标。\n互联网国际出口带宽达到48太比特/秒(Tbps)，建成四大国际信息通道，连接太平洋、中东欧、西非北非、东南亚、中亚、印巴缅俄等国家和地区，涌现一批具有强大国际竞争力的大型跨国网信企业。\n到本世纪中叶，信息化全面支撑富强民主文明和谐的社会主义现代化国家建设，网络强国地位日益巩固，在引领全球信息化发展方面有更大作为。\n(三)基本方针\n——统筹推进。信息化事关国家经济社会长期可持续发展、事关国家长治久安、事关人民群众福祉，必须胸怀大局、把握大势、着眼大事，统筹中央和地方，统筹党政军各方力量，统筹发挥市场和政府作用，统筹阶段性目标和长远目标，统筹各领域信息化发展重大问题，确保国家信息化全面协调可持续健康发展。\n——创新引领。全面实施创新驱动发展战略，把创新发展作为应对发展环境变化、增强发展动力、把握发展主动权，更好引领经济发展新常态的根本之策，以时不我待、只争朝夕的精神，努力掌握核心技术，快马加鞭争取主动局面，占据竞争制高点。\n——驱动发展。最大程度发挥信息化的驱动作用，实施国家大数据战略，推进“互联网+”行动计划，引导新一代信息技术与经济社会各领域深度融合，推动优势新兴业态向更广范围、更宽领域拓展，全面提升经济、政治、文化、社会、生态文明和国防等领域信息化水平。\n——惠及民生。坚持以造福社会、造福人民为工作的出发点和落脚点，发挥互联网在助推脱贫攻坚中的作用，推进精准扶贫、精准脱贫，不断增进人民福祉；紧紧围绕人民期待和需求，以信息化促进基本公共服务均等化，让亿万人民在共享互联网发展成果上有更多获得感。\n——合作共赢。坚持国家利益在哪里、信息化就推进到哪里，围绕“一带一路”建设，加强网络互联、促进信息互通，加快构建网络空间命运共同体；用好国内国际两个市场两种资源、网上网下两个空间，主动参与全球治理，不断提升国际影响力和话语权。\n——确保安全。网络安全和信息化是一体之两翼、驱动之双轮，必须统一谋划、统一部署、统一推进、统一实施，做到协调一致、齐头并进；切实防范、控制和化解信息化进程中可能产生的风险，以安全保发展，以发展促安全，努力建久安之势、成长治之业。","level":1},{"name":"三、大力增强信息化发展能力","text":"(一)发展核心技术，做强信息产业\n信息技术和产业发展程度决定着信息化发展水平。我国正处于从跟跑并跑向并跑领跑转变的关键时期，要抓住自主创新的牛鼻子，构建安全可控的信息技术体系，培育形成具有国际竞争力的产业生态，把发展主动权牢牢掌握在自己手里。\n1.构建先进技术体系。制定国家信息领域核心技术设备发展战略纲要，以体系化思维弥补单点弱势，打造国际先进、安全可控的核心技术体系，带动集成电路、基础软件、核心元器件等薄弱环节实现根本性突破。积极争取并巩固新一代移动通信、下一代互联网等领域全球领先地位，着力构筑移动互联网、云计算、大数据、物联网等领域比较优势。\n2.加强前沿和基础研究。加快完善基础研究体制机制，强化企业创新主体地位和主导作用，面向信息通信技术领域的基础前沿技术、共性关键技术，加大科技攻关。遵循创新规律，着眼长远发展，超前规划布局，加大投资保障力度，为前沿探索提供长期支持。实施新一代信息技术创新国际交流项目。\n3.打造协同发展的产业生态。统筹基础研究、技术创新、产业发展与应用部署，加强产业链各环节协调互动。提高产品服务附加值，加速产业向价值链高端迁移。加强专利与标准前瞻性布局，完善覆盖知识产权、技术标准、成果转化、测试验证和产业化投资评估等环节的公共服务体系。\n4.培育壮大龙头企业。支持龙头企业发挥引领带动作用，联合高校和科研机构打造研发中心、技术产业联盟，探索成立核心技术研发投资公司，打通技术产业化的高效转化通道。深化上市发审制度改革，支持创新型企业在国内上市。支持企业在海外设立研发机构和开拓市场，有效利用全球资源，提升国际化发展水平。\n5.支持中小微企业创新。加大对科技型创新企业研发支持力度，落实企业研发费用加计扣除政策，适当扩大政策适用范围。完善技术交易和企业孵化机制，构建普惠性创新支持政策体系。完善公共服务平台，提高科技型中小微企业自主创新和可持续发展能力。\n(二)夯实基础设施，强化普遍服务\n泛在先进的基础设施是信息化发展的基石。要加快构建陆地、海洋、天空、太空立体覆盖的国家信息基础设施，不断完善普遍服务，让人们通过网络了解世界、掌握信息、摆脱贫困、改善生活、享有幸福。\n6.统筹规划基础设施布局。深化电信业改革，鼓励多种所有制企业有序参与竞争。统筹国家现代化建设需求，实现信息基础设施共建共享，推进区域和城乡协调发展。协调频谱资源配置，科学规划无线电频谱，提升资源利用效率。加强信息基础设施与市政、公路、铁路、机场等规划建设的衔接。支持港澳地区完善信息基础设施布局。\n7.增强空间设施能力。围绕通信、导航、遥感等应用卫星领域，建立持续稳定、安全可控的国家空间基础设施。科学规划和利用卫星频率和轨道资源。建设天地一体化信息网络，增强接入服务能力，推动空间与地面设施互联互通。统筹北斗卫星导航系统建设和应用，推进北斗产业化和走出去进程。加强陆地、大气、海洋遥感监测，提升对我国资源环境、生态保护、应急减灾、大众消费以及全球观测的服务保障能力。\n8.优化升级宽带网络。扩大网络覆盖范围，提高业务承载能力和应用服务水平，实现多制式网络和业务协调发展。加快下一代互联网大规模部署和商用，推进公众通信网、广播电视网和下一代互联网融合发展。加强未来网络长期演进的战略布局和技术储备，构建国家统一试验平台。积极开展第五代移动通信(5G)技术的研发、标准和产业化布局。\n9.提高普遍服务水平。科学灵活选择接入技术，分类推进农村网络覆盖。发达地区优先推进光纤到村。边远地区、林牧区、海岛等区域根据条件采用移动蜂窝、卫星通信等多种方式实现覆盖。居住分散、位置偏远、地理条件恶劣的地区可结合人口搬迁、集中安置实现网络接入。完善电信普遍服务补偿机制，建立支持农村和中西部地区宽带网络发展长效机制，推进网络提速降费，为社会困难群体运用网络创造条件。\n(三)开发信息资源，释放数字红利\n信息资源日益成为重要的生产要素和社会财富，信息掌握的多寡、信息能力的强弱成为衡量国家竞争力的重要标志。当前，我国信息资源开发利用不足与无序滥用的现象并存，要加强顶层设计和系统规划，完善制度体系，全面提升信息采集、处理、传输、利用、安全能力，构筑国家信息优势。\n10.加强信息资源规划、建设和管理。推动重点信息资源国家统筹规划和分类管理，增强关键信息资源掌控能力。完善基础信息资源动态更新和共享应用机制。创新部门业务系统建设运营模式，逐步实现业务应用与数据管理分离。统筹规划建设国家互联网大数据平台。逐步开展社会化交易型数据备份和认证，确保数据可追溯、可恢复。\n11.提高信息资源利用水平。建立公共信息资源开放目录，构建统一规范、互联互通、安全可控的国家数据开放体系，积极稳妥推进公共信息资源开放共享。发展信息资源市场，促进信息消费。引导和规范公共信息资源增值开发利用，支持市场主体利用全球信息资源开展业务创新。\n12.建立信息资源基本制度体系。探索建立信息资产权益保护制度，实施分级分类管理，形成重点信息资源全过程管理体系。加强采集管理和标准制定，提高信息资源准确性、可靠性和可用性。依法保护个人隐私、企业商业秘密，确保国家安全。研究制定信息资源跨境流动管理办法。\n(四)优化人才队伍，提升信息技能\n人才资源是第一资源，人才竞争是最终的竞争。要完善人才培养、选拔、使用、评价、激励机制，破除壁垒，聚天下英才而用之，为网信事业发展提供有力人才支撑。\n13.造就一批领军人才。依托国家重大人才工程，加大对信息化领军人才支持力度，培养造就世界水平的科学家、网络科技领军人才、卓越工程师、高水平创新团队和信息化管理人才。吸引和扶持海外高层次人才回国创新创业，建立海外人才特聘专家制度，对需要引进的特殊人才，降低永久居留权门槛，探索建立技术移民制度，提高我国在全球配置人才资源能力。\n14.壮大专业人才队伍。构建以高等教育、职业教育为主体，继续教育为补充的信息化专业人才培养体系。在普通本科院校和职业院校中设置信息技术应用课程。推广订单式人才培养，建立信息化人才培养实训基地。支持与海外高水平机构联合开展人才培养。\n15.完善人才激励机制。采取特殊政策，建立适应网信特点的人事制度、薪酬制度、人才评价机制，打破人才流动的体制界限。拓宽人才发现渠道，支持开展创新创业大赛、技能竞赛等活动，善用竞争性机制选拔特殊人才。完善技术入股、股权期权等激励方式，建立健全科技成果知识产权收益分配机制。\n16.提升国民信息技能。改善中小学信息化环境，推进信息化基础教育。全面开展国家工作人员信息化培训和考核。实施信息扫盲行动计划，发挥博士服务团、大学生村官、大学生志愿服务西部计划、“三支一扶”等项目的作用，为老少边穷地区和弱势群体提供知识和技能培训。\n(五)深化合作交流，拓展发展空间\n互联网真正让世界变成了地球村，让国际社会越来越成为你中有我、我中有你的命运共同体。要积极开展双边、多边国际交流合作，共同应对网络安全面临的挑战，共同维护网络空间的公平正义，共同分享全球信息革命的机遇和成果。\n17.深化国际合作交流。加强在联合国、二十国集团、金砖国家、亚太经济合作组织、上海合作组织等国际框架和多边机制内的协调配合，推动建立信息化领域国际互信对话机制。组织搭建合作渠道，建设全球信息化最佳实践推广平台。实施中美、中欧、中英、中德数字经济合作项目。\n18.参与国际规则制定。积极参与国际网络空间安全规则制定。巩固和发展区域标准化合作机制，积极争取国际标准化组织重要职位。在移动通信、下一代互联网、下一代广播电视网、云计算、大数据、物联网、智能制造、智慧城市、网络安全等关键技术和重要领域，积极参与国际标准制定。鼓励企业、科研机构、社会组织和个人积极融入国际开源社区。\n19.拓展国际发展空间。推进“一带一路”建设信息化发展，统筹规划海底光缆和跨境陆地光缆建设，提高国际互联互通水平，打造网上丝绸之路。加快推动与周边国家信息基础设施互联互通，打通经中亚到西亚、经南亚到印度洋、经俄罗斯到中东欧国家等陆上通道，积极推进美洲、欧洲、非洲等方向海底光缆建设。合作建设中国-中亚信息平台、中国-东盟信息港、中阿网上丝绸之路。统筹规划我国全球网络设施建设，支持企业拓展海外业务与节点布局，提升我国在全球网络中的影响力。\n20.共建国际网络新秩序。坚持尊重网络主权、维护和平安全、促进开放合作、构建良好秩序的原则，推动建立多边、民主、透明的国际互联网治理体系。积极参与和推进互联网名称与数字地址分配机构(ICANN)国际化改革。加强国际网络空间执法合作，推动制定网络空间国际反恐公约。健全打击网络犯罪司法协助机制，共同维护网络空间和平安全。","level":1},{"name":"四、着力提升经济社会信息化水平","text":"(一)培育信息经济，促进转型发展\n加快建设数字中国、大力发展信息经济是信息化工作的重中之重。要围绕推进供给侧结构性改革，发挥信息化对全要素生产率的提升作用，培育发展新动力，塑造更多发挥先发优势的引领型发展，支撑我国经济向形态更高级、分工更优化、结构更合理的阶段演进。\n21.推进信息化和工业化深度融合。加快实施《中国制造2025》，推动工业互联网创新发展。以智能制造为突破口，加快信息技术与制造技术、产品、装备融合创新，推广智能工厂和智能制造模式，全面提升企业研发、生产、管理和服务的智能化水平。普及信息化和工业化融合管理体系标准，深化互联网在制造领域的应用，积极培育众创设计、网络众包、个性化定制、服务型制造等新模式，完善产业链，打造新型制造体系。\n22.加快推进农业现代化。把信息化作为农业现代化的制高点，推动信息技术和智能装备在农业生产经营中的应用，培育互联网农业，建立健全智能化、网络化农业生产经营体系，加快农业产业化进程。加强耕地、水、草原等重要资源和主要农业投入品联网监测，健全农业信息监测预警和服务体系，提高农业生产全过程信息管理服务能力，确保国家粮食安全和农产品质量安全。\n23.推进服务业网络化转型。支持运用互联网开展服务模式创新，加快传统服务业现代化进程，提高生活性服务业信息化水平。积极培育设计、咨询、金融、交通、物流、商贸等生产性服务业，推动现代服务业网络化发展。大力发展跨境电子商务，构建繁荣健康的电子商务生态系统。引导和规范互联网金融发展，有效防范和化解金融风险。发展分享经济，建立网络化协同创新体系。\n24.促进区域协调发展。转变城镇化发展方式，破解制约城乡发展的信息障碍，促进城镇化和新农村建设协调推进。加强顶层设计，提高城市基础设施、运行管理、公共服务和产业发展的信息化水平，分级分类推进新型智慧城市建设。实施以信息化推动京津冀协同发展、信息化带动长江经济带发展行动计划。支持港澳地区发展信息经济。\n25.夯实发展新基础。推进物联网设施建设，优化数据中心布局，加强大数据、云计算、宽带网络协同发展，增强应用基础设施服务能力。加快电力、民航、铁路、公路、水路、水利等公共基础设施的网络化和智能化改造。发挥信息化支撑作用，推动安全支付、信用体系、现代物流等新型商业基础设施建设，形成大市场、大流通、大服务格局，奠定经济发展新基石。\n26.优化政策环境。完善互联网企业资本准入制度，设立中国互联网投资基金，引导多元化投融资市场发展。发挥中国互联网发展基金会的作用，组建中国“互联网+”联盟，支持中小微互联网企业成长。深入推进简政放权、放管结合、优化服务。设立国家信息经济示范区。\n(二)深化电子政务，推进国家治理现代化\n适应国家现代化发展需要，更好用信息化手段感知社会态势、畅通沟通渠道、辅助科学决策。持续深化电子政务应用，着力解决信息碎片化、应用条块化、服务割裂化等问题，以信息化推进国家治理体系和治理能力现代化。\n27.服务党的执政能力建设。推进党委信息化工作，提升党委决策指挥的信息化保障能力。充分运用信息技术提高党员、干部、人才管理和服务的科学化水平。加强信息公开，畅通民主监督渠道，全面提高廉政风险防控和巡视工作信息化水平，增强权力运行的信息化监督能力。加强党内法规制度建设信息化保障，重视发挥互联网在党内法规制定和宣传中的作用。推进信息资源共享，提升各级党的部门工作信息化水平。\n28.提高政府信息化水平。完善部门信息共享机制，建立国家治理大数据中心。加强经济运行数据交换共享、处理分析和监测预警，增强宏观调控和决策支持能力。深化财政、税务信息化应用，支撑中央和地方财政关系调整，促进税收制度改革。推进人口、企业基础信息共享，有效支撑户籍制度改革和商事制度改革。推进政务公开信息化，加强互联网政务信息数据服务平台和便民服务平台建设，提供更加优质高效的网上政务服务。\n29.服务民主法治建设。建立健全网络信息平台，密切人大代表同人民群众的联系。加快政协信息化建设，推进协商民主广泛多层制度化发展。实施“科技强检”，推进检察工作现代化。建设“智慧法院”，提高案件受理、审判、执行、监督等各环节信息化水平，推动执法司法信息公开，促进司法公平正义。\n30.提高社会治理能力。加快创新立体化社会治安防控体系，提高公共安全智能化水平，全面推进平安中国建设。构建基层综合服务管理平台，推动政府职能下移，支持社区自治。依托网络平台，加强政民互动，保障公民知情权、参与权、表达权、监督权。推行网上受理信访，完善群众利益协调、权益保障机制。\n31.健全市场服务和监管体系。实施“多证合一”、“一照一码”制度，在海关、税务、工商、质检等领域推进便利化服务，加强事中事后监管与服务，实现服务前移、监管后移。以公民身份号码、法人和其他组织统一社会信用代码为基础，建立全国统一信用信息网络平台，构建诚信营商环境。建设食品药品、特种设备等重要产品信息化追溯体系，完善产品售后服务质量监测。加强在线即时监督监测和非现场监管执法，提高监管透明度。\n32.完善一体化公共服务体系。制定在线公共服务指南，支持各级政府整合服务资源，面向企业和公众提供一体化在线公共服务，促进公共行政从独立办事向协同治理转变。各部门要根据基层服务需求，开放业务系统和数据接口，推动电子政务服务向基层延伸。\n33.创新电子政务运行管理体制。建立强有力的国家电子政务统筹协调机制，制定电子政务管理办法，建立涵盖规划、建设、应用、管理、评价的全流程闭环管理机制。大力推进政府采购服务，试点推广政府和社会资本合作模式，鼓励社会力量参与电子政务建设。鼓励应用云计算技术，整合改造已建应用系统。\n(三)繁荣网络文化，增强国家软实力\n互联网是传播人类优秀文化、弘扬正能量的重要载体。要始终坚持社会主义先进文化前进方向，坚持正确舆论导向，遵循网络传播规律，弘扬主旋律，激发正能量，大力培育和践行社会主义核心价值观，发展积极向上的网络文化，把中国故事讲得愈来愈精彩，让中国声音愈来愈洪亮。\n34.提升网络文化供给能力。实施网络内容建设工程。加快文化资源数字化建设，提高网络文化生产的规模化、专业化水平。整合公共文化资源，构建公共文化服务体系，提升信息服务水平。引导社会力量积极开发适合网络传播特点、满足人们多样化需求的网络文化产品。\n35.提高网络文化传播能力。完善网络文化传播机制，构建现代文化传播体系。推动传统媒体和新兴媒体融合发展，有效整合各种媒介资源和生产要素。实施中华优秀文化网上传播工程，加强港澳地区网络传播能力建设，完善全球信息采集传播网络，逐步形成与我国国际地位相适应的网络国际传播能力。\n36.加强网络文化阵地建设。做大做强中央主要新闻网站和地方重点新闻网站，规范引导商业网站健康有序发展。推进重点新闻网站体制机制创新。加快党报党刊、通讯社、电台电视台数字化改造和技术升级。推动文化金融服务模式创新，建立多元网络文化产业投融资体系。鼓励优秀互联网企业和文化企业强强联合，培育一批具有国际影响力的新型文化集团、媒体集团。\n37。规范网络文化传播秩序。综合利用法律、行政、经济和行业自律等手段，规范网络信息传播秩序。坚决遏制违法有害信息网上传播，巩固壮大健康向上的主流舆论。完善网络文化服务市场准入和退出机制，加大网络文化管理执法力度，打击网络侵权盗版行为。\n(四)创新公共服务，保障和改善民生\n围绕人民群众最关心最直接最现实的利益问题，大力推进社会事业信息化，优化公共服务资源配置，降低应用成本，为老百姓提供用得上、用得起、用得好的信息服务，促进基本公共服务均等化。\n38.推进教育信息化。完善教育信息基础设施和公共服务平台，推进优质数字教育资源共建共享和均衡配置，建立适应教育模式变革的网络学习空间，缩小区域、城乡、校际差距。建立网络环境下开放学习模式，鼓励更多学校应用在线开放课程，探索建立跨校课程共享与学分认定制度。完善准入机制，吸纳社会力量参与大型开放式网络课程建设，支撑全民学习、终身教育。\n39.加快科研信息化。加强科研信息化管理，构建公开透明的国家科研资源管理和项目评价机制。建设覆盖全国、资源共享的科研信息化基础设施，提升科研信息服务水平。加快科研手段数字化进程，构建网络协同的科研模式，推动科研资源共享与跨地区合作，促进科技创新方式转变。\n40.推进智慧健康医疗服务。完善人口健康信息服务体系，推进全国电子健康档案和电子病历数据整合共享，实施健康医疗信息惠民行动，促进和规范健康医疗大数据应用发展。探索建立市场化远程医疗服务模式、运营机制和管理机制，促进优质医疗资源纵向流动。加强区域公共卫生服务资源整合，探索医疗联合体等新型服务模式。运用新一代信息技术，满足多元服务需求，推动医疗救治向健康服务转变。\n41.提高就业和社会保障信息化水平。推进就业和养老、医疗、工伤、失业、生育、保险等信息全国联网。建立就业创业信息服务体系，引导劳动力资源有序跨地区流动，促进充分就业。加快社会保障“一卡通”推广和升级，实行跨地区应用接入，实现社会保险关系跨地区转移接续和异地就医联网结算。加快政府网站信息无障碍建设，鼓励社会力量为残疾人提供个性化信息服务。\n42.实施网络扶贫行动计划。构建网络扶贫信息服务体系，加快贫困地区互联网建设步伐，扩大光纤网、宽带网有效覆盖。开展网络公益扶贫宣传，鼓励网信企业与贫困地区结对帮扶，开发适合民族边远地区特点和需求的移动应用，建立扶贫跟踪监测和评估信息系统。\n(五)服务生态文明建设，助力美丽中国\n建设生态文明是关乎人民福祉和民族未来的长远大计。要着力破解资源约束趋紧、环境污染严重、生态系统退化问题，构建基于信息化的新型生态环境治理体系，加快建设天蓝、地绿、水净的美丽中国。\n43.创新资源管理和利用方式。开展国家自然生态空间统一确权登记。整合自然生态空间数据，优化资源开发利用的空间格局和供应时序。完善自然资源监管体系，逐步实现全程、全覆盖动态监管，提高用途管制能力。探索建立废弃物信息管理和交易体系，形成再生资源循环利用机制。\n44.构建新型生态环境治理体系。健全环境信息公开制度。实施生态文明和环境保护监测信息化工程，逐步实现污染源、污染物、生态环境全时监测，提高区域流域环境污染联防联控能力。推动建立绿色低碳循环发展产业体系，鼓励有条件地区探索开展节能量、碳排放权、排污权、水权网上交易。利用信息技术提高生态环境修复能力，促进生态环境根本性改善。\n(六)加快信息强军，构建现代军事力量体系\n积极适应国家安全形势新变化、信息技术发展新趋势和强军目标新要求，坚定不移把信息化作为军队现代化建设发展方向，贯彻军民融合深度发展战略思想，在新的起点上推动军队信息化建设跨越发展。\n45.加强体系化建设。创新发展信息化军事理论，加强信息化建设集中统管，发挥作战需求牵引作用，推进机械化信息化有机融合。完善信息基础设施，推动指挥信息系统集成运用，加大信息资源开发利用力度，构建信息安全防御体系，全面提高打赢信息化局部战争能力。\n46.提高实战化训练水平。适应战争形态演变趋势，依托网络信息系统，开展以信息主导、体系对抗、精确作战、全域机动、网络防控为主要特征的检验性、对抗性演习，推进军事训练向实战化转变，提高以夺取制信息权为核心的战场综合控制权能力。\n47.深化军事斗争准备。充分发挥信息化融合、渗透作用，深化国防和军队改革，推进军队组织形态现代化。健全国防信息动员领导管理体制机制，完善国防信息动员与应急保障预案。大力培养信息化作战指挥、信息技术专业、信息系统组织运用及操作维护等作战急需人才，不断增强官兵运用信息系统和信息化装备打胜仗的能力。","level":1},{"name":"五、不断优化信息化发展环境","text":"(一)推进信息化法治建设\n依法推进信息化、维护网络安全是全面依法治国的重要内容。要以网络空间法治化为重点，发挥立法的引领和推动作用，加强执法能力建设，提高全社会自觉守法意识，营造良好的信息化法治环境。\n48.完善信息化法律框架。以网络立法为重点，加快建立以促进信息化发展和强化网络安全管理为目标，涵盖网络基础设施、网络服务提供者、网络用户、网络信息等对象的法律、行政法规框架。\n49.有序推进信息化立法进程。坚持急用先行，加快出台急需法律法规和规范性文件。强化网络基础设施保护，加快制定网络安全法、电信法、电子商务法，研究制定密码法。加强网络用户权利保护，研究制定个人信息保护法、未成年人网络保护条例。规范网络信息服务与管理，修订互联网信息服务管理办法。研究制定电子文件管理条例。完善司法解释，推动现有法律延伸适用到网络空间。\n50.加强执法能力建设。加强部门信息共享与执法合作，创新执法手段，形成执法合力。理顺网络执法体制机制，明确执法主体、执法权限、执法标准。\n(二)加强网络生态治理\n网络空间是亿万民众共同的精神家园。网络空间天朗气清、生态良好，符合人民利益。坚持正能量是总要求、管得住是硬道理，创新改进网上正面宣传，加强全网全程管理，建设为民、文明、诚信、法治、安全、创新的网络空间，使网络空间清朗起来。\n51.强化互联网管理。坚持积极利用、科学发展、依法管理、确保安全的方针，建立法律规范、行政监管、行业自律、技术保障、公众监督、社会教育相结合的网络治理体系。落实网络身份管理制度，建立网络诚信评价体系，健全网络服务提供者和网民信用记录，完善褒奖和惩戒机制。加强互联网域名、地址等基础资源管理，确保登记备案信息真实准确。强化网络舆情管理，对所有从事新闻信息服务、具有媒体属性和舆论动员功能的网络传播平台进行管理。依法完善互联网信息服务市场准入和退出机制。\n52.形成全社会参与的治理机制。坚持依法治网，加快建立政府引领，企业、社会组织、技术社群、公民共同参与、相互协作的互联网治理机制。强化互联网企业的主体责任，引导企业公平竞争、自我管理和改善服务。建立健全网络社会组织，充分发挥社会组织自我管理、自我监督作用。加强社会力量引导，积极培育“中国好网民”。\n53.维护公民合法权益。依法保护信息自由有序流动，切实保障公民基本权利和自由。全面规范企业和个人信息采集、存储、使用等行为，防范信息滥用。加强个人数据保护，依法打击网络违法犯罪。\n(三)维护网络空间安全\n树立正确的网络安全观，坚持积极防御、有效应对，增强网络安全防御能力和威慑能力，切实维护国家网络空间主权、安全、发展利益。\n54.维护网络主权和国家安全。依法管理我国主权范围内的网络活动，坚定捍卫我国网络主权。坚决防范和打击通过网络分裂国家、煽动叛乱、颠覆政权、破坏统一、窃密泄密等行为。\n55.确保关键信息基础设施安全。加快构建关键信息基础设施安全保障体系，加强党政机关以及重点领域网站的安全防护，建立政府、行业与企业网络安全信息有序共享机制。建立实施网络安全审查制度，对关键信息基础设施中使用的重要信息技术产品和服务开展安全审查。健全信息安全等级保护制度。\n56.强化网络安全基础性工作。加强网络安全基础理论研究、关键技术研发和技术手段建设，建立完善国家网络安全技术支撑体系，推进网络安全标准化和认证认可工作。提升全天候全方位感知网络安全态势能力，做好等级保护、风险评估、漏洞发现等基础性工作，完善网络安全监测预警和网络安全重大事件应急处置机制。实施网络安全人才工程，开展全民网络安全教育，提升网络媒介素养，增强全社会网络安全意识和防护技能。","level":1},{"name":"六、体制保障和组织实施","text":"要加强统筹协调，有力整合资源，形成推进合力，切实将各项战略任务落到实处，确保战略目标如期实现。\n(一)强化组织领导。坚持中央网络安全和信息化领导小组对国家信息化发展的集中统一领导，信息化领域重大政策和事项须经领导小组审定。各级网络安全和信息化领导小组要加强统筹，研究解决本地区信息化发展中的重大问题。\n(二)健全工作机制。中央网络安全和信息化领导小组办公室负责统筹协调本战略纲要的实施和督促检查。各级网络安全和信息化主管部门要充分发挥组织协调作用，加强部门、行业、区域、军地间合作，形成统一领导、分工合理、责任明确、运转顺畅的信息化推进机制。加快中国特色新型信息化智库建设，完善重大政策、重大项目专家咨询制度。\n(三)完善配套政策。各地区各部门要将本战略纲要提出的任务与经济社会发展规划有效衔接、同步推进，制定好“十三五”信息化发展规划和相关专项规划。相关部门要加快完善产业、财税、金融、科技、教育等领域配套政策措施，加大财政投入和管理，重点支持关键性、基础性、公共性领域的信息化建设和网络安全保障。加大政府购买服务力度，创新信息化投融资机制，在信息化领域实行有利于商业运作、持续运营的政策，为社会投资参与创造条件。\n(四)加强督促落实。各地区各部门要按照职责分工细化任务，明确时限，逐级落实。建立和完善信息化统计指标体系，加强信息化统计监测和评估工作，组织开展战略实施年度检查与绩效评估。加大信息化工作考核力度，将考核结果作为评价有关领导干部的内容。","level":1}]},{"id":"r0533","sections":[{"name":"中共中央关于加强党的政治建设的意见","text":"中共中央关于加强党的政治建设的意见\n（2019年1月31日）","level":1},{"name":"","text":"为深入贯彻落实习近平新时代中国特色社会主义思想和党的十九大精神，切实加强党的政治建设，坚持和加强党的全面领导，推进全面从严治党向纵深发展，不断提高党的执政能力和领导水平，确保全党统一意志、统一行动、步调一致向前进，现提出如下意见。","level":0},{"name":"一、加强党的政治建设的总体要求","text":"旗帜鲜明讲政治是我们党作为马克思主义政党的根本要求。党的政治建设是党的根本性建设，决定党的建设方向和效果，事关统揽推进伟大斗争、伟大工程、伟大事业、伟大梦想。\n在革命、建设、改革各个时期，我们党都高度重视党的政治建设，形成了讲政治的优良传统。党的十八大以来，以习近平同志为核心的党中央把党的政治建设摆在更加突出位置，加大力度抓，形成了鲜明的政治导向，消除了党内严重政治隐患，推动党的政治建设取得重大历史性成就。同时，必须清醒看到，党内存在的政治问题还没有得到根本解决，一些党组织和党员干部忽视政治、淡化政治、不讲政治的问题还比较突出，有的甚至存在偏离中国特色社会主义方向的严重问题。切实有效解决这些问题，必须进一步加强党的政治建设。\n加强党的政治建设，必须高举中国特色社会主义伟大旗帜，全面贯彻党的十九大精神，坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，坚持党的基本理论、基本路线、基本方略，落实新时代党的建设总要求，增强“四个意识”，坚定“四个自信”，坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导，把准政治方向，坚持党的政治领导，夯实政治根基，涵养政治生态，防范政治风险，永葆政治本色，提高政治能力，把我们党建设得更加坚强有力，确保我们党始终成为中国特色社会主义事业的坚强领导核心，为实现“两个一百年”奋斗目标和中华民族伟大复兴的中国梦提供坚强政治保证。\n加强党的政治建设，目的是坚定政治信仰，强化政治领导，提高政治能力，净化政治生态，实现全党团结统一、行动一致。要以党章为根本遵循，把党章明确的党的性质和宗旨、指导思想和奋斗目标、路线和纲领落到实处。要突显党的政治建设的根本性地位，聚焦党的政治属性、政治使命、政治目标、政治追求持续发力。要以党的政治建设为统领，把政治标准和政治要求贯穿党的思想建设、组织建设、作风建设、纪律建设以及制度建设、反腐败斗争始终，以政治上的加强推动全面从严治党向纵深发展，引领带动党的建设质量全面提高。要坚持问题导向，注重“靶向治疗”，针对政治意识不强、政治立场不稳、政治能力不足、政治行为不端等突出问题强弱项补短板。要把党的政治建设融入党和国家重大决策部署的制定和落实全过程，做到党的政治建设与各项业务工作特别是中心工作紧密结合、相互促进。","level":1},{"name":"二、坚定政治信仰","text":"加强党的政治建设，必须坚持马克思主义指导地位，坚持用习近平新时代中国特色社会主义思想武装全党、教育人民，夯实思想根基，牢记初心使命，凝聚同心共筑中国梦的磅礴力量。","level":1},{"name":"（一）坚持用党的科学理论武装头脑","text":"马克思主义是我们立党立国的根本指导思想。习近平新时代中国特色社会主义思想是当代中国马克思主义、21世纪马克思主义，是全党全国人民为实现中华民族伟大复兴而奋斗的行动指南，是经过实践检验、富有实践伟力的强大思想武器，必须长期坚持并不断发展。要深入学习习近平新时代中国特色社会主义思想，加强思想政治教育，推动学习教育往深里走、往心里走、往实里走，真正做到学深悟透、融会贯通、真信笃行，巩固全党全国人民团结奋斗的共同思想基础。要坚定理想信念，牢固树立共产主义远大理想和中国特色社会主义共同理想，挺起共产党人的精神脊梁，坚决防止不信马列信鬼神、不信真理信金钱，坚决反对各种歪曲、篡改、否定马克思主义的错误思想。要坚定“四个自信”，坚信中国特色社会主义是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一，是当代中国发展进步的根本方向，是全面建成小康社会、全面建成社会主义现代化强国、实现中华民族伟大复兴的必由之路。领导干部要带头学理论、强信念，筑牢信仰之基，补足精神之钙，把稳思想之舵。实施年轻干部理想信念宗旨教育计划，大力培养造就具有坚定共产主义信仰和较高马克思主义理论素养的社会主义建设者和接班人。","level":1},{"name":"（二）坚定执行党的政治路线","text":"党在社会主义初级阶段的基本路线作为党的政治路线，是党和国家的生命线、人民的幸福线，必须坚决捍卫、坚定执行。越是面临严峻复杂的国际国内形势，越是处于中华民族伟大复兴的关键时期，越要保持清醒头脑和战略定力，全面贯彻执行党的政治路线，把以经济建设为中心同坚持四项基本原则、坚持改革开放两个基本点统一于中国特色社会主义伟大实践，绝不能有丝毫偏离和动摇。坚持党的政治路线，必须全面贯彻实施新时代中国特色社会主义基本方略，统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，为实现“两个一百年”奋斗目标不懈努力。全党制定执行大政方针，要从党的政治路线出发；部署推进党和国家事业发展重大战略、重大任务、重大工作，要紧紧围绕党的政治路线来进行。各地区各部门确定工作思路、工作部署、政策措施，要自觉同党的政治路线对标对表、及时校准偏差。要坚决同一切违背、歪曲、否定党的政治路线的言行作斗争。","level":1},{"name":"（三）坚决站稳政治立场","text":"政治立场事关根本。全党必须始终坚定马克思主义立场，坚持党性和人民性相统一，坚决站稳党性立场和人民立场。要坚持以党的旗帜为旗帜、以党的方向为方向、以党的意志为意志，始终做到在党言党、在党忧党、在党为党，任何时候都同党同心同德。要坚持以人民为中心，立党为公、执政为民，践行全心全意为人民服务的根本宗旨，树立真挚的人民情怀，把人民放在心中最高位置，始终相信人民，紧紧依靠人民，把人民对美好生活的向往作为奋斗目标。要把对党负责和对人民负责高度统一起来，想问题、作决策、办事情都从人民利益出发，崇尚实干、勤政为民，把精力和心思用在稳增长、促改革、调结构、惠民生、防风险、保稳定上，着力解决人民群众最关心最直接最现实的利益问题，努力让人民群众有更多获得感、幸福感、安全感。","level":1},{"name":"三、坚持党的政治领导","text":"党是最高政治领导力量，党的领导是中国特色社会主义最本质的特征，是中国特色社会主义制度的最大优势。加强党的政治建设，必须坚持和加强党的全面领导，完善党的领导体制，改进党的领导方式，承担起执政兴国的政治责任。","level":1},{"name":"（四）坚决做到“两个维护”","text":"事在四方，要在中央。坚持和加强党的全面领导，最重要的是坚决维护党中央权威和集中统一领导；坚决维护党中央权威和集中统一领导，最关键的是坚决维护习近平总书记党中央的核心、全党的核心地位。要教育引导党员干部从历史和现实、理论和实践、国内和国际的结合上深刻认识、强化认同，不断增强拥护核心、跟随核心、捍卫核心的思想自觉政治自觉行动自觉，始终同以习近平同志为核心的党中央保持高度一致，做到党中央提倡的坚决响应、党中央决定的坚决执行、党中央禁止的坚决不做。要以党章为根本依据，不断完善保障“两个维护”的制度机制，严格执行《关于新形势下党内政治生活的若干准则》、《中国共产党重大事项请示报告条例》、《中共中央政治局关于加强和维护党中央集中统一领导的若干规定》等党内法规，加强对贯彻执行党的路线方针政策和决议情况的督促检查，完善党中央重大决策部署和习近平总书记重要指示批示贯彻落实的督查问责机制。要以正确的认识、正确的行动坚决做到“两个维护”，坚决防止和纠正一切偏离“两个维护”的错误言行，不得搞任何形式的“低级红”、“高级黑”，决不允许对党中央阳奉阴违做两面人、搞两面派、搞“伪忠诚”。","level":1},{"name":"（五）完善党的领导体制","text":"坚持党总揽全局、协调各方，建立健全坚持和加强党的全面领导的制度体系，为把党的领导落实到改革发展稳定、内政外交国防、治党治国治军各领域各方面各环节提供坚实制度保障。研究制定党领导经济社会各方面重要工作的党内法规。健全党中央集中统一领导重大工作的体制机制。完善地方党委、党组、党的工作机关实施党的领导的体制机制。建立健全国有企业党委（党组）和农村、事业单位、街道社区等的基层党组织发挥领导作用的制度规定。贯彻落实宪法规定，制定和修改有关法律法规要明确规定党领导相关工作的法律地位。将坚持党的全面领导的要求载入人大、政府、法院、检察院的组织法，载入政协、民主党派、工商联、人民团体、国有企业、高等学校、有关社会组织等的章程，健全党对这些组织实施领导的制度规定，确保其始终在党的领导下积极主动、独立负责、协调一致地开展工作。","level":1},{"name":"（六）改进党的领导方式","text":"着眼于党把方向、谋大局、定政策、促改革，强化战略思维、创新思维、辩证思维、法治思维、底线思维，正确制定和坚决执行党的路线方针政策，不断增强党的政治领导力、思想引领力、群众组织力、社会号召力。要坚持民主集中制这一根本领导制度，善于运用民主的办法汇集意见、科学决策，善于通过协商的方式增进共识、凝聚力量，同时善于集中、敢于担责，防止议而不决、决而不行。要坚持群众路线这一基本领导方法，不断增强群众工作本领，大兴调查研究之风，改进和创新联系群众的途径方法，坚持走好网上群众路线，汇集民智民力，善于通过群众喜闻乐见方式宣传党的理论和路线方针政策，把党的主张变为群众自觉行动。坚决反对“四风”特别是形式主义、官僚主义。要坚持依法执政这一基本领导方式，注重运用法治思维和法治方式治国理政，善于使党的主张通过法定程序成为国家意志、转化为法律法规，自觉把党的领导活动纳入制度轨道。","level":1},{"name":"四、提高政治能力","text":"加强党的政治建设，关键是要提高各级各类组织和党员干部的政治能力。必须进一步增强党组织政治功能，彰显国家机关政治属性，发挥群团组织政治作用，强化国有企事业单位政治导向，不断提高党员干部特别是领导干部政治本领。","level":1},{"name":"（七）增强党组织政治功能","text":"党的力量来自组织。政治属性是党组织的根本属性，政治功能是党组织的基本功能，要认真贯彻落实新时代党的组织路线，不断强化各级各类党组织的政治属性和政治功能。党中央是党的最高领导机关，是党的组织体系的大脑和中枢，对党和国家事业发展重大工作实行集中统一领导，涉及全党全国性的重大方针政策问题只能由党中央作出决定和解释。地方党委要在党中央和上级党委领导下，全面领导本地区经济社会发展，全面负责本地区党的建设，坚决纠正党的领导弱化、党的建设缺失、全面从严治党不力问题。党的基层组织要着力提升组织力，突出政治功能、强化政治引领，下大气力解决软弱涣散问题。党支部要担负起直接教育党员、管理党员、监督党员和组织群众、宣传群众、凝聚群众、服务群众的职责，发挥好战斗堡垒作用。党组要在批准其设立的党组织领导下，在本部门本单位发挥好把方向、管大局、保落实的重要作用，确保党中央和上级党组织决策部署在本部门本单位贯彻落实。党的各级纪委要进一步强化党内监督专责机关的职能定位，全面监督执纪问责，坚决维护党章党规党纪的严肃性和权威性。党的工作机关要更好发挥党委参谋助手作用，提高履职尽责的政治性和有效性，力求参当其时、谋当其用，更好服务党委决策、抓好决策落实。党员要强化党的意识和组织观念，自觉做到思想上认同组织、政治上依靠组织、工作上服从组织、感情上信赖组织。所有党组织和全体党员都必须牢固树立一盘棋意识，在党中央集中统一领导下齐心协力、步调一致开展工作，形成党的组织体系整体合力。","level":1},{"name":"（八）彰显国家机关政治属性","text":"中央和地方各级人大机关、行政机关、政协机关、监察机关、审判机关、检察机关本质上都是政治机关，旗帜鲜明讲政治是应尽之责。要始终坚持在党的领导下依法实施经济社会管理活动，坚决贯彻落实党的基本理论、基本路线、基本方略，积极主动将党的领导主张和重大决策部署转化为法律法规和政策政令，转化为对经济社会管理的部署安排和工作活动，转化为领导体制、工作机制和管理方式方法创新，转化为推动经济社会发展的实际效果。国家机关履行职责、开展工作，要提高政治站位，把准政治方向，注重政治效果，考虑政治影响，坚决防止和纠正把政治与业务割裂开来、对立起来的错误认识和做法，确保政治和业务融为一体、高度统一。","level":1},{"name":"（九）发挥群团组织政治作用","text":"工会、共青团、妇联等群团组织是党领导下的政治组织，政治性是群团组织的灵魂。各群团组织要认真履行政治职责，充分发挥联系人民群众的桥梁和纽带作用，加大政治动员、政治引领、政治教育工作力度，更好承担起引导群众听党话、跟党走的政治任务，把自己联系的群众最广泛最紧密地团结在党的周围。要坚定不移坚持党的领导，坚定不移走中国特色社会主义群团发展道路，不折不扣落实党中央关于群团改革的决策部署，切实增强群团组织的政治性、先进性、群众性。","level":1},{"name":"（十）强化国有企事业单位政治导向","text":"国有企业是中国特色社会主义的重要物质基础和政治基础，事业单位承担着满足人民群众日益增长的公益服务需求职责，都是我们党执政兴国的重要依靠力量。国有企事业单位必须始终坚持党的领导，坚决贯彻执行党的路线方针政策，认真落实党中央关于推进国有企事业单位改革发展的决策部署，切实加强本单位党的建设工作，充分发挥党组织重要作用，保证本单位工作坚持正确政治方向、取得良好政治效果。","level":1},{"name":"（十一）提高党员干部政治本领","text":"党员干部特别是领导干部要加强政治能力训练和政治实践历练，切实提高把握方向、把握大势、把握全局的能力和辨别政治是非、保持政治定力、驾驭政治局面、防范政治风险的能力。要在大是大非面前态度鲜明、立场坚定，始终在政治立场、政治方向、政治原则、政治道路上同以习近平同志为核心的党中央保持高度一致。要善于从政治上研判形势、分析问题，自觉在党和国家工作大局下想问题、做工作，做到一切服从大局、一切服务大局。要强化忧患意识、风险意识，增强政治敏锐性和政治鉴别力，对容易诱发政治问题特别是重大突发事件的敏感因素、苗头性倾向性问题，对意识形态领域各种错误思潮、模糊认识、不良现象，保持高度警惕，做到眼睛亮、见事早、行动快。要提高风险处置能力，及时阻断不同领域风险转换通道，防止非公共性风险扩大为公共性风险、非政治性风险演变为政治风险。要增强斗争精神，强化政治担当，敢于亮剑、善于斗争，发现违反政治纪律、危害政治安全的行为坚决抵制，做勇于斗争的“战士”，不做爱惜羽毛的“绅士”，严防对挑战政治底线的错误言论和不良风气听之任之、逃避责任、失职失察。","level":1},{"name":"五、净化政治生态","text":"加强党的政治建设，必须把营造风清气正的政治生态作为基础性、经常性工作，浚其源、涵其林，养正气、固根本，锲而不舍、久久为功，实现正气充盈、政治清明。","level":1},{"name":"（十二）严肃党内政治生活","text":"营造良好政治生态，必须严格执行《关于新形势下党内政治生活的若干准则》，着力提高党内政治生活质量，努力在全党形成又有集中又有民主、又有纪律又有自由、又有统一意志又有个人心情舒畅生动活泼的政治局面。增强党内政治生活的政治性，强化政治教育和政治引领，让党员干部经常接受政治体检，打扫政治灰尘，净化政治灵魂，增强政治免疫力，坚决防止和克服党内政治生活忽视政治、淡化政治、不讲政治的倾向。增强党内政治生活的时代性，主动适应信息时代新形势和党员队伍新变化，积极运用互联网、大数据等新兴技术，创新党组织活动内容方式，推进“智慧党建”，使党内政治生活始终充满活力，坚决防止和克服党内政治生活不讲创新、不讲活力、照搬照套的倾向。增强党内政治生活的原则性，坚持按原则开展党的工作和活动，按原则处理党内各种关系，按原则解决党内矛盾和问题，严格执行党的组织生活制度，认真召开民主生活会和组织生活会，提高“三会一课”质量，落实谈心谈话、民主评议党员和主题党日等制度，坚持和完善重温入党誓词、党员过“政治生日”等政治仪式，使党内生活庄重、严肃、规范，坚决防止和克服党内政治生活不讲原则、平淡化庸俗化随意化的倾向。增强党内政治生活的战斗性，坚持以整风精神开展批评和自我批评，勇于思想交锋、揭短亮丑，旗帜鲜明坚持真理、修正错误，统一意志、增进团结，建立健全民主生活会列席指导、及时叫停、责令重开、整改通报等制度，坚决防止和克服党内政治生活一团和气、评功摆好、明哲保身的倾向。","level":1},{"name":"（十三）严明党的政治纪律和政治规矩","text":"政治纪律是党最根本、最重要的纪律，是净化政治生态的重要保证。要把坚决做到“两个维护”作为首要政治纪律，在全党持续深入开展忠诚教育，开展“守纪律、讲规矩”模范机关创建和先进个人评选活动，教育督促党员干部始终对党忠诚老实，决不允许在重大政治原则问题上、大是大非问题上同党中央唱反调，搞自由主义。严格执行《中国共产党纪律处分条例》，严肃查处违反政治纪律的行为，通过严明政治纪律带动党的其他纪律严起来。坚持“五个必须”，必须维护党中央权威，决不允许背离党中央要求另搞一套；必须维护党的团结，决不允许在党内培植个人势力；必须遵循组织程序，决不允许擅作主张、我行我素；必须服从组织决定，决不允许搞非组织活动；必须管好领导干部亲属和身边工作人员，决不允许他们擅权干政、谋取私利。严肃查处“七个有之”问题，把政治上蜕变的两面人及时辨别出来、清除出去，坚决防止党内形成利益集团攫取政治权力、改变党的性质，坚决防止山头主义和宗派主义危害党的团结、破坏党的集中统一。","level":1},{"name":"（十四）发展积极健康的党内政治文化","text":"营造良好政治生态，离不开党内政治文化的浸润滋养。坚持“三严三实”，大力弘扬忠诚老实、公道正派、实事求是、清正廉洁等价值观，充分利用各类爱国主义教育基地和党性教育基地对广大党员干部进行教育和熏陶，增强党员干部的政治定力、纪律定力、道德定力、拒腐定力。大力倡导清清爽爽的同志关系、规规矩矩的上下级关系、干干净净的政商关系，弘扬正气、树立新风。推动中华优秀传统文化创造性转化、创新性发展，培育党员干部政治气节、政治风骨。发扬革命文化，传承红色基因，弘扬革命精神，教育党员干部正确处理公和私、义和利、是和非、正和邪、苦和乐的关系。弘扬社会主义先进文化，推进社会主义核心价值观宣传教育，引导党员干部带头做社会主义核心价值观的坚定信仰者、积极传播者、模范践行者。坚决抵制庸俗腐朽的政治文化，自觉抵制商品交换原则对党内生活的侵蚀，狠刹权权交易、权钱交易、权色交易等不正之风，破除关系学、厚黑学、官场术等封建糟粕，坚决防止和反对个人主义、分散主义、自由主义、本位主义、好人主义，坚决防止和反对宗派主义、圈子文化、码头文化。","level":1},{"name":"（十五）突出政治标准选人用人","text":"选人用人是政治生态的风向标。要坚持党管干部原则，贯彻新时期好干部标准，始终把政治标准放在第一位，注重选拔任用牢固树立“四个意识”、自觉坚定“四个自信”、坚决做到“两个维护”、全面贯彻执行党的理论和路线方针政策、忠诚干净担当的干部，对政治不合格的干部实行“一票否决”，已经在领导岗位的坚决调整。严格执行《党政领导干部选拔任用工作条例》，在选人用人中进一步突出政治标准，强化政治把关。制定实施《党政领导干部考核工作条例》，建立健全领导干部政治素质识别和评价机制，强化对干部政治忠诚、政治定力、政治担当、政治能力、政治自律等方面的深入考察考核，坚决把政治上的两面人挡在门外。匡正选人用人风气，坚持不懈整治选人用人上的不正之风，对任人唯亲、说情打招呼、跑官要官、买官卖官、拉票贿选等行为发现一起查处一起，对“带病提拔”的干部实行倒查，对政治标准把关不严的严肃处理。严格执行干部选拔任用工作纪实制度，对私自干预下级或者原任职地方和单位选人用人的，记录在案并严肃追究责任。","level":1},{"name":"（十六）永葆清正廉洁的政治本色","text":"坚决反对腐败，建设廉洁政治，是涵养政治生态的必要条件和重要任务。强化不敢腐的震慑，坚持反腐败无禁区、全覆盖、零容忍，坚持重遏制、强高压、长震慑，运用监督执纪“四种形态”，重点查处党的十八大以来不收敛、不收手，问题线索反映集中、群众反映强烈，政治问题和经济问题交织的腐败案件，严肃查处违反中央八项规定精神的问题，持续保持反腐败高压态势。扎紧不能腐的笼子，健全党和国家监督体系，加强对权力运行的制约和监督，通过改革和制度创新切断利益输送链条。特别要针对管人管钱管物管项目的单位和岗位，查找廉政风险点，通过科学管理、严格监督和发挥巡视利剑作用，切实管住权力，坚决反对特权行为和特权现象，让人民群众真正感受到清正干部、清廉政府、清明政治就在身边。增强不想腐的自觉，领导干部特别是高级干部要带头加强党性修养，知敬畏、存戒惧、守底线，坚决防范被利益集团“围猎”，持之以恒锤炼政德，明大德、守公德、严私德，带头遵守《中国共产党廉洁自律准则》，注重家庭家教家风，自觉做廉洁自律、廉洁用权、廉洁齐家的模范。","level":1},{"name":"六、强化组织实施","text":"加强党的政治建设是一项重大艰巨的政治任务。各地区各部门要进一步增强推进党的政治建设的自觉性坚定性，把思想和行动统一到党中央部署要求上来，加强组织领导、强化责任担当，确保本意见提出的各项举措落到实处，确保党的政治建设取得成效。","level":1},{"name":"（十七）落实领导责任","text":"建立健全推进党的政治建设工作责任制，各级党委（党组）要切实负起本地区本部门党的政治建设工作主体责任，将其纳入党委（党组）工作总体布局，摆在首要位置来抓，认真研究部署、大力推进落实。党委（党组）书记要认真履行第一责任人职责，对党的政治建设重要工作亲自部署、重要问题亲自过问、重大事件亲自处置。党委（党组）其他成员要根据职责分工，按照“一岗双责”要求，抓好分管部门和领域党的政治建设工作。各级党的建设工作领导小组要发挥统筹协调的职能作用，各级纪检监察机关和党委有关部门要各司其职、各负其责，履行推进党的政治建设工作相关职责。中央和国家机关要在推进党的政治建设上带好头、作示范，在深入学习贯彻习近平新时代中国特色社会主义思想上作表率，在始终同党中央保持高度一致上作表率，在坚决贯彻落实党中央决策部署上作表率，建设让党中央放心、让人民群众满意的模范机关。","level":1},{"name":"（十八）抓住“关键少数”","text":"加强党的政治建设，要坚持抓“关键少数”和管“绝大多数”相结合，重点是抓住领导机关和领导干部，发挥其示范引领作用。各级领导干部特别是高级干部要深刻认识自己在加强党的政治建设中的特殊重要性和肩负的重大责任，职位越高越要自觉严格要求自己，注重加强政治历练、积累政治经验、增进政治智慧，做到信念如磐、意志如铁，政治坚定、绝对忠诚，清正廉洁、担当负责，坚决做到“两个维护”，成为坚定的马克思主义者。实施“一把手”政治能力提升计划。","level":1},{"name":"（十九）强化制度保障","text":"加强党的政治建设，要把建章立制贯穿全过程各方面，建立健全长效机制，形成系统完备、有效管用的政治规范体系，真正实现党的政治建设有章可循、有据可依。坚持集成联动，完善党内法规制度体系有关制度，健全国家法律体系有关规定，在各类章程中明确提出有关要求，做到相辅相成、有机统一。坚持明确标准，既提出政治高线，激励党员干部向往践行，又划出政治底线，防止党员干部逾矩失范。坚持执规必严，加大宣传教育和执行力度，督促党员干部把党的政治规范刻印在心上、落实在行动上，坚决维护制度权威。","level":1},{"name":"（二十）加强监督问责","text":"各地区各部门要加强对党的政治建设工作的监督检查，将其作为巡视巡察和督查检查的重要内容，深化政治巡视，强化政治监督，着力发现和纠正政治偏差。探索建立本地区本部门政治生态评价体系。把党的政治建设工作情况纳入党委（党组）书记抓党建述职评议和党建考核评价体系，并突出其权重。坚持失责必问、问责必严，对落实党的政治建设责任不到位、推进党的政治建设工作不力以及违反党的政治纪律和政治规矩的行为严肃追责问责。\n各地区各部门要紧密结合自身实际制定贯彻实施本意见的具体措施。中央军委可以根据本意见提出加强军队党的政治建设的具体意见。\n延伸阅读\n中央办公厅负责人就《中共中央关于加强党的政治建设的意见》答记者问\n人民日报评论员：把党的政治建设摆在首位","level":1}]},{"id":"r0534","sections":[{"name":"中共中央办公厅 国务院办公厅关于完善自然资源资产管理制度体系的意见","text":"中共中央办公厅 国务院办公厅关于完善自然资源资产管理制度体系的意见\n（2026年7月4日）","level":1},{"name":"","text":"为完善自然资源资产管理制度体系，落实统一履行全民所有自然资源资产所有者职责，促进自然资源安全、高效、永续利用和资产保值增值，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，全面贯彻习近平生态文明思想，牢固树立和践行绿水青山就是金山银山的理念，尊重自然、顺应自然、保护自然，处理好高质量发展与高水平保护的关系，以健全自然资源资产产权制度为主线，强化自然资源整体保护，促进自然资源资产高效配置，维护自然资源资产所有者权益，健全自然资源资产管理体制机制，加强监督管理，守牢资源安全底线，为推进人与自然和谐共生的现代化提供有力支撑和保障。\n主要目标是：到2030年，自然资源资产管理制度体系更加健全，履职主体更加明确、资产家底更加清晰、整体保护更加有力、资产配置更加高效、考核监督更加完善，各类自然资源资产和全部国土空间得到有效保护，自然资源资产管理水平明显提升。到2035年，自然资源资产管理体制机制运转顺畅，系统完备的自然资源资产管理制度体系全面建立，自然资源资产管理水平全面提升。","level":1},{"name":"二、摸清自然资源资产家底","text":"（一）完善自然资源统一调查监测评价制度。覆盖土地、矿产、森林、草原、湿地、水、海洋、荒漠等各类自然资源以及国家公园等国土空间，完善统一调查标准体系。统筹实施国土调查及年度变更调查、自然资源专项调查和监测、国土空间动态监测，体系化开展海洋综合调查，优化森林草原湿地荒漠调查监测等，全面掌握自然资源本底。推进新型基础测绘体系建设，基于统一的时空基准构建自然资源管理和国土空间规划“一张图”。基于国土空间基础信息平台强化调查监测数据分析评价，健全自然资源调查监测评价成果应用和共享机制。加快推进调查监测工作数字化转型。\n（二）健全自然资源资产清查统计核算制度。融合运用自然资源调查、国土空间监测、确权登记、分等定级估价等成果，定期开展自然资源资产清查，查清实物量、探索核算价值量，摸清自然资源资产底数，理清使用权状况。建立自然资源资产清查成果年度更新机制，加强清查成果分析应用。健全全民所有自然资源资产统计制度。完善自然资源资产负债表编制制度并推进常态化编制。探索开展自然资本核算。","level":1},{"name":"三、健全自然资源资产产权制度","text":"（三）健全自然资源资产用益物权等权利体系。坚持资源公有、物权法定，依法设立和保护自然资源资产使用权，推动自然资源资产所有权与使用权分离。建立和完善自然资源资产权利体系，明确相应权利内容和行使方式，解决资源种类交叉重叠时权利不清等问题。探索单独设立深层地下空间建设用地使用权，完善与规划保护利用方式相适应的地下空间权利体系。推动设立国有农用地使用权，健全国有农用地权利体系。完善填海成陆后海域使用权向土地使用权转换的衔接机制。构建无居民海岛权利体系。依法依规推进用水权改革，明确各区域和各类取用水户的用水权利边界。\n（四）全面推进自然资源和不动产统一确权登记。深化自然资源确权登记制度改革，推进水流、森林、山岭、草原、荒地、滩涂、海域、无居民海岛以及探明储量的矿产资源等自然资源和国家公园、自然保护区、自然公园（含风景名胜区）等国土空间的统一确权登记，明晰自然资源资产的产权主体和权属界线。巩固不动产统一登记改革成果，提升登记规范化水平和便利度。深化农村集体土地所有权登记成果更新应用。规范高效做好林权类、海域使用权和无居民海岛使用权不动产登记。加快完善地籍数据库，推动形成统一产权底板。","level":1},{"name":"四、强化自然资源整体保护","text":"（五）促进自然资源资产保值增值。建立自然资源资产管理指标体系并发挥引导作用，强化整体保护和合理利用，严守耕地和永久基本农田保护红线，强化生态保护红线底线约束，严格城镇开发边界管控。结合国土空间规划编制实施，推进土地混合开发、空间复合利用和土地用途依法合理转换。健全主体功能区制度体系，引导各地区立足资源禀赋发挥比较优势，充分挖掘和提升自然资源资产价值。在自然资源开发利用全过程强化生态保护修复和系统治理，健全市场化多元化投入机制，通过保护修复促进自然资源资产保值增值。完善生态产品价值实现机制，探索建立资源权益指标市场化交易机制、大陆自然岸线占用与修复平衡机制、生态保护红线内建设用地腾退指标交易激励机制，实现保护成本共担、生态效益共享。\n（六）优化自然资源资产储备管护机制。完善土地储备分级管理，将所有未确定使用权人的国有建设用地纳入储备管理。探索开展自然资源资产综合收储，制定自然资源资产储备计划，分类实施储备资产管护，对公益性特征明显的自然资源资产主要实施日常管护，对经营性特征明显的自然资源资产可进行必要的前期开发和临时利用。探索由自然资源资产专业运营机构、国有林业或农业经营单位等符合条件的主体承担特定自然资源资产管护等工作。","level":1},{"name":"五、促进自然资源资产高效配置","text":"（七）完善自然资源资产市场制度和规则。深化自然资源资产有偿使用制度改革，依法依规建立健全自然资源资产划拨、出让、租赁、作价出资（入股）、联营和承包经营等配置规则，完善相关自然资源资产配置合同，明确各方权利义务责任并实施全生命周期管理。探索建立国有农用地有偿使用制度。全面推进矿业权竞争性出让，严格控制协议出让。逐步提高海域使用权市场化配置比例。培育和规范用水权交易市场。依法依规制定自然资源资产分等定级估价规则，健全自然资源资产价格体系。完善自然资源资产交易机制，加强市场动态监测监管，建立市场信用体系，维护自然资源资产市场秩序。\n（八）构建自然资源资产配置新模式新路径。根据国民经济和社会发展规划、国土空间规划，探索编制自然资源资产配置方案，区分公益性、经营性资产，因地制宜在国土空间规划中划定储备片区、配置单元，统筹谋划自然资源资产储备、配置、价值实现、收益管理等内容，形成资产组合标的。加强自然资源资产配置方案与国土空间规划的协同，结合落实详细规划有关土地和空间使用性质、开发强度等要求，明确并细化自然资源资产配置的规模、用途、结构、形态、方式、时序。完善多要素自然资源资产组合配置规则和估价技术体系，在特定国土空间范围内涉及同一使用主体需整体使用多种类自然资源资产的，可依法实行组合配置。将各种类自然资源资产的使用条件、开发要求、起始价、收益核算和生态保护修复要求等纳入组合标的配置方案，一并向社会公告、签订资产配置合同，相关部门按职责进行监管。探索研究自然资源资产组合配置收益按资源种类核算方法，并与自然资源资产收益分配和管理制度做好衔接。","level":1},{"name":"六、完善自然资源资产监督考核","text":"（九）加强自然资源资产收益管理。建立统一的全民所有自然资源资产收益管理制度，相关收入全部纳入政府预算。健全全民所有自然资源资产收益成本核算制度，加强自然资源资产收益管理。健全农村集体经营性建设用地入市增值收益分配机制。\n（十）强化自然资源资产管理监督。制定全民所有自然资源资产所有权资源清单管理办法，编制所有权资源清单，明确主体、对象、权利义务责任等。加强自然资源保护利用全流程监管，压实履职主体的保护责任。统筹开展自然资源资产管理责任考核，探索对自然资源资产履职主体的考核评价。更好发挥国家自然资源督察机制作用，依职责对全民所有自然资源资产所有者职责履行和权益维护情况开展监督。探索建立国有自然资源资产损害赔偿机制，并做好与检察公益诉讼制度、生态环境损害赔偿制度的衔接，所有者职责履行主体及承担管护工作的主体根据法定职责或清单管理事项，承担资产损害的发现、核实、索赔和报告责任，有权依法要求侵权人停止侵害、恢复原状、赔偿损失和作为原告向法院提起诉讼。\n（十一）完善自然资源资产统一报告制度。完善政府向同级人大常委会专项报告国有自然资源资产管理情况的机制。建立自然资源资产管理及履职情况报告机制。依法向社会公布国有自然资源资产状况和管理情况，接受社会监督。","level":1},{"name":"七、加强组织实施","text":"坚持党中央对自然资源资产管理工作的集中统一领导。按照中央统筹、省负总责、市县抓落实的要求，强化自然资源资产管理工作组织协调。各地区各有关部门要树立和践行正确政绩观，密切协同配合，以全链条协作促进一体化治理，加强对各类风险的监测预警，提升风险防控能力，确保自然资源资产管理各项制度落地落实。要严明纪律规矩，强化监督执纪问责，持续深化自然资源领域正风肃纪反腐。完善自然资源资产领域立法，严格执法、公正司法。提高科技支撑能力，加强自然资源资产相关学科和人才队伍建设。加强自然资源资产管理信息化建设，促进信息共享。提高绿色金融服务质效，引导金融机构按照市场化法治化原则加大对自然资源保护和利用等领域的金融支持。建立激励机制，鼓励各地区结合实际开展差别化改革探索。自然资源部要会同有关部门及时研究解决本意见实施过程中出现的新情况新问题。重大事项及时按程序向党中央、国务院请示报告。","level":1}]},{"id":"r0535","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于做好2021年元旦春节期间有关工作的通知》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于做好2021年元旦春节期间有关工作的通知》。全文如下：","level":1},{"name":"","text":"2021年是中国共产党成立100周年，是“十四五”规划开局之年，做好元旦春节期间各项工作十分重要。各地区各部门要以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，坚持以人民为中心，统筹做好新冠肺炎疫情防控和节日期间各项工作，确保全国各族人民度过欢乐祥和的节日。经党中央、国务院同意，现将有关事项通知如下。\n一、毫不松懈做好疫情防控工作。坚持常态化精准防控和局部应急处置有机结合，克服麻痹思想、松劲心态，毫不放松抓好“外防输入、内防反弹”工作，减少“两节”期间人员流动和聚集，严防死守，确保不出现规模性输入和反弹。坚持“人”、“物”同防，规范做好直接接触进口物品人员的个人防护、日常监测和定期核酸检测，对重点场所采取严格的环境监测和卫生措施，落实重点人群“应检尽检”。发挥发热门诊等“哨点”作用，强化“两节”期间医疗检验、院感控制、疫情处置等工作。加强健康教育，引导群众坚持科学佩戴口罩、保持社交距离、勤洗手等良好习惯。\n二、用心用情关爱困难群众。按时足额发放社保待遇，切实做好兜底保障工作，把党和政府的温暖送到困难群众心坎上。畅通社会救助渠道，确保困难群众特别是受疫情影响困难群众“求助有门、受助及时”。适时启动社会救助和保障标准与物价上涨挂钩联动机制，确保困难群众基本生活水平不因物价上涨而降低。组织开展对困难老年人、孤儿、留守妇女和儿童、生活无着流浪乞讨人员、残疾人、精神病人等特殊困难群体的走访慰问和关心关爱，确保他们有饭吃、有暖衣、有避寒场所。统筹做好救灾资金和物资调拨发放等工作，把受灾群众冷暖安危放在心上。以工程建设领域和劳动密集型加工制造及受疫情影响严重的行业为重点，扎实开展根治欠薪冬季专项行动，确保农民工按时足额拿到工资。\n三、着力满足群众节日消费需求。加强煤电油气运供需监测，做好能源保供稳价工作，保障人民群众温暖过冬。全面落实粮食安全省长责任制和“菜篮子”市长负责制，加强肉类、蔬菜等重要储备商品管理，确保粮油肉蛋菜果奶等重要商品市场供应和价格平稳运行。根据节日特点组织开展产销衔接，满足人民群众多样化消费需求。加强食品安全监管、产品质量监管、价格监管，维护消费者合法权益。在全国范围内广泛开展“我们的中国梦”——文化进万家活动，围绕庆祝中国共产党成立100周年、全面建成小康社会和开启全面建设社会主义现代化国家新征程，创作推出一批人民群众喜闻乐见的高质量文化文艺产品，唱响主旋律，传播正能量，更好满足群众精神文化需求。倡导健康向上的网上网下节日文化活动。加强文化和旅游市场执法，引导推进文明旅游。\n四、努力保障群众平安有序出行。抓紧抓实抓细常态化客运疫情防控工作，严格落实通风消毒、体温检测、客座率控制、乘客信息登记等措施。鼓励用人单位结合工作需要和职工意愿，统筹安排休假，引导错峰出行。增强运力供给，优化运力配置，满足旅客出行需求。做好多种运输方式接续接驳，畅通旅客出行“最先和最后一公里”。加强改进春运售票组织工作，增配自动检票机、安检仪，设置急客绿色通道，进一步提升进站安检效率。完善健康码、电子客票等使用，保障老年人等特殊群体在智能化条件下的出行服务。严格落实春节假期免收小型客车通行费政策，做好道路疏堵保畅工作，保障运输通道便捷高效通行。制定和完善应急预案，及时疏散滞留旅客。严管“两客一危一货一面”等重点车辆，严查“三超一疲劳”等严重违法行为，确保群众安全出行。\n五、坚持底线思维扎实抓好安全生产。树牢安全发展理念，把安全生产摆到重要位置，层层压实责任，切实维护人民群众生命财产安全。突出抓好高危行业领域风险管控，坚决治理高风险煤矿，深入排查危化品重大隐患，严格落实重大危险源安全包保责任制，严厉打击烟花爆竹违法生产、无证销售、超量储存、违规燃放等行为，坚决遏制重特大事故发生。深化建筑施工、工贸、民爆、城市燃气等安全整治，深入开展大型商业综合体、宾馆饭店、歌舞娱乐和城中村、门店房、“多合一”等高危场所火灾防控，加强旅游景区和客运索道、游乐设施等隐患排查，严格跨年夜、焰火晚会、游园庙会等大型活动安全审批和人流监控。加强对低温雨雪冰冻等极端灾害天气和森林火险的监测预警和应急处置。\n六、全力维护社会大局稳定。密切关注疫情防控常态化条件下影响社会稳定的突出问题，推动落实属地管理责任、源头稳控措施和多元化解机制，把各类不稳定因素和群体性事件苗头解决在萌芽、化解在基层。常态化开展扫黑除恶斗争，加强对偏远农村、城乡结合部、城中村等社会治安重点地区、重点部位以及各类社会治安突出问题的排查整治，深入打击暴力恐怖、涉枪涉爆、个人极端暴力、电信网络诈骗、侵犯公民个人信息、侵害未成年人和盗抢骗、黄赌毒、食药环等违法犯罪，维护社会良好秩序。加强社会面整体防控，落实公安武警联勤巡逻，强化重点目标、重要基础设施、人员密集场所的安全防范，加强枪支弹药、管制刀具等的安全监管，及时消除治安隐患。\n七、倡导勤俭节约文明过节新风尚。贯彻落实习近平总书记关于厉行节约、反对浪费特别是制止餐饮浪费行为的重要指示精神，抓住“两节”这一特殊时间节点，有针对性加强宣传教育，在全社会营造浪费可耻、节约光荣的氛围。坚决抵制大操大办、铺张浪费、高额彩礼、厚葬薄养、不文明祭扫等不良习俗，摒弃婚丧嫁娶陋习，倡导树立文明新风。引导餐饮消费者使用公勺公筷、实行聚餐分餐制、减少使用一次性餐具。自觉抵制餐饮浪费，引导消费者适量点餐，开展“光盘行动”，杜绝“舌尖上的浪费”。加强健康安全和生态保护宣传教育，严格执行长江禁捕和禁止野生动物及其制品交易有关要求，革除滥食野生动物的陋习。\n八、坚持不懈推进正风肃纪。坚持纠“四风”和树新风并举，营造风清气正的节日氛围。严格落实中央八项规定及其实施细则精神，严明廉洁过节各项纪律要求，坚决整治违反规定发放津贴、补贴、奖金和实物问题，着力纠正以反“四风”为名取消干部职工正常福利问题。紧盯节日期间违规收送礼品礼金、公款吃喝、大办婚丧喜庆等享乐奢靡突出问题，精准监督、靶向发力。对不吃公款吃老板、收受私企老板礼品礼金、私车公养等隐形变异问题露头就打、深挖细查。坚决纠正在巩固拓展脱贫攻坚成果、民生保障、帮扶救助、安全生产、政务服务、维护社会稳定、疫情防控、灾害监测预警和应急处置等方面不担当、不作为、乱作为、假作为等问题，着力整治群众身边腐败和不正之风。严肃查处随意向下派任务、要材料要报表、扎堆调研和随意要求干部“24小时在岗”等给基层造成严重负担的形式主义问题。严明换届纪律要求，加大对拉票贿选、跑官要官、说情打招呼等行为的监督查处力度。坚持严管厚爱结合、激励约束并重，持续推动激励干部担当作为的具体措施落细落实，加大对基层干部特别是战斗在脱贫攻坚一线同志的关心关爱力度，做好对“共和国勋章”、国家荣誉称号获得者和因公去世干部家属走访慰问、照顾救助和长期帮扶工作，加强党内激励关怀帮扶，使党员、干部等深切感受到以习近平同志为核心的党中央的关怀和温暖。\n九、认真负责做好应急值守工作。落实岗位责任制，严格执行24小时专人值班和领导干部在岗带班、外出报备制度，确保节日期间各项工作正常运转。遇有重要紧急情况特别是新冠肺炎疫情突发情况，要第一时间请示报告并及时采取应对处置措施。完善应急预案，强化应急演练，做好应急准备，确保第一时间响应、快速高效处置。直接服务群众的单位，要安排好节日期间值班执勤并保证服务质量。\n各地区各部门要增强“四个意识”，提高政治站位，加强组织领导，周密部署安排，确保本通知精神落到实处。","level":0}]},{"id":"r0536","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于加强新时代高技能人才队伍建设的意见》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于加强新时代高技能人才队伍建设的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于加强新时代高技能人才队伍建设的意见》全文如下。\n技能人才是支撑中国制造、中国创造的重要力量。加强高级工以上的高技能人才队伍建设，对巩固和发展工人阶级先进性，增强国家核心竞争力和科技创新能力，缓解就业结构性矛盾，推动高质量发展具有重要意义。为贯彻落实党中央、国务院决策部署，加强新时代高技能人才队伍建设，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，深入贯彻党的十九大和十九届历次全会精神，全面贯彻习近平总书记关于做好新时代人才工作的重要思想，坚持党管人才，立足新发展阶段，贯彻新发展理念，服务构建新发展格局，推动高质量发展，深入实施新时代人才强国战略，以服务发展、稳定就业为导向，大力弘扬劳模精神、劳动精神、工匠精神，全面实施“技能中国行动”，健全技能人才培养、使用、评价、激励制度，构建党委领导、政府主导、政策支持、企业主体、社会参与的高技能人才工作体系，打造一支爱党报国、敬业奉献、技艺精湛、素质优良、规模宏大、结构合理的高技能人才队伍。\n（二）目标任务。到“十四五”时期末，高技能人才制度政策更加健全、培养体系更加完善、岗位使用更加合理、评价机制更加科学、激励保障更加有力，尊重技能尊重劳动的社会氛围更加浓厚，技能人才规模不断壮大、素质稳步提升、结构持续优化、收入稳定增加，技能人才占就业人员的比例达到30%以上，高技能人才占技能人才的比例达到1/3，东部省份高技能人才占技能人才的比例达到35%。力争到2035年，技能人才规模持续壮大、素质大幅提高，高技能人才数量、结构与基本实现社会主义现代化的要求相适应。","level":1},{"name":"二、加大高技能人才培养力度","text":"（三）健全高技能人才培养体系。构建以行业企业为主体、职业学校（含技工院校，下同）为基础、政府推动与社会支持相结合的高技能人才培养体系。行业主管部门和行业组织要结合本行业生产、技术发展趋势，做好高技能人才供需预测和培养规划。鼓励各类企业结合实际把高技能人才培养纳入企业发展总体规划和年度计划，依托企业培训中心、产教融合实训基地、高技能人才培训基地、公共实训基地、技能大师工作室、劳模和工匠人才创新工作室、网络学习平台等，大力培养高技能人才。国有企业要结合实际将高技能人才培养规划的制定和实施情况纳入考核评价体系。鼓励各类企业事业组织、社会团体及其他社会组织以独资、合资、合作等方式依法参与举办职业教育培训机构，积极参与承接政府购买服务。对纳入产教融合型企业建设培育范围的企业兴办职业教育符合条件的投资，可依据有关规定按投资额的30%抵免当年应缴教育费附加和地方教育附加。\n（四）创新高技能人才培养模式。探索中国特色学徒制。深化产教融合、校企合作，开展订单式培养、套餐制培训，创新校企双制、校中厂、厂中校等方式。对联合培养高技能人才成效显著的企业，各级政府按规定予以表扬和相应政策支持。完善项目制培养模式，针对不同类别不同群体高技能人才实施差异化培养项目。鼓励通过名师带徒、技能研修、岗位练兵、技能竞赛、技术交流等形式，开放式培训高技能人才。建立技能人才继续教育制度，推广求学圆梦行动，定期组织开展研修交流活动，促进技能人才知识更新与技术创新、工艺改造、产业优化升级要求相适应。\n（五）加大急需紧缺高技能人才培养力度。围绕国家重大战略、重大工程、重大项目、重点产业对高技能人才的需求，实施高技能领军人才培育计划。支持制造业企业围绕转型升级和产业基础再造工程项目，实施制造业技能根基工程。围绕建设网络强国、数字中国，实施提升全民数字素养与技能行动，建立一批数字技能人才培养试验区，打造一批数字素养与技能提升培训基地，举办全民数字素养与技能提升活动，实施数字教育培训资源开放共享行动。围绕乡村振兴战略，实施乡村工匠培育计划，挖掘、保护和传承民间传统技艺，打造一批“工匠园区”。\n（六）发挥职业学校培养高技能人才的基础性作用。优化职业教育类型、院校布局和专业设置。采取中等职业学校和普通高中同批次并行招生等措施，稳定中等职业学校招生规模。在技工院校中普遍推行工学一体化技能人才培养模式。允许职业学校开展有偿性社会培训、技术服务或创办企业，所取得的收入可按一定比例作为办学经费自主安排使用；公办职业学校所取得的收入可按一定比例作为绩效工资来源，用于支付本校教师和其他培训教师的劳动报酬。合理保障职业学校师资受公派临时出国（境）参加培训访学、进修学习、技能交流等学术交流活动相关费用。切实保障职业学校学生在升学、就业、职业发展等方面与同层次普通学校学生享有平等机会。实施现代职业教育质量提升计划，支持职业学校改善办学条件。\n（七）优化高技能人才培养资源和服务供给。实施国家乡村振兴重点帮扶地区职业技能提升工程，加大东西部协作和对口帮扶力度。健全公共职业技能培训体系，实施职业技能培训共建共享行动，开展县域职业技能培训共建共享试点。加快探索“互联网+职业技能培训”，构建线上线下相结合的培训模式。依托“金保工程”，加快推进职业技能培训实名制管理工作，建立以社会保障卡为载体的劳动者终身职业技能培训电子档案。","level":1},{"name":"三、完善技能导向的使用制度","text":"（八）健全高技能人才岗位使用机制。企业可设立技能津贴、班组长津贴、带徒津贴等，支持鼓励高技能人才在岗位上发挥技能、管理班组、带徒传技。鼓励企业根据需要，建立高技能领军人才“揭榜领题”以及参与重大生产决策、重大技术革新和技术攻关项目的制度。实行“技师+工程师”等团队合作模式，在科研和技术攻关中发挥高技能人才创新能力。鼓励支持高技能人才兼任职业学校实习实训指导教师。注重青年高技能人才选用。高技能人才配置状况应作为生产经营性企业及其他实体参加重大工程项目招投标、评优和资质评估的重要因素。\n（九）完善技能要素参与分配制度。引导企业建立健全基于岗位价值、能力素质和业绩贡献的技能人才薪酬分配制度，实现多劳者多得、技高者多得，促进人力资源优化配置。国有企业在工资分配上要发挥向技能人才倾斜的示范作用。完善企业薪酬调查和信息发布制度，鼓励有条件的地区发布分职业（工种、岗位）、分技能等级的工资价位信息，为企业与技能人才协商确定工资水平提供信息参考。用人单位在聘的高技能人才在学习进修、岗位聘任、职务晋升、工资福利等方面，分别比照相应层级专业技术人员享受同等待遇。完善科技成果转化收益分享机制，对在技术革新或技术攻关中作出突出贡献的高技能人才给予奖励。高技能人才可实行年薪制、协议工资制，企业可对作出突出贡献的优秀高技能人才实行特岗特酬，鼓励符合条件的企业积极运用中长期激励工具，加大对高技能人才的激励力度。畅通为高技能人才建立企业年金的机制，鼓励和引导企业为包括高技能人才在内的职工建立企业年金。完善高技能特殊人才特殊待遇政策。\n（十）完善技能人才稳才留才引才机制。鼓励和引导企业关心关爱技能人才，依法保障技能人才合法权益，合理确定劳动报酬。健全人才服务体系，促进技能人才合理流动，提高技能人才配置效率。建立健全技能人才柔性流动机制，鼓励技能人才通过兼职、服务、技术攻关、项目合作等方式更好发挥作用。畅通高技能人才向专业技术岗位或管理岗位流动渠道。引导企业规范开展共享用工。支持各地结合产业发展需求实际，将急需紧缺技能人才纳入人才引进目录，引导技能人才向欠发达地区、基层一线流动。支持各地将高技能人才纳入城市直接落户范围，高技能人才的配偶、子女按有关规定享受公共就业、教育、住房等保障服务。","level":1},{"name":"四、建立技能人才职业技能等级制度和多元化评价机制","text":"（十一）拓宽技能人才职业发展通道。建立健全技能人才职业技能等级制度。对设有高级技师的职业（工种），可在其上增设特级技师和首席技师技术职务（岗位），在初级工之下补设学徒工，形成由学徒工、初级工、中级工、高级工、技师、高级技师、特级技师、首席技师构成的“八级工”职业技能等级（岗位）序列。鼓励符合条件的专业技术人员按有关规定申请参加相应职业（工种）的职业技能评价。支持各地面向符合条件的技能人才招聘事业单位工作人员，重视从技能人才中培养选拔党政干部。建立职业资格、职业技能等级与相应职称、学历的双向比照认定制度，推进学历教育学习成果、非学历教育学习成果、职业技能等级学分转换互认，建立国家资历框架。\n（十二）健全职业标准体系和评价制度。健全符合我国国情的现代职业分类体系，完善新职业信息发布制度。完善由国家职业标准、行业企业评价规范、专项职业能力考核规范等构成的多层次、相互衔接的职业标准体系。探索开展技能人员职业标准国际互通、证书国际互认工作，各地可建立境外技能人员职业资格认可清单制度。健全以职业资格评价、职业技能等级认定和专项职业能力考核等为主要内容的技能人才评价机制。完善以职业能力为导向、以工作业绩为重点，注重工匠精神培育和职业道德养成的技能人才评价体系，推动职业技能评价与终身职业技能培训制度相适应，与使用、待遇相衔接。深化职业资格制度改革，完善职业资格目录，实行动态调整。围绕新业态、新技术和劳务品牌、地方特色产业、非物质文化遗产传承项目等，加大专项职业能力考核项目开发力度。\n（十三）推行职业技能等级认定。支持符合条件的企业自主确定技能人才评价职业（工种）范围，自主设置岗位等级，自主开发制定岗位规范，自主运用评价方式开展技能人才职业技能等级评价；企业对新招录或未定级职工，可根据其日常表现、工作业绩，结合职业标准和企业岗位规范要求，直接认定相应的职业技能等级。打破学历、资历、年龄、比例等限制，对技能高超、业绩突出的一线职工，可直接认定高级工以上职业技能等级。对解决重大工艺技术难题和重大质量问题、技术创新成果获得省部级以上奖项、“师带徒”业绩突出的高技能人才，可破格晋升职业技能等级。推进“学历证书+若干职业技能证书”制度实施。强化技能人才评价规范管理，加大对社会培训评价组织的征集遴选力度，优化遴选条件，构建政府监管、机构自律、社会监督的质量监督体系，保障评价认定结果的科学性、公平性和权威性。\n（十四）完善职业技能竞赛体系。广泛深入开展职业技能竞赛，完善以世界技能大赛为引领、全国职业技能大赛为龙头、全国行业和地方各级职业技能竞赛以及专项赛为主体、企业和院校职业技能比赛为基础的中国特色职业技能竞赛体系。依托现有资源，加强世界技能大赛综合训练中心、研究（研修）中心、集训基地等平台建设，推动世界技能大赛成果转化。定期举办全国职业技能大赛，推动省、市、县开展综合性竞赛活动。鼓励行业开展特色竞赛活动，举办乡村振兴职业技能大赛。举办世界职业院校技能大赛、全国职业院校技能大赛等职业学校技能竞赛。健全竞赛管理制度，推行“赛展演会”结合的办赛模式，建立政府、企业和社会多方参与的竞赛投入保障机制，加强竞赛专兼职队伍建设，提高竞赛科学化、规范化、专业化水平。完善并落实竞赛获奖选手表彰奖励、升学、职业技能等级晋升等政策。鼓励企业对竞赛获奖选手建立与岗位使用及薪酬待遇挂钩的长效激励机制。","level":1},{"name":"五、建立高技能人才表彰激励机制","text":"（十五）加大高技能人才表彰奖励力度。建立以国家表彰为引领、行业企业奖励为主体、社会奖励为补充的高技能人才表彰奖励体系。完善评选表彰中华技能大奖获得者和全国技术能手制度。国家级荣誉适当向高技能人才倾斜。加大高技能人才在全国劳动模范和先进工作者、国家科学技术奖等相关表彰中的评选力度，积极推荐高技能人才享受政府特殊津贴，对符合条件的高技能人才按规定授予五一劳动奖章、青年五四奖章、青年岗位能手、三八红旗手、巾帼建功标兵等荣誉，提高全社会对技能人才的认可认同。\n（十六）健全高技能人才激励机制。加强对技能人才的政治引领和政治吸纳，注重做好党委（党组）联系服务高技能人才工作。将高技能人才纳入各地人才分类目录。注重依法依章程推荐高技能人才为人民代表大会代表候选人、政治协商会议委员人选、群团组织代表大会代表或委员会委员候选人。进一步提高高技能人才在职工代表大会中的比例，支持高技能人才参与企业管理。按照有关规定，选拔推荐优秀高技能人才到工会、共青团、妇联等群团组织挂职或兼职。建立高技能人才休假疗养制度，鼓励支持分级开展高技能人才休假疗养、研修交流和节日慰问等活动。","level":1},{"name":"六、保障措施","text":"（十七）强化组织领导。坚持党对高技能人才队伍建设的全面领导，确保正确政治方向。各级党委和政府要将高技能人才工作纳入本地区经济社会发展、人才队伍建设总体部署和考核范围。在本级人才工作领导小组统筹协调下，建立组织部门牵头抓总、人力资源社会保障部门组织实施、有关部门各司其职、行业企业和社会各方广泛参与的高技能人才工作机制。各地区各部门要大力宣传技能人才在经济社会发展中的作用和贡献，进一步营造重视、关心、尊重高技能人才的社会氛围，形成劳动光荣、技能宝贵、创造伟大的时代风尚。\n（十八）加强政策支持。各级政府要统筹利用现有资金渠道，按规定支持高技能人才工作。企业要按规定足额提取和使用职工教育经费，60%以上用于一线职工教育和培训。落实企业职工教育经费税前扣除政策，有条件的地方可探索建立省级统一的企业职工教育经费使用管理制度。各地要按规定发挥好有关教育经费等各类资金作用，支持职业教育发展。\n（十九）加强技能人才基础工作。充分利用大数据、云计算等新一代信息技术，加强技能人才工作信息化建设。建立健全高技能人才库。加强高技能人才理论研究和成果转化。大力推进符合高技能人才培养需求的精品课程、教材和师资建设，开发高技能人才培养标准和一体化课程。加强国际交流合作，推动实施技能领域“走出去”、“引进来”合作项目，支持青年学生、毕业生参与青年国际实习交流计划，推进与各国在技能领域的交流互鉴。","level":1}]},{"id":"r0537","sections":[{"name":"关于加强国家工作人员因私事出国（境）管理的暂行规定","text":"为适应改革开放和我国加入世贸组织后形势发展的需要，保障公民出国（境）权利，公安机关将进一步简化公民因私事出国（境）申请手续，2005年以前在全国大、中城市实现公民按需申领护照。即除保留部分国家工作人员仍按照组织、人事管理权限和行政隶属关系出具单位意见外，其他公民只要不具有法律、法规规定的不准出境的情形，凭本人居民身份证、户口簿即可按需要向公安机关申领出入境证件。\n为加强国家工作人员因私事出国（境）的管理，落实中央关于加强党政领导干部出国（境）管理的规定，维护党纪政纪，维护国家安全和利益，我们制定了《关于加强国家工作人员因私事出国（境）管理的暂行规定》，请遵照执行。各组织、人事部门和公安机关要相互配合，切实加强对国家工作人员因私事出国（境）的管理工作。各事业单位和企业单位人事部门要参照本规定，加强对有关国家工作人员因私事出国（境）的管理工作。因工作相互推诿扯皮，管理不力，出现漏洞的，要视情节追究有关人员的责任。\n关于加强国家工作人员因私事出国（境）管理的暂行规定","level":1},{"name":"","text":"第一条 为加强对国家工作人员因私事出国（境）管理，适应改革开放和经济发展的需要，制定本规定。\n第二条 国家工作人员因私事出国（境），应按照组织、人事管理权限履行审批手续。\n第三条 本规定所称国家工作人员，是指国家公务员以及参照、依照公务员管理的国家工作人员。\n国有公司、企业中从事公务的人员和国家机关、国有公司、企业、事业单位委派到非国有企业单位、社会团体从事公务的人员，以国家工作人员论。\n第四条 下列国家工作人员（以下称“登记备案人员”）申请因私事出国（境），须向户口所在地的公安机关出入境管理部门提交所在工作单位对申请人出国（境）的意见。\n（一）各级党政机关、人大、政协、人民法院、人民检察院、人民团体、事业单位在职的县（处）级以上领导干部，离（退）休的厅（局）级以上干部；\n（二）金融机构、国有企业的法人代表，县级以上金融机构领导成员及其相应职级的领导干部，国有大中型企业中层以上管理人员，国有控股、参股企业中的国有股权代表；\n（三）各部门、行业中涉及国家安全及国有资产安全、行业机密的人员。\n第五条 登记备案人员的基本情况由其所在工作单位负责向公安机关登记备案。登记备案的内容包括：姓名、性别、出生日期、身份证号码、户口所在地、工作单位、现任职务、主管部门等。登记备案人员工作单位、现任职务、主管部门等发生变化的，有关单位应当及时变更相应登记备案的内容。\n第六条 公安机关负责本地区国家工作人员登记备案工作的业务指导和数据管理。\n第七条 公安机关出入境管理部门受理公民因私事出国（境）申请时，应当核实有关单位登记备案的情况，确定是否颁发出入境证件。已登记备案的国家工作人员，如未提交所在工作单位对申请人因私事出国（境）的意见，公安机关出入境管理部门不予受理或办理。\n第八条 各级组织、人事部门和公安机关在因私事出国（境）管理工作中，应建立有效的联系机制，制定责任制度和保密制度，指定专人负责。\n第九条 各级组织、人事部门应对本单位已申领出入境证件的国家工作人员严格执行有关管理规定，实行因私事出国（境）报告登记制度，要求出国（境）人员在境外遵守外事纪律，未经批准不得逾期滞留。登记备案人员已申领的出入境证件，由所在单位组织、人事部门集中保管。\n第十条 各级组织、人事部门因未按规定办理审批手续或登记备案手续的，公安机关违反规定办理出入境证件造成国家利益损失的，应视情节追究直接责任人和主管领导的责任，按照有关规定给予行政处分或者依法予以处罚。\n第十一条 各地区、各部门可根据实际情况，制定具体实施办法，按照隶属关系，分别报送中央组织部、中央金融工委、中央企业工委、公安部、人事部备案。\n第十二条 本规定由中央组织部、中央金融工委、中央企业工委、公安部、人事部负责解释。\n第十三条 本规定自印发之日起执行。","level":0}]},{"id":"r0538","sections":[{"name":"中共中央 国务院关于做好2023年全面推进乡村振兴重点工作的意见","text":"中共中央 国务院关于做好2023年全面推进乡村振兴重点工作的意见","level":1},{"name":"","text":"党的二十大擘画了以中国式现代化全面推进中华民族伟大复兴的宏伟蓝图。全面建设社会主义现代化国家，最艰巨最繁重的任务仍然在农村。世界百年未有之大变局加速演进，我国发展进入战略机遇和风险挑战并存、不确定难预料因素增多的时期，守好“三农”基本盘至关重要、不容有失。党中央认为，必须坚持不懈把解决好“三农”问题作为全党工作重中之重，举全党全社会之力全面推进乡村振兴，加快农业农村现代化。强国必先强农，农强方能国强。要立足国情农情，体现中国特色，建设供给保障强、科技装备强、经营体系强、产业韧性强、竞争能力强的农业强国。\n做好2023年和今后一个时期“三农”工作，要坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的二十大精神，深入贯彻落实习近平总书记关于“三农”工作的重要论述，坚持和加强党对“三农”工作的全面领导，坚持农业农村优先发展，坚持城乡融合发展，强化科技创新和制度创新，坚决守牢确保粮食安全、防止规模性返贫等底线，扎实推进乡村发展、乡村建设、乡村治理等重点工作，加快建设农业强国，建设宜居宜业和美乡村，为全面建设社会主义现代化国家开好局起好步打下坚实基础。","level":0},{"name":"一、抓紧抓好粮食和重要农产品稳产保供","text":"（一）全力抓好粮食生产。确保全国粮食产量保持在1.3万亿斤以上，各省（自治区、直辖市）都要稳住面积、主攻单产、力争多增产。全方位夯实粮食安全根基，强化藏粮于地、藏粮于技的物质基础，健全农民种粮挣钱得利、地方抓粮担责尽义的机制保障。实施新一轮千亿斤粮食产能提升行动。开展吨粮田创建。推动南方省份发展多熟制粮食生产，鼓励有条件的地方发展再生稻。支持开展小麦“一喷三防”。实施玉米单产提升工程。继续提高小麦最低收购价，合理确定稻谷最低收购价，稳定稻谷补贴，完善农资保供稳价应对机制。健全主产区利益补偿机制，增加产粮大县奖励资金规模。逐步扩大稻谷小麦玉米完全成本保险和种植收入保险实施范围。实施好优质粮食工程。鼓励发展粮食订单生产，实现优质优价。严防“割青毁粮”。严格省级党委和政府耕地保护和粮食安全责任制考核。推动出台粮食安全保障法。\n（二）加力扩种大豆油料。深入推进大豆和油料产能提升工程。扎实推进大豆玉米带状复合种植，支持东北、黄淮海地区开展粮豆轮作，稳步开发利用盐碱地种植大豆。完善玉米大豆生产者补贴，实施好大豆完全成本保险和种植收入保险试点。统筹油菜综合性扶持措施，推行稻油轮作，大力开发利用冬闲田种植油菜。支持木本油料发展，实施加快油茶产业发展三年行动，落实油茶扩种和低产低效林改造任务。深入实施饲用豆粕减量替代行动。\n（三）发展现代设施农业。实施设施农业现代化提升行动。加快发展水稻集中育秧中心和蔬菜集约化育苗中心。加快粮食烘干、农产品产地冷藏、冷链物流设施建设。集中连片推进老旧蔬菜设施改造提升。推进畜禽规模化养殖场和水产养殖池塘改造升级。在保护生态和不增加用水总量前提下，探索科学利用戈壁、沙漠等发展设施农业。鼓励地方对设施农业建设给予信贷贴息。\n（四）构建多元化食物供给体系。树立大食物观，加快构建粮经饲统筹、农林牧渔结合、植物动物微生物并举的多元化食物供给体系，分领域制定实施方案。建设优质节水高产稳产饲草料生产基地，加快苜蓿等草产业发展。大力发展青贮饲料，加快推进秸秆养畜。发展林下种养。深入推进草原畜牧业转型升级，合理利用草地资源，推进划区轮牧。科学划定限养区，发展大水面生态渔业。建设现代海洋牧场，发展深水网箱、养殖工船等深远海养殖。培育壮大食用菌和藻类产业。加大食品安全、农产品质量安全监管力度，健全追溯管理制度。\n（五）统筹做好粮食和重要农产品调控。加强粮食应急保障能力建设。强化储备和购销领域监管。落实生猪稳产保供省负总责，强化以能繁母猪为主的生猪产能调控。严格“菜篮子”市长负责制考核。完善棉花目标价格政策。继续实施糖料蔗良种良法技术推广补助政策。完善天然橡胶扶持政策。加强化肥等农资生产、储运调控。发挥农产品国际贸易作用，深入实施农产品进口多元化战略。深入开展粮食节约行动，推进全链条节约减损，健全常态化、长效化工作机制。提倡健康饮食。","level":1},{"name":"二、加强农业基础设施建设","text":"（六）加强耕地保护和用途管控。严格耕地占补平衡管理，实行部门联合开展补充耕地验收评定和“市县审核、省级复核、社会监督”机制，确保补充的耕地数量相等、质量相当、产能不降。严格控制耕地转为其他农用地。探索建立耕地种植用途管控机制，明确利用优先序，加强动态监测，有序开展试点。加大撂荒耕地利用力度。做好第三次全国土壤普查工作。\n（七）加强高标准农田建设。完成高标准农田新建和改造提升年度任务，重点补上土壤改良、农田灌排设施等短板，统筹推进高效节水灌溉，健全长效管护机制。制定逐步把永久基本农田全部建成高标准农田的实施方案。加强黑土地保护和坡耕地综合治理。严厉打击盗挖黑土、电捕蚯蚓等破坏土壤行为。强化干旱半干旱耕地、红黄壤耕地产能提升技术攻关，持续推动由主要治理盐碱地适应作物向更多选育耐盐碱植物适应盐碱地转变，做好盐碱地等耕地后备资源综合开发利用试点。\n（八）加强水利基础设施建设。扎实推进重大水利工程建设，加快构建国家水网骨干网络。加快大中型灌区建设和现代化改造。实施一批中小型水库及引调水、抗旱备用水源等工程建设。加强田间地头渠系与灌区骨干工程连接等农田水利设施建设。支持重点区域开展地下水超采综合治理，推进黄河流域农业深度节水控水。在干旱半干旱地区发展高效节水旱作农业。强化蓄滞洪区建设管理、中小河流治理、山洪灾害防治，加快实施中小水库除险加固和小型水库安全监测。深入推进农业水价综合改革。\n（九）强化农业防灾减灾能力建设。研究开展新一轮农业气候资源普查和农业气候区划工作。优化完善农业气象观测设施站网布局，分区域、分灾种发布农业气象灾害信息。加强旱涝灾害防御体系建设和农业生产防灾救灾保障。健全基层动植物疫病虫害监测预警网络。抓好非洲猪瘟等重大动物疫病常态化防控和重点人兽共患病源头防控。提升重点区域森林草原火灾综合防控水平。","level":1},{"name":"三、强化农业科技和装备支撑","text":"（十）推动农业关键核心技术攻关。坚持产业需求导向，构建梯次分明、分工协作、适度竞争的农业科技创新体系，加快前沿技术突破。支持农业领域国家实验室、全国重点实验室、制造业创新中心等平台建设，加强农业基础性长期性观测实验站（点）建设。完善农业科技领域基础研究稳定支持机制。\n（十一）深入实施种业振兴行动。完成全国农业种质资源普查。构建开放协作、共享应用的种质资源精准鉴定评价机制。全面实施生物育种重大项目，扎实推进国家育种联合攻关和畜禽遗传改良计划，加快培育高产高油大豆、短生育期油菜、耐盐碱作物等新品种。加快玉米大豆生物育种产业化步伐，有序扩大试点范围，规范种植管理。\n（十二）加快先进农机研发推广。加紧研发大型智能农机装备、丘陵山区适用小型机械和园艺机械。支持北斗智能监测终端及辅助驾驶系统集成应用。完善农机购置与应用补贴政策，探索与作业量挂钩的补贴办法，地方要履行法定支出责任。\n（十三）推进农业绿色发展。加快农业投入品减量增效技术推广应用，推进水肥一体化，建立健全秸秆、农膜、农药包装废弃物、畜禽粪污等农业废弃物收集利用处理体系。推进农业绿色发展先行区和观测试验基地建设。健全耕地休耕轮作制度。加强农用地土壤镉等重金属污染源头防治。强化受污染耕地安全利用和风险管控。建立农业生态环境保护监测制度。出台生态保护补偿条例。严格执行休禁渔期制度，实施好长江十年禁渔，巩固退捕渔民安置保障成果。持续开展母亲河复苏行动，科学实施农村河湖综合整治。加强黄土高原淤地坝建设改造。加大草原保护修复力度。巩固退耕还林还草成果，落实相关补助政策。严厉打击非法引入外来物种行为，实施重大危害入侵物种防控攻坚行动，加强“异宠”交易与放生规范管理。","level":1},{"name":"四、巩固拓展脱贫攻坚成果","text":"（十四）坚决守住不发生规模性返贫底线。压紧压实各级巩固拓展脱贫攻坚成果责任，确保不松劲、不跑偏。强化防止返贫动态监测。对有劳动能力、有意愿的监测户，落实开发式帮扶措施。健全分层分类的社会救助体系，做好兜底保障。巩固提升“三保障”和饮水安全保障成果。\n（十五）增强脱贫地区和脱贫群众内生发展动力。把增加脱贫群众收入作为根本要求，把促进脱贫县加快发展作为主攻方向，更加注重扶志扶智，聚焦产业就业，不断缩小收入差距、发展差距。中央财政衔接推进乡村振兴补助资金用于产业发展的比重力争提高到60%以上，重点支持补上技术、设施、营销等短板。鼓励脱贫地区有条件的农户发展庭院经济。深入开展多种形式的消费帮扶，持续推进消费帮扶示范城市和产地示范区创建，支持脱贫地区打造区域公用品牌。财政资金和帮扶资金支持的经营性帮扶项目要健全利益联结机制，带动农民增收。管好用好扶贫项目资产。深化东西部劳务协作，实施防止返贫就业攻坚行动，确保脱贫劳动力就业规模稳定在3000万人以上。持续运营好就业帮扶车间和其他产业帮扶项目。充分发挥乡村公益性岗位就业保障作用。深入开展“雨露计划+”就业促进行动。在国家乡村振兴重点帮扶县实施一批补短板促振兴重点项目，深入实施医疗、教育干部人才“组团式”帮扶，更好发挥驻村干部、科技特派员产业帮扶作用。深入开展巩固易地搬迁脱贫成果专项行动和搬迁群众就业帮扶专项行动。\n（十六）稳定完善帮扶政策。落实巩固拓展脱贫攻坚成果同乡村振兴有效衔接政策。开展国家乡村振兴重点帮扶县发展成效监测评价。保持脱贫地区信贷投放力度不减，扎实做好脱贫人口小额信贷工作。按照市场化原则加大对帮扶项目的金融支持。深化东西部协作，组织东部地区经济较发达县（市、区）与脱贫县开展携手促振兴行动，带动脱贫县更多承接和发展劳动密集型产业。持续做好中央单位定点帮扶，调整完善结对关系。深入推进“万企兴万村”行动。研究过渡期后农村低收入人口和欠发达地区常态化帮扶机制。","level":1},{"name":"五、推动乡村产业高质量发展","text":"（十七）做大做强农产品加工流通业。实施农产品加工业提升行动，支持家庭农场、农民合作社和中小微企业等发展农产品产地初加工，引导大型农业企业发展农产品精深加工。引导农产品加工企业向产地下沉、向园区集中，在粮食和重要农产品主产区统筹布局建设农产品加工产业园。完善农产品流通骨干网络，改造提升产地、集散地、销地批发市场，布局建设一批城郊大仓基地。支持建设产地冷链集配中心。统筹疫情防控和农产品市场供应，确保农产品物流畅通。\n（十八）加快发展现代乡村服务业。全面推进县域商业体系建设。加快完善县乡村电子商务和快递物流配送体系，建设县域集采集配中心，推动农村客货邮融合发展，大力发展共同配送、即时零售等新模式，推动冷链物流服务网络向乡村下沉。发展乡村餐饮购物、文化体育、旅游休闲、养老托幼、信息中介等生活服务。鼓励有条件的地区开展新能源汽车和绿色智能家电下乡。\n（十九）培育乡村新产业新业态。继续支持创建农业产业强镇、现代农业产业园、优势特色产业集群。支持国家农村产业融合发展示范园建设。深入推进农业现代化示范区建设。实施文化产业赋能乡村振兴计划。实施乡村休闲旅游精品工程，推动乡村民宿提质升级。深入实施“数商兴农”和“互联网+”农产品出村进城工程，鼓励发展农产品电商直采、定制生产等模式，建设农副产品直播电商基地。提升净菜、中央厨房等产业标准化和规范化水平。培育发展预制菜产业。\n（二十）培育壮大县域富民产业。完善县乡村产业空间布局，提升县城产业承载和配套服务功能，增强重点镇集聚功能。实施“一县一业”强县富民工程。引导劳动密集型产业向中西部地区、向县域梯度转移，支持大中城市在周边县域布局关联产业和配套企业。支持国家级高新区、经开区、农高区托管联办县域产业园区。","level":1},{"name":"六、拓宽农民增收致富渠道","text":"（二十一）促进农民就业增收。强化各项稳岗纾困政策落实，加大对中小微企业稳岗倾斜力度，稳定农民工就业。促进农民工职业技能提升。完善农民工工资支付监测预警机制。维护好超龄农民工就业权益。加快完善灵活就业人员权益保障制度。加强返乡入乡创业园、农村创业孵化实训基地等建设。在政府投资重点工程和农业农村基础设施建设项目中推广以工代赈，适当提高劳务报酬发放比例。\n（二十二）促进农业经营增效。深入开展新型农业经营主体提升行动，支持家庭农场组建农民合作社、合作社根据发展需要办企业，带动小农户合作经营、共同增收。实施农业社会化服务促进行动，大力发展代耕代种、代管代收、全程托管等社会化服务，鼓励区域性综合服务平台建设，促进农业节本增效、提质增效、营销增效。引导土地经营权有序流转，发展农业适度规模经营。总结地方“小田并大田”等经验，探索在农民自愿前提下，结合农田建设、土地整治逐步解决细碎化问题。完善社会资本投资农业农村指引，加强资本下乡引入、使用、退出的全过程监管。健全社会资本通过流转取得土地经营权的资格审查、项目审核和风险防范制度，切实保障农民利益。坚持为农服务和政事分开、社企分开，持续深化供销合作社综合改革。\n（二十三）赋予农民更加充分的财产权益。深化农村土地制度改革，扎实搞好确权，稳步推进赋权，有序实现活权，让农民更多分享改革红利。研究制定第二轮土地承包到期后再延长30年试点工作指导意见。稳慎推进农村宅基地制度改革试点，切实摸清底数，加快房地一体宅基地确权登记颁证，加强规范管理，妥善化解历史遗留问题，探索宅基地“三权分置”有效实现形式。深化农村集体经营性建设用地入市试点，探索建立兼顾国家、农村集体经济组织和农民利益的土地增值收益有效调节机制。保障进城落户农民合法土地权益，鼓励依法自愿有偿转让。巩固提升农村集体产权制度改革成果，构建产权关系明晰、治理架构科学、经营方式稳健、收益分配合理的运行机制，探索资源发包、物业出租、居间服务、资产参股等多样化途径发展新型农村集体经济。健全农村集体资产监管体系。保障妇女在农村集体经济组织中的合法权益。继续深化集体林权制度改革。深入推进农村综合改革试点示范。","level":1},{"name":"七、扎实推进宜居宜业和美乡村建设","text":"（二十四）加强村庄规划建设。坚持县域统筹，支持有条件有需求的村庄分区分类编制村庄规划，合理确定村庄布局和建设边界。将村庄规划纳入村级议事协商目录。规范优化乡村地区行政区划设置，严禁违背农民意愿撤并村庄、搞大社区。推进以乡镇为单元的全域土地综合整治。积极盘活存量集体建设用地，优先保障农民居住、乡村基础设施、公共服务空间和产业用地需求，出台乡村振兴用地政策指南。编制村容村貌提升导则，立足乡土特征、地域特点和民族特色提升村庄风貌，防止大拆大建、盲目建牌楼亭廊“堆盆景”。实施传统村落集中连片保护利用示范，建立完善传统村落调查认定、撤并前置审查、灾毁防范等制度。制定农村基本具备现代生活条件建设指引。\n（二十五）扎实推进农村人居环境整治提升。加大村庄公共空间整治力度，持续开展村庄清洁行动。巩固农村户厕问题摸排整改成果，引导农民开展户内改厕。加强农村公厕建设维护。以人口集中村镇和水源保护区周边村庄为重点，分类梯次推进农村生活污水治理。推动农村生活垃圾源头分类减量，及时清运处置。推进厕所粪污、易腐烂垃圾、有机废弃物就近就地资源化利用。持续开展爱国卫生运动。\n（二十六）持续加强乡村基础设施建设。加强农村公路养护和安全管理，推动与沿线配套设施、产业园区、旅游景区、乡村旅游重点村一体化建设。推进农村规模化供水工程建设和小型供水工程标准化改造，开展水质提升专项行动。推进农村电网巩固提升，发展农村可再生能源。支持农村危房改造和抗震改造，基本完成农房安全隐患排查整治，建立全过程监管制度。开展现代宜居农房建设示范。深入实施数字乡村发展行动，推动数字化应用场景研发推广。加快农业农村大数据应用，推进智慧农业发展。落实村庄公共基础设施管护责任。加强农村应急管理基础能力建设，深入开展乡村交通、消防、经营性自建房等重点领域风险隐患治理攻坚。\n（二十七）提升基本公共服务能力。推动基本公共服务资源下沉，着力加强薄弱环节。推进县域内义务教育优质均衡发展，提升农村学校办学水平。落实乡村教师生活补助政策。推进医疗卫生资源县域统筹，加强乡村两级医疗卫生、医疗保障服务能力建设。统筹解决乡村医生薪酬分配和待遇保障问题，推进乡村医生队伍专业化规范化。提高农村传染病防控和应急处置能力。做好农村新冠疫情防控工作，层层压实责任，加强农村老幼病残孕等重点人群医疗保障，最大程度维护好农村居民身体健康和正常生产生活秩序。优化低保审核确认流程，确保符合条件的困难群众“应保尽保”。深化农村社会工作服务。加快乡镇区域养老服务中心建设，推广日间照料、互助养老、探访关爱、老年食堂等养老服务。实施农村妇女素质提升计划，加强农村未成年人保护工作，健全农村残疾人社会保障制度和关爱服务体系，关心关爱精神障碍人员。","level":1},{"name":"八、健全党组织领导的乡村治理体系","text":"（二十八）强化农村基层党组织政治功能和组织功能。突出大抓基层的鲜明导向，强化县级党委抓乡促村责任，深入推进抓党建促乡村振兴。全面培训提高乡镇、村班子领导乡村振兴能力。派强用好驻村第一书记和工作队，强化派出单位联村帮扶。开展乡村振兴领域腐败和作风问题整治。持续开展市县巡察，推动基层纪检监察组织和村务监督委员会有效衔接，强化对村干部全方位管理和经常性监督。对农村党员分期分批开展集中培训。通过设岗定责等方式，发挥农村党员先锋模范作用。\n（二十九）提升乡村治理效能。坚持以党建引领乡村治理，强化县乡村三级治理体系功能，压实县级责任，推动乡镇扩权赋能，夯实村级基础。全面落实县级领导班子成员包乡走村、乡镇领导班子成员包村联户、村干部经常入户走访制度。健全党组织领导的村民自治机制，全面落实“四议两公开”制度。加强乡村法治教育和法律服务，深入开展“民主法治示范村（社区）”创建。坚持和发展新时代“枫桥经验”，完善社会矛盾纠纷多元预防调处化解机制。完善网格化管理、精细化服务、信息化支撑的基层治理平台。推进农村扫黑除恶常态化。开展打击整治农村赌博违法犯罪专项行动。依法严厉打击侵害农村妇女儿童权利的违法犯罪行为。完善推广积分制、清单制、数字化、接诉即办等务实管用的治理方式。深化乡村治理体系建设试点，组织开展全国乡村治理示范村镇创建。\n（三十）加强农村精神文明建设。深入开展社会主义核心价值观宣传教育，继续在乡村开展听党话、感党恩、跟党走宣传教育活动。深化农村群众性精神文明创建，拓展新时代文明实践中心、县级融媒体中心等建设，支持乡村自办群众性文化活动。注重家庭家教家风建设。深入实施农耕文化传承保护工程，加强重要农业文化遗产保护利用。办好中国农民丰收节。推动各地因地制宜制定移风易俗规范，强化村规民约约束作用，党员、干部带头示范，扎实开展高价彩礼、大操大办等重点领域突出问题专项治理。推进农村丧葬习俗改革。","level":1},{"name":"九、强化政策保障和体制机制创新","text":"（三十一）健全乡村振兴多元投入机制。坚持把农业农村作为一般公共预算优先保障领域，压实地方政府投入责任。稳步提高土地出让收益用于农业农村比例。将符合条件的乡村振兴项目纳入地方政府债券支持范围。支持以市场化方式设立乡村振兴基金。健全政府投资与金融、社会投入联动机制，鼓励将符合条件的项目打捆打包按规定由市场主体实施，撬动金融和社会资本按市场化原则更多投向农业农村。用好再贷款再贴现、差别化存款准备金、差异化金融监管和考核评估等政策，推动金融机构增加乡村振兴相关领域贷款投放，重点保障粮食安全信贷资金需求。引导信贷担保业务向农业农村领域倾斜，发挥全国农业信贷担保体系作用。加强农业信用信息共享。发挥多层次资本市场支农作用，优化“保险+期货”。加快农村信用社改革化险，推动村镇银行结构性重组。鼓励发展渔业保险。\n（三十二）加强乡村人才队伍建设。实施乡村振兴人才支持计划，组织引导教育、卫生、科技、文化、社会工作、精神文明建设等领域人才到基层一线服务，支持培养本土急需紧缺人才。实施高素质农民培育计划，开展农村创业带头人培育行动，提高培训实效。大力发展面向乡村振兴的职业教育，深化产教融合和校企合作。完善城市专业技术人才定期服务乡村激励机制，对长期服务乡村的在职务晋升、职称评定方面予以适当倾斜。引导城市专业技术人员入乡兼职兼薪和离岗创业。允许符合一定条件的返乡回乡下乡就业创业人员在原籍地或就业创业地落户。继续实施农村订单定向医学生免费培养项目、教师“优师计划”、“特岗计划”、“国培计划”，实施“大学生乡村医生”专项计划。实施乡村振兴巾帼行动、青年人才开发行动。\n（三十三）推进县域城乡融合发展。健全城乡融合发展体制机制和政策体系，畅通城乡要素流动。统筹县域城乡规划建设，推动县城城镇化补短板强弱项，加强中心镇市政、服务设施建设。深入推进县域农民工市民化，建立健全基本公共服务同常住人口挂钩、由常住地供给机制。做好农民工金融服务工作。梯度配置县乡村公共资源，发展城乡学校共同体、紧密型医疗卫生共同体、养老服务联合体，推动县域供电、供气、电信、邮政等普遍服务类设施城乡统筹建设和管护，有条件的地区推动市政管网、乡村微管网等往户延伸。扎实开展乡村振兴示范创建。\n办好农村的事，实现乡村振兴，关键在党。各级党委和政府要认真学习宣传贯彻党的二十大精神，学深悟透习近平总书记关于“三农”工作的重要论述，把“三农”工作摆在突出位置抓紧抓好，不断提高“三农”工作水平。加强工作作风建设，党员干部特别是领导干部要树牢群众观点，贯彻群众路线，多到基层、多接地气，大兴调查研究之风。发挥农民主体作用，调动农民参与乡村振兴的积极性、主动性、创造性。强化系统观念，统筹解决好“三农”工作中两难、多难问题，把握好工作时度效。深化纠治乡村振兴中的各类形式主义、官僚主义等问题，切实减轻基层迎评送检、填表报数、过度留痕等负担，推动基层把主要精力放在谋发展、抓治理和为农民群众办实事上。全面落实乡村振兴责任制，坚持五级书记抓，统筹开展乡村振兴战略实绩考核、巩固拓展脱贫攻坚成果同乡村振兴有效衔接考核评估，将抓党建促乡村振兴情况作为市县乡党委书记抓基层党建述职评议考核的重要内容。加强乡村振兴统计监测。制定加快建设农业强国规划，做好整体谋划和系统安排，同现有规划相衔接，分阶段扎实稳步推进。\n让我们紧密团结在以习近平同志为核心的党中央周围，坚定信心、踔厉奋发、埋头苦干，全面推进乡村振兴，加快建设农业强国，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴作出新的贡献。\n延伸阅读\n2023年中央一号文件说了什么？要点速览来了\n从关键词看新任务 这份文件惠农利农“干货”多\n2023年中央一号文件聚焦守底线、促振兴、强保障 全面推进乡村振兴有了“操作手册”\n解读中央一号文件 | 强国必先强农 农强方能国强","level":1}]},{"id":"r0539","sections":[{"name":"关于构建现代环境治理体系的指导意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于构建现代环境治理体系的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于构建现代环境治理体系的指导意见》全文如下。\n为贯彻落实党的十九大部署，构建党委领导、政府主导、企业主体、社会组织和公众共同参与的现代环境治理体系，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中全会精神，深入贯彻习近平生态文明思想，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，认真落实党中央、国务院决策部署，牢固树立绿色发展理念，以坚持党的集中统一领导为统领，以强化政府主导作用为关键，以深化企业主体作用为根本，以更好动员社会组织和公众共同参与为支撑，实现政府治理和社会调节、企业自治良性互动，完善体制机制，强化源头治理，形成工作合力，为推动生态环境根本好转、建设生态文明和美丽中国提供有力制度保障。\n（二）基本原则\n——坚持党的领导。贯彻党中央关于生态环境保护的总体要求，实行生态环境保护党政同责、一岗双责。\n——坚持多方共治。明晰政府、企业、公众等各类主体权责，畅通参与渠道，形成全社会共同推进环境治理的良好格局。\n——坚持市场导向。完善经济政策，健全市场机制，规范环境治理市场行为，强化环境治理诚信建设，促进行业自律。\n——坚持依法治理。健全法律法规标准，严格执法、加强监管，加快补齐环境治理体制机制短板。\n（三）主要目标。到2025年，建立健全环境治理的领导责任体系、企业责任体系、全民行动体系、监管体系、市场体系、信用体系、法律法规政策体系，落实各类主体责任，提高市场主体和公众参与的积极性，形成导向清晰、决策科学、执行有力、激励有效、多元参与、良性互动的环境治理体系。","level":1},{"name":"二、健全环境治理领导责任体系","text":"（四）完善中央统筹、省负总责、市县抓落实的工作机制。党中央、国务院统筹制定生态环境保护的大政方针，提出总体目标，谋划重大战略举措。制定实施中央和国家机关有关部门生态环境保护责任清单。省级党委和政府对本地区环境治理负总体责任，贯彻执行党中央、国务院各项决策部署，组织落实目标任务、政策措施，加大资金投入。市县党委和政府承担具体责任，统筹做好监管执法、市场规范、资金安排、宣传教育等工作。\n（五）明确中央和地方财政支出责任。制定实施生态环境领域中央与地方财政事权和支出责任划分改革方案，除全国性、重点区域流域、跨区域、国际合作等环境治理重大事务外，主要由地方财政承担环境治理支出责任。按照财力与事权相匹配的原则，在进一步理顺中央与地方收入划分和完善转移支付制度改革中统筹考虑地方环境治理的财政需求。\n（六）开展目标评价考核。着眼环境质量改善，合理设定约束性和预期性目标，纳入国民经济和社会发展规划、国土空间规划以及相关专项规划。各地区可制定符合实际、体现特色的目标。完善生态文明建设目标评价考核体系，对相关专项考核进行精简整合，促进开展环境治理。\n（七）深化生态环境保护督察。实行中央和省（自治区、直辖市）两级生态环境保护督察体制。以解决突出生态环境问题、改善生态环境质量、推动经济高质量发展为重点，推进例行督察，加强专项督察，严格督察整改。进一步完善排查、交办、核查、约谈、专项督察“五步法”工作模式，强化监督帮扶，压实生态环境保护责任。","level":1},{"name":"三、健全环境治理企业责任体系","text":"（八）依法实行排污许可管理制度。加快排污许可管理条例立法进程，完善排污许可制度，加强对企业排污行为的监督检查。按照新老有别、平稳过渡原则，妥善处理排污许可与环评制度的关系。\n（九）推进生产服务绿色化。从源头防治污染，优化原料投入，依法依规淘汰落后生产工艺技术。积极践行绿色生产方式，大力开展技术创新，加大清洁生产推行力度，加强全过程管理，减少污染物排放。提供资源节约、环境友好的产品和服务。落实生产者责任延伸制度。\n（十）提高治污能力和水平。加强企业环境治理责任制度建设，督促企业严格执行法律法规，接受社会监督。重点排污企业要安装使用监测设备并确保正常运行，坚决杜绝治理效果和监测数据造假。\n（十一）公开环境治理信息。排污企业应通过企业网站等途径依法公开主要污染物名称、排放方式、执行标准以及污染防治设施建设和运行情况，并对信息真实性负责。鼓励排污企业在确保安全生产前提下，通过设立企业开放日、建设教育体验场所等形式，向社会公众开放。","level":1},{"name":"四、健全环境治理全民行动体系","text":"（十二）强化社会监督。完善公众监督和举报反馈机制，充分发挥“12369”环保举报热线作用，畅通环保监督渠道。加强舆论监督，鼓励新闻媒体对各类破坏生态环境问题、突发环境事件、环境违法行为进行曝光。引导具备资格的环保组织依法开展生态环境公益诉讼等活动。\n（十三）发挥各类社会团体作用。工会、共青团、妇联等群团组织要积极动员广大职工、青年、妇女参与环境治理。行业协会、商会要发挥桥梁纽带作用，促进行业自律。加强对社会组织的管理和指导，积极推进能力建设，大力发挥环保志愿者作用。\n（十四）提高公民环保素养。把环境保护纳入国民教育体系和党政领导干部培训体系，组织编写环境保护读本，推进环境保护宣传教育进学校、进家庭、进社区、进工厂、进机关。加大环境公益广告宣传力度，研发推广环境文化产品。引导公民自觉履行环境保护责任，逐步转变落后的生活风俗习惯，积极开展垃圾分类，践行绿色生活方式，倡导绿色出行、绿色消费。","level":1},{"name":"五、健全环境治理监管体系","text":"（十五）完善监管体制。整合相关部门污染防治和生态环境保护执法职责、队伍，统一实行生态环境保护执法。全面完成省以下生态环境机构监测监察执法垂直管理制度改革。实施“双随机、一公开”环境监管模式。推动跨区域跨流域污染防治联防联控。除国家组织的重大活动外，各地不得因召开会议、论坛和举办大型活动等原因，对企业采取停产、限产措施。\n（十六）加强司法保障。建立生态环境保护综合行政执法机关、公安机关、检察机关、审判机关信息共享、案情通报、案件移送制度。强化对破坏生态环境违法犯罪行为的查处侦办，加大对破坏生态环境案件起诉力度，加强检察机关提起生态环境公益诉讼工作。在高级人民法院和具备条件的中基层人民法院调整设立专门的环境审判机构，统一涉生态环境案件的受案范围、审理程序等。探索建立“恢复性司法实践+社会化综合治理”审判结果执行机制。\n（十七）强化监测能力建设。加快构建陆海统筹、天地一体、上下协同、信息共享的生态环境监测网络，实现环境质量、污染源和生态状况监测全覆盖。实行“谁考核、谁监测”，不断完善生态环境监测技术体系，全面提高监测自动化、标准化、信息化水平，推动实现环境质量预报预警，确保监测数据“真、准、全”。推进信息化建设，形成生态环境数据一本台账、一张网络、一个窗口。加大监测技术装备研发与应用力度，推动监测装备精准、快速、便携化发展。","level":1},{"name":"六、健全环境治理市场体系","text":"（十八）构建规范开放的市场。深入推进“放管服”改革，打破地区、行业壁垒，对各类所有制企业一视同仁，平等对待各类市场主体，引导各类资本参与环境治理投资、建设、运行。规范市场秩序，减少恶性竞争，防止恶意低价中标，加快形成公开透明、规范有序的环境治理市场环境。\n（十九）强化环保产业支撑。加强关键环保技术产品自主创新，推动环保首台（套）重大技术装备示范应用，加快提高环保产业技术装备水平。做大做强龙头企业，培育一批专业化骨干企业，扶持一批专特优精中小企业。鼓励企业参与绿色“一带一路”建设，带动先进的环保技术、装备、产能走出去。\n（二十）创新环境治理模式。积极推行环境污染第三方治理，开展园区污染防治第三方治理示范，探索统一规划、统一监测、统一治理的一体化服务模式。开展小城镇环境综合治理托管服务试点，强化系统治理，实行按效付费。对工业污染地块，鼓励采用“环境修复+开发建设”模式。\n（二十一）健全价格收费机制。严格落实“谁污染、谁付费”政策导向，建立健全“污染者付费+第三方治理”等机制。按照补偿处理成本并合理盈利原则，完善并落实污水垃圾处理收费政策。综合考虑企业和居民承受能力，完善差别化电价政策。","level":1},{"name":"七、健全环境治理信用体系","text":"（二十二）加强政务诚信建设。建立健全环境治理政务失信记录，将地方各级政府和公职人员在环境保护工作中因违法违规、失信违约被司法判决、行政处罚、纪律处分、问责处理等信息纳入政务失信记录，并归集至相关信用信息共享平台，依托“信用中国”网站等依法依规逐步公开。\n（二十三）健全企业信用建设。完善企业环保信用评价制度，依据评价结果实施分级分类监管。建立排污企业黑名单制度，将环境违法企业依法依规纳入失信联合惩戒对象名单，将其违法信息记入信用记录，并按照国家有关规定纳入全国信用信息共享平台，依法向社会公开。建立完善上市公司和发债企业强制性环境治理信息披露制度。","level":1},{"name":"八、健全环境治理法律法规政策体系","text":"（二十四）完善法律法规。制定修订固体废物污染防治、长江保护、海洋环境保护、生态环境监测、环境影响评价、清洁生产、循环经济等方面的法律法规。鼓励有条件的地方在环境治理领域先于国家进行立法。严格执法，对造成生态环境损害的，依法依规追究赔偿责任；对构成犯罪的，依法追究刑事责任。\n（二十五）完善环境保护标准。立足国情实际和生态环境状况，制定修订环境质量标准、污染物排放（控制）标准以及环境监测标准等。推动完善产品环保强制性国家标准。做好生态环境保护规划、环境保护标准与产业政策的衔接配套，健全标准实施信息反馈和评估机制。鼓励开展各类涉及环境治理的绿色认证制度。\n（二十六）加强财税支持。建立健全常态化、稳定的中央和地方环境治理财政资金投入机制。健全生态保护补偿机制。制定出台有利于推进产业结构、能源结构、运输结构和用地结构调整优化的相关政策。严格执行环境保护税法，促进企业降低大气污染物、水污染物排放浓度，提高固体废物综合利用率。贯彻落实好现行促进环境保护和污染防治的税收优惠政策。\n（二十七）完善金融扶持。设立国家绿色发展基金。推动环境污染责任保险发展，在环境高风险领域研究建立环境污染强制责任保险制度。开展排污权交易，研究探索对排污权交易进行抵质押融资。鼓励发展重大环保装备融资租赁。加快建立省级土壤污染防治基金。统一国内绿色债券标准。","level":1},{"name":"九、强化组织领导","text":"（二十八）加强组织实施。地方各级党委和政府要根据本意见要求，结合本地区发展实际，进一步细化落实构建现代环境治理体系的目标任务和政策措施，确保本意见确定的重点任务及时落地见效。国家发展改革委要加强统筹协调和政策支持，生态环境部要牵头推进相关具体工作，有关部门各负其责、密切配合，重大事项及时向党中央、国务院报告。","level":1}]},{"id":"r0540","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于加快推进乡村人才振兴的意见》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于加快推进乡村人才振兴的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于加快推进乡村人才振兴的意见》全文如下。\n乡村振兴，关键在人。为深入贯彻落实习近平总书记关于推动乡村人才振兴的重要指示精神，落实党中央、国务院有关决策部署，促进各类人才投身乡村建设，现就加快推进乡村人才振兴提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，坚持和加强党对乡村人才工作的全面领导，坚持农业农村优先发展，坚持把乡村人力资本开发放在首要位置，大力培养本土人才，引导城市人才下乡，推动专业人才服务乡村，吸引各类人才在乡村振兴中建功立业，健全乡村人才工作体制机制，强化人才振兴保障措施，培养造就一支懂农业、爱农村、爱农民的“三农”工作队伍，为全面推进乡村振兴、加快农业农村现代化提供有力人才支撑。\n（二）目标任务。到2025年，乡村人才振兴制度框架和政策体系基本形成，乡村振兴各领域人才规模不断壮大、素质稳步提升、结构持续优化，各类人才支持服务乡村格局基本形成，乡村人才初步满足实施乡村振兴战略基本需要。\n（三）工作原则\n——坚持加强党对乡村人才工作的全面领导。贯彻党管人才原则，将乡村人才振兴纳入党委人才工作总体部署，引导各类人才向农村基层一线流动，打造一支能够担当乡村振兴使命的人才队伍。\n——坚持全面培养、分类施策。围绕全面推进乡村振兴需要，全方位培养各类人才，扩大总量、提高质量、优化结构。尊重乡村发展规律和人才成长规律，针对不同地区、不同类型人才，实施差别化政策措施。\n——坚持多元主体、分工配合。推动政府、培训机构、企业等发挥各自优势，共同参与乡村人才培养，解决制约乡村人才振兴的问题，形成工作合力。\n——坚持广招英才、高效用才。坚持培养与引进相结合、引才与引智相结合，拓宽乡村人才来源，聚天下英才而用之。用好用活人才，为人才干事创业和实现价值提供机会条件，最大限度激发人才内在活力。\n——坚持完善机制、强化保障。深化乡村人才培养、引进、管理、使用、流动、激励等制度改革，完善人才服务乡村激励机制，让农村的机会吸引人，让农村的环境留住人。","level":1},{"name":"二、加快培养农业生产经营人才","text":"（四）培养高素质农民队伍。深入实施现代农民培育计划，重点面向从事适度规模经营的农民，分层分类开展全产业链培训，加强训后技术指导和跟踪服务，支持创办领办新型农业经营主体。充分利用现有网络教育资源，加强农民在线教育培训。实施农村实用人才培养计划，加强培训基地建设，培养造就一批能够引领一方、带动一片的农村实用人才带头人。\n（五）突出抓好家庭农场经营者、农民合作社带头人培育。深入推进家庭农场经营者培养，完善项目支持、生产指导、质量管理、对接市场等服务。建立农民合作社带头人人才库，加强对农民合作社骨干的培训。鼓励农民工、高校毕业生、退役军人、科技人员、农村实用人才等创办领办家庭农场、农民合作社。鼓励有条件的地方支持农民合作社聘请农业经理人。鼓励家庭农场经营者、农民合作社带头人参加职称评审、技能等级认定。","level":1},{"name":"三、加快培养农村二三产业发展人才","text":"（六）培育农村创业创新带头人。深入实施农村创业创新带头人培育行动，不断改善农村创业创新生态，稳妥引导金融机构开发农村创业创新金融产品和服务方式，加快建设农村创业创新孵化实训基地，组建农村创业创新导师队伍。壮大新一代乡村企业家队伍，通过专题培训、实践锻炼、学习交流等方式，完善乡村企业家培训体系，完善涉农企业人才激励机制，加强对乡村企业家合法权益的保护。\n（七）加强农村电商人才培育。提升电子商务进农村效果，开展电商专家下乡活动。依托全国电子商务公共服务平台，加快建立农村电商人才培养载体及师资、标准、认证体系，开展线上线下相结合的多层次人才培训。\n（八）培育乡村工匠。挖掘培养乡村手工业者、传统艺人，通过设立名师工作室、大师传习所等，传承发展传统技艺。鼓励高等学校、职业院校开展传统技艺传承人教育。在传统技艺人才聚集地设立工作站，开展研习培训、示范引导、品牌培育。支持鼓励传统技艺人才创办特色企业，带动发展乡村特色手工业。\n（九）打造农民工劳务输出品牌。实施劳务输出品牌计划，围绕地方特色劳务群体，建立技能培训体系和评价体系，完善创业扶持、品牌培育政策，通过完善行业标准、建设专家工作室、邀请专家授课、举办技能比赛等途径，普遍提升从业者职业技能，提高劳务输出的组织化、专业化、标准化水平，培育一批叫得响的农民工劳务输出品牌。","level":1},{"name":"四、加快培养乡村公共服务人才","text":"（十）加强乡村教师队伍建设。落实城乡统一的中小学教职工编制标准。继续实施革命老区、民族地区、边疆地区人才支持计划、教师专项计划和银龄讲学计划。加大乡村骨干教师培养力度，精准培养本土化优秀教师。改革完善“国培计划”，深入推进“互联网+义务教育”，健全乡村教师发展体系。对长期在乡村学校任教的教师，职称评审可按规定“定向评价、定向使用”，高级岗位实行总量控制、比例单列，可不受所在学校岗位结构比例限制。落实好乡村教师生活补助政策，加强乡村学校教师周转宿舍建设，按规定将符合条件的乡村教师纳入当地住房保障范围。\n（十一）加强乡村卫生健康人才队伍建设。按照服务人口1‰左右的比例，以县为单位每5年动态调整乡镇卫生院人员编制总量，允许编制在县域内统筹使用，用好用足空余编制。推进乡村基层医疗卫生机构公开招聘，艰苦边远地区县级及基层医疗卫生机构可根据情况适当放宽学历、年龄等招聘条件，对急需紧缺卫生健康专业人才可以采取面试、直接考察等方式公开招聘。乡镇卫生院应至少配备1名公共卫生医师。深入实施全科医生特岗计划、农村订单定向医学生免费培养和助理全科医生培训，支持城市二级及以上医院在职或退休医师到乡村基层医疗卫生机构多点执业，开办乡村诊所，充实乡村卫生健康人才队伍。完善乡村基层卫生健康人才激励机制，落实职称晋升和倾斜政策，优化乡镇医疗卫生机构岗位设置，按照政策合理核定乡村基层医疗卫生机构绩效工资总量和水平。优化乡村基层卫生健康人才能力提升培训项目，加强在岗培训和继续教育。落实乡村医生各项补助，逐步提高乡村医生收入待遇，做好乡村医生参加基本养老保险工作，深入推进乡村全科执业助理医师资格考试，推动乡村医生向执业（助理）医师转化，引导医学专业高校毕业生免试申请乡村医生执业注册。鼓励免费定向培养一批源于本乡本土的大学生乡村医生，多途径培养培训乡村卫生健康工作队伍，改善乡村卫生服务和治理水平。\n（十二）加强乡村文化旅游体育人才队伍建设。推动文化旅游体育人才下乡服务，重点向革命老区、民族地区、边疆地区倾斜。完善文化和旅游、广播电视、网络视听等专业人才扶持政策，培养一批乡村文艺社团、创作团队、文化志愿者、非遗传承人和乡村旅游示范者。鼓励运动员、教练员、体育专业师生、体育科研人员参与乡村体育指导志愿服务。\n（十三）加强乡村规划建设人才队伍建设。支持熟悉乡村的首席规划师、乡村规划师、建筑师、设计师及团队参与村庄规划设计、特色景观制作、人文风貌引导，提高设计建设水平，塑造乡村特色风貌。统筹推进城乡基础设施建设管护人才互通共享，搭建服务平台，畅通交流机制。实施乡村本土建设人才培育工程，加强乡村建设工匠培训和管理，培育修路工、水利员、改厕专家、农村住房建设辅导员等专业人员，提升农村环境治理、基础设施及农村住房建设管护水平。","level":1},{"name":"五、加快培养乡村治理人才","text":"（十四）加强乡镇党政人才队伍建设。选优配强乡镇领导班子特别是乡镇党委书记，健全从乡镇事业人员、优秀村党组织书记、到村任职过的选调生、驻村第一书记、驻村工作队员中选拔乡镇领导干部常态化机制。实行乡镇编制专编专用，明确乡镇新录用公务员在乡镇最低服务年限，规范从乡镇借调工作人员。落实乡镇工作补贴和艰苦边远地区津贴政策，确保乡镇机关工作人员收入高于县直机关同职级人员。落实艰苦边远地区乡镇公务员考录政策，适当降低门槛和开考比例，允许县乡两级拿出一定数量的职位面向高校毕业生、退役军人等具有本地户籍或在本地长期生活工作的人员招考。\n（十五）推动村党组织带头人队伍整体优化提升。坚持把政治标准放在首位，选拔思想政治素质好、道德品行好、带富能力强、协调能力强，公道正派、廉洁自律，热心为群众服务的党员担任村党组织书记。注重从本村致富能手、外出务工经商返乡人员、本乡本土大学毕业生、退役军人中的党员里培养选拔村党组织书记。对本村暂时没有党组织书记合适人选的，可从上级机关、企事业单位优秀党员干部中选派，有条件的地方也可以探索跨村任职。全面落实村党组织书记县级党委组织部门备案管理制度和村“两委”成员资格联审机制，实行村“两委”成员近亲属回避，净化、优化村干部队伍。加大从优秀村党组织书记中考录乡镇公务员、招聘乡镇事业编制人员力度。县级党委每年至少对村党组织书记培训1次，支持村干部和农民参加学历教育。坚持和完善向重点乡村选派驻村第一书记和工作队制度。\n（十六）实施“一村一名大学生”培育计划。鼓励各地遴选一批高等职业学校，按照有关规定，根据乡村振兴需求开设涉农专业，支持村干部、新型农业经营主体带头人、退役军人、返乡创业农民工等，采取在校学习、弹性学制、农学交替、送教下乡等方式，就地就近接受职业高等教育，培养一批在乡大学生、乡村治理人才。进一步加强选调生到村任职、履行大学生村官有关职责、按照大学生村官管理工作，落实选调生一般应占本年度公务员考录计划10%左右的规模要求。鼓励各地多渠道招录大学毕业生到村工作。扩大高校毕业生“三支一扶”计划招募规模。\n（十七）加强农村社会工作人才队伍建设。加快推动乡镇社会工作服务站建设，加大政府购买服务力度，吸引社会工作人才提供专业服务，大力培育社会工作服务类社会组织。加大本土社会工作专业人才培养力度，鼓励村干部、年轻党员等参加社会工作职业资格评价和各类教育培训。持续实施革命老区、民族地区、边疆地区社会工作专业人才支持计划。加强乡村儿童关爱服务人才队伍建设。通过项目奖补、税收减免等方式引导高校毕业生、退役军人、返乡入乡人员参与社区服务。\n（十八）加强农村经营管理人才队伍建设。依法依规划分农村经营管理的行政职责和事业职责，建立健全职责目录清单。采取招录、调剂、聘用等方式，通过安排专兼职人员等途径，充实农村经营管理队伍，确保事有人干、责有人负。加强业务培训，力争3年内轮训一遍。加强农村土地承包经营纠纷调解仲裁人才队伍建设，鼓励各地探索建立仲裁员等级评价制度。将农村合作组织管理专业纳入农业技术人员职称评审范围，完善评价标准。加强农村集体经济组织人才培养，完善激励机制。\n（十九）加强农村法律人才队伍建设。加强农业综合行政执法人才队伍建设，加大执法人员培训力度，完善工资待遇和职业保障政策，培养通专结合、一专多能执法人才。推动公共法律服务力量下沉，通过招录、聘用、政府购买服务、发展志愿者队伍等方式，充实乡镇司法所公共法律服务人才队伍，加强乡村法律服务人才培训。以村干部、村妇联执委、人民调解员、网格员、村民小组长、退役军人等为重点，加快培育“法律明白人”。培育农村学法用法示范户，构建农业综合行政执法人员与农村学法用法示范户的密切联结机制。提高乡村人民调解员队伍专业化水平，有序推进在农村“五老”人员中选聘人民调解员。完善和落实“一村一法律顾问”制度。","level":1},{"name":"六、加快培养农业农村科技人才","text":"（二十）培养农业农村高科技领军人才。国家重大人才工程、人才专项优先支持农业农村领域，推进农业农村科研杰出人才培养，鼓励各地实施农业农村领域“引才计划”，加快培育一批高科技领军人才和团队。加强优秀青年后备人才培养，突出服务基层导向。支持高科技领军人才按照有关政策在国家农业高新技术产业示范区、农业科技园区等落户。\n（二十一）培养农业农村科技创新人才。依托现代农业产业技术体系、农业科技创新联盟、现代农业产业科技创新中心等平台，发现人才、培育人才、凝聚人才。加强农业企业科技人才培养。健全农业农村科研立项、成果评价、成果转化机制，完善科技人员兼职兼薪、分享股权期权、领办创办企业、成果权益分配等激励办法。\n（二十二）培养农业农村科技推广人才。推进农技推广体系改革创新，完善公益性和经营性农技推广融合发展机制，允许提供增值服务合理取酬。全面实施农技推广服务特聘计划。深化农技人员职称制度改革，突出业绩水平和实际贡献，向服务基层一线人才倾斜，实行农业农村科技推广人才差异化分类考核。实施基层农技人员素质提升工程，重点培训年轻骨干农技人员。建立健全农产品质量安全协管员、信息员队伍。鼓励地方对“土专家”、“田秀才”、“乡创客”发放补贴。开展“寻找最美农技员”活动。引导科研院所、高等学校开展专家服务基层活动，推广“科技小院”等培养模式，派驻研究生深入农村开展实用技术研究和推广服务工作。\n（二十三）发展壮大科技特派员队伍。坚持政府选派、市场选择、志愿参加原则，完善科技特派员工作机制，拓宽科技特派员来源渠道，逐步实现各级科技特派员科技服务和创业带动全覆盖。完善优化科技特派员扶持激励政策，持续加大对科技特派员工作支持力度，推广利益共同体模式，支持科技特派员领办创办协办农民合作社、专业技术协会和农业企业。","level":1},{"name":"七、充分发挥各类主体在乡村人才培养中的作用","text":"（二十四）完善高等教育人才培养体系。全面加强涉农高校耕读教育，将耕读教育相关课程作为涉农专业学生必修课。深入实施卓越农林人才教育培养计划2.0，加快培养拔尖创新型、复合应用型、实用技能型农林人才。用生物技术、信息技术等现代科学技术改造提升现有涉农专业，建设一批新兴涉农专业。引导综合性高校拓宽农业传统学科专业边界，增设涉农学科专业。加强乡村振兴发展研究院建设，加大涉农专业招生支持力度。加强农林高校网络培训教育资源共享，打造实用精品培训课程体系。\n（二十五）加快发展面向农村的职业教育。加强农村职业院校基础能力建设，优先支持高水平农业高职院校开展本科层次职业教育，采取校企合作、政府划拨、整合资源等方式建设一批实习实训基地。支持职业院校加强涉农专业建设、开发技术研发平台、开设特色工艺班，培养基层急需的专业技术人才。采取学制教育和专业培训相结合的模式对农村“两后生”进行技能培训。鼓励退役军人、下岗职工、农民工、高素质农民、留守妇女等报考高职院校，可适当降低文化素质测试录取分数线。\n（二十六）依托各级党校（行政学院）培养基层党组织干部队伍。发挥好党校（行政学院）、干部学院主渠道、主阵地作用，分类分级开展“三农”干部培训。以县级党校（行政学校）为主体，加强对村干部、驻村第一书记、基层团组织书记等乡村干部队伍的培训。采取线上线下相结合等模式，将党校（行政学院）、干部学院的教育资源延伸覆盖至村和社区。\n（二十七）充分发挥农业广播电视学校等培训机构作用。支持职业院校、农业广播电视学校、农村成人文化技术培训学校（机构）、农技推广机构、农业科研院所等，加强对高素质农民、能工巧匠等本土人才培养。探索建立农民学分银行，推动农民培训与职业教育有效衔接。建立政府引导、多元参与的投入机制，将农民教育培训经费按规定列入各级预算，吸引社会资本投入。\n（二十八）支持企业参与乡村人才培养。引导农业企业依托原料基地、产业园区等建设实训基地，推动和培训农民应用新技术。鼓励农业企业依托信息、科技、品牌、资金等优势，带动农民创办家庭农场、农民合作社，打造乡村人才孵化基地。支持农业企业联合科研院所、高等学校建设产学研用协同创新基地，培育科技创新人才。","level":1},{"name":"八、建立健全乡村人才振兴体制机制","text":"（二十九）健全农村工作干部培养锻炼制度。完善县级以上机关年轻干部在农村基层培养锻炼机制，有计划地选派县级以上机关有发展潜力的年轻干部到乡镇任职、挂职，多渠道选派优秀干部到农村干事创业。\n（三十）完善乡村人才培养制度。加大公费师范生培养力度，实行定向培养，明确基层服务年限，推动特岗计划与公费师范生培养相结合。推动职业院校（含技工院校）建设涉农专业或开设特色工艺班，与基层行政事业单位、用工企业精准对接，定向培养乡村人才。支持中央和国家机关有关部门、地方政府、高等学校、职业院校加强合作，按规定为艰苦地区和基层一线“订单式”培养专业人才。\n（三十一）建立各类人才定期服务乡村制度。建立城市医生、教师、科技、文化等人才定期服务乡村制度，支持和鼓励符合条件的事业单位科研人员按照国家有关规定到乡村和涉农企业创新创业，充分保障其在职称评审、工资福利、社会保障等方面的权益。鼓励地方整合各领域外部人才成立乡村振兴顾问团，支持引导退休专家和干部服务乡村振兴。落实中小学教师晋升高级职称原则上要有1年以上农村基层工作服务经历要求。国家建立医疗卫生人员定期到基层和艰苦边远地区从事医疗卫生工作制度。执业医师晋升为副高级技术职称的，应当有累计1年以上在县级以下或者对口支援的医疗卫生机构提供医疗卫生服务的经历。支持专业技术人才通过项目合作、短期工作、专家服务、兼职等多种形式到基层开展服务活动，在基层时间累计超过半年的视为基层工作经历，作为职称评审、岗位聘用的重要参考。对县乡事业单位专业性强的岗位聘用的高层次人才，可采取协议工资、项目工资、年薪制等灵活多样的分配方式，合理确定薪酬待遇。鼓励地方通过建设人才公寓、发放住房补助，允许返乡入乡人员子女在就业创业地接受学前教育、义务教育，解决好返乡入乡人员的居住和子女入学问题。完善社保关系转移接续机制，为返乡入乡人员及其家属按规定参加城镇职工基本养老保险、基本医疗保险提供便捷服务。\n（三十二）健全鼓励人才向艰苦地区和基层一线流动激励制度。适当放宽在基层一线工作的专业技术人才职称评审条件。对长期在基层一线和艰苦边远地区工作的，加大爱岗敬业表现、实际工作业绩及工作年限等评价权重，落实完善工资待遇倾斜政策，激励人才扎根一线建功立业。推广医疗、教育人才“组团式”援疆援藏经验做法，逐步将人才“组团式”帮扶拓展到其他艰苦地区和更多领域。\n（三十三）建立县域专业人才统筹使用制度。积极开展统筹使用基层各类编制资源试点，探索赋予乡镇更加灵活的用人自主权，鼓励从上往下跨层级调剂行政事业编制，推动资源服务管理向基层倾斜。推进义务教育阶段教师“县管校聘”，推广城乡学校共同体、乡村中心校模式。加强县域卫生人才一体化配备和管理，在区域卫生编制总量内统一配备各类卫生人才，强化多劳多得、优绩优酬，鼓励实行“县聘乡用”和“乡聘村用”。\n（三十四）完善乡村高技能人才职业技能等级制度。组织农民参加职业技能鉴定、职业技能等级认定、职业技能竞赛等多种技能评价。探索“以赛代评”、“以项目代评”，符合条件可直接认定相应技能等级。按照有关规定对有突出贡献人才破格评定相应技能等级。\n（三十五）建立健全乡村人才分级分类评价体系。坚持“把论文写在大地上”，完善农业农村领域高级职称评审申报条件，探索推行技术标准、专题报告、发展规划、技术方案、试验报告等视同发表论文的评审方式。对乡村发展急需紧缺人才，可以设置特设岗位，不受常设岗位总量、职称最高等级和结构比例限制。\n（三十六）提高乡村人才服务保障能力。完善乡村人才认定标准，做好乡村人才分类统计，加强乡村人才工作信息化建设，建立健全县乡村三级乡村人才管理网络。加强人才管理服务工作，大力发展乡村人才服务业，引导市场主体为乡村人才提供中介、信息等服务。","level":1},{"name":"九、保障措施","text":"（三十七）加强组织领导。各级党委要将乡村人才振兴作为实施乡村振兴战略的重要任务，建立党委统一领导、组织部门指导、党委农村工作部门统筹协调、相关部门分工负责的乡村人才振兴工作联席会议制度。把乡村人才振兴纳入人才工作目标责任制考核和乡村振兴实绩考核。加强农村工作干部队伍的培养、配备、管理、使用，将干部培养向乡村振兴一线倾斜，选优配强涉农部门领导班子和市县分管乡村振兴的领导干部，注重提拔使用政治过硬、实绩突出的农村工作干部。\n（三十八）强化政策保障。加强乡村人才振兴投入保障，支持涉农企业加大乡村人力资本开发投入。农村集体经营性建设用地和复垦腾退建设用地指标注重支持各类乡村人才发展新产业新业态。推进农村金融产品和服务创新，鼓励证券、保险、担保、基金等金融机构服务乡村振兴，引导工商资本投资乡村事业，带动人才回流乡村。\n（三十九）搭建乡村引才聚才平台。加强现代农业产业园、农业科技园区、农村创业创新园区等平台建设，支持入园企业、科研院所等建设科研创新平台，完善科技成果转化、人才奖补等政策，引进高层次人才和急需紧缺专业人才。加强人才驿站、人才服务站、专家服务基地、青年之家、妇女之家等人才服务平台建设，为乡村人才提供政策咨询、职称申报、项目申报、融资对接等服务。\n（四十）制定乡村人才专项规划。对标实施乡村振兴战略需要，评估乡村人才供求总量和结构，细分乡村人才供求缺口，探索建立乡村人才信息库和需求目录。在摸清乡村人才现状基础上，制定乡村人才振兴规划，明确乡村人才振兴的总体要求、重点任务、政策措施，推动“三农”工作人才队伍建设制度化、规范化、常态化。\n（四十一）营造良好环境。完善扶持乡村产业发展的政策体系，建好农村基础设施和公共服务设施，改善农村发展条件，提高农村生活便利化水平，吸引城乡人才留在农村。通过优秀人才评选、创新创业比赛、职业技能大赛等途径，每年选树一批乡村人才先进典型，按照规定给予表彰和政策扶持，引导乡村人才增强力争上游、务农光荣的思想观念。\n延伸阅读\n加快培养一支懂农业、爱农村、爱农民的“三农”工作队伍——中央农办负责人就《关于加快推进乡村人才振兴的意见》答记者问\n全面推进乡村振兴","level":1}]},{"id":"r0541","sections":[{"name":"关于深入推进城市执法体制改革改进城市管理工作的指导意见","text":"改革开放以来，我国城镇化快速发展，城市规模不断扩大，建设水平逐步提高，保障城市健康运行的任务日益繁重，加强和改善城市管理的需求日益迫切，城市管理工作的地位和作用日益突出。各地区各有关方面适应社会发展形势，积极做好城市管理工作，探索提高城市管理执法和服务水平，对改善城市秩序、促进城市和谐、提升城市品质发挥了重要作用。但也要清醒看到，与新型城镇化发展要求和人民群众生产生活需要相比，我国多数地区在城市市政管理、交通运行、人居环境、应急处置、公共秩序等方面仍有较大差距，城市管理执法工作还存在管理体制不顺、职责边界不清、法律法规不健全、管理方式简单、服务意识不强、执法行为粗放等问题，社会各界反映较为强烈，在一定程度上制约了城市健康发展和新型城镇化的顺利推进。","level":1},{"name":"","text":"深入推进城市管理执法体制改革，改进城市管理工作，是落实“四个全面”战略布局的内在要求，是提高政府治理能力的重要举措，是增进民生福祉的现实需要，是促进城市发展转型的必然选择。为理顺城市管理执法体制，解决城市管理面临的突出矛盾和问题，消除城市管理工作中的短板，进一步提高城市管理和公共服务水平，现提出以下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。深入贯彻党的十八大和十八届二中、三中、四中、五中全会及中央城镇化工作会议、中央城市工作会议精神，以“四个全面”战略布局为引领，牢固树立创新、协调、绿色、开放、共享的发展理念，以城市管理现代化为指向，以理顺体制机制为途径，将城市管理执法体制改革作为推进城市发展方式转变的重要手段，与简政放权、放管结合、转变政府职能、规范行政权力运行等有机结合，构建权责明晰、服务为先、管理优化、执法规范、安全有序的城市管理体制，推动城市管理走向城市治理，促进城市运行高效有序，实现城市让生活更美好。\n（二）基本原则\n——坚持以人为本。牢固树立为人民管理城市的理念，强化宗旨意识和服务意识，落实惠民和便民措施，以群众满意为标准，切实解决社会各界最关心、最直接、最现实的问题，努力消除各种“城市病”。\n——坚持依法治理。完善执法制度，改进执法方式，提高执法素养，把严格规范公正文明执法的要求落实到城市管理执法全过程。\n——坚持源头治理。增强城市规划、建设、管理的科学性、系统性和协调性，综合考虑公共秩序管理和群众生产生活需要，合理安排各类公共设施和空间布局，加强对城市规划、建设实施情况的评估和反馈。变被动管理为主动服务，变末端执法为源头治理，从源头上预防和减少违法违规行为。\n——坚持权责一致。明确城市管理和执法职责边界，制定权力清单，落实执法责任，权随事走、人随事调、费随事转，实现事权和支出相适应、权力和责任相统一。合理划分城市管理事权，实行属地管理，明确市、县政府在城市管理和执法中负主体责任，充实一线人员力量，落实执法运行经费，将工作重点放在基层。\n——坚持协调创新。加强政策措施的配套衔接，强化部门联动配合，有序推进相关工作。以网格化管理、社会化服务为方向，以智慧城市建设为契机，充分发挥现代信息技术的优势，加快形成与经济社会发展相匹配的城市管理能力。\n（三）总体目标。到2017年年底，实现市、县政府城市管理领域的机构综合设置。到2020年，城市管理法律法规和标准体系基本完善，执法体制基本理顺，机构和队伍建设明显加强，保障机制初步完善，服务便民高效，现代城市治理体系初步形成，城市管理效能大幅提高，人民群众满意度显著提升。","level":1},{"name":"二、理顺管理体制","text":"（四）匡定管理职责。城市管理的主要职责是市政管理、环境管理、交通管理、应急管理和城市规划实施管理等。具体实施范围包括：市政公用设施运行管理、市容环境卫生管理、园林绿化管理等方面的全部工作；市、县政府依法确定的，与城市管理密切相关、需要纳入统一管理的公共空间秩序管理、违法建设治理、环境保护管理、交通管理、应急管理等方面的部分工作。城市管理执法即是在上述领域根据国家法律法规规定履行行政执法权力的行为。\n（五）明确主管部门。国务院住房和城乡建设主管部门负责对全国城市管理工作的指导，研究拟定有关政策，制定基本规范，做好顶层设计，加强对省、自治区、直辖市城市管理工作的指导监督协调，积极推进地方各级政府城市管理事权法律化、规范化。各省、自治区、直辖市政府应当确立相应的城市管理主管部门，加强对辖区内城市管理工作的业务指导、组织协调、监督检查和考核评价。各地应科学划分城市管理部门与相关行政主管部门的工作职责，有关管理和执法职责划转城市管理部门后，原主管部门不再行使。\n（六）综合设置机构。按照精简统一效能的原则，住房城乡建设部会同中央编办指导地方整合归并省级执法队伍，推进市县两级政府城市管理领域大部门制改革，整合市政公用、市容环卫、园林绿化、城市管理执法等城市管理相关职能，实现管理执法机构综合设置。统筹解决好机构性质问题，具备条件的应当纳入政府机构序列。遵循城市运行规律，建立健全以城市良性运行为核心，地上地下设施建设运行统筹协调的城市管理体制机制。有条件的市和县应当建立规划、建设、管理一体化的行政管理体制，强化城市管理和执法工作。\n（七）推进综合执法。重点在与群众生产生活密切相关、执法频率高、多头执法扰民问题突出、专业技术要求适宜、与城市管理密切相关且需要集中行使行政处罚权的领域推行综合执法。具体范围是：住房城乡建设领域法律法规规章规定的全部行政处罚权；环境保护管理方面社会生活噪声污染、建筑施工噪声污染、建筑施工扬尘污染、餐饮服务业油烟污染、露天烧烤污染、城市焚烧沥青塑料垃圾等烟尘和恶臭污染、露天焚烧秸秆落叶等烟尘污染、燃放烟花爆竹污染等的行政处罚权；工商管理方面户外公共场所无照经营、违规设置户外广告的行政处罚权；交通管理方面侵占城市道路、违法停放车辆等的行政处罚权；水务管理方面向城市河道倾倒废弃物和垃圾及违规取土、城市河道违法建筑物拆除等的行政处罚权；食品药品监管方面户外公共场所食品销售和餐饮摊点无证经营，以及违法回收贩卖药品等的行政处罚权。城市管理部门可以实施与上述范围内法律法规规定的行政处罚权有关的行政强制措施。到2017年年底，实现住房城乡建设领域行政处罚权的集中行使。上述范围以外需要集中行使的具体行政处罚权及相应的行政强制权，由市、县政府报所在省、自治区政府审批，直辖市政府可以自行确定。\n（八）下移执法重心。按照属地管理、权责一致的原则，合理确定设区的市和市辖区城市管理部门的职责分工。市级城市管理部门主要负责城市管理和执法工作的指导、监督、考核，以及跨区域及重大复杂违法违规案件的查处。按照简政放权、放管结合、优化服务的要求，在设区的市推行市或区一级执法，市辖区能够承担的可以实行区一级执法，区级城市管理部门可以向街道派驻执法机构，推动执法事项属地化管理；市辖区不能承担的，市级城市管理部门可以向市辖区和街道派驻执法机构，开展综合执法工作。派驻机构业务工作接受市或市辖区城市管理部门的领导，日常管理以所在市辖区或街道为主，负责人的调整应当征求派驻地党（工）委的意见。逐步实现城市管理执法工作全覆盖，并向乡镇延伸，推进城乡一体化发展。","level":1},{"name":"三、强化队伍建设","text":"（九）优化执法力量。各地应当根据执法工作特点合理设置岗位，科学确定城市管理执法人员配备比例标准，统筹解决好执法人员身份编制问题，在核定的行政编制数额内，具备条件的应当使用行政编制。执法力量要向基层倾斜，适度提高一线人员的比例，通过调整结构优化执法力量，确保一线执法工作需要。区域面积大、流动人口多、管理执法任务重的地区，可以适度调高执法人员配备比例。\n（十）严格队伍管理。建立符合职业特点的城市管理执法人员管理制度，优化干部任用和人才选拔机制，严格按照公务员法有关规定开展执法人员录用等有关工作，加大接收安置军转干部的力度，加强领导班子和干部队伍建设。根据执法工作需要，统一制式服装和标志标识，制定执法执勤用车、装备配备标准，到2017年年底，实现执法制式服装和标志标识统一。严格执法人员素质要求，加强思想道德和素质教育，着力提升执法人员业务能力，打造政治坚定、作风优良、纪律严明、廉洁务实的执法队伍。\n（十一）注重人才培养。加强现有在编执法人员业务培训和考试，严格实行执法人员持证上岗和资格管理制度，到2017年年底，完成处级以上干部轮训和持证上岗工作。建立符合职业特点的职务晋升和交流制度，切实解决基层执法队伍基数大、职数少的问题，确保部门之间相对平衡、职业发展机会平等。完善基层执法人员工资政策。研究通过工伤保险、抚恤等政策提高风险保障水平。鼓励高等学校设置城市管理专业或开设城市管理课程，依托党校、行政学院、高等学校等开展岗位培训。\n（十二）规范协管队伍。各地可以根据实际工作需要，采取招用或劳务派遣等形式配置城市管理执法协管人员。建立健全协管人员招聘、管理、奖惩、退出等制度。协管人员数量不得超过在编人员，并应当随城市管理执法体制改革逐步减少。协管人员只能配合执法人员从事宣传教育、巡查、信息收集、违法行为劝阻等辅助性事务，不得从事具体行政执法工作。协管人员从事执法辅助事务以及超越辅助事务所形成的后续责任，由本级城市管理部门承担。","level":1},{"name":"四、提高执法水平","text":"（十三）制定权责清单。各地要按照转变政府职能、规范行政权力运行的要求，全面清理调整现有城市管理和综合执法职责，优化权力运行流程。依法建立城市管理和综合执法部门的权力和责任清单，向社会公开职能职责、执法依据、处罚标准、运行流程、监督途径和问责机制。制定责任清单与权力清单工作要统筹推进，并实行动态管理和调整。到2016年年底，市、县两级城市管理部门要基本完成权力清单和责任清单的制定公布工作。\n（十四）规范执法制度。各地城市管理部门应当切实履行城市管理执法职责，完善执法程序，规范办案流程，明确办案时限，提高办案效率。积极推行执法办案评议考核制度和执法公示制度。健全行政处罚适用规则和裁量基准制度、执法全过程记录制度。严格执行重大执法决定法制审核制度。杜绝粗暴执法和选择性执法，确保执法公信力，维护公共利益、人民权益和社会秩序。\n（十五）改进执法方式。各地城市管理执法人员应当严格履行执法程序，做到着装整齐、用语规范、举止文明，依法规范行使行政检查权和行政强制权，严禁随意采取强制执法措施。坚持处罚与教育相结合的原则，根据违法行为的性质和危害后果，灵活运用不同执法方式，对情节较轻或危害后果能够及时消除的，应当多做说服沟通工作，加强教育、告诫、引导。综合运用行政指导、行政奖励、行政扶助、行政调解等非强制行政手段，引导当事人自觉遵守法律法规，及时化解矛盾纷争，促进社会和谐稳定。\n（十六）完善监督机制。强化外部监督机制，畅通群众监督渠道、行政复议渠道，城市管理部门和执法人员要主动接受法律监督、行政监督、社会监督。强化内部监督机制，全面落实行政执法责任制，加强城市管理部门内部流程控制，健全责任追究机制、纠错问责机制。强化执法监督工作，坚决排除对执法活动的违规人为干预，防止和克服各种保护主义。","level":1},{"name":"五、完善城市管理","text":"（十七）加强市政管理。市政公用设施建设完成后，应当及时将管理信息移交城市管理部门，并建立完备的城建档案，实现档案信息共享。加强市政公用设施管护工作，保障安全高效运行。加强城市道路管理，严格控制道路开挖或占用道路行为。加强城市地下综合管廊、给排水和垃圾处理等基础设施管理，服务入廊单位生产运行和市民日常生活。\n（十八）维护公共空间。加强城市公共空间规划，提升城市设计水平。加强建筑物立面管理和色调控制，规范报刊亭、公交候车亭等“城市家具”设置，加强户外广告、门店牌匾设置管理。加强城市街头流浪乞讨人员救助管理。严查食品无证摊贩、散发张贴小广告、街头非法回收药品、贩卖非法出版物等行为。及时制止、严肃查处擅自变更建设项目规划设计和用途、违规占用公共空间以及乱贴乱画乱挂等行为，严厉打击违法用地、违法建设行为。\n（十九）优化城市交通。坚持公交优先战略，着力提升城市公共交通服务水平。加强不同交通工具之间的协调衔接，倡导步行、自行车等绿色出行方式。打造城市交通微循环系统，加大交通需求调控力度，优化交通出行结构，提高路网运行效率。加强城市交通基础设施和智能化交通指挥设施管理维护。整顿机动车交通秩序。加强城市出租客运市场管理。加强静态交通秩序管理，综合治理非法占道停车及非法挪用、占用停车设施，鼓励社会资本投入停车场建设，鼓励单位停车场错时对外开放，逐步缓解停车难问题。\n（二十）改善人居环境。切实增加物质和人力投入，提高城市园林绿化、环卫保洁水平，加强大气、噪声、固体废物、河湖水系等环境管理，改善城市人居环境。规范建筑施工现场管理，严控噪声扰民、施工扬尘和渣土运输抛洒。推进垃圾减量化、资源化、无害化管理。加强废弃电器电子产品回收处理和医疗垃圾集中处理管理。大力开展爱国卫生运动，提高城市卫生水平。\n（二十一）提高应急能力。提高城市防灾减灾能力，保持水、电、气、热、交通、通信、网络等城市生命线系统畅通。建立完善城市管理领域安全监管责任制，强化重大危险源监控，消除重大事故隐患。加强城市基础设施安全风险隐患排查，建立分级、分类、动态管理制度。完善城市管理应急响应机制，提高突发事件处置能力。强化应急避难场所、设施设备管理，加强各类应急物资储备。建立应急预案动态调整管理制度，经常性开展疏散转移、自救互救等综合演练。做好应对自然灾害等突发事件的军地协调工作。\n（二十二）整合信息平台。积极推进城市管理数字化、精细化、智慧化，到2017年年底，所有市、县都要整合形成数字化城市管理平台。基于城市公共信息平台，综合运用物联网、云计算、大数据等现代信息技术，整合人口、交通、能源、建设等公共设施信息和公共基础服务，拓展数字化城市管理平台功能。加快数字化城市管理向智慧化升级，实现感知、分析、服务、指挥、监察“五位一体”。整合城市管理相关电话服务平台，形成全国统一的12319城市管理服务热线，并实现与110报警电话等的对接。综合利用各类监测监控手段，强化视频监控、环境监测、交通运行、供水供气供电、防洪防涝、生命线保障等城市运行数据的综合采集和管理分析，形成综合性城市管理数据库，重点推进城市建筑物数据库建设。强化行政许可、行政处罚、社会诚信等城市管理全要素数据的采集与整合，提升数据标准化程度，促进多部门公共数据资源互联互通和开放共享，建立用数据说话、用数据决策、用数据管理、用数据创新的新机制。\n（二十三）构建智慧城市。加强城市基础设施智慧化管理与监控服务，加快市政公用设施智慧化改造升级，构建城市虚拟仿真系统，强化城镇重点应用工程建设。发展智慧水务，构建覆盖供水全过程、保障供水质量安全的智能供排水和污水处理系统。发展智慧管网，实现城市地下空间、地下综合管廊、地下管网管理信息化和运行智能化。发展智能建筑，实现建筑设施设备节能、安全的智能化管控。加快城市管理和综合执法档案信息化建设。依托信息化技术，综合利用视频一体化技术，探索快速处置、非现场执法等新型执法模式，提升执法效能。","level":1},{"name":"六、创新治理方式","text":"（二十四）引入市场机制。发挥市场作用，吸引社会力量和社会资本参与城市管理。鼓励地方通过政府和社会资本合作等方式，推进城市市政基础设施、市政公用事业、公共交通、便民服务设施等的市场化运营。推行环卫保洁、园林绿化管养作业、公共交通等由政府向社会购买服务，逐步加大购买服务力度。综合运用规划引导、市场运作、商户自治等方式，顺应历史沿革和群众需求，合理设置、有序管理方便生活的自由市场、摊点群、流动商贩疏导点等经营场所和服务网点，促创业、带就业、助发展、促和谐。\n（二十五）推进网格管理。建立健全市、区（县）、街道（乡镇）、社区管理网络，科学划分网格单元，将城市管理、社会管理和公共服务事项纳入网格化管理。明确网格管理对象、管理标准和责任人，实施常态化、精细化、制度化管理。依托基层综合服务管理平台，全面加强对人口、房屋、证件、车辆、场所、社会组织等各类基础信息的实时采集、动态录入，准确掌握情况，及时发现和快速处置问题，有效实现政府对社会单元的公共管理和服务。\n（二十六）发挥社区作用。加强社区服务型党组织建设，充分发挥党组织在基层社会治理中的领导核心作用，发挥政府在基层社会治理中的主导作用。依法建立社区公共事务准入制度，充分发挥社区居委会作用，增强社区自治功能。充分发挥社会工作者等专业人才的作用，培育社区社会组织，完善社区协商机制。推动制定社区居民公约，促进居民自治管理。建设完善社区公共服务设施，打造方便快捷生活圈。通过建立社区综合信息平台、编制城市管理服务图册、设置流动服务站等方式，提供惠民便民公共服务。\n（二十七）动员公众参与。依法规范公众参与城市治理的范围、权利和途径，畅通公众有序参与城市治理的渠道。倡导城市管理志愿服务，建立健全城市管理志愿服务宣传动员、组织管理、激励扶持等制度和组织协调机制，引导志愿者与民间组织、慈善机构和非营利性社会团体之间的交流合作，组织开展多形式、常态化的志愿服务活动。依法支持和规范服务性、公益性、互助性社会组织发展。采取公众开放日、主题体验活动等方式，引导社会组织、市场中介机构和公民法人参与城市治理，形成多元共治、良性互动的城市治理模式。\n（二十八）提高文明意识。把培育和践行社会主义核心价值观作为城市文明建设的根本任务，融入国民教育和精神文明创建全过程，广泛开展城市文明教育，大力弘扬社会公德。深化文明城市创建，不断提升市民文明素质和城市文明程度。积极开展新市民教育和培训，让新市民尽快融入城市生活，促进城市和谐稳定。充分发挥各级党组织和工会、共青团、妇联等群团组织的作用，广泛开展城市文明主题宣传教育和实践活动。加强社会诚信建设，坚持将公约引导、信用约束、法律规制相结合，以他律促自律。","level":1},{"name":"七、完善保障机制","text":"（二十九）健全法律法规。加强城市管理和执法方面的立法工作，完善配套法规和规章，实现深化改革与法治保障有机统一，发挥立法对改革的引领和规范作用。有立法权的城市要根据立法法的规定，加快制定城市管理执法方面的地方性法规、规章，明晰城市管理执法范围、程序等内容，规范城市管理执法的权力和责任。全面清理现行法律法规中与推进城市管理执法体制改革不相适应的内容，定期开展规章和规范性文件清理工作，并向社会公布清理结果，加强法律法规之间的衔接。加快制定修订一批城市管理和综合执法方面的标准，形成完备的标准体系。\n（三十）保障经费投入。按照事权和支出责任相适应原则，健全责任明确、分类负担、收支脱钩、财政保障的城市管理经费保障机制，实现政府资产与预算管理有机结合，防止政府资产流失。城市政府要将城市管理经费列入同级财政预算，并与城市发展速度和规模相适应。严格执行罚缴分离、收支两条线制度，不得将城市管理经费与罚没收入挂钩。各地要因地制宜加大财政支持力度，统筹使用有关资金，增加对城市管理执法人员、装备、技术等方面的资金投入，保障执法工作需要。\n（三十一）加强司法衔接。建立城市管理部门与公安机关、检察机关、审判机关信息共享、案情通报、案件移送等制度，实现行政处罚与刑事处罚无缝对接。公安机关要依法打击妨碍城市管理执法和暴力抗法行为，对涉嫌犯罪的，应当依照法定程序处理。检察机关、审判机关要加强法律指导，及时受理、审理涉及城市管理执法的案件。检察机关有权对城市管理部门在行政执法中发现涉嫌犯罪案件线索的移送情况进行监督，城市管理部门对于发现的涉嫌犯罪案件线索移送不畅的，可以向检察机关反映。加大城市管理执法行政处罚决定的行政和司法强制执行力度。","level":1},{"name":"八、加强组织领导","text":"（三十二）明确工作责任。加强党对城市管理工作的组织领导。各级党委和政府要充分认识推进城市管理执法体制改革、改进城市管理工作的重要性和紧迫性，把这项工作列入重要议事日程，按照有利于服务群众的原则，切实履行领导责任，研究重大问题，把握改革方向，分类分层推进。各省、自治区可以选择一个城市先行试点，直辖市可以全面启动改革工作。各省、自治区、直辖市政府要制定具体方案，明确时间步骤，细化政策措施，及时总结试点经验，稳妥有序推进改革。上级政府要加强对下级政府的指导和督促检查，重要事项及时向党委报告。中央和国家机关有关部门要增强大局意识、责任意识，加强协调配合，支持和指导地方推进改革工作。\n（三十三）建立协调机制。建立全国城市管理工作部际联席会议制度，统筹协调解决制约城市管理工作的重大问题，以及相关部门职责衔接问题。各省、自治区政府应当建立相应的协调机制。市、县政府应当建立主要负责同志牵头的城市管理协调机制，加强对城市管理工作的组织协调、监督检查和考核奖惩。建立健全市、县相关部门之间信息互通、资源共享、协调联动的工作机制，形成管理和执法工作合力。\n（三十四）健全考核制度。将城市管理执法工作纳入经济社会发展综合评价体系和领导干部政绩考核体系，推动地方党委、政府履职尽责。推广绩效管理和服务承诺制度，加快建立城市管理行政问责制度，健全社会公众满意度评价及第三方考评机制，形成公开、公平、公正的城市管理和综合执法工作考核奖惩制度体系。加强城市管理效能考核，将考核结果作为城市党政领导班子和领导干部综合考核评价的重要参考。\n（三十五）严肃工作纪律。各级党委和政府要严格执行有关编制、人事、财经纪律，严禁在推进城市管理执法体制改革工作中超编进人、超职数配备领导干部、突击提拔干部。对违反规定的，要按规定追究有关单位和人员的责任。在职责划转、机构和人员编制整合调整过程中，应当按照有关规定衔接好人财物等要素，做好工作交接，保持工作的连续性和稳定性。涉及国有资产划转的，应做好资产清查工作，严格执行国有资产管理有关规定，确保国有资产安全完整。\n（三十六）营造舆论环境。各级党委和政府要高度重视宣传和舆论引导工作，加强中央与地方的宣传联动，将改革实施与宣传工作协同推进，正确引导社会预期。加强对城市管理执法先进典型的正面宣传，营造理性、积极的舆论氛围，及时回应社会关切，凝聚改革共识。推进城市管理执法信息公开，保障市民的知情权、参与权、表达权、监督权。加强城市管理执法舆情监测、研判、预警和应急处置，提高舆情应对能力。住房城乡建设部、中央编办、国务院法制办要及时总结各地经验，切实强化对推进城市管理执法体制改革、提高城市管理水平相关工作的协调指导和监督检查。重大问题要及时报告党中央、国务院。中央将就贯彻落实情况适时组织开展专项监督检查。","level":1}]},{"id":"r0542","sections":[{"name":"中共中央办公厅印发《关于在县处级以上领导干部中开展“三严三实”专题教育方案》","text":"点击此处观看视频","level":1},{"name":"","text":"近日，中共中央办公厅印发《关于在县处级以上领导干部中开展“三严三实”专题教育方案》（以下简称《方案》），对2015年在县处级以上领导干部中开展“三严三实”专题教育作出安排。\n《方案》要求，开展“三严三实”专题教育，要深入学习贯彻党的十八大和十八届三中、四中全会精神，深入学习贯彻习近平总书记系列重要讲话精神，紧紧围绕协调推进“四个全面”战略布局，对照“严以修身、严以用权、严以律己，谋事要实、创业要实、做人要实”的要求，聚焦对党忠诚、个人干净、敢于担当，着力解决“不严不实”问题，切实增强践行“三严三实”要求的思想自觉和行动自觉，努力在深化“四风”整治、巩固和拓展党的群众路线教育实践活动成果上见实效，在守纪律讲规矩、营造良好政治生态上见实效，在真抓实干、推动改革发展稳定上见实效。\n《方案》强调，坚持从严要求，强化问题导向，真正把自己摆进去，着力解决理想信念动摇、信仰迷茫、精神迷失，宗旨意识淡薄、忽视群众利益、漠视群众疾苦，党性修养缺失、不讲党的原则等问题；着力解决滥用权力、设租寻租，官商勾结、利益输送，不直面问题、不负责任、不敢担当，顶风违纪还在搞“四风”、不收敛不收手等问题；着力解决无视党的政治纪律和政治规矩，对党不忠诚、做人不老实，阳奉阴违、自行其是，心中无党纪、眼里无国法等问题，推动各级领导干部把“三严三实”作为修身做人用权律己的基本遵循、干事创业的行为准则，争做“三严三实”的好干部。\n《方案》提出，坚持以上率下、示范带动。中央政治局带头开展“三严三实”专题教育。全国人大常委会党组、国务院党组、全国政协党组结合各自实际开展“三严三实”专题教育。同时，对省部级领导干部，市、县党政领导班子成员特别是党政主要负责同志，机关、企事业单位及其内设机构县处级以上领导干部和管理人员，分层提出要求。\n《方案》明确，“三严三实”专题教育作为党的群众路线教育实践活动的延展深化，作为加强党的思想政治建设和作风建设的重要举措，要融入领导干部经常性学习教育，不分批次、不划阶段、不设环节，不是一次活动。从今年4月底开始，在各级党政机关、人民团体及其内设机构县处级以上领导干部和事业单位、国有企业中层以上领导人员中开展，各级同步进行。\n《方案》提出，结合专题教育动员部署工作，县级以上党委（党组）书记要带头讲“三严三实”专题党课。党委（党组）中心组和内设机构党组织要开展“三严三实”专题学习研讨。今年底，机关、企事业单位及其内设机构县处级以上党员领导干部年度民主生活会和组织生活会，要以践行“三严三实”为主题进行。要强化整改落实和立规执纪，坚持边学边查边改，主要领导干部带头，列出问题清单，一项一项整改，进行专项整治，严格正风肃纪。对存在“不严不实”问题的领导干部，立足于教育提高，促其改进；对群众意见大、不能认真查摆问题、没有明显改进的，要进行组织调整。针对“不严不实”问题，建制度、立规矩，强化刚性执行。\n《方案》要求，把开展“三严三实”专题教育与做好当前改革发展稳定各项工作结合起来，与完成本地区本部门本单位重点工作任务结合起来，做到专题教育与日常工作有机融合、相互促进，两手抓、两不误。","level":0}]},{"id":"r0543","sections":[{"name":"中共中央 国务院 中央军委印发《关于加强和改进新时代全民国防教育工作的意见》","text":"近日，中共中央、国务院、中央军委印发了《关于加强和改进新时代全民国防教育工作的意见》（以下简称《意见》）。","level":1},{"name":"","text":"《意见》指出，全民国防教育是建设巩固国防和强大人民军队的基础性工程，是党的宣传思想工作的重要组成部分，是弘扬爱国主义精神、增强全民国防意识的有效途径，意义重大，影响深远。党的十八大以来，以习近平同志为核心的党中央高度重视全民国防教育工作，作出一系列重要决策部署，推动新时代全民国防教育领导体制机制改革，设立烈士纪念日、国家公祭日，建立党和国家功勋荣誉表彰制度，筹划举行一系列重大庆祝纪念活动，极大提振了党心军心民心，全民国防意识不断增强，关心支持国防和军队建设的社会氛围更加浓厚。在推进祖国和平统一，维护国家主权、安全、发展利益，实现建军一百年奋斗目标中，全民国防教育工作使命光荣、任务艰巨。\n《意见》明确，加强和改进新时代全民国防教育工作，要以习近平新时代中国特色社会主义思想为指导，坚持和加强党对全民国防教育工作的领导，增强“四个意识”、坚定“四个自信”、做到“两个维护”，贯彻总体国家安全观，培育和践行社会主义核心价值观，着力增强全民爱党爱国爱社会主义的深厚感情、居安思危的忧患意识、崇军尚武的思想观念、强国强军的责任担当，使关心国防、热爱国防、建设国防、保卫国防成为全社会的思想共识和自觉行动。\n《意见》强调，要落实习近平总书记关于加强全民国防教育的重要指示精神，将习近平强军思想融入全民国防教育各领域、全过程。加强国防理论、国防知识、国防历史、国防法规、国防科技、国防形势与任务、国防技能学习教育，培育国防文化，提高广大干部群众的国防意识和国防素养。持续强化领导干部国防教育，分级组织对省部级、厅局级、县处级领导干部进行国防教育专题培训，有序开展企事业单位、大中小学校、各类媒体等负责人的国防教育专题培训。着力加强青少年国防教育，将国防教育要求有机融入课程教材，将国防教育融入普通高等学校和中等学校考试内容，纳入学校绩效考评体系。\n《意见》提出，要不断丰富实践载体，依托军地资源，优化结构布局，推动各省区市建设一批国防特色鲜明、功能设施配套的全民国防教育基地。广泛开展群众性国防教育活动，组织举办“爱我国防”全国大学生演讲和大中小学国防知识普及活动，开展国防主题电影展映、国防竞技比武、国防体育运动赛事等群众性国防教育活动，吸引社会各界广泛参与。加强舆论宣传引导，把全民国防教育融入重大主题宣传、形势政策宣传、成就宣传、典型宣传，提高全民国防教育宣传的吸引力和感染力。鼓励创作优秀文艺作品，不断推出更多体现爱国强军、献身国防的文艺精品力作。注重先进典型示范引领，精心选树一批为国防事业做出重大贡献的先进典型，开展“情系国防”系列先进典型宣传活动。加强全民国防教育信息化建设，建设全民国防教育新媒体网络体系。\n《意见》要求，要大力推动创新发展，探索运用互联网、大数据、云计算、人工智能、区块链等新技术新应用，发挥数字技术对全民国防教育的放大、叠加、倍增作用。加强全民国防教育学科建设，完善学科课程体系，开展理论研究和教材编写。充分发挥军队重要作用，按照规定组织开展系列军营开放活动，遴选军队专家学者参加国防教育师资库、宣讲团，协调开展军事实践活动，支持配合地方开展全民国防教育。完善领导体系，健全工作机制，完善政策法规，建立考评体系，把加强和改进全民国防教育作为全党全军全社会的共同责任，纳入地方党委和政府、军队各部门职责任务，形成党委领导、军地密切配合、社会各界支持、全民共同参与的工作局面。\n延伸阅读\n开创新时代全民国防教育工作新局面——中央宣传部负责人就《关于加强和改进新时代全民国防教育工作的意见》答记者问","level":0}]},{"id":"r0544","sections":[{"name":"推进领导干部能上能下规定","text":"推进领导干部能上能下规定\n（2015年6月26日中共中央政治局会议审议批准 2015年7月19日中共中央办公厅发布 2022年8月19日中共中央政治局常委会会议修订 2022年9月8日中共中央办公厅发布）","level":1},{"name":"","text":"第一条 为了全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，健全能上能下的选人用人机制，建设德才兼备、忠诚干净担当的高素质专业化干部队伍，完善从严管理干部队伍制度体系，根据《中国共产党组织工作条例》、《党政领导干部选拔任用工作条例》等党内法规和《中华人民共和国公务员法》等法律，制定本规定。\n第二条 推进领导干部能上能下，坚持以习近平新时代中国特色社会主义思想为指导，贯彻新时代党的建设总要求和新时代党的组织路线，落实新时代好干部标准，坚持党要管党、全面从严治党，坚持实事求是、公道正派，坚持事业为上、人事相宜，坚持依法依规、积极稳妥，着力解决不担当、不作为、乱作为等问题，促使领导干部自觉践行“三严三实”要求，推动形成能者上、优者奖、庸者下、劣者汰的用人导向和从政环境。\n第三条 本规定适用于各级党的机关、人大机关、行政机关、政协机关、监察机关、审判机关、检察机关，以及列入公务员法管理的其他机关和参照公务员法管理的机关（单位）中担任领导职务的干部。国有企业、事业单位中担任领导职务的人员，参照本规定执行。\n第四条 推进领导干部能上能下，重点是解决能下问题。应当结合实际分类施策，严格执行问责、党纪政务处分、组织处理、辞职、职务任期、退休等有关制度规定，畅通干部下的渠道。\n本规定主要规范对不适宜担任现职干部的领导职务所作的组织调整。\n第五条 不适宜担任现职，主要指干部的德、能、勤、绩、廉与所任职务要求不符，不宜在现岗位继续任职。干部具有下列情形之一，被认定为不适宜担任现职，应当及时予以调整：\n（一）政治能力不过硬，缺乏应有的政治判断力、政治领悟力、政治执行力，在不折不扣贯彻落实党中央决策部署、结合实际推动落地见效上存在明显差距的；\n（二）理想信念动摇，在涉及党的领导、中国特色社会主义制度等重大原则问题上立场不坚定、态度暧昧，关键时刻经不住考验的；\n（三）担当和斗争精神不强，在事关党和国家利益、人民群众生命财产安全等紧要关头临阵退缩，在急难险重任务、重大风险考验面前消极逃避或者应对处置不力的；\n（四）政绩观存在偏差，不能坚持以人民为中心的发展思想，不能准确把握新发展阶段、完整准确全面贯彻新发展理念，在构建新发展格局、推动高质量发展上不积极不作为，搞“形象工程”、“政绩工程”乱作为的；\n（五）违背党的民主集中制原则，独断专行或者软弱涣散、自行其是，不执行或者擅自改变组织作出的决定，在领导班子中闹无原则纠纷，或者任人唯亲、拉帮结派，破坏所在地方、单位政治生态的；\n（六）组织观念淡薄，不严格执行重大事项请示报告、个人有关事项报告等制度，无正当理由拒不执行组织的分配、调动、交流等决定的；\n（七）事业心和责任感不强，精神状态差，对职责范围内的事项敷衍塞责，对群众急难愁盼问题不上心、不尽力，工作推拖绕躲、贻误事业发展的；\n（八）领导能力不足，不能有效履行职责、按要求完成目标任务，重大战略、重要改革、重点工作推进不力，所负责的工作较长时间处于落后状态或者出现较大失误的；\n（九）违规决策或者决策论证不充分、不慎重，造成公共资金、国有资产、国有资源损失浪费，生态环境破坏，公共利益损害等后果的；\n（十）作风不严不实，执行中央八项规定精神不严格，形式主义、官僚主义问题突出，造成不良影响的；\n（十一）品行不端，行为失范，违背社会公德、职业道德、家庭美德，造成不良影响的；\n（十二）因存在配偶、子女移居国（境）外，配偶、子女及其配偶经商办企业等情况，按照有关规定需要组织调整的；\n（十三）年度考核被确定为不称职，或者连续两年被确定为基本称职，以及民主测评优秀和称职得票率达不到三分之二，经认定确属不适宜担任现职的；\n（十四）因健康原因无法正常履行工作职责1年以上的；\n（十五）其他不适宜担任现职的情形。\n第六条 党委（党组）及其组织（人事）部门按照干部管理权限，履行组织调整的有关职责。\n各级组织（人事）部门应当把功夫下在平时，深化对干部的日常了解，定期分析研判考核考察、巡视巡察、审计、统计、个人有关事项报告、民主评议、信访举报等有关领导班子和干部队伍情况，动态掌握干部现实表现，对存在苗头性、倾向性或者轻微问题的，及时予以提醒、谈话、函询、批评教育、责令检查或者诫勉，对不适宜担任现职的及时启动调整程序。\n第七条 调整不适宜担任现职干部，一般按照以下程序进行：\n（一）核实认定。组织（人事）部门综合分析各方面情况，对不适宜担任现职的情形进行核实，作出客观评价和准确认定。注重听取群众反映、了解群众口碑，特别是听取工作对象、服务对象等相关人员的意见。必要时可以与干部本人谈话听取说明。\n（二）提出建议。组织（人事）部门根据调查核实和分析研判结果，对不适宜担任现职干部提出调整建议。调整建议包括调整原因、调整方式、安排去向等内容。\n（三）组织决定。党委（党组）召开会议集体研究，作出调整决定。作出决定前，应当听取有关方面意见。涉及干部双重管理的，主管方应当按照有关规定程序征求协管方意见。\n（四）谈话。党委（党组）或者组织（人事）部门负责同志与调整对象进行谈话，宣布组织决定，认真细致做好思想工作。\n（五）按照有关规定履行任免程序。一般在1个月内办理调整干部工资、待遇等方面的手续。对选举和依法任免的干部，按照有关法律法规、章程和规定的程序进行。\n第八条 干部本人对调整决定不服的，可以按照有关规定申请复核或者提出申诉。复核、申诉期间不停止调整决定的执行。\n第九条 对不适宜担任现职干部，应当根据其一贯表现和工作需要，区分不同情形，采取平职调整、转任职级公务员、免职、降职等方式予以调整，符合提前退休条件的可以办理提前退休。\n对非个人原因或者健康原因不能胜任现职岗位的，应当从事业需要和关心爱护干部出发，予以妥善安排。\n调整不适宜担任现职干部，原则上在职数范围内安排。暂时超职数的，应当报经上一级党委组织部门和机构编制部门同意，并明确消化时限，一般应在1年内消化。\n第十条 对被调整的干部，应当跟踪了解其思想动态和工作状况，有针对性地做好教育管理工作。根据工作需要，对认真汲取教训、积极努力工作，德才表现和工作实绩突出且经考察符合任职条件的，可以进一步使用、晋升职级或者提拔职务。\n第十一条 各级组织（人事）部门应当对不适宜担任现职干部的调整原因、安排方式和后续管理等情况进行纪实，每年1月底前向上一级党委组织部门报备上年度相关情况。\n第十二条 健全和落实推进领导干部能上能下工作责任制，党委（党组）应当坚决扛起主体责任，党委（党组）书记应当切实履行第一责任人的责任，组织（人事）部门应当自觉承担具体工作责任，坚持原则、敢于负责，做到真管真严、敢管敢严、长管长严，结合日常干部选拔任用、管理监督、领导班子换届等工作，推进能上能下常态化。\n第十三条 坚持严管和厚爱结合、激励和约束并重，落实“三个区分开来”要求，正确把握政策界限，保护干部干事创业、改革创新的积极性，宽容改革探索、先行先试等工作中的失误。\n第十四条 严明推进领导干部能上能下工作纪律，不得搞好人主义，不得避重就轻、以党纪政务处分规避组织调整或者以组织调整代替党纪政务处分，不得借机打击报复。\n第十五条 积极营造推进领导干部能上能下的制度环境和舆论氛围，加强督促检查，把本规定执行情况纳入党委（党组）履行全面从严治党主体责任、“一报告两评议”、巡视巡察、选人用人专项检查等内容，纳入党委（党组）书记年度考核述职内容。对严重不负责任，或者违反有关工作纪律要求的，应当追究党委（党组）及其组织（人事）部门主要负责人和有关领导成员、直接责任人的责任。\n第十六条 各地区各部门可以根据本规定，结合自身实际，制定实施细则。\n第十七条 本规定由中央组织部负责解释。\n第十八条 本规定自发布之日起施行。\n延伸阅读\n中共中央办公厅印发《推进领导干部能上能下规定》\n推进干部能上能下 激励干部担当作为——中央组织部负责人就修订颁布《推进领导干部能上能下规定》答记者问\n仲祖文：激励干部精神抖擞走好新的赶考之路\n图解 | 领导干部不适宜担任现职的情形有哪些变化\n图解 | 调整不适宜担任现职干部的程序有哪些变化\n党内法规制度","level":0}]},{"id":"r0545","sections":[{"name":"关于全面加强危险化学品安全生产工作的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于全面加强危险化学品安全生产工作的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于全面加强危险化学品安全生产工作的意见》全文如下。\n为深刻吸取一些地区发生的重特大事故教训，举一反三，全面加强危险化学品安全生产工作，有力防范化解系统性安全风险，坚决遏制重特大事故发生，有效维护人民群众生命财产安全，现提出如下意见。","level":0},{"name":"一、总体要求","text":"以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中全会精神，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，坚持总体国家安全观，按照高质量发展要求，以防控系统性安全风险为重点，完善和落实安全生产责任和管理制度，建立安全隐患排查和安全预防控制体系，加强源头治理、综合治理、精准治理，着力解决基础性、源头性、瓶颈性问题，加快实现危险化学品安全生产治理体系和治理能力现代化，全面提升安全发展水平，推动安全生产形势持续稳定好转，为经济社会发展营造安全稳定环境。","level":1},{"name":"二、强化安全风险管控","text":"（一）深入开展安全风险排查。按照《化工园区安全风险排查治理导则（试行）》和《危险化学品企业安全风险隐患排查治理导则》等相关制度规范，全面开展安全风险排查和隐患治理。严格落实地方党委和政府领导责任，结合实际细化排查标准，对危险化学品企业、化工园区或化工集中区（以下简称化工园区），组织实施精准化安全风险排查评估，分类建立完善安全风险数据库和信息管理系统，区分“红、橙、黄、蓝”四级安全风险，突出一、二级重大危险源和有毒有害、易燃易爆化工企业，按照“一企一策”、“一园一策”原则，实施最严格的治理整顿。制定实施方案，深入组织开展危险化学品安全三年提升行动。\n（二）推进产业结构调整。完善和推动落实化工产业转型升级的政策措施。严格落实国家产业结构调整指导目录，及时修订公布淘汰落后安全技术工艺、设备目录，各地区结合实际制定修订并严格落实危险化学品“禁限控”目录，结合深化供给侧结构性改革，依法淘汰不符合安全生产国家标准、行业标准条件的产能，有效防控风险。坚持全国“一盘棋”，严禁已淘汰落后产能异地落户、办厂进园，对违规批建、接收者依法依规追究责任。\n（三）严格标准规范。制定化工园区建设标准、认定条件和管理办法。整合化工、石化和化学制药等安全生产标准，解决标准不一致问题，建立健全危险化学品安全生产标准体系。完善化工和涉及危险化学品的工程设计、施工和验收标准。提高化工和涉及危险化学品的生产装置设计、制造和维护标准。加快制定化工过程安全管理导则和精细化工反应安全风险评估标准等技术规范。鼓励先进化工企业对标国际标准和国外先进标准，制定严于国家标准或行业标准的企业标准。","level":1},{"name":"三、强化全链条安全管理","text":"（四）严格安全准入。各地区要坚持有所为、有所不为，确定化工产业发展定位，建立发展改革、工业和信息化、自然资源、生态环境、住房城乡建设和应急管理等部门参与的化工产业发展规划编制协调沟通机制。新建化工园区由省级政府组织开展安全风险评估、论证并完善和落实管控措施。涉及“两重点一重大”（重点监管的危险化工工艺、重点监管的危险化学品和危险化学品重大危险源）的危险化学品建设项目由设区的市级以上政府相关部门联合建立安全风险防控机制。建设内有化工园区的高新技术产业开发区、经济技术开发区或独立设置化工园区，有关部门应依据上下游产业链完备性、人才基础和管理能力等因素，完善落实安全防控措施。完善并严格落实化学品鉴定评估与登记有关规定，科学准确鉴定评估化学品的物理危险性、毒性，严禁未落实风险防控措施就投入生产。\n（五）加强重点环节安全管控。对现有化工园区全面开展评估和达标认定。对新开发化工工艺进行安全性审查。2020年年底前实现涉及“两重点一重大”的化工装置或储运设施自动化控制系统装备率、重大危险源在线监测监控率均达到100％。加强全国油气管道发展规划与国土空间、交通运输等其他专项规划衔接。督促企业大力推进油气输送管道完整性管理，加快完善油气输送管道地理信息系统，强化油气输送管道高后果区管控。严格落实油气管道法定检验制度，提升油气管道法定检验覆盖率。加强涉及危险化学品的停车场安全管理，纳入信息化监管平台。强化托运、承运、装卸、车辆运行等危险货物运输全链条安全监管。提高危险化学品储罐等贮存设备设计标准。研究建立常压危险货物储罐强制监测制度。严格特大型公路桥梁、特长公路隧道、饮用水源地危险货物运输车辆通行管控。加强港口、机场、铁路站场等危险货物配套存储场所安全管理。加强相关企业及医院、学校、科研机构等单位危险化学品使用安全管理。\n（六）强化废弃危险化学品等危险废物监管。全面开展废弃危险化学品等危险废物（以下简称危险废物）排查，对属性不明的固体废物进行鉴别鉴定，重点整治化工园区、化工企业、危险化学品单位等可能存在的违规堆存、随意倾倒、私自填埋危险废物等问题，确保危险废物贮存、运输、处置安全。加快制定危险废物贮存安全技术标准。建立完善危险废物由产生到处置各环节联单制度。建立部门联动、区域协作、重大案件会商督办制度，形成覆盖危险废物产生、收集、贮存、转移、运输、利用、处置等全过程的监管体系，加大打击故意隐瞒、偷放偷排或违法违规处置危险废物违法犯罪行为力度。加快危险废物综合处置技术装备研发，合理规划布点处置企业，加快处置设施建设，消除处置能力瓶颈。督促企业对重点环保设施和项目组织安全风险评估论证和隐患排查治理。","level":1},{"name":"四、强化企业主体责任落实","text":"（七）强化法治措施。积极研究修改刑法相关条款，严格责任追究。推进制定危险化学品安全和危险货物运输相关法律，修改安全生产法、安全生产许可证条例等，强化法治力度。严格执行执法公示制度、执法全过程记录制度和重大执法决定法制审核制度，细化安全生产行政处罚自由裁量标准，强化精准严格执法。落实职工及家属和社会公众对企业安全生产隐患举报奖励制度，依法严格查处举报案件。\n（八）加大失信约束力度。危险化学品生产贮存企业主要负责人（法定代表人）必须认真履责，并作出安全承诺；因未履行安全生产职责受刑事处罚或撤职处分的，依法对其实施职业禁入；企业管理和技术团队必须具备相应的履职能力，做到责任到人、工作到位，对安全隐患排查治理不力、风险防控措施不落实的，依法依规追究相关责任人责任。对存在以隐蔽、欺骗或阻碍等方式逃避、对抗安全生产监管和环境保护监管，违章指挥、违章作业产生重大安全隐患，违规更改工艺流程，破坏监测监控设施，夹带、谎报、瞒报、匿报危险物品等严重危害人民群众生命财产安全的主观故意行为的单位及主要责任人，依法依规将其纳入信用记录，加强失信惩戒，从严监管。\n（九）强化激励措施。全面推进危险化学品企业安全生产标准化建设，对一、二级标准化企业扩产扩能、进区入园等，在同等条件下分别给予优先考虑并减少检查频次。对国家鼓励发展的危险化学品项目，在投资总额内进口的自用先进危险品检测检验设备按照现行政策规定免征进口关税。落实安全生产专用设备投资抵免企业所得税优惠。提高危险化学品生产贮存企业安全生产费用提取标准。推动危险化学品企业建立安全生产内审机制和承诺制度，完善风险分级管控和隐患排查治理预防机制，并纳入安全生产标准化等级评审条件。","level":1},{"name":"五、强化基础支撑保障","text":"（十）提高科技与信息化水平。强化危险化学品安全研究支撑，加强危险化学品安全相关国家级科技创新平台建设，开展基础性、前瞻性研究。研究建立危险化学品全生命周期信息监管系统，综合利用电子标签、大数据、人工智能等高新技术，对生产、贮存、运输、使用、经营、废弃处置等各环节进行全过程信息化管理和监控，实现危险化学品来源可循、去向可溯、状态可控，做到企业、监管部门、执法部门及应急救援部门之间互联互通。将安全生产行政处罚信息统一纳入监管执法信息化系统，实现信息共享，取代层层备案。加强化工危险工艺本质安全、大型储罐安全保障、化工园区安全环保一体化风险防控等技术及装备研发。推进化工园区安全生产信息化智能化平台建设，实现对园区内企业、重点场所、重大危险源、基础设施实时风险监控预警。加快建成应急管理部门与辖区内化工园区和危险化学品企业联网的远程监控系统。\n（十一）加强专业人才培养。实施安全技能提升行动计划，将化工、危险化学品企业从业人员作为高危行业领域职业技能提升行动的重点群体。危险化学品生产企业主要负责人、分管安全生产负责人必须具有化工类专业大专及以上学历和一定实践经验，专职安全管理人员至少要具备中级及以上化工专业技术职称或化工安全类注册安全工程师资格，新招一线岗位从业人员必须具有化工职业教育背景或普通高中及以上学历并接受危险化学品安全培训，经考核合格后方能上岗。企业通过内部培养或外部聘用形式建立化工专业技术团队。化工重点地区扶持建设一批化工相关职业院校（含技工院校），依托重点化工企业、化工园区或第三方专业机构建立实习实训基地。把化工过程安全管理知识纳入相关高校化工与制药类专业核心课程体系。\n（十二）规范技术服务协作机制。加快培育一批专业能力强、社会信誉好的技术服务龙头企业，引入市场机制，为涉及危险化学品企业提供管理和技术服务。建立专家技术服务规范，分级分类开展精准指导帮扶。安全生产责任保险覆盖所有危险化学品企业。对安全评价、检测检验等中介机构和环境评价文件编制单位出具虚假报告和证明的，依法依规吊销其相关资质或资格；构成犯罪的，依法追究刑事责任。\n（十三）加强危险化学品救援队伍建设。统筹国家综合性消防救援力量、危险化学品专业救援力量，合理规划布局建设立足化工园区、辐射周边、覆盖主要贮存区域的危险化学品应急救援基地。强化长江干线危险化学品应急处置能力建设。加强应急救援装备配备，健全应急救援预案，开展实训演练，提高区域协同救援能力。推进实施危险化学品事故应急指南，指导企业提高应急处置能力。","level":1},{"name":"六、强化安全监管能力","text":"（十四）完善监管体制机制。将涉恐涉爆涉毒危险化学品重大风险纳入国家安全管控范围，健全监管制度，加强重点监督。进一步调整完善危险化学品安全生产监督管理体制。按照“管行业必须管安全、管业务必须管安全、管生产经营必须管安全”和“谁主管谁负责”原则，严格落实相关部门危险化学品各环节安全监管责任，实施全主体、全品种、全链条安全监管。应急管理部门负责危险化学品安全生产监管工作和危险化学品安全监管综合工作；按照《危险化学品安全管理条例》规定，应急管理、交通运输、公安、铁路、民航、生态环境等部门分别承担危险化学品生产、贮存、使用、经营、运输、处置等环节相关安全监管责任；在相关安全监管职责未明确部门的情况下，应急管理部门承担危险化学品安全综合监督管理兜底责任。生态环境部门依法对危险废物的收集、贮存、处置等进行监督管理。应急管理部门和生态环境部门以及其他有关部门建立监管协作和联合执法工作机制，密切协调配合，实现信息及时、充分、有效共享，形成工作合力，共同做好危险化学品安全监管各项工作。完善国务院安全生产委员会工作机制，及时研究解决危险化学品安全突出问题，加强对相关单位履职情况的监督检查和考核通报。\n（十五）健全执法体系。建立健全省、市、县三级安全生产执法体系。省级应急管理部门原则上不设执法队伍，由内设机构承担安全生产监管执法责任，市、县级应急管理部门一般实行“局队合一”体制。危险化学品重点县（市、区、旗）、危险化学品贮存量大的港区，以及各类开发区特别是内设化工园区的开发区，应强化危险化学品安全生产监管职责，落实落细监管执法责任，配齐配强专业执法力量。具体由地方党委和政府研究确定，按程序审批。\n（十六）提升监管效能。严把危险化学品监管执法人员进人关，进一步明确资格标准，严格考试考核，突出专业素质，择优录用；可通过公务员聘任制方式选聘专业人才，到2022年年底具有安全生产相关专业学历和实践经验的执法人员数量不低于在职人员的75％。完善监管执法人员培训制度，入职培训不少于3个月，每年参加为期不少于2周的复训。实行危险化学品重点县（市、区、旗）监管执法人员到国有大型化工企业进行岗位实训。深化“放管服”改革，加强和规范事中事后监管，在对涉及危险化学品企业进行全覆盖监管基础上，实施分级分类动态严格监管，运用“两随机一公开”进行重点抽查、突击检查。严厉打击非法建设生产经营行为。省、市、县级应急管理部门对同一企业确定一个执法主体，避免多层多头重复执法。加强执法监督，既严格执法，又避免简单化、“一刀切”。大力推行“互联网＋监管”、“执法＋专家”模式，及时发现风险隐患，及早预警防范。各地区根据工作需要，面向社会招聘执法辅助人员并健全相关管理制度。\n各地区各有关部门要加强组织领导，认真落实党政同责、一岗双责、齐抓共管、失职追责安全生产责任制，整合一切条件、尽最大努力，加快推进危险化学品安全生产各项工作措施落地见效，重要情况及时向党中央、国务院报告。","level":1}]},{"id":"r0546","sections":[{"name":"关于深化项目评审、人才评价、机构评估改革的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于深化项目评审、人才评价、机构评估改革的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于深化项目评审、人才评价、机构评估改革的意见》全文如下。\n项目评审、人才评价、机构评估（以下简称“三评”）改革是推进科技评价制度改革的重要举措。为全面贯彻党的十九大精神，落实全国科技创新大会部署和《国家创新驱动发展战略纲要》要求，深入推进“三评”改革，进一步优化科研项目评审管理机制、改进科技人才评价方式、完善科研机构评估制度、加强监督评估和科研诚信体系建设，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。全面贯彻党的十九大和十九届二中、三中全会精神，以习近平新时代中国特色社会主义思想为指导，按照党中央、国务院决策部署，坚定实施创新驱动发展战略，深化科技体制改革，以激发科研人员的积极性创造性为核心，以构建科学、规范、高效、诚信的科技评价体系为目标，以改革科研项目评审、人才评价、机构评估为关键，统筹自然科学和哲学社会科学等不同学科门类，推进分类评价制度建设，发挥好评价指挥棒和风向标作用，营造潜心研究、追求卓越、风清气正的科研环境，形成中国特色科技评价体系，为提升我国科技创新能力、加快建设创新型国家和世界科技强国提供有力的制度保障。\n（二）基本原则\n——坚持尊重规律。遵循科技人才发展和科研规律，科学设立评价目标、指标、方法，引导科研人员潜心研究、追求卓越。加强顶层设计，统筹和精简“三评”工作，简化优化流程，为科研人员和机构松绑减负，并形成长效机制。\n——坚持问题导向。聚焦“三评”工作中存在的突出问题，从破除体制机制障碍入手，找准突破口，更加注重质量、贡献、绩效，树立正确评价导向，增强针对性，突出实招硬招，提高改革的含金量和实效性。\n——坚持分类评价。针对自然科学、哲学社会科学、军事科学等不同学科门类特点，建立分类评价指标体系和评价程序规范。基础前沿研究突出原创导向，以同行评议为主；社会公益性研究突出需求导向，以行业用户和社会评价为主；应用技术开发和成果转化评价突出企业主体、市场导向，以用户评价、第三方评价和市场绩效为主。\n——坚持客观公正。客观、真实、准确反映不同评价对象的实际情况，推行同行评价，引入国际评价，进一步提高科技评价活动的公开性和开放性，保证评价工作的独立性和公正性，确保评价结果的科学性和客观性。\n（三）主要目标。“十三五”期间，在优化“三评”工作布局、减少“三评”项目数量、改进评价机制、提高质量效率等方面实现更大突破，基本形成适应创新驱动发展要求、符合科技创新规律、突出质量贡献绩效导向的分类评价体系，科技资源配置更加高效，科研机构和科研人员创新创业潜能活力竞相迸发，科技创新和供给能力大幅提升，科技进步对经济社会发展作出更大贡献。","level":1},{"name":"二、优化科研项目评审管理","text":"（一）完善项目指南编制和发布机制。国家科技计划项目指南编制工作应采取有效方式充分吸收相关部门、行业、地方以及产业界、科技社团、社会公众共同参与。项目指南内容要广泛吸纳各方意见，更好体现国家意志、反映各方需求，有条件的可在网上公开征求意见并进行审核评估，提高指南的科学性。项目体量应大小适中，目标集中明确，合理设置课题及参加单位数量，确保下设各课题任务紧密关联形成有机整体，避免拼凑组团和执行中的碎片化。各类国家科技计划逐步实行年度指南定期发布制度。自然科学类项目指南应关注重大原创性、颠覆性、交叉学科创新等。哲学社会科学类项目指南应注重研究的政治方向、学术创新、社会效益、实践价值等。\n项目指南应根据分类原则明确不同类型项目的组织实施方式。国家科技计划项目一般采取公开竞争的方式择优遴选承担单位。对具有明确国家目标、技术路线清晰、组织程度较高、优势承担单位集中的重大科技项目，可采取定向择优或定向委托等方式确定承担单位；对于企业牵头的技术创新项目，应对企业的资质、技术创新能力和财务情况提出明确要求，鼓励企业共同投入并组织实施。深入实施军民融合发展战略，加快建设军民融合创新体系，推动重大科技项目军地一体论证和实施。\n（二）保证项目评审公开公平公正。建立公正、科学、明确的项目评审工作规则，并在评审前公布。按照不同立项方式，采取相应的评审程序和方法，同一轮次实行同一种评审方法，避免评审结果出现歧义。推行视频评审、电话录音、评审结果反馈、立项公示等措施，实现评审全过程的可申诉、可查询、可追溯。允许项目申报人在评审前提出回避单位及个人。建立项目负责人科研背景核查制度，对立项公示期间存在异议的项目负责人开展科研业绩、经历、诚信情况调查，确保符合项目要求。不同类别国家科技计划应根据实际情况，在项目申报和评审中，综合考虑负责人和团队实际能力以及项目要求，不把发表论文、获得专利、荣誉性头衔、承担项目、获奖等情况作为限制性条件。探索建立对重大原创性、颠覆性、交叉学科创新项目等的非常规评审机制。保密项目评审管理按国家科技保密有关规定执行。\n（三）完善评审专家选取使用。进一步推动建设集中统一、标准规范、安全可靠、开放共享的国家科技专家库，及时补充高层次专家，细化专家领域和研究方向，更好地满足项目评审要求。完善国家科技专家库入库标准和评审专家遴选规范，明确推荐单位在专家推荐和管理等方面的权责，强化推荐单位对专家信息的审核把关责任，建立专家入库信息定期更新机制。根据项目类型特点，合理确定评审专家遴选条件和专家组组成原则，原则上应主要选取活跃在科研一线、真懂此行此项的专家参与评审，充分考虑其专业水平和知识结构。与产业应用结合紧密的项目，还应选取活跃在生产一线的专家参与评审。建立完善评审专家的诚信记录、动态调整、责任追究制度，严格规范专家评审行为。完善专家轮换、随机抽取、回避、公示等相关制度，对公示期间存在异议的专家开展背景经历调查，确保专家选取使用科学、公正。初评环节实施小同行评议，在部分前沿与基础科学等领域逐步按适当比例引入国际同行评议。项目管理专业机构应加强对评审专家名单抽取和保密的管理，进一步推进专家抽取和使用岗位分离。开展会议评审的，原则上应在评审前公布评审专家名单；开展通讯评审的，应在评审结束前对评审专家名单严格保密，有条件的应在评审结束后向社会公布。评审专家要强化学术自律，学术共同体要加强学术监督。\n（四）提高项目评审质量和效率。合理确定专家的评审项目数、总时长等工作量，会议评审前及时组织专家审阅申报材料，确保专家充分了解申报项目情况；合理确定项目汇报和质询答辩时间。项目负责人原则上应亲自汇报答辩，不在项目申报团队内的人员不得参与答辩。进一步优化预算评估工作，只针对拟立项的项目开展预算评估，规范和优化预算评估专家的遴选、评估方法，提高评估质量，及时反馈评估结果。\n（五）严格项目成果评价验收。项目承担单位对本单位科研成果管理负主体责任，要组织对本单位科研人员拟公布的成果进行真实性审查。行业主管部门对所属科研单位的科研成果每年要按一定比例进行抽查。非涉密的国家科技计划项目成果验收前，应在遵守知识产权保护法律法规的前提下，纳入国家科技报告系统，向社会公开，接受监督。项目管理专业机构应按照规定时限和程序组织开展国家科技计划项目验收，严格依据任务书确定的目标、指标和验收工作标准规范进行考核评价。有明确应用要求的，在项目验收后不定期组织对成果应用情况的现场抽查、后评估。\n（六）加强国家科技计划绩效评估。针对科技计划整体情况组织开展绩效评估，重点评估计划目标完成、管理、产出、效果、影响等绩效。绩效评估通过公开竞争等方式择优委托第三方开展，以独立、专业、负责为基本要求，充分发挥第三方评估机构作用，根据需要引入国际评估。加强对第三方评估机构的规范和监督，逐步建立第三方评估机构评估结果负责制和信用评价机制。\n（七）落实国家科技奖励改革方案。改革现行由政府下达指标、科技人员申报、单位推荐的方式，实行由专家学者、组织机构、相关部门提名的制度。提名者承担推荐、答辩、异议答复等责任，对相关材料的真实性和准确性负责。实行定标定额评审制度，自然科学奖、技术发明奖、科技进步奖实行按等级标准提名、独立评审表决的机制，一等奖评审落选项目不再降格参评二等奖。提高奖励工作的公开透明度，向全社会公开评奖规则、流程、指标数量，全程公示自然科学奖、技术发明奖、科技进步奖候选项目及其提名者。","level":1},{"name":"三、改进科技人才评价方式","text":"（一）统筹科技人才计划。加强部门、地方的协调，建立人才项目申报查重及处理机制，防止人才申报违规行为，避免多个类似人才项目同时支持同一人才。指导部门、地方针对不同支持对象科学设置科技人才计划，优化人才计划结构。\n（二）科学设立人才评价指标。突出品德、能力、业绩导向，克服唯论文、唯职称、唯学历、唯奖项倾向，推行代表作评价制度，注重标志性成果的质量、贡献、影响。把学科领域活跃度和影响力、重要学术组织或期刊任职、研发成果原创性、成果转化效益、科技服务满意度等作为重要评价指标。在对社会公益性研究、应用技术开发等类型科研人才的评价中，SCI（科学引文索引）和核心期刊论文发表数量、论文引用榜单和影响因子排名等仅作为评价参考。注重个人评价与团队评价相结合，尊重和认可团队所有参与者的实际贡献。引进海外人才要加强对其海外教育和科研经历的调查验证，不把教育、工作背景简单等同于科研水平。注重发挥同行评议机制在人才评价过程中的作用。探索对特殊人才采取特殊评价标准。对承担国防重大工程任务的人才可采用针对性评价措施，对国防科技涉密领域人才评价开辟特殊通道。\n（三）树立正确的人才评价使用导向。坚持正确价值导向，不把人才荣誉性称号作为承担各类国家科技计划项目、获得国家科技奖励、职称评定、岗位聘用、薪酬待遇确定的限制性条件，使人才称号回归学术性、荣誉性本质，避免与物质利益简单、直接挂钩。鼓励人才合理流动，引导人才良性竞争和有序流动，探索人才共享机制。中西部、东北老工业基地及欠发达地区的科研人员因政策倾斜因素获得的国家级人才称号、人才项目等支持，在支持周期内原则上不得跟随人员向东部、发达地区流转。合理发挥市场机制作用，逐步建立高层次人才流动的培养补偿机制。\n（四）强化用人单位人才评价主体地位。坚持评用结合，支持用人单位健全科技人才评价组织管理，根据单位实际建立人才分类评价指标体系，突出岗位履职评价，完善内部监督机制，使人才发展与单位使命更好协调统一。按照深化职称制度改革方向要求，分类完善职称评价标准，不将论文、外语、专利、计算机水平作为应用型人才、基层一线人才职称评审的限制性条件。落实职称评审权限下放改革措施，支持符合条件的高校、科研院所、医院、大型企业等单位自主开展职称评审。选择部分国家临床医学研究中心试点开展临床医生科研评价改革工作。不简单以学术头衔、人才称号确定薪酬待遇、配置学术资源。\n（五）加大对优秀人才和团队的稳定支持力度。国家实验室等的全职科研人员及团队不参与申请除国家人才计划之外的竞争性科研经费，由中央财政给予中长期目标导向的持续稳定经费支持。推动中央部委所属高校、科研院所完善基本科研业务费的内部管理机制，切实加强对青年科研人员的倾斜支持。","level":1},{"name":"四、完善科研机构评估制度","text":"（一）实行章程管理。推动中央级科研事业单位制定实施章程，确立章程在单位管理运行中的基础性制度地位，实现“一院（所）一章程”和依章程管理。章程要明确规定单位的宗旨目标、功能定位、业务范围、领导体制、运行管理机制等，确保机构运行各项事务有章可循。\n（二）落实法人自主权。中央级科研事业单位主管部门要加快推进政事分开、管办分离，赋予科研事业单位充分自主权，对章程明确赋予科研事业单位管理权限的事务，由单位自主独立决策、科学有效管理，少干预或不干预。坚持权责一致原则，细化自主权的行使规则与监督制度，明确重大管理决策事项的基本规则、决策程序、监督机制、责任机制，形成完善的内控机制，保障科研事业单位依法合规管理运行。切实发挥单位党委（党组）把方向、管大局、保落实的重要作用，坚决防止党的领导弱化、党的建设缺失。\n（三）建立中长期绩效评价制度。根据科研机构从事的科研活动类型，分类建立相应的评价指标和评价方式，避免简单以高层次人才数量评价科研事业单位。建立综合评价与年度抽查评价相结合的中央级科研事业单位绩效评价长效机制。以5年为评价周期，对科研事业单位开展综合评价，涵盖职责定位、科技产出、创新效益等方面。5年期间，每年按一定比例，聚焦年度绩效完成情况等重点方面，开展年度抽查评价。加强绩效评价结果与科研管理机制的衔接，充分发挥绩效评价的激励约束作用，在科技创新政策规划制定、财政拨款、国家科技计划项目承担、国家级科技人才推荐、国家科技创新基地建设、学科专业设置、研究生和博士后招收、科研事业单位领导人员考核评价、科研事业单位人事管理、绩效工资总量核定等工作中，将绩效评价结果作为重要依据。按照程序办理科研事业单位编制调整事项时，应参考绩效评价结果。\n（四）完善国家科技创新基地评价考核体系。根据优化整合后的各类国家科技创新基地功能定位、任务目标、运行机制等不同特点，确定合理的评价方式和标准。科学与工程研究类基地重点评价原始创新能力、国际科学前沿竞争力、满足国家重大需求的能力；技术创新与成果转化类基地重点评价行业共性关键技术研发、成果转化应用能力、对行业技术进步的带动作用；基础支撑与条件保障类基地重点评价科技创新条件资源支撑保障和服务能力。对各类基地的评价要有利于人才队伍建设、能力提升和可持续发展。建立与评价结果挂钩的动态管理机制，坚持优胜劣汰、有进有出，实现国家科技创新基地建设运行的良性循环。","level":1},{"name":"五、加强监督评估和科研诚信体系建设","text":"（一）建立覆盖“三评”全过程的监督评估机制。将监督和评估嵌入“三评”活动事前、事中、事后全过程，确保科学、规范、高效。事前，实行诚信承诺制度，申报人员、评审专家、工作人员均应签订诚信承诺书，明确行为规范并划定负面行为的底线。事中，实行重点监督和随机抽查相结合，强化重点环节监督，加强对各类主体履职尽责和任务完成情况的监督评估。事后，强化绩效评估和动态调整，按照合同（委托书、协议书）约定开展绩效评估，评估结果作为对相关主体今后监督管理和动态调整的重要参考。建立学术期刊预警监测制度，定期发布学术期刊预警名单和黑名单。加强与纪检监察机关等的信息沟通，自觉接受监督。\n（二）加强科研诚信建设。对科研不端行为零容忍，完善调查核实、公开公示、惩戒处理等制度。建设完善严重失信行为记录信息系统，对纳入系统的严重失信行为责任主体实行“一票否决”，一定期限、一定范围内禁止其获得政府奖励和申报政府科技项目等。推进科研信用与其他社会领域诚信信息共享，实施联合惩戒。逐步建立科研领域守信激励机制。将诚信监管关口前移，推动高校、科研院所、医院等单位建立完善学术管理制度，对科研人员学术成长轨迹和学术水平进行跟踪评价，加强对科研人员和青年学生的科研诚信教育，引导其树立正确的科研价值观，潜心科研、淡泊名利。强化导师对学生发表论文的主要内容和研究数据的真实性及实验的可重复性等的审核把关。引导学术共同体建立符合本领域特点的科研诚信规范。","level":1},{"name":"六、加强组织实施，确保政策措施落地见效","text":"（一）加强组织领导。国家科技体制改革和创新体系建设领导小组负责“三评”改革工作的组织领导和统筹协调。各有关部门要根据职责分工，细化任务举措，加强协调配合，抓好本领域“三评”改革的组织实施。各地区要结合实际制定具体方案，推进本地区“三评”改革工作。\n（二）强化责任担当。各相关评价主体要强化责任意识，敢于担当，切实推进“三评”改革政策措施落实落地。各有关部门要深化“放管服”改革，进一步减少“三评”项目数量，加强监管，优化服务。各项目管理专业机构要切实履行监督管理职责，各法人单位、学（协）会要完善内部管理，广大科研人员要强化学术自律。各方面要齐心协力，共同营造良好科研环境。\n（三）加大推进力度。加强政府部门、用人单位、学术共同体、第三方评估机构等各类评价主体间的相互配合和协同联动，强化“三评”之间的统筹协调。强化政策解读和宣传引导，加强对科研单位干部教育培训，提升科研管理水平，让广大科研人员知晓、掌握、用好改革政策。持续跟踪调研，加强总结评估，及时推广先进经验，发现和解决问题。加强督查督办，推动“三评”改革政策措施落实和动态完善，形成长效机制。\n（四）开展试点示范。对一些关联度高、探索性强、暂时不具备全面推行条件的改革举措，可以结合实际情况选择部分地方和单位先期开展试点。鼓励试点地方和单位大胆探索实践，发挥示范突破和带动作用。对基层因地制宜的改革要探索建立容错纠错机制，激发改革动力，保护改革积极性。","level":1}]},{"id":"r0547","sections":[{"name":"中共中央办公厅 国务院办公厅关于持续推进城市更新行动的意见","text":"中共中央办公厅 国务院办公厅关于持续推进城市更新行动的意见\n（2025年5月2日）","level":1},{"name":"","text":"实施城市更新行动，是推动城市高质量发展、不断满足人民美好生活需要的重要举措。为持续推进城市更新行动，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，全面贯彻习近平总书记关于城市工作的重要论述，坚持稳中求进工作总基调，转变城市开发建设方式，建立可持续的城市更新模式和政策法规，大力实施城市更新，促进城市结构优化、功能完善、文脉赓续、品质提升，打造宜居、韧性、智慧城市。\n工作中要做到：坚持以人民为中心，全面践行人民城市理念，建设好房子、好小区、好社区、好城区；坚持系统观念，尊重城市发展规律，树立全周期管理意识，不断增强城市的系统性、整体性、协调性；坚持规划引领，发挥发展规划战略导向作用，强化国土空间规划基础作用，增强专项规划实施支撑作用；坚持统筹发展和安全，防范应对城市运行中的风险挑战，全面提高城市韧性；坚持保护第一、应保尽保、以用促保，在城市更新全过程、各环节加强城市文化遗产保护；坚持实事求是、因地制宜，尽力而为、量力而行，不搞劳民伤财的“面子工程”、“形象工程”。\n主要目标是：到2030年，城市更新行动实施取得重要进展，城市更新体制机制不断完善，城市开发建设方式转型初见成效，安全发展基础更加牢固，服务效能不断提高，人居环境明显改善，经济业态更加丰富，文化遗产有效保护，风貌特色更加彰显，城市成为人民群众高品质生活的空间。","level":1},{"name":"二、主要任务","text":"（一）加强既有建筑改造利用。稳妥推进危险住房改造，加快拆除改造D级危险住房，通过加固、改建、重建等多种方式，积极稳妥实施国有土地上C级危险住房和国有企事业单位非成套住房改造。分类分批对存在抗震安全隐患且具备加固价值的城镇房屋进行抗震加固。涉及不可移动文物、历史建筑等保护对象的，按照相关法律法规予以维护和使用，“一屋一策”提出改造方案，严禁以危险住房名义违法违规拆除改造历史文化街区、传统村落、文物、历史建筑。持续推进既有居住建筑和公共建筑节能改造，加强建筑保温材料管理，鼓励居民开展城镇住房室内装修。加强老旧厂房、低效楼宇、传统商业设施等存量房屋改造利用，推动建筑功能转换和混合利用，根据建筑主导功能依法依规合理转换土地用途。\n（二）推进城镇老旧小区整治改造。更新改造小区燃气等老化管线管道，整治楼栋内人行走道、排风烟道、通风井道等，全力消除安全隐患，支持有条件的楼栋加装电梯。整治小区及周边环境，完善小区停车、充电、消防、通信等配套基础设施，增设助餐、家政等公共服务设施。加强老旧小区改造质量安全监管，压实各参建单位责任。结合改造同步完善小区长效管理机制，注重引导居民参与和监督，共同维护改造成果。统筹实施老旧小区、危险住房改造，在挖掘文化遗产价值、保护传统风貌的基础上制定综合性保护、修缮、改造方案，持续提升老旧小区居住环境、设施条件、服务功能和文化价值。\n（三）开展完整社区建设。完善社区基本公共服务设施、便民商业服务设施、公共活动场地等，建设安全健康、设施完善、管理有序的完整社区，构建城市一刻钟便民生活圈。开展城市社区嵌入式服务设施建设，因地制宜补齐公共服务设施短板，优化综合服务设施布局。引导居民、规划师、设计师等参与社区建设。\n（四）推进老旧街区、老旧厂区、城中村等更新改造。推动老旧街区功能转换、业态升级、活力提升，因地制宜打造一批活力街区。改造提升商业步行街和旧商业街区，完善配套设施，优化交通组织，提升公共空间品质，丰富商业业态，创新消费场景，推动文旅产业赋能城市更新。鼓励以市场化方式推动老旧厂区更新改造，加强工业遗产保护利用，盘活利用闲置低效厂区、厂房和设施，植入新业态新功能。积极推进城中村改造，做好历史文化风貌保护前期工作，不搞大拆大建，“一村一策”采取拆除新建、整治提升、拆整结合等方式实施改造，切实消除安全风险隐患，改善居住条件和生活环境。加快实施群众改造意愿强烈、城市资金能平衡、征收补偿方案成熟的城中村改造项目。推动老旧火车站与周边老旧街区统筹实施更新改造。\n（五）完善城市功能。建立健全多层级、全覆盖的公共服务网络，充分利用存量闲置房屋和低效用地，优先补齐民生领域公共服务设施短板，合理满足人民群众生活需求。积极稳步推进“平急两用”公共基础设施建设。完善城市医疗应急服务体系，加强临时安置、应急物资保障。推进适老化、适儿化改造，加快公共场所无障碍环境建设改造。增加普惠托育服务供给，发展兜底性、普惠型、多样化养老服务。因地制宜建设改造群众身边的全民健身场地设施。推动消费基础设施改造升级。积极拓展城市公共空间，科学布局新型公共文化空间。\n（六）加强城市基础设施建设改造。全面排查城市基础设施风险隐患。推进地下空间统筹开发和综合利用。加快城市燃气、供水、排水、污水、供热等地下管线管网和地下综合管廊建设改造，完善建设运维长效管理制度。推动城市供水设施改造提标，加强城市生活污水收集、处理和再生利用及污泥处理处置设施建设改造，加快建立污水处理厂网一体建设运维机制。统筹城市防洪和内涝治理，建立健全城区水系、排水管网与周边江河湖海、水库等联排联调运行管理模式，加快排水防涝设施建设改造，构建完善的城市防洪排涝体系，提升应急处置能力。推动生活垃圾处理设施改造升级。加强公共消防设施建设，适度超前建设防灾工程。完善城市交通基础设施，发展快速干线交通、生活性集散交通和绿色慢行交通，加快建设停车设施。优化城市货运网络规划设计，健全分级配送设施体系。推进新型城市基础设施建设，深化建筑信息模型（BIM）技术应用，实施城市基础设施生命线安全工程建设。\n（七）修复城市生态系统。坚持治山、治水、治城一体推进，建设连续完整的城市生态基础设施体系。加快修复受损山体和采煤沉陷区，消除安全隐患。推进海绵城市建设，保护修复城市湿地，巩固城市黑臭水体治理成效，推进城市水土保持和生态清洁小流域建设。加强建设用地土壤污染风险管控和修复，确保污染地块安全再利用。持续推进城市绿环绿廊绿楔绿道建设，提高乡土植物应用水平，保护城市生物多样性，增加群众身边的社区公园和口袋公园，推动公园绿地开放共享。\n（八）保护传承城市历史文化。衔接全国文物普查，扎实开展城市文化遗产资源调查。落实“老城不能再拆”的要求，全面调查老城及其历史文化街区，摸清城镇老旧小区、老旧街区、老旧厂区文化遗产资源底数，划定最严格的保护范围。开展文化遗产影响评价，建立健全“先调查后建设”、“先考古后出让”的保护前置机制。加强老旧房屋拆除管理，不随意拆除具有保护价值的老建筑、古民居，禁止拆真建假。建立以居民为主体的保护实施机制，推进历史文化街区修复和不可移动文物、历史建筑修缮，探索合理利用文化遗产的方式路径。保护具有重要历史文化价值、体现中华历史文脉的地名，稳妥清理不规范地名。加强城市更新重点地区、重要地段风貌管控，严格管理超大体量公共建筑、超高层建筑。","level":1},{"name":"三、加强支撑保障","text":"（一）建立健全城市更新实施机制。创新完善以需求为导向、以项目为牵引的城市更新体制机制。全面开展城市体检评估，建立发现问题、解决问题、评估效果、巩固提升的工作路径。依据国土空间规划，结合城市体检评估结果，制定实施城市更新专项规划，确定城市更新行动目标、重点任务、建设项目和实施时序，建立完善“专项规划－片区策划－项目实施方案”的规划实施体系。强化城市设计对城市更新项目实施的引导作用，明确房屋、小区、社区、城区、城市等不同尺度的设计管理要求。不断完善适应城市更新的工程项目建设实施管理制度。\n（二）完善用地政策。坚持“项目跟着规划走、土地要素跟着项目走”，加强用地保障，建立健全覆盖全域全类型、统一衔接的国土空间用途管制和规划许可制度，统筹好新增和存量建设用地，涉及国土空间规划调整的，按程序依法办理。推动土地混合开发利用和用途依法合理转换，明确用途转换和兼容使用的正面清单、负面清单和管控要求，完善用途转换过渡期政策。盘活利用存量低效用地，完善闲置土地使用权收回机制，优化零星用地集中改造、容积率转移或奖励政策。支持利用存量低效用地建设保障性住房、发展产业、完善公共服务设施。除国有土地使用权出让合同约定或者划拨用地决定书规定由政府收回土地使用权以及法律、行政法规禁止擅自转让的情形外，鼓励国有土地使用权人按程序自行或以转让、入股、联营等方式更新改造低效用地。优化地价计收规则。推进建设用地使用权在土地的地表、地上或者地下分别设立。完善城市更新相关的不动产登记制度。\n（三）建立房屋使用全生命周期安全管理制度。落实房屋使用安全主体责任和监管责任，加强房屋安全日常巡查和安全体检，及时发现和处置安全隐患。探索以市场化手段创新房屋质量安全保障机制。完善住宅专项维修资金政策，推动建立完善既有房屋安全管理公共资金筹集、管理、使用模式。\n（四）健全多元化投融资方式。加大中央预算内投资等支持力度，通过超长期特别国债对符合条件的项目给予支持。中央财政要支持实施城市更新行动。地方政府要加大财政投入，推进相关资金整合和统筹使用，在债务风险可控前提下，通过发行地方政府专项债券对符合条件的城市更新项目予以支持，严禁违法违规举债融资。落实城市更新相关税费减免政策。鼓励各类金融机构在依法合规、风险可控、商业可持续的前提下积极参与城市更新，强化信贷支持。完善市场化投融资模式，吸引社会资本参与城市更新，推动符合条件的项目发行基础设施领域不动产投资信托基金（REITs）、资产证券化产品、公司信用类债券等。\n（五）建立政府引导、市场运作、公众参与的城市更新可持续模式。充分发挥街道社区作用，调动人民群众参与城市更新积极性。开展城市管理进社区工作。鼓励产权所有人自主更新，支持企业盘活闲置低效存量资产，更好发挥国有资本带动作用。引导经营主体参与，支持多领域专业力量和服务机构参与城市更新，健全专家参与公共决策制度。建立健全适应城市更新的建设、运营、治理体制机制。加强城市更新社会风险评估、矛盾化解处置机制建设。\n（六）健全法规标准。加快推进城市更新相关立法工作，健全城市规划建设运营治理和房屋管理法律法规。完善适用于城市更新的技术标准，制定修订分类适用的消防、配套公共设施等标准。加强城市更新科技创新能力建设，大力研发新技术、新工艺、新材料，加快科技成果推广应用。","level":1},{"name":"四、强化组织实施","text":"在党中央集中统一领导下，各地区各有关部门要结合实际抓好本意见贯彻落实。省级党委和政府要确定本地区城市更新行动的目标任务，做好上下衔接。城市党委和政府要切实履行责任，构建市级统筹、部门联动、分级落实的工作格局，加强政策统筹，强化资金等保障，稳妥有序实施城市更新行动，力戒形式主义，杜绝搞“花架子”。住房城乡建设部要发挥牵头作用，会同相关部门加强统筹指导和协调支持，完善制度政策。支持地方因地制宜进行探索创新，建立健全可持续的城市更新机制。","level":1}]},{"id":"r0548","sections":[{"name":"关于加快推进失信被执行人信用监督、警示和惩戒机制建设的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于加快推进失信被执行人信用监督、警示和惩戒机制建设的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于加快推进失信被执行人信用监督、警示和惩戒机制建设的意见》全文如下。\n人民法院通过司法程序认定的被执行人失信信息是社会信用信息重要组成部分。对失信被执行人进行信用监督、警示和惩戒，有利于促进被执行人自觉履行生效法律文书确定的义务，提高司法公信力，推进社会信用体系建设。为加快推进失信被执行人信用监督、警示和惩戒机制建设，现提出以下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。全面贯彻落实党的十八大和十八届三中、四中、五中全会精神，深入学习贯彻习近平总书记系列重要讲话精神，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，牢固树立新发展理念，按照培育和践行社会主义核心价值观、推进信用信息共享、健全激励惩戒机制、提高全社会诚信水平的有关要求，进一步提高人民法院执行工作能力，加快推进失信被执行人跨部门协同监管和联合惩戒机制建设，构建一处失信、处处受限的信用监督、警示和惩戒工作体制机制，维护司法权威，提高司法公信力，营造向上向善、诚信互助的社会风尚。\n（二）基本原则\n——坚持合法性。对失信被执行人信用监督、警示和惩戒要严格遵照法律法规实施。\n——坚持信息共享。破除各地区各部门之间以及国家机关与人民团体、社会组织、企事业单位之间的信用信息壁垒，依法推进信用信息互联互通和交换共享。\n——坚持联合惩戒。各地区各部门要各司其职，相互配合，形成合力，构建一处失信、处处受限的信用监督、警示和惩戒体系。\n——坚持政府主导和社会联动。各级政府要发挥主导作用，同时发挥各方面力量，促进全社会共同参与、共同治理，实现政府主导与社会联动的有效融合。\n（三）建设目标。到2018年，人民法院执行工作能力显著增强，执行联动体制便捷、顺畅、高效运行。失信被执行人名单制度更加科学、完善，失信被执行人界定与信息管理、推送、公开、屏蔽、撤销等合法高效、准确及时。失信被执行人信息与各类信用信息互联共享，以联合惩戒为核心的失信被执行人信用监督、警示和惩戒机制高效运行。有效促进被执行人自觉履行人民法院生效裁判确定的义务，执行难问题基本解决，司法公信力大幅提升，诚实守信成为全社会共同的价值追求和行为准则。","level":1},{"name":"二、加强联合惩戒","text":"（一）从事特定行业或项目限制\n1.设立金融类公司限制。将失信被执行人相关信息作为设立银行业金融机构及其分支机构，以及参股、收购银行业金融机构审批的审慎性参考，作为设立证券公司、基金管理公司、期货公司审批，私募投资基金管理人登记的审慎性参考。限制失信被执行人设立融资性担保公司、保险公司。\n2.发行债券限制。对失信被执行人在银行间市场发行债券从严审核，限制失信被执行人公开发行公司债券。\n3.合格投资者额度限制。在合格境外机构投资者、合格境内机构投资者额度审批和管理中，将失信状况作为审慎性参考依据。\n4.股权激励限制。失信被执行人为境内国有控股上市公司的，协助中止其股权激励计划；对失信被执行人为境内国有控股上市公司股权激励对象的，协助终止其行权资格。\n5.股票发行或挂牌转让限制。将失信被执行人信息作为股票发行和在全国中小企业股份转让系统挂牌公开转让股票审核的参考。\n6.设立社会组织限制。将失信被执行人信息作为发起设立社会组织审批登记的参考，限制失信被执行人发起设立社会组织。\n7.参与政府投资项目或主要使用财政性资金项目限制。协助人民法院查询政府采购项目信息；依法限制失信被执行人作为供应商参加政府采购活动；依法限制失信被执行人参与政府投资项目或主要使用财政性资金项目。\n（二）政府支持或补贴限制\n1.获取政府补贴限制。限制失信被执行人申请政府补贴资金和社会保障资金支持。\n2.获得政策支持限制。在审批投资、进出口、科技等政策支持的申请时，查询相关机构及其法定代表人、实际控制人、董事、监事、高级管理人员是否为失信被执行人，作为其享受该政策的审慎性参考。\n（三）任职资格限制\n1.担任国企高管限制。失信被执行人为个人的，限制其担任国有独资公司、国有资本控股公司董事、监事、高级管理人员，以及国有资本参股公司国有股权方派出或推荐的董事、监事、高级管理人员；已担任相关职务的，按照有关程序依法免去其职务。\n2.担任事业单位法定代表人限制。失信被执行人为个人的，限制其登记为事业单位法定代表人。\n3.担任金融机构高管限制。限制失信被执行人担任银行业金融机构、证券公司、基金管理公司、期货公司、保险公司、融资性担保公司的董事、监事、高级管理人员。\n4.担任社会组织负责人限制。失信被执行人为个人的，限制其登记或备案为社会组织负责人。\n5.招录（聘）为公务人员限制。限制招录（聘）失信被执行人为公务员或事业单位工作人员，在职公务员或事业单位工作人员被确定为失信被执行人的，失信情况应作为其评先、评优、晋职晋级的参考。\n6.入党或党员的特别限制。将严格遵守法律、履行生效法律文书确定的义务情况，作为申请加入中国共产党、预备党员转为正式党员以及党员评先、评优、晋职晋级的重要参考。\n7.担任党代表、人大代表和政协委员限制。失信被执行人为个人的，不作为组织推荐的各级党代会代表、各级人大代表和政协委员候选人。\n8.入伍服役限制。失信被执行人为个人的，将其失信情况作为入伍服役和现役、预备役军官评先、评优、晋职晋级的重要参考。\n（四）准入资格限制\n1.海关认证限制。限制失信被执行人成为海关认证企业；在失信被执行人办理通关业务时，实施严密监管，加强单证审核或布控查验。\n2.从事药品、食品等行业限制。对失信被执行人从事药品、食品安全行业从严审批；限制失信被执行人从事危险化学品生产经营储存、烟花爆竹生产经营、矿山生产和安全评价、认证、检测、检验等行业；限制失信被执行人担任上述行业单位主要负责人及董事、监事、高级管理人员，已担任相关职务的，按规定程序要求予以变更。\n3.房地产、建筑企业资质限制。将房地产、建筑企业不依法履行生效法律文书确定的义务情况，记入房地产和建筑市场信用档案，向社会披露有关信息，对其企业资质作出限制。\n（五）荣誉和授信限制\n1.授予文明城市、文明村镇、文明单位、文明家庭、道德模范、慈善类奖项限制。将履行人民法院生效裁判情况作为评选文明村镇、文明单位、文明家庭的前置条件，作为文明城市测评的指标内容。有关机构及其法定代表人、实际控制人、董事、监事、高级管理人员为失信被执行人的，不得参加文明单位、慈善类奖项评选，列入失信被执行人后取得的文明单位荣誉称号、慈善类奖项予以撤销。失信被执行人为个人的，不得参加道德模范、慈善类奖项评选，列入失信被执行人后获得的道德模范荣誉称号、慈善类奖项予以撤销。\n2.律师和律师事务所荣誉限制。协助人民法院查询失信被执行人的律师身份信息、律师事务所登记信息；失信被执行人为律师、律师事务所的，在一定期限内限制其参与评先、评优。\n3.授信限制。银行业金融机构在融资授信时要查询拟授信对象及其法定代表人、主要负责人、实际控制人、董事、监事、高级管理人员是否为失信被执行人，对拟授信对象为失信被执行人的，要从严审核。\n（六）特殊市场交易限制\n1.从事不动产交易、国有资产交易限制。协助人民法院查询不动产登记情况，限制失信被执行人及失信被执行人的法定代表人、主要负责人、实际控制人、影响债务履行的直接责任人员购买或取得房产、土地使用权等不动产；限制失信被执行人从事土地、矿产等不动产资源开发利用，参与国有企业资产、国家资产等国有产权交易。\n2.使用国有林地限制。限制失信被执行人申报使用国有林地项目；限制其申报重点林业建设项目。\n3.使用草原限制。限制失信被执行人申报草原征占用项目；限制其申报承担国家草原保护建设项目。\n4.其他国有自然资源利用限制。限制失信被执行人申报水流、海域、无居民海岛、山岭、荒地、滩涂等国有自然资源利用项目以及重点自然资源保护建设项目。\n（七）限制高消费及有关消费\n1.乘坐火车、飞机限制。限制失信被执行人及失信被执行人的法定代表人、主要负责人、实际控制人、影响债务履行的直接责任人员乘坐列车软卧、G字头动车组列车全部座位、其他动车组列车一等以上座位、民航飞机等非生活和工作必需的消费行为。\n2.住宿宾馆饭店限制。限制失信被执行人及失信被执行人的法定代表人、主要负责人、实际控制人、影响债务履行的直接责任人员住宿星级以上宾馆饭店、国家一级以上酒店及其他高消费住宿场所；限制其在夜总会、高尔夫球场等高消费场所消费。\n3.高消费旅游限制。限制失信被执行人及失信被执行人的法定代表人、主要负责人、实际控制人、影响债务履行的直接责任人员参加旅行社组织的团队出境旅游，以及享受旅行社提供的与出境旅游相关的其他服务；对失信被执行人在获得旅游等级评定的度假区内或旅游企业内消费实行限额控制。\n4.子女就读高收费学校限制。限制失信被执行人及失信被执行人的法定代表人、主要负责人、实际控制人、影响债务履行的直接责任人员以其财产支付子女入学就读高收费私立学校。\n5.购买具有现金价值保险限制。限制失信被执行人及失信被执行人的法定代表人、主要负责人、实际控制人、影响债务履行的直接责任人员支付高额保费购买具有现金价值的保险产品。\n6.新建、扩建、高档装修房屋等限制。限制失信被执行人及失信被执行人的法定代表人、主要负责人、实际控制人、影响债务履行的直接责任人员新建、扩建、高档装修房屋，购买非经营必需车辆等非生活和工作必需的消费行为。\n（八）协助查询、控制及出境限制\n协助人民法院依法查询失信被执行人身份、出入境证件信息及车辆信息，协助查封、扣押失信被执行人名下的车辆，协助查找、控制下落不明的失信被执行人，限制失信被执行人出境。\n（九）加强日常监管检查\n将失信被执行人和以失信被执行人为法定代表人、主要负责人、实际控制人、董事、监事、高级管理人员的单位，作为重点监管对象，加大日常监管力度，提高随机抽查的比例和频次，并可依据相关法律法规对其采取行政监管措施。\n（十）加大刑事惩戒力度\n公安、检察机关和人民法院对拒不执行生效判决、裁定以及其他妨碍执行构成犯罪的行为，要及时依法侦查、提起公诉和审判。\n（十一）鼓励其他方面限制\n鼓励各级党政机关、人民团体、社会组织、企事业单位使用失信被执行人名单信息，结合各自主管领域、业务范围、经营活动，实施对失信被执行人的信用监督、警示和惩戒。","level":1},{"name":"三、加强信息公开与共享","text":"（一）失信信息公开\n人民法院要及时准确更新失信被执行人名单信息，并通过全国法院失信被执行人名单信息公布与查询平台、有关网站、移动客户端、户外媒体等多种形式向社会公开，供公众免费查询；根据联合惩戒工作需要，人民法院可以向有关单位推送名单信息，供其结合自身工作依法使用名单信息。对依法不宜公开失信信息的被执行人，人民法院要通报其所在单位，由其所在单位依纪依法处理。\n（二）纳入政府政务公开\n各地区各部门要按照中共中央办公厅、国务院办公厅印发的《关于全面推进政务公开工作的意见》的有关要求，将失信被执行人信用监督、警示和惩戒信息列入政务公开事项，对失信被执行人信用监督、警示和惩戒要依据部门权力清单、责任清单和负面清单依法开展。\n（三）信用信息共享\n各地区各部门之间要进一步打破信息壁垒，实现信息共享，通过全国信用信息共享平台，加快推进失信被执行人信息与公安、民政、人力资源社会保障、国土资源、住房城乡建设、财政、金融、税务、工商、安全监管、证券、科技等部门信用信息资源共享，推进失信被执行人信息与有关人民团体、社会组织、企事业单位信用信息资源共享。\n（四）共享体制机制建设\n加快推进失信被执行人信用信息共享体制机制建设，建立健全政府与征信机构、信用评级机构、金融机构、社会组织之间的信用信息共享机制。建立社会信用档案制度，将失信被执行人信息作为重要信用评价指标纳入社会信用评价体系。","level":1},{"name":"四、完善相关制度机制","text":"（一）进一步提高执行查控工作能力\n1.加快推进网络执行查控系统建设。加大信息化手段在执行工作中的应用，整合完善现有法院信息化系统，实现网络化查找被执行人和控制财产的执行工作机制。要通过政务网、专网等实现人民法院执行查控网络与公安、民政、人力资源社会保障、国土资源、住房城乡建设、工商、交通运输、农业、人民银行、银行监管、证券监管、保险监管、外汇管理等政府部门，及各金融机构、银联、互联网企业等企事业单位之间的网络连接，建成覆盖全国地域及土地、房产、存款、金融理财产品、证券、股权、车辆等主要财产形式的网络化、自动化执行查控体系，实现全国四级法院互联互通、全面应用。\n2.拓展执行查控措施。人民法院要进一步拓展对被告和被执行人财产的查控手段和措施。研究制定被执行人财产报告制度、律师调查被执行人财产制度、公告悬赏制度、审计调查制度等财产查控制度。\n3.完善远程执行指挥系统。最高人民法院和各高级、中级人民法院以及有条件的基层人民法院要建立执行指挥中心和远程指挥系统，实现四级法院执行指挥系统联网运行。建立上下一体、内外联动、规范高效、反应快捷的执行指挥工作体制机制。建立四级法院统一的网络化执行办案平台、公开平台和案件流程节点管理平台。\n（二）进一步完善失信被执行人名单制度\n1.完善名单纳入制度。各级人民法院要根据执行案件的办理权限，严格按照法定条件和程序决定是否将被执行人纳入失信名单。\n2.确保名单信息准确规范。人民法院要建立严格的操作规程和审核纠错机制，确保失信被执行人名单信息准确规范。\n3.风险提示与救济。在将被执行人纳入失信名单前，人民法院应当向被执行人发出风险提示通知。被执行人认为将其纳入失信名单错误的，可以自收到决定之日起10日内向作出决定的人民法院申请纠正，人民法院应当自收到申请之日起3日内审查，理由成立的，予以撤销；理由不成立的，予以驳回。被执行人对驳回不服的，可以向上一级人民法院申请复议。\n4.失信名单退出。失信被执行人全部履行了生效法律文书确定的义务，或与申请执行人达成执行和解协议并经申请执行人确认履行完毕，或案件依法终结执行等，人民法院要在3日内屏蔽或撤销其失信名单信息。屏蔽、撤销信息要及时向社会公开并通报给已推送单位。\n5.惩戒措施解除。失信名单被依法屏蔽、撤销的，各信用监督、警示和惩戒单位要及时解除对被执行人的惩戒措施。确需继续保留对被执行人信用监督、警示和惩戒的，必须严格按照法律法规的有关规定实施，并明确继续保留的期限。\n6.责任追究。进一步完善责任追究制度，对应当纳入而不纳入、违法纳入以及不按规定屏蔽、撤销失信名单等行为，要按照有关规定追究责任。\n（三）进一步完善党政机关支持人民法院执行工作制度\n1.进一步加强协助执行工作。各地区各部门要按照建立和完善执行联动机制的有关要求，进一步抓好落实工作。各级执行联动机制工作领导小组要制定具体的工作机制、程序，明确各协助执行单位的具体职责。强化协助执行工作考核与问责，组织人事、政法等部门要建立协助执行定期联合通报机制，对协助执行不力的单位予以通报和追责。\n2.严格落实执行工作综治考核责任。将失信被执行人联合惩戒情况作为社会治安综合治理目标责任考核的重要内容。严格落实人民法院执行工作在社会治安综合治理目标责任考核中的有关要求。\n3.强化对党政机关干扰执行的责任追究。党政机关要自觉履行人民法院生效裁判，并将落实情况纳入党风廉政建设主体责任和监督责任范围。坚决落实中共中央办公厅、国务院办公厅印发的《领导干部干预司法活动、插手具体案件处理的记录、通报和责任追究规定》，以及《司法机关内部人员过问案件的记录和责任追究规定》，对有关部门及领导干部干预执行、阻扰执行、不配合执行工作的行为，依纪依法严肃处理。","level":1},{"name":"五、加强组织领导","text":"（一）加强组织实施\n各地区各部门要高度重视对失信被执行人信用监督、警示和惩戒工作，将其作为推进全面依法治国、推进社会信用体系建设、培育和践行社会主义核心价值观的重要内容，切实加强组织领导。进一步加强和完善社会信用体系建设部际联席会议制度，形成常态化工作机制。各成员单位要确定专门机构、专业人员负责统筹协调、督促检查各项任务落实情况，并向部际联席会议报告，对工作落实不到位的，予以通报批评，强化问责。负有信息共享、联合惩戒职责的部门要抓紧制定实施细则，确定责任部门，明确时间表、路线图，确保各项措施在2016年年底前落实到位。各联合惩戒单位要在2016年年底前完成与全国信用信息共享平台联合惩戒系统的对接，通过网络自动抓取失信被执行人名单信息，及时反馈惩戒情况。同时要加快惩戒软件开发使用进度，将失信被执行人名单信息嵌入单位管理、审批、工作系统中，实现对失信被执行人名单信息的自动比对、自动拦截、自动监督、自动惩戒。\n（二）强化工作保障\n各地区各部门要认真落实中央关于解决人民法院执行难问题的要求，强化执行机构的职能作用，配齐配强执行队伍，大力推进执行队伍正规化、专业化、职业化建设。加快推进人民法院执行查控系统与执行指挥系统的软硬件建设，加快推进全国信用信息共享平台建设，加快推进各信息共享单位、联合惩戒单位的信息传输专线、存储设备等硬件建设和软件开发，加强人才、资金、设备、技术等方面的保障。\n（三）完善相关法律规定\n加快推进强制执行法等相关法律法规、司法解释及其他规范性文件的立改废释工作，及时将加强执行工作、推进执行联动、信用信息公开和共享、完善失信被执行人名单制度、加强联合惩戒等工作法律化、制度化，确保法律规范的科学性、针对性、实用性。\n（四）加大宣传力度\n加大对失信被执行人名单和信用惩戒的宣传力度，充分发挥新闻媒体的宣传、监督和舆论引导作用。利用报纸、广播、电视、网络等媒体，依法将失信被执行人信息、受惩戒情况等公之于众，形成舆论压力，扩大失信被执行人名单制度的影响力和警示力。","level":1}]},{"id":"r0549","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于依法从严打击证券违法活动的意见》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于依法从严打击证券违法活动的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于依法从严打击证券违法活动的意见》主要内容如下。\n打击证券违法活动是维护资本市场秩序、有效发挥资本市场枢纽功能的重要保障。党的十八大以来，各有关方面认真贯彻党中央、国务院决策部署，扎实推进资本市场执法司法体系建设，依法打击资本市场违法活动，维护投资者合法权益，取得积极成效。同时，在经济金融环境深刻变化、资本市场改革开放不断深化背景下，资本市场违法行为仍较为突出，案件查处难度加大，相关执法司法等工作面临新形势新挑战。为进一步推动资本市场高质量发展，现就依法从严打击证券违法活动提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，坚持市场化、法治化方向，坚持建制度、不干预、零容忍，加强资本市场基础制度建设，健全依法从严打击证券违法活动体制机制，提高执法司法效能，有效防范化解重大风险，为加快建设规范、透明、开放、有活力、有韧性的资本市场提供有力支撑。\n（二）工作原则\n——坚持零容忍要求。依法严厉查处证券违法犯罪案件，加大对大案要案的查处力度，加强诚信约束惩戒，强化震慑效应。\n——坚持法治原则。遵循公开、公平、公正原则，坚持严格执法、公正司法，统一标准、规范程序，提高专业化水平，提升透明度，不断增强公信力。\n——坚持统筹协调。加强证券期货监督管理机构与公安、司法、市场监管等部门及有关地方的工作协同，形成高效打击证券违法活动的合力。\n——坚持底线思维。将依法从严打击证券违法活动与有效防范化解风险、维护国家安全和社会稳定相结合，加强重点领域风险排查，强化源头风险防控，严防风险叠加共振、放大升级。\n（三）主要目标。到2022年，资本市场违法犯罪法律责任制度体系建设取得重要进展，依法从严打击证券违法活动的执法司法体制和协调配合机制初步建立，证券违法犯罪成本显著提高，重大违法犯罪案件多发频发态势得到有效遏制，投资者权利救济渠道更加通畅，资本市场秩序明显改善。到2025年，资本市场法律体系更加科学完备，中国特色证券执法司法体制更加健全，证券执法司法透明度、规范性和公信力显著提升，行政执法与刑事司法衔接高效顺畅，崇法守信、规范透明、开放包容的良好资本市场生态全面形成。","level":1},{"name":"二、完善资本市场违法犯罪法律责任制度体系","text":"（四）完善证券立法机制。充分运用法律修正、法律解释、授权决定等形式，提高证券领域立法效率，增强法律供给及时性。\n（五）加大刑事惩戒力度。贯彻实施刑法修正案（十一），同步修改有关刑事案件立案追诉标准，完善相关刑事司法解释和司法政策。\n（六）完善行政法律制度。贯彻实施新修订的证券法，加快制定修订上市公司监督管理条例、证券公司监督管理条例、新三板市场监督管理条例、证券期货行政执法当事人承诺实施办法等配套法规制度，大幅提高违法违规成本。加快制定期货法，补齐期货市场监管执法制度短板。\n（七）健全民事赔偿制度。抓紧推进证券纠纷代表人诉讼制度实施。修改因虚假陈述引发民事赔偿有关司法解释，取消民事赔偿诉讼前置程序。开展证券行业仲裁制度试点。\n（八）强化市场约束机制。推进退市制度改革，强化退市监管，严格执行强制退市制度，研究完善已退市公司的监管和风险处置制度，健全上市公司优胜劣汰的良性循环机制。加强证券投资基金发行和运作监管，对严重违法违规的基金管理人依法实施市场退出，做好风险处置工作，保护基金持有人合法利益。完善交易场所、行业协会等对证券违法违规行为的自律监管制度。","level":1},{"name":"三、建立健全依法从严打击证券违法活动的执法司法体制机制","text":"（九）建立打击资本市场违法活动协调工作机制。成立打击资本市场违法活动协调工作小组，加大对重大案件的协调力度，完善信息共享机制，推进重要规则制定，协调解决重大问题。\n（十）完善证券案件侦查体制机制。进一步发挥公安部证券犯罪侦查局派驻中国证监会的体制优势，完善线索研判、数据共享、情报导侦、协同办案等方面的行政刑事执法协作机制。进一步优化公安部证券犯罪侦查编制资源配置，加强一线侦查力量建设。\n（十一）完善证券案件检察体制机制。根据案件数量、人员配备等情况，研究在检察机关内部组建金融犯罪办案团队。探索在中国证监会建立派驻检察的工作机制，通过参与案件线索会商研判、开展犯罪预防等，加强最高人民检察院与中国证监会、公安部的协同配合。加强证券领域检察队伍专业化建设。涉嫌重大犯罪案件移送公安机关时，同步抄送检察机关。\n（十二）完善证券案件审判体制机制。充分利用现有审判资源，加强北京、深圳等证券交易场所所在地金融审判工作力量建设，探索统筹证券期货领域刑事、行政、民事案件的管辖和审理。深化金融审判专业化改革，加强金融审判队伍专业化建设。落实由中级法院和同级检察院办理证券犯罪第一审案件的级别管辖。加大行政处罚、司法判决的执行力度。建立专家咨询制度和专业人士担任人民陪审员的专门机制。\n（十三）加强办案、审判基地建设。在证券交易场所、期货交易所所在地等部分地市的公安机关、检察机关、审判机关设立证券犯罪办案、审判基地。加强对证券犯罪办案基地的案件投放，并由对应的检察院、法院分别负责提起公诉、审判，通过犯罪地管辖或者指定管辖等方式，依法对证券犯罪案件适当集中管辖。\n（十四）强化地方属地责任。加强中国证监会与地方政府及有关部门之间的信息互通和执法合作，研究建立资本市场重大违法案件内部通报制度，有效防范和约束办案中可能遇到的地方保护等阻力和干扰，推动高效查办案件。在坚持金融管理主要是中央事权前提下，强化属地风险处置责任。地方政府要规范各类区域性交易场所，依法打击各种非法证券期货活动，做好区域内金融风险防范处置工作，维护社会稳定。","level":1},{"name":"四、强化重大证券违法犯罪案件惩治和重点领域执法","text":"（十五）依法严厉查处大案要案。坚持分类监管、精准打击，全面提升证券违法大案要案查处质量和效率。依法从严从快从重查处欺诈发行、虚假陈述、操纵市场、内幕交易、利用未公开信息交易以及编造、传播虚假信息等重大违法案件。对资金占用、违规担保等严重侵害上市公司利益的行为，要依法严肃清查追偿，限期整改。加大对证券发行人控股股东、实际控制人、董事、监事、高级管理人员等有关责任人证券违法行为的追责力度。加强对中介机构的监管，存在证券违法行为的，依法严肃追究机构及其从业人员责任，对参与、协助财务造假等违法行为依法从重处罚。加快推进相关案件调查、处罚、移送等工作。依法严格控制缓刑适用。\n（十六）依法严厉打击非法证券活动。加强市场监管、公安等部门与中国证监会的协同配合，完善跨部门协作机制，坚决取缔非法证券经营机构，坚决清理非法证券业务，坚决打击非法证券投资咨询等活动。加强场外配资监测，依法坚决打击规模化、体系化场外配资活动。严格核查证券投资资金来源合法性，严控杠杆率。加强涉地方交易场所案件的行政处置与司法审判工作衔接，有效防范区域性金融风险。\n（十七）加强债券市场统一执法。强化对债券市场各类违法行为的统一执法，重点打击欺诈发行债券、信息披露造假、中介机构未勤勉尽责等违法行为。不断优化债券市场监管协作机制。\n（十八）强化私募违法行为的法律责任。加大对私募领域非法集资、私募基金管理人及其从业人员侵占或挪用基金财产等行为的刑事打击力度。加快制定私募投资基金管理暂行条例，对创业投资企业和创业投资管理企业实行差异化监管和行业自律。","level":1},{"name":"五、进一步加强跨境监管执法司法协作","text":"（十九）加强跨境监管合作。完善数据安全、跨境数据流动、涉密信息管理等相关法律法规。抓紧修订关于加强在境外发行证券与上市相关保密和档案管理工作的规定，压实境外上市公司信息安全主体责任。加强跨境信息提供机制与流程的规范管理。坚持依法和对等原则，进一步深化跨境审计监管合作。探索加强国际证券执法协作的有效路径和方式，积极参与国际金融治理，推动建立打击跨境证券违法犯罪行为的执法联盟。\n（二十）加强中概股监管。切实采取措施做好中概股公司风险及突发情况应对，推进相关监管制度体系建设。修改国务院关于股份有限公司境外募集股份及上市的特别规定，明确境内行业主管和监管部门职责，加强跨部门监管协同。\n（二十一）建立健全资本市场法律域外适用制度。抓紧制定证券法有关域外适用条款的司法解释和配套规则，细化法律域外适用具体条件，明确执法程序、证据效力等事项。加强资本市场涉外审判工作，推动境外国家、地区与我国对司法判决的相互承认与执行。","level":1},{"name":"六、着力提升证券执法司法能力和专业化水平","text":"（二十二）增强证券执法能力。加强证券执法力量，优化证券稽查执法机构设置，推动完善符合资本市场发展需要的中国特色证券执法体制机制。充分发挥证券期货行政执法当事人承诺制度功能。完善证券违法线索举报奖励制度，加强违法线索举报受理平台建设。\n（二十三）丰富证券执法手段。有效运用大数据、人工智能、区块链等技术，建立证券期货市场监测预警体系，构建以科技为支撑的现代化监管执法新模式，提高监管执法效能，加强对严重违法隐患的排查预警，做到有效预防、及时发现、精准打击。\n（二十四）严格执法公正司法。牢固树立权责意识、证据意识、程序意识，切实提升执法司法专业性、规范性、权威性和公信力。加强统一执法，制定行政处罚裁量基准，规范执法行为。发挥复议监督、诉讼监督和检察监督作用，强化对监管执法机构的规范与监督，坚决纠正执法司法工作中的不规范现象，为资本市场发展营造公平公正的法治环境。","level":1},{"name":"七、加强资本市场信用体系建设","text":"（二十五）夯实资本市场诚信建设制度基础。在相关法律法规中增设诚信建设专门条款，建立资本市场诚信记录主体职责制度，明确市场参与主体诚信条件、义务和责任，依法合规开展资本市场失信惩戒和守信激励。\n（二十六）建立健全信用承诺制度。建立资本市场行政许可信用承诺制度，明确适用主体范围和许可事项。将信用承诺事项及其履行情况纳入信用记录，作为事中事后监管的重要依据。对严重违反承诺的当事人，依法撤销有关行政许可。\n（二十七）强化资本市场诚信监管。建立健全全国统一的资本市场诚信档案，全面记录资本市场参与主体诚信信息。健全诚信信息共享机制，加大信息归集、查询、公示力度。将相关信息纳入全国信用信息共享平台和“信用中国”网站，形成各方共建共治共享的资本市场诚信建设格局。","level":1},{"name":"八、加强组织保障和监督问责","text":"（二十八）加强组织领导。各地区各部门要高度重视资本市场执法司法工作，切实把思想和行动统一到党中央、国务院决策部署上来，明确职责分工，加强工作协同，落实工作责任，确保各项任务落到实处。\n（二十九）加强舆论引导。做好立体化打击证券违法活动的新闻舆论工作，多渠道多平台强化对重点案件的执法宣传，充分发挥典型案件查处的警示教育作用，向市场传递零容忍明确信号，推动形成崇法守信的良好资本市场生态。\n（三十）加强监督问责。坚持全面从严治党，坚决落实深化金融领域反腐败工作要求。执法司法机关与纪检监察机关协同推进风险处置和金融领域反腐败工作，坚决查处金融风险背后的各种腐败问题，同时注重防范腐败案件可能诱发的资本市场风险。优先查处可能影响资本市场重大改革进程、可能引发系统性风险的案件，以及监管工作人员与市场人员内外勾连等案件。依法严格规范证券监督管理机构工作人员到与原工作业务直接相关的企业或者其他营利性组织任职等行为。对不严格执行法律法规、发现线索不报、有案不立、查处不力以及影响干扰案件正常查办的，依规依纪依法严肃追究责任。","level":1}]},{"id":"r0550","sections":[{"name":"关于完善国家统一法律职业资格制度的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于完善国家统一法律职业资格制度的意见》（以下简称《意见》）。《意见》贯彻落实党的十八大和十八届三中、四中全会精神，提出了完善国家统一法律职业资格制度的目标任务和重要举措，对于推进法治工作队伍正规化、专业化、职业化，为建设社会主义法治国家提供人才保障具有重要意义。","level":1},{"name":"","text":"《意见》明确了指导思想和基本原则，为完善国家统一法律职业资格制度指明了方向。《意见》提出，要以党的十八大、十八届三中、四中全会精神和习近平总书记系列重要讲话精神为指导，以建设一支忠于党、忠于国家、忠于人民、忠于法律的社会主义法治工作队伍为目标，通过建立健全国家统一法律职业资格制度，培育和发展社会主义法治工作队伍，为全面推进依法治国提供人才保障。\n《意见》强调，完善国家统一法律职业资格制度，必须遵循以下基本原则：一要坚持正确方向。坚持党的领导，贯彻中国特色社会主义法治理论，按照政治过硬、业务过硬、责任过硬、纪律过硬、作风过硬的要求，选拔培养社会主义法律职业人才。二要坚持整体规划。加强顶层设计，注重整体谋划，确保国家统一法律职业资格制度各项改革措施的系统性、整体性和协同性。三要坚持遵循规律。遵循法治工作队伍形成规律，遵循法律职业人才特殊的职业素养、职业能力、职业操守要求，按照法治工作队伍建设正规化、专业化、职业化标准，科学设计和实施国家统一法律职业资格制度，提高法律职业人才选拔、培养的科学性和公信力。四要坚持积极稳妥。实行老人老办法、新人新办法，只对新进法律职业岗位人员实行考试和职前培训，促进新旧制度妥善对接。\n《意见》明确了法律职业的范围和取得法律职业资格的条件。在司法考试制度确定的法官、检察官、律师和公证员四类法律职业人员基础上，《意见》将部分涉及对公民、法人权利义务的保护和克减、具有准司法性质的法律从业人员纳入法律职业资格考试的范围。《意见》还分别从思想政治、专业学历条件和取得法律职业资格等三个方面，明确了法律职业的准入条件。\n《意见》规定，建立健全国家统一法律职业资格考试制度，将现行司法考试制度调整为国家统一法律职业资格考试制度，改革法律职业资格考试内容，加强法律职业资格考试科学化、标准化、信息化建设。《意见》要求，建立法律职业人员任职前培训制度，统一职前培训的内容和方式，加强职前培训的组织保障。为完善对法律职业资格的管理，《意见》提出，要加强法律职业资格管理规范化、制度化建设，建立法律职业资格档案管理和信息发布制度，建立法律职业资格暂停、吊销制度。同时，为实现由司法考试制度向国家统一法律职业资格制度的平稳顺利过渡，《意见》要求做好相关制度衔接工作。\n《意见》强调，各地区各部门要把思想和行动统一到中央决策部署上来，切实加强领导，密切协调配合，形成工作合力，确保国家统一法律职业资格制度顺利建立和有效实施。健全国家统一法律职业资格考试、职前培训工作协调机制，同步推进相关法律法规制定修订工作进程，落实各项保障措施。加强部门间的协同配合，配套推进与国家统一法律职业资格制度紧密相关事项的改革，做好国家统一法律职业资格制度改革方案和政策的宣传解读工作。","level":0}]},{"id":"r0551","sections":[{"name":"中共中央 国务院关于推进价格机制改革的若干意见","text":"价格机制是市场机制的核心，市场决定价格是市场在资源配置中起决定性作用的关键。改革开放以来，作为经济体制改革的重要组成部分，价格改革持续推进、不断深化，放开了绝大多数竞争性商品价格，对建立健全社会主义市场经济体制、促进经济社会持续健康发展发挥了重要作用。特别是近年来，价格改革步伐大大加快，一大批商品和服务价格陆续放开，成品油、天然气、铁路运输等领域价格市场化程度显著提高。同时也要看到，一些重点领域和关键环节价格改革还需深化，政府定价制度需要进一步健全，市场价格行为有待进一步规范。为推动价格改革向纵深发展，加快完善主要由市场决定价格机制，现提出以下意见。","level":1},{"name":"一、总体要求","text":"（一）指导思想。全面贯彻党的十八大和十八届二中、三中、四中全会精神，按照党中央、国务院决策部署，主动适应和引领经济发展新常态，紧紧围绕使市场在资源配置中起决定性作用和更好发挥政府作用，全面深化价格改革，完善重点领域价格形成机制，健全政府定价制度，加强市场价格监管和反垄断执法，为经济社会发展营造良好价格环境。\n（二）基本原则\n——坚持市场决定。正确处理政府和市场关系，凡是能由市场形成价格的都交给市场，政府不进行不当干预。推进水、石油、天然气、电力、交通运输等领域价格改革，放开竞争性环节价格，充分发挥市场决定价格作用。\n——坚持放管结合。进一步增强法治、公平、责任意识，强化事中事后监管，优化价格服务。政府定价领域，必须严格规范政府定价行为，坚决管细管好管到位；经营者自主定价领域，要通过健全规则、加强执法，维护市场秩序，保障和促进公平竞争，推进现代市场体系建设。\n——坚持改革创新。在价格形成机制、调控体系、监管方式上探索创新，尊重基层和群众的首创精神，推动价格管理由直接定价向规范价格行为、营造良好价格环境、服务宏观调控转变。充分发挥价格杠杆作用，促进经济转型升级和提质增效。\n——坚持稳慎推进。价格改革要与财政税收、收入分配、行业管理体制等改革相协调，合理区分基本与非基本需求，统筹兼顾行业上下游、企业发展和民生保障、经济效率和社会公平、经济发展和环境保护等关系，把握好时机、节奏和力度，切实防范各类风险，确保平稳有序。\n（三）主要目标。到2017年，竞争性领域和环节价格基本放开，政府定价范围主要限定在重要公用事业、公益性服务、网络型自然垄断环节。到2020年，市场决定价格机制基本完善，科学、规范、透明的价格监管制度和反垄断执法体系基本建立，价格调控机制基本健全。","level":1},{"name":"二、深化重点领域价格改革，充分发挥市场决定价格作用","text":"紧紧围绕使市场在资源配置中起决定性作用，加快价格改革步伐，深入推进简政放权、放管结合、优化服务，尊重企业自主定价权、消费者自由选择权，促进商品和要素自由流动、公平交易。\n（四）完善农产品价格形成机制。统筹利用国际国内两个市场，注重发挥市场形成价格作用，农产品价格主要由市场决定。按照“突出重点、有保有放”原则，立足我国国情，对不同品种实行差别化支持政策，调整改进“黄箱”支持政策，逐步扩大“绿箱”支持政策实施规模和范围，保护农民生产积极性，促进农业生产可持续发展，确保谷物基本自给、口粮绝对安全。继续执行并完善稻谷、小麦最低收购价政策，改革完善玉米收储制度，继续实施棉花、大豆目标价格改革试点，完善补贴发放办法。加强农产品成本调查和价格监测，加快建立全球农业数据调查分析系统，为政府制定农产品价格、农业补贴等政策提供重要支撑。\n（五）加快推进能源价格市场化。按照“管住中间、放开两头”总体思路，推进电力、天然气等能源价格改革，促进市场主体多元化竞争，稳妥处理和逐步减少交叉补贴，还原能源商品属性。择机放开成品油价格，尽快全面理顺天然气价格，加快放开天然气气源和销售价格，有序放开上网电价和公益性以外的销售电价，建立主要由市场决定能源价格的机制。把输配电价与发售电价在形成机制上分开，单独核定输配电价，分步实现公益性以外的发售电价由市场形成。按照“准许成本加合理收益”原则，合理制定电网、天然气管网输配价格。扩大输配电价改革试点范围，逐步覆盖到各省级电网，科学核定电网企业准许收入和分电压等级输配电价，改变对电网企业的监管模式，逐步形成规则明晰、水平合理、监管有力、科学透明的独立输配电价体系。在放开竞争性环节电价之前，完善煤电价格联动机制和标杆电价体系，使电力价格更好反映市场需求和成本变化。\n（六）完善环境服务价格政策。统筹运用环保税收、收费及相关服务价格政策，加大经济杠杆调节力度，逐步使企业排放各类污染物承担的支出高于主动治理成本，提高企业主动治污减排的积极性。按照“污染付费、公平负担、补偿成本、合理盈利”原则，合理提高污水处理收费标准，城镇污水处理收费标准不应低于污水处理和污泥处理处置成本，探索建立政府向污水处理企业拨付的处理服务费用与污水处理效果挂钩调整机制，对污水处理资源化利用实行鼓励性价格政策。积极推进排污权有偿使用和交易试点工作，完善排污权交易价格体系，运用市场手段引导企业主动治污减排。\n（七）理顺医疗服务价格。围绕深化医药卫生体制改革目标，按照“总量控制、结构调整、有升有降、逐步到位”原则，积极稳妥推进医疗服务价格改革，合理调整医疗服务价格，同步强化价格、医保等相关政策衔接，确保医疗机构发展可持续、医保基金可承受、群众负担不增加。建立以成本和收入结构变化为基础的价格动态调整机制，到2020年基本理顺医疗服务比价关系。落实非公立医疗机构医疗服务市场调节价政策。公立医疗机构医疗服务项目价格实行分类管理，对市场竞争比较充分、个性化需求比较强的医疗服务项目价格实行市场调节价，其中医保基金支付的服务项目由医保经办机构与医疗机构谈判合理确定支付标准。进一步完善药品采购机制，发挥医保控费作用，药品实际交易价格主要由市场竞争形成。\n（八）健全交通运输价格机制。逐步放开铁路运输竞争性领域价格，扩大由经营者自主定价的范围；完善铁路货运与公路挂钩的价格动态调整机制，简化运价结构；构建以列车运行速度和等级为基础、体现服务质量差异的旅客运输票价体系。逐步扩大道路客运、民航国内航线客运、港口经营等领域由经营者自主定价的范围，适时放开竞争性领域价格，完善价格收费规则。放开邮政竞争性业务资费，理顺邮政业务资费结构和水平。实行有利于促进停车设施建设、有利于缓解城市交通拥堵、有效促进公共交通优先发展与公共道路资源利用的停车收费政策。进一步完善出租汽车运价形成机制，发挥运价调节出租汽车运输市场供求关系的杠杆作用，建立健全出租汽车运价动态调整机制以及运价与燃料价格联动办法。\n（九）创新公用事业和公益性服务价格管理。清晰界定政府、企业和用户的权利义务，区分基本和非基本需求，建立健全公用事业和公益性服务财政投入与价格调整相协调机制，促进政府和社会资本合作，保证行业可持续发展，满足多元化需求。全面实行居民用水用电用气阶梯价格制度，推行供热按用热量计价收费制度，并根据实际情况进一步完善。教育、文化、养老、殡葬等公益性服务要结合政府购买服务改革进程，实行分类管理。对义务教育阶段公办学校学生免收学杂费，公办幼儿园、高中（含中职）、高等学校学费作为行政事业性收费管理；营利性民办学校收费实行自主定价，非营利性民办学校收费政策由省级政府按照市场化方向根据当地实际情况确定。政府投资兴办的养老服务机构依法对“三无”老人免费；对其他特殊困难老人提供养老服务，其床位费、护理费实行政府定价管理，其他养老服务价格由经营者自主定价。分类推进旅游景区门票及相关服务价格改革。推动公用事业和公益性服务经营者加大信息公开力度，接受社会监督，保障社会公众知情权、监督权。","level":1},{"name":"三、建立健全政府定价制度，使权力在阳光下运行","text":"对于极少数保留的政府定价项目，要推进定价项目清单化，规范定价程序，加强成本监审，推进成本公开，坚决管细管好管到位，最大限度减少自由裁量权，推进政府定价公开透明。\n（十）推进政府定价项目清单化。中央和地方要在加快推进价格改革的基础上，于2016年以前制定发布新的政府定价目录，将政府定价范围主要限定在重要公用事业、公益性服务、网络型自然垄断环节。凡是政府定价项目，一律纳入政府定价目录管理。目录内的定价项目要逐项明确定价内容和定价部门，确保目录之外无定价权，政府定价纳入权力和责任清单。定期评估价格改革成效和市场竞争程度，适时调整具体定价项目。\n（十一）规范政府定价程序。对纳入政府定价目录的项目，要制定具体的管理办法、定价机制、成本监审规则，进一步规范定价程序。鼓励和支持第三方提出定调价方案建议、参与价格听证。完善政府定价过程中的公众参与、合法性审查、专家论证等制度，保证工作程序明晰、规范、公开、透明，主动接受社会监督，有效约束政府定价行为。\n（十二）加强成本监审和成本信息公开。坚持成本监审原则，将成本监审作为政府制定和调整价格的重要程序，不断完善成本监审机制。对按规定实行成本监审的，要逐步建立健全成本公开制度。公用事业和公益性服务的经营者应当按照政府定价机构的规定公开成本，政府定价机构在制定和调整价格前应当公开成本监审结论。","level":1},{"name":"四、加强市场价格监管和反垄断执法，逐步确立竞争政策的基础性地位","text":"清理和废除妨碍全国统一市场和公平竞争的各种规定和做法，严禁和惩处各类违法实行优惠政策行为，建立公平、开放、透明的市场价格监管规则，大力推进市场价格监管和反垄断执法，反对垄断和不正当竞争。加快建立竞争政策与产业、投资等政策的协调机制，实施公平竞争审查制度，促进统一开放、竞争有序的市场体系建设。\n（十三）健全市场价格行为规则。在经营者自主定价领域，对经济社会影响重大特别是与民生紧密相关的商品和服务，要依法制定价格行为规则和监管办法；对存在市场竞争不充分、交易双方地位不对等、市场信息不对称等问题的领域，要研究制定相应议价规则、价格行为规范和指南，完善明码标价、收费公示等制度规定，合理引导经营者价格行为。\n（十四）推进宽带网络提速降费。规范电信资费行为，推进宽带网络提速降费，为“互联网＋”发展提供有力支撑。指导、推动电信企业简化资费结构，切实提高宽带上网等业务的性价比，并为城乡低收入群体提供更加优惠的资费方案。督促电信企业合理制定互联网接入服务资费标准和计费办法，促进电信网间互联互通。严禁利用不正当定价行为阻碍电信服务竞争，扰乱市场秩序。加强资费行为监管，清理宽带网络建设环节中存在的进场费、协调费、分摊费等不合理费用，严厉打击价格违法行为。\n（十五）加强市场价格监管。建立健全机构权威、法律完备、机制完善、执行有力的市场价格监管工作体系，有效预防、及时制止和依法查处各类价格违法行为。坚持日常监管和专项检查相结合，加强民生领域价格监管，着力解决群众反映的突出问题，保护消费者权益。加大监督检查力度，对政府已放开的商品和服务价格，要确保经营者依法享有自主定价权。\n（十六）强化反垄断执法。密切关注竞争动态，对涉嫌垄断行为及时启动反垄断调查，着力查处达成实施垄断协议、滥用市场支配地位和滥用行政权力排除限制竞争等垄断行为，依法公布处理决定，维护公平竞争的市场环境。建立健全垄断案件线索收集机制，拓宽案件来源。研究制定反垄断相关指南，完善市场竞争规则。促进经营者加强反垄断合规建设。\n（十七）完善价格社会监督体系。充分发挥全国四级联网的12358价格举报管理信息系统作用，鼓励消费者和经营者共同参与价格监督。加强举报数据分析，定期发布分析报告，警示经营者，提醒消费者。建立健全街道、社区、乡镇、村居民价格监督员队伍，完善价格社会监督网络。依托社会信用体系，加快推进价格诚信建设，构建经营者价格信用档案，开展价格诚信单位创建活动，设立价格失信者“黑名单”，对构成价格违法的失信行为予以联合惩戒。鼓励和支持新闻媒体积极参与价格社会监督，完善舆论监督和引导机制。","level":1},{"name":"五、充分发挥价格杠杆作用，更好服务宏观调控","text":"在全面深化改革、强化价格监管的同时，加强和改善宏观调控，保持价格总水平基本稳定；充分发挥价格杠杆作用，促进节能环保和结构调整，推动经济转型升级。\n（十八）加强价格总水平调控。加强价格与财政、货币、投资、产业、进出口、物资储备等政策手段的协调配合，合理运用法律手段、经济手段和必要的行政手段，形成政策合力，努力保持价格总水平处于合理区间。加强通缩、通胀预警，制定和完善相应防范治理预案。健全价格监测预警机制和应急处置体系，构建大宗商品价格指数体系，健全重要商品储备制度，提升价格总水平调控能力。\n（十九）健全生产领域节能环保价格政策。建立有利于节能减排的价格体系，逐步使能源价格充分反映环境治理成本。继续实施并适时调整脱硫、脱硝、除尘等环保电价政策。鼓励各地根据产业发展实际和结构调整需要，结合电力、水等领域体制改革进程，研究完善对“两高一剩”（高耗能、高污染、产能过剩）行业落后工艺、设备和产品生产的差别电价、水价等价格措施，对电解铝、水泥等行业实行基于单位能耗超定额加价的电价政策，加快淘汰落后产能，促进产业结构转型升级。\n（二十）完善资源有偿使用制度和生态补偿制度。加快自然资源及其产品价格和财税制度改革，全面反映市场供求、资源稀缺程度、生态环境损害成本和修复效益。完善涉及水土保持、矿山、草原植被、森林植被、海洋倾倒等资源环境收费基金或有偿使用收费政策。推进水资源费改革，研究征收水资源税，推动在地下水超采地区先行先试。采取综合措施逐步理顺水资源价格，深入推进农业水价综合改革，促进水资源保护和节约使用。\n（二十一）创新促进区域发展的价格政策。对具有区域特征的政府和社会资本合作项目，已具备竞争条件的，尽快放开价格管理；仍需要实行价格管理的，探索将定价权限下放到地方，提高价格调整灵活性，调动社会投资积极性。加快制定完善适应自由贸易试验区发展的价格政策，能够下放到区内自主实施的尽快下放，促进各类市场主体公平竞争。","level":1},{"name":"六、保障措施","text":"价格工作涉及面广、政策性强、社会关注度高，牵一发而动全身。必须加强组织落实，科学制定方案，完善配套措施，做好舆论引导，为加快完善主要由市场决定价格机制提供有力保障。\n（二十二）加强组织落实。各地区各有关部门要充分认识加快完善主要由市场决定价格机制的重要性、紧迫性和艰巨性，统一思想、形成合力，以敢啃“硬骨头”精神打好攻坚战。要深入调研、科学论证，广泛听取各方面意见，突出重点、分类推进，细化工作方案，及时总结评估，稳步有序推进，务求取得实效。影响重大、暂不具备全面推开条件的，可先行开展试点，发挥示范引领作用，积累可复制、可推广的经验。要以抓铁有痕、踏石留印的作风，狠抓落实，明确时间表、路线图、责任状，定期督查、强化问责，全力打通政策出台的“最先一公里”、政策实施的“中梗阻”与政策落地的“最后一公里”，确保各项措施落地生根。\n（二十三）健全价格法制。紧密结合价格改革、调控和监管工作实际，加快修订价格法等相关法律法规，完善以价格法、反垄断法为核心的价格法律法规，及时制定或修订政府定价行为规则以及成本监审、价格监测、价格听证、规范市场价格行为等规章制度，全面推进依法治价。\n（二十四）强化能力建设。在减少政府定价事项的同时，注重做好价格监测预警、成本调查监审、价格调控、市场价格监管和反垄断执法、价格公共服务等工作，并同步加强队伍建设，充实和加强工作力量，夯实工作基础。大力推进价格信息化建设，为增强价格调控监管服务能力提供有力支撑。鼓励高等学校和科研机构建立价格与反垄断研究机构，加强国际交流合作，培养专门人才。整合反垄断执法主体和力量，相对集中执法权。\n（二十五）兜住民生底线。牢固树立底线思维，始终把保障和改善民生作为工作的出发点和落脚点。推行涉及民生的价格政策特别是重大价格改革政策时，要充分考虑社会承受能力，特别是政策对低收入群体生活的可能影响，做好风险评估，完善配套措施。落实和完善社会救助、保障标准与物价上涨挂钩的联动机制，完善社会救助制度特别是对特困人群的救助措施，保障困难群众基本生活不受影响。加强民生领域价格监管，做好价格争议纠纷调解处理，维护群众合法价格权益。\n（二十六）做好舆论引导。加大对全面深化价格改革、规范政府定价、强化市场价格监管与反垄断执法等方面的宣传报道力度，加强新闻发布，准确阐述价格政策，讲好“价格改革故事”，及时引导舆论，回应社会关切，传递有利于加快完善主要由市场决定价格机制、推动经济转型升级的好声音和正能量，积极营造良好舆论氛围。","level":1}]},{"id":"r0552","sections":[{"name":"中共中央办公厅印发《关于在全社会开展党史、新中国史、改革开放史、社会主义发展史宣传教育的通知》","text":"奋斗百年路 启航新征程","level":1},{"name":"","text":"近日，中共中央办公厅印发《关于在全社会开展党史、新中国史、改革开放史、社会主义发展史宣传教育的通知》，对在中国共产党成立100周年之际开展“四史”宣传教育作出安排部署。\n《通知》强调，要高举中国特色社会主义伟大旗帜，以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，深入贯彻落实党的十九大和十九届二中、三中、四中、五中全会精神，增强“四个意识”、坚定“四个自信”、做到“两个维护”，围绕庆祝中国共产党成立100周年，在全社会广泛开展党史、新中国史、改革开放史、社会主义发展史宣传教育，普及党史知识，推动党史学习教育深入群众、深入基层、深入人心，引导广大人民群众深刻认识中国共产党为国家和民族作出的伟大贡献，深刻感悟中国共产党始终不渝为人民的初心宗旨，学习中国共产党推进马克思主义中国化形成的重大理论成果，传承中国共产党在长期奋斗中铸就的伟大精神，坚定不移听党话、跟党走，在全面建设社会主义现代化国家伟大实践中建功立业。\n《通知》明确，要以学习宣传贯彻习近平新时代中国特色社会主义思想为主线，准确把握这一重要思想的理论逻辑、历史逻辑、实践逻辑，深入领会这一重要思想的历史地位和重大意义，不断增进政治认同、思想认同、理论认同、情感认同。深入学习领会习近平总书记关于党史、新中国史、改革开放史、社会主义发展史的重要论述，特别是在党史学习教育动员大会、庆祝中国共产党成立100周年大会上的重要讲话精神，及时跟进学、前后贯通学、联系实际学。要把握“四史”宣传教育内涵，注重内容上融会贯通、逻辑上环环相扣，引导广大人民群众特别是青少年弄清楚中国共产党为什么能、马克思主义为什么行、中国特色社会主义为什么好等基本道理，加深对党的历史的理解和把握，加深对党的理论的理解和认识。\n《通知》指出，要组织好各项宣传教育活动。一是开展读书学史活动。开展“书映百年伟业”好书荐读活动，举办“红色经典·献礼百年”阅读活动，组织“强素质·作表率”读书活动，开展党建文献专题阅读学习活动。二是组织基层宣讲活动。广泛开展百姓宣讲，深入基层开展巡回宣讲，用小故事讲透大道理。举办形势报告会、“四史”专题宣讲等，邀请领导干部带头作报告。三是开展学习体验活动。深入挖掘红色文化内涵，精心设计推出一批精品展览、红色旅游精品线路、学习体验线路。组织有庄严感和教育意义的仪式活动，开展文化科技卫生“三下乡”等社会实践活动。四是开展致敬革命先烈活动。结合烈士纪念日等重要纪念日及其他传统节日，组织开展祭扫烈士墓、敬献花篮、宣读祭文、瞻仰遗物等活动。开展“为烈士寻亲”专项行动，组织“心中的旗帜”等红色讲解员大赛，弘扬英雄精神。五是开展学习先进模范活动。集中宣传发布“3个100杰出人物”，开展党和国家功勋荣誉获得者、时代楷模等先进模范学习宣传活动。深入走访慰问老战士、老同志、老支前模范、烈士遗属等，帮助解决实际困难。六是开展红色家风传承活动。发挥文明家庭、五好家庭、最美家庭的示范带动作用，通过巡讲、主题展、快闪、家庭故事汇等方式讲述感人家风故事。七是开展全民国防教育活动。组织开展“迈向强国新征程·军民共筑强军梦”巡讲，组织军营开放活动，抓好高校和高中学生军训，依托国防教育基地进行红色研学，强化全民国防观念。八是组织群众性文化活动。组织美术展、优秀影视剧展播、优秀网络文艺作品展示等活动，开展知识竞赛、演讲比赛等活动。创新实施文化惠民工程，开展“唱支山歌给党听”群众歌咏、广场舞展演、“村晚”等活动。\n《通知》强调，各地区各部门要始终把握正确导向，树立正确历史观，准确把握党史、新中国史、改革开放史、社会主义发展史的主题主线、主流本质，旗帜鲜明反对历史虚无主义。要突出青少年群体，把握青少年群体的特点和习惯，组织好青少年学习教育，厚植爱党爱国爱社会主义的情感，让红色基因、革命薪火代代传承。要丰富活动载体，发挥爱国主义教育基地作用，着力打造精品陈列，精心设计活动内容和载体，增强教育感染力。要用好网络平台，发挥融媒体优势，制作播出一批接地气、易传播、群众爱听爱看的网络文化产品和文艺作品。要加强统筹协调，把“四史”宣传教育同党史学习教育、“永远跟党走”群众性主题宣传教育活动等有机结合起来，相互促进、相得益彰。严格执行中央八项规定及其实施细则精神，坚决克服形式主义、官僚主义。加强安全管理，做好新冠肺炎疫情防控工作，确保宣传教育各项工作安全有序。\n党史学习教育专题","level":0}]},{"id":"r0553","sections":[{"name":"党政领导干部选拔任用工作有关事项报告办法（试行）","text":"第一条 为加强对党政领导干部选拔任用工作的监督，进一步规范干部选拔任用行为，防止和纠正用人上不正之风，根据《党政领导干部选拔任用工作条例》、《党政领导干部选拔任用工作监督检查办法（试行）》，制定本办法。","level":1},{"name":"","text":"第二条 党委（党组）组织（人事）部门按照干部管理权限，负责本级党委管理的党政领导干部选拔任用工作有关事项的报告工作，并负责审核下一级组织（人事）部门报告的党政领导干部选拔任用工作有关事项。\n第三条 在干部选拔任用工作中有下列情形之一的，应当按照要求书面报告上一级组织（人事）部门，经批复同意后方可进行：\n（一）在机构变动或者主要领导成员已经明确即将离任时确因工作需要提拔、调整干部的；\n（二）越级提拔干部的；\n（三）党委、政府及其工作部门个别特殊需要的领导成员人选，不经民主推荐，由组织推荐提名作为考察对象的；\n（四）市、县、乡党政正职在同一岗位任期不到3年进行调整的；\n（五）其他应当事先报批的事项。\n本条第（四）项需要报经更上一级组织（人事）部门批复同意。\n报告内容包括提拔调整干部的原由，拟提拔调整对象个人情况、任用意向，职数配备以及其他需要说明的情况。\n第四条 在干部选拔任用工作中有下列情形之一的，在作出决定前应当征求上一级组织（人事）部门的意见：\n（一）破格提拔干部的；\n（二）除领导班子换届外，一批集中调整干部数量较大的（具体数量界限由各级组织人事部门根据实际确定）；\n（三）领导干部的近亲属在领导干部所在单位（系统）内提拔任用，或者在领导干部所在地区提拔担任下一级领导职务的；\n（四）领导干部的秘书等身边工作人员提拔任用的；\n（五）领导干部因被问责受到组织处理或者纪律处分，影响期满拟重新任用的；\n（六）超过任职年龄或者规定任期需要继续留任的；\n（七）其他需要报告的事项。\n本条第（三）项所称领导干部的近亲属，是指与领导干部有夫妻关系、直系血亲关系、三代以内旁系血亲以及近姻亲关系的人员。\n征求意见应当以书面形式事前函报上一级组织（人事）部门，随函附报拟提拔任用干部的《干部任免审批表》、考察材料等。\n第五条 上级组织（人事）部门依据有关规定审核报告事项，应当在15个工作日内予以答复。未经答复，不得提交党委（党组）会议讨论决定相关任用事项。党委（党组）会议讨论研究有关干部任用时，本级组织（人事）部门应当如实报告征求意见的情况。\n第六条 凡违反本办法作出的干部任用决定，应当予以纠正，并按照规定追究有关责任人的责任。\n第七条 工会、共青团、妇联等人民团体和国有企事业单位参照本办法执行。\n第八条 本办法由中共中央组织部负责解释。\n第九条 本办法自发布之日起施行。","level":0}]},{"id":"r0554","sections":[{"name":"中宣部、中央文明办、中央纪委机关等联合印发《关于进一步加强家庭家教家风建设的实施意见》","text":"近日，中宣部、中央文明办、中央纪委机关、中组部、国家监委、教育部、全国妇联印发《关于进一步加强家庭家教家风建设的实施意见》（以下简称《意见》）。","level":1},{"name":"","text":"《意见》指出，要以习近平新时代中国特色社会主义思想为指导，立足新发展阶段、贯彻新发展理念、构建新发展格局，以培育和践行社会主义核心价值观为根本，以建设文明家庭、实施科学家教、传承优良家风为重点，强化党员和领导干部家风建设，突出少年儿童品德教育关键，推动家庭家教家风建设高质量发展。\n《意见》要求，要加强习近平总书记关于注重家庭家教家风建设重要论述的学习宣传，让新时代家庭观成为亿万家庭日用而不觉的道德规范和行为准则。要以社会主义核心价值观引领家庭家教家风建设，升华爱国爱家的家国情怀、建设相亲相爱的家庭关系、弘扬向上向善的家庭美德、体现共建共享的家庭追求。要围绕落实立德树人根本任务开展家庭教育，引导家长用正确行动、正确思想、正确方法培养孩子养成好思想、好品行、好习惯。要把家风建设作为党员和领导干部作风建设重要内容，引导党员和领导干部筑牢反腐倡廉的家庭防线，以纯正家风涵养清朗党风政风社风。要注重发挥家庭家教家风建设在基层社会治理中的重要作用，吸引群众走出“小”家、融入“大”家，积极参与和谐社区、美丽乡村等建设。\n《意见》强调，要强化制度保障，把新时代家庭观的要求体现到法律法规、制度规范和行为准则中，体现到各项经济社会发展和社会管理政策中，彰显公共政策价值导向。要加强组织领导，强化部门有效协同，形成家庭家教家风建设合力，动员广大家庭把个人梦、家庭梦融入国家梦、民族梦之中，为实现中华民族伟大复兴中国梦汇聚磅礴力量。","level":0}]},{"id":"r0555","sections":[{"name":"宣传思想文化系统事业单位领导人员管理办法","text":"宣传思想文化系统事业单位领导人员管理办法\n（2017年1月13日中共中央组织部、中共中央宣传部制定 2026年7月22日中共中央组织部、中共中央宣传部修订 2026年8月12日发布）","level":1},{"name":"第一章 总则","text":"第一条 为加强和改进宣传思想文化系统事业单位领导人员管理，根据《事业单位领导人员管理规定》和有关法律法规，制定本办法。\n第二条 本办法适用于省级以上党委和政府直属以及部门所属宣传思想文化系统事业单位领导班子成员。\n法律法规对宣传思想文化系统事业单位领导人员管理另有规定的，从其规定。\n宣传思想文化系统事业单位内设机构负责人选拔任用工作，按照干部管理权限，依照本办法第二章、第三章有关条款执行。\n第三条 宣传思想文化系统事业单位领导人员管理，坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻习近平党建思想、习近平文化思想，坚持和加强党的全面领导，贯彻新时代党的组织路线和干部工作方针政策，坚持党管干部、党管人才，坚持德才兼备、以德为先、五湖四海、任人唯贤，注重意识形态工作的政治属性和行业特点，贯彻管事与管人相结合要求，充分调动积极性、主动性、创造性，促进新时代宣传思想文化事业高质量发展。\n第四条 主管机关（部门）党委（党组）及其组织（人事）部门按照干部管理权限履行宣传思想文化系统事业单位领导人员管理职责，负责本办法的组织实施。","level":1},{"name":"第二章 任职条件和资格","text":"第五条 宣传思想文化系统事业单位领导人员应当具备《事业单位领导人员管理规定》要求的基本条件，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，严守政治纪律和政治规矩，符合新时代好干部标准，认真贯彻党的宣传思想文化工作方针政策，坚持政治家办报办刊办台办新媒体，具有强烈的意识形态阵地意识，坚持以人民为中心的工作导向，贯彻总体国家安全观，树立和践行正确政绩观，弘扬和践行社会主义核心价值观；勤于学习钻研，具有胜任岗位职责的理论水平、专业知识和职业素养，自觉增强脚力、眼力、脑力、笔力；具有较强的组织领导和管理能力，贯彻执行民主集中制；顺应信息技术发展潮流，勇于改革创新，敢于善于斗争，严于律己，清正廉洁。\n社科理论、新闻出版、广播电视、文化艺术、对外宣传和网络信息传播等不同领域事业单位领导人员，其能力素质还应当适应本领域业务特点和工作要求。\n党组织书记应当政治强、懂党建、懂业务，具有驾驭全局能力，善于把方向、抓导向、管阵地、强队伍，作风民主；行政正职应当政治素质好，具有较高的专业水平和较强的管理能力，善于合作共事。\n第六条 宣传思想文化系统事业单位领导人员应当具备下列基本资格：\n（一）一般应当具有大学本科以上文化程度。\n（二）一般应当具有5年以上宣传思想文化领域工作经历或者其他党政机关、企事业单位管理工作经历。\n（三）从副职提任正职的，应当具有副职岗位2年以上任职经历；从下级正职提任上级副职的，应当具有下级正职岗位3年以上任职经历。\n（四）应当达到干部教育培训相关要求。确因特殊情况在提任前未达到培训要求的，应当在提任后1年内完成。\n（五）具有正常履行职责的身心条件。\n（六）符合有关党内法规、法律法规和行业主管部门规定的其他任职资格要求。\n第七条 宣传思想文化系统事业单位内设机构负责人基本条件应当符合本办法第五条规定；基本资格一般应当符合本办法第六条规定，其中，工作年限要求可以由主管机关（部门）或者单位结合实际具体确定。内设业务机构负责人，应当具有与本岗位相关的专业背景或者从事相关专业工作的经历。\n第八条 专业技术人员直接提任领导人员的，应当具有相应的专业技术岗位任职经历和一定的管理工作经历。其中：\n（一）提任六级管理岗位领导人员的，一般应当已聘用副高级以上专业技术岗位或者5年以上中级专业技术岗位。\n（二）提任五级管理岗位领导人员的，一般应当已聘用正高级专业技术岗位或者2年以上副高级专业技术岗位。\n（三）提任四级以上管理岗位领导人员的，一般应当已聘用正高级专业技术岗位或者5年以上副高级专业技术岗位。\n第九条 特别优秀的，或者因国家重大战略、重大工程、重大项目、重点任务选拔高精尖缺人才担任领导人员以及内设机构负责人等工作特殊需要的，可以根据有关规定适当放宽任职资格。\n放宽任职资格以及从专业技术岗位到管理岗位担任领导班子正职或者四级以上管理岗位领导职务的，应当从严掌握，并报上级组织（人事）部门同意。","level":1},{"name":"第三章 选拔任用","text":"第十条 主管机关（部门）党委（党组）及其组织（人事）部门按照干部管理权限，根据分析研判和动议、民主推荐、考察、讨论决定、任职等有关程序和要求组织实施选拔任用工作。坚持正确选人用人导向，严格标准条件和程序，充分发挥党组织领导和把关作用。\n具体程序和要求，参照《党政领导干部选拔任用工作条例》及有关规定，结合单位实际确定。\n第十一条 选拔宣传思想文化系统事业单位领导人员，一般采取单位内部推选、外部选派的方式进行。根据工作需要和岗位特点，可以采取竞争（聘）上岗、公开选拔（聘）等方式拓宽选人用人视野。\n探索从混合所有制文化企业、非公有制文化企业等发现高层次急需紧缺人才，按程序聘任为专业领导人员，对人选严格把关，并报上级组织（人事）部门同意。\n第十二条 严格执行考察制度，坚持把政治标准放在首位，做深做实政治素质考察，着重了解贯彻落实党中央决策部署、坚守意识形态阵地和作风品行、廉洁自律等情况，深入了解专业素养、管理能力、职业精神和工作实绩等情况，客观准确地作出评价，严把政治关、品行关、能力关、作风关、廉洁关。\n第十三条 任用领导人员，区别不同情况实行选任制、委任制、聘任制。\n聘任制领导人员在任职资格条件、选拔任用程序和要求等方面应当按照本办法执行，在薪酬待遇、聘期等方面可以结合实际探索采取灵活方式。\n第十四条 领导班子和领导人员一般应当实行任期制和任期目标责任制。每个任期一般为3至5年。领导人员在同一岗位连续任职一般不超过10年，工作特殊需要的，按照干部管理权限经批准后可以适当延长任职年限。领导人员在任期内应当保持相对稳定，一般应当任满1个任期。做好领导班子主要负责人变动交接工作。\n第十五条 领导班子的任期目标，应当涵盖领导班子各项职责，体现政治方向和宣传导向、作品产品的生产和服务、科学管理和改革创新、队伍建设和党的建设等内容，注重打基础、利长远、求实效，清晰明确、便于考核，具体内容根据单位实际确定。领导人员的任期目标，根据领导班子任期目标和岗位职责等确定。","level":1},{"name":"第四章 考核评价","text":"第十六条 完善体现宣传思想文化系统事业单位特点的领导班子和领导人员考核评价制度，注意差异化、增强针对性，切实发挥考核指挥棒作用。\n对领导班子和领导人员的考核，主要是年度考核和任期考核，根据工作实际开展平时考核、专项考核。\n第十七条 考核评价应当贯彻落实党建工作责任制和意识形态工作责任制有关要求，以岗位职责、任期目标为依据，以日常管理为基础，以公益服务效果为重点，注重听取服务对象的意见和评价，把政治思想建设考核放在首位，强化意识形态阵地管理责任，突出党建工作实效，注重社会效益和业绩导向。\n坚持党建工作与业务工作一体考核，实行党组织书记抓基层党建工作述职评议考核制度。\n第十八条 根据社科理论、新闻出版、广播电视、文化艺术、对外宣传和网络信息传播等不同领域单位特点，聚焦主责主业，科学合理确定考核内容和指标。注意改进方法，优化程序，提高考核工作质量和效率。\n第十九条 领导班子年度考核和任期考核的评价等次，分为优秀、良好、一般、较差。领导人员年度考核和任期考核的评价等次，分为优秀、合格、基本合格、不合格。\n领导班子年度考核优秀等次比例一般不超过参加考核领导班子总数的30%，领导人员年度考核优秀等次比例一般不超过参加考核领导人员总人数的25%。\n所在领导班子为优秀等次的，领导人员评为优秀等次的比例可以适当上调，一般不超过30%；所在领导班子为一般等次的，领导人员评为优秀等次的比例不得超过20%，主要负责人一般不得确定为优秀等次；所在领导班子为较差等次的，领导人员一般不得确定为优秀等次，主要负责人一般不得确定为合格及以上等次。\n第二十条 考核评价结果应当以适当方式向领导班子和领导人员反馈，并作为领导班子建设和领导人员选拔任用、培养教育、管理监督、激励约束、追责问责等的重要依据。","level":1},{"name":"第五章 职业发展和激励保障","text":"第二十一条 完善宣传思想文化系统事业单位领导人员培养教育制度，充分利用党校（行政学院）、干部学院等机构，重点加强党的理论教育、党性教育和政策业务、领导科学等方面的培训，采取多种方式加强实践锻炼，着力提高政治素质、管理能力和专业水平。原则上每5年对领导人员培训全覆盖。\n第二十二条 完善领导人员交流制度，积极推进系统内单位之间领导人员交流，统筹推进与党政机关、国有企业以及其他事业单位之间领导人员交流。\n对重要宣传舆论阵地和重要岗位领导人员有计划地进行交流，对专业性强的领导人员交流应当注意发挥其专业特长。\n第二十三条 健全培养选拔优秀年轻干部常态化工作机制，按照拓宽来源、优化结构、改进方式、提高质量的要求，积极发现和培养政治素质好、业务水平高、管理能力强、有文化情怀、善于改革创新的优秀年轻人才，切实加强教育管理监督。\n第二十四条 领导人员应当确保主要精力和时间用于单位管理工作，确因工作需要兼职的，严格按照有关规定执行。\n完善领导人员后续职业发展制度，对任期结束后未达到退休年龄界限，适合继续从事专业工作的，在业务培训、项目经费、团队建设等方面给予必要支持；其他退出领导岗位人员，根据工作需要和本人实际，作出适当安排。\n第二十五条 落实工资正常增长机制，完善领导人员收入分配办法，根据单位类别和经费来源等，结合考核情况合理确定绩效工资水平，使其收入与履职情况和事业发展相联系，与本单位职工的平均收入水平保持合理关系。\n第二十六条 领导人员在履行单位管理职责、承担专项重要工作、应对重大突发事件等方面表现突出、作出显著成绩和贡献的，按照有关规定给予表彰奖励。\n主管机关（部门）可以根据实际情况，探索行之有效的措施，激励领导人员担当作为、干事创业。\n第二十七条 加强人文关怀，关心领导人员身心健康，帮助解决实际困难。加大正向激励力度，营造鼓励探索、支持创新的良好氛围。","level":1},{"name":"第六章 监督约束","text":"第二十八条 主管机关（部门）党委（党组）及纪检监察机关、组织（人事）部门等按照管理权限和职责分工，综合运用巡视巡察、审计等多种方式，加强对宣传思想文化系统事业单位领导班子和领导人员特别是主要负责人的监督。\n加强政治监督，重点监督践行“两个维护”，贯彻落实党中央重大决策部署，坚持正确的政治方向和宣传导向，落实党建工作责任制和意识形态工作责任制，严肃党内政治生活等情况。\n加强权力运行的监督，重点监督贯彻执行民主集中制，落实“三重一大”决策制度，履行公益性职责，依法依规办事，公道正派选人用人等情况。加大对宣传资源分配、评奖评优、影视剧购销、广告经营、新闻采编、课题项目、资金使用、职务（职称）评聘以及重流量轻质量、重收入轻导向、“吃空饷”等方面问题的监督力度。\n加强作风和廉洁的监督，重点监督落实中央八项规定及其实施细则精神，转作风、正学风、改文风，道德品行，廉洁自律等情况。\n第二十九条 完善单位党的领导体制机制，健全议事决策机制，明确决策事项清单，完善单位内部治理结构和内控机制。\n推进单位事务公开，注意发挥职工（代表）大会等组织在单位民主管理方面的作用，畅通职工群众参与讨论单位事务的渠道。\n第三十条 实行事业单位领导人员任职回避、履职回避制度，回避范围和情形按照有关规定执行。","level":1},{"name":"第七章 退出","text":"第三十一条 领导人员达到任职年龄界限或者退休年龄界限的，应当按照有关规定程序办理免职（退休）手续。正职领导人员特别优秀的，根据工作需要和本人履职情况，按照有关规定经批准可以延迟免职（退休）。\n第三十二条 按照《推进领导干部能上能下规定》等有关规定，结合行业实际，领导人员存在贯彻执行党的宣传思想文化工作方针政策、意识形态工作责任制、上级党组织指示和决定不及时不得力，在大是大非问题上立场摇摆、态度暧昧或无动于衷、置身事外，在错误言行面前不抵制、不斗争，明哲保身、当老好人，擅自公开发表与中央精神不符的言论、文章、作品，应对处置重大突发事件、舆情事件不力或者有其他违背社会公德、职业道德、家庭美德行为造成不良社会影响等情形，经综合分析研判，被认定为不适宜担任现职的，应当按照有关规定及时予以调整。\n第三十三条 领导人员退出领导岗位从事专业工作的，确因工作需要，由本单位党委（党组）研究并报上级组织（人事）部门同意，在出国（境）、兼职等方面可以不再按照领导人员管理，执行专业技术人员相关规定。\n第三十四条 实行领导人员辞职制度，辞职程序和辞职后从业限制等按照有关规定执行，防范政商“旋转门”、“逃逸式辞职”等问题。","level":1},{"name":"第八章 附则","text":"第三十五条 本办法由中央组织部、中央宣传部负责解释。\n第三十六条 本办法自发布之日起施行。","level":1}]},{"id":"r0556","sections":[{"name":"中共中央办公厅转发《中央宣传部、中央组织部关于认真组织学习〈习近平谈治国理政〉第二卷的通知》","text":"点击观看视频","level":1},{"name":"","text":"近日，中共中央办公厅转发了《中央宣传部、中央组织部关于认真组织学习〈习近平谈治国理政〉第二卷的通知》，并发出通知，要求各地区各部门结合实际认真贯彻落实。\n《中央宣传部、中央组织部关于认真组织学习〈习近平谈治国理政〉第二卷的通知》全文如下。\n党的十八大以来，以习近平同志为核心的党中央团结带领全党全国各族人民，推动党和国家事业取得历史性成就、发生历史性变革，中国特色社会主义进入新时代。在治国理政新的实践中，以习近平同志为主要代表的中国共产党人，顺应时代发展，从理论和实践结合上系统回答了新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义这个重大时代课题，创立了习近平新时代中国特色社会主义思想。党的十九大把习近平新时代中国特色社会主义思想确立为党必须长期坚持的指导思想，实现了党的指导思想又一次与时俱进。\n习近平总书记是习近平新时代中国特色社会主义思想的主要创立者。党的十八大以来，在领导全党全国推进党和国家事业的实践中，习近平总书记以马克思主义政治家、理论家的深刻洞察力、敏锐判断力和战略定力，提出了一系列具有开创性意义的新理念新思想新战略，为习近平新时代中国特色社会主义思想的创立发挥了决定性作用、作出了决定性贡献。\n2014年9月出版发行的《习近平谈治国理政》第一卷，收入了习近平总书记在党的十八大闭幕后至2014年6月13日期间的重要著作，受到国内外读者的广泛关注和好评。此后3年多来，习近平总书记又发表一系列重要讲话，深刻回答了一系列方向性、根本性、全局性、战略性重大问题，使党的创新理论更加丰富、更加系统。\n经党中央批准，中央宣传部会同中央文献研究室、中国外文局，编辑出版了《习近平谈治国理政》第二卷。该书收入了习近平总书记在2014年8月18日至2017年9月29日期间的讲话、谈话、演讲、批示、贺电等99篇，分为17个专题。该书生动记录了以习近平同志为核心的党中央团结带领全党全国各族人民在新时代坚持和发展中国特色社会主义的伟大实践，集中反映了习近平新时代中国特色社会主义思想的发展脉络和主要内容。《习近平谈治国理政》第二卷的出版发行，对于推动广大干部群众深入学习领会习近平新时代中国特色社会主义思想，在全党全社会兴起学习宣传贯彻党的十九大精神热潮，具有重要意义。\n学习贯彻习近平新时代中国特色社会主义思想是当前和今后一个时期全党的重大政治任务，也是增强政治意识、大局意识、核心意识、看齐意识，维护习近平总书记党中央的核心、全党的核心地位，维护党中央权威和集中统一领导，在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致的实际举措。各级党组织要把《习近平谈治国理政》第二卷和先期出版的《习近平谈治国理政》第一卷，作为深入学习领会习近平新时代中国特色社会主义思想和党的十九大精神的权威读本，切实组织好学习。要以高度的使命感和责任感，系统学习、深入学习，切实把思想和行动统一到习近平新时代中国特色社会主义思想上来，统一到党的十九大确定的重大决策部署上来。各级党委（党组）理论学习中心组要带头学好用好这部重要著作，推动全党深入领会习近平新时代中国特色社会主义思想的时代背景、科学体系、精神实质、实践要求，深入领会这一思想的重大政治意义、理论意义、实践意义，不断提高全党马克思主义水平。要大力弘扬理论联系实际的优良学风，强化问题意识、树立问题导向，着力增强学习本领、政治领导本领、改革创新本领、科学发展本领、依法执政本领、群众工作本领、狠抓落实本领、驾驭风险本领。各级党校、干部学院、行政学院要将其纳入培训教学内容，各高等学校要将其作为师生理论学习教育的重要材料，各级党委讲师团要组织好对基层党员和群众的宣讲活动。\n延伸阅读\n《习近平谈治国理政》第二卷中英文版出版发行\n《习近平谈治国理政》第二卷出版说明\n《习近平谈治国理政》第二卷讲了什么\n《习近平谈治国理政》第一卷","level":0}]},{"id":"r0557","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于做好2022年元旦春节期间有关工作的通知》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于做好2022年元旦春节期间有关工作的通知》。全文如下：","level":1},{"name":"","text":"2022年是我国踏上全面建设社会主义现代化国家、向第二个百年奋斗目标进军新征程的重要一年，年初将举办北京冬奥会、冬残奥会，做好元旦春节期间各项工作十分重要。各地区各部门要以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届历次全会精神，在做好疫情防控的前提下，统筹做好节日期间各项工作，确保人民群众度过喜庆安康的节日。经党中央、国务院同意，现将有关事项通知如下。\n一、毫不放松做好疫情防控工作，坚决防止疫情反弹蔓延。坚持“外防输入、内防反弹”，坚持常态化精准防控和局部应急处置相结合，减少“两节”期间人员流动和聚集。加强口岸城市疫情防控，严格落实人、物、环境同防和空港口岸分流措施，加强进口冷链食品市场监管，严防境外疫情输入。加强疫情监测预警，强化旅途、餐饮、公园景区、商场超市等重点环节和场所疫情防控。落实预检分诊和首诊负责制，严格发热病人闭环管理，强化医疗救治服务。引导群众增强自身健康第一责任人意识，坚持少聚集、勤洗手、戴口罩、用公筷等卫生习惯，做好个人防护。\n二、加大兜底性保障力度，真心真情关爱困难群众。按时足额发放基本养老金和失业保险金，认真落实各项社会救助政策，保障困难群众基本生活，坚决兜牢民生底线。组织好社会救助和保障标准与物价上涨挂钩联动机制实施工作。及时落实“煤改气”、“煤改电”补贴，加大对困难群体取暖补助力度，确保群众温暖过冬。加强对低保、特困、重病重残、流浪乞讨、留守儿童等困难群众的救助帮扶，加强对脱贫不稳定人口、突发严重困难户的监测帮扶，及时向受灾群众发放救灾资金物资和冬春生活救助，使他们感受到党和政府的温暖。开展冬季专项行动，加大对拖欠农民工工资的治理力度，切实维护农民工合法权益。\n三、强化市场保供稳价，满足群众节日消费需求。统筹安排好煤电油气运保障供应，切实增加煤炭特别是电煤供应，有效提升电力供应保障能力，稳定增加成品油生产供应，保证北方地区取暖用气。全面落实粮食安全党政同责和“菜篮子”市长负责制，加强市场运行监测，切实做好粮油肉蛋奶果蔬等重要民生商品保供稳价工作，确保生活必需品供应不断档、不脱销。丰富节日市场供给，满足人民群众多样化消费需求。严格落实食品安全“四个最严”要求，保障“舌尖上的安全”。加强节日重点消费品质量监管和价格监管，依法查处侵害消费者权益违法行为，维护良好市场秩序。\n四、大力唱响主旋律，丰富群众精神文化生活。围绕宣传贯彻党的十九届六中全会精神组织开展形式多样、内涵丰富的文化文艺活动，激发广大群众热爱党、热爱祖国、热爱社会主义的热情，凝聚团结进取、奋发图强的精神力量。开展“我们的中国梦”——文化进万家活动、“我们的新时代”主题作品创作展播活动、“文化进万家——视频直播家乡年”活动，弘扬社会主义核心价值观和中华优秀传统文化，讴歌新时代。加强执法，维护文化和旅游节日市场秩序。\n五、统筹安排春运工作，保障群众平安有序出行。严格交通运输疫情防控要求，按照引导错峰出行、降低旅途风险、加强人员防护的原则，组织做好春运工作。细化落实客运场站和交通运输工具消毒通风、信息登记、设置隔离区等措施，加强客运一线服务人员日常健康监测和定期核酸检测，制定完善应急预案。加强重点时段、热点路线运力供给，优化运输方式衔接、客运枢纽服务、防疫检查站点设置，减少车辆拥堵、人员聚集。落实健康码全国“一码通行”，保障老年人等特殊群体在智能化条件下的出行。针对极端天气做好应急准备，防止发生大范围旅客、车辆滞留。强化运输安全监管，保障群众出行安全。\n六、树牢底线思维，抓紧抓实安全生产工作。坚持人民至上、生命至上，严格落实安全生产责任和管理制度，强化安全隐患排查治理，坚决遏制重特大事故发生。狠抓重点行业领域安全防范，加强特种设备、建筑施工、危险化学品、烟花爆竹、渔业船舶等安全监管，严格大型活动审批，消除商住混合楼、大型综合体等人员密集场所消防安全隐患，扎实开展燃气安全整治。突出抓好能源保供安全，对高风险矿井落实专人盯守，严厉打击违法开采行为，加强油气存储运输等危险源巡查。加强极寒天气和雨雪冰冻等灾害、森林草原火险的监测预警和应急处置，保障人民群众生命财产安全。\n七、防范处置矛盾问题，全力维护社会大局稳定。坚持和发展新时代“枫桥经验”，围绕重点领域、重点群体深入开展矛盾纠纷排查化解，落实属地管理责任和源头治理措施，把矛盾隐患化解在当地、解决在基层。把握岁末年初社会治安规律特点，结合常态化开展扫黑除恶斗争，依法严厉打击涉枪涉爆、电信网络诈骗、跨境赌博、“黄赌毒”、“盗抢骗”、“食药环”等影响群众安全感的突出违法犯罪，确保节日期间社会治安平稳有序。加强社会面巡防巡控，强化人员密集场所安全防控，最大限度消除治安隐患和盲点。统筹警卫安保和疫情防控工作，切实筑牢冬奥安保防线。\n八、坚持勤俭文明过节，倡导良好社会风尚。教育引导广大党员干部特别是领导干部带头转作风树新风，自觉反对特权思想、特权现象，自觉反对餐饮浪费、铺张奢侈，严格家教家风。推动移风易俗，倡导勤俭节约，坚决抵制大操大办、高额彩礼、厚葬薄养、封建迷信、不文明祭扫等不良习俗。关心关爱基层干部特别是工作在困难艰苦地区和急难险重任务一线的同志，做好对因公去世基层干部家属的走访慰问、照顾救助和长期帮扶工作，做好“共和国勋章”、国家荣誉称号和“七一勋章”获得者有关待遇落实和走访慰问工作，加强党内激励关怀帮扶。\n九、持续推进正风肃纪，严防“节日腐败”。严格执行中央八项规定及其实施细则精神，严查快处违规吃喝、违规收送礼品礼金、违规使用公车、公款旅游等问题，严肃惩治违规发放津贴补贴或者福利，注意纠治快递送礼、收送电子红包、“不吃公款吃老板”等隐形变异行为，持续释放从严信号。聚焦疫情防控、安全生产、灾害监测预警、应急处置、民生保障、政务服务等，坚决纠治影响党中央决策部署贯彻落实、漠视侵害群众利益的形式主义、官僚主义。对以总结部署工作等名义随意向基层派任务要材料、同一内容视频会议层层套开、“指尖上的形式主义”等问题及时督促整改，切实为基层减负。严格执行“十严禁”换届纪律要求，确保换届工作清明清朗。\n十、加强应急值守，保证各项工作正常运转。严格执行24小时专人值班和领导干部在岗带班、外出报备等制度，应急值守任务较重、与人民群众生产生活密切相关的单位要健全应急值守联动机制。提前做好应急保障准备，遇有重特大突发事件或者其他重要紧急情况，要第一时间请示报告并及时妥善处置。直接服务群众的单位要安排好节日期间值班执勤并保证服务质量。\n各地区各部门要增强“四个意识”，提高政治判断力、政治领悟力、政治执行力，忠于职守、尽职尽责，确保本通知精神落到实处。","level":0}]},{"id":"r0558","sections":[{"name":"中共中央办公厅印发《中国侨联改革方案》","text":"近日，中共中央办公厅印发《中国侨联改革方案》（以下简称《方案》）。《方案》强调，侨联是党领导的人民团体，是党和政府联系广大归侨侨眷和海外侨胞的桥梁和纽带，是团结服务归侨侨眷和海外侨胞的群众组织。","level":1},{"name":"","text":"党中央历来重视发挥广大归侨侨眷和海外侨胞的独特作用，高度重视做好归侨侨眷和海外侨胞工作。党的十八大以来，以习近平同志为核心的党中央对做好新形势下的归侨侨眷和海外侨胞工作、推进中国侨联改革作出重要部署。习近平总书记多次作出重要批示指示，为中国侨联改革指方向、定方针、提任务。中央政治局常委会会议、中央全面深化改革领导小组会议、中央书记处办公会议分别审议了《方案》。\n《方案》明确了中国侨联改革的指导思想、基本原则、主要目标。《方案》提出，要全面贯彻落实党的十八大和十八届三中、四中、五中、六中全会精神，深入学习贯彻习近平总书记系列重要讲话精神，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，坚定不移走中国特色社会主义群团发展道路，以增强政治性、先进性、群众性为目标，高举爱国主义和中国特色社会主义旗帜，坚持国内、海外工作并重，老侨、新侨工作并重，深化拓展海外工作，拓展新侨工作，聚焦体制机制，锐意改革创新，充分发挥凝聚侨心、汇集侨智、发挥侨力、维护侨益的独特作用，最大限度把广大归侨侨眷和海外侨胞团结起来，最大限度把他们爱国爱乡的积极性调动起来，最大限度把他们促进改革开放和社会主义现代化建设的独特优势发挥出来，为夺取全面建成小康社会决胜阶段伟大胜利、实现中华民族伟大复兴中国梦贡献力量。侨联改革必须坚持党的领导、把牢正确方向，坚持服务宗旨、激发组织活力，坚持问题导向、着力转变作风，坚持整体推进、切实履行职责，从侨联的群众性、民间性、涉外性、统战性特点出发，推进侨联组织创新、工作创新，打造侨联工作品牌，更好履行侨联服务经济发展、依法维护侨益、拓展海外联谊、积极参政议政、弘扬中华文化、参与社会建设职能，切实当好党和政府联系广大归侨侨眷和海外侨胞的桥梁纽带。\n《方案》从四个方面、十七个领域提出了中国侨联的改革措施。第一，改革调整中国侨联领导机构、机关设置和运行机制。增强侨联代表大会的代表性和广泛性，进一步增强全国归侨侨眷代表大会代表中基层代表的比重，注重吸收基层组织、科研院所、大专院校、各类园区、侨资侨企、新经济组织、新社会组织中的新侨和青年代表人物，优化中国侨联委员和常委结构。调整优化侨联领导机关和事业单位设置，根据侨情变化，聚焦工作主业，优化工作职能，提高工作效率。推动形成侨务工作合力，按照党和国家侨务工作方针政策和整体规划，积极参与创新社会治理，就涉侨政策法规提出意见和建议，与各涉侨部门、外交部和驻外使领馆加强协作配合。\n第二，改革中国侨联组织人事制度，加强干部队伍作风建设。打造专职、挂职、兼职相结合的侨联干部队伍，坚持重心下移，为地方侨联“减上补下”作出示范；突出“知侨、懂侨、爱侨”，坚持五湖四海、德才兼备，打破年龄、学历、身份、职级限制，不拘一格选拔侨联干部；按照干部管理权限，建立专职干部、挂职和兼职干部选任制度；专职干部应注重专业化，适当增加流动性；挂职、兼职干部不对应行政级别；实施干部分类管理，建立专职、挂职、兼职侨联干部激励和约束机制；参与协商和推荐人大归侨代表、提名侨联界政协委员人选工作；在大力培养选拔有侨身份的干部的同时，积极培养选拔非侨身份的侨联工作者。加强侨联干部作风建设，深入开展“学党章党规、学系列讲话，做合格党员”学习教育，加强侨联工作网络培训，着力提高侨联干部践行“三严三实”能力；建立直接联系服务侨界群众制度，中国侨联及各省区市侨联要把侨联干部直接联系一定数量的归侨侨眷和海外侨胞作为一项重要制度，与归侨侨眷和海外侨胞交朋友，及时倾听意见、反映诉求，帮助解决现实困难；建立基层联系点制度，形成上级侨联干部下基层常态化。健全由地方党委领导的侨联工作领导体制。\n第三，提升侨联服务大局、服务侨界群众的能力和水平。强化对侨界群众的思想政治引领，用党的理论和路线方针政策，特别是党的十八大以来党中央治国理政的新理念新思想新战略引领归侨侨眷；以爱国主义为核心，广泛开展中国特色社会主义和中国梦宣传教育，积极培育和践行社会主义核心价值观。服务国家外交工作大局，引导和鼓励海外侨胞向住在国社会公众传播中国和平发展理念；把加强新侨队伍建设和新侨团事业发展作为重点，引导和支持海外侨胞积极融入当地主流社会。聚焦新侨创新创业扶助，深化“创业中华”品牌，引导侨界群众创新创业，践行创新、协调、绿色、开放、共享发展理念，适应经济发展新常态，为加快转变经济发展方式、推进供给侧结构性改革、推动经济社会持续健康发展献策献力；关注海外人才回国发展遇到的问题；配合做好中外经贸合作等工作，积极服务“一带一路”建设；关注国内侨资企业走出去，建立健全与海外和港澳台侨商的联系网络；关注海外侨胞在异国他乡生活、工作、学习面临的困难；发挥侨联法律顾问委员会海外律师团作用。拓展中华优秀文化传播，讲好中国故事，传播好中国声音。维护侨界群众合法权益，引导侨界群众运用法治思维和法治方式维护权益、解决问题。开展精准扶贫和困难帮扶，实施惠侨助侨行动，深化“侨爱心工程”，加强与工会、共青团、妇联等群团组织合作。\n第四，夯实侨联基层基础，增强侨联组织活力。切实扩大侨联的组织覆盖，突出重点侨乡，加强薄弱地区；推动把侨联基层组织建设纳入各级党委党建工作规划；指导和支持各地在乡镇（街道）、村（社区）、非公有制经济组织、社会组织以及高校、科研院所、科技园区、创业园区、楼宇等探索建立各种形式的基层侨联组织。加强侨联所属社团组织建设，发挥各级侨联所属侨商联合会、青年委员会、特聘专家委员会、法律顾问委员会、留学生亲属联谊会、归侨联谊会、华侨基金会、华侨历史学会、华侨国际文化交流促进会等社团的独特作用。加快建设“网上侨联”，大力建设网上“侨胞之家”，注重应用互联网思维和技术开展联系、引导、服务侨社和侨胞工作，开设中国侨联官方微博和微信公众号，推广和完善“侨联通”，强化侨联网上工作内容供给。建立健全海外联谊机制，切实发挥中国侨联海外顾问、海外委员在海外侨胞中的凝聚引领作用，支持和鼓励地方侨联密切与海外侨胞的联系，注重发挥基层侨联的作用。改进和创新侨联工作方式方法，扩大侨界参与，让侨界群众当主角；突出工作重点，整合工作项目，整合各方资源，丰富工作手段，推行项目管理，建立侨联工作科学评价体系，完善侨联宣传表彰体系和机制，加强侨联工作研究。\n《方案》要求，要加强党的领导，深入细致做好机关干部思想政治工作，加强侨联改革宣传工作，选准改革突破口，细化路线图和时间表，推动改革取得实质性成效，实现侨联工作创新发展。","level":0}]},{"id":"r0559","sections":[{"name":"关于进一步弘扬科学家精神加强作风和学风建设的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于进一步弘扬科学家精神加强作风和学风建设的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于进一步弘扬科学家精神加强作风和学风建设的意见》全文如下。\n为激励和引导广大科技工作者追求真理、勇攀高峰，树立科技界广泛认可、共同遵循的价值理念，加快培育促进科技事业健康发展的强大精神动力，在全社会营造尊重科学、尊重人才的良好氛围，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，以塑形铸魂科学家精神为抓手，切实加强作风和学风建设，积极营造良好科研生态和舆论氛围，引导广大科技工作者紧密团结在以习近平同志为核心的党中央周围，增强“四个意识”，坚定“四个自信”，做到“两个维护”，在践行社会主义核心价值观中走在前列，争做重大科研成果的创造者、建设科技强国的奉献者、崇高思想品格的践行者、良好社会风尚的引领者，为实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦作出更大贡献。\n（二）基本原则。坚持党的领导，提高政治站位，强化政治引领，把党的领导贯穿到科技工作全过程，筑牢科技界共同思想基础。坚持价值引领，把握主基调，唱响主旋律，弘扬家国情怀、担当作风、奉献精神，发挥示范带动作用。坚持改革创新，大胆突破不符合科技创新规律和人才成长规律的制度藩篱，营造良好学术生态，激发全社会创新创造活力。坚持久久为功，汇聚党政部门、群团组织、高校院所、企业和媒体等各方力量，推动作风和学风建设常态化、制度化，为科技工作者潜心科研、拼搏创新提供良好政策保障和舆论环境。\n（三）主要目标。力争1年内转变作风改进学风的各项治理措施得到全面实施，3年内取得作风学风实质性改观，科技创新生态不断优化，学术道德建设得到显著加强，新时代科学家精神得到大力弘扬，在全社会形成尊重知识、崇尚创新、尊重人才、热爱科学、献身科学的浓厚氛围，为建设世界科技强国汇聚磅礴力量。","level":1},{"name":"二、自觉践行、大力弘扬新时代科学家精神","text":"（四）大力弘扬胸怀祖国、服务人民的爱国精神。继承和发扬老一代科学家艰苦奋斗、科学报国的优秀品质，弘扬“两弹一星”精神，坚持国家利益和人民利益至上，以支撑服务社会主义现代化强国建设为己任，着力攻克事关国家安全、经济发展、生态保护、民生改善的基础前沿难题和核心关键技术。\n（五）大力弘扬勇攀高峰、敢为人先的创新精神。坚定敢为天下先的自信和勇气，面向世界科技前沿，面向国民经济主战场，面向国家重大战略需求，抢占科技竞争和未来发展制高点。敢于提出新理论、开辟新领域、探寻新路径，不畏挫折、敢于试错，在独创独有上下功夫，在解决受制于人的重大瓶颈问题上强化担当作为。\n（六）大力弘扬追求真理、严谨治学的求实精神。把热爱科学、探求真理作为毕生追求，始终保持对科学的好奇心。坚持解放思想、独立思辨、理性质疑，大胆假设、认真求证，不迷信学术权威。坚持立德为先、诚信为本，在践行社会主义核心价值观、引领社会良好风尚中率先垂范。\n（七）大力弘扬淡泊名利、潜心研究的奉献精神。静心笃志、心无旁骛、力戒浮躁，甘坐“冷板凳”，肯下“数十年磨一剑”的苦功夫。反对盲目追逐热点，不随意变换研究方向，坚决摒弃拜金主义。从事基础研究，要瞄准世界一流，敢于在世界舞台上与同行对话；从事应用研究，要突出解决实际问题，力争实现关键核心技术自主可控。\n（八）大力弘扬集智攻关、团结协作的协同精神。强化跨界融合思维，倡导团队精神，建立协同攻关、跨界协作机制。坚持全球视野，加强国际合作，秉持互利共赢理念，为推动科技进步、构建人类命运共同体贡献中国智慧。\n（九）大力弘扬甘为人梯、奖掖后学的育人精神。坚决破除论资排辈的陈旧观念，打破各种利益纽带和裙带关系，善于发现培养青年科技人才，敢于放手、支持其在重大科研任务中“挑大梁”，甘做致力提携后学的“铺路石”和领路人。","level":1},{"name":"三、加强作风和学风建设，营造风清气正的科研环境","text":"（十）崇尚学术民主。鼓励不同学术观点交流碰撞，倡导严肃认真的学术讨论和评论，排除地位影响和利益干扰。开展学术批评要开诚布公，多提建设性意见，反对人身攻击。尊重他人学术话语权，反对门户偏见和“学阀”作风，不得利用行政职务或学术地位压制不同学术观点。鼓励年轻人大胆提出自己的学术观点，积极与学术权威交流对话。\n（十一）坚守诚信底线。科研诚信是科技工作者的生命。高等学校、科研机构和企业等要把教育引导和制度约束结合起来，主动发现、严肃查处违背科研诚信要求的行为，并视情节追回责任人所获利益，按程序记入科研诚信严重失信行为数据库，实行“零容忍”，在晋升使用、表彰奖励、参与项目等方面“一票否决”。科研项目承担者要树立“红线”意识，严格履行科研合同义务，严禁违规将科研任务转包、分包他人，严禁随意降低目标任务和约定要求，严禁以项目实施周期外或不相关成果充抵交差。严守科研伦理规范，守住学术道德底线，按照对科研成果的创造性贡献大小据实署名和排序，反对无实质学术贡献者“挂名”，导师、科研项目负责人不得在成果署名、知识产权归属等方面侵占学生、团队成员的合法权益。对已发布的研究成果中确实存在错误和失误的，责任方要以适当方式予以公开和承认。不参加自己不熟悉领域的咨询评审活动，不在情况不掌握、内容不了解的意见建议上署名签字。压紧压实监督管理责任，有关主管部门和高等学校、科研机构、企业等单位要建立健全科研诚信审核、科研伦理审查等有关制度和信息公开、举报投诉、通报曝光等工作机制。对违反项目申报实施、经费使用、评审评价等规定，违背科研诚信、科研伦理要求的，要敢于揭短亮丑，不迁就、不包庇，严肃查处、公开曝光。\n（十二）反对浮夸浮躁、投机取巧。深入科研一线，掌握一手资料，不人为夸大研究基础和学术价值，未经科学验证的现象和观点，不得向公众传播。论文等科研成果发表后1个月内，要将所涉及的实验记录、实验数据等原始数据资料交所在单位统一管理、留存备查。参与国家科技计划（专项、基金等）项目的科研人员要保证有足够时间投入研究工作，承担国家关键领域核心技术攻关任务的团队负责人要全时全职投入攻关任务。科研人员同期主持和主要参与的国家科技计划（专项、基金等）项目（课题）数原则上不得超过2项，高等学校、科研机构领导人员和企业负责人作为项目（课题）负责人同期主持的不得超过1项。每名未退休院士受聘的院士工作站不超过1个、退休院士不超过3个，院士在每个工作站全职工作时间每年不少于3个月。国家人才计划入选者、重大科研项目负责人在聘期内或项目执行期内擅自变更工作单位，造成重大损失、恶劣影响的要按规定承担相应责任。兼职要与本人研究专业相关，杜绝无实质性工作内容的各种兼职和挂名。高等学校、科研机构和企业要加强对本单位科研人员的学术管理，对短期内发表多篇论文、取得多项专利等成果的，要开展实证核验，加强核实核查。科研人员公布突破性科技成果和重大科研进展应当经所在单位同意，推广转化科技成果不得故意夸大技术价值和经济社会效益，不得隐瞒技术风险，要经得起同行评、用户用、市场认。\n（十三）反对科研领域“圈子”文化。要以“功成不必在我”的胸襟，打破相互封锁、彼此封闭的门户倾向，防止和反对科研领域的“圈子”文化，破除各种利益纽带和人身依附关系。抵制各种人情评审，在科技项目、奖励、人才计划和院士增选等各种评审活动中不得“打招呼”、“走关系”，不得投感情票、单位票、利益票，一经发现这类行为，立即取消参评、评审等资格。院士等高层次专家要带头打破壁垒，树立跨界融合思维，在科研实践中多做传帮带，善于发现、培养青年科研人员，在引领社会风气上发挥表率作用。要身体力行、言传身教，积极履行社会责任，主动走近大中小学生，传播爱国奉献的价值理念，开展科普活动，引领更多青少年投身科技事业。","level":1},{"name":"四、加快转变政府职能，构建良好科研生态","text":"（十四）深化科技管理体制机制改革。政府部门要抓战略、抓规划、抓政策、抓服务，树立宏观思维，倡导专业精神，减少对科研活动的微观管理和直接干预，切实把工作重点转到制定政策、创造环境、为科研人员和企业提供优质高效服务上。坚持刀刃向内，深化科研领域政府职能转变和“放管服”改革，建立信任为前提、诚信为底线的科研管理机制，赋予科技领军人才更大的技术路线决策权、经费支配权、资源调动权。优化项目形成和资源配置方式，根据不同科学研究活动的特点建立稳定支持、竞争申报、定向委托等资源配置方式，合理控制项目数量和规模，避免“打包”、“拼盘”、任务发散等问题。建立健全重大科研项目科学决策、民主决策机制，确定重大创新方向要围绕国家战略和重大需求，广泛征求科技界、产业界等意见。对涉及国家安全、重大公共利益或社会公众切身利益的，应充分开展前期论证评估。建立完善分层分级责任担当机制，政府部门要敢于为科研人员的探索失败担当责任。\n（十五）正确发挥评价引导作用。改革科技项目申请制度，优化科研项目评审管理机制，让最合适的单位和人员承担科研任务。实行科研机构中长期绩效评价制度，加大对优秀科技工作者和创新团队稳定支持力度，反对盲目追求机构和学科排名。大幅减少评比、评审、评奖，破除唯论文、唯职称、唯学历、唯奖项倾向，不得简单以头衔高低、项目多少、奖励层次等作为前置条件和评价依据，不得以单位名义包装申报项目、奖励、人才“帽子”等。优化整合人才计划，避免相同层次的人才计划对同一人员的重复支持，防止“帽子”满天飞。支持中西部地区稳定人才队伍，发达地区不得片面通过高薪酬高待遇竞价抢挖人才，特别是从中西部地区、东北地区挖人才。\n（十六）大力减轻科研人员负担。加快国家科技管理信息系统建设，实现在线申报、信息共享。大力解决表格多、报销繁、牌子乱、“帽子”重复、检查频繁等突出问题。原则上1个年度内对1个项目的现场检查不超过1次。项目管理专业机构要强化合同管理，按照材料只报1次的要求，严格控制报送材料数量、种类、频次，对照合同从实从严开展项目成果考核验收。专业机构和项目专员严禁向评审专家施加倾向性影响，坚决抵制各种形式的“围猎”。高等学校、科研机构和企业等创新主体要切实履行法人主体责任，改进内部科研管理，减少繁文缛节，不层层加码。高等学校、科研机构领导人员和企业负责人在履行勤勉尽责义务、没有牟取非法利益前提下，免除追究其技术创新决策失误责任，对已履行勤勉尽责义务但因技术路线选择失误等导致难以完成预定目标的项目单位和科研人员予以减责或免责。","level":1},{"name":"五、加强宣传，营造尊重人才、尊崇创新的舆论氛围","text":"（十七）大力宣传科学家精神。高度重视“人民科学家”等功勋荣誉表彰奖励获得者的精神宣传，大力表彰科技界的民族英雄和国家脊梁。推动科学家精神进校园、进课堂、进头脑。系统采集、妥善保存科学家学术成长资料，深入挖掘所蕴含的学术思想、人生积累和精神财富。建设科学家博物馆，探索在国家和地方博物馆中增加反映科技进步的相关展项，依托科技馆、国家重点实验室、重大科技工程纪念馆（遗迹）等设施建设一批科学家精神教育基地。\n（十八）创新宣传方式。建立科技界与文艺界定期座谈交流、调研采风机制，引导支持文艺工作者运用影视剧、微视频、小说、诗歌、戏剧、漫画等多种艺术形式，讲好科技工作者科学报国故事。以“时代楷模”、“最美科技工作者”、“大国工匠”等宣传项目为抓手，积极选树、广泛宣传基层一线科技工作者和创新团队典型。支持有条件的高等学校和中学编排创作演出反映科学家精神的文艺作品，创新青少年思想政治教育手段。\n（十九）加强宣传阵地建设。主流媒体要在黄金时段和版面设立专栏专题，打造科技精品栏目。加强科技宣传队伍建设，开展系统培训，切实提高相关从业人员的科学素养和业务能力。加强网络和新媒体宣传平台建设，创新宣传方式和手段，增强宣传效果、扩大传播范围。","level":1},{"name":"六、保障措施","text":"（二十）强化组织保障。各级党委和政府要切实加强对科技工作的领导，对科技工作者政治上关怀、工作上支持、生活上关心，把弘扬科学家精神、加强作风和学风建设作为践行社会主义核心价值观的重要工作摆上议事日程。各有关部门要转变职能，创新工作模式和方法，加强沟通、密切配合、齐抓共管，细化政策措施，推动落实落地，切实落实好党中央关于为基层减负的部署。科技类社会团体要制定完善本领域科研活动自律公约和职业道德准则，经常性开展职业道德和学风教育，发挥自律自净作用。各类新闻媒体要提高科学素养，宣传报道科研进展和科技成就要向相关机构和人员进行核实，听取专家意见，杜绝盲目夸大或者恶意贬低，反对“标题党”。对宣传报道不实、造成恶劣影响的，相关媒体、涉事单位及责任人员应及时澄清，有关部门应依规依法处理。\n中央宣传部、科技部、中国科协、教育部、中国科学院、中国工程院等要会同有关方面分解工作任务，对落实情况加强跟踪督办和总结评估，确保各项举措落到实处。军队可根据本意见，结合实际建立健全相应工作机制。","level":1}]},{"id":"r0560","sections":[{"name":"关于深化“四风”整治、巩固和拓展党的群众路线教育实践活动成果的指导意见","text":"点击此处观看视频","level":1},{"name":"","text":"近日，中共中央办公厅印发了《关于深化“四风”整治、巩固和拓展党的群众路线教育实践活动成果的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻执行。\n《关于深化“四风”整治、巩固和拓展党的群众路线教育实践活动成果的指导意见》主要内容如下。\n习近平总书记在党的群众路线教育实践活动总结大会上发表重要讲话，对巩固和拓展教育实践活动成果、加强党的作风建设、全面推进从严治党作出战略部署，提出明确要求。现就深化“四风”整治、巩固和拓展教育实践活动成果提出如下指导意见。","level":0},{"name":"一、充分认识巩固和拓展教育实践活动成果的重要意义","text":"1.坚持不懈抓好作风建设。各级党组织必须充分认识作风建设的长期性复杂性艰巨性，牢固树立持续整改、长期整改的思想，切实把作风建设紧紧抓在手上，坚持抓常、抓细、抓长，以锲而不舍、驰而不息的决心和毅力，持续努力、久久为功，推进集中反“四风”改作风转为经常性的作风建设，形成作风建设新常态。\n2.始终保持反“四风”高压态势。要清醒地看到，教育实践活动取得的成效还是初步的，基础还不稳固。要采取有力措施抓好整改落实，防止曲终人散，使活动期间形成的反“四风”改作风良好势头戛然而止，改作风成为一阵风；防止束之高阁，对活动中作出的公开承诺、制定的整改措施不再过问、不再落实；防止推诿扯皮，对整改任务无单位认领或者虽认领了却不牵头沟通、有解决方案却迟迟没有行动；防止反弹反复，活动一过一切照旧，“四风”卷土重来。\n3.总结运用好教育实践活动宝贵经验。坚持教育与实践并重，一手抓“四风”整治，一手抓经常性教育；坚持问题导向，经常分析党员、干部作风状况和本地区本部门本单位群众反映强烈的“四风”问题，有什么问题就解决什么问题，什么问题突出就重点解决什么问题；坚持领导带头，牢牢抓住县处级以上领导机关、领导班子、领导干部这个重点，督促他们以上率下、作出示范、树立标杆；坚持最讲认真精神，严格标准不降格，严抓落实不懈怠，严肃执纪不手软；坚持开门改作风，经常听取群众意见建议，及时公布整改落实情况，自觉接受群众评价监督；坚持围绕中心、服务大局，以优良作风促进经济社会科学发展，以科学发展检验作风建设成效。","level":1},{"name":"二、切实兑现承诺，持续深入抓好整改落实","text":"4.认真落实整改任务。对领导班子整改方案和领导干部整改措施落实情况进行盘点分析，真实掌握整改落实的进展、效果和存在问题，有针对性地拿出对策。定期公开后续整改进展情况，群众认可一件、销号一件，绝不允许出现“烂尾工程”或“形象工程”。\n5.深入推进专项整治。各地区各部门各单位要扭住党中央确定的21项专项整治任务，进一步把责任明确到位、措施落实到位、问题解决到位。各牵头单位要成立专门工作班子，制定实施方案，细化分解具体任务，加强协调和调度；参与单位要按照职责分工，主动配合、抓好落实。专项整治工作纳入落实中央八项规定督促检查内容。\n6.上下联动推进整改。各行业系统要聚焦基层和群众反映强烈的政风行风问题，确定需要上下联动整改的重点项目，制定专门方案，上下互动、挂牌督办。各省区市党委要统筹抓好省、市、县三级联动整改，认真梳理基层需要上级牵头解决的问题，列出联动整改项目清单，明确责任单位和具体措施，抓好组织实施。","level":1},{"name":"三、强化源头治理，健全和落实改进作风常态化制度","text":"7.切实加强制度建设。认真执行中央出台的《党政机关厉行节约反对浪费条例》等文件精神，针对存在问题，修订完善或制定相应配套措施，坚决防止上有政策下有对策、无视制度规定的行为。各地区各部门各单位要按照作风建设要求、体现机关和干部管理规律、反映行业和领域特点，搞好制度承接，抓好新旧制度衔接，确保出台的每项制度行得通、有效果、管长久。\n8.围绕权力运行扎紧织密制度笼子。中央和国家机关要围绕规范权力运行，带头建立权力清单制度，梳理职权目录，厘清权力边界，依法公开权力运行流程。地方各级党政机关及其工作部门，要加快建立并公布本级权力清单，完善重大事项、重大决策民主协商和咨询制度，健全党务公开、政务公开和各领域办事公开制度。执法监管部门要针对权责交叉、多头执法、自由裁量权过大等问题，着力理顺执法体制、完善执法程序。窗口单位和服务行业要围绕改进服务态度、简化办事流程、提高服务效能，着力完善便民服务、高效服务、优质服务制度规定。国有企业要建立健全经营投资责任追究机制，完善企业管理人员薪酬制度，规范履职待遇和业务支出。高等学校要完善内部治理结构，健全考试招生制度，规范科研经费和设备管理办法。\n9.强化正风肃纪维护制度严肃性。加大制度执行监督检查力度，明确违规处理的具体办法，始终坚持对踩“红线”、闯“雷区”的零容忍，触犯法律的及时移交司法机关处理。坚持“一案双查”，既要追究当事人责任，也要追究监管领导责任，防止以集体责任代替个人责任。对顶风违纪、影响恶劣的典型案例，要指名道姓予以通报曝光。","level":1},{"name":"四、严肃党内政治生活，坚决克服自由主义、分散主义、好人主义、个人主义","text":"10.严格执行党内政治生活制度。各级领导班子要坚持民主集中制，完善并严格执行民主决策机制、集体领导与个人分工负责相结合的制度、请示报告制度。各级党组织要着力解决不按规定开展党内活动，党内生活质量不高、流于形式、难以发挥作用的问题，切实提高党内政治生活的政治性原则性战斗性。党员领导干部要严格执行双重组织生活会制度，既要认真参加领导班子民主生活会，又要以普通党员身份参加所在党支部的组织生活会。要坚持“三会一课”、民主评议党员、党员党性定期分析等制度，结合实际开展主题党日、警示教育等活动。结合年度考核，对各级领导班子和领导干部贯彻执行党内政治生活有关规定情况进行检查，各级领导班子要在自查基础上向上级党组织专题报告。\n11.用好批评和自我批评武器。要将开门听取意见、认真撰写对照检查材料并报上级审核把关、深入谈心交心、严肃开展批评、上级党组织点评并严格督导等有效做法固定下来，促进批评和自我批评常态化；按照教育实践活动专题民主生活会标准，切实开好2014年度领导干部民主生活会。基层党组织组织生活会要明确组织学习、谈心谈话征求意见、撰写简要对照检查材料、召开支部委员会开展批评和自我批评、召开党员大会进行民主评议等方法步骤，确保组织生活会有质量地召开、党员都能参加。\n12. 坚持党性原则基础上的团结。每一名党员、干部都必须站在党和人民立场上，坚持个人服从组织、少数服从多数、下级服从上级、全党服从中央，坚决维护中央权威，坚决维护党的集中统一。各级领导班子要大力提倡掏心见胆、并肩奋斗的真团结，领导班子成员要坚持大事讲原则、小事讲风格，多沟通、勤补台，正确处理权力行使、利益分配、沟通协调上的分歧，营造心往一处想、劲往一处使的生动局面。","level":1},{"name":"五、充分发挥领导带头表率作用，继续保持作风建设以上率下态势","text":"13.不断推进领导机关作风建设。各级党政机关要结合实际，持续开展作风建设专题活动，每年确定一个方面的作风问题，集中攻坚解决。全面推行机关联系基层、干部联系群众“双联系”制度，落实党员干部直接联系群众制度，开展在职党员到社区报到为群众服务工作。中央和地方机关工委牵头负责，继续开展机关作风和行风评议监督工作。\n14.加强领导班子领导干部作风教育。把作风教育纳入各级党委（党组）中心组学习和集体学习内容，每年至少集中开展一次专题学习。党员领导干部要联系思想、工作和作风建设实际，每年至少为基层党员、干部讲一次党课。各级党校、行政学院、干部学院要开设作风教育专门课程，各类主体班次都要把作风教育作为学员必修课。\n15. 严格考核领导班子领导干部作风。坚持选拔看作风、考核考作风、监督管作风。建立领导班子领导干部作风状况定期分析机制，制定实施领导班子领导干部作风建设考核办法，把作风状况作为年度考核和干部考察重要内容，结合干部考察、工作检查、专项巡视、重点督查等方式，多渠道了解干部作风情况。","level":1},{"name":"六、着力夯实基层基础，建强联系群众组织体系、服务体系、监督体系、保障体系","text":"16.加强基层服务型党组织建设。建立健全基层组织体系，强化基层党组织政治功能，充分发挥战斗堡垒作用。严把党员队伍入口、疏通出口，加强党员教育管理，稳妥有序处置不合格党员，推动党员立足本职岗位发挥先锋模范作用。继续整顿软弱涣散党组织，建立常态化机制，每年按一定比例倒排，滚动开展整顿。\n17.完善基层为民服务平台。强化县级行政服务中心、乡镇和街道一站式服务大厅、村和社区便民服务站点三级平台服务功能，推广为民服务全程代理、一站式服务、网络服务等做法。全面清理部门延伸到村、社区的公共事务，着力整改基层牌子多、检查评比多等问题。\n18.健全基层民主管理机制。在村和社区普遍推行“四议两公开”等民主管理制度。全面建立村务监督委员会，进一步规范监督内容、权限和程序，保证村级各项事务公开、公平、公正。\n19.推动人财物向基层倾斜。充实加强基层干部队伍，选派党政机关年轻干部到基层工作。认真落实基层党组织工作经费、服务群众专项经费、基层干部报酬待遇和基本养老医疗保险。注重从基层培养选拔干部，加大从村、社区干部和优秀大学生村官中考录公务员力度，适当提高基层干部待遇，逐步改善工作生活条件。建立健全市、县、乡党委书记基层党建工作三级联述联评联考机制，结合年度考核每年开展一次述职评议考核。","level":1},{"name":"七、加强组织领导，落实作风建设各项责任","text":"20.明确作风建设责任。各级党委（党组）必须树立正确政绩观，把抓好党建作为最大政绩，切实做到真管真严、敢管敢严、长管长严。党委担负着抓作风建设的主体责任，党委（党组）书记担负着第一责任。各级党委（党组）要认真履职尽责，党委（党组）书记要成为从严治党的书记。对各级各部门党组织负责人特别是党委（党组）书记的考核，首先要看抓党建的实效，考核其他党员领导干部工作也要加大这方面的权重。\n21.形成作风建设合力。要充分发挥职能部门作用，明确和落实相关责任，形成作风建设齐抓共管的整体格局。要把思想教育、纪律约束、监督查处融为一体，坚持正面教育与警示惩戒并重、立规与执纪并举、自律与他律结合，打好作风建设“组合拳”。要加强宣传和舆论引导工作，继续营造抓作风树新风的良好舆论氛围。\n22.加强作风建设督查。建立健全作风建设督查机制。2014年年底，各级党委（党组）要结合年度工作总结，对整改落实情况进行一次“回头看”。2015年适当时机，各地区各部门各单位要对整改落实工作以及巩固和拓展教育实践活动成果情况组织专项检查，党中央将进行专项检查。\n延伸阅读：\n总政治部下发《关于深化“四风”整治、巩固和拓展党的群众路线教育实践活动成果的指导意见》\n巩固和拓展教育实践活动成果 中央明确下一步整治“四风”的七个方向","level":1}]},{"id":"r0561","sections":[{"name":"人事争议处理规定","text":"第一章 总 则","level":1},{"name":"","text":"第一条 为公正及时地处理人事争议，保护当事人的合法权益，根据《中华人民共和国公务员法》、《中国人民解放军文职人员条例》等有关法律法规，制定本规定。\n第二条 本规定适用于下列人事争议:\n（一）实施公务员法的机关与聘任制公务员之间、参照《中华人民共和国公务员法》管理的机关（单位）与聘任工作人员之间因履行聘任合同发生的争议。\n（二）事业单位与工作人员之间因解除人事关系、履行聘用合同发生的争议。\n（三）社团组织与工作人员之间因解除人事关系、履行聘用合同发生的争议。\n（四）军队聘用单位与文职人员之间因履行聘用合同发生的争议。\n（五）依照法律、法规规定可以仲裁的其他人事争议。\n第三条 人事争议发生后，当事人可以协商解决；不愿协商或者协商不成的，可以向主管部门申请调解，其中军队聘用单位与文职人员的人事争议，可以向聘用单位的上一级单位申请调解；不愿调解或调解不成的，可以向人事争议仲裁委员会申请仲裁。当事人也可以直接向人事争议仲裁委员会申请仲裁。当事人对仲裁裁决不服的，可以向人民法院提起诉讼。\n第四条 当事人在人事争议处理中的地位平等，适用法律、法规平等。\n当事人有使用本民族语言文字申请仲裁的权利。人事争议仲裁委员会对于不熟悉当地通用语言文字的当事人，应当为他们翻译。\n第五条 处理人事争议，应当注重调解，遵循合法、公正、及时的原则，以事实为依据，以法律为准绳。","level":0},{"name":"第二章 组织机构","text":"第六条 中央机关及所属事业单位人事争议仲裁委员会设在人事部。\n省（自治区、直辖市）、副省级市、地（市、州、盟）、县（市、区、旗）设立人事争议仲裁委员会。\n人事争议仲裁委员会独立办案，相互之间无隶属关系。\n第七条 人事争议仲裁委员会由公务员主管部门代表、聘任（用）单位代表、工会组织代表、受聘人员代表以及人事、法律专家组成。人事争议仲裁委员会组成人员应当是单数，设主任一名、副主任二至四名、委员若干名。\n同级人民政府分管人事工作的负责人或者政府人事行政部门的主要负责人任人事争议仲裁委员会主任。\n第八条 人事争议仲裁委员会实行少数服从多数原则，不同意见应如实记录。\n第九条 人事争议仲裁委员会的职责是:\n（一）负责处理管辖范围内的人事争议。\n（二）决定仲裁员的聘任和解聘。\n（三）法律、法规规定由人事争议仲裁委员会承担的其他职责。\n第十条 人事争议仲裁委员会下设办事机构，其职责是:负责人事争议案件的受理、仲裁文书送达、档案管理以及仲裁员的考核、培训等日常工作，办理人事争议仲裁委员会授权的其他事宜。办事机构设在同级人民政府人事部门。\n第十一条 人事争议仲裁委员会处理人事争议案件实行仲裁庭制度，仲裁庭是人事争议仲裁委员会处理人事争议案件的基本形式。仲裁庭一般由三名仲裁员组成。人事争议仲裁委员会指定一名仲裁员担任首席仲裁员，主持仲裁庭工作；另两名仲裁员可由双方当事人各选定一名，也可由人事争议仲裁委员会指定。简单的人事争议案件，经双方当事人同意，人事争议仲裁委员会可以指定一名仲裁员独任处理。\n第十二条 人事争议仲裁委员会可以聘任有关部门的工作人员、专家学者和律师为专职或兼职仲裁员。仲裁员的职责是:受人事争议仲裁委员会的委托或当事人的选择，负责人事争议案件的具体处理工作。\n兼职仲裁员与专职仲裁员在仲裁活动中享有同等权利。\n兼职仲裁员进行仲裁活动时，所在单位应当给予支持。","level":1},{"name":"第三章 管 辖","text":"第十三条 中央机关、直属机构、直属事业单位及其在京所属事业单位的人事争议由中央机关及所属事业单位人事争议仲裁委员会处理。\n中央机关在京外垂直管理机构以及中央机关、直属机构、直属事业单位在京外所属事业单位的人事争议，由所在地的省（自治区、直辖市）设立的人事争议仲裁委员会处理，也可由省（自治区、直辖市）根据情况授权所在地的人事争议仲裁委员会处理。\n第十四条 省（自治区、直辖市）、副省级市、地（市、州、盟）、县（市、区、旗）人事争议仲裁委员会的管辖范围，由省（自治区、直辖市）确定。\n第十五条 军队聘用单位与文职人员的人事争议，一般由聘用单位所在地的县（市、区、旗）人事争议仲裁委员会处理，其中师级聘用单位与文职人员的人事争议，由所在地的地（市、州、盟）、副省级市人事争议仲裁委员会处理，军级以上聘用单位与文职人员的人事争议由所在地的省（自治区、直辖市）人事争议仲裁委员会处理。驻京部队聘用单位与文职人员的人事争议，由中央机关及所属事业单位人事争议仲裁委员会处理。","level":1}]},{"id":"r0562","sections":[{"name":"国有重要骨干企业领导人员任职和公务回避暂行规定","text":"第一章 总 则","level":1},{"name":"","text":"第一条 为加强对国有重要骨干企业的管理，保证国有重要骨干企业领导人员公正履行职责，促进国有重要骨干企业党风廉政建设，制定本规定。\n第二条 本规定所称国有重要骨干企业（含国有控股企业）领导人员是指列入中共中央管理和中央企业工委管理的职务名称表的企业领导人员。\n第三条 本规定所称企业领导人员亲属是指：配偶，父母，配偶的父母，子女及其配偶，兄弟姐妹及其配偶、子女，配偶的兄弟姐妹。","level":0},{"name":"第二章 任职回避","text":"第四条 企业领导人员有第三条所列亲属关系，并有下列情况之一的，应当实行任职回避。\n（一）在同一领导班子中任职的；\n（二）同时在有直接隶属关系的领导班子中任主要领导职务的；\n（三）一方在领导班子，另一方在其分管的部门、企业、驻外机构（境内外，下同）及工程、投资项目中任领导职务的；\n（四）企业领导班子主管部门提出需要任职回避的。\n第五条 企业领导人员任职回避应当按照下列程序进行：\n（一）本人提出回避申请或者领导班子、有关管理部门提出回避建议；\n（二）按企业领导人员管理权限进行审核和做出决定；\n（三）需要回避的，由企业领导班子主管部门调整工作岗位。\n第六条 回避双方职务不同的，一般由职务较低一方回避；职务相同的，由企业领导班子主管部门根据工作需要和当事人的实际情况决定其中一方回避。\n第七条 新任用或新调入的人员在任职或调入企业前，应如实报告应回避的关系，并及时申请回避。因婚姻、职务变化等情况新形成的回避关系，当事人应当及时申请回避。\n当事人申请任职回避的，企业领导班子主管部门应在半年内予以调整。","level":1},{"name":"第三章 公务回避","text":"第八条 企业领导人员所在企业不准与企业领导人员的配偶、子女个人所从事的生产经营活动直接发生经济关系；因专利、特许经营等原因具有经营项目的独占性，企业必须与其发生经济往来的，其经营的项目及项目所涉及的重要指标应当列为厂务公开的一项内容。\n第三条所列企业领导人员配偶、子女以外的亲属和其他来往密切的亲属，本人或代表其所在单位与企业领导人员所在企业进行业务往来时，企业领导人员应申请公务回避。企业领导人员无法回避时，应将有关情况以适当形式在一定范围内公示，并向纪检监察部门报告。\n第九条 企业领导人员在纪检监察、仲裁、组织处理、出国审批、人事考核、任免、奖惩、录用、聘用、调配、专业技术职务评聘、专家选拔、发展党员、调资、安置复转军人、毕业生分配等公务活动中，涉及本人和亲属时，不得参加有关调查、讨论、审核、决定，也不得以任何方式施加影响。\n第十条 企业领导人员与在党政机关任职的第三条所列亲属发生直接公务关系时，应回避，不得影响亲属公正执行公务。\n第十一条 企业领导人员公务回避程序依照任职回避程序进行。特殊情况下，主管领导或领导班子可直接作出回避决定。\n第十二条 严禁企业领导人员利用职权为第三条所列亲属及其他亲属或关系密切的个人从事下列活动：\n（一）为其经商办企业提供场地、设备、备品备件及其他生产资料等（含无偿提供、有偿使用、暂时使用）；\n（二）为其经商办企业挪用、拆借资金，提供贷款抵押、质押、担保等；\n（三）向其批售或授意批售本企业物资、产成品，提供加工产品、备品备件或批购其推销的原材料及产品；\n（四）将本企业的项目或下属企业、单位以委托、承包、租赁、转卖等方式给其经营或与其合作、联营；\n（五）为其承揽本企业工程或参加自己主管、参与的工程施工、物资采购、加工制作等方面的招投标业务；\n（六）企业改制重组时，在处理物资设备、发行股票和企业内部债券等业务中，向其提供便利和优惠条件；\n（七）为其提供商标、品牌、专利、非公开信息、客户市场等方面的便利；\n（八）其他侵害企业利益的行为。","level":1},{"name":"第四章 监督与处罚","text":"第十三条 企业领导人员任职三个月内，必须向有关管理部门或企业领导班子书面报告第三条所列来往密切的亲属任职从业的情况。\n第十四条 企业领导人员每年应向职代会或领导班子成员民主生活会报告执行任职回避和公务回避的情况。\n第十五条 本规定按企业领导人员管理权限，由组织人事部门组织实施，纪检监察机关负责监督检查。企业党组织应将回避工作纳入党风廉政建设责任制。\n第十六条 企业领导人员有下列行为之一的，视情节轻重，给予组织处理，或根据有关规定给予党纪政纪处分。涉嫌犯罪的，移送司法机关处理。\n（一）违反任职回避规定，或拒不执行回避决定；\n（二）违反公务回避有关规定，不履行或不正确履行职责，使国家、企业利益受到损害；\n（三）违反公务回避有关规定，以权谋私，使本人、亲属、亲属所在单位或合伙人获取不正当利益。\n第十七条 企业领导班子主管部门和企业领导班子在回避工作中玩忽职守，致使企业造成重大经济损失或其他严重后果的，要追究有关责任人员的责任，根据情节轻重给予组织处理或党纪政纪处分。","level":1},{"name":"第五章 附 则","text":"第十八条 本规定适用于中共中央和中央企业工委管理的国有重要骨干企业（含国有控股企业）。\n第十九条 未列入中共中央和中央企业工委管理的职务名称表的总会计师、总经济师、总工程师等重要岗位的人员，参照本规定执行。\n第二十条 各国有重要骨干企业依据本规定，结合企业实际，制定实施办法，分别报中央组织部和中央企业工委备案。个别执行任职回避确有困难的企业，可适当放宽，但必须根据监督制约原则，在实施办法中制定内部监管的条款。\n第二十一条 本规定由中央组织部、中央企业工委负责解释。\n第二十二条 本规定自发布之日起施行。","level":1}]},{"id":"r0563","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于加强重特大事件档案工作的通知》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于加强重特大事件档案工作的通知》（以下简称《通知》），对进一步加强重特大事件档案工作提出要求。","level":1},{"name":"","text":"《通知》指出，重特大事件档案是党和国家组织应对自然灾害、事故灾难、公共卫生事件、社会安全事件等突发事件所形成的具有保存价值的历史记录。收集好、保管好、利用好重特大事件档案，对于总结历史经验教训、维护国家安全和社会公共利益、推进国家治理体系和治理能力现代化具有重要意义。\n《通知》要求，加强重特大事件档案工作要以习近平新时代中国特色社会主义思想为指导，深入贯彻落实党中央决策部署和习近平总书记重要指示精神，以对党、对人民、对历史高度负责的态度，完善制度机制，坚持创新引领，推动资源共享，全面提高重特大事件档案工作现代化水平，更好地服务党和国家工作大局、服务人民群众。\n《通知》提出，要认真贯彻实施档案法和相关法律法规，加强法规制度协同，完善重特大事件档案工作制度规定。着力强化重特大事件档案收集工作，从源头抓好重特大事件档案的形成和留存工作。各有关单位在重特大事件的预防与应急准备、监测与预警、应急处置与救援、事后恢复与重建等各个环节，按照相关规定形成和留存各类文件材料，鼓励参加志愿服务的组织和个人留存相关记录并捐赠给有关单位。充分利用现代信息技术，科学推进重特大事件档案数据库建设，促进重特大事件档案资源整合。加强统筹协调，实现重特大事件档案跨地区跨部门跨层级查询利用，简化优化档案利用流程，加强重特大事件档案资源深度开发，不断提升重特大事件档案利用效能。\n《通知》要求，各级党委（党组）要提高政治站位，加强组织领导和统筹协调，建立党委统一领导、党政齐抓共管、责任分工明确、部门协同联动的重特大事件档案工作机制，确保档案工作与重特大事件应对管理工作同部署、同推进、同落实。重特大事件应对管理议事协调机制应将档案部门作为成员单位。加大对相关基础设施建设、档案整理和数字化、档案开发利用、人员教育培训等方面的经费投入，为做好重特大事件档案工作创造良好环境和条件。","level":0}]},{"id":"r0564","sections":[{"name":"中共中央 国务院关于做好2022年全面推进乡村振兴重点工作的意见","text":"中共中央 国务院关于做好2022年全面推进乡村振兴重点工作的意见\n（2022年1月4日）","level":1},{"name":"","text":"当前，全球新冠肺炎疫情仍在蔓延，世界经济复苏脆弱，气候变化挑战突出，我国经济社会发展各项任务极为繁重艰巨。党中央认为，从容应对百年变局和世纪疫情，推动经济社会平稳健康发展，必须着眼国家重大战略需要，稳住农业基本盘、做好“三农”工作，接续全面推进乡村振兴，确保农业稳产增产、农民稳步增收、农村稳定安宁。\n做好2022年“三农”工作，要以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届历次全会精神，深入贯彻中央经济工作会议精神，坚持稳中求进工作总基调，立足新发展阶段、贯彻新发展理念、构建新发展格局、推动高质量发展，促进共同富裕，坚持和加强党对“三农”工作的全面领导，牢牢守住保障国家粮食安全和不发生规模性返贫两条底线，突出年度性任务、针对性举措、实效性导向，充分发挥农村基层党组织领导作用，扎实有序做好乡村发展、乡村建设、乡村治理重点工作，推动乡村振兴取得新进展、农业农村现代化迈出新步伐。","level":0},{"name":"一、全力抓好粮食生产和重要农产品供给","text":"（一）稳定全年粮食播种面积和产量。坚持中国人的饭碗任何时候都要牢牢端在自己手中，饭碗主要装中国粮，全面落实粮食安全党政同责，严格粮食安全责任制考核，确保粮食播种面积稳定、产量保持在1.3万亿斤以上。主产区、主销区、产销平衡区都要保面积、保产量，不断提高主产区粮食综合生产能力，切实稳定和提高主销区粮食自给率，确保产销平衡区粮食基本自给。推进国家粮食安全产业带建设。大力开展绿色高质高效行动，深入实施优质粮食工程，提升粮食单产和品质。推进黄河流域农业深度节水控水，通过提升用水效率、发展旱作农业，稳定粮食播种面积。积极应对小麦晚播等不利影响，加强冬春田间管理，促进弱苗转壮。\n（二）大力实施大豆和油料产能提升工程。加大耕地轮作补贴和产油大县奖励力度，集中支持适宜区域、重点品种、经营服务主体，在黄淮海、西北、西南地区推广玉米大豆带状复合种植，在东北地区开展粮豆轮作，在黑龙江省部分地下水超采区、寒地井灌稻区推进水改旱、稻改豆试点，在长江流域开发冬闲田扩种油菜。开展盐碱地种植大豆示范。支持扩大油茶种植面积，改造提升低产林。\n（三）保障“菜篮子”产品供给。加大力度落实“菜篮子”市长负责制。稳定生猪生产长效性支持政策，稳定基础产能，防止生产大起大落。加快扩大牛羊肉和奶业生产，推进草原畜牧业转型升级试点示范。稳定水产养殖面积，提升渔业发展质量。稳定大中城市常年菜地保有量，大力推进北方设施蔬菜、南菜北运基地建设，提高蔬菜应急保供能力。完善棉花目标价格政策。探索开展糖料蔗完全成本保险和种植收入保险。开展天然橡胶老旧胶园更新改造试点。\n（四）合理保障农民种粮收益。按照让农民种粮有利可图、让主产区抓粮有积极性的目标要求，健全农民种粮收益保障机制。2022年适当提高稻谷、小麦最低收购价，稳定玉米、大豆生产者补贴和稻谷补贴政策，实现三大粮食作物完全成本保险和种植收入保险主产省产粮大县全覆盖。加大产粮大县奖励力度，创新粮食产销区合作机制。支持家庭农场、农民合作社、农业产业化龙头企业多种粮、种好粮。聚焦关键薄弱环节和小农户，加快发展农业社会化服务，支持农业服务公司、农民合作社、农村集体经济组织、基层供销合作社等各类主体大力发展单环节、多环节、全程生产托管服务，开展订单农业、加工物流、产品营销等，提高种粮综合效益。\n（五）统筹做好重要农产品调控。健全农产品全产业链监测预警体系，推动建立统一的农产品供需信息发布制度，分类分品种加强调控和应急保障。深化粮食购销领域监管体制机制改革，开展专项整治，依法从严惩治系统性腐败。加强智能粮库建设，促进人防技防相结合，强化粮食库存动态监管。严格控制以玉米为原料的燃料乙醇加工。做好化肥等农资生产储备调运，促进保供稳价。坚持节约优先，落实粮食节约行动方案，深入推进产运储加消全链条节粮减损，强化粮食安全教育，反对食物浪费。","level":1},{"name":"二、强化现代农业基础支撑","text":"（六）落实“长牙齿”的耕地保护硬措施。实行耕地保护党政同责，严守18亿亩耕地红线。按照耕地和永久基本农田、生态保护红线、城镇开发边界的顺序，统筹划定落实三条控制线，把耕地保有量和永久基本农田保护目标任务足额带位置逐级分解下达，由中央和地方签订耕地保护目标责任书，作为刚性指标实行严格考核、一票否决、终身追责。分类明确耕地用途，严格落实耕地利用优先序，耕地主要用于粮食和棉、油、糖、蔬菜等农产品及饲草饲料生产，永久基本农田重点用于粮食生产，高标准农田原则上全部用于粮食生产。引导新发展林果业上山上坡，鼓励利用“四荒”资源，不与粮争地。落实和完善耕地占补平衡政策，建立补充耕地立项、实施、验收、管护全程监管机制，确保补充可长期稳定利用的耕地，实现补充耕地产能与所占耕地相当。改进跨省域补充耕地国家统筹管理办法。加大耕地执法监督力度，严厉查处违法违规占用耕地从事非农建设。强化耕地用途管制，严格管控耕地转为其他农用地。巩固提升受污染耕地安全利用水平。稳妥有序开展农村乱占耕地建房专项整治试点。巩固“大棚房”问题专项清理整治成果。落实工商资本流转农村土地审查审核和风险防范制度。\n（七）全面完成高标准农田建设阶段性任务。多渠道增加投入，2022年建设高标准农田1亿亩，累计建成高效节水灌溉面积4亿亩。统筹规划、同步实施高效节水灌溉与高标准农田建设。各地要加大中低产田改造力度，提升耕地地力等级。研究制定增加农田灌溉面积的规划。实施重点水源和重大引调水等水资源配置工程。加大大中型灌区续建配套与改造力度，在水土资源条件适宜地区规划新建一批现代化灌区，优先将大中型灌区建成高标准农田。深入推进国家黑土地保护工程。实施黑土地保护性耕作8000万亩。积极挖掘潜力增加耕地，支持将符合条件的盐碱地等后备资源适度有序开发为耕地。研究制定盐碱地综合利用规划和实施方案。分类改造盐碱地，推动由主要治理盐碱地适应作物向更多选育耐盐碱植物适应盐碱地转变。支持盐碱地、干旱半干旱地区国家农业高新技术产业示范区建设。启动全国第三次土壤普查。\n（八）大力推进种源等农业关键核心技术攻关。全面实施种业振兴行动方案。加快推进农业种质资源普查收集，强化精准鉴定评价。推进种业领域国家重大创新平台建设。启动农业生物育种重大项目。加快实施农业关键核心技术攻关工程，实行“揭榜挂帅”、“部省联动”等制度，开展长周期研发项目试点。强化现代农业产业技术体系建设。开展重大品种研发与推广后补助试点。贯彻落实种子法，实行实质性派生品种制度，强化种业知识产权保护，依法严厉打击套牌侵权等违法犯罪行为。\n（九）提升农机装备研发应用水平。全面梳理短板弱项，加强农机装备工程化协同攻关，加快大马力机械、丘陵山区和设施园艺小型机械、高端智能机械研发制造并纳入国家重点研发计划予以长期稳定支持。实施农机购置与应用补贴政策，优化补贴兑付方式。完善农机性能评价机制，推进补贴机具有进有出、优机优补，重点支持粮食烘干、履带式作业、玉米大豆带状复合种植、油菜籽收获等农机，推广大型复合智能农机。推动新生产农机排放标准升级。开展农机研发制造推广应用一体化试点。\n（十）加快发展设施农业。因地制宜发展塑料大棚、日光温室、连栋温室等设施。集中建设育苗工厂化设施。鼓励发展工厂化集约养殖、立体生态养殖等新型养殖设施。推动水肥一体化、饲喂自动化、环境控制智能化等设施装备技术研发应用。在保护生态环境基础上，探索利用可开发的空闲地、废弃地发展设施农业。\n（十一）有效防范应对农业重大灾害。加大农业防灾减灾救灾能力建设和投入力度。修复水毁灾损农业、水利基础设施，加强沟渠疏浚以及水库、泵站建设和管护。加强防汛抗旱应急物资储备。强化农业农村、水利、气象灾害监测预警体系建设，增强极端天气应对能力。加强基层动植物疫病防控体系建设，落实属地责任，配齐配强专业人员，实行定责定岗定人，确保非洲猪瘟、草地贪夜蛾等动植物重大疫病防控责有人负、活有人干、事有人管。做好人兽共患病源头防控。加强外来入侵物种防控管理，做好普查监测、入境检疫、国内防控，对已传入并造成严重危害的，要“一种一策”精准治理、有效灭除。加强中长期气候变化对农业影响研究。","level":1},{"name":"三、坚决守住不发生规模性返贫底线","text":"（十二）完善监测帮扶机制。精准确定监测对象，将有返贫致贫风险和突发严重困难的农户纳入监测范围，简化工作流程，缩短认定时间。针对发现的因灾因病因疫等苗头性问题，及时落实社会救助、医疗保障等帮扶措施。强化监测帮扶责任落实，确保工作不留空档、政策不留空白。继续开展巩固脱贫成果后评估工作。\n（十三）促进脱贫人口持续增收。推动脱贫地区更多依靠发展来巩固拓展脱贫攻坚成果，让脱贫群众生活更上一层楼。巩固提升脱贫地区特色产业，完善联农带农机制，提高脱贫人口家庭经营性收入。逐步提高中央财政衔接推进乡村振兴补助资金用于产业发展的比重，重点支持帮扶产业补上技术、设施、营销等短板，强化龙头带动作用，促进产业提档升级。巩固光伏扶贫工程成效，在有条件的脱贫地区发展光伏产业。压实就业帮扶责任，确保脱贫劳动力就业规模稳定。深化东西部劳务协作，做好省内转移就业工作。延续支持帮扶车间发展优惠政策。发挥以工代赈作用，具备条件的可提高劳务报酬发放比例。统筹用好乡村公益岗位，实行动态管理。逐步调整优化生态护林员政策。\n（十四）加大对乡村振兴重点帮扶县和易地搬迁集中安置区支持力度。在乡村振兴重点帮扶县实施一批补短板促发展项目。编制国家乡村振兴重点帮扶县巩固拓展脱贫攻坚成果同乡村振兴有效衔接实施方案。做好国家乡村振兴重点帮扶县科技特派团选派，实行产业技术顾问制度，有计划开展教育、医疗干部人才组团式帮扶。建立健全国家乡村振兴重点帮扶县发展监测评价机制。加大对国家乡村振兴重点帮扶县信贷资金投入和保险保障力度。完善易地搬迁集中安置区配套设施和公共服务，持续加大安置区产业培育力度，开展搬迁群众就业帮扶专项行动。落实搬迁群众户籍管理、合法权益保障、社会融入等工作举措，提升安置社区治理水平。\n（十五）推动脱贫地区帮扶政策落地见效。保持主要帮扶政策总体稳定，细化落实过渡期各项帮扶政策，开展政策效果评估。拓展东西部协作工作领域，深化区县、村企、学校、医院等结对帮扶。在东西部协作和对口支援框架下，继续开展城乡建设用地增减挂钩节余指标跨省域调剂。持续做好中央单位定点帮扶工作。扎实做好脱贫人口小额信贷工作。创建消费帮扶示范城市和产地示范区，发挥脱贫地区农副产品网络销售平台作用。","level":1},{"name":"四、聚焦产业促进乡村发展","text":"（十六）持续推进农村一二三产业融合发展。鼓励各地拓展农业多种功能、挖掘乡村多元价值，重点发展农产品加工、乡村休闲旅游、农村电商等产业。支持农业大县聚焦农产品加工业，引导企业到产地发展粮油加工、食品制造。推进现代农业产业园和农业产业强镇建设，培育优势特色产业集群，继续支持创建一批国家农村产业融合发展示范园。实施乡村休闲旅游提升计划。支持农民直接经营或参与经营的乡村民宿、农家乐特色村（点）发展。将符合要求的乡村休闲旅游项目纳入科普基地和中小学学农劳动实践基地范围。实施“数商兴农”工程，推进电子商务进乡村。促进农副产品直播带货规范健康发展。开展农业品种培优、品质提升、品牌打造和标准化生产提升行动，推进食用农产品承诺达标合格证制度，完善全产业链质量安全追溯体系。加快落实保障和规范农村一二三产业融合发展用地政策。\n（十七）大力发展县域富民产业。支持大中城市疏解产业向县域延伸，引导产业有序梯度转移。大力发展县域范围内比较优势明显、带动农业农村能力强、就业容量大的产业，推动形成“一县一业”发展格局。加强县域基层创新，强化产业链与创新链融合。加快完善县城产业服务功能，促进产业向园区集中、龙头企业做强做大。引导具备条件的中心镇发展专业化中小微企业集聚区，推动重点村发展乡村作坊、家庭工场。\n（十八）加强县域商业体系建设。实施县域商业建设行动，促进农村消费扩容提质升级。加快农村物流快递网点布局，实施“快递进村”工程，鼓励发展“多站合一”的乡镇客货邮综合服务站、“一点多能”的村级寄递物流综合服务点，推进县乡村物流共同配送，促进农村客货邮融合发展。支持大型流通企业以县城和中心镇为重点下沉供应链。加快实施“互联网+”农产品出村进城工程，推动建立长期稳定的产销对接关系。推动冷链物流服务网络向农村延伸，整县推进农产品产地仓储保鲜冷链物流设施建设，促进合作联营、成网配套。支持供销合作社开展县域流通服务网络建设提升行动，建设县域集采集配中心。\n（十九）促进农民就地就近就业创业。落实各类农民工稳岗就业政策。发挥大中城市就业带动作用。实施县域农民工市民化质量提升行动。鼓励发展共享用工、多渠道灵活就业，规范发展新就业形态，培育发展家政服务、物流配送、养老托育等生活性服务业。推进返乡入乡创业园建设，落实各项扶持政策。大力开展适合农民工就业的技能培训和新职业新业态培训。合理引导灵活就业农民工按规定参加职工基本医疗保险和城镇职工基本养老保险。\n（二十）推进农业农村绿色发展。加强农业面源污染综合治理，深入推进农业投入品减量化，加强畜禽粪污资源化利用，推进农膜科学使用回收，支持秸秆综合利用。建设国家农业绿色发展先行区。开展农业绿色发展情况评价。开展水系连通及水美乡村建设。实施生态保护修复重大工程，复苏河湖生态环境，加强天然林保护修复、草原休养生息。科学推进国土绿化。支持牧区发展和牧民增收，落实第三轮草原生态保护补助奖励政策。研发应用减碳增汇型农业技术，探索建立碳汇产品价值实现机制。实施生物多样性保护重大工程。巩固长江禁渔成果，强化退捕渔民安置保障，加强常态化执法监管。强化水生生物养护，规范增殖放流。构建以国家公园为主体的自然保护地体系。出台推进乡村生态振兴的指导意见。","level":1},{"name":"五、扎实稳妥推进乡村建设","text":"（二十一）健全乡村建设实施机制。落实乡村振兴为农民而兴、乡村建设为农民而建的要求，坚持自下而上、村民自治、农民参与，启动乡村建设行动实施方案，因地制宜、有力有序推进。坚持数量服从质量、进度服从实效，求好不求快，把握乡村建设的时度效。立足村庄现有基础开展乡村建设，不盲目拆旧村、建新村，不超越发展阶段搞大融资、大开发、大建设，避免无效投入造成浪费，防范村级债务风险。统筹城镇和村庄布局，科学确定村庄分类，加快推进有条件有需求的村庄编制村庄规划，严格规范村庄撤并。开展传统村落集中连片保护利用示范，健全传统村落监测评估、警示退出、撤并事前审查等机制。保护特色民族村寨。实施“拯救老屋行动”。推动村庄小型建设项目简易审批，规范项目管理，提高资金绩效。总结推广村民自治组织、农村集体经济组织、农民群众参与乡村建设项目的有效做法。明晰乡村建设项目产权，以县域为单位组织编制村庄公共基础设施管护责任清单。\n（二十二）接续实施农村人居环境整治提升五年行动。从农民实际需求出发推进农村改厕，具备条件的地方可推广水冲卫生厕所，统筹做好供水保障和污水处理；不具备条件的可建设卫生旱厕。巩固户厕问题摸排整改成果。分区分类推进农村生活污水治理，优先治理人口集中村庄，不适宜集中处理的推进小型化生态化治理和污水资源化利用。加快推进农村黑臭水体治理。推进生活垃圾源头分类减量，加强村庄有机废弃物综合处置利用设施建设，推进就地利用处理。深入实施村庄清洁行动和绿化美化行动。\n（二十三）扎实开展重点领域农村基础设施建设。有序推进乡镇通三级及以上等级公路、较大人口规模自然村（组）通硬化路，实施农村公路安全生命防护工程和危桥改造。扎实开展农村公路管理养护体制改革试点。稳步推进农村公路路况自动化检测。推进农村供水工程建设改造，配套完善净化消毒设施设备。深入实施农村电网巩固提升工程。推进农村光伏、生物质能等清洁能源建设。实施农房质量安全提升工程，继续实施农村危房改造和抗震改造，完善农村房屋建设标准规范。加强对用作经营的农村自建房安全隐患整治。\n（二十四）大力推进数字乡村建设。推进智慧农业发展，促进信息技术与农机农艺融合应用。加强农民数字素养与技能培训。以数字技术赋能乡村公共服务，推动“互联网+政务服务”向乡村延伸覆盖。着眼解决实际问题，拓展农业农村大数据应用场景。加快推动数字乡村标准化建设，研究制定发展评价指标体系，持续开展数字乡村试点。加强农村信息基础设施建设。\n（二十五）加强基本公共服务县域统筹。加快推进以县城为重要载体的城镇化建设。加强普惠性、基础性、兜底性民生建设，推动基本公共服务供给由注重机构行政区域覆盖向注重常住人口服务覆盖转变。实施新一轮学前教育行动计划，多渠道加快农村普惠性学前教育资源建设，办好特殊教育。扎实推进城乡学校共同体建设。深入推进紧密型县域医疗卫生共同体建设，实施医保按总额付费，加强监督考核，实现结余留用、合理超支分担。推动农村基层定点医疗机构医保信息化建设，强化智能监控全覆盖，加强医疗保障基金监管。落实对特殊困难群体参加城乡居民基本医保的分类资助政策。有条件的地方可提供村卫生室运行经费补助，分类落实村医养老保障、医保等社会保障待遇。提升县级敬老院失能照护能力和乡镇敬老院集中供养水平，鼓励在有条件的村庄开展日间照料、老年食堂等服务。加强乡镇便民服务和社会工作服务，实施村级综合服务设施提升工程。健全分层分类的社会救助体系，切实保障困难农民群众基本生活。健全基层党员、干部关爱联系制度，经常探访空巢老人、留守儿童、残疾人。完善未成年人关爱保护工作网络。","level":1},{"name":"六、突出实效改进乡村治理","text":"（二十六）加强农村基层组织建设。强化县级党委抓乡促村职责，深化乡镇管理体制改革，健全乡镇党委统一指挥和统筹协调机制，加强乡镇、村集中换届后领导班子建设，全面开展农村基层干部乡村振兴主题培训。持续排查整顿软弱涣散村党组织。发挥驻村第一书记和工作队抓党建促乡村振兴作用。完善村级重要事项、重大问题经村党组织研究讨论机制，全面落实“四议两公开”制度。深入开展市县巡察，强化基层监督，加强基层纪检监察组织与村务监督委员会的沟通协作、有效衔接，强化对村干部的监督。健全党组织领导的自治、法治、德治相结合的乡村治理体系，推行网格化管理、数字化赋能、精细化服务。推进村委会规范化建设。深化乡村治理体系建设试点示范。开展村级议事协商创新实验。推广村级组织依法自治事项、依法协助政府工作事项等清单制，规范村级组织机构牌子和证明事项，推行村级基础信息统计“一张表”制度，减轻村级组织负担。\n（二十七）创新农村精神文明建设有效平台载体。依托新时代文明实践中心、县级融媒体中心等平台开展对象化分众化宣传教育，弘扬和践行社会主义核心价值观。在乡村创新开展“听党话、感党恩、跟党走”宣传教育活动。探索统筹推动城乡精神文明融合发展的具体方式，完善全国文明村镇测评体系。启动实施文化产业赋能乡村振兴计划。整合文化惠民活动资源，支持农民自发组织开展村歌、“村晚”、广场舞、趣味运动会等体现农耕农趣农味的文化体育活动。办好中国农民丰收节。加强农耕文化传承保护，推进非物质文化遗产和重要农业文化遗产保护利用。推广积分制等治理方式，有效发挥村规民约、家庭家教家风作用，推进农村婚俗改革试点和殡葬习俗改革，开展高价彩礼、大操大办等移风易俗重点领域突出问题专项治理。\n（二十八）切实维护农村社会平安稳定。推进更高水平的平安法治乡村建设。创建一批“枫桥式公安派出所”、“枫桥式人民法庭”。常态化开展扫黑除恶斗争，持续打击“村霸”。防范黑恶势力、家族宗族势力等对农村基层政权的侵蚀和影响。依法严厉打击农村黄赌毒和侵害农村妇女儿童人身权利的违法犯罪行为。加强农村法治宣传教育。加强基层社会心理服务和危机干预，构建一站式多元化矛盾纠纷化解机制。加强农村宗教工作力量。统筹推进应急管理与乡村治理资源整合，加快推进农村应急广播主动发布终端建设，指导做好人员紧急转移避险工作。开展农村交通、消防、安全生产、自然灾害、食品药品安全等领域风险隐患排查和专项治理，依法严厉打击农村制售假冒伪劣农资、非法集资、电信诈骗等违法犯罪行为。加强农业综合行政执法能力建设。落实基层医疗卫生机构疾病预防控制责任。健全农村新冠肺炎疫情常态化防控工作体系，严格落实联防联控、群防群控措施。","level":1},{"name":"七、加大政策保障和体制机制创新力度","text":"（二十九）扩大乡村振兴投入。继续把农业农村作为一般公共预算优先保障领域，中央预算内投资进一步向农业农村倾斜，压实地方政府投入责任。加强考核监督，稳步提高土地出让收入用于农业农村的比例。支持地方政府发行政府债券用于符合条件的乡村振兴公益性项目。提高乡村振兴领域项目储备质量。强化预算绩效管理和监督。\n（三十）强化乡村振兴金融服务。对机构法人在县域、业务在县域、资金主要用于乡村振兴的地方法人金融机构，加大支农支小再贷款、再贴现支持力度，实施更加优惠的存款准备金政策。支持各类金融机构探索农业农村基础设施中长期信贷模式。加快农村信用社改革，完善省（自治区）农村信用社联合社治理机制，稳妥化解风险。完善乡村振兴金融服务统计制度，开展金融机构服务乡村振兴考核评估。深入开展农村信用体系建设，发展农户信用贷款。加强农村金融知识普及教育和金融消费权益保护。积极发展农业保险和再保险。优化完善“保险+期货”模式。强化涉农信贷风险市场化分担和补偿，发挥好农业信贷担保作用。\n（三十一）加强乡村振兴人才队伍建设。发现和培养使用农业领域战略科学家。启动“神农英才”计划，加快培养科技领军人才、青年科技人才和高水平创新团队。深入推行科技特派员制度。实施高素质农民培育计划、乡村产业振兴带头人培育“头雁”项目、乡村振兴青春建功行动、乡村振兴巾帼行动。落实艰苦边远地区基层事业单位公开招聘倾斜政策，对县以下基层专业技术人员开展职称评聘“定向评价、定向使用”工作，对中高级专业技术岗位实行总量控制、比例单列。完善耕读教育体系。优化学科专业结构，支持办好涉农高等学校和职业教育。培养乡村规划、设计、建设、管理专业人才和乡土人才。鼓励地方出台城市人才下乡服务乡村振兴的激励政策。\n（三十二）抓好农村改革重点任务落实。开展第二轮土地承包到期后再延长30年整县试点。巩固提升农村集体产权制度改革成果，探索建立农村集体资产监督管理服务体系，探索新型农村集体经济发展路径。稳慎推进农村宅基地制度改革试点，规范开展房地一体宅基地确权登记。稳妥有序推进农村集体经营性建设用地入市。推动开展集体经营性建设用地使用权抵押融资。依法依规有序开展全域土地综合整治试点。深化集体林权制度改革。健全农垦国有农用地使用权管理制度。开展农村产权流转交易市场规范化建设试点。制定新阶段深化农村改革实施方案。","level":1},{"name":"八、坚持和加强党对“三农”工作的全面领导","text":"（三十三）压实全面推进乡村振兴责任。制定乡村振兴责任制实施办法，明确中央和国家机关各部门推进乡村振兴责任，强化五级书记抓乡村振兴责任。开展省级党政领导班子和领导干部推进乡村振兴战略实绩考核。完善市县党政领导班子和领导干部推进乡村振兴战略实绩考核制度，鼓励地方对考核排名靠前的市县给予适当激励，对考核排名靠后、履职不力的进行约谈。落实各级党委和政府负责同志乡村振兴联系点制度。借鉴推广浙江“千万工程”经验，鼓励地方党委和政府开展现场观摩、交流学习等务实管用活动。开展《乡村振兴战略规划（2018－2022年）》实施总结评估。加强集中换届后各级党政领导干部特别是分管“三农”工作的领导干部培训。\n（三十四）建强党的农村工作机构。各级党委农村工作领导小组要发挥“三农”工作牵头抓总、统筹协调等作用，一体承担巩固拓展脱贫攻坚成果、全面推进乡村振兴议事协调职责。推进各级党委农村工作领导小组议事协调规范化制度化建设，建立健全重点任务分工落实机制，协同推进乡村振兴。加强各级党委农村工作领导小组办公室建设，充实工作力量，完善运行机制，强化决策参谋、统筹协调、政策指导、推动落实、督导检查等职责。\n（三十五）抓点带面推进乡村振兴全面展开。开展“百县千乡万村”乡村振兴示范创建，采取先创建后认定方式，分级创建一批乡村振兴示范县、示范乡镇、示范村。推进农业现代化示范区创建。广泛动员社会力量参与乡村振兴，深入推进“万企兴万村”行动。按规定建立乡村振兴表彰激励制度。\n让我们紧密团结在以习近平同志为核心的党中央周围，真抓实干，埋头苦干，奋力开创全面推进乡村振兴新局面，以实际行动迎接党的二十大胜利召开！\n抓党建促乡村振兴","level":1}]},{"id":"r0565","sections":[{"name":"中共中央办公厅 国务院办公厅关于推进绿色低碳转型加强全国碳市场建设的意见","text":"中共中央办公厅 国务院办公厅关于推进绿色低碳转型加强全国碳市场建设的意见\n（2025年5月24日）","level":1},{"name":"","text":"碳市场是利用市场机制积极应对气候变化、加快经济社会发展全面绿色转型的重要政策工具。目前，我国已建立重点排放单位履行强制减排责任的全国碳排放权交易市场和激励社会自主减排的全国温室气体自愿减排交易市场。为推动建设更加有效、更有活力、更具国际影响力的全国碳市场，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，全面贯彻习近平经济思想、习近平生态文明思想，坚持稳中求进工作总基调，兼顾绿色低碳转型和经济发展需要，坚持有效市场、有为政府，坚持碳市场作为控制温室气体排放政策工具的基本定位，加快建设全国统一的碳市场，有计划分步骤扩大实施范围、扩展参与主体，营造更加公平公开透明的市场环境，努力实现碳排放资源配置效率最优化和效益最大化，推动传统产业深度转型，培育发展新质生产力，激发全社会绿色低碳发展内生动力，为积极稳妥推进碳达峰碳中和、建设美丽中国提供重要支撑。\n主要目标是：到2027年，全国碳排放权交易市场基本覆盖工业领域主要排放行业，全国温室气体自愿减排交易市场实现重点领域全覆盖。到2030年，基本建成以配额总量控制为基础、免费和有偿分配相结合的全国碳排放权交易市场，建成诚信透明、方法统一、参与广泛、与国际接轨的全国温室气体自愿减排交易市场，形成减排效果明显、规则体系健全、价格水平合理的碳定价机制。","level":1},{"name":"二、加快建设全国碳排放权交易市场","text":"（一）扩大全国碳排放权交易市场覆盖范围。根据行业发展状况、降碳减污贡献、数据质量基础、碳排放特征等，有序扩大覆盖行业范围和温室气体种类。\n（二）完善碳排放配额管理制度。建立预期明确、公开透明的碳排放配额管理制度，保持政策稳定性和连续性。综合考虑经济社会发展、行业特点、低碳转型成本等，明确市场中长期碳排放配额控制目标。根据国家温室气体排放控制目标及碳排放双控要求，处理好与能源安全、产业链供应链安全、民生保障的关系，科学设定配额总量，逐步由强度控制转向总量控制。到2027年，对碳排放总量相对稳定的行业优先实施配额总量控制。稳妥推行免费和有偿相结合的碳排放配额分配方式，有序提高有偿分配比例。建立配额储备和市场调节机制，平衡市场供需，增强市场稳定性和流动性。合理确定用核证自愿减排量抵销碳排放配额清缴的比例。\n（三）加强对碳排放权交易试点市场的指导和监督管理。统筹好全国碳排放权交易市场和有关地方试点开展的碳市场。现有碳排放权交易试点市场要按照有关要求规范建设运行，助力区域绿色低碳转型。鼓励碳排放权交易试点市场在扩大覆盖范围、完善市场调节机制、创新监管手段、健康有序发展碳金融等方面先行先试，为全国碳排放权交易市场建设探索经验。建立定期评估和退出机制，不再新建地方或区域碳排放权交易市场。","level":1},{"name":"三、积极发展全国温室气体自愿减排交易市场","text":"（四）加快自愿减排交易市场建设。建立科学完备的方法学体系，针对可持续发展效益显著、社会期待高、社会和生态效益兼具的重点领域加快方法学开发，有效服务社会自主减排和生态产品价值实现。强化自愿减排项目开发、审定、实施及减排量核查等全链条管理。项目业主、审定与核查机构要恪守诚信原则，严格落实承诺事项，主动接受社会监督。加强全国碳减排资源统筹管理，规范各类自愿减排交易活动。\n（五）积极推动核证自愿减排量应用。倡导推动党政机关、企业、社会团体等在绿色供应链管理、开展大型活动、履行社会责任、绿色低碳生活等方面，积极使用核证自愿减排量抵销碳排放，各级党政机关和国有企业要发挥表率作用。完善核证自愿减排量抵销规则，提高国际认可度，积极服务有关行业企业国际履约和产品碳中和。","level":1},{"name":"四、着力提升碳市场活力","text":"（六）丰富交易产品。稳慎推进金融机构探索开发与碳排放权和核证自愿减排量相关的绿色金融产品和服务，加大对温室气体减排的支持力度。建立完善碳质押、碳回购等政策制度，规范开展与碳排放权相关的金融活动，拓展企业碳资产管理渠道。以全国碳市场为主体建立完善碳定价机制，充分利用全国碳市场的价格发现功能，为金融支持绿色低碳发展提供有效的价格信号。\n（七）扩展交易主体。支持银行等金融机构规范开展碳质押融资业务，稳妥推进符合要求的金融机构在依法合规、风险可控前提下参与全国碳市场交易，适时引入其他非履约主体。全国温室气体自愿减排交易市场逐步引入符合条件的自然人参与交易。\n（八）加强市场交易监管。规范重大政策信息发布，完善市场交易风险预防预警及处置程序，开展全国碳市场价格跟踪评估，推动形成合理交易价格。加强交易行为监管，严厉打击扰乱市场秩序、操纵市场等行为。建立重点排放单位履约风险评估预警和管理制度，防范履约风险。加强对碳金融活动的监督管理，引导金融机构按照市场化、法治化原则做好金融服务，守住不发生系统性金融风险的底线。","level":1},{"name":"五、全面加强碳市场能力建设","text":"（九）完善管理体制和支撑体系。建立健全与全国碳市场发展阶段相适应、有利于加强统一监督管理、权责清晰、运行高效的管理体系。加强全国碳市场管理能力建设。推动建设全链条、数字化、智能化的全国碳市场管理系统、注册登记系统和交易系统，强化服务功能，保障数据安全。\n（十）加强碳排放核算与报告管理。健全企业温室气体排放报告制度。结合全国碳市场建设，加快修订重点行业企业温室气体核算与报告指南，条件成熟后转化为国家标准。实施碳排放核算分类管理，完善基于排放因子法的核算体系，探索开展基于自动监测的碳排放核算。加强碳排放关键计量器具配备、使用和管理，依法进行检定或校准，制定计量技术规范，开展碳排放计量审查。实施重点排放单位关键参数月度存证。\n（十一）严格规范碳排放核查。完善重点行业核查技术规范，明确核查要点和要求，规范核查流程。推动审定核查机构严格遵循客观独立、诚实守信、公平公正、专业严谨的原则，对碳排放进行全面核实查证，确保审定、核查结果的准确性和可信度。对碳排放报告持续保持高质量的重点排放单位可结合实际简化核查。\n（十二）加强碳排放数据质量全过程监管。压实重点排放单位履行碳排放核算与报告的主体责任，推动企业建立健全碳排放数据质量内部管理制度。地方生态环境、市场监管部门会同有关部门加强碳排放数据日常监督管理，综合运用大数据、区块链、物联网等技术，提升监管水平。加大违法违规行为查处力度，严厉打击弄虚作假行为。\n（十三）加强技术服务机构监管。对全国碳排放权交易市场核查机构实施认证机构资质管理，明确准入条件、行为规范和退出机制。加强碳排放相关检验检测机构管理，建立违规机构清出机制。积极培育咨询服务、检验检测、审定核查等技术服务业，定期开展评估，促进第三方技术服务市场健康发展，打造更多国际性专业服务机构。推动技术服务机构加强行业自律管理。\n（十四）完善信息披露制度。重点排放单位、注册登记机构、交易机构、技术服务机构、金融机构等根据有关要求及时公开排放、履约、交易、质押等相关信息，接受社会监督。建立碳市场相关数据部门共享机制。依法加强重点排放单位、技术服务机构和金融机构信用监督管理。","level":1},{"name":"六、加强组织实施保障","text":"（十五）加强组织领导。在党中央集中统一领导下，各地区各有关部门要结合实际抓好本意见贯彻落实。地方各级党委和政府要加强组织领导，积极推进绿色低碳转型，强化对碳市场建设运行的政策支持，加强对重点排放单位的监督管理，扎实做好本地区重点排放单位配额发放、配额清缴、数据质量管理等工作。生态环境部要加强碳市场建设统筹协调、组织实施和跟踪评估，系统推进任务落地落实。有关部门要根据职责分工，加强协调配合和监管指导，形成工作合力。重大事项及时按程序向党中央、国务院请示报告。\n（十六）强化政策法规支撑。研究完善相关法律法规，为碳市场建设提供法律支撑。开展温室气体自愿减排交易管理相关立法研究。健全行政执法与刑事司法衔接长效机制，依法开展相关领域检察公益诉讼，加大对碳市场违法犯罪行为的联合打击力度。完善裁判规则体系，依法支持行政机关履行碳市场行政监管职责。加强全国碳市场与绿电、绿证等市场化机制的政策协同、制度衔接。制定全国碳市场注册登记和交易收费规则。完善全国碳市场资金清算机制，提高资金清算效率。降低碳市场制度性交易成本。\n（十七）深化国际交流与合作。积极参与应对气候变化《巴黎协定》相关碳市场机制规则制定，推动全球绿色低碳公正转型。加强国际磋商和对话交流。加强碳市场领域交流合作，推动技术、方法、标准、数据国际互认。多渠道宣传我国碳市场建设做法和经验。","level":1}]},{"id":"r0566","sections":[{"name":"中共中央 国务院关于表彰全国劳动模范和先进工作者的决定","text":"中共中央 国务院关于表彰全国劳动模范和先进工作者的决定\n（2015年4月28日）","level":1},{"name":"","text":"2010年以来特别是党的十八大以来，在全面建成小康社会、加快推进社会主义现代化、夺取中国特色社会主义新胜利的伟大实践中，各行各业涌现出一大批爱岗敬业、勇于创新、品格高尚、业绩突出的先进模范人物。他们是我国工人阶级和广大劳动群众的优秀代表，是坚持中国道路、弘扬中国精神、凝聚中国力量的时代楷模。为表彰他们的突出贡献，弘扬伟大的时代精神、创业精神、奉献精神，进一步激励全国各族人民积极推进“四个全面”战略布局，促进经济平稳健康发展和社会和谐稳定，值此“五一”国际劳动节之际，党中央、国务院决定，授予白永明等2064人全国劳动模范荣誉称号，授予吴甡等904人全国先进工作者荣誉称号。\n希望获得全国劳动模范和先进工作者荣誉称号的同志，珍惜荣誉、再接再厉，继续做坚定理想信念的模范、勤奋劳动的模范、增进团结的模范，努力在新的征途上再创新业、再立新功。\n全国各族人民要更加紧密地团结在以习近平同志为总书记的党中央周围，全面贯彻党的十八大和十八届三中、四中全会精神，高举中国特色社会主义伟大旗帜，以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神，积极培育和践行社会主义核心价值观，大力弘扬“爱岗敬业、争创一流，艰苦奋斗、勇于创新，淡泊名利、甘于奉献”的劳模精神，营造劳动光荣、知识崇高、人才宝贵、创造伟大的社会氛围，通过辛勤劳动创造更加幸福美好的生活，为实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦而努力奋斗！","level":0}]},{"id":"r0567","sections":[{"name":"关于进一步加强东西部扶贫协作工作的指导意见","text":"Normal\r\n 0\r\n \r\n \r\n \r\n 7.8 磅\r\n 0\r\n 2\r\n \r\n false\r\n false\r\n false\r\n \r\n EN-US\r\n ZH-CN\r\n X-NONE","level":1},{"name":"","text":"近日，中共中央办公厅、国务院办公厅印发《关于进一步加强东西部扶贫协作工作的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。\n《关于进一步加强东西部扶贫协作工作的指导意见》全文如下。\n东西部扶贫协作和对口支援，是推动区域协调发展、协同发展、共同发展的大战略，是加强区域合作、优化产业布局、拓展对内对外开放新空间的大布局，是打赢脱贫攻坚战、实现先富帮后富、最终实现共同富裕目标的大举措。为全面贯彻落实《中共中央、国务院关于打赢脱贫攻坚战的决定》和中央扶贫开发工作会议、东西部扶贫协作座谈会精神，做好东西部扶贫协作和对口支援工作，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。全面贯彻党的十八大和十八届三中、四中、五中、六中全会精神，以习近平总书记扶贫开发重要战略思想为指导，牢固树立新发展理念，坚持精准扶贫、精准脱贫基本方略，进一步强化责任落实、优化结对关系、深化结对帮扶、聚焦脱贫攻坚，提高东西部扶贫协作和对口支援工作水平，推动西部贫困地区与全国一道迈入全面小康社会。\n（二）主要目标。经过帮扶双方不懈努力，推进东西部扶贫协作和对口支援工作机制不断健全，合作领域不断拓展，综合效益得到充分发挥，确保西部地区现行国家扶贫标准下的农村贫困人口到2020年实现脱贫，贫困县全部摘帽，解决区域性整体贫困。\n（三）基本原则\n——坚持党的领导，社会广泛参与。帮扶双方党委和政府要加强对东西部扶贫协作和对口支援工作的领导，将工作纳入重要议事日程，科学编制帮扶规划并认真部署实施，建立完善机制，广泛动员党政机关、企事业单位和社会力量参与，形成帮扶合力。\n——坚持精准聚焦，提高帮扶实效。东西部扶贫协作和对口支援要聚焦脱贫攻坚，按照精准扶贫、精准脱贫要求，把被帮扶地区建档立卡贫困人口稳定脱贫作为工作重点，帮扶资金和项目瞄准贫困村、贫困户，真正帮到点上、扶到根上。\n——坚持优势互补，鼓励改革创新。立足帮扶双方实际情况，因地制宜、因人施策开展扶贫协作和对口支援，实现帮扶双方优势互补、长期合作、聚焦扶贫、实现共赢，努力探索先富帮后富、逐步实现共同富裕的新途径新方式。\n——坚持群众主体，激发内生动力。充分调动贫困地区干部群众积极性创造性，不断激发脱贫致富的内生动力，帮助和带动贫困人口苦干实干，实现光荣脱贫、勤劳致富。","level":1},{"name":"二、结对关系","text":"（四）调整东西部扶贫协作结对关系。对原有结对关系进行适当调整，在完善省际结对关系的同时，实现对民族自治州和西部贫困程度深的市州全覆盖，落实北京市、天津市与河北省扶贫协作任务。调整后的东西部扶贫协作结对关系为：北京市帮扶内蒙古自治区、河北省张家口市和保定市；天津市帮扶甘肃省、河北省承德市；辽宁省大连市帮扶贵州省六盘水市；上海市帮扶云南省、贵州省遵义市；江苏省帮扶陕西省、青海省西宁市和海东市，苏州市帮扶贵州省铜仁市；浙江省帮扶四川省，杭州市帮扶湖北省恩施土家族苗族自治州、贵州省黔东南苗族侗族自治州，宁波市帮扶吉林省延边朝鲜族自治州、贵州省黔西南布依族苗族自治州；福建省帮扶宁夏回族自治区，福州市帮扶甘肃省定西市，厦门市帮扶甘肃省临夏回族自治州；山东省帮扶重庆市，济南市帮扶湖南省湘西土家族苗族自治州，青岛市帮扶贵州省安顺市、甘肃省陇南市；广东省帮扶广西壮族自治区、四川省甘孜藏族自治州，广州市帮扶贵州省黔南布依族苗族自治州和毕节市，佛山市帮扶四川省凉山彝族自治州，中山市和东莞市帮扶云南省昭通市，珠海市帮扶云南省怒江傈僳族自治州。\n各省（自治区、直辖市）要根据实际情况，在本行政区域内组织开展结对帮扶工作。\n（五）开展携手奔小康行动。东部省份组织本行政区域内经济较发达县（市、区）与扶贫协作省份和市州扶贫任务重、脱贫难度大的贫困县开展携手奔小康行动。探索在乡镇之间、行政村之间结对帮扶。\n（六）深化对口支援。对口支援西藏、新疆和四省藏区工作在现有机制下继续坚持向基层倾斜、向民生倾斜、向农牧民倾斜，更加聚焦精准扶贫、精准脱贫，瞄准建档立卡贫困人口精准发力，提高对口支援实效。北京市、天津市与河北省扶贫协作工作，要与京津冀协同发展中京津两市对口帮扶张承环京津相关地区做好衔接。","level":1},{"name":"三、主要任务","text":"（七）开展产业合作。帮扶双方要把东西部产业合作、优势互补作为深化供给侧结构性改革的新课题，研究出台相关政策，大力推动落实。要立足资源禀赋和产业基础，激发企业到贫困地区投资的积极性，支持建设一批贫困人口参与度高的特色产业基地，培育一批带动贫困户发展产业的合作组织和龙头企业，引进一批能够提供更多就业岗位的劳动密集型企业、文化旅游企业等，促进产业发展带动脱贫。加大产业合作科技支持，充分发挥科技创新在增强西部地区自我发展能力中的重要作用。\n（八）组织劳务协作。帮扶双方要建立和完善劳务输出精准对接机制，提高劳务输出脱贫的组织化程度。西部地区要摸清底数，准确掌握建档立卡贫困人口中有就业意愿和能力的未就业人口信息，以及已在外地就业人员的基本情况，因人因需提供就业服务，与东部地区开展有组织的劳务对接。西部地区要做好本行政区域内劳务对接工作，依托当地产业发展，多渠道开发就业岗位，支持贫困人口在家乡就地就近就业。开展职业教育东西协作行动计划和技能脱贫“千校行动”，积极组织引导贫困家庭子女到东部省份的职业院校、技工学校接受职业教育和职业培训。东部省份要把解决西部贫困人口稳定就业作为帮扶重要内容，创造就业机会，提供用工信息，动员企业参与，实现人岗对接，保障稳定就业。对在东部地区工作生活的建档立卡贫困人口，符合条件的优先落实落户政策，有序实现市民化。\n（九）加强人才支援。帮扶双方要选派优秀干部挂职，广泛开展人才交流，促进观念互通、思路互动、技术互学、作风互鉴。采取双向挂职、两地培训、委托培养和组团式支教、支医、支农等方式，加大教育、卫生、科技、文化、社会工作等领域的人才支持，把东部地区的先进理念、人才、技术、信息、经验等要素传播到西部地区。加大政策激励力度，鼓励各类人才扎根西部贫困地区建功立业。帮扶省市选派到被帮扶地区的挂职干部要把主要精力放到脱贫攻坚上，挂职期限原则上两到三年。加大对西部地区干部特别是基层干部、贫困村创业致富带头人培训力度。\n（十）加大资金支持。东部省份要根据财力增长情况，逐步增加扶贫协作和对口支援财政投入，并列入年度预算。西部地区要以扶贫规划为引领，整合扶贫协作和对口支援资金，聚焦脱贫攻坚，形成脱贫合力。要切实加强资金监管，提高使用效益。\n（十一）动员社会参与。帮扶省市要鼓励支持本行政区域内民营企业、社会组织、公民个人积极参与东西部扶贫协作和对口支援。充分利用全国扶贫日和中国社会扶贫网等平台，组织社会各界到西部地区开展捐资助学、慈善公益医疗救助、支医支教、社会工作和志愿服务等扶贫活动。实施社会工作专业人才服务贫困地区计划和扶贫志愿者行动计划，支持东部地区社会工作机构、志愿服务组织、社会工作者和志愿者结对帮扶西部贫困地区，为西部地区提供专业人才和服务保障。注重发挥军队和武警部队在西部贫困地区脱贫攻坚中的优势和积极作用，因地制宜做好帮扶工作。积极组织民营企业参与“万企帮万村”精准扶贫行动，与被帮扶地区贫困村开展结对帮扶。","level":1},{"name":"四、保障措施","text":"（十二）加强组织领导。国务院扶贫开发领导小组要加强东西部扶贫协作的组织协调、工作指导和考核督查。东西部扶贫协作双方要建立高层联席会议制度，党委或政府主要负责同志每年开展定期互访，确定协作重点，研究部署和协调推进扶贫协作工作。\n（十三）完善政策支持。中央和国家机关各部门要加大政策支持力度。国务院扶贫办、国家发展改革委、教育部、民政部、人力资源社会保障部、农业部、中国人民银行等部门要按照职责分工，加强对东西部扶贫协作和对口支援工作的指导和支持。中央组织部要统筹东西部扶贫协作和对口支援挂职干部人才选派管理工作。审计机关要依法加强对扶贫政策落实情况和扶贫资金的审计监督。纪检监察机关要加强扶贫领域监督执纪问责。\n（十四）开展考核评估。把东西部扶贫协作工作纳入国家脱贫攻坚考核范围，作为国家扶贫督查巡查重要内容，突出目标导向、结果导向，督查巡查和考核内容包括减贫成效、劳务协作、产业合作、人才支援、资金支持五个方面，重点是解决多少建档立卡贫困人口脱贫。对口支援工作要进一步加强对精准扶贫工作成效的考核。东西部扶贫协作考核工作由国务院扶贫开发领导小组组织实施，考核结果向党中央、国务院报告。","level":1}]},{"id":"r0568","sections":[{"name":"中共中央办公厅 国务院办公厅关于进一步保障和改善民生 着力解决群众急难愁盼的意见","text":"中共中央办公厅 国务院办公厅关于进一步保障和改善民生 着力解决群众急难愁盼的意见\n（2025年3月2日）","level":1},{"name":"","text":"为进一步保障和改善民生，着力解决群众急难愁盼，推动民生建设更加公平、均衡、普惠、可及，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、增强社会保障公平性","text":"（一）有效扩大社会保障覆盖面。强化社会保险在社会保障体系中的主体作用，健全灵活就业人员、农民工、新就业形态人员社会保险制度，全面取消在就业地参加社会保险的户籍限制，健全参保激励约束机制，完善转移接续机制，稳妥有序提高城镇就业人员参加职工基本养老保险和医疗保险比例。优化城乡居民基本养老保险缴费档次设置，合理确定缴费补贴水平，适当增加缴费灵活性，健全多缴多得激励机制。对符合条件的高校毕业生、就业困难人员等予以社会保险补贴。健全城乡居民基本医疗保险筹资机制，推动缴费与城乡居民人均可支配收入相挂钩，对连续参保和当年零报销人员按规定提高次年大病保险最高支付限额，有序推进职工基本医疗保险个人账户跨省共济。继续将技能提升补贴申领对象放宽至领取失业保险金人员。支持引导有条件的地方将生育保险生育津贴按程序直接发放给参保人。加强社会保险与社会救助、社会福利制度衔接，精准落实为困难群体代缴城乡居民社会保险费政策，增强低收入人口抗风险能力。\n（二）加强低收入群体兜底帮扶。充分运用大数据比对与实地摸排相结合等方式，加强动态监测预警，及时将符合条件的群众纳入社会救助范围。制定低收入人口认定办法、低收入家庭经济状况核对办法，全面开展低保边缘家庭、刚性支出困难家庭认定。合理确定调整最低生活保障标准，与城乡居民人均消费支出相挂钩，切实保障困难群众基本生活。加强最低生活保障标准与其他社会救助标准的统筹衔接。完善最低工资标准调整机制，合理提高最低工资标准。制定技能人才最低工资分类参考指引。实施农村低收入人口开发式帮扶提能增收行动，建立农村低收入家庭劳动力劳动伤害帮扶机制。加大以工代赈实施力度，优先吸纳带动低收入人口就地就近就业增收。","level":1},{"name":"二、提高基本公共服务均衡性","text":"（三）全方位提高基本公共服务质效。依据国家基本公共服务标准，细化制定分地区分领域基本服务项目清单、基本质量标准、均衡评估办法。根据经济社会发展水平和财政可承受能力，适时将涉及群众切身利益的增量服务事项纳入国家基本公共服务标准。推动基本公共服务供给与人口变化相协调，按照服务半径合理、规模适度、功能适用、保障有力要求，优化服务设施建设和运行管理。支持各地建立健全存量公共服务设施统筹利用机制。以县域为基本单元，全面推进公共服务规划布局、设施建设、资源配置、人才调配城乡一体化。支持面向艰苦边远地区农村提供形式灵活的基本公共服务。优化基本公共服务供给方式，符合条件的新增基本公共服务事项优先以政府购买服务方式提供。推动数字智能技术与公共服务深度融合，加快信息数据互通共享，推进婚姻登记等常用服务事项取消户籍地限制全国通办，扩大优质数字公共服务资源覆盖面。\n（四）推行由常住地提供基本公共服务。采取常住地直接提供、跨区域协同经办、完善转移接续等方式，逐步将基本公共服务调整为常住地提供。推动人口集中流入地城市“一城一策”制定常住地提供基本公共服务实施办法，推动符合条件的农业转移人口享有同迁入地户籍人口同等权利。稳步推进灵活就业人员参加住房公积金制度。支持各地统筹资金渠道，加大保障性住房供给，引导支持社会力量运营长期租赁住房。","level":1},{"name":"三、扩大基础民生服务普惠性","text":"（五）推动教育资源扩优提质。实施基础教育扩优提质行动计划，通过挖潜扩容扩大现有优质中小学校、公办幼儿园学位供给，将义务教育基础薄弱学校纳入优质学校集团化办学或托管帮扶。用5年左右时间，逐步实现义务教育学校标准化建设全覆盖。新建改扩建1000所以上优质普通高中，重点改善县域普通高中基本办学条件。加快扩大优质普通高中招生指标到校比例，主要依据学生规模分配到区域内初中学校，并向农村学校等倾斜。推动高等教育提质扩容，新增高等教育资源适度向中西部人口大省倾斜。支持布局新型研究型大学和高水平中外合作办学，逐步提高优质高校本科招生规模。全面深化产教融合改革，引导高校面向经济社会发展需要完善学科专业设置调整机制，强化行业企业实践培养，支持高校针对社会急需紧缺技能开展“微专业”建设，增强学生就业创业能力。\n（六）推进优质医疗卫生资源共享。推进优质医疗资源扩容下沉和区域均衡布局，优化区域医疗中心建设模式、管理体制和运行机制。实施医疗卫生强基工程，推动城市医疗资源向县级医院和城乡基层下沉，逐步实现紧密型县域医共体建设全覆盖。支持高水平医院人员、服务、技术、管理等向基层医疗卫生机构下沉，推进城市医联体建设。支持高水平医学人才向县级医院下沉，重点强化基层医疗卫生机构短板专业建设，因地制宜培育办好基层特色专科，提高常见病多发病诊治水平，推动基层医疗卫生机构提高服务能力。推动建立远程医疗服务网络，推广“分布式检查、集中式诊断”医疗服务模式。完善基本医疗保险药品目录调整机制，制定出台商业健康保险创新药品目录，更好满足人民群众多层次用药保障需求。\n（七）大力发展“一老一小”普惠服务。推动各地多渠道扩大“一老一小”服务低成本场地设施供给。支持“一老一小”服务机构提供质量有保障、价格可承受、运营可持续的普惠服务。完善普惠养老、普惠托育服务价格形成机制，对基本服务收费加强引导。以失能老年人照护为重点，提高养老服务机构医养结合服务能力，增加护理型床位供给，新建养老机构护理型床位占比原则上不低于80%。支持普惠养老服务增量资源向社区倾斜，增强日间照料、康复护理、上门服务等能力，积极发展家庭养老床位，完善家庭养老支持政策。积极发展农村互助性养老服务，引导有条件的乡镇敬老院向社会提供服务，优先满足孤寡、残障失能、高龄留守和低保家庭老年人照护需求。多渠道增加公建托位供给，大力发展社区嵌入式托育和家庭托育点，支持有条件的幼儿园延伸发展托育服务，用10年左右时间，推动有条件的大城市逐步实现嵌入式等普惠托育覆盖80%以上社区。推动普惠托育纳入企事业单位职工福利体系，用人单位开展普惠托育服务的有关支出，按规定从职工福利费中列支，用人单位工会经费可以适当补充。","level":1},{"name":"四、提升多样化社会服务可及性","text":"（八）发展群众家门口的社区服务。以社区为主场景主阵地，加强各类便民服务资源统筹整合，推进服务设施复合利用，完善社区嵌入式服务设施，提供一站式便民服务。支持养老、托育、家政、助餐、助残等普惠社会服务进社区，允许提供社区群众急需服务的经营主体在确保安全规范前提下租赁普通住宅设置服务网点。充分利用社会化资源，因地制宜发展老年助餐服务。加强家庭教育社区支持，建设群众可感可及的社区公共文化空间，支持社区广泛开展邻里互助服务。\n（九）提高多样化生活服务品质。完善全民健身公共服务体系，推进体育公园、健身步道等建设，支持社会体育场地建设，发展功能复合的多用途运动场地，稳步增加体育场地供给。推动文化、旅游、健康、体育等业态融合发展。积极推动将利用率高的中小型体育场馆、全民健身中心向社会免费或低收费开放。支持有条件的博物馆、图书馆、美术馆等文化场馆夜间开放。支持有条件的地区依托户外运动优质资源和优势项目，打造设施完善、服务优质、赛事丰富的高质量户外运动目的地。推动全民阅读，建设覆盖城乡、实用便利、服务高效的全民阅读设施。\n（十）促进包容共享发展。在公共政策制定、公共设施建设、公共服务供给中落实儿童优先原则和儿童友好理念。提升儿童福利服务机构日常生活照料、基本医疗、基本康复、教育权益保障、社会工作能力。深化“爱心妈妈”结对关爱，帮助解决留守儿童、困境儿童亲情陪伴、安全照护等方面的实际问题。完善青年发展促进政策，为青年在求学工作、婚恋生育、社会融入等方面提供更多支持。引导支持在保障性住房中加大兼顾职住平衡的宿舍型、小户型青年公寓供给。清理取消限制老年人社会参与的不合理政策规定，支持推广“以老助老”服务模式，开发适合大龄劳动者的多样化工作岗位。大力发展老年用户友好的智能技术产品和应用，推动公共设施、居民住宅等多层建筑加装电梯。完善困难残疾人生活补贴、重度残疾人护理补贴标准动态调整机制。完善孕期妇女产前检查基本服务，鼓励有条件的地方为适龄女孩接种人乳头瘤病毒（HPV）疫苗。全面推进城乡公共空间适儿化、适老化和无障碍改造。完善社会保险、社会福利、税收等方面支持家庭发展政策。","level":1},{"name":"五、保障措施","text":"各地区各有关部门要在党中央集中统一领导下，把党的领导贯彻到民生工作的各领域全过程，结合实际抓好本意见贯彻落实。按照中央和地方财政事权和支出责任划分，发挥财政转移支付促进基本公共服务均等化作用。提高预算内投资支持社会事业比重。各地要强化责任落实，坚持尽力而为、量力而行，优化财政支出结构，强化基本民生财力保障，持续完善教育、卫生健康、社保、就业等重点民生领域支持政策，切实兜住兜牢民生底线。完善各级政府民生实事清单制度。加强重大民生政策跨部门统筹协调，在宏观政策取向一致性评估时注重从社会公平角度评估对社会预期的影响。科学评价民生政策实施效果，对全国层面的预期性民生指标，不搞层层分解和“一刀切”考核。","level":1}]},{"id":"r0569","sections":[{"name":"从律师和法学专家中公开选拔立法工作者、法官、检察官办法","text":"近日，中共中央办公厅印发了《从律师和法学专家中公开选拔立法工作者、法官、检察官办法》，并发出通知，要求各地区各部门遵照执行。","level":1},{"name":"","text":"《从律师和法学专家中公开选拔立法工作者、法官、检察官办法》全文如下。\n第一条 为深化立法工作者、法官、检察官招录制度改革，推进法治专门队伍正规化、专业化、职业化建设，根据党的十八届三中、四中全会有关要求和相关规定，制定本办法。\n第二条 具有立法权的人大常委会的法制工作机构、政府法制部门、人民法院、人民检察院应当将从符合条件的律师、法学专家中公开选拔立法工作者、法官、检察官工作纳入队伍建设规划，并采取切实措施予以落实。\n第三条 具有立法权的人大常委会的法制工作机构、政府法制部门可以根据工作需要招录一定数量的律师、法学专家从事法律法规起草工作。人民法院、人民检察院应当把从律师、法学专家中选拔法官、检察官工作常态化、制度化。\n第四条 人民法院、人民检察院在招录、遴选法官、检察官时，应当根据工作实际预留适当数量的岗位用于从律师、法学专家中公开选拔法官、检察官。\n第五条 公开选拔坚持以下原则：\n（一）党管干部；\n（二）德才兼备、以德为先；\n（三）专业化、职业化；\n（四）公开、公正、竞争、择优。\n第六条 参加公开选拔的律师应当具备公务员法、法官法、检察官法规定的任职基本条件，并符合以下要求：\n（一）拥护党的领导，忠于宪法法律；\n（二）具有坚定的社会主义法治信仰、良好的职业操守；\n（三）具有独立办案能力，执业经验丰富，或者通晓境外法律制度并具有成功处理国际法律事务的经验，或者精通某些特殊专业领域的法律实务；\n（四）实际执业不少于五年，从业声誉良好。\n第七条 参加公开选拔的法学专家应当具备公务员法、法官法、检察官法规定的任职条件，并符合以下要求：\n（一）拥护党的领导，忠于宪法法律；\n（二）具有坚定的社会主义法治信仰、优良的师德和学术品行，公道正派；\n（三）自觉贯彻中国特色社会主义法治理论，善于理论联系实际；\n（四）具有讲师及以上职称，从事教学或者科研五年以上，有突出研究能力和优秀研究成果，具有法律实务工作经验的优先。\n第八条 律师、法学专家具有下列情形之一的，不得参加公开选拔：\n（一）被刑事处罚或者因违法违纪被辞退、开除或者吊销执业证书的；\n（二）有妨害司法公正行为的；\n（三）因违反职业道德、学术道德、执业纪律或者行业规范受到惩戒、处罚的；\n（四）受过党纪政纪处分的；\n（五）涉嫌违法违纪正在接受审查尚未结案的；\n（六）配偶已移居国（境）外，或者没有配偶，子女均已移居国（境）外的；\n（七）法律法规规定不得担任立法工作者、法官、检察官的其他情形。\n第九条公务员主管部门应当会同具有立法权的人大常委会的法制工作机构、政府法制部门、人民法院、人民检察院，在人员编制限额内制定公开选拔计划和实施方案，明确公开选拔的岗位、条件、程序。\n第十条对参加公开选拔人员能力和素质的考察考评工作应当科学规范，注重能力素质、职业伦理、工作实绩和一贯表现。参加公开选拔人员工作单位所在地的律师协会或者法学会，应当在充分听取参加公开选拔人员工作单位、从业相关人员意见的基础上，就参加公开选拔人员的政治态度、专业能力、品行操守出具评估意见。\n第十一条拟任法官、检察官入围人选的专业能力评审由法官、检察官遴选委员会负责。具有立法权的人大常委会的法制工作机构或者政府法制部门可以组织有关业务部门负责人、专家学者、律师对入围人选进行专业能力评审。评审应当通过查阅人事档案、承办案件卷宗或者论著、面谈等方式进行。\n第十二条 公开选拔应当接受社会监督。组织和纪检监察部门应当及时受理相关举报，并按照规定权限和程序处理。\n第十三条律师、法学专家被选拔为立法工作者、法官、检察官的，适用国家机关工作人员禁止性规定，不得持有非上市公司的股份；不得在企业、律师事务所及营利性机构兼职。\n律师、法学专家被选拔为法官、检察官的，其父母、配偶、子女在拟任职人民法院、人民检察院辖区内开办律师事务所、担任律师或者从事司法鉴定、司法拍卖等与司法活动利益相关职业的，应当按照任职回避的要求不再担任律师事务所设立人、合伙人或者退出股份、调整工作。\n在一年试用期内未能按照本条规定要求不再担任律师事务所设立人、合伙人或者退出股份、调整工作的，视为试用不合格，不予录用。\n第十四条鼓励法学专家到人大常委会法制工作机构、政府法制部门、人民法院、人民检察院挂职锻炼。上述单位应当为法学专家挂职锻炼创造条件。\n第十五条 被选拔为立法工作者、法官、检察官的律师、法学专家，比照所任职单位同等资历人员确定职务、级别、待遇。\n第十六条 本办法由中央政法委负责解释。\n第十七条 本办法自2016年6月2日起施行。","level":0}]},{"id":"r0570","sections":[{"name":"地方党委委员、纪委委员开展党内询问和质询办法（试行）","text":"第一条 为推动和规范党内询问和质询工作，发挥党的地方委员会委员、纪律检查委员会委员在党内监督中的作用，根据《中国共产党党内监督条例（试行）》有关规定，制定本办法。","level":1},{"name":"","text":"第二条 党的地方各级委员会委员、纪律检查委员会委员，对所在委员会全体会议决议、决定执行中存在的问题提出询问和质询，适用本办法。\n第三条 党委委员询问和质询的对象是所在党委的常委会、同级纪委，所在党委的工作部门、直属机构、派出机关、派出的巡视机构和所在党委批准成立的党组（党委）。\n纪委委员询问和质询的对象是所在纪委的常委会、派出机关、派驻机构。\n对常委会进行询问和质询时，可以要求询问和质询事项所涉及的相关党组织和有关部门参与说明、解释或者答复。\n第四条 党委委员、纪委委员提出的询问和质询由本级党委、纪委办公厅（室）分别负责受理。询问和质询对象为党委常委会或者纪委常委会的，分别由上一级党委、纪委办公厅（室）受理，其中对省级党委常委会、纪委常委会的询问和质询，分别由中央办公厅和中央纪委办公厅受理。\n询问和质询以书面形式提出。\n委员单独提出询问和质询；多名委员就同一问题分别提出询问和质询的，一并处理。\n提出质询，应当以提出过询问为前提条件。\n询问和质询应当按照本办法规定的时限受理和处理，有交通、通信不便等特殊原因的，可以适当延长。\n第五条 党委委员、纪委委员提出询问，应当填写《地方党委委员、纪委委员询问书》，送受理部门。\n对涉及多个对象的询问，应当分别填写《地方党委委员、纪委委员询问书》。\n第六条 党委委员、纪委委员提出的询问应当具备以下要件：\n（一）有明确的询问对象；\n（二）询问对象执行所在委员会全体会议决议、决定中存在的问题；\n（三）署真实姓名。\n第七条 受理部门自受理之日起15个工作日内，对符合第六条规定要件的询问，将《地方党委委员、纪委委员询问书》送交询问对象并告知询问人；对不符合第六条规定要件的，告知询问人，可以由其收回询问或者按照规定要件重新提出询问。\n第八条 询问对象应当自收到受理部门送交的《地方党委委员、纪委委员询问书》之日起20个工作日内作出书面说明，由其党组织负责人署名后送受理部门。存在询问书所涉及问题的，应当说明具体情况和整改措施；不存在询问书所涉及问题的，应当作出解释。\n受理部门收到询问对象所作的书面说明后，应当在5个工作日内送交询问人并留存备案。\n第九条 询问人对询问对象所作说明不满意或者询问对象未在规定期限内作出说明的，可以自收到说明或者说明期满之日起填写《地方党委委员、纪委委员质询书》，提出质询。\n对涉及多个对象的质询，应当分别填写《地方党委委员、纪委委员质询书》。\n第十条 党委委员、纪委委员提出的质询应当具备以下要件：\n（一）针对询问对象提出；\n（二）针对询问提出的同一问题提出；\n（三）有对询问对象所作说明不满意的理由或者询问对象未在规定期限内作出说明；\n（四）署真实姓名。\n第十一条 受理部门自受理之日起15个工作日内，对符合第十条规定要件的质询，将《地方党委委员、纪委委员质询书》送交质询对象并告知质询人；对不符合第十条规定要件的，告知质询人，可以由其收回质询或者按照规定要件重新提出质询。\n第十二条 质询对象应当自收到受理部门送交的《地方党委委员、纪委委员质询书》之日起30个工作日内作出书面答复，由其党组织负责人署名后送受理部门。\n受理部门收到质询对象所作的书面答复后，应当在5个工作日内送交质询人并留存备案。\n质询对象在规定期限内作出答复确有困难的，可以在到期日之前书面告知受理部门并说明理由，由受理部门决定是否予以适当延长，并将延长期限书面告知质询人。\n第十三条 质询人对质询对象作出的书面解释或者答复仍不满意，或者质询对象未在规定期限内作出书面解释或者答复的，质询人可以书面形式向党委常委会、纪委常委会提出或者向上一级党委、纪委反映。\n第十四条 对质询人提出或者反映的问题，党委常委会、纪委常委会或者上一级党委、纪委应当及时研究处理。\n必要时，可以成立调查组，对有关问题进行核实。\n第十五条 询问、质询对象对询问、质询情况及其办理结果，应当在年度工作报告中予以说明。\n第十六条 询问、质询对象认为询问、质询事项涉及保密内容的，应当书面说明情况并送受理部门。受理部门认为确应保密的，书面通知询问、质询对象对涉密内容可不作答复。\n询问、质询人不得传播在询问、质询中获悉的保密事项或者其他不宜扩散的情况。\n第十七条 受理部门拒不受理或者拖延办理询问、质询事项的，由同级党委或者纪委主要负责人对直接负责的主管人员和其他直接责任人员给予批评教育，责令限期改正。\n询问和质询对象不办理或者不按期办理，或者不如实答复询问和质询事项的，给予通报批评，责令限期改正；情节严重的，依照《中国共产党纪律处分条例》第六十二条的规定追究主要责任人员的责任。\n询问、质询对象打击报复或者有其他侵犯委员询问、质询权的，依照《中国共产党纪律处分条例》第一百四十条的规定追究主要责任人员的责任。\n质询人不按照规定程序开展质询、故意刁难、无理纠缠的，给予批评教育；情节严重的，比照《中国共产党纪律处分条例》第六十三条的规定处理。\n第十八条 纪律检查机关负责本办法执行情况的监督检查。询问和质询对象是所在纪委常委会的，由上一级纪律检查机关负责该询问和质询事项执行情况的监督检查。\n第十九条 各省、自治区、直辖市党委可以根据本办法制定实施细则。\n第二十条 本办法由中央纪律检查委员会商中央组织部解释。\n第二十一条 本办法自发布之日起施行。\n附件一：《地方党委委员、纪委委员询问书》\n附件二：《地方党委委员、纪委委员质询书》","level":0}]},{"id":"r0571","sections":[{"name":"关于查处党员违纪案件中收集、鉴别、使用证据的具体规定","text":"第一条 为正确收集、鉴别和使用证据，保证办案质量，正确执行党的纪律，特制定本规定。","level":1},{"name":"","text":"第二条 证明案件真实情况的一切事实都是证据。证据包括：\n1、物证，指能够证明案件真实情况的物品和痕迹。\n2、书证，指以其记载的内容证明案件真实情况的文字（包括符号、图画）。\n3、证人证言，指证人就其所了解的案件情况所作的陈述。凡是知道案件真实情况的人都可以作为证人。不能辨别是非的人，不能正确表达的人，不能作证人。\n4、视听材料，指可以将重现的原始声响或形象的录音录像用作证明案件事实的材料。\n5、受侵害人员的陈述，指受违纪行为直接侵害的人员就案件事实情况所作的控告和述说。\n6、受审查党员的陈述，指受审查党员就案件事实所作的交待、申辩和对同案违纪人员的检举、揭发。\n7、鉴定结论，指鉴定人运用专门知识或技能对办案人员不能解决的专门事项进行科学鉴定后所作出的结论。\n8、勘验、检查笔录，指公安、司法人员对与案件有关的场所、物品及其他证据材料进行勘验、检查时所作的笔录。\n9、现场笔录，指纪律检查人员对案件（非刑事案件）有关的场所进行检查时所作的笔录。\n证据必须经过审核属实，才能作为定案的根据。\n第三条 收集、鉴别和使用证据必须实事求是，一切从客观实际出发，不得带框框、主观臆断、偏听偏信；必须尊重党员的民主权利和公民的合法权利。任何党员和群众都有向党组织提供自己所知道的案情的义务。严禁使用威胁、引诱、欺骗及其他非法手段收集证据。\n第四条 收集违犯党纪案件的证据，由党的纪律检查工作人员或党组织委派的党员负责进行，收集证据必须两人以上。收集证据要及时、客观、全面。\n证据的收集主要由案件检查人员进行。案件审理人员在审理案件时，发现证据不足或证据间存在矛盾，一般由报案单位补充调查取证，需要补充个别证据的也可以由案件审理部门补充收集。\n第五条 收集物证应尽可能提取原物。物证能随卷保存的即随卷保存，不能提取的原物或不能随卷保存的原物应拍成照片入卷，并注明原物存放何处。\n第六条 收集书证采用提取会议记录、介绍信、文件、个人记录、私人信件、日记等方法，并尽可能提取原件。如不能提取原件的，用摘抄或复印的方法提取，但应注明出处、原件保存单位，并应由原件保存单位加盖公章。摘抄或复印会议记录、个人记录、私人日记时，要注意时间的连续性，节录材料不得断章取义。\n对可作为书证的原始材料或复制件，党的各级组织不得以任何借口拒绝提供。收集的材料涉及机密事项应履行一定的批准手续。党员有义务向组织提供记载有与案情有关系的工作记录本。\n对可作为书证的私人日记、信件等原始材料的收集只能采取动员的方法，不得强行收集，涉及个人隐私的，有关党组织应为其保密。\n第七条 凡是知道案件情况的党员和群众，都应及时地、如实地提供证言，不得拒绝作证。党员故意提供虚假情况，情节严重的给予必要的纪律处分。\n收集证人证言，不要采取座谈会的形式。证人证言要一人一证，一般情况下一事一证。由证人用钢笔或毛笔书写。没有书写能力的，由他人或调查取证人根据证人的讲述代写，写好后读给证人听，并按证人意见进行修改，然后由证人签字、盖章或按手印。书写证人证言，应把所要证明的事实发生的时间、地点、当事人、原因、情节、手段、结果等书写清楚。调查人员要做好询问笔录，并应由被询问人签字。\n对证人证言，应由取证人注明证人工作单位、职务，并由取证人签字。不必由所在单位加盖公章或加注“属实”、“供参考”之类的文字。\n证人作证后，如有补充、更正，可另行书写，并说明更正的理由。办案人员应将补充、更正的证人证言与该证人原出具的证言一并归入案卷。\n证人作证后，党组织应为其保密。如发现受审查党员及其亲友对证人打击报复，从严处理。\n第八条 收集受审查党员的陈述包括：受审查党员对自己所犯错误的交待或申辩；揭发同案违纪人员的材料。\n受审查党员应对党忠诚老实，如实向组织交待自己的问题，同时也有依据党章的规定为自己申辩的权利。受审查党员对“处分所依据的事实材料”如提出不同意见，有关党组织应认真研究并作出说明，一并归入案卷。\n第九条 纪律检查机关在需要时，可以运用公安机关、人民检察院、人民法院的鉴定结论、勘验检查笔录等。\n从公安机关、人民检察院、人民法院取得证据，按有关规定办理。\n纪律检查人员对有作案现场的非刑事案件，应注意对现场作出检查，并作好笔录。\n第十条 对受到刑事处罚、政纪处分的党员作党纪处理，必须收集主要证据材料。\n第十一条 鉴别证据的任务是：根据各种证据材料的具体特征，逐个进行审查和分析研究，鉴别其真伪，判断其与案件事实有无内在联系，对查明和证实案情有无意义。经过鉴别，确实符合客观实际，与案件事实有内在联系的证据，才能作为定案的依据。\n第十二条 鉴别证据，首先鉴别每个证据是否客观真实，是否伪造；是否与案件事实有联系；是原始证据还是传来证据，是直接证据还是间接证据，其来源有无问题，然后，综合分析证明案件的同一事实的各类证据之间有无矛盾；各种证据之间有无内在的联系，要注意时间、条件的变化对证据的影响，要把不同的证据摆到案件发生、发展的过程中去，考虑当时的历史背景，同其他证据联系起来综合分析。\n第十三条 对物证的鉴别，要审查是否错误地收集了疑似的物品和痕迹，收集的物证是否伪造，有无栽赃陷害的情况。研究、分析所取物证与案件事实的联系，确定其有无证明作用。\n第十四条 对书证的鉴别，要查清其原始制作人，是在何种情况下制作的，是否伪造，节录材料是否断章取义，所记载的内容有无差错，联系其他证据判断所取书证的真实性。\n第十五条 对证人证言的鉴别，要注意审查证言的内容与案件事实是否有联系，来源有无问题，是否受到外界不正常因素的干扰，是否属实，证言前后是否一致，有无矛盾。不得采用对质的方法鉴别证言。\n第十六条 对受审查党员陈述的鉴别，要审查其交待或申辩前后是否一致，有无矛盾，将交待或申辩与其他证据相对照，看其是否合情合理，是否属实。\n第十七条 对视听材料的鉴别，要注意是否伪造，是否被裁剪，是否拼接组合。\n第十八条 对受侵害人员陈述的鉴别，要注意受侵害人员感情因素对其陈述真实性的影响。\n第十九条 认定案件事实，证据必须确凿。证据经过鉴别，其真实性得到确认后，即成为有效证据，任何人无权涂改或弃毁，有关党组织在移送证据时，不得任意取舍。特别不得舍弃那些经过鉴别证明受审查党员无错的证据。要综合运用证据，证据之间矛盾时，不能仅凭数量多少决定其真实可靠性；认定主要错误事实所依据的证据之间的矛盾不能排除时，不能定案。\n第二十条 在没有物证、书证的情况下，仅凭言词证据定案时，必须有两个以上（含两个）证据，才能定案。\n第二十一条 没有直接证据而仅凭间接证据定案时，所有间接证据必须查证属实；每个证据与案件事实都有着客观联系；取得的证据必须形成一个完整的证明体系，这个证明体系足以排除其他可能性，才能定案。不能排除其他可能时，不能定案。\n第二十二条 仅有受审查党员的交待，没有其他证据，不能定案；受审查党员拒不承认，其他证据确实充分，仍可定案。\n第二十三条 本规定由中共中央纪律检查委员会案件审理室负责解释。\n第二十四条 本规定自下发之日起施行。","level":0}]},{"id":"r0572","sections":[{"name":"中共中央 国务院印发《国家标准化发展纲要》","text":"近日，中共中央、国务院印发了《国家标准化发展纲要》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《国家标准化发展纲要》主要内容如下。\n标准是经济活动和社会发展的技术支撑，是国家基础性制度的重要方面。标准化在推进国家治理体系和治理能力现代化中发挥着基础性、引领性作用。新时代推动高质量发展、全面建设社会主义现代化国家，迫切需要进一步加强标准化工作。为统筹推进标准化发展，制定本纲要。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，深入贯彻党的十九大和十九届二中、三中、四中、五中全会精神，按照统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局要求，坚持以人民为中心的发展思想，立足新发展阶段、贯彻新发展理念、构建新发展格局，优化标准化治理结构，增强标准化治理效能，提升标准国际化水平，加快构建推动高质量发展的标准体系，助力高技术创新，促进高水平开放，引领高质量发展，为全面建成社会主义现代化强国、实现中华民族伟大复兴的中国梦提供有力支撑。\n（二）发展目标\n到2025年，实现标准供给由政府主导向政府与市场并重转变，标准运用由产业与贸易为主向经济社会全域转变，标准化工作由国内驱动向国内国际相互促进转变，标准化发展由数量规模型向质量效益型转变。标准化更加有效推动国家综合竞争力提升，促进经济社会高质量发展，在构建新发展格局中发挥更大作用。\n——全域标准化深度发展。农业、工业、服务业和社会事业等领域标准全覆盖，新兴产业标准地位凸显，健康、安全、环境标准支撑有力，农业标准化生产普及率稳步提升，推动高质量发展的标准体系基本建成。\n——标准化水平大幅提升。共性关键技术和应用类科技计划项目形成标准研究成果的比率达到50%以上，政府颁布标准与市场自主制定标准结构更加优化，国家标准平均制定周期缩短至18个月以内，标准数字化程度不断提高，标准化的经济效益、社会效益、质量效益、生态效益充分显现。\n——标准化开放程度显著增强。标准化国际合作深入拓展，互利共赢的国际标准化合作伙伴关系更加密切，标准化人员往来和技术合作日益加强，标准信息更大范围实现互联共享，我国标准制定透明度和国际化环境持续优化，国家标准与国际标准关键技术指标的一致性程度大幅提升，国际标准转化率达到85%以上。\n——标准化发展基础更加牢固。建成一批国际一流的综合性、专业性标准化研究机构，若干国家级质量标准实验室，50个以上国家技术标准创新基地，形成标准、计量、认证认可、检验检测一体化运行的国家质量基础设施体系，标准化服务业基本适应经济社会发展需要。\n到2035年，结构优化、先进合理、国际兼容的标准体系更加健全，具有中国特色的标准化管理体制更加完善，市场驱动、政府引导、企业为主、社会参与、开放融合的标准化工作格局全面形成。","level":1},{"name":"二、推动标准化与科技创新互动发展","text":"（三）加强关键技术领域标准研究。在人工智能、量子信息、生物技术等领域，开展标准化研究。在两化融合、新一代信息技术、大数据、区块链、卫生健康、新能源、新材料等应用前景广阔的技术领域，同步部署技术研发、标准研制与产业推广，加快新技术产业化步伐。研究制定智能船舶、高铁、新能源汽车、智能网联汽车和机器人等领域关键技术标准，推动产业变革。适时制定和完善生物医学研究、分子育种、无人驾驶等领域技术安全相关标准，提升技术领域安全风险管理水平。\n（四）以科技创新提升标准水平。建立重大科技项目与标准化工作联动机制，将标准作为科技计划的重要产出，强化标准核心技术指标研究，重点支持基础通用、产业共性、新兴产业和融合技术等领域标准研制。及时将先进适用科技创新成果融入标准，提升标准水平。对符合条件的重要技术标准按规定给予奖励，激发全社会标准化创新活力。\n（五）健全科技成果转化为标准的机制。完善科技成果转化为标准的评价机制和服务体系，推进技术经理人、科技成果评价服务等标准化工作。完善标准必要专利制度，加强标准制定过程中的知识产权保护，促进创新成果产业化应用。完善国家标准化技术文件制度，拓宽科技成果标准化渠道。将标准研制融入共性技术平台建设，缩短新技术、新工艺、新材料、新方法标准研制周期，加快成果转化应用步伐。","level":1},{"name":"三、提升产业标准化水平","text":"（六）筑牢产业发展基础。加强核心基础零部件（元器件）、先进基础工艺、关键基础材料与产业技术基础标准建设，加大基础通用标准研制应用力度。开展数据库等方面标准攻关，提升标准设计水平，制定安全可靠、国际先进的通用技术标准。\n（七）推进产业优化升级。实施高端装备制造标准化强基工程，健全智能制造、绿色制造、服务型制造标准，形成产业优化升级的标准群，部分领域关键标准适度领先于产业发展平均水平。完善扩大内需方面的标准，不断提升消费品标准和质量水平，全面促进消费。推进服务业标准化、品牌化建设，健全服务业标准，重点加强食品冷链、现代物流、电子商务、物品编码、批发零售、房地产服务等领域标准化。健全和推广金融领域科技、产品、服务与基础设施等标准，有效防范化解金融风险。加快先进制造业和现代服务业融合发展标准化建设，推行跨行业跨领域综合标准化。建立健全大数据与产业融合标准，推进数字产业化和产业数字化。\n（八）引领新产品新业态新模式快速健康发展。实施新产业标准化领航工程，开展新兴产业、未来产业标准化研究，制定一批应用带动的新标准，培育发展新业态新模式。围绕食品、医疗、应急、交通、水利、能源、金融等领域智慧化转型需求，加快完善相关标准。建立数据资源产权、交易流通、跨境传输和安全保护等标准规范，推动平台经济、共享经济标准化建设，支撑数字经济发展。健全依据标准实施科学有效监管机制，鼓励社会组织应用标准化手段加强自律、维护市场秩序。\n（九）增强产业链供应链稳定性和产业综合竞争力。围绕生产、分配、流通、消费，加快关键环节、关键领域、关键产品的技术攻关和标准研制应用，提升产业核心竞争力。发挥关键技术标准在产业协同、技术协作中的纽带和驱动作用，实施标准化助力重点产业稳链工程，促进产业链上下游标准有效衔接，提升产业链供应链现代化水平。\n（十）助推新型基础设施提质增效。实施新型基础设施标准化专项行动，加快推进通信网络基础设施、新技术基础设施、算力基础设施等信息基础设施系列标准研制，协同推进融合基础设施标准研制，建立工业互联网标准，制定支撑科学研究、技术研发、产品研制的创新基础设施标准，促进传统基础设施转型升级。","level":1},{"name":"四、完善绿色发展标准化保障","text":"（十一）建立健全碳达峰、碳中和标准。加快节能标准更新升级，抓紧修订一批能耗限额、产品设备能效强制性国家标准，提升重点产品能耗限额要求，扩大能耗限额标准覆盖范围，完善能源核算、检测认证、评估、审计等配套标准。加快完善地区、行业、企业、产品等碳排放核查核算标准。制定重点行业和产品温室气体排放标准，完善低碳产品标准标识制度。完善可再生能源标准，研究制定生态碳汇、碳捕集利用与封存标准。实施碳达峰、碳中和标准化提升工程。\n（十二）持续优化生态系统建设和保护标准。不断完善生态环境质量和生态环境风险管控标准，持续改善生态环境质量。进一步完善污染防治标准，健全污染物排放、监管及防治标准，筑牢污染排放控制底线。统筹完善应对气候变化标准，制定修订应对气候变化减缓、适应、监测评估等标准。制定山水林田湖草沙多生态系统质量与经营利用标准，加快研究制定水土流失综合防治、生态保护修复、生态系统服务与评价、生态承载力评估、生态资源评价与监测、生物多样性保护及生态效益评估与生态产品价值实现等标准，增加优质生态产品供给，保障生态安全。\n（十三）推进自然资源节约集约利用。构建自然资源统一调查、登记、评价、评估、监测等系列标准，研究制定土地、矿产资源等自然资源节约集约开发利用标准，推进能源资源绿色勘查与开发标准化。以自然资源资产清查统计和资产核算为重点，推动自然资源资产管理体系标准化。制定统一的国土空间规划技术标准，完善资源环境承载能力和国土空间开发适宜性评价机制。制定海洋资源开发保护标准，发展海洋经济，服务陆海统筹。\n（十四）筑牢绿色生产标准基础。建立健全土壤质量及监测评价、农业投入品质量、适度规模养殖、循环型生态农业、农产品食品安全、监测预警等绿色农业发展标准。建立健全清洁生产标准，不断完善资源循环利用、产品绿色设计、绿色包装和绿色供应链、产业废弃物综合利用等标准。建立健全绿色金融、生态旅游等绿色发展标准。建立绿色建造标准，完善绿色建筑设计、施工、运维、管理标准。建立覆盖各类绿色生活设施的绿色社区、村庄建设标准。\n（十五）强化绿色消费标准引领。完善绿色产品标准，建立绿色产品分类和评价标准，规范绿色产品、有机产品标识。构建节能节水、绿色采购、垃圾分类、制止餐饮浪费、绿色出行、绿色居住等绿色生活标准。分类建立绿色公共机构评价标准，合理制定消耗定额和垃圾排放指标。","level":1},{"name":"五、加快城乡建设和社会建设标准化进程","text":"（十六）推进乡村振兴标准化建设。强化标准引领，实施乡村振兴标准化行动。加强高标准农田建设，加快智慧农业标准研制，加快健全现代农业全产业链标准，加强数字乡村标准化建设，建立农业农村标准化服务与推广平台，推进地方特色产业标准化。完善乡村建设及评价标准，以农村环境监测与评价、村容村貌提升、农房建设、农村生活垃圾与污水治理、农村卫生厕所建设改造、公共基础设施建设等为重点，加快推进农村人居环境改善标准化工作。推进度假休闲、乡村旅游、民宿经济、传统村落保护利用等标准化建设，促进农村一二三产业融合发展。\n（十七）推动新型城镇化标准化建设。研究制定公共资源配置标准，建立县城建设标准、小城镇公共设施建设标准。研究制定城市体检评估标准，健全城镇人居环境建设与质量评价标准。完善城市生态修复与功能完善、城市信息模型平台、建设工程防灾、更新改造及海绵城市建设等标准。推进城市设计、城市历史文化保护传承与风貌塑造、老旧小区改造等标准化建设，健全街区和公共设施配建标准。建立智能化城市基础设施建设、运行、管理、服务等系列标准，制定城市休闲慢行系统和综合管理服务等标准，研究制定新一代信息技术在城市基础设施规划建设、城市管理、应急处置等方面的应用标准。健全住房标准，完善房地产信息数据、物业服务等标准。推动智能建造标准化，完善建筑信息模型技术、施工现场监控等标准。开展城市标准化行动，健全智慧城市标准，推进城市可持续发展。\n（十八）推动行政管理和社会治理标准化建设。探索开展行政管理标准建设和应用试点，重点推进行政审批、政务服务、政务公开、财政支出、智慧监管、法庭科学、审判执行、法律服务、公共资源交易等标准制定与推广，加快数字社会、数字政府、营商环境标准化建设，完善市场要素交易标准，促进高标准市场体系建设。强化信用信息采集与使用、数据安全和个人信息保护、网络安全保障体系和能力建设等领域标准的制定实施。围绕乡村治理、综治中心、网格化管理，开展社会治理标准化行动，推动社会治理标准化创新。\n（十九）加强公共安全标准化工作。坚持人民至上、生命至上，实施公共安全标准化筑底工程，完善社会治安、刑事执法、反恐处突、交通运输、安全生产、应急管理、防灾减灾救灾标准，织密筑牢食品、药品、农药、粮食能源、水资源、生物、物资储备、产品质量、特种设备、劳动防护、消防、矿山、建筑、网络等领域安全标准网，提升洪涝干旱、森林草原火灾、地质灾害、地震等自然灾害防御工程标准，加强重大工程和各类基础设施的数据共享标准建设，提高保障人民群众生命财产安全水平。加快推进重大疫情防控救治、国家应急救援等领域标准建设，抓紧完善国家重大安全风险应急保障标准。构建多部门多区域多系统快速联动、统一高效的公共安全标准化协同机制，推进重大标准制定实施。\n（二十）推进基本公共服务标准化建设。围绕幼有所育、学有所教、劳有所得、病有所医、老有所养、住有所居、弱有所扶等方面，实施基本公共服务标准体系建设工程，重点健全和推广全国统一的社会保险经办服务、劳动用工指导和就业创业服务、社会工作、养老服务、儿童福利、残疾人服务、社会救助、殡葬公共服务以及公共教育、公共文化体育、住房保障等领域技术标准，使发展成果更多更公平惠及全体人民。\n（二十一）提升保障生活品质的标准水平。围绕普及健康生活、优化健康服务、倡导健康饮食、完善健康保障、建设健康环境、发展健康产业等方面，建立广覆盖、全方位的健康标准。制定公共体育设施、全民健身、训练竞赛、健身指导、线上和智能赛事等标准，建立科学完备、门类齐全的体育标准。开展养老和家政服务标准化专项行动，完善职业教育、智慧社区、社区服务等标准，加强慈善领域标准化建设。加快广播电视和网络视听内容融合生产、网络智慧传播、终端智能接收、安全智慧保障等标准化建设，建立全媒体传播标准。提高文化旅游产品与服务、消费保障、公园建设、景区管理等标准化水平。","level":1},{"name":"六、提升标准化对外开放水平","text":"（二十二）深化标准化交流合作。履行国际标准组织成员国责任义务，积极参与国际标准化活动。积极推进与共建“一带一路”国家在标准领域的对接合作，加强金砖国家、亚太经合组织等标准化对话，深化东北亚、亚太、泛美、欧洲、非洲等区域标准化合作，推进标准信息共享与服务，发展互利共赢的标准化合作伙伴关系。联合国际标准组织成员，推动气候变化、可持续城市和社区、清洁饮水与卫生设施、动植物卫生、绿色金融、数字领域等国际标准制定，分享我国标准化经验，积极参与民生福祉、性别平等、优质教育等国际标准化活动，助力联合国可持续发展目标实现。支持发展中国家提升利用标准化实现可持续发展的能力。\n（二十三）强化贸易便利化标准支撑。持续开展重点领域标准比对分析，积极采用国际标准，大力推进中外标准互认，提高我国标准与国际标准的一致性程度。推出中国标准多语种版本，加快大宗贸易商品、对外承包工程等中国标准外文版编译。研究制定服务贸易标准，完善数字金融、国际贸易单一窗口等标准。促进内外贸质量标准、检验检疫、认证认可等相衔接，推进同线同标同质。创新标准化工作机制，支撑构建面向全球的高标准自由贸易区网络。\n（二十四）推动国内国际标准化协同发展。统筹推进标准化与科技、产业、金融对外交流合作，促进政策、规则、标准联通。建立政府引导、企业主体、产学研联动的国际标准化工作机制。实施标准国际化跃升工程，推进中国标准与国际标准体系兼容。推动标准制度型开放，保障外商投资企业依法参与标准制定。支持企业、社会团体、科研机构等积极参与各类国际性专业标准组织。支持国际性专业标准组织来华落驻。","level":1},{"name":"七、推动标准化改革创新","text":"（二十五）优化标准供给结构。充分释放市场主体标准化活力，优化政府颁布标准与市场自主制定标准二元结构，大幅提升市场自主制定标准的比重。大力发展团体标准，实施团体标准培优计划，推进团体标准应用示范，充分发挥技术优势企业作用，引导社会团体制定原创性、高质量标准。加快建设协调统一的强制性国家标准，筑牢保障人身健康和生命财产安全、生态环境安全的底线。同步推进推荐性国家标准、行业标准和地方标准改革，强化推荐性标准的协调配套，防止地方保护和行业垄断。建立健全政府颁布标准采信市场自主制定标准的机制。\n（二十六）深化标准化运行机制创新。建立标准创新型企业制度和标准融资增信制度，鼓励企业构建技术、专利、标准联动创新体系，支持领军企业联合科研机构、中小企业等建立标准合作机制，实施企业标准领跑者制度。建立国家统筹的区域标准化工作机制，将区域发展标准需求纳入国家标准体系建设，实现区域内标准发展规划、技术规则相互协同，服务国家重大区域战略实施。持续优化标准制定流程和平台、工具，健全企业、消费者等相关方参与标准制定修订的机制，加快标准升级迭代，提高标准质量水平。\n（二十七）促进标准与国家质量基础设施融合发展。以标准为牵引，统筹布局国家质量基础设施资源，推进国家质量基础设施统一建设、统一管理，健全国家质量基础设施一体化发展体制机制。强化标准在计量量子化、检验检测智能化、认证市场化、认可全球化中的作用，通过人工智能、大数据、区块链等新一代信息技术的综合应用，完善质量治理，促进质量提升。强化国家质量基础设施全链条技术方案提供，运用标准化手段推动国家质量基础设施集成服务与产业价值链深度融合。\n（二十八）强化标准实施应用。建立法规引用标准制度、政策实施配套标准制度，在法规和政策文件制定时积极应用标准。完善认证认可、检验检测、政府采购、招投标等活动中应用先进标准机制，推进以标准为依据开展宏观调控、产业推进、行业管理、市场准入和质量监管。健全基于标准或标准条款订立、履行合同的机制。建立标准版权制度、呈缴制度和市场自主制定标准交易制度，加大标准版权保护力度。按照国家有关规定，开展标准化试点示范工作，完善对标达标工作机制，推动企业提升执行标准能力，瞄准国际先进标准提高水平。\n（二十九）加强标准制定和实施的监督。健全覆盖政府颁布标准制定实施全过程的追溯、监督和纠错机制，实现标准研制、实施和信息反馈闭环管理。开展标准质量和标准实施第三方评估，加强标准复审和维护更新。健全团体标准化良好行为评价机制。强化行业自律和社会监督，发挥市场对团体标准的优胜劣汰作用。有效实施企业标准自我声明公开和监督制度，将企业产品和服务符合标准情况纳入社会信用体系建设。建立标准实施举报、投诉机制，鼓励社会公众对标准实施情况进行监督。","level":1},{"name":"八、夯实标准化发展基础","text":"（三十）提升标准化技术支撑水平。加强标准化理论和应用研究，构建以国家级综合标准化研究机构为龙头，行业、区域和地方标准化研究机构为骨干的标准化科技体系。发挥优势企业在标准化科技体系中的作用。完善专业标准化技术组织体系，健全跨领域工作机制，提升开放性和透明度。建设若干国家级质量标准实验室、国家标准验证点和国家产品质量检验检测中心。有效整合标准技术、检测认证、知识产权、标准样品等资源，推进国家技术标准创新基地建设。建设国家数字标准馆和全国统一协调、分工负责的标准化公共服务平台。发展机器可读标准、开源标准，推动标准化工作向数字化、网络化、智能化转型。\n（三十一）大力发展标准化服务业。完善促进标准、计量、认证认可、检验检测等标准化相关高技术服务业发展的政策措施，培育壮大标准化服务业市场主体，鼓励有条件地区探索建立标准化服务业产业集聚区，健全标准化服务评价机制和标准化服务业统计分析报告制度。鼓励标准化服务机构面向中小微企业实际需求，整合上下游资源，提供标准化整体解决方案。大力发展新型标准化服务工具和模式，提升服务专业化水平。\n（三十二）加强标准化人才队伍建设。将标准化纳入普通高等教育、职业教育和继续教育，开展专业与标准化教育融合试点。构建多层次从业人员培养培训体系，开展标准化专业人才培养培训和国家质量基础设施综合教育。建立健全标准化领域人才的职业能力评价和激励机制。造就一支熟练掌握国际规则、精通专业技术的职业化人才队伍。提升科研人员标准化能力，充分发挥标准化专家在国家科技决策咨询中的作用，建设国家标准化高端智库。加强基层标准化管理人员队伍建设，支持西部地区标准化专业人才队伍建设。\n（三十三）营造标准化良好社会环境。充分利用世界标准日等主题活动，宣传标准化作用，普及标准化理念、知识和方法，提升全社会标准化意识，推动标准化成为政府管理、社会治理、法人治理的重要工具。充分发挥标准化社会团体的桥梁和纽带作用，全方位、多渠道开展标准化宣传，讲好标准化故事。大力培育发展标准化文化。","level":1},{"name":"九、组织实施","text":"（三十四）加强组织领导。坚持党对标准化工作的全面领导。进一步完善国务院标准化协调推进部际联席会议制度，健全统一、权威、高效的管理体制和工作机制，强化部门协同、上下联动。各省（自治区、直辖市）要建立健全标准化工作协调推进领导机制，将标准化工作纳入政府绩效评价和政绩考核。各地区各有关部门要将本纲要主要任务与国民经济和社会发展规划有效衔接、同步推进，确保各项任务落到实处。\n（三十五）完善配套政策。各地区各有关部门要强化金融、信用、人才等政策支持，促进科技、产业、贸易等政策协同。按照有关规定开展表彰奖励。发挥财政资金引导作用，积极引导社会资本投入标准化工作。完善标准化统计调查制度，开展标准化发展评价，将相关指标纳入国民经济和社会发展统计。建立本纲要实施评估机制，把相关结果作为改进标准化工作的重要依据。重大事项及时向党中央、国务院请示报告。","level":1}]},{"id":"r0573","sections":[{"name":"中共中央关于加强和改进新形势下党校工作的意见","text":"点击此处观看视频","level":1},{"name":"","text":"中共中央关于加强和改进新形势下党校工作的意见\n（2015年12月9日）\n党校事业是党的事业的重要组成部分。重视发挥党校作用是党的优良传统和政治优势，是提高党的执政能力、执政水平的重要保证。为适应党和国家面临的新形势新任务，更好地促进党校事业发展，现就加强和改进新形势下党校工作提出如下意见。","level":0},{"name":"一、加强和改进党校工作的重要意义","text":"（一）加强和改进党校工作是协调推进“四个全面”战略布局的迫切需要。长期以来，各级党校在干部队伍建设中发挥了重要作用，为推进我国革命、建设和改革事业提供了有力支撑。现在，我们党正带领人民进行具有许多新的历史特点的伟大斗争，致力于协调推进“四个全面”战略布局，实现“两个一百年”奋斗目标和中华民族伟大复兴的中国梦。办好中国的事情，关键在党，在于锻造一支能够担当重任的高素质领导干部队伍。提高党的执政能力，实现党的执政使命，迫切需要按照建设学习型、服务型、创新型马克思主义执政党的要求，进一步发挥党校培训党员领导干部的主渠道作用，推动党员领导干部强化战略思维、历史思维、辩证思维、系统思维、创新思维、底线思维，全面提升能力素养，解决新形势下能力欠缺、“本领恐慌”问题，更好推进国家治理体系和治理能力现代化。\n（二）加强和改进党校工作是落实全面从严治党的内在要求。全面从严治党，必须加强党的思想政治建设，提高党员干部思想理论素养和党性修养。现在，一些干部不合格，主要是思想政治素质不合格；一些干部出问题，根子是世界观、人生观、价值观这个“总开关”出问题。党校承担着强化理论武装、加强理想信念教育的重要职责，肩负着加强党性党风教育、传承党的优良传统作风的重要使命。加强和改进党校工作，充分发挥“三个阵地、一个熔炉”的重要作用，有利于推动党员干部落实“三严三实”要求，从思想、政治、作风等方面严起来、强起来，做到对党忠诚、个人干净、敢于担当，把全面从严治党的任务落到实处。\n（三）加强和改进党校工作是促进党校事业健康发展的紧迫课题。伴随着党和国家事业发展，党校事业取得历史性进步，各方面工作取得明显成效。同时，在实际工作中，也存在一些亟待解决的问题：有的定位不准，没有突出党校有别于一般学校和社会培训机构的特色和优势；有的主业主课不突出，存在重一般知识技能培训、轻党的理论教育和党性教育的现象；有的教学针对性实效性不强，不善于运用科学理论说明和解决实际问题；有的在管理上失之于宽、失之于软，导致学风不好、校风不正；有的对党校重视不够，投入不足、保障不力，等等。这些问题严重制约党校事业发展和党校作用发挥，必须认真解决。","level":1},{"name":"二、坚持党校姓党根本原则","text":"（四）坚定政治方向。坚持正确政治方向是党校办学第一位的要求，是党校姓党最重要的标志。要全面贯彻党的十八大和十八届三中、四中、五中全会精神，以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神，紧紧围绕“四个全面”战略布局，坚持以党的旗帜为旗帜、以党的意志为意志、以党的使命为使命，严守党的政治纪律和政治规矩，在思想上政治上行动上同以习近平同志为总书记的党中央保持高度一致。一切教学、科研和办学活动都要坚持党性原则、遵循党的政治路线，做到党的重大理论成果、重大战略部署及时进课堂，党中央作出的决策迅速贯彻、关注的问题深入研究、交付的任务认真完成。\n（五）坚持实事求是。实事求是是马克思主义活的灵魂，是党校姓党的内在要求。必须坚持解放思想、实事求是、与时俱进，把实事求是的精神贯穿到党校各项工作中，反对主观主义、教条主义、形式主义，防止书斋式的空谈、教条式的研究。既加强对学员进行实事求是思想方法、工作方法、领导方法教育，又倡导教职工坚持理论联系实际，深入开展调查研究，弘扬求真务实风气、民主讨论风气、创新进取风气。鼓励学员之间、教员之间、学员和教员之间开展平等讨论交流，实现学学相长、教学相长。\n（六）坚持质量立校。办学质量是党校安身立命之本。要把质量立校作为党校工作的重要遵循，作为全面提升党校工作水平的一项战略任务。坚持高标准办学，不断总结实践经验，积极探索和运用党校教育规律、干部成长规律，着力提高教学、科研和管理水平。坚持以改革创新为动力，加快形成以质量为办学导向的考核评价机制、激励约束机制、责任落实机制，充分调动教职工和学员的积极性创造性，更好发挥党校特色和优势。\n（七）坚持从严治校。从严治校是全面从严治党在党校工作中的具体体现，是对党校校风、校纪、校规的根本要求。要坚持严以治校、严以治教、严以治学，坚持艰苦奋斗、勤俭办学，严格落实中央八项规定精神，建立健全各项管理制度，加强校风学风建设，严肃查处自由散漫、请客送礼、经营人脉等不正之风。对到党校学习培训的干部，无论什么身份、什么职务，都要作为学员严格要求、严格教育、严格管理，引导学员严格遵守学习培训和廉洁自律各项规定，自觉维护教学秩序。对党校的学历教育，要加强规范，从严管理。","level":1},{"name":"三、把党的理论教育和党性教育作为党校教学首要任务","text":"（八）突出党的理论教育和党性教育的主课地位。马克思主义理论教育和党性教育是党校的主课，是党校教学最重要的任务，是必须重点抓好的教学内容。这两类课，在中央党校、省（自治区、直辖市）委党校、市（地）委党校教学安排中不低于总课时的70%。按照分级分类和规范班次学制的要求，党校的培训类班次，省（自治区、直辖市）委党校一般不少于3个月，市（地）委党校一般不少于2个月，县（市）委党校一般不少于1个月；进修类班次一般不少于1个月；专题研讨班一般不少于5天。在一个任期内，县委书记、乡镇（街道）党委书记、村（社区）党组织书记分别由中央党校、省（自治区、直辖市）委党校、市（地）委党校集中轮训一次。突出主课安排，完善教学布局，所有主体班次都应当在教学安排中充分体现党的理论教育和党性教育的主课地位。\n（九）强化党的理论教育。坚持把马克思主义中国化最新成果作为理论教育中心内容，把马克思主义经典著作导读课作为重要课程，抓好马克思列宁主义、毛泽东思想学习教育，抓好中国特色社会主义理论体系学习教育，引导学员系统掌握马克思主义基本原理和立场观点方法。紧跟党的理论创新步伐，把深入学习习近平总书记系列重要讲话精神作为重中之重，做好讲话精神进教材、进课堂、进学员头脑工作，引导学员坚持读原著、学原文、悟原理，坚持及时学、跟进学、深入学，坚持学而信、学而用、学而行，坚定中国特色社会主义道路自信、理论自信、制度自信，提高分析和解决实际问题的能力，更好地用讲话精神武装头脑、指导实践、推动工作。\n（十）强化党性教育。各级党校每个主体班次都要设置专门的“党性教育单元”，针对不同班次的学制长短，安排充分的教学内容和时间，确保党性教育课不低于总课时的20%。深入开展理想信念教育、党的宗旨教育，深入开展党史国史教育、革命传统教育，深入开展道德品行教育、法治思维教育、反腐倡廉教育，引导学员提升政治修养、道德修养、法纪修养、作风修养，带头践行社会主义核心价值观，传承红色基因，保持共产党人的政治本色。坚持先进典型示范教育与反面典型警示教育相结合、党性分析与组织生活相结合，加强对违法违纪典型案例的剖析，推动党员干部自觉打扫政治灰尘、净化思想灵魂，认真践行“三严三实”要求，时时铭记、事事坚持、处处上心，增强教育的针对性实效性。\n（十一）强化党章党规党纪教育。各级党校要把党章教育作为党性教育的重要组成部分，列为各个班次的必修课，打造党章精品课程，推动学员把党章作为加强党性修养的根本遵循，自觉学习党章、遵守党章、贯彻党章、维护党章，真正使党章内化于心、外化于行。抓好党规党纪学习教育，加强党内政治生活若干准则、中国共产党廉洁自律准则和中国共产党纪律处分条例等党内法规的学习教育，加强党内有关规章制度学习教育，引导学员守住党规党纪底线，自觉用党规党纪规范言行。\n（十二）创新优化党的理论教育和党性教育方式。弘扬马克思主义优良学风，强化问题导向、实践导向，注重回答学员关心的热点难点问题。倡导和运用研讨式教学、案例式教学、体验式教学、情景模拟式教学和现场教学等多种教学方式，深入开展领导工作经验交流和党性分析等教学活动，重视运用网络信息技术，提高教学的吸引力感染力。加强教学基地建设，规范基地管理。制定全国党校理论教育教学大纲和党性教育教学大纲，加强基础课程、公共课程统编教材建设。实行严格的教案审核、集体备课、课前试讲等制度，对课堂教学进行科学评估并建立激励机制。根据不同班次特点建立学习考核制度，激发学员学习动力。\n（十三）加强优势学科和重点学科建设。根据党校定位确定重点学科，加强以中国特色社会主义理论体系为主的马克思主义理论学科建设，加强党性教育学科建设，积极扶持教学急需且相对薄弱学科，逐步形成突出党校特色、满足干部培训需要的学科体系。积极参加马克思主义理论研究和建设工程，深入实施马克思主义理论骨干人才计划，把培养高素质马克思主义理论人才工作做实做好做出更大成效，确保党的理论教育后继有人。重视学位点建设，加强学科带头人培养工作。学位研究生教育要坚持国家标准、办出党校特色。党校学科建设和学科发展，纳入国家哲学社会科学创新体系建设。","level":1},{"name":"四、提升党校科研水平和影响力","text":"（十四）发挥科研工作的支撑作用。党校科研要紧紧围绕教学展开，以更多有价值的研究成果服务于党校教育培训。加强对马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观研究，加强对习近平总书记系列重要讲话精神研究，加强对“四个全面”战略布局研究，加强对基础理论和重大现实问题研究，建立健全科研考核激励机制，确保既出成果又出人才。及时跟进中央重大决策部署，做到重大节点有声音、重大问题亮观点、重大时段搭平台，为党员干部学习贯彻中央精神提供正确引领和学理支撑。加强对社会思潮的辨析和引导，发挥党校报刊、网站等思想理论阵地的作用，及时澄清模糊认识，抵制错误思想，弘扬主旋律，传播正能量。加强同国内理论界学术界联系与交流，不断提高党校科研的影响力。加大对外交流力度，注重用中国理论阐述中国实践，进一步提高对外交流工作水平。\n（十五）积极推进新型智库建设。中央党校和省（自治区、直辖市）委党校要聚焦党和国家中心工作、党委和政府重大决策部署、社会热点难点问题进行深入研究，及时向中央和地方各级党委反映重要思想理论动态、提出有价值的对策建议。建立和完善符合党校智库运行特点的经费管理使用机制，加强智库成果在决策中的转化应用。创新党校学员参与决策咨询机制。建立全国党校系统智库建设协作机制，确立决策咨询模式和智库成员管理模式，提高决策咨询服务水平。加强党校系统与行政学院系统、高等学校系统、科研院所系统的智库交流与合作，构建协同创新的新模式新机制。","level":1},{"name":"五、加强党校师资队伍和干部队伍建设","text":"（十六）严格政治要求。加强和改进党校思想政治工作，教育引导教师夯实马克思主义理论功底，忠诚于党、忠诚于党校事业，坚持党的立场，坚定党的信仰，践行党的宗旨。严明政治纪律和组织纪律，坚持学术研究无禁区、讲坛论坛有纪律，促进教师正确宣传党的理论和路线方针政策，在大是大非问题面前旗帜鲜明、同党中央保持一致。加强师德师风建设，推动教师明大德、守公德、严私德，恪守职业道德，弘扬优良作风，坚持为人师表，自觉维护党的形象和党校声誉。对师德师风不良或不适宜从事党校教学的，调整工作岗位或调离党校。\n（十七）优化教师队伍结构。落实人才强校战略，把更多优秀人才吸引到党校事业中来。拓宽教师来源渠道，坚持严格的政治标准和业务标准，注重从高等学校优秀毕业生中招录青年教研人员，从高等学校和其他部门引进符合党校教学要求的优秀人才。加强党校与其他党政机关和单位干部的交流力度，畅通人才双向交流渠道。选聘政治素质过硬、理论水平较高、善于课堂讲授的党政军领导干部、企事业单位领导人员，选聘先进典型人物、知名专家学者，担任党校兼职教师。\n（十八）切实提高师资水平。建立健全科学有效的人才激励机制，实施党校系统“名师工程”，以学科学术带头人为主体，着力培养政治强、业务精、作风好的知名教师。通过加强经典著作学习、加强教学科研实践、发挥优秀教师传帮带作用等多种途径，加强拔尖人才、学术领军人才培养，加快中青年教师培养。加大党校教师到党政机关或基层挂职锻炼力度，实行蹲点调研制度，组织党校教研人员到基层一线深入了解实际，加深对国情党情的认识，增强分析和解决问题的能力。提高专职教研岗位在全校岗位总量中的比例。\n（十九）创新师资管理。推进党校组织人事制度改革，进一步形成民主、公开、竞争、择优的选人用人机制。探索建立符合干部教育培训特点的师资准入和退出机制、师资考核评价体系、职称评定和岗位聘任办法，推行教师竞争竞聘上岗，探索建立岗位等级、工作业绩与薪酬福利挂钩机制。切实保障党校教师工资待遇，增强党校教师岗位的吸引力。\n（二十）抓好组织员或班主任队伍建设。党校的组织员或班主任处于教学管理一线，在联系、管理和服务学员中负有重要责任。根据党校层级、编制数量、办学规模等，配好配强相应级别和数量的组织员或班主任。引导组织员或班主任提高自身素质，强化责任意识，讲认真、敢较真，督促学员严格遵守学习纪律、课堂纪律、考试纪律、请假纪律，对违反纪律和规定的学员，该提醒的提醒、该批评的批评、该通报的通报，落实好从严管理学员的责任。","level":1},{"name":"六、充分发挥党校系统整体优势","text":"（二十一）加强上级党校对下级党校的指导。坚持统筹协调、上下联动，强化全国党校系统的整体功能。中央党校要制定对地方党校和中央党校分校业务指导的年度工作计划；制定《〈中国共产党党校工作条例〉执行情况评估办法》和《党校办学质量评估指标体系》并抓好督促落实；制定全国党校系统干部培训班次及其培训目标建议清单、各种培训班课程设置建议清单，提高党校系统培训的规范性、科学性和整体质量。中央党校和省（自治区、直辖市）委党校、副省级城市党委党校，设立党校教研与管理骨干研修班，为下级党校培训师资和干部。在中央党校建立全国党校教师进修学院，有计划培训党校教师。加强中央党校分校建设，不断提高办学质量和水平。加强各级党校之间交流，科学统筹党校系统资源，强化教学、科研、管理服务等方面合作，提升资源利用效率和教学效果。深入开展精品课示范教学，建立全国党校系统名师名课库，推动名师名课资源共享。\n（二十二）因地制宜推进县（市）委党校办学体制改革。坚持从实际出发，有效整合县域干部教育培训资源。有条件的县（市）可独立设置党校，并探索实行县委党校与讲师团合并。提倡和鼓励将市辖区委党校和不具备办学条件的县委党校设为市（地）委党校分校，由市（地）委党校统筹安排有关培训任务和师资力量，集中力量办好市（地）委党校。党政部门、国有企业、高等学校、部队等所属党校是培训党员干部和开展党建工作的重要阵地，都要履行好职能，充分发挥作用。","level":1},{"name":"七、加强和改善党委对党校工作的领导","text":"（二十三）坚持党委办党校。各级党委要把办好管好建好党校作为履行党建工作责任制的重要内容，把党校工作纳入党委整体工作部署和党的建设总体安排，每年至少专题研究一次党校工作。各级党委主要负责同志要经常过问党校工作，每年至少一次到党校调研指导或与学员座谈。兼任党校校长的党委负责同志要认真履职尽责，做到时间到位、精力到位、工作到位。各级党委要点名选调重要岗位干部和优秀干部到党校培训，防止和纠正一些领导骨干和业务骨干多年未参加培训、部分干部多次重复培训的现象，真正使党校成为既培养人才又发现人才的重要渠道。支持和促进党校人员外派挂职交流，为党校教师挂职锻炼、进行社会调查提供必要帮助。\n（二十四）选优配强党校领导班子。地方党委党校校长一般由同级党委书记或副书记兼任。选拔政治立场坚定、理论功底扎实、有实践经验、年富力强、开拓创新的优秀干部担任主持日常工作的副校长。地方党委党校主持日常工作的副校长可按同级党委部门正职领导干部选配并作为同级党委成员提名人选，主管教学、科研的副校长人选一般从教师队伍中选拔产生，防止把党校作为单纯照顾安排干部的地方。\n（二十五）建立和实行领导干部到党校讲课制度。领导干部到党校讲课是我们党的一个传统、一大优势，必须长期坚持并形成制度。坚持中央领导同志带头到中央党校讲课的做法。省、市、县党委领导班子成员每人每年至少到同级党校讲一次课。县级以上党委和政府工作部门主要负责人，根据需要不定期到同级党校讲课。每年领导干部讲课总课时，占各级党校主体班次总课时的比例不低于20%。领导干部到党校讲课，要以问题为导向，紧密结合干部思想实际和工作实际，采取形势报告、专题讲座、讲党课等形式，为学员阐明形势、解析政策、交流经验、答疑释惑，增强讲授的思想性和指导性。各级党委要把领导干部到党校讲课作为加强领导班子思想政治建设的重要内容，纳入经常性工作，作出制度性安排。\n（二十六）重视地方党校基础设施建设和办学经费保障。学员教室、学员宿舍、学员食堂、学员图书馆等设施是党校正常办学必需的基础设施，相关经费由同级财政性资金等途径解决。健全党校经费保障机制，党校办学经费纳入同级财政预算统筹考虑。中央财政加大对中西部地区、民族地区、革命老区和欠发达地区的转移支付力度，相关地区可统筹中央补助和自有财力加大对党校的经费投入。\n延伸阅读\n中央党校负责人就《关于加强和改进新形势下党校工作的意见》答问","level":1}]},{"id":"r0574","sections":[{"name":"关于认真学习宣传贯彻党的十八大精神的通知","text":"为深入学习宣传贯彻党的十八大精神，把全党全国各族人民的思想统一到党的十八大精神上来，把力量凝聚到实现党的十八大确定的各项任务上来，现通知如下。","level":1},{"name":"一、充分认识学习宣传贯彻党的十八大精神的重大意义","text":"中国共产党第十八次全国代表大会于11月8日至14日在北京举行。这是在我国进入全面建成小康社会决定性阶段召开的一次十分重要的大会，是一次高举旗帜、继往开来、团结奋进的大会，对凝聚党心军心民心、推动党和国家事业发展具有十分重大的意义。大会高举中国特色社会主义伟大旗帜，以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观为指导，分析了国际国内形势的发展变化，回顾和总结了过去5年的工作和党的十六大以来的奋斗历程及取得的历史性成就，确立了科学发展观的历史地位，提出了夺取中国特色社会主义新胜利必须牢牢把握的基本要求，确定了全面建成小康社会和全面深化改革开放的目标，对新的时代条件下推进中国特色社会主义事业作出了全面部署，对全面提高党的建设科学化水平提出了明确要求。胡锦涛同志代表十七届中央委员会作的《坚定不移沿着中国特色社会主义道路前进，为全面建成小康社会而奋斗》的报告，描绘了全面建成小康社会、加快推进社会主义现代化的宏伟蓝图，为党和国家事业进一步发展指明了方向，是全党全国各族人民智慧的结晶，是我们党团结带领全国各族人民夺取中国特色社会主义新胜利的政治宣言和行动纲领，是马克思主义的纲领性文献。大会通过的《中国共产党章程（修正案）》，体现了党的理论创新和实践发展的成果，体现了党的十八大确立的重大理论观点和重大工作部署，对以改革创新精神全面推进党的建设新的伟大工程、提高党的建设科学化水平提出了明确要求。\n党的十八届一中全会选举产生了以习近平同志为总书记的新一届中央领导集体，一批经验丰富、年富力强、德才兼备、奋发有为的同志进入中央领导机构，实现了党的中央领导集体的又一次新老交替，充分显示了中国特色社会主义事业蓬勃兴旺、薪火相传、后继有人。\n认真学习宣传贯彻党的十八大精神，关系党和国家工作全局，关系中国特色社会主义事业长远发展，对动员全党全国各族人民在以习近平同志为总书记的党中央领导下，高举中国特色社会主义伟大旗帜，满怀信心为全面建成小康社会、夺取中国特色社会主义新胜利而奋斗，具有重大现实意义和深远历史意义。","level":1},{"name":"二、全面准确学习领会党的十八大精神","text":"学习宣传贯彻党的十八大精神，首先要认真研读党的十八大文件，原原本本学习党的十八大报告和党章，学习习近平同志在党的十八届一中全会上的重要讲话精神。要着重把握以下几个方面。\n1．要深刻领会党的十八大的主题。高举中国特色社会主义伟大旗帜，以邓小平理论、“三个代表”重要思想、科学发展观为指导，解放思想，改革开放，凝聚力量，攻坚克难，坚定不移沿着中国特色社会主义道路前进，为全面建成小康社会而奋斗。这是党的十八大的主题，鲜明回答了我们党举什么旗帜、走什么道路、保持什么样的精神状态、朝着什么样的目标继续前进的重大问题。中国特色社会主义是当代中国发展进步的旗帜，也是全党全国各族人民团结奋斗的旗帜。解放思想是推动党和人民事业发展的强大思想武器，改革开放是推动党和人民事业发展的强大动力，凝聚力量、攻坚克难是坚持和发展中国特色社会主义的基本要求，全面建成小康社会是党和国家到2020年的奋斗目标，是全国各族人民的根本利益所在。\n2．要深刻领会过去5年和10年党和国家事业取得新的历史性成就。党的十七大以来的5年，是我们在中国特色社会主义道路上奋勇前进的5年，是我们经受住各种困难和风险考验、夺取全面建设小康社会新胜利的5年。过去5年的工作，是党的十六大以来全面建设小康社会10年实践的重要组成部分。这10年，我们紧紧抓住和用好我国发展的重要战略机遇期，战胜一系列重大挑战，奋力把中国特色社会主义推进到新的发展阶段。这10年，社会生产力、经济实力、科技实力迈上一个大台阶，人民生活水平、居民收入水平、社会保障水平迈上一个大台阶，综合国力、国际竞争力、国际影响力迈上一个大台阶，国家面貌发生新的历史性变化，是我国经济持续发展、民主不断健全、文化日益繁荣、社会保持稳定的时期，是着力保障和改善民生、人民得到实惠更多的时期。同时，必须清醒看到，我们工作中还存在许多不足，前进道路上还有不少困难和问题，面对前所未有的风险挑战，我们必须高度重视，居安思危，进一步认真加以解决。\n3．要深刻领会科学发展观的历史地位和指导意义。科学发展观是马克思主义同当代中国实际和时代特征相结合的产物，是马克思主义关于发展的世界观和方法论的集中体现，对新形势下实现什么样的发展、怎样发展等重大问题作出了新的科学回答，把我们对中国特色社会主义规律的认识提高到新的水平，开辟了当代中国马克思主义发展新境界。科学发展观是中国特色社会主义理论体系最新成果，是中国共产党集体智慧的结晶，是指导党和国家全部工作的强大思想武器。科学发展观同马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想一道，是党必须长期坚持的指导思想。面向未来，深入贯彻落实科学发展观，对坚持和发展中国特色社会主义具有重大现实意义和深远历史意义，必须把科学发展观贯彻到我国现代化建设全过程、体现到党的建设各方面。全党必须更加自觉地把推动经济社会发展作为深入贯彻落实科学发展观的第一要义，必须更加自觉地把以人为本作为深入贯彻落实科学发展观的核心立场，必须更加自觉地把全面协调可持续作为深入贯彻落实科学发展观的基本要求，必须更加自觉地把统筹兼顾作为深入贯彻落实科学发展观的根本方法。解放思想、实事求是、与时俱进、求真务实，是科学发展观最鲜明的精神实质。\n4．要深刻领会中国特色社会主义的丰富内涵，深刻领会夺取中国特色社会主义新胜利的基本要求。中国特色社会主义是当代中国发展进步的根本方向，只有中国特色社会主义才能发展中国。中国特色社会主义道路，中国特色社会主义理论体系，中国特色社会主义制度，是党和人民90多年奋斗、创造、积累的根本成就，必须倍加珍惜、始终坚持、不断发展，坚定道路自信、理论自信、制度自信。中国特色社会主义道路是实现途径，中国特色社会主义理论体系是行动指南，中国特色社会主义制度是根本保障，三者统一于中国特色社会主义伟大实践，这是党领导人民在建设社会主义长期实践中形成的最鲜明特色。建设中国特色社会主义，总依据是社会主义初级阶段，总布局是五位一体，总任务是实现社会主义现代化和中华民族伟大复兴。在新的历史条件下夺取中国特色社会主义新胜利要牢牢把握以下基本要求：必须坚持人民主体地位，必须坚持解放和发展社会生产力，必须坚持推进改革开放，必须坚持维护社会公平正义，必须坚持走共同富裕道路，必须坚持促进社会和谐，必须坚持和平发展，必须坚持党的领导，并使之成为全党全国各族人民的共同信念。党的基本路线是党和国家的生命线，要坚持把以经济建设为中心同四项基本原则、改革开放这两个基本点统一于中国特色社会主义伟大实践，扎扎实实夺取中国特色社会主义新胜利。\n5．要深刻领会全面建成小康社会和全面深化改革开放的目标。党的十八大根据我国经济社会发展实际，提出了全面建成小康社会和全面深化改革开放的目标。要在党的十六大、十七大确立的全面建设小康社会目标的基础上努力实现新的要求，即：经济持续健康发展，人民民主不断扩大，文化软实力显著增强，人民生活水平全面提高，资源节约型、环境友好型社会建设取得重大进展。要加快完善社会主义市场经济体制，加快推进社会主义民主政治制度化、规范化、程序化，加快完善文化管理体制和文化生产经营机制，加快形成科学有效的社会管理体制，加快建立生态文明制度，构建系统完备、科学规范、运行有效的制度体系，使各方面制度更加成熟更加定型。\n6．要深刻领会社会主义经济建设、政治建设、文化建设、社会建设、生态文明建设等方面的重大部署。在经济建设上，必须坚持发展是硬道理的战略思想，以科学发展为主题，以加快转变经济发展方式为主线，坚持走中国特色新型工业化、信息化、城镇化、农业现代化道路，打胜全面深化经济体制改革和加快转变经济发展方式这场硬仗，把我国经济发展活力和竞争力提高到新的水平。在政治建设上，必须坚持走中国特色社会主义政治发展道路，继续积极稳妥推进政治体制改革，坚持党的领导、人民当家作主、依法治国有机统一，发展更加广泛、更加充分、更加健全的人民民主。在文化建设上，必须走中国特色社会主义文化发展道路，加强社会主义核心价值体系建设，积极培育和践行社会主义核心价值观，丰富人民精神文化生活，提高国民素质，增强文化整体实力和竞争力，扎实推进社会主义文化强国建设。在社会建设上，必须加快健全基本公共服务体系，加强和创新社会管理，以保障和改善民生为重点，多谋民生之利，多解民生之忧，解决好人民最关心最直接最现实的利益问题，在学有所教、劳有所得、病有所医、老有所养、住有所居上持续取得新进展。在生态文明建设上，必须树立尊重自然、顺应自然、保护自然的生态文明理念，坚持节约资源和保护环境的基本国策，着力推进绿色发展、循环发展、低碳发展，形成节约资源和保护环境的空间格局、产业结构、生产方式、生活方式，努力建设美丽中国，实现中华民族永续发展。党的十八大还对加快推进国防和军队现代化、丰富“一国两制”实践和推进祖国统一、继续促进人类和平与发展的崇高事业等方面作出重要部署。\n7．要深刻领会全面提高党的建设科学化水平。新形势下，党面临的执政考验、改革开放考验、市场经济考验、外部环境考验是长期的、复杂的、严峻的，精神懈怠危险、能力不足危险、脱离群众危险、消极腐败危险更加尖锐地摆在全党面前。要牢牢把握加强党的执政能力建设、先进性和纯洁性建设这条主线，坚持解放思想、改革创新，坚持党要管党、从严治党，全面加强党的思想建设、组织建设、作风建设、反腐倡廉建设、制度建设，增强自我净化、自我完善、自我革新、自我提高能力，建设学习型、服务型、创新型的马克思主义执政党，确保党始终成为中国特色社会主义事业的坚强领导核心。","level":1},{"name":"三、认真做好党的十八大精神的宣传","text":"要全面准确、深入系统地宣传党的十八大精神，使之更好地为广大干部群众所掌握。\n1．切实抓好学习培训。要通过举办各种形式的培训班、研讨班，组织广大党员干部认真学习党的十八大精神。中央将于年内举办新进中央委员会的委员、候补委员学习贯彻党的十八大精神研讨班。各级党委（党组）理论学习中心组要把学习党的十八大精神作为中心内容，制定系统学习培训计划，列出专题进行研讨，力求学深学透、融会贯通。各地要集中一段时间分期分批把县处级以上领导干部轮训一遍。基层党组织要采取多种形式，组织广大党员干部认真学习党的十八大精神。要注意抓好离退休人员中党员的学习，抓好偏远地区农村党员的学习，抓好失业人员和流动人口中党员的学习。要抓好党的十八大精神进教材、进课堂、进学生头脑的工作，把学习党的十八大精神作为学校思想政治教育和课堂教学的重要内容。\n2．集中开展宣讲活动。从现在起到明年初，在全国范围内集中开展党的十八大精神宣讲活动。中央将组织学习党的十八大精神宣讲团，赴各地开展宣讲。各地要参照这一做法，抽调有演讲能力的理论和实际工作者组成宣讲团，深入城乡基层开展面对面宣讲。要组织专门宣讲团到高校进行宣讲。各级领导干部要带头宣讲，以实际行动带动广大干部群众的学习。\n3．精心组织新闻宣传。各级党报、党刊、电台、电视台要精心策划、集中报道，大力宣传党的十八大精神，宣传广大干部群众在学习贯彻党的十八大精神过程中解决实际问题的新成效新进展。要深入解读党的十八大提出的重大理论观点、重大方针政策、重大工作部署，增强舆论引导能力。要推出一批有分量有深度的报道、综述、社论、评论和理论文章。要结合“走基层、转作风、改文风”活动，组织新闻工作者深入基层一线，推出一批来自群众、生动鲜活的报道。\n4．积极开展网络宣传。要组织网络媒体通过系列报道、在线访谈、论坛跟帖等方式，开展具有网络特点的宣传报道，积极引导网上舆论，有效回应网民关切，形成网上正面宣传强势。注重运用微博客、社交网络和移动多媒体等新技术新手段，调动网民参与积极性，增强网络宣传的实效性和影响力。","level":1},{"name":"四、坚持联系实际、推动工作","text":"学习宣传贯彻党的十八大精神，要紧密联系改革开放和社会主义现代化建设实际，联系本地区本部门工作实际，联系广大干部群众思想实际，与深入调查研究紧密结合，坚持学以致用、用以促学，把党的十八大精神落实到经济社会发展各方面，体现到做好今年各项工作和安排好明年工作之中。\n1．要落实到推动科学发展、加快完善社会主义市场经济体制和加快转变经济发展方式上来。牢牢把握科学发展这个主题和加快转变经济发展方式这条主线，坚持稳中求进的工作总基调，把稳增长放在更加重要的位置，积极应对世界经济波动冲击。推进经济结构战略性调整，加快形成新的经济发展方式，促进经济持续健康发展，推进社会主义民主法制建设，推动社会主义文化大发展大繁荣，推进生态文明建设。要坚持社会主义市场经济的改革方向，提高改革决策的科学性，增强改革措施的协调性，找准深化改革开放的突破口，明确深化改革开放的着力点，不失时机地推进重要领域和关键环节改革，继续解放和发展社会生产力，继续推动我国社会主义制度自我完善和发展，坚决破除一切妨碍科学发展的思想观念和体制机制弊端。深化经济体制改革、政治体制改革、文化体制改革、社会体制改革、生态体制改革，不断在制度建设和创新方面迈出新步伐，不断促进生产关系和生产力、上层建筑和经济基础相适应，促进经济社会各个领域、各个方面、各个环节相协调。\n2．要落实到促进社会和谐、保障和改善民生上来。把保障和改善民生放在更加突出的位置，努力办好人民满意的教育，推动实现更高质量的就业，千方百计增加居民收入，统筹推进城乡社会保障体系建设，提高人民健康水平，加强和创新社会管理。着力解决教育、就业、社会保障、医疗、住房、生态环境、食品药品安全、安全生产、社会治安、执法司法等关系群众切身利益的问题，维护社会公平正义，使发展成果更多更公平惠及全体人民，让人民群众通过辛勤劳动过上更加美好生活。正确处理改革发展稳定关系，着力化解人民内部矛盾和不和谐因素，最大限度增加和谐因素。\n3．要落实到全面推进党的建设新的伟大工程上来。形势的发展、事业的开拓、人民的期待，都要求我们以改革创新精神全面推进党的建设新的伟大工程，全面提高党的建设科学化水平。要按照加强和改进党的建设的总体要求，以改革创新精神全面推进党的建设新的伟大工程，全面提高党的建设科学化水平，保持党的先进性和纯洁性。要突出抓好党的十八大提出的重点任务，进一步坚定理想信念，进一步保持党同人民群众的血肉联系，进一步积极发展党内民主，进一步夯实党执政的组织基础，进一步搞好党风廉政建设，进一步严明党的纪律，加紧建立健全保证党科学执政、民主执政、依法执政的体制机制，抓紧解决党内存在的突出矛盾和问题。广大党员干部要自觉遵守党章，自觉按照党的组织原则和党内政治生活准则办事。党员干部要自觉做坚定理想信念的表率，自觉做认真学习实践的表率，自觉做坚持民主集中制的表率，自觉做弘扬优良作风的表率。\n4．要落实到解放思想、改革开放、凝聚力量、攻坚克难上来。准确把握我国发展的重要战略机遇期内涵和条件的变化，充分认识如期全面建成小康社会任务十分艰巨，着力解放思想、改革开放、凝聚力量、攻坚克难，勇于实践、勇于变革、勇于创新。增强忧患意识、风险意识、责任意识，坚定必胜信念，积极开拓进取，全面做好改革发展稳定各项工作，着力解决经济社会发展中的突出矛盾和问题，有效防范各种潜在风险，努力促进经济社会发展，努力保持社会和谐稳定。","level":1},{"name":"五、切实加强组织领导","text":"学习宣传贯彻党的十八大精神，是全党全国当前和今后一个时期的首要政治任务。各级党委要把学习宣传贯彻党的十八大精神摆上重要议事日程，切实加强组织领导。\n1．切实负起领导责任。各级党委要按照中央的部署，结合本地区本部门实际，作出专题部署，提出具体要求，着力抓好落实，迅速兴起学习宣传贯彻党的十八大精神的热潮。要着力抓好县处级以上领导干部的学习培训。要加强工作指导，加强督促检查，务求取得实效，切忌形式主义。各级组织、宣传部门和其他有关部门，要在党委统一领导下，密切配合。组织部门要把学习宣传贯彻党的十八大精神与干部教育培训工作、加强领导班子建设和基层党组织建设结合起来。宣传部门要扎实做好党的十八大精神宣传工作，营造学习宣传贯彻党的十八大精神的浓厚氛围。工会、共青团、妇联等人民团体要充分发挥自身优势，开展各具特色的学习教育活动。\n2．牢牢把握正确导向。要坚持团结稳定鼓劲、正面宣传为主的方针，着力用党的十八大精神统一思想、凝聚力量。要及时了解干部群众的思想状况，密切关注社会舆情，有针对性地做好工作。加强对敏感问题和热点问题的正面引导，解疑释惑，最大限度凝聚社会共识。加强对宣传思想文化阵地的管理，绝不给错误思想言论提供传播渠道。\n3．不断创新方式方法。要坚持贴近实际、贴近生活、贴近群众，创新形式载体，探索方法手段，努力增强学习宣传贯彻党的十八大精神的吸引力感染力和针对性实效性。善于运用群众乐于参与、便于参与的方式，采取富有时代特色、体现实践要求的方法，在拓展广度深度上下功夫。善于运用新科技手段创造性地开展工作，努力扩大工作的覆盖面和影响力。\n各地区各部门要及时将学习宣传贯彻党的十八大精神的情况报告中央。","level":1}]},{"id":"r0575","sections":[{"name":"中央军委办公厅印发《关于加强新时代军队财务工作的意见》","text":"经中央军委批准，中央军委办公厅日前印发《关于加强新时代军队财务工作的意见》。","level":1},{"name":"","text":"《意见》指出，要坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻党的二十大精神，深入贯彻习近平强军思想，深入贯彻新时代军事战略方针，紧紧围绕全面加强军事治理，以实现高质量发展为主题，着力建设打仗型财务、绩效型财务、服务型财务、信息型财务、廉洁型财务，努力打造与现代化后勤相融合、与建成世界一流军队相匹配的新时代军队财务。\n《意见》聚焦坚持党委管财正确方向、提升向战为战质量效益、推进财务管理改革创新、纯正清正廉洁行业风气、打造精武强能人才队伍，对加强新时代军队财务工作的组织领导、运行方式、监督管理等作出全面规范。\n《意见》强调，要着眼保障向战为战，促进财力向战斗力有效转化；着眼强化战略管理，促进战略管理链路顺畅运行；着眼服务部队官兵，促进基层建设全面进步、全面过硬；着眼严格财会监督，促进不敢腐、不能腐、不想腐一体推进，更好履行新时代军队财务的职能任务。","level":0}]},{"id":"r0576","sections":[{"name":"中共中央办公厅印发《关于中央企业在完善公司治理中加强党的领导的意见》","text":"近日，中共中央办公厅印发了《关于中央企业在完善公司治理中加强党的领导的意见》（以下简称《意见》），并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《意见》对中央企业进一步把加强党的领导和完善公司治理统一起来、加快完善中国特色现代企业制度作出部署、提出要求，是推进中国特色现代企业制度建设的标志性制度成果，对于中央企业坚持和加强党的全面领导、加快建设世界一流企业，具有重要意义。\n《意见》坚持以习近平新时代中国特色社会主义思想为指导，全面落实习近平总书记关于坚持党对国有企业的领导必须一以贯之、建立现代企业制度必须一以贯之的重要指示要求，立足于在完善公司治理中加强党的领导，明确了中央企业党委（党组）在决策、执行、监督等各环节的权责和工作方式。\n《意见》提出，中央企业党委（党组）是党的组织体系重要组成部分，在公司治理结构中具有法定地位，在企业发挥把方向、管大局、促落实的领导作用。同时，《意见》在明晰中央企业党委（党组）讨论和决定重大事项的职责范围，规范党委（党组）前置研究讨论重大经营管理事项的要求和程序，明确党委（党组）在董事会授权决策和总经理办公会决策中发挥作用的方式，强化党委（党组）在执行、监督环节的责任担当，以及加强党委（党组）自身建设等方面，作出了制度性安排。\n《意见》强调，各地区各有关部门和各中央企业党委（党组）要加强分类指导，鼓励探索创新，在国有企业完善公司治理中切实加强党的领导。","level":0}]},{"id":"r0577","sections":[{"name":"关于引导农村土地经营权有序流转发展农业适度规模经营的意见","text":"点击此处观看视频","level":1},{"name":"","text":"近日，中共中央办公厅、国务院办公厅印发了《关于引导农村土地经营权有序流转发展农业适度规模经营的意见》，并发出通知，要求各地区各部门结合实际认真贯彻执行。\n《关于引导农村土地经营权有序流转发展农业适度规模经营的意见》全文如下。\n伴随我国工业化、信息化、城镇化和农业现代化进程，农村劳动力大量转移，农业物质技术装备水平不断提高，农户承包土地的经营权流转明显加快，发展适度规模经营已成为必然趋势。实践证明，土地流转和适度规模经营是发展现代农业的必由之路，有利于优化土地资源配置和提高劳动生产率，有利于保障粮食安全和主要农产品供给，有利于促进农业技术推广应用和农业增效、农民增收，应从我国人多地少、农村情况千差万别的实际出发，积极稳妥地推进。为引导农村土地(指承包耕地)经营权有序流转、发展农业适度规模经营，现提出如下意见。","level":0},{"name":"一、总体要求","text":"(一)指导思想。全面理解、准确把握中央关于全面深化农村改革的精神，按照加快构建以农户家庭经营为基础、合作与联合为纽带、社会化服务为支撑的立体式复合型现代农业经营体系和走生产技术先进、经营规模适度、市场竞争力强、生态环境可持续的中国特色新型农业现代化道路的要求，以保障国家粮食安全、促进农业增效和农民增收为目标，坚持农村土地集体所有，实现所有权、承包权、经营权三权分置，引导土地经营权有序流转，坚持家庭经营的基础性地位，积极培育新型经营主体，发展多种形式的适度规模经营，巩固和完善农村基本经营制度。改革的方向要明，步子要稳，既要加大政策扶持力度，加强典型示范引导，鼓励创新农业经营体制机制，又要因地制宜、循序渐进，不能搞大跃进，不能搞强迫命令，不能搞行政瞎指挥，使农业适度规模经营发展与城镇化进程和农村劳动力转移规模相适应，与农业科技进步和生产手段改进程度相适应，与农业社会化服务水平提高相适应，让农民成为土地流转和规模经营的积极参与者和真正受益者，避免走弯路。\n(二)基本原则\n——坚持农村土地集体所有权，稳定农户承包权，放活土地经营权，以家庭承包经营为基础，推进家庭经营、集体经营、合作经营、企业经营等多种经营方式共同发展。\n——坚持以改革为动力，充分发挥农民首创精神，鼓励创新，支持基层先行先试，靠改革破解发展难题。\n——坚持依法、自愿、有偿，以农民为主体，政府扶持引导，市场配置资源，土地经营权流转不得违背承包农户意愿、不得损害农民权益、不得改变土地用途、不得破坏农业综合生产能力和农业生态环境。\n——坚持经营规模适度，既要注重提升土地经营规模，又要防止土地过度集中，兼顾效率与公平，不断提高劳动生产率、土地产出率和资源利用率，确保农地农用，重点支持发展粮食规模化生产。","level":1},{"name":"二、稳定完善农村土地承包关系","text":"(三)健全土地承包经营权登记制度。建立健全承包合同取得权利、登记记载权利、证书证明权利的土地承包经营权登记制度，是稳定农村土地承包关系、促进土地经营权流转、发展适度规模经营的重要基础性工作。完善承包合同，健全登记簿，颁发权属证书，强化土地承包经营权物权保护，为开展土地流转、调处土地纠纷、完善补贴政策、进行征地补偿和抵押担保提供重要依据。建立健全土地承包经营权信息应用平台，方便群众查询，利于服务管理。土地承包经营权确权登记原则上确权到户到地，在尊重农民意愿的前提下，也可以确权确股不确地。切实维护妇女的土地承包权益。\n(四)推进土地承包经营权确权登记颁证工作。按照中央统一部署、地方全面负责的要求，在稳步扩大试点的基础上，用5年左右时间基本完成土地承包经营权确权登记颁证工作，妥善解决农户承包地块面积不准、四至不清等问题。在工作中，各地要保持承包关系稳定，以现有承包台账、合同、证书为依据确认承包地归属；坚持依法规范操作，严格执行政策，按照规定内容和程序开展工作；充分调动农民群众积极性，依靠村民民主协商，自主解决矛盾纠纷；从实际出发，以农村集体土地所有权确权为基础，以第二次全国土地调查成果为依据，采用符合标准规范、农民群众认可的技术方法；坚持分级负责，强化县乡两级的责任，建立健全党委和政府统一领导、部门密切协作、群众广泛参与的工作机制；科学制定工作方案，明确时间表和路线图，确保工作质量。有关部门要加强调查研究，有针对性地提出操作性政策建议和具体工作指导意见。土地承包经营权确权登记颁证工作经费纳入地方财政预算，中央财政给予补助。","level":1},{"name":"三、规范引导农村土地经营权有序流转","text":"(五)鼓励创新土地流转形式。鼓励承包农户依法采取转包、出租、互换、转让及入股等方式流转承包地。鼓励有条件的地方制定扶持政策，引导农户长期流转承包地并促进其转移就业。鼓励农民在自愿前提下采取互换并地方式解决承包地细碎化问题。在同等条件下，本集体经济组织成员享有土地流转优先权。以转让方式流转承包地的，原则上应在本集体经济组织成员之间进行，且需经发包方同意。以其他形式流转的，应当依法报发包方备案。抓紧研究探索集体所有权、农户承包权、土地经营权在土地流转中的相互权利关系和具体实现形式。按照全国统一安排，稳步推进土地经营权抵押、担保试点，研究制定统一规范的实施办法，探索建立抵押资产处置机制。\n(六)严格规范土地流转行为。土地承包经营权属于农民家庭，土地是否流转、价格如何确定、形式如何选择，应由承包农户自主决定，流转收益应归承包农户所有。流转期限应由流转双方在法律规定的范围内协商确定。没有农户的书面委托，农村基层组织无权以任何方式决定流转农户的承包地，更不能以少数服从多数的名义，将整村整组农户承包地集中对外招商经营。防止少数基层干部私相授受，谋取私利。严禁通过定任务、下指标或将流转面积、流转比例纳入绩效考核等方式推动土地流转。\n(七)加强土地流转管理和服务。有关部门要研究制定流转市场运行规范，加快发展多种形式的土地经营权流转市场。依托农村经营管理机构健全土地流转服务平台，完善县乡村三级服务和管理网络，建立土地流转监测制度，为流转双方提供信息发布、政策咨询等服务。土地流转服务主体可以开展信息沟通、委托流转等服务，但禁止层层转包从中牟利。土地流转给非本村(组)集体成员或村(组)集体受农户委托统一组织流转并利用集体资金改良土壤、提高地力的，可向本集体经济组织以外的流入方收取基础设施使用费和土地流转管理服务费，用于农田基本建设或其他公益性支出。引导承包农户与流入方签订书面流转合同，并使用统一的省级合同示范文本。依法保护流入方的土地经营权益，流转合同到期后流入方可在同等条件下优先续约。加强农村土地承包经营纠纷调解仲裁体系建设，健全纠纷调处机制，妥善化解土地承包经营流转纠纷。\n(八)合理确定土地经营规模。各地要依据自然经济条件、农村劳动力转移情况、农业机械化水平等因素，研究确定本地区土地规模经营的适宜标准。防止脱离实际、违背农民意愿，片面追求超大规模经营的倾向。现阶段，对土地经营规模相当于当地户均承包地面积10至15倍、务农收入相当于当地二三产业务工收入的，应当给予重点扶持。创新规模经营方式，在引导土地资源适度集聚的同时，通过农民的合作与联合、开展社会化服务等多种形式，提升农业规模化经营水平。\n(九)扶持粮食规模化生产。加大粮食生产支持力度，原有粮食直接补贴、良种补贴、农资综合补贴归属由承包农户与流入方协商确定，新增部分应向粮食生产规模经营主体倾斜。在有条件的地方开展按照实际粮食播种面积或产量对生产者补贴试点。对从事粮食规模化生产的农民合作社、家庭农场等经营主体，符合申报农机购置补贴条件的，要优先安排。探索选择运行规范的粮食生产规模经营主体开展目标价格保险试点。抓紧开展粮食生产规模经营主体营销贷款试点，允许用粮食作物、生产及配套辅助设施进行抵押融资。粮食品种保险要逐步实现粮食生产规模经营主体愿保尽保，并适当提高对产粮大县稻谷、小麦、玉米三大粮食品种保险的保费补贴比例。各地区各有关部门要研究制定相应配套办法，更好地为粮食生产规模经营主体提供支持服务。\n(十)加强土地流转用途管制。坚持最严格的耕地保护制度，切实保护基本农田。严禁借土地流转之名违规搞非农建设。严禁在流转农地上建设或变相建设旅游度假村、高尔夫球场、别墅、私人会所等。严禁占用基本农田挖塘栽树及其他毁坏种植条件的行为。严禁破坏、污染、圈占闲置耕地和损毁农田基础设施。坚决查处通过“以租代征”违法违规进行非农建设的行为，坚决禁止擅自将耕地“非农化”。利用规划和标准引导设施农业发展，强化设施农用地的用途监管。采取措施保证流转土地用于农业生产，可以通过停发粮食直接补贴、良种补贴、农资综合补贴等办法遏制撂荒耕地的行为。在粮食主产区、粮食生产功能区、高产创建项目实施区，不符合产业规划的经营行为不再享受相关农业生产扶持政策。合理引导粮田流转价格，降低粮食生产成本，稳定粮食种植面积。","level":1},{"name":"四、加快培育新型农业经营主体","text":"(十一)发挥家庭经营的基础作用。在今后相当长时期内，普通农户仍占大多数，要继续重视和扶持其发展农业生产。重点培育以家庭成员为主要劳动力、以农业为主要收入来源，从事专业化、集约化农业生产的家庭农场，使之成为引领适度规模经营、发展现代农业的有生力量。分级建立示范家庭农场名录，健全管理服务制度，加强示范引导。鼓励各地整合涉农资金建设连片高标准农田，并优先流向家庭农场、专业大户等规模经营农户。\n(十二)探索新的集体经营方式。集体经济组织要积极为承包农户开展多种形式的生产服务，通过统一服务降低生产成本、提高生产效率。有条件的地方根据农民意愿，可以统一连片整理耕地，将土地折股量化、确权到户，经营所得收益按股分配，也可以引导农民以承包地入股组建土地股份合作组织，通过自营或委托经营等方式发展农业规模经营。各地要结合实际不断探索和丰富集体经营的实现形式。\n(十三)加快发展农户间的合作经营。鼓励承包农户通过共同使用农业机械、开展联合营销等方式发展联户经营。鼓励发展多种形式的农民合作组织，深入推进示范社创建活动，促进农民合作社规范发展。在管理民主、运行规范、带动力强的农民合作社和供销合作社基础上，培育发展农村合作金融。引导发展农民专业合作社联合社，支持农民合作社开展农社对接。允许农民以承包经营权入股发展农业产业化经营。探索建立农户入股土地生产性能评价制度，按照耕地数量质量、参照当地土地经营权流转价格计价折股。\n(十四)鼓励发展适合企业化经营的现代种养业。鼓励农业产业化龙头企业等涉农企业重点从事农产品加工流通和农业社会化服务，带动农户和农民合作社发展规模经营。引导工商资本发展良种种苗繁育、高标准设施农业、规模化养殖等适合企业化经营的现代种养业，开发农村“四荒”资源发展多种经营。支持农业企业与农户、农民合作社建立紧密的利益联结机制，实现合理分工、互利共赢。支持经济发达地区通过农业示范园区引导各类经营主体共同出资、相互持股，发展多种形式的农业混合所有制经济。\n(十五)加大对新型农业经营主体的扶持力度。鼓励地方扩大对家庭农场、专业大户、农民合作社、龙头企业、农业社会化服务组织的扶持资金规模。支持符合条件的新型农业经营主体优先承担涉农项目，新增农业补贴向新型农业经营主体倾斜。加快建立财政项目资金直接投向符合条件的合作社、财政补助形成的资产转交合作社持有和管护的管理制度。各省(自治区、直辖市)根据实际情况，在年度建设用地指标中可单列一定比例专门用于新型农业经营主体建设配套辅助设施，并按规定减免相关税费。综合运用货币和财税政策工具，引导金融机构建立健全针对新型农业经营主体的信贷、保险支持机制，创新金融产品和服务，加大信贷支持力度，分散规模经营风险。鼓励符合条件的农业产业化龙头企业通过发行短期融资券、中期票据、中小企业集合票据等多种方式，拓宽融资渠道。鼓励融资担保机构为新型农业经营主体提供融资担保服务，鼓励有条件的地方通过设立融资担保专项资金、担保风险补偿基金等加大扶持力度。落实和完善相关税收优惠政策，支持农民合作社发展农产品加工流通。\n(十六)加强对工商企业租赁农户承包地的监管和风险防范。各地对工商企业长时间、大面积租赁农户承包地要有明确的上限控制，建立健全资格审查、项目审核、风险保障金制度，对租地条件、经营范围和违规处罚等作出规定。工商企业租赁农户承包地要按面积实行分级备案，严格准入门槛，加强事中事后监管，防止浪费农地资源、损害农民土地权益，防范承包农户因流入方违约或经营不善遭受损失。定期对租赁土地企业的农业经营能力、土地用途和风险防范能力等开展监督检查，查验土地利用、合同履行等情况，及时查处纠正违法违规行为，对符合要求的可给予政策扶持。有关部门要抓紧制定管理办法，并加强对各地落实情况的监督检查。","level":1},{"name":"五、建立健全农业社会化服务体系","text":"(十七)培育多元社会化服务组织。巩固乡镇涉农公共服务机构基础条件建设成果。鼓励农技推广、动植物防疫、农产品质量安全监管等公共服务机构围绕发展农业适度规模经营拓展服务范围。大力培育各类经营性服务组织，积极发展良种种苗繁育、统防统治、测土配方施肥、粪污集中处理等农业生产性服务业，大力发展农产品电子商务等现代流通服务业，支持建设粮食烘干、农机场库棚和仓储物流等配套基础设施。农产品初加工和农业灌溉用电执行农业生产用电价格。鼓励以县为单位开展农业社会化服务示范创建活动。开展政府购买农业公益性服务试点，鼓励向经营性服务组织购买易监管、可量化的公益性服务。研究制定政府购买农业公益性服务的指导性目录，建立健全购买服务的标准合同、规范程序和监督机制。积极推广既不改变农户承包关系，又保证地有人种的托管服务模式，鼓励种粮大户、农机大户和农机合作社开展全程托管或主要生产环节托管，实现统一耕作，规模化生产。\n(十八)开展新型职业农民教育培训。制定专门规划和政策，壮大新型职业农民队伍。整合教育培训资源，改善农业职业学校和其他学校涉农专业办学条件，加快发展农业职业教育，大力发展现代农业远程教育。实施新型职业农民培育工程，围绕主导产业开展农业技能和经营能力培养培训，扩大农村实用人才带头人示范培养培训规模，加大对专业大户、家庭农场经营者、农民合作社带头人、农业企业经营管理人员、农业社会化服务人员和返乡农民工的培养培训力度，把青年农民纳入国家实用人才培养计划。努力构建新型职业农民和农村实用人才培养、认定、扶持体系，建立公益性农民培养培训制度，探索建立培育新型职业农民制度。\n(十九)发挥供销合作社的优势和作用。扎实推进供销合作社综合改革试点，按照改造自我、服务农民的要求，把供销合作社打造成服务农民生产生活的生力军和综合平台。利用供销合作社农资经营渠道，深化行业合作，推进技物结合，为新型农业经营主体提供服务。推动供销合作社农产品流通企业、农副产品批发市场、网络终端与新型农业经营主体对接，开展农产品生产、加工、流通服务。鼓励基层供销合作社针对农业生产重要环节，与农民签订服务协议，开展合作式、订单式服务，提高服务规模化水平。\n土地问题涉及亿万农民切身利益，事关全局。各级党委和政府要充分认识引导农村土地经营权有序流转、发展农业适度规模经营的重要性、复杂性和长期性，切实加强组织领导，严格按照中央政策和国家法律法规办事，及时查处违纪违法行为。坚持从实际出发，加强调查研究，搞好分类指导，充分利用农村改革试验区、现代农业示范区等开展试点试验，认真总结基层和农民群众创造的好经验好做法。加大政策宣传力度，牢固树立政策观念，准确把握政策要求，营造良好的改革发展环境。加强农村经营管理体系建设，明确相应机构承担农村经管工作职责，确保事有人干、责有人负。各有关部门要按照职责分工，抓紧修订完善相关法律法规，建立工作指导和检查监督制度，健全齐抓共管的工作机制，引导农村土地经营权有序流转，促进农业适度规模经营健康发展。\n延伸阅读：\n短评：进一步激发农村改革发展活力","level":1}]},{"id":"r0578","sections":[{"name":"关于创新政府配置资源方式的指导意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于创新政府配置资源方式的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于创新政府配置资源方式的指导意见》全文如下。\n改革开放以来，随着市场化改革的不断深化，市场在资源配置中的作用日益增强，政府配置资源的范围和方式也在不断调整。在社会主义市场经济条件下，政府配置的资源主要是政府代表国家和全民所拥有的自然资源、经济资源和社会事业资源等公共资源。为解决当前政府配置资源中存在的市场价格扭曲、配置效率较低、公共服务供给不足等突出问题，需要从广度和深度上推进市场化改革，大幅度减少政府对资源的直接配置，创新配置方式，更多引入市场机制和市场化手段，提高资源配置的效率和效益。按照党中央、国务院决策部署，现就创新政府配置资源方式提出以下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。全面贯彻党的十八大和十八届三中、四中、五中、六中全会精神，以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，主动适应把握引领经济发展新常态，牢固树立和贯彻落实新发展理念，提高政府治理能力和水平，着力推进供给侧结构性改革，使市场在资源配置中起决定性作用和更好发挥政府作用。对于适宜由市场化配置的公共资源，要充分发挥市场机制作用，切实遵循价值规律，建立市场竞争优胜劣汰机制，实现资源配置效益最大化和效率最优化。对于不完全适宜由市场化配置的公共资源，要引入竞争规则，充分体现政府配置资源的引导作用，实现政府与市场作用有效结合。对于需要通过行政方式配置的公共资源，要遵循规律，注重运用市场机制，实现更有效率的公平性和均等化。通过创新公共资源配置方式，促进经济社会持续健康发展。\n（二）基本原则\n——问题导向、分类施策。针对政府配置资源方式单一、行政性配置手段较多的突出问题，坚持从体制上改革突破，构建科学、合理、规范的公共资源配置长效机制。根据各类公共资源的不同情况和特点，分类分领域创新资源配置方式。\n——提高效率、促进公平。正确处理效率与公平的关系，更加注重公共资源配置的公平性，充分发挥市场机制作用，拓展竞争性配置的公共资源范围，以资源配置方式创新推动实现公平配置基础上的效率提升，努力实现全体人民公平分享公共资源收益。\n——平台整合、信息共享。整合分散设立的各类公共资源交易平台，立足公共服务职能定位，完善管理规则，优化市场环境，着力构建规则统一、公开透明、服务高效、监督规范的公共资源交易平台体系。依托大数据、云计算等信息技术，加快推进交易全过程电子化，实现交易全流程公开透明和信息共享。\n——依法依规、创新监管。坚持运用法治思维和法治方式，着力健全规划、产权、监管等各方面制度，推动各类公共资源依法依规、公开透明配置。严格区分政府资源配置职能和监管职能，创新资源配置监管方式，实现对公共资源配置的动态和全程监管。\n（三）改革目标。创新政府配置资源方式，自然资源方面要以建立产权制度为基础，实现资源有偿获得和使用；经济资源方面（主要指金融类和非金融类经营性国有资产）要突出国有资本的内在要求，明确委托代理关系的制度安排，建立健全国有资本形态转换机制；社会事业资源方面（主要指非经营性国有资产）要引入市场化手段和方法，实现更有效率的公平性和均等化，促进公共资源配置更高效、更公平、更可持续。\n到2020年，公共资源产权制度进一步健全，形成合理的资源收益分配机制，资源所有者权益得到进一步保障；行政性配置范围进一步厘清，结构进一步优化，市场配置资源的决定性作用明显增强；以目录管理、统一平台、规范交易、全程监管为主要内容的新型资源配置体系基本建立，资源配置过程公开公平公正，公共资源配置的效益和效率显著提高。","level":1},{"name":"二、创新自然资源配置方式","text":"法律明确规定由全民所有的土地、矿藏、水流、森林、山岭、草原、荒地、海域、无居民海岛、滩涂等自然资源，建立明晰的产权制度、健全管理体制，对无线电频率等非传统自然资源，推进市场化配置进程，完善资源有偿使用制度。\n（四）建立健全自然资源产权制度。坚持资源公有、物权法定，明确全部国土空间各类自然资源资产的产权主体。对水流、森林、山岭、草原、荒地、滩涂等所有自然生态空间统一进行确权登记。区分全民所有和集体所有，明确国家对全民所有的自然资源的所有者权益。除具有重要生态功能及农牧民从事农牧业生产必需的资源外，可推动自然资源资产所有权和使用权相分离，明确自然资源所有权、使用权等产权归属关系和权责，适度扩大使用权的出让、转让、出租、担保、入股等权能。\n（五）健全国家自然资源资产管理体制。区分自然资源资产所有者和监管者职能，健全国家自然资源资产管理体制，依照法律规定，由国务院代表国家行使所有权，探索建立分级代理行使所有权的体制。划清全民所有、不同层级政府行使所有权的边界，按照不同资源种类和在生态、经济、国防等方面的重要程度，研究实行中央和地方政府分级代理行使所有权职责体制。完善自然资源监管体制，强化各自然资源管理部门监管职能，使自然资源资产所有者和监管者相互独立、相互配合、相互监督。\n（六）完善自然资源有偿使用制度。建立健全全民所有自然资源的有偿使用制度，更多引入竞争机制进行配置，完善土地、水、矿产资源和海域有偿使用制度，探索推进国有森林、国有草原、无居民海岛有偿使用。在充分考虑资源所有者权益和生态环境损害成本基础上，完善自然资源及其产品价格形成机制。发挥资源产出指标、使用强度指标及安全标准等的标杆作用，促进资源公平出让、高效利用。\n（七）发挥空间规划对自然资源配置的引导约束作用。以主体功能区规划为基础，整合各部门分头编制的各类空间性规划，编制统一的空间规划，合理布局城镇空间、农业空间和生态空间，划定城镇开发边界、永久基本农田和生态保护红线，科学配置和严格管控各类自然资源。健全国土空间用途管制制度，将开发强度指标分解到各县级行政区，控制建设用地总量。将用途管制扩大到所有自然生态空间，确定林地、草原、河流、湖泊、湿地、荒漠等的保护边界，严禁任意改变用途。\n（八）推进无线电频率、空域等资源优化配置。对地面公众移动通信使用频率等商用无线电频率、电信网码号等资源，要逐步探索引入招投标、拍卖等竞争性方式进行配置。优化空域资源配置，提高空域资源配置使用效率，增加民航可用空域，深化低空空域管理改革。","level":1},{"name":"三、创新经营性国有资产配置方式","text":"对于金融类和非金融类经营性国有资产，要建立健全以管资本为主的国有资产管理体制，优化国有资本布局，推动国有资本合理流动、有序进退和优化配置，提高国有资本配置效率和效益。\n（九）优化国有资本布局。紧紧围绕服务国家战略，统筹规划国有资本战略布局，建立动态调整机制。落实国家产业政策和重点产业布局调整总体要求，优化国有资本重点投向和领域，推动国有资本向关系国家安全、国民经济命脉和国计民生的重要行业和关键领域、重点基础设施集中，向前瞻性战略性产业集中，向具有核心竞争力的优势企业集中。完善国有资本退出机制，研究国家持股金融机构的合理比例，对系统重要性金融机构保持控制力，对其他机构按照市场化原则优化股权结构，激发社会资本活力。\n（十）完善国有资本授权经营体制。建立以管资本为主的国有资产监管体系，改革国有资本授权经营体制，改组组建国有资本投资、运营公司，开展政府直接授权国有资本投资、运营公司履行出资人职责的试点。国有资本投资、运营公司通过开展投资融资、产业培育、资本整合等，优化国有资本布局结构；通过股权运作、价值管理、有序进退，促进国有资本合理流动，实现保值增值。国有资本投资、运营公司作为国有资本市场化运作的专业平台，依法自主开展国有资本运作，对所出资企业行使股东职责，按照责权对应原则切实承担起国有资产保值增值责任。\n（十一）建立健全国有资本形态转换机制。坚持以管资本为主，以提高国有资本流动性为目标，积极推动经营性国有资产证券化。建立健全优胜劣汰市场化退出机制，加快处置低效无效资产，支持企业依法合规通过证券交易、产权交易等市场，以市场公允价格处置国有资产，实现国有资本形态转换，用于国家长远战略、宏观调控以及保障基本民生的需要，更好服务于国家发展目标。\n（十二）规范经营性国有资产处置和收益分配。企业重大资产转让应依托统一的公共资源交易平台公开进行。重大经营性国有资产出租、出借要引入市场机制，做到公开、公正、透明。建立覆盖全部国有企业、分级管理的国有资本经营预算管理制度，国有资本收益和国有资产处置等非税收入，必须按规定及时足额上缴国库并纳入政府预算，更多用于保障和改善民生，国家另有规定的从其规定。逐步提高国有资本收益上缴公共财政比例，划转部分国有资本充实社保基金。\n（十三）强化国有资本基础管理。守住防止国有资产流失的底线。强化国有产权流转环节监管，创新监管方式和手段，协同推进监管工作，按照收放有度要求，实现维护出资人权益和尊重企业自主经营权的有效结合。","level":1},{"name":"四、创新非经营性国有资产配置方式","text":"对用于实施公共管理和提供公共服务目的的非经营性国有资产，坚持公平配置原则，积极引入竞争机制提高配置效率，提高基本公共服务的可及性、公平性。\n（十四）推进政事分开、管办分离。区分政府作为资源配置者和行业监管者的不同职能，创新和改进政府直接配置资源的方式，强化教育、医疗、养老、文化、体育等部门的行业监管职能。放开相关行业市场准入，放松价格管制，促进公平竞争。区分基本与非基本公共服务，理顺政府与事业单位在基本公共服务供给中的关系，推进政事分开、事企分开、管办分离。创新与事业单位运行相适应的制度体系，健全事业单位法人治理结构。\n（十五）推进基本公共服务均等化。围绕均等化、标准化、法治化，加快健全国家基本公共服务制度，制定国家基本公共服务清单，动态调整服务项目和标准，促进城乡区域间服务项目和标准有机衔接，推动基本公共服务公平共享。合理确定各级政府的财政事权和支出责任。加强基本公共服务资源均衡配置，推动基层基本公共服务资源优化整合，提高服务效率。\n（十六）创新公共服务供给方式。建立政府主导、社会参与、自主运行、公众监督的多元化公共服务供给体制。各地区各部门可以根据需要和财力状况，通过特许经营、政府购买服务等方式，扩大和改善公共产品和服务供给。推进公益类事业单位改革，强化公益属性，创新体制机制，提高供给质量和效益。制定发布政府购买服务指导性目录，引入竞争机制，提高财政资金使用效率。采取人员培训、项目指导、公益创投等多种途径和方式，提升事业单位、企业和社会组织承接政府购买服务能力。\n（十七）推进非经营性国有资产整合与共享。在清产核资、界定产权的基础上，进一步打破部门行政化分割，构建共享平台，实现公共科技、教育、医疗、文化等资源开放共享。建立资产共享共用与资产绩效、资产配置、单位预算挂钩的联动机制，避免资产重复配置、闲置浪费。对行政事业单位超标准配置、低效运转或者长期闲置资产，要建立完善的调剂机制，有效盘活存量资产，实现高效利用。按规定程序报经批准后，允许将部分闲置的非经营性国有资产转为经营性国有资产。\n（十八）推进行政事业单位资产规范管理。依据行政事业单位职能及其工作性质，按完成职能的最低限度和最优标准配置资产。制定行政事业单位资产配置标准体系，针对通用、专用资产实施不同的配置标准。严格非经营性国有资产建设项目审批，强化预算约束和财政拨款控制，符合预算管理规定的非经营性国有资产配置涉及的管理费用支出具体安排应编入预决算，经同级人民代表大会或其常务委员会审议批准后应向社会公开。建立健全全方位、多层次的资产管理和监督体系，建立工作机制，加强资产使用、处置和收益管理，确保规范高效使用、公开透明处置，确保资产处置收入和出租、出借收入应收尽收，防止国有资产流失。","level":1},{"name":"五、创新资源配置组织方式","text":"着眼于各类资源的整合管理和高效利用，依托国家公共资源交易服务平台，加强清查核算和综合管理，创新服务方式，构建新型组织和服务体系。\n（十九）建立公共资源目录清单。结合编制权责发生制政府综合财务报告制度中的资产负债表、自然资源资产负债表，全面开展公共资源清查，系统梳理现有政府配置公共资源的数量和范围、各项资源产权归属、市场化配置情况以及监管主体、监管制度等。对公共资源进行适当分类并按类逐项登记，明确资源底数。建立完善的资源申报、登记、调整、公开和报告制度，资源清单根据资源变动进行动态调整、及时更新。\n（二十）加快推进公共资源交易全过程电子化。按照国务院办公厅印发的《整合建立统一的公共资源交易平台工作方案》精神，推动公共资源交易全过程电子化，充分发挥信息技术在提高交易效率和透明度，节约资源和交易成本，解决公共资源配置领域突出问题方面的优势，实现公共资源交易平台从依托有形场所向以电子化平台为主转变，为市场主体和社会公众服务，为行政监督部门依法履职提供便利。积极稳妥推进公共资源电子交易系统市场化竞争，引导市场主体参与平台服务供给。做好国家公共资源交易平台和不动产统一登记平台的对接和数据共享。\n（二十一）完善市场交易机制。在摸清底数的基础上，对政府配置资源中应该或可以通过市场化方式配置的资源，按照应进必进、能进必进的原则，严格将其纳入统一的公共资源交易平台进行规范交易，采取招拍挂或其他方式进行配置。针对不同公共资源特点，明确交易基本规则，准确评估资源价值，严格规范交易程序，确保交易过程公开公平公正。培育资源价值评估的专业人才队伍，完善相关技术标准体系。\n（二十二）建立健全信息服务机制。推动各级公共资源交易平台加大信息公开力度，依法公开交易公告、资格审查结果、成交、履约及变更等信息。加快建立市场信息共享数据库和验证互认机制，逐步实现市场主体登记注册信息全国范围内共享互认。建立公共资源交易市场主体信用信息库，实现市场主体信用信息共享。加强公共资源交易数据统计分析、综合利用和风险监测预警，为市场主体、社会公众和行政监管部门提供信息服务。","level":1},{"name":"六、创新资源配置监管方式","text":"全面履行政府监管职能，转变监管理念，坚持运用法治思维和法治方式，创新监管机制和监管方式，构建依法监管与信用激励约束、政府监管与社会监督相结合的新型监管格局。\n（二十三）加强和完善信用监管。加快推进社会信用体系建设，建立健全市场主体信用评价制度，建立信用信息互通共享机制，完善全国信用信息共享平台，健全守信联合激励和失信联合惩戒机制。充分发挥信用管理在事中事后监管中的作用，将市场主体参与公共资源交易活动的信用信息作为实施监管的重要依据，建立失信黑名单制度，强化信用约束。\n（二十四）加强和完善协同监管。在理顺各部门监管职责、落实执法责任的基础上，以加强市场监管为重点，建立健全行业主管部门监管、国有资产监管与行政审批、司法、监察、审计监督等衔接机制，建立跨部门、跨区域执法协作机制，推动实现各部门和地区之间监管资源共享、联动预防监控、联动检查处理，形成各司其职、各负其责、横向协调、纵向联通的协同监管新格局。\n（二十五）加强和完善动态在线监管。运用互联网和大数据技术，依托政务服务网上平台，对公共资源配置项目规划、评估、审核、交易、收支等过程实施电子化行政监督，全面记录各市场主体、服务机构、监管机构信息，形成来源可溯、去向可查、监督留痕、责任可究的完整信息链条，实现实时动态监管和在线即时监督监测。\n（二十六）加强和完善全过程监管。严格执行招标投标法、政府采购法等法律法规，规范招标人、投标人、评价人、中介机构等相关方行为，依法依规公开相关信息，确保公共资源配置全过程公开透明。强化惩戒措施，依法纠正和查处违法违规行为，并及时向社会公布。","level":1},{"name":"七、强化组织领导和实施保障","text":"（二十七）加强组织领导。各地区各部门要充分认识创新政府配置资源方式改革的重要性，把创新政府配置资源方式列入重要工作日程，完善工作机制，明确和落实责任分工。强化舆论引导，大力宣传和解读创新政府配置资源方式的重要意义和政策措施。加强调查研究、政策指导和工作协调，及时掌握和研究解决资源配置改革中的困难和问题。强化督查考核，建立科学的绩效考核制度，对公共资源配置情况定期开展绩效评估和综合性考核。\n（二十八）鼓励开展改革探索。创新政府配置资源方式涉及面广，情况复杂，各地区各部门要结合工作实际，积极开展改革探索，建立健全有效推进改革的问责、容错和纠偏机制。在维护全国统一大市场的前提下，支持各地区在新型城镇化、国资国企改革、区域性金融市场和金融机构、房地产税、养老和医疗保障等方面探索创新。各省（自治区、直辖市）可根据经济社会发展需要，将部分经营性国有资产由实物形态转变为资本形态，将部分统筹使用后仍闲置的非经营性国有资产转为经营性国有资产，其经营收益或出让变现所得上缴财政，统筹用于保障和改善民生。认真总结各地区在实践中的经验做法，及时加以推广。\n（二十九）建立健全法律法规。健全政府配置资源相关法律法规和规章，加大法律法规立改废释工作力度，着力完善资源产权制度，调整相关法律法规中有关市场准入、市场主体资格、行政许可等方面不符合市场化改革方向的规定，明确资源所有者权益，健全资源产权占有、使用、收益、处分制度。根据创新政府配置资源方式需要，加快修订完善涉及自然资源、经济资源、社会事业资源配置等方面法律法规。加快制定有关产权保护、社会信用、公平竞争等方面法律法规。\n（三十）完善相关配套制度。根据法律法规的制定和修改情况，加快完善市场准入和退出、交易规则、公平竞争、特许经营等方面的配套制度，协同推进行政审批、财税、金融、投资、价格、国有企事业单位等各方面改革。加快制定完善自然资源、公共服务领域专项规划，科学建立公共服务和公共设施配置定额指标、资源开发强度指标、使用效率指标、效益评价指标，合理确定并公布指标标准，指导和引导地方各级政府和市场主体合理配置资源。建立健全促进资源节约集约利用、资源管理责任以及政府考核、激励、监督等方面制度。建立健全资源配置信息公开和公众参与制度，资源配置目标、原则、程序、配置结果等信息，除涉及国家安全内容外，要一律向社会公开，充分发挥社会公众和第三方专业机构在创新政府配置资源方式工作中的积极作用。","level":1}]},{"id":"r0579","sections":[{"name":"中共中央印发《关于深化人才发展体制机制改革的意见》","text":"近日，中共中央印发了《关于深化人才发展体制机制改革的意见》（以下简称《意见》），并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"通知指出，《意见》着眼于破除束缚人才发展的思想观念和体制机制障碍，解放和增强人才活力，形成具有国际竞争力的人才制度优势，聚天下英才而用之，明确深化改革的指导思想、基本原则和主要目标，从管理体制、工作机制和组织领导等方面提出改革措施，是当前和今后一个时期全国人才工作的重要指导性文件。《意见》的颁布实施，对于全面贯彻党的十八大和十八届三中、四中、五中全会精神，深入贯彻习近平总书记系列重要讲话精神，加快建设人才强国，最大限度激发人才创新创造创业活力，把各方面优秀人才集聚到党和国家事业中来，为实现“两个一百年”奋斗目标提供有力人才支撑，具有十分重要的战略意义和现实意义。\n通知强调，各级党委和政府要切实增强责任感、使命感，加强对《意见》实施的组织领导。有关方面要抓紧制定任务分工方案，明确各项改革的进度安排。各地区各部门要结合实际，采取有力措施，把《意见》提出的各项任务落到实处。要加强政策解读和舆论引导，调动各方面积极性，形成全社会关心支持人才发展体制机制改革的良好氛围。要配齐配强工作力量，加强指导监督，研究解决人才发展体制机制改革中遇到的新情况新问题。\n通知要求，落实《意见》过程中的重要情况和建议，要及时报告党中央。\n《关于深化人才发展体制机制改革的意见》全文如下。\n人才是经济社会发展的第一资源。人才发展体制机制改革是全面深化改革的重要组成部分，是党的建设制度改革的重要内容。协调推进“四个全面”战略布局，贯彻落实创新、协调、绿色、开放、共享的发展理念，实现“两个一百年”奋斗目标，必须深化人才发展体制机制改革，加快建设人才强国，最大限度激发人才创新创造创业活力，把各方面优秀人才集聚到党和国家事业中来。现就深化人才发展体制机制改革提出如下意见。","level":0},{"name":"一、指导思想、基本原则和主要目标","text":"（一）指导思想\n高举中国特色社会主义伟大旗帜，全面贯彻党的十八大和十八届三中、四中、五中全会精神，以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神，坚持聚天下英才而用之，牢固树立科学人才观，深入实施人才优先发展战略，遵循社会主义市场经济规律和人才成长规律，破除束缚人才发展的思想观念和体制机制障碍，解放和增强人才活力，构建科学规范、开放包容、运行高效的人才发展治理体系，形成具有国际竞争力的人才制度优势。\n（二）基本原则\n——坚持党管人才。充分发挥党的思想政治优势、组织优势和密切联系群众优势，进一步加强和改进党对人才工作的领导，健全党管人才领导体制和工作格局，创新党管人才方式方法，为深化人才发展体制机制改革提供坚强的政治和组织保证。\n——服务发展大局。围绕经济社会发展需求，聚焦国家重大战略，科学谋划改革思路和政策措施，促进人才规模、质量和结构与经济社会发展相适应、相协调，实现人才发展与经济建设、政治建设、文化建设、社会建设、生态文明建设深度融合。\n——突出市场导向。充分发挥市场在人才资源配置中的决定性作用和更好发挥政府作用，加快转变政府人才管理职能，保障和落实用人主体自主权，提高人才横向和纵向流动性，健全人才评价、流动、激励机制，最大限度激发和释放人才创新创造创业活力，使人才各尽其能、各展其长、各得其所，让人才价值得到充分尊重和实现。\n——体现分类施策。根据不同领域、行业特点，坚持从实际出发，具体问题具体分析，增强改革针对性、精准性。纠正人才管理中存在的行政化、“官本位”倾向，防止简单套用党政领导干部管理办法管理科研教学机构学术领导人员和专业人才。\n——扩大人才开放。树立全球视野和战略眼光，充分开发利用国内国际人才资源，主动参与国际人才竞争，完善更加开放、更加灵活的人才培养、吸引和使用机制，不唯地域引进人才，不求所有开发人才，不拘一格用好人才，确保人才引得进、留得住、流得动、用得好。\n（三）主要目标\n通过深化改革，到2020年，在人才发展体制机制的重要领域和关键环节上取得突破性进展，人才管理体制更加科学高效，人才评价、流动、激励机制更加完善，全社会识才爱才敬才用才氛围更加浓厚，形成与社会主义市场经济体制相适应、人人皆可成才、人人尽展其才的政策法律体系和社会环境。","level":1},{"name":"二、推进人才管理体制改革","text":"（四）转变政府人才管理职能。根据政社分开、政事分开和管办分离要求，强化政府人才宏观管理、政策法规制定、公共服务、监督保障等职能。推动人才管理部门简政放权，消除对用人主体的过度干预，建立政府人才管理服务权力清单和责任清单，清理和规范人才招聘、评价、流动等环节中的行政审批和收费事项。\n（五）保障和落实用人主体自主权。充分发挥用人主体在人才培养、吸引和使用中的主导作用，全面落实国有企业、高校、科研院所等企事业单位和社会组织的用人自主权。创新事业单位编制管理方式，对符合条件的公益二类事业单位逐步实行备案制管理。改进事业单位岗位管理模式，建立动态调整机制。探索高层次人才协议工资制等分配办法。\n（六）健全市场化、社会化的人才管理服务体系。构建统一、开放的人才市场体系，完善人才供求、价格和竞争机制。深化人才公共服务机构改革。大力发展专业性、行业性人才市场，鼓励发展高端人才猎头等专业化服务机构，放宽人才服务业准入限制。积极培育各类专业社会组织和人才中介服务机构，有序承接政府转移的人才培养、评价、流动、激励等职能。充分运用云计算和大数据等技术，为用人主体和人才提供高效便捷服务。扩大社会组织人才公共服务覆盖面。完善人才诚信体系，建立失信惩戒机制。\n（七）加强人才管理法制建设。研究制定促进人才开发及人力资源市场、人才评价、人才安全等方面的法律法规。完善外国人才来华工作、签证、居留和永久居留管理的法律法规。制定人才工作条例。清理不合时宜的人才管理法律法规和政策性文件。","level":1},{"name":"三、改进人才培养支持机制","text":"（八）创新人才教育培养模式。突出经济社会发展需求导向，建立高校学科专业、类型、层次和区域布局动态调整机制。统筹产业发展和人才培养开发规划，加强产业人才需求预测，加快培育重点行业、重要领域、战略性新兴产业人才。注重人才创新意识和创新能力培养，探索建立以创新创业为导向的人才培养机制，完善产学研用结合的协同育人模式。\n（九）改进战略科学家和创新型科技人才培养支持方式。更大力度实施国家高层次人才特殊支持计划（国家“万人计划”），完善支持政策，创新支持方式。构建科学、技术、工程专家协同创新机制。建立统一的人才工程项目信息管理平台，推动人才工程项目与各类科研、基地计划相衔接。按照精简、合并、取消、下放要求，深入推进项目评审、人才评价、机构评估改革。\n建立基础研究人才培养长期稳定支持机制。加大对新兴产业以及重点领域、企业急需紧缺人才支持力度。支持新型研发机构建设，鼓励人才自主选择科研方向、组建科研团队，开展原创性基础研究和面向需求的应用研发。\n（十）完善符合人才创新规律的科研经费管理办法。改革完善科研项目招投标制度，健全竞争性经费和稳定支持经费相协调的投入机制，提高科研项目立项、评审、验收科学化水平。进一步改革科研经费管理制度，探索实行充分体现人才创新价值和特点的经费使用管理办法。下放科研项目部分经费预算调整审批权，推行有利于人才创新的经费审计方式。完善企业研发费用加计扣除政策。探索实行哲学社会科学研究成果后期资助和事后奖励制。\n（十一）优化企业家成长环境。遵循企业家成长规律，拓宽培养渠道。建立有利于企业家参与创新决策、凝聚创新人才、整合创新资源的新机制。依法保护企业家财产权和创新收益，进一步营造尊重、关怀、宽容、支持企业家的社会文化环境。合理提高国有企业经营管理人才市场化选聘比例，畅通各类企业人才流动渠道。研究制定在国有企业建立职业经理人制度的指导意见。完善国有企业经营管理人才中长期激励措施。\n（十二）建立产教融合、校企合作的技术技能人才培养模式。大力培养支撑中国制造、中国创造的技术技能人才队伍，加快构建现代职业教育体系，深化技术技能人才培养体制改革，加强统筹协调，形成工作合力。创新技术技能人才教育培训模式，促进企业和职业院校成为技术技能人才培养的“双主体”，开展校企联合培养试点。研究制定技术技能人才激励办法，探索建立企业首席技师制度，试行年薪制和股权制、期权制。健全以职业农民为主体的农村实用人才培养机制。弘扬劳动光荣、技能宝贵、创造伟大的时代风尚，不断提高技术技能人才经济待遇和社会地位。\n（十三）促进青年优秀人才脱颖而出。破除论资排辈、求全责备等陈旧观念，抓紧培养造就青年英才。建立健全对青年人才普惠性支持措施。加大教育、科技和其他各类人才工程项目对青年人才培养支持力度，在国家重大人才工程项目中设立青年专项。改革博士后制度，发挥高校、科研院所、企业在博士后研究人员招收培养中的主体作用，有条件的博士后科研工作站可独立招收博士后研究人员。拓宽国际视野，吸引国外优秀青年人才来华从事博士后研究。","level":1},{"name":"四、创新人才评价机制","text":"（十四）突出品德、能力和业绩评价。制定分类推进人才评价机制改革的指导意见。坚持德才兼备，注重凭能力、实绩和贡献评价人才，克服唯学历、唯职称、唯论文等倾向。不将论文等作为评价应用型人才的限制性条件。建立符合中小学教师、全科医生等岗位特点的人才评价机制。\n（十五）改进人才评价考核方式。发挥政府、市场、专业组织、用人单位等多元评价主体作用，加快建立科学化、社会化、市场化的人才评价制度。基础研究人才以同行学术评价为主，应用研究和技术开发人才突出市场评价，哲学社会科学人才强调社会评价。注重引入国际同行评价。应用型人才评价应根据职业特点突出能力和业绩导向。加强评审专家数据库建设，建立评价责任和信誉制度。适当延长基础研究人才评价考核周期。\n（十六）改革职称制度和职业资格制度。深化职称制度改革，提高评审科学化水平。研究制定深化职称制度改革的意见。突出用人主体在职称评审中的主导作用，合理界定和下放职称评审权限，推动高校、科研院所和国有企业自主评审。对职称外语和计算机应用能力考试不作统一要求。探索高层次人才、急需紧缺人才职称直聘办法。畅通非公有制经济组织和社会组织人才申报参加职称评审渠道。清理减少准入类职业资格并严格管理，推进水平类职业资格评价市场化、社会化。放宽急需紧缺人才职业资格准入。","level":1},{"name":"五、健全人才顺畅流动机制","text":"（十七）破除人才流动障碍。打破户籍、地域、身份、学历、人事关系等制约，促进人才资源合理流动、有效配置。建立高层次人才、急需紧缺人才优先落户制度。加快人事档案管理服务信息化建设，完善社会保险关系转移接续办法，为人才跨地区、跨行业、跨体制流动提供便利条件。\n（十八）畅通党政机关、企事业单位、社会各方面人才流动渠道。研究制定吸引非公有制经济组织和社会组织优秀人才进入党政机关、国有企事业单位的政策措施，注重人选思想品德、职业素养、从业经验和专业技能综合考核。\n（十九）促进人才向艰苦边远地区和基层一线流动。研究制定鼓励和引导人才向艰苦边远地区和基层一线流动的意见，提高艰苦边远地区和基层一线人才保障水平，使他们在政治上受重视、社会上受尊重、经济上得实惠。重大人才工程项目适当向艰苦边远地区倾斜。边远贫困和民族地区县以下单位招录人才，可适当放宽条件、降低门槛。鼓励西部地区、东北地区、边远地区、民族地区、革命老区设立人才开发基金。完善东、中部地区对口支持西部地区人才开发机制。","level":1},{"name":"六、强化人才创新创业激励机制","text":"（二十）加强创新成果知识产权保护。完善知识产权保护制度，加快出台职务发明条例。研究制定商业模式、文化创意等创新成果保护办法。建立创新人才维权援助机制。建立人才引进使用中的知识产权鉴定机制，防控知识产权风险。完善知识产权质押融资等金融服务机制，为人才创新创业提供支持。\n（二十一）加大对创新人才激励力度。赋予高校、科研院所科技成果使用、处置和收益管理自主权，除事关国防、国家安全、国家利益、重大社会公共利益外，行政主管部门不再审批或备案。允许科技成果通过协议定价、在技术市场挂牌交易、拍卖等方式转让转化。完善科研人员收入分配政策，依法赋予创新领军人才更大人财物支配权、技术路线决定权，实行以增加知识价值为导向的激励机制。完善市场评价要素贡献并按贡献分配的机制。研究制定国有企事业单位人才股权期权激励政策，对不适宜实行股权期权激励的采取其他激励措施。探索高校、科研院所担任领导职务科技人才获得现金与股权激励管理办法。完善人才奖励制度。\n（二十二）鼓励和支持人才创新创业。研究制定高校、科研院所等事业单位科研人员离岗创业的政策措施。高校、科研院所科研人员经所在单位同意，可在科技型企业兼职并按规定获得报酬。允许高校、科研院所设立一定比例的流动岗位，吸引具有创新实践经验的企业家、科技人才兼职。鼓励和引导优秀人才向企业集聚。重视吸收民营企业育才引才用才经验做法。总结推广各类创新创业孵化模式，打造一批低成本、便利化、开放式的众创空间。","level":1},{"name":"七、构建具有国际竞争力的引才用才机制","text":"（二十三）完善海外人才引进方式。实行更积极、更开放、更有效的人才引进政策，更大力度实施海外高层次人才引进计划（国家“千人计划”），敞开大门，不拘一格，柔性汇聚全球人才资源。对国家急需紧缺的特殊人才，开辟专门渠道，实行特殊政策，实现精准引进。支持地方、部门和用人单位设立引才项目，加强动态管理。鼓励社会力量参与人才引进。扩大来华留学规模，优化外国留学生结构，提高政府奖学金资助标准，出台学位研究生毕业后在华工作的相关政策。\n（二十四）健全工作和服务平台。对引进人才充分信任、放手使用，支持他们深度参与国家计划项目、开展科研攻关。研究制定外籍科学家领衔国家科技项目办法。完善引才配套政策，解决引进人才任职、社会保障、户籍、子女教育等问题。对外国人才来华签证、居留，放宽条件、简化程序、落实相关待遇。整合人才引进管理服务资源，优化机构与职能配置。\n（二十五）扩大人才对外交流。鼓励支持人才更广泛地参加国际学术交流与合作，完善相关管理办法。支持有条件的高校、科研院所、企业在海外建立办学机构、研发机构，吸引使用当地优秀人才。完善国际组织人才培养推送机制。创立国际人才合作组织，促进人才国际交流与合作。研究制定维护国家人才安全的政策措施。","level":1},{"name":"八、建立人才优先发展保障机制","text":"（二十六）促进人才发展与经济社会发展深度融合。坚持人才引领创新发展，将人才发展列为经济社会发展综合评价指标。综合运用区域、产业政策和财政、税收杠杆，加大人才资源开发力度。坚持人才发展与实施重大国家战略、调整产业布局同步谋划、同步推进。研究制定“一带一路”建设、京津冀协同发展、长江经济带建设、“中国制造2025”、自贸区建设以及国家重大项目和重大科技工程等人才支持措施。创新人才工作服务发展政策，鼓励和支持地方开展人才管理改革试验探索。围绕实施国家“十三五”规划，编制地区、行业系统以及重点领域人才发展规划。鼓励各类优秀人才投身国防事业，促进军民深度融合发展，建立军地人才、技术、成果转化对接机制。\n（二十七）建立多元投入机制。优化财政支出结构，完善人才发展投入机制，加大人才开发投入力度。实施重大建设工程和项目时，统筹安排人才开发培养经费。调整和规范人才工程项目财政性支出，提高资金使用效益。发挥人才发展专项资金、中小企业发展基金、产业投资基金等政府投入的引导和撬动作用，建立政府、企业、社会多元投入机制。创新人才与资本、技术对接合作模式。研究制定鼓励企业、社会组织加大人才投入的政策措施。发展天使投资和创业投资引导基金，鼓励金融机构创新产品和服务，加大对人才创新创业资金扶持力度。落实有利于人才发展的税收支持政策，完善国家有关鼓励和吸引高层次人才的税收优惠政策。","level":1},{"name":"九、加强对人才工作的领导","text":"（二十八）完善党管人才工作格局。发挥党委（党组）总揽全局、协调各方的领导核心作用，加强党对人才工作统一领导，切实履行管宏观、管政策、管协调、管服务职责。改进党管人才方式方法，完善党委统一领导，组织部门牵头抓总，有关部门各司其职、密切配合，社会力量发挥重要作用的人才工作新格局。进一步明确人才工作领导小组职责任务和工作规则，健全领导机构，配强工作力量，完善宏观指导、科学决策、统筹协调、督促落实机制。理顺党委和政府人才工作职能部门职责，将行业、领域人才队伍建设列入相关职能部门“三定”方案。\n（二十九）实行人才工作目标责任考核。建立各级党政领导班子和领导干部人才工作目标责任制，细化考核指标，加大考核力度，将考核结果作为领导班子评优、干部评价的重要依据。将人才工作列为落实党建工作责任制情况述职的重要内容。\n（三十）坚持对人才的团结教育引导服务。加强政治引领和政治吸纳，充分发挥党的组织凝聚人才作用。制定加强党委联系专家工作意见，建立党政领导干部直接联系人才机制。加强各类人才教育培训、国情研修，增强认同感和向心力。完善专家决策咨询制度，畅通建言献策渠道，充分发挥新型智库作用。建立健全特殊一线岗位人才医疗保健制度。加强优秀人才和工作典型宣传，营造尊重人才、见贤思齐的社会环境，鼓励创新、宽容失败的工作环境，待遇适当、无后顾之忧的生活环境，公开平等、竞争择优的制度环境。\n各级党委和政府要切实增强责任感、使命感，统一思想、加强领导，部门协同、上下联动，推动各项改革任务落实。鼓励支持各地区各部门因地制宜，开展差别化改革探索。加强指导监督，研究解决人才发展体制机制改革中遇到的新情况新问题。有关方面要抓紧制定任务分工方案，明确各项改革的进度安排。各地应当结合实际研究制定实施意见。加强政策解读和舆论引导，形成全社会关心支持人才发展体制机制改革的良好氛围。\n延伸阅读\n加快建立集聚人才体制机制——中央组织部负责人就《关于深化人才发展体制机制改革的意见》答记者问","level":1}]},{"id":"r0580","sections":[{"name":"关于深化中央纪委国家监委派驻机构改革的意见","text":"近日，经党中央同意，中共中央办公厅印发《关于深化中央纪委国家监委派驻机构改革的意见》。党中央决定，在巩固党的十八大以来派驻监督取得的明显成效基础上，进一步深化中央纪委国家监委派驻机构改革，完善派驻监督体制机制，为推动全面从严治党和反腐败斗争向纵深发展提供有力保证。","level":1},{"name":"","text":"党的十九大对健全党和国家监督体系作出战略部署，提出构建党统一指挥、全面覆盖、权威高效的监督体系的目标任务。《意见》指出，派驻监督是在党中央集中统一领导下，强化自上而下组织监督的重要形式，在党和国家监督体系中具有十分重要的作用。要以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的十九大和十九届二中、三中全会精神，紧紧围绕维护习近平总书记党中央的核心、全党的核心地位，紧紧围绕维护党中央权威和集中统一领导，坚持稳中求进工作总基调，改革派驻机构领导体制，完善派驻监督工作机制，赋予派驻机构监察职能，深化转职能、转方式、转作风，提高派驻监督全覆盖质量，把制度优势转化为治理效能，实现全面深化改革、全面依法治国和全面从严治党的有机统一。\n《意见》强调，全面加强对派驻机构的领导。中央纪委国家监委派驻机构是中央纪委国家监委的重要组成部分，由中央纪委国家监委直接领导、统一管理。要建立中央纪委常委会统一领导、中央纪委国家监委统一管理，中央纪委副书记（常委）、国家监委副主任（委员）分管，相关职能部门分工负责、协调配合的派驻工作领导体制，加强对派驻机构的指导、管理、服务和保障。\n《意见》明确，推动驻在部门党组织担负起全面从严治党政治责任，建立定期会商、重要情况通报、线索联合排查、联合监督执纪等机制，为党组（党委）主体作用发挥提供有效载体，形成同向发力、协作互动的工作格局。派驻机构要紧紧围绕监督这个第一职责，加强对驻在部门党组织的监督，重点检查遵守党章党规党纪和宪法法律、贯彻落实党的路线方针政策和决议等情况，确保党中央政令畅通。赋予派驻机构监察权，派驻机构既要依照党章和其他党内法规履行监督执纪问责职责，又要依照宪法和监察法履行监督调查处置职责，对行使公权力的公职人员实行监察全覆盖。健全审查调查工作机制，加强问题线索集中统一管理，完善审查调查协调、案件审理协调、重大案件督办机制。分类施策推进中管企业、中管金融企业、党委书记和校长列入中央管理的高校纪检监察体制改革。\n《意见》强调，中央纪委国家监委要及时研究解决改革中的重大问题，加强派驻机构制度建设和服务保障。中央和国家机关各部门要积极配合，自觉支持派驻机构工作，确保改革各项任务落到实处。要坚守派驻机构作为党的政治机构、派驻监督作为政治监督的职能定位，加强政治建设，强化政治担当，加强能力建设，强化管理监督，建设忠诚干净担当的派驻机构干部队伍。\n延伸阅读\n深化派驻机构改革 提高派驻监督质量 推动全面从严治党向纵深发展——专访中央纪委国家监委有关负责同志","level":0}]},{"id":"r0581","sections":[{"name":"中共中央 国务院印发《加快建设农业强国规划（2024—2035年）》","text":"近日，中共中央、国务院印发了《加快建设农业强国规划（2024—2035年）》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《加快建设农业强国规划（2024—2035年）》主要内容如下。\n强国必先强农，农强方能国强。农业强国是社会主义现代化强国的根基。面对新形势新要求，必须把加快建设农业强国作为统领“三农”工作的战略总纲，摆上建设社会主义现代化强国的重要位置。为加快建设农业强国，制定本规划。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，全面贯彻习近平总书记关于“三农”工作的重要论述，完整准确全面贯彻新发展理念，加快构建新发展格局，着力推动高质量发展，立足国情农情、体现中国特色，保持战略定力、坚持久久为功，坚持农业农村优先发展，运用“千万工程”经验，健全推动乡村全面振兴长效机制，完善城乡融合发展体制机制，一体推进农业现代化和农村现代化，更高水平守牢国家粮食安全底线和耕地保护红线，加快建设宜居宜业和美乡村，有力有效推进乡村全面振兴，加快建设供给保障强、科技装备强、经营体系强、产业韧性强、竞争能力强的农业强国，让广大农民过上更加美好的生活，为以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。\n工作中要做到：夯实产能、筑牢根基，把提高农业综合生产能力摆在更加突出的位置，紧紧围绕粮食和重要农产品供给保障短板，打牢设施基础、技术基础、装备基础、政策基础、制度基础，高水平把牢粮食安全主动权。创新驱动、厚植动能，坚持创新在现代化建设全局中的核心地位，强化科技和改革双轮驱动，加大农业关键核心技术攻关力度，进一步全面深化农村改革，提高农业创新力、竞争力、全要素生产率，增强农业强国建设后劲。绿色低碳、彰显底色，牢固树立绿水青山就是金山银山的理念，加快形成绿色低碳生产生活方式，让绿色循环、低碳发展成为农业强国的鲜明底色。共建共享、富裕农民，注重保护小农户利益，以促进农民持续增收、城乡收入差距持续缩小为重点，统筹推进产业发展、务工就业，完善强农惠农富农支持制度，牢牢守住不发生规模性返贫底线，促进城乡共同繁荣发展，让农业强国建设成果更多更公平惠及农民。循序渐进、稳扎稳打，立足资源禀赋和发展阶段，适应人口变化趋势，尊重农村发展规律，从农业农村发展最迫切、农民反映最强烈的实际问题入手，因地制宜、注重实效，分阶段扎实稳步推进。\n主要目标是：到2027年，农业强国建设取得明显进展。乡村全面振兴取得实质性进展，农业农村现代化迈上新台阶。稳产保供能力巩固提升，粮食综合生产能力达到1.4万亿斤，重要农产品保持合理自给水平。农业科技装备支撑持续强化，关键核心技术攻关取得突破，育种攻关取得显著进展，农机装备补短板取得阶段性成效。现代乡村产业体系基本健全，产业链供应链价值链延伸拓展，农业国际竞争力进一步提高。宜居宜业和美乡村建设取得积极进展，农村生态环境明显改善，集中力量抓好办成一批群众可感可及的实事，逐步实现出行、用水、如厕便利，稳步提升污水治理、诊疗服务、养老保障、乡风文明、产业带农水平。脱贫攻坚成果巩固拓展，农村居民人均可支配收入增长与国内生产总值增长基本同步，城乡居民收入差距持续缩小。到2035年，农业强国建设取得显著成效。乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件。粮食产能稳固、供给更加安全，乡村产业链升级完善、融合更加充分，乡村设施完备配套、生活更加便利，乡村公共服务普惠均等、保障更加有力，农业农村法治建设更加完善，乡村治理体系基本健全、社会更加安宁，农民收入稳定增长、城乡发展更加协调。到本世纪中叶，农业强国全面建成。供给保障安全可靠，科技创新自立自强，设施装备配套完善，乡村产业链健全高效，田园乡村文明秀美，农民生活幸福美好，国际竞争优势明显，城乡全面融合，乡村全面振兴，农业农村现代化全面实现。","level":1},{"name":"二、全方位夯实粮食安全根基，把中国人的饭碗端得更牢更稳","text":"把保障粮食和重要农产品稳定安全供给作为头等大事，落实藏粮于地、藏粮于技战略，筑牢加快建设农业强国的物质基础。\n（一）全面加强耕地保护和建设。健全耕地数量、质量、生态“三位一体”保护制度体系，改革完善耕地占补平衡制度，各类耕地占用纳入统一管理，完善补充耕地质量验收机制，确保达到平衡标准。守牢18.65亿亩耕地和15.46亿亩永久基本农田保护红线。分区分类开展盐碱耕地治理改良，因地制宜推动盐碱地等耕地后备资源开发。优先把东北黑土地区、平原地区、具备水利灌溉条件地区的耕地建成高标准农田，提高建设标准和质量，推动逐步把具备条件的永久基本农田全部建成高标准农田。完善高标准农田建设、验收、管护机制，建立健全农田建设工程质量监督检验体系。实施耕地有机质提升行动，加强黑土地保护利用和退化耕地治理。加强现代化灌区建设改造，健全农业水利基础设施网络。全面提升农业防灾减灾救灾能力。\n（二）提升粮食和重要农产品生产水平。扎实推进新一轮千亿斤粮食产能提升行动，深入实施粮油等主要作物大面积单产提升行动，加快建设国家粮食安全产业带。稳定水稻、小麦生产，促进结构优化和品质提升。因地制宜发展薯类杂粮。挖掘油菜、花生等油料作物生产潜力，拓展油茶、动物油脂等油源。强化“菜篮子”市长负责制，发展南菜北运和冷凉地区蔬菜生产，推进生猪产业高质量发展，提升奶业竞争力，开展肉牛肉羊增量提质行动，发展现代渔业。积极培育和推广糖料蔗良种，加快提高机械化作业水平。推进天然橡胶老旧胶园更新改造，加快建设特种胶园。\n（三）健全粮食生产扶持政策。全面落实耕地保护和粮食安全党政同责，压实“米袋子”保供责任。健全保障耕地用于种植基本农作物管理体系，确保粮食播种面积稳定在17.5亿亩左右、谷物面积14.5亿亩左右。加快健全种粮农民收益保障机制，完善价格、补贴、保险等政策体系，推动粮食等重要农产品价格保持在合理水平。完善农业保险大灾风险分散机制。健全粮食主产区利益补偿机制，完善产粮大县奖补制度，中央预算内投资向粮食主产区倾斜，省级统筹的土地出让收入可按规定用于粮食主产区的高标准农田建设、现代种业提升等，统筹建立粮食产销区省际横向利益补偿机制。\n（四）强化粮食和重要农产品储备调控。加快完善国家储备体系。统筹推进粮食购销和储备管理体制机制改革，建立监管新模式。健全粮食和重要农产品全链条监测预警体系。实施饲用豆粕减量替代行动，推广低蛋白日粮技术。健全粮食和食物节约长效机制，推进粮食播种、收获、储运、加工、消费等全链条全环节节约减损，完善反食品浪费制度。\n（五）构建多元化食物供给体系。树立大农业观、大食物观，全方位、多途径开发食物资源。在保护好生态环境的前提下，发展木本粮油。发展优质节水高产饲草生产。发展大水面生态渔业，推进陆基和深远海养殖渔场建设，规范发展近海捕捞和远洋渔业。实施设施农业现代化提升行动，建设标准规范、装备先进、产出高效的现代种养设施，发展农业工厂等新形态。发展生物科技、生物产业，壮大食用菌产业，推进合成生物产业化。","level":1},{"name":"三、全领域推进农业科技装备创新，加快实现高水平农业科技自立自强","text":"以农业关键核心技术攻关为引领，以产业急需为导向，加快以种业为重点的农业科技创新，推进重大农业科技突破，以发展农业新质生产力推进农业强国建设。\n（六）加快农业科技创新水平整体跃升。加强国家农业科技战略力量建设，稳定支持农业基础研究和公益科研机构，培育农业科技领军企业，构建梯次分明、分工协作、适度竞争的农业科技创新体系。强化农业基础研究前瞻性、战略性、系统性布局，加快基因组学、预防兽医学、重大病虫害成灾和气象灾害致灾机理等研究突破。改善农业领域国家实验室和全国重点实验室条件，建成一批世界一流农业科研机构和研究型农业高校。加强农业科技成果转化，推动农业主产区与科技创新活跃区深度合作。加强农业知识产权保护和侵权打击。健全公益性和经营性相结合的农业科技推广体系，加强基层农技推广队伍建设。\n（七）推动种业自主创新全面突破。深入实施种业振兴行动，加快实现种业科技自立自强、种源自主可控。加强种质资源保护利用，建设国际一流的国家农业种质资源保存、鉴定、创制和基因挖掘重大设施，推进种质资源交流共享。实施育种联合攻关和畜禽遗传改良计划，加快建设南繁硅谷。实施生物育种重大专项，选育高油高产大豆、耐盐碱作物等品种，加快生物育种产业化应用。健全植物新品种保护制度。加强现代化育制种基地建设，健全重大品种支撑推广体系和种源应急保障体系。\n（八）推进农机装备全程全面升级。加强大型高端智能农机、丘陵山区适用小型机械等农机装备和关键零部件研发应用，加快实现国产农机装备全面支撑农业高质高效发展。推进老旧农机报废更新，优化农机装备结构。打造重要农机装备产业集群，建立上下游稳定配套、工程电子等领域相关企业协同参与的产业格局。推进农机农艺深度融合，推动农机装备研发制造、熟化定型、推广应用衔接贯通，实现种养加全链条高性能农机装备应用全覆盖。\n（九）促进数字技术与现代农业全面融合。建立健全天空地一体化农业观测网络，完善农业农村统计调查监测体系，建设全领域覆盖、多层级联通的农业农村大数据平台，健全涉农数据开发利用机制。研发具有自主知识产权的智慧农业技术，健全智慧农业标准体系，释放农业农村数字生产力。实施智慧农业建设工程，推动规模化农场（牧场、渔场）数字化升级，培育链条完整、协同联动的智慧农业集群。","level":1},{"name":"四、全环节完善现代农业经营体系，促进小农户和现代农业发展有机衔接","text":"巩固和完善农村基本经营制度，牢牢守住土地公有制性质不改变、耕地红线不突破、农民利益不受损的底线，发展农业适度规模经营，促进农业经营主体高质量发展，为加快建设农业强国增活力添动能。\n（十）提升家庭经营集约化水平。有序推进第二轮土地承包到期后再延长30年试点，健全延包配套制度。深化承包地所有权、承包权、经营权分置改革，健全承包地集体所有权行使机制，依法保护承包农户合法土地权益，探索放活土地经营权的有效途径。实施小农户能力提升工程，鼓励小农户通过联户经营、联耕联种等方式开展生产。\n（十一）推进农村集体经济活权赋能。深化农村集体产权制度改革，健全农村集体资产监督管理服务体系。发挥农村集体经济组织贴近农户、服务综合、辐射带动等优势，完善农村集体经济组织在服务农业生产方面的统筹协调功能。发展新型农村集体经济，构建产权明晰、分配合理的运行机制，赋予农民更加充分的财产权益。\n（十二）推进新型农业经营主体提质增效。引导农户发展家庭农场，提升家庭农场生产经营能力。支持农民合作社依法自愿组建联合社，鼓励农民合作社开展农产品加工、仓储物流、市场营销等。完善农业经营体系，完善承包地经营权流转价格形成机制，促进农民合作经营，推动新型农业经营主体扶持政策同带动农户增收挂钩。提升农业产业化水平，健全各类市场主体联农带农利益联结机制。深化供销合作社综合改革。强化国有农场农业统一经营管理和服务职能，推进城乡及垦区一体化协调发展。\n（十三）健全便捷高效的农业社会化服务体系。加强农业社会化服务主体能力建设，引导各类涉农主体向社会化服务领域拓展。创新推广单环节、多环节托管等服务模式，推动服务由粮油作物向经济作物、畜禽水产养殖等领域拓展，由产中向产前、产后环节延伸。完善农业社会化服务标准，提升规范化服务水平。","level":1},{"name":"五、全链条推进农业产业体系升级，提升农业综合效益","text":"依托农业农村特色资源，开发农业多种功能，挖掘乡村多元价值，加快构建粮经饲统筹、农林牧渔并举、产加销贯通、农文旅融合的现代乡村产业体系，把农业建成现代化大产业。\n（十四）推动农产品加工流通优化升级。完善国家农产品加工技术研发体系，开发类别多样、品质优良的加工产品。完善全国农产品流通骨干网络，优化产地冷链集配中心布局，推动有需求的县乡村加强田头冷藏保鲜设施建设。健全县乡村物流配送体系，鼓励大型电商平台、物流、商贸等主体下沉农村，发展农村电商服务网点。\n（十五）推动农业优质化品牌化提升。深入推进农业品种培优、品质提升、品牌打造和标准化生产，增加绿色优质农产品供给。实施农业标准化提升计划。建立健全农产品品质评价和认证制度，完善农产品质量安全监管监测体系。培育一批品质过硬、竞争力强的区域公用品牌、企业品牌和产品品牌。加强中国农业品牌文化赋能，推进农业品牌与中华优秀传统文化元素相融合。\n（十六）加快发展乡村特色产业。做精做优乡村特色种养业，做好地方特色品种筛选，发展产地清洁、全程贯标、品质优良的特色种养。创新发展乡村特色手工业，培育乡村工匠，推进乡村传统工艺振兴。深度开发乡村特色文化产业，加强农业文化遗产、民族村寨、传统建筑等保护。\n（十七）促进乡村产业融合发展。推进生产、加工、流通等全环节升级，拓展产业增值增效空间。深入推进优势特色产业集群、现代农业产业园、农业产业强镇建设，实施农村产业融合发展项目。扶优培强农业产业化龙头企业，做大引领行业发展的产业链“链主”企业和区域头部企业，做优中小企业，形成生产协同、技术互补、要素共享的企业发展阵型。大力培育乡村新产业新业态，推动农业与旅游、教育、康养等产业深度融合，丰富休闲农业和乡村旅游产品。\n（十八）加快推进农业全面绿色转型。全面推行农业用水总量控制和定额管理，开展地下水超采综合治理，深入推进农业水价综合改革。健全耕地轮作休耕制度，加强受污染耕地治理和安全利用。保护重要生物物种和遗传资源，加强农业生物安全管理。健全重要农业资源台账制度。推进农业面源污染综合防治，发展生态循环农业。健全山水林田湖草沙一体化保护和系统治理机制。实施好长江十年禁渔和海洋伏季休渔，推进黄河流域农业深度节水控水。建立农业生态环境保护监测制度。推进生态综合补偿，健全横向生态保护补偿机制，统筹推进生态环境损害赔偿。","level":1},{"name":"六、进一步深化农业对外合作，培育农业国际竞争新优势","text":"坚持在开放中合作、在合作中共赢，增强国内国际两个市场两种资源联动效应，着力开创更大范围、更宽领域、更深层次农业对外合作新局面。\n（十九）提高农业国际竞争力。鼓励国内优势农产品参与国际竞争，推动农产品外贸转型升级。实施农业服务贸易促进行动。优化农业领域外商投资准入特别管理措施，发挥自由贸易试验区、海南自由贸易港等先行先试作用。深耕多双边农业合作关系，推进全球发展倡议粮食安全领域合作。实施农业领域国际大科学计划和大科学工程。深入参与全球粮农治理。","level":1},{"name":"七、高质量推进宜居宜业和美乡村建设，提升农村现代生活水平","text":"对标农村基本具备现代生活条件，推进物质文明和精神文明协调发展，实现乡村全面提升，让农民就地过上现代文明生活。\n（二十）持续提升乡村建设水平。强化县域国土空间规划对城镇、村庄、产业园区等空间布局的统筹，分类编制村庄规划。深入实施乡村建设行动，逐步提高乡村基础设施完备度、公共服务便利度、人居环境舒适度。推进乡村基础设施提档升级，加强农村交通运输网、供水设施、能源体系和新型基础设施建设。完善农村公共服务体系，提高农村教育质量，办好必要的乡村小规模学校，促进乡村医疗卫生体系健康发展，提升农村养老服务水平，健全农村老年人、留守妇女儿童和残疾人关爱服务体系。扎实推进农村厕所革命，分区分类推进农村生活污水垃圾治理，健全农村人居环境长效管护机制。编制村容村貌提升导则，保护乡村特色风貌。\n（二十一）整体提升乡村治理效能。坚持和发展新时代“枫桥经验”，健全党组织领导的自治、法治、德治相结合的乡村治理体系。深入推进抓党建促乡村全面振兴，建好建强农村基层党组织，健全以财政投入为主的稳定的村级组织运转经费保障制度。培养选拔村党组织带头人。推动基层纪检监察组织和村务监督委员会有效衔接。推进村民自治组织规范化建设，加强基层群团组织建设，推动乡村服务性、公益性、互助性社会组织健康发展。健全村民会议、村民代表会议等制度，完善农村基层公共法律服务体系。健全农村扫黑除恶常态化机制，依法管理农村宗教事务。促进治理和服务重心向基层下移，健全乡镇（街道）职责和权力、资源相匹配制度，加强乡镇（街道）服务管理力量，推广务实管用的治理方式。加强县乡村应急管理和消防安全体系建设。\n（二十二）深化农村精神文明建设。弘扬和践行社会主义核心价值观，拓展新时代文明实践中心建设，培养新时代农民。实施文明乡风建设工程，强化道德教化和激励约束，持续推进农村移风易俗。加强传统村落保护传承。推进中国传统节日振兴，以农民为主体办好中国农民丰收节。实施农耕文化传承保护工程，强化农业文化遗产挖掘整理和保护利用。加强农村公共文化服务体系建设，实施文化惠民工程。完善农村群众文艺扶持机制，增加富有农耕农趣农味、体现和谐和顺和美的乡村文化产品服务供给。","level":1},{"name":"八、促进城乡融合发展，缩小城乡差别","text":"坚持把增加农民收入作为“三农”工作的中心任务，把更多资源力量配置到产业就业上，切实增进民生福祉。\n（二十三）拓宽农民增收致富渠道。壮大县域富民产业，推动县域产业加快融入邻近大中城市产业链供应链创新链，引导劳动密集型产业梯次向县域转移。支持涉农高校、企业办好高质量职业技能培训，鼓励开展农民工急需紧缺职业专项培训，健全跨区域就业服务机制，建立区域劳务协作平台，促进农民就业拓岗增收。加强农村宅基地规范管理，允许农户合法拥有的住房通过出租、入股、合作等方式盘活利用。有序推进农村集体经营性建设用地入市改革，健全土地增值收益分配机制。健全城乡居民基本医疗保险筹资机制，推进基本养老保险制度覆盖全体农村居民并适时提高基础养老金标准，健全低保标准制定和动态调整机制。\n（二十四）推进城乡融合发展。统筹新型工业化、新型城镇化和乡村全面振兴，全面提高城乡规划、建设、治理融合水平。完善城乡融合发展体制机制和政策体系，促进城乡要素平等交换、双向流动，推动公共资源均衡配置。健全政府投资与金融、社会投入联动机制，稳步提高土地出让收入用于农业农村比例。构建城乡统一的建设用地市场，新编县乡级国土空间规划安排不少于10%建设用地指标用于农业农村。健全农业转移人口市民化配套政策体系，推行由常住地登记户口提供基本公共服务制度，推动符合条件的农业转移人口社会保险、住房保障、随迁子女义务教育等享有同迁入地户籍人口同等权利。把县域作为城乡融合发展的重要切入点，推动城乡交通道路连接、供电网络互联、客运物流一体，促进城乡基本公共服务标准统一、制度并轨。加强县域商业体系建设，发掘农村消费潜力。\n（二十五）增强脱贫地区和脱贫群众内生发展动力。完善覆盖农村人口的常态化防止返贫致贫机制，建立农村低收入人口和欠发达地区分层分类帮扶制度。按照巩固、升级、盘活、调整的原则，推进脱贫地区帮扶产业高质量发展，构建成长性好、带动力强的帮扶产业体系，将发展联农带农富农产业作为中央财政衔接推进乡村全面振兴补助资金优先支持内容。加快补齐脱贫地区农村基础设施短板，优先布局产业发展所需配套设施。发展面向脱贫地区的职业教育，持续开展“雨露计划+”就业促进行动。持续做好中央单位定点帮扶，深化东西部协作，推进“万企兴万村”行动。集中支持国家乡村振兴重点帮扶县，强化易地扶贫搬迁后续扶持。深入实施兴边富民行动。健全脱贫攻坚国家投入形成资产的长效管理机制。","level":1},{"name":"九、保障措施","text":"加快建设农业强国必须坚持和加强党的全面领导，把党的领导贯彻到农业强国建设各领域各方面各环节，确保党中央决策部署落到实处。各级党委和政府要高度重视“三农”工作，坚决扛起主体责任，将农业强国建设列入重要议事日程，纳入国民经济和社会发展规划等，确保农业强国建设各项任务不断取得实质性进展。各有关部门要加强政策协同配合，强化规划、项目、资金、要素间的有效衔接，避免重复安排建设。对本规划确定的重大任务和重大工程项目，优先保障土地供应。完善乡村振兴投入机制，健全农村金融服务体系，发展多层次农业保险，重点支持农业强国建设关键领域和薄弱环节。加强涉农干部培训，提高“三农”工作本领，打造一支政治过硬、适应新时代要求、具有服务农业强国建设能力的“三农”干部队伍。实施乡村振兴人才支持计划，坚持本土培养和外部引进相结合，加强高校涉农专业建设，提升职业教育水平，建强农业强国建设人才队伍。建立健全农业农村法律规范体系。推动东部沿海发达地区有条件省份率先建成农业强省，鼓励中西部地区经济发展水平较高、资源条件较好的市地加快建设农业强市，引导有条件的县（市、区）加快建设农业强县，分类探索差异化、特色化发展模式。重大事项及时按程序向党中央、国务院请示报告。\n延伸阅读\n农业农村部负责人就《加快建设农业强国规划（2024—2035年）》答记者问","level":1}]},{"id":"r0582","sections":[{"name":"关于在防汛救灾中充分发挥基层党组织战斗堡垒作用和广大党员先锋模范作用的通知","text":"近日，中共中央组织部印发《关于在防汛救灾中充分发挥基层党组织战斗堡垒作用和广大党员先锋模范作用的通知》。全文如下：","level":1},{"name":"","text":"近期，长江、淮河等流域，洞庭湖、鄱阳湖、太湖等湖泊处于超警戒水位，重庆、江西、安徽、湖北、湖南、江苏、浙江、贵州等地发生严重洪涝灾害，造成人员伤亡和财产损失，防汛形势十分严峻。为深入贯彻落实习近平总书记关于防汛救灾工作的重要指示精神和党中央决策部署，现就在防汛救灾中充分发挥基层党组织战斗堡垒作用和广大党员先锋模范作用的有关事项通知如下。\n一、受灾地区各级领导干部要深入一线、靠前指挥。要以高度的政治责任感和极端负责的精神，恪尽职守、勇于担当，采取得力措施，有效应对灾情，尽最大努力保障人民群众生命财产安全。坚持以身作则、身先士卒，到灾情最严重、抢险最困难、群众最需要的地方，加强现场指导，解决实际问题。组织、带领广大党员干部和人民群众全力以赴做好抢险救灾工作，妥善安置受灾群众、保障基本生活；积极进行灾后重建、恢复生产生活秩序，坚决打赢防汛救灾这场硬仗。受灾的贫困地区要把防汛救灾与决战决胜脱贫攻坚结合起来，与做好常态化疫情防控和经济社会发展各项工作结合起来，全面排查受灾情况，抓紧修复因灾受损基础设施和房屋，认真做好受灾困难群众帮扶救助，防止因灾致贫返贫。\n二、受灾地区基层党组织和党员干部要守土尽责、奋力抗灾。要视灾情为命令，把防汛救灾作为当前第一位的任务，发扬不怕疲劳、连续作战的作风，团结带领群众筑牢战胜洪涝灾害的坚强战斗堡垒。严格落实包保责任制，组织党员群众严防死守，加强轮流值班、监测预警、堤库巡查、应急处置等，及时排查化解各类风险隐患。通过组建“党员突击队”、设立“党员责任堤”、开展“党员联系户”等方式，组织党员冲锋在第一线、战斗在最前沿，成为群众的主心骨和贴心人。推动第一书记、驻村工作队就地转化为防汛救灾队，组织机关党员、干部下沉防汛救灾一线，以在危急关头、危险时刻的实际行动，影响和带动广大群众增强信心、战胜灾害、渡过难关。\n三、非受灾地区各级党组织和党员干部要心系灾区、全力支援。要按照党中央统一部署，积极行动起来，组织本地区本部门本单位力量，帮助和支持灾区抗灾救灾、恢复生产生活，充分体现社会主义大家庭的温暖。水利、电力、交通、通信、应急管理、物资保障等部门单位党组织和党员干部，要立足本职、发挥优势，千方百计支援灾区，为防汛救灾作出应有贡献。\n四、各级党委组织部门要主动履职、有效发挥作用。要动员组织基层党组织和广大党员、干部在救灾一线冲锋陷阵、挺身而出，全力投入到防汛救灾工作中去。在防汛救灾一线考察识别干部，把在防汛救灾中的表现作为评价干部的重要依据；指导基层党组织发现和考验入党积极分子，对表现突出、符合条件的，及时发展入党。注重发现、及时表扬、宣传表彰防汛救灾中涌现的基层党组织和党员、干部先进典型，充分利用各种媒体广泛宣传他们的感人事迹和崇高精神，营造不畏艰险、敢于胜利、奋勇争先的浓厚氛围。加强对防汛救灾一线党员、干部的关心关爱，会同有关方面对因公牺牲的党员、干部家属及时给予抚恤、慰问，帮助他们解决困难。","level":0}]},{"id":"r0583","sections":[{"name":"中共中央办公厅 国务院办公厅关于进一步提升基层应急管理能力的意见","text":"中共中央办公厅 国务院办公厅关于进一步提升基层应急管理能力的意见\n（2024年9月21日）","level":1},{"name":"","text":"加强基层应急管理能力建设是防范化解重大安全风险、及时应对处置各类灾害事故的固本之策，是推进应急管理体系和能力现代化的重要内容。为深入贯彻党的二十大和二十届二中、三中全会精神，认真落实习近平总书记关于应急管理和基层治理的重要论述，强化基层应急基础和力量，进一步提升基层应急管理能力，筑牢安全底板、守牢安全底线，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、提升基层应急管理组织指挥能力","text":"（一）加强党的全面领导。在党中央集中统一领导下，完善基层应急管理组织体系，把党的领导贯彻到基层应急管理工作全过程各方面。在县级党委和政府组织领导下，乡镇（街道）（含开发区、工业园区等各类功能区，下同）和村（社区）依法依规开展巡查巡护、隐患排查、信息传递、先期处置、组织群众疏散撤离以及应急知识宣传普及等应急管理工作，做到预防在先、发现在早、处置在小。充分发挥基层党组织战斗堡垒作用和党员先锋模范作用，调动广大党员参与应急管理的积极性，平时组团服务，应急时就地入列。\n（二）理顺应急管理体制。坚持资源统筹、县乡一体、上下联动、条块结合，县级党委和政府根据本地实际整合安全生产监管、消防、防灾减灾救灾、应急救援有关职责，统一归口应急管理部门综合管理。发挥应急管理部门综合优势以及相关部门和有关方面专业优势，衔接好“防”和“救”的责任链条，推动形成隐患排查、风险识别、监测预警、及时处置闭环管理。在人才、科技、装备、专业培训、业务指导等方面给予乡镇（街道）支持。乡镇（街道）明确专门工作力量，统筹强化应急管理及消防工作并纳入基层网格化管理服务内容。\n（三）建立应急指挥机制。完善县（市、区、旗）、乡镇（街道）大安全大应急框架下应急指挥机制，统一组织、指挥、协调突发事件应急处置工作。明确党政领导班子成员和相关单位职责，完善调度指挥、会商研判、业务保障等设施设备和系统，确保上下贯通、一体应对。\n（四）健全责任落实机制。坚持党政同责、一岗双责、齐抓共管、失职追责。落实分级负责、属地管理为主的原则，县级党委和政府负责本地应急管理体系和能力建设，指挥协调灾害事故抢险救援工作。党政主要负责同志是本地应急管理工作的第一责任人，定期组织研究应急管理工作；党政领导班子其他成员对分管范围内的应急管理工作承担领导责任，与业务工作同部署、同推进、同检查。县级应急管理和消防救援部门负责牵头协调有关部门，组织开展应急管理及消防工作，合理布局应急资源和人员力量。根据有关规定，按照责权一致、责能一致原则，在乡镇（街道）履行职责事项清单中，明确应急管理及消防相关基本履职事项和以上级应急管理等部门为主负责、乡镇（街道）为辅配合的履职事项，并相应下沉工作力量和资源，建立健全相关工作制度。对不属于乡镇（街道）职责范围或乡镇（街道）不能有效承接的事项，不得由乡镇（街道）承担。完善安全生产风险排查整治和责任倒查机制。","level":1},{"name":"二、提高基层安全风险防范能力","text":"（五）强化智能监测预警。推动公共安全治理模式向事前预防转型，促进专业监测和群测群防深度融合，进一步完善监测手段，提高预警精准度，实现从人防、技防向智防提升。健全自然灾害综合风险普查和数据成果动态更新制度，强化结果分析应用。加强洪涝、泥石流等自然灾害和安全生产、消防安全风险监测网络建设，建立专职或兼职信息报告员制度，推动系统应用向基层延伸，强化数据汇聚共享和风险综合研判。定期开展危险源辨识评估，积极运用物联网、大数据等先进技术，对老化燃气管道、桥涵隧道、病险水库等高风险领域加强风险实时监测，制定安全防范措施。乡镇（街道）和村（社区）在相关部门指导下建立风险隐患“一张图”，畅通预警信息发布和传播渠道，落实直达网格责任人的预警“叫应”机制，综合运用应急广播、短信微信、智能外呼、鸣锣吹哨、敲门入户等手段，及时传达到户到人。\n（六）做实隐患排查治理。市县两级加强对基层隐患排查治理的业务和技术指导，推广应用简便易用的风险隐患信息报送系统。乡镇（街道）和村（社区）配合相关部门定期开展重点检查，做好日常巡查，推动落实生产经营单位主动自查等制度，突出防御重点，盯紧基层末梢，着重开展“九小场所”、农家乐、经营性自建房、在建工地、燃气、低洼易涝点及城市地下空间、江河堤防、山塘水库、尾矿库、山洪和地质灾害危险区、森林草原火险区等风险隐患排查，提升排查专业性。企业依法配备专职或兼职安全生产管理人员。鼓励群众发现报告风险隐患并按照规定给予奖励。推行“街乡吹哨、部门报到”做法，完善发现问题、流转交办、督查督办等制度。分区域、分灾种、分行业领域建立隐患排查治理台账，采取工程治理、避险搬迁、除险加固等方式，及时消除重大隐患。\n（七）依法开展监督检查。综合运用派驻执法、联合执法、协作执法和“四不两直”等方式，提升乡镇（街道）执法效能。加强执法装备配备，强化“互联网+执法”，推动执法全过程上线入网。发挥应急管理综合行政执法技术检查员和社会监督员作用，加强专家指导服务。\n（八）广泛开展科普宣传。开展全国防灾减灾日、安全生产月、消防宣传月等活动。加强科普读物、动漫游戏、短视频等公众教育产品开发推送，采取案例警示、模拟仿真、体验互动、文艺作品等形式，深入推进安全宣传进企业、进农村、进社区、进学校、进家庭，普及应急管理法律法规和防灾减灾救灾知识，培育安全文化。有条件的地方依托公共场所、各类场馆等因地制宜建设防灾减灾体验场所，常态化开展科普宣传和技能培训，强化对基层干部教育培训，提升社会公众风险防范意识和自救互救能力。","level":1},{"name":"三、增强基层应急救援队伍实战能力","text":"（九）完善救援力量体系。市县两级根据本地人口数量、经济规模、灾害事故特点、安全风险程度等因素，依规配齐配强应急救援力量，优化队伍布局，构建“综合+专业+社会”基层应急救援力量体系，推动力量下沉、保障下倾，在党委和政府领导下，由应急管理部门统一指挥、调度使用。发挥属地企业专职救援力量、微型消防站以及民兵、预备役人员、物业管理人员、保安员、医务人员等作用，加强专兼职基层应急救援力量建设。水旱灾害、地震地质灾害、森林草原火灾等风险突出，或矿山（含尾矿库）、危险化学品等高危行业生产经营单位集中的县（市、区、旗），要加强相关专业救援力量建设。\n（十）鼓励支持社会应急力量发展。发挥有关部门、群团组织以及志愿服务组织等作用，推动社会应急力量建设。加强对社会应急力量的政治引领、政策指导和规范管理。开展政治理论、业务知识和救援技能培训，举办技能竞赛，组织实施分级分类测评。将社会应急力量纳入资源统计、管理训练和对接调动的范畴，积极搭建任务对接、技能提升、激励等平台，可在训练等方面给予适当支持。完善应急管理领域政府购买服务指导性目录。\n（十一）加强一体管理与实战训练。国家综合性消防救援队伍要充分发挥主力军作用，建立健全与基层应急救援力量联训联演联战机制。优化力量编成，对基层应急救援力量进行体系化编组，统一管理指挥，强化救援协作。坚持实战导向编制训练计划，采取理论培训、案例教学、岗位练兵、比武竞赛、联合演练等方式，提高抢险救援能力。\n（十二）加强队伍规范化建设。市县两级在充分利用现有资源的基础上，科学规划建设功能齐全、配套完善、经济实用的应急救援训练场地，推动与国防动员相关场所设施共建共享。规范救援装备配备，购置破拆、清障、防护、通信等先进适用应急装备，强化共享共用。加强队伍正规化管理，建立人员选配、值班备勤、应急响应、指挥调度、训练演练等制度。","level":1},{"name":"四、提升基层应急处置能力","text":"（十三）加强预案编制和演练。相关部门要结合当地灾害事故风险特点，指导编制并动态修订上下衔接的乡镇（街道）综合应急预案、专项应急预案和简明实用的村（社区）应急预案，制定重点岗位应急处置卡，明确各环节责任人和应对措施。常态化开展预案演练，乡镇（街道）和村（社区）每年至少组织1次以先期处置、转移避险、自救互救为重点内容的综合演练，高风险地区要加强防汛、防台风、避震自救、山洪和地质灾害避险、火灾逃生等专项演练。\n（十四）加强值班值守和信息报告发布。落实领导带班和值班值守制度。明确信息报告的主体、范围、内容、时限、流程和工作纪律，落实企业、学校、医院、村（社区）等基层单位及时报告信息的主体责任，加强多渠道多部门信息报告，强化信息互通共享，不得迟报、谎报、瞒报、漏报。按照有关规定及时、准确发布信息，积极回应社会关切。\n（十五）开展先期处置。依法赋予乡镇（街道）应急处置权。强化预警和应急响应联动，提高响应速度。灾害事故发生后，迅速启动应急预案，按照有关规定成立现场指挥部，及时组织人员转移，救早救小救初期。就近启用应急设施和避难场所，组织群众自救互救。根据需要申请上级增援并配合做好救援工作。推动应急避难场所和文化、教育、体育、旅游等基础设施融合共建、综合利用。\n（十六）统筹做好灾后救助。地方党委和政府要加强灾情统计和灾害救助，及时下拨救灾资金和物资，组织协调承保机构开展保险理赔，保障受灾群众基本生活。乡镇（街道）和村（社区）协助做好救灾资金和物资发放、卫生防疫、抚恤补偿、心理抚慰以及恢复重建等工作。组织群众开展生产自救，重建家园。","level":1},{"name":"五、强化基层应急管理支撑保障能力","text":"（十七）强化人才支持。通过公务员考录、实施基层应急管理特设岗位计划、公开招聘、退出消防员安置等方式，配备专业人员，充实基层应急专业力量。支持有条件的高校、职业学校开设应急管理相关学科专业，加强对基层应急管理人员的专业培训。鼓励基层应急管理人员考取注册安全工程师、注册消防工程师、应急救援员等职业资格，参加紧急救援救护、应急医疗急救等专业技能培训。维护退出消防员合法权益，合理保障基层应急管理人员待遇，按规定落实人身意外伤害保险、抚恤优待等政策。\n（十八）保障资金投入。按照事权与支出责任相适应原则，将基层应急管理工作经费纳入地方政府财政预算，完善多元经费保障。将救援队伍和应急场所建设、应急装备物资配备、应急信息化项目等纳入地方经济社会发展规划和相关专项规划，完善基层防灾减灾、公共消防等基础设施。\n（十九）强化物资保障。市县两级要坚持节约高效原则，综合考虑本地灾害事故特点、人口分布、地理位置等因素，合理规划应急物资储备点布局，在重点区域和高风险乡镇（街道）、村（社区）配备卫星通信终端、险情监控、救生防护等必要物资装备。对市场保有量充足、保质期短、养护成本高的物资，逐步提高协议储备占比。鼓励引导企事业单位、社会组织和家庭储备必要应急物资。充分发挥各级交通物流保通保畅工作机制作用，健全直达基层的现代应急物流调配体系。按照规定完善社会资源应急征用补偿机制。加强基层应急救援用车保障，为应急救援人员和车辆提供通行便利。\n（二十）加强科技赋能。推动“智慧应急”和基层治理有机融合，按照部省统筹管理、市县推广创新、基层落地应用的要求，推广应用符合基层实际需求的科技手段和信息化系统。强化系统集成，加强数据融合与分析应用，为乡镇（街道）和村（社区）提供隐患辅助识别、预警预报自动提醒等智能服务。加强“断路、断网、断电”等极端状态下的应急通信保障能力建设。在基层推广配备“小、快、轻、智”新型技术装备。\n（二十一）推进标准化建设。鼓励地方采取以奖代补等方式支持村（社区）综合减灾等工作。加快基层应急力量配置、场所设施、物资装备、应急标识等标准化建设，做到力量充足、设施完备、装备齐全、标识一致、管理规范。","level":1},{"name":"六、强化组织实施","text":"按照省负总责、市县抓落实的工作要求，地方各级党委和政府要把基层应急管理能力建设与重点工作统筹谋划推进，结合实际抓好本意见贯彻落实。各省（自治区、直辖市）按照分类指导、符合实际、明确职责的原则，可制定配套文件。明确细化落实应急管理工作相关部门职责，充分发挥群团组织作用，完善相关政策，形成工作合力。将应急管理工作岗位作为培养锻炼和考察识别干部的重要平台，在干部考察考核等工作中，注意了解有关领导干部履行灾害事故预防、应急准备、救援处置等职责情况。对在防范灾害事故、应急抢险救灾等急难险重任务中作出突出贡献的单位和个人，按规定给予表彰奖励；对玩忽职守造成损失或重大社会影响的，依规依纪依法严肃追究有关单位和人员责任。总结推广经验做法，加大宣传力度，营造良好氛围。","level":1}]},{"id":"r0584","sections":[{"name":"中共中央关于追授廖俊波同志“全国优秀共产党员”称号的决定","text":"专题：向廖俊波同志学习\n点击观看视频\n中共中央关于追授廖俊波同志“全国优秀共产党员”称号的决定\n（2017年6月6日）","level":1},{"name":"","text":"2017年3月31日，习近平总书记对福建省南平市委原常委、副市长、武夷新区党工委书记廖俊波同志先进事迹作出重要指示强调，廖俊波同志任职期间，牢记党的嘱托，尽心尽责，带领当地干部群众扑下身子、苦干实干，以实际行动体现了对党忠诚、心系群众、忘我工作、无私奉献的优秀品质，无愧于“全国优秀县委书记”的称号，广大党员、干部要向廖俊波同志学习，不忘初心、扎实工作、廉洁奉公，身体力行把党的方针政策落实到基层和群众中去，真心实意为人民造福。\n廖俊波，男，福建浦城人，1968年8月出生，1990年8月参加工作，1992年7月加入中国共产党，生前系福建省南平市委常委、副市长、武夷新区党工委书记，历任邵武市拿口镇镇长、党委书记，邵武市副市长，政和县委书记，南平市副市长等职务。2015年荣获“全国优秀县委书记”称号。2017年3月18日晚，廖俊波同志在赶往武夷新区主持召开会议途中不幸发生车祸，因公殉职，年仅48岁。\n廖俊波同志以党和人民事业为最高追求，以干事创业、造福百姓为最大快乐，始终做到心中有党、心中有民、心中有责、心中有戒，是“两学一做”学习教育中涌现出的先进典型，是新时期县委书记的好榜样，是用生命践行忠诚、干净、担当要求的好干部。他入党25年来，始终信念坚定、不忘初心，对党和人民无限忠诚，在每一个工作岗位都倾心尽力为党和人民事业奋斗，直至生命最后一刻。他担任政和县委书记期间，时刻想着“如何让老区人民尽快脱贫增收”，带头深入贫困村蹲点调研，分类推进精准扶贫，坚持“赚钱的事让群众干，不赚钱的事让党委政府干”，政和县3年多时间累计减少贫困人口3万多人，连续3年进入福建省县域经济发展“十佳”。他当事不推责、遇事不避难，抓工作“能在现场就不在会场”，以“背石头上山”的劲头带领干部群众苦干实干，常年奔忙在项目建设、园区开发、脱贫攻坚工作一线。他严守廉洁底线，做人光明磊落，从不利用权力、地位为自己和亲属谋取私利，时常叮嘱家人多付出、多奉献，不搞特殊，以良好的形象和口碑赢得了党员、干部和群众的广泛赞誉。\n为深入学习贯彻习近平总书记重要指示精神，表彰先进、弘扬正气，引导广大党员、干部对标先进、见贤思齐，凝心聚力、开拓奋进，在促进改革发展稳定中当先锋、作表率，党中央决定，追授廖俊波同志“全国优秀共产党员”称号。\n党中央号召，广大党员、干部特别是领导干部向廖俊波同志学习。要像廖俊波同志那样坚定理想信念、对党绝对忠诚，深入学习贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，切实增强政治意识、大局意识、核心意识、看齐意识，坚决维护以习近平同志为核心的党中央权威，始终做到政治信仰不变、政治立场不移、政治方向不偏。要像廖俊波同志那样践行全心全意为人民服务的根本宗旨，真心实意为百姓谋福祉，始终做到权为民所用、情为民所系、利为民所谋，让群众有更多获得感。要像廖俊波同志那样扑下身子真抓实干，敢挑最重的担子、敢啃最硬的骨头，始终做到敢担当、敢负责、敢作为，努力创造经得起实践、人民、历史检验的实绩。要像廖俊波同志那样清清白白做人，干干净净做事，自觉践行共产党人价值观，始终做到一身正气、两袖清风，坚守共产党人精神家园。\n各级党组织要把学习廖俊波同志先进事迹纳入推进“两学一做”学习教育常态化制度化重要内容，与学党章党规、学系列讲话结合起来，与做好改革发展稳定各项工作结合起来，采取多种形式广泛开展学习宣传。要引导党员、干部以先进典型为榜样，自觉践行“三严三实”要求，努力做到“四个合格”，更加紧密地团结在以习近平同志为核心的党中央周围，奋发有为，扎实工作，身体力行把党的方针政策和各项工作任务落实到基层和群众中去，为统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，贯彻落实新发展理念，实现“两个一百年”奋斗目标、实现中华民族伟大复兴的中国梦作出新的更大贡献。\n点击进入“两学一做”学习教育网","level":0},{"name":"榜样 先进典型库","text":"专题：全国“两优一先”","level":1},{"name":"全国优秀共产党员 2011 2006 2001 1997 1996","text":"","level":1},{"name":"先进事迹","text":"爱人者 人恒爱之——廖俊波的大爱人生\n“樵夫”的魔力——追记全国优秀县委书记廖俊波\n随时随地都在办公的副市长——追记廖俊波\n党的好干部 百姓带路人——追记全国优秀县委书记廖俊波\n用生命诠释为民情怀——追记全国优秀县委书记廖俊波\n廖俊波：扑下身子苦干实干\n廖俊波：政声人去后 百姓记心头 真心实意为人民造福\n一生好官廖俊波","level":1}]},{"id":"r0585","sections":[{"name":"关于改革社会组织管理制度促进社会组织健康有序发展的意见","text":"点击此处观看视频","level":1},{"name":"","text":"近日，中共中央办公厅、国务院办公厅印发了《关于改革社会组织管理制度促进社会组织健康有序发展的意见》，并发出通知，要求各地区各部门结合实际认真贯彻执行。\n《关于改革社会组织管理制度促进社会组织健康有序发展的意见》主要内容如下。\n为深入贯彻党的十八大和十八届二中、三中、四中、五中全会精神，进一步加强社会组织建设，激发社会组织活力，现就改革社会组织管理制度、促进社会组织健康有序发展提出以下意见。","level":0},{"name":"一、重要性和紧迫性","text":"以社会团体、基金会和社会服务机构为主体组成的社会组织，是我国社会主义现代化建设的重要力量。党中央、国务院历来高度重视社会组织工作，改革开放以来，在各级党委和政府的重视和支持下，我国社会组织不断发展，在促进经济发展、繁荣社会事业、创新社会治理、扩大对外交往等方面发挥了积极作用。同时也要看到，目前社会组织工作中还存在法规制度建设滞后、管理体制不健全、支持引导力度不够、社会组织自身建设不足等问题，从总体上看社会组织发挥作用还不够充分，一些社会组织违法违规现象时有发生。当前，我国正处于全面建成小康社会决胜阶段，改革社会组织管理制度、促进社会组织健康有序发展，有利于厘清政府、市场、社会关系，完善社会主义市场经济体制；有利于改进公共服务供给方式，加强和创新社会治理；有利于激发社会活力，巩固和扩大党的执政基础。各地区各部门要站在战略和全局高度，充分认识做好这项工作的重要性和紧迫性，将其作为一项重要基础性工作来抓，主动适应新形势新任务要求，全面落实相关政策措施，扎扎实实做好各项工作。","level":1},{"name":"二、指导思想、基本原则和总体目标","text":"（一）指导思想。以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神，按照“四个全面”战略布局要求，贯彻落实创新、协调、绿色、开放、共享发展理念，一手抓积极引导发展，一手抓严格依法管理，充分发挥社会组织服务国家、服务社会、服务群众、服务行业的作用，努力走出一条具有中国特色的社会组织发展之路。\n（二）基本原则\n——坚持党的领导。按照党中央明确的党组织在社会组织中的功能定位，发挥党组织的政治核心作用，加强社会组织党的建设，注重加强对社会组织的政治引领和示范带动，支持群团组织充分发挥作用，增强联系服务群众的合力，确保社会组织发展的正确政治方向。\n——坚持改革创新。改革社会组织管理制度，正确处理政府、市场、社会三者关系，改革制约社会组织发展的体制机制，激发社会组织内在活力和发展动力，促进社会组织真正成为提供服务、反映诉求、规范行为、促进和谐的重要力量。\n——坚持放管并重。处理好“放”和“管”的关系，既要简政放权，优化服务，积极培育扶持，又要加强事中事后监管，促进社会组织健康有序发展。\n——坚持积极稳妥推进。统筹兼顾，分类指导，抓好试点，确保改革工作平稳过渡、有序推进。\n（三）总体目标。到2020年，统一登记、各司其职、协调配合、分级负责、依法监管的中国特色社会组织管理体制建立健全，社会组织法规政策更加完善，综合监管更加有效，党组织作用发挥更加明显，发展环境更加优化；政社分开、权责明确、依法自治的社会组织制度基本建立，结构合理、功能完善、竞争有序、诚信自律、充满活力的社会组织发展格局基本形成。","level":1},{"name":"三、大力培育发展社区社会组织","text":"（一）降低准入门槛。对在城乡社区开展为民服务、养老照护、公益慈善、促进和谐、文体娱乐和农村生产技术服务等活动的社区社会组织，采取降低准入门槛的办法，支持鼓励发展。对符合登记条件的社区社会组织，优化服务，加快审核办理程序，并简化登记程序。对达不到登记条件的社区社会组织，按照不同规模、业务范围、成员构成和服务对象，由街道办事处（乡镇政府）实施管理，加强分类指导和业务指导。鼓励在街道（乡镇）成立社区社会组织联合会，发挥管理服务协调作用。\n（二）积极扶持发展。鼓励依托街道（乡镇）综合服务中心和城乡社区服务站等设施，建立社区社会组织综合服务平台，为社区社会组织提供组织运作、活动场地、活动经费、人才队伍等方面支持。采取政府购买服务、设立项目资金、补贴活动经费等措施，加大对社区社会组织扶持力度，重点培育为老年人、妇女、儿童、残疾人、失业人员、农民工、服刑人员未成年子女、困难家庭、严重精神障碍患者、有不良行为青少年、社区矫正人员等特定群体服务的社区社会组织。有条件的地方可探索建立社区社会组织孵化机制，设立孵化培育资金，建设孵化基地。鼓励社会力量支持社区社会组织发展。\n（三）增强服务功能。发挥社区社会组织在创新基层社会治理中的积极作用，推动建立多元主体参与的社区治理格局。鼓励社区社会组织开展邻里互助、居民融入、纠纷调解、平安创建等社区活动，组织社区居民参与社区公共事务和公益事业，促进社区和谐稳定。支持社区社会组织承接社区公共服务和基层政府委托事项，开展社区志愿服务。建立社区社会组织与社区建设、社会工作联动机制，促进资源共享、优势互补，把社区社会组织建设成为增强社区自治和服务功能、吸纳社会工作人才的重要载体。","level":1},{"name":"四、完善扶持社会组织发展政策措施","text":"（一）支持社会组织提供公共服务。结合政府职能转变和行政审批改革，将政府部门不宜行使、适合市场和社会提供的事务性管理工作及公共服务，通过竞争性方式交由社会组织承担。逐步扩大政府向社会组织购买服务的范围和规模，对民生保障、社会治理、行业管理等公共服务项目，同等条件下优先向社会组织购买。\n（二）完善财政税收支持政策。中央财政继续安排专项资金，有条件的地方可参照安排专项资金，支持社会组织参与社会服务，加强社会组织能力建设，有计划有重点地扶持一批品牌性社会组织。落实国家对社会组织各项税收优惠政策，符合条件的社会组织按照有关法律法规享受相关税收优惠政策。财政、税务部门要结合综合监管体制建设，研究完善社会组织税收政策体系和票据管理制度，改进和落实公益慈善事业捐赠税收优惠制度。鼓励银行业金融机构加大对符合条件社会组织的金融支持力度。\n（三）完善人才政策。把社会组织人才工作纳入国家人才工作体系，对社会组织的专业技术人员执行与相关行业相同的职业资格、注册考核、职称评定政策，对符合条件的社会组织专门人才给予相关补贴，将社会组织人才纳入国家专业技术人才知识更新工程。建立社会组织负责人培训制度，引导其自觉践行社会主义核心价值观，增强社会责任意识和诚信意识。积极向国际组织推荐具备国际视野的社会组织人才。有关部门和群团组织要将社会组织及其从业人员纳入有关表彰奖励推荐范围。民政部、人力资源社会保障部要会同有关部门研究制定加强社会组织人才工作的意见。\n（四）发挥社会组织积极作用。进一步发挥社会组织在促进经济发展、管理社会事务、提供公共服务中的作用。支持社会组织尤其是行业协会商会在服务企业发展、规范市场秩序、开展行业自律、制定团体标准、维护会员权益、调解贸易纠纷等方面发挥作用，使之成为推动经济发展的重要力量。支持社会组织在创新社会治理、化解社会矛盾、维护社会秩序、促进社会和谐等方面发挥作用，使之成为社会建设的重要主体。支持社会组织在发展公益慈善事业、繁荣科学文化、扩大就业渠道等方面发挥作用，满足人民群众多样化需求。","level":1},{"name":"五、依法做好社会组织登记审查","text":"（一）稳妥推进直接登记。重点培育、优先发展行业协会商会类、科技类、公益慈善类、城乡社区服务类社会组织。成立行业协会商会，按照《行业协会商会与行政机关脱钩总体方案》的精神，直接向民政部门依法申请登记。在自然科学和工程技术领域内从事学术研究和交流活动的科技类社会组织，以及提供扶贫、济困、扶老、救孤、恤病、助残、救灾、助医、助学服务的公益慈善类社会组织，直接向民政部门依法申请登记。为满足城乡社区居民生活需求，在社区内活动的城乡社区服务类社会组织，直接向县级民政部门依法申请登记。民政部门审查直接登记申请时，要广泛听取意见，根据需要征求有关部门意见或组织专家进行评估。国务院法制办要抓紧推动修订《社会团体登记管理条例》等行政法规。民政部要会同有关部门尽快制定直接登记的社会组织分类标准和具体办法。\n（二）完善业务主管单位前置审查。对直接登记范围之外的其他社会组织，继续实行登记管理机关和业务主管单位双重负责的管理体制。业务主管单位要健全工作程序，完善审查标准，切实加强对社会组织名称、宗旨、业务范围、发起人和拟任负责人的把关，支持符合条件的社会组织依法成立。\n（三）严格民政部门登记审查。民政部门要会同行业管理部门及相关党建工作机构，加强对社会组织发起人、拟任负责人资格审查。对跨领域、跨行业以及业务宽泛、不易界定的社会组织，按照明确、清晰、聚焦主业的原则，加强名称审核、业务范围审定，听取利益相关方和管理部门意见。严禁社会组织之间建立垂直领导或变相垂直领导关系，严禁社会组织设立地域性分支机构。对全国性社会团体，要从成立的必要性、发起人的代表性、会员的广泛性等方面认真加以审核，业务范围相似的，要充分进行论证。活动地域跨省（自治区、直辖市）的社会组织比照全国性社会组织从严审批。\n（四）强化社会组织发起人责任。国务院法制办会同民政部推动将社会组织发起人的资格、人数、行为、责任等事项纳入有关行政法规予以规范。发起人应当对社会组织登记材料的合法性、真实性、准确性、有效性、完整性负责，对社会组织登记之前的活动负责，主要发起人应当担任首届负责人。建立发起人不良行为记录档案。发起人不得以拟成立社会组织名义开展与发起无关的活动，禁止向非特定对象发布筹备和筹款信息。党政领导干部未经批准不得发起成立社会组织。经批准担任发起人但不履行责任的，批准机关要严肃问责。","level":1},{"name":"六、严格管理和监督","text":"（一）加强对社会组织负责人的管理。民政部门会同有关部门建立社会组织负责人任职、约谈、警告、责令撤换、从业禁止等管理制度，落实法定代表人离任审计制度。建立负责人不良行为记录档案，强化社会组织负责人过错责任追究，对严重违法违规的，责令撤换并依法依规追究责任。推行社会组织负责人任职前公示制度、法定代表人述职制度。\n（二）加强对社会组织资金的监管。建立民政部门牵头，财政、税务、审计、金融、公安等部门参加的资金监管机制，共享执法信息，加强风险评估、预警。民政、财政部门要推动社会组织建立健全内控管理机制，严格执行国家有关财务会计制度和票据管理使用制度，推行社会组织财务信息公开和注册会计师审计制度。财政部门要加强对社会组织财政、财务、会计等政策执行情况的监督检查，发现问题依法处罚并及时通报民政部门。税务部门要推动社会组织依法进行税务登记，对于没有在税务机关登记的社会组织，要在本意见下发后半年内完成登记手续；加强对社会组织非营利性的监督，严格核查非营利组织享受税收优惠政策的条件，落实非营利性收入免税申报和经营性收入依法纳税制度；加强对社会组织的税务检查，对违法违规开展营利性经营活动的，依法取消税收优惠资格，通报有关部门依法处罚社会组织和主要责任人。审计机关要对社会组织的财务收支情况、国有资产管理使用情况进行审计监督。金融管理部门要加强对社会组织账户的监管、对资金往来特别是大额现金支付的监测，防范和打击洗钱和恐怖融资等违法犯罪活动。中国人民银行要会同民政部加快研究将社会组织纳入反洗钱监管体系。\n（三）加强对社会组织活动的管理。各级政府及有关部门要按照职能分工加强对社会组织内部治理、业务活动、对外交往的管理。民政部门要通过检查、评估等手段依法监督社会组织负责人、资金、活动、信息公开、章程履行等情况，建立社会组织“异常名录”和“黑名单”，加强与有关部门的协调联动，将社会组织的实际表现情况与社会组织享受税收优惠、承接政府转移职能和购买服务等挂钩。民政部门要会同有关部门建立联合执法制度，严厉查处违法违规行为，依法取缔未经登记的各类非法社会组织。对被依法取缔后仍以非法社会组织名义活动的，公安机关要依法处理。行业管理部门要将社会组织纳入行业管理，加强业务指导和行业监管，引导社会组织健康发展，配合登记管理机关做好本领域社会组织的登记审查，协助登记管理机关和相关部门做好对本领域社会组织非法活动和非法社会组织的查处。外交、公安、物价、人力资源社会保障等部门对社会组织涉及本领域的事项事务履行监管职责，依法查处违法违规行为并及时向民政部门通报。实行双重管理的社会组织的业务主管单位，要对所主管社会组织的思想政治工作、党的建设、财务和人事管理、研讨活动、对外交往、接收境外捐赠资助、按章程开展活动等事项切实负起管理责任，每年组织专项监督抽查，协助有关部门查处社会组织违法违规行为，督促指导内部管理混乱的社会组织进行整改，组织指导社会组织清算工作。\n（四）规范管理直接登记的社会组织。直接登记的行业协会商会类、科技类、公益慈善类、城乡社区服务类社会组织的综合监管以及党建、外事、人力资源服务等事项，参照《行业协会商会与行政机关脱钩总体方案》及配套政策执行，落实“谁主管谁负责”的原则，切实加强事中事后监管。对已经成立的科技类、公益慈善类、城乡社区服务类社会组织，本着审慎推进、稳步过渡的原则，通过试点逐步按照对直接登记社会组织的管理方式进行管理。民政部要会同有关部门制定全国性社会组织试点方案，具体负责组织实施。地方社会组织试点工作，在各省（自治区、直辖市）党委和政府统一领导下，由民政部门具体负责组织实施，试点方案要根据当地情况研究制定。具备条件的地方可探索一业多会。已开展试点工作的地区要根据本意见精神进一步完善试点工作。\n（五）加强社会监督。鼓励支持新闻媒体、社会公众对社会组织进行监督。民政部要会同有关部门制定实施各类社会组织信息公开办法，探索建立社会组织年度报告制度，规范公开内容、机制和方式，提高透明度；探索建立专业化、社会化的第三方监督机制，建立健全社会组织第三方评估机制，确保评估信息公开、程序公平、结果公正；建立对社会组织违法违规行为及非法社会组织投诉举报受理和奖励机制，依法向社会公告行政处罚和取缔情况。\n（六）健全社会组织退出机制。对严重违反国家有关法律法规的社会组织，要依法吊销其登记证书；对弄虚作假骗取登记的社会组织，依法撤销登记；对未经许可擅自以社会组织名义开展活动的非法社会组织，依法予以取缔。完善社会组织清算、注销制度，确保社会组织资产不被侵占、私分或者挪用。","level":1},{"name":"七、规范社会组织涉外活动","text":"引导社会组织有序开展对外交流，参加非政府间国际组织，参与国际标准和规则制定，发挥社会组织在对外经济、文化、科技、体育、环保等交流中的辅助配合作用，在民间对外交往中的重要平台作用。完善相应登记管理制度，积极参与新建国际性社会组织，支持成立国际性社会组织，服务构建开放型经济新体制。确因工作需要在境外设立分支（代表）机构的，必须经业务主管单位或者负责其外事管理的单位批准。党政领导干部如确需以个人身份加入境外专业、学术组织或兼任该组织有关职务的，按干部管理权限和有关规定报批。","level":1},{"name":"八、加强社会组织自身建设","text":"（一）健全社会组织法人治理结构。针对不同类型社会组织特点制定章程示范文本。社会组织要依照法规政策和章程建立健全法人治理结构和运行机制以及党组织参与社会组织重大问题决策等制度安排，完善会员大会（会员代表大会）、理事会、监事会制度，落实民主选举、民主决策和民主管理，健全内部监督机制，成为权责明确、运转协调、制衡有效的法人主体，独立承担法律责任。推动社会组织建立健全内部纠纷解决机制，推行社会组织人民调解制度，引导当事人通过司法途径依法解决纠纷。\n（二）充分发挥党组织的战斗堡垒作用和党员的先锋模范作用。社会组织党组织要紧紧围绕党章赋予党的基层组织的基本任务开展工作，团结凝聚群众，保证社会组织正确政治方向；对社会组织重要事项决策、重要业务活动、大额经费开支、接收大额捐赠、开展涉外活动等提出意见，加强对社会组织分支机构党建工作的指导，对具备条件的分支机构，督促其及时建立党组织。对住所地不在北京以及设立分支机构的全国性、跨区域社会组织，除按有关规定由中央直属机关工委、中央国家机关工委、国务院国资委党委加强党的领导外，住所地及分支机构所在地党委应当按照“条块结合”的要求，加强对有关社会组织及其分支机构党组织的日常指导和监管服务。社会组织党组织书记一般从社会组织内部产生，提倡党员社会组织负责人担任党组织书记。规模较大、成员较多或没有合适党组织书记人选的社会组织，上级党组织可按规定选派党组织书记。积极开展党员先锋岗、党员责任区、党员公开承诺等活动。注重在社会组织负责人、管理层和业务骨干中培养和发展党员。坚持党建带群建，推动有条件的社会组织建立工会、共青团、妇联等群团组织。支持工会代表职工对社会组织贯彻执行有关法律法规和政策实施监督。\n（三）加强社会组织诚信自律建设。推动社会组织建立诚信承诺制度，建立行业性诚信激励和惩戒机制。支持社会组织建立社会责任标准体系，积极履行社会责任。引导社会组织建立活动影响评估机制，对可能引发社会风险的重要事项应事先向政府有关部门报告。强化社会组织管理服务意识，社会团体设立机构、发展会员要与其管理服务能力相适应。探索建立各领域社会组织行业自律联盟，通过发布公益倡导、制定活动准则、实行声誉评价等形式，引领和规范行业内社会组织的行为。规范社会组织收费行为，严禁巧立名目乱收费，切实防止只收费不服务、只收费不管理的现象。\n（四）推进社会组织政社分开。支持社会组织自我约束、自我管理，发挥提供服务、反映诉求、规范行为、促进和谐的作用。贯彻落实《行业协会商会与行政机关脱钩总体方案》，稳妥开展脱钩试点。除法律法规有特殊规定外，政府部门不得授权或委托社会组织行使行政审批。国务院决定取消的行政审批事项，原承担审批职能的部门不得通过任何形式指定交由行业协会商会继续审批。严格执行《中共中央办公厅、国务院办公厅关于党政机关领导干部不兼任社会团体领导职务的通知》、《中共中央组织部关于规范退（离）休领导干部在社会团体兼职问题的通知》，从严规范公务员兼任社会团体负责人，因特殊情况确需兼任的，按照干部管理权限从严审批，且兼职一般不得超过1个。在职公务员不得兼任基金会、社会服务机构负责人，已兼职的在本意见下发后半年内应辞去公职或辞去社会组织职务。","level":1},{"name":"九、加强党对社会组织工作的领导","text":"（一）完善领导体制。各级党委和政府要把加强和改进社会组织管理工作列入重要议事日程，列入地方党委和政府绩效考核内容和社会治安综合治理考评体系。地方党委和政府要建立完善研究决定社会组织工作重大事项制度；党委常委会应该定期听取社会组织工作汇报。各部门党组（党委）要加强对社会组织管理工作的组织领导，落实党建工作责任制，制定本部门管理规定，配齐配强相关管理力量，抓好督促落实。中央建立社会组织工作协调机制，地方各级要建立相应机制，统筹、规划、协调、指导社会组织工作，及时研究解决工作中出现的问题。重视和加强社会组织党风廉政建设和反腐败工作，完善社会组织惩治和预防腐败机制。\n（二）推进社会组织党的组织和工作有效覆盖。按照应建尽建的原则，加大社会组织党组织组建力度，实现党的组织和工作全覆盖。暂不具备组建条件的社会组织，可通过选派党建工作指导员、联络员或建立工会、共青团组织等开展党的工作，条件成熟时及时建立党组织。新成立的社会组织，具备组建条件的应同步建立党组织。经党中央批准，全国性重要社会组织可以设立党组。各有关部门要结合社会组织登记、检查、评估以及日常监管等工作，督促推动社会组织及时成立党组织和开展党的工作。\n（三）加强社会组织党建工作基础保障。推动建立多渠道、多元化投入的党建工作基础保障，提倡企事业单位、机关和街道社区、乡镇、村党组织与社会组织党组织资源共享、共建互促，为党组织开展活动、发挥作用创造条件。根据实际给予社会组织党组织书记和专职党务工作者适当工作津贴。加强对社会组织负责人的思想政治教育，引导他们主动支持党建工作。推动将党的建设写入社会组织章程。","level":1},{"name":"十、抓好组织实施","text":"（一）加快法制建设。加快修订出台社会团体、基金会和民办非企业单位登记管理条例。研究制定志愿服务和行业协会商会等方面的单项法律法规。加快调研论证，适时启动社会组织法的研究起草工作。鼓励和支持有条件的地方根据本意见精神出台地方性法规、地方政府规章。\n（二）加强服务管理能力建设。各有关部门、地方各级政府要寓服务于管理中，加强社会组织管理服务队伍建设，配齐配强工作力量，确保事有人管、责有人负。各级民政部门特别是县级民政部门要有专门机构和人员负责社会组织登记管理日常工作。重点加强执法队伍建设，保障工作经费，确保服务到位、执法有力、监管有效。加快建设全国社会组织管理信息系统和社会组织信用信息管理平台，推进社会组织法人库建设，提高监管水平和服务能力。\n（三）加强宣传引导。充分利用报刊、广播、电视、网络等多种方式，广泛宣传社会组织在参与社会建设和治理中的积极作用，及时总结、宣传、推广社会组织先进典型，加强社会组织理论研究和文化建设，提高公众对社会组织的认识，为社会组织改革发展营造良好社会氛围。\n（四）做好督促落实工作。各省（自治区、直辖市）党委和政府要结合实际制定本地区社会组织管理制度改革的具体实施意见，做好组织贯彻落实工作。各有关部门要根据本意见要求和职责分工，抓紧制定落实相关配套政策措施和具体管理办法，做好本系统社会组织改革工作。民政部要会同有关部门做好本意见执行情况的监督检查，确保各项任务落到实处。\n延伸阅读\n人民日报评论员：走中国特色社会组织之路","level":1}]},{"id":"r0586","sections":[{"name":"中央办公厅印发《2019—2023年全国党政领导班子建设规划纲要》","text":"近日，中共中央办公厅印发了《2019—2023年全国党政领导班子建设规划纲要》（以下简称《规划纲要》），并发出通知，要求各地区各部门各单位结合实际认真贯彻落实。","level":1},{"name":"","text":"《规划纲要》以习近平新时代中国特色社会主义思想为指导，适应“两个一百年”奋斗目标历史交汇期的新形势新任务，对2019－2023年全国各级党政领导班子建设作出全面规划，是落实新时代党的建设总要求和新时代党的组织路线、加强新时代党政领导班子建设的指导性文件。\n《规划纲要》指出，要着眼进行伟大斗争、建设伟大工程、推进伟大事业、实现伟大梦想，围绕推进国家治理体系和治理能力现代化，坚持和加强党的全面领导，坚持全面从严治党，贯彻落实新时代党的组织路线，以党的政治建设为统领，聚焦“两个维护”强化政治忠诚，着眼坚定信仰深化理论武装，适应时代发展需要配强领导班子，不断提升能力素质，持续改进作风，激励担当作为，努力锻造忠实践行习近平新时代中国特色社会主义思想的坚强领导集体，为决胜全面建成小康社会、夺取新时代中国特色社会主义伟大胜利、实现中华民族伟大复兴的中国梦提供有力组织保证。\n《规划纲要》提出，要把党的政治建设摆在首位，引导各级领导班子和领导干部增强“四个意识”、坚定“四个自信”、带头做到“两个维护”，提高政治能力，全面加强和规范党内政治生活，严格执行民主集中制。要学懂弄通做实习近平新时代中国特色社会主义思想，深化理论武装，坚持学以致用、知行合一，做习近平新时代中国特色社会主义思想的坚定信仰者、忠实实践者。要优化领导班子配备、增强整体功能，选优配强党政正职，优化年龄结构，改善专业结构，完善来源、经历结构，大力发现培养选拔优秀年轻干部，合理配备女干部、少数民族干部和党外干部。要全面提高领导水平和专业素养，注重实践锻炼，提高领导班子专业化水平，发扬斗争精神、增强斗争本领。要加强管理监督、激励担当作为，严格日常管理，完善考核评价，强化正向激励。要持之以恒改进作风、严肃纪律，密切联系群众，持续推进党风廉政建设，落实全面从严治党政治责任。\n《规划纲要》强调，各级党委（党组）要抓好贯彻落实，提高领导班子建设质量。党委（党组）主要负责同志要认真履行第一责任人职责，把选干部、配班子作为重要政治责任，履责情况要纳入考核内容。班子其他成员要各司其职、各负其责。组织（人事）部门要与其他有关部门密切配合，形成工作合力，推动各项任务顺利完成。\n延伸阅读\n努力锻造忠实践行习近平新时代中国特色社会主义思想的坚强领导集体——中央组织部负责人就印发《2019—2023年全国党政领导班子建设规划纲要》答记者问\n仲祖文：努力锻造忠实践行习近平新时代中国特色社会主义思想的坚强领导集体","level":0}]},{"id":"r0587","sections":[{"name":"关于做好国家勋章和国家荣誉称号提名评选工作的通知","text":"近日，中共中央办公厅印发了《关于做好国家勋章和国家荣誉称号提名评选工作的通知》（以下简称《通知》）。《通知》指出，今年是中华人民共和国成立70周年，为深入贯彻落实习近平新时代中国特色社会主义思想，弘扬民族精神和时代精神，激发全国各族人民建设富强民主文明和谐美丽的社会主义现代化强国的积极性，为决胜全面建成小康社会、夺取新时代中国特色社会主义伟大胜利、实现中华民族伟大复兴的中国梦不懈奋斗，党中央决定，首次开展国家勋章和国家荣誉称号评选颁授，隆重表彰一批为中华人民共和国建设和发展作出杰出贡献的功勋模范人物。","level":1},{"name":"","text":"《通知》明确了提名人选范围和条件。提名人选范围为新中国成立以来，各地区各行业各领域为中华人民共和国建设和发展作出杰出贡献的个人，包括港澳台侨人员和外国人。符合条件的已故人员可以提名。提名条件根据功勋荣誉种类不同存在差别。“共和国勋章”提名人选，应当是在中华人民共和国建设和发展中作出巨大贡献、建立卓越功勋，道德品质高尚、群众公认的杰出人士。“友谊勋章”提名人选，应当是在我国社会主义现代化建设和促进中外交流合作、维护世界和平中作出杰出贡献，对华坚定长期友好，具有良好社会声誉的外国人。国家荣誉称号提名人选，应当是在经济、社会、国防、外交、教育、科技、文化、卫生、体育等各领域各行业作出重大贡献、享有崇高声誉，道德品质高尚、群众公认的杰出人士。\n《通知》明确了提名评选程序，要求加强组织领导，精心部署安排。党和国家功勋荣誉表彰工作委员会负责国家勋章和国家荣誉称号提名评选工作的组织领导。各地区各部门党委（党组）要切实负起责任，精心组织实施，以高度的政治责任感做好相关工作。要把握正确方向，确保被提名人选的先进性、代表性和时代性。要全面考核被提名人选一贯表现，以实际贡献作为重要评判标准，坚持公开公平公正，坚持群众路线，充分发扬民主，广泛听取各方面意见，好中选优。","level":0}]},{"id":"r0588","sections":[{"name":"关于做好地方政府专项债券发行及项目配套融资工作的通知","text":"近日，中共中央办公厅、国务院办公厅印发了《关于做好地方政府专项债券发行及项目配套融资工作的通知》。全文如下：","level":1},{"name":"","text":"为贯彻落实党中央、国务院决策部署，加大逆周期调节力度，更好发挥地方政府专项债券（以下简称专项债券）的重要作用，着力加大对重点领域和薄弱环节的支持力度，增加有效投资、优化经济结构、稳定总需求，保持经济持续健康发展，经中央领导同志同意，现就有关事项通知如下。","level":0},{"name":"一、总体要求和基本原则","text":"（一）总体要求。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，认真落实党中央、国务院决策部署，坚决打好防范化解重大风险攻坚战。坚持以供给侧结构性改革为主线不动摇，坚持结构性去杠杆的基本思路，按照坚定、可控、有序、适度要求，进一步健全地方政府举债融资机制，推进专项债券管理改革，在较大幅度增加专项债券规模基础上，加强宏观政策协调配合，保持市场流动性合理充裕，做好专项债券发行及项目配套融资工作，促进经济运行在合理区间。","level":1},{"name":"（二）基本原则","text":"——坚持疏堵结合。坚持用改革的办法解决发展中的矛盾和问题，把“开大前门”和“严堵后门”协调起来，在严控地方政府隐性债务（以下简称隐性债务）、坚决遏制隐性债务增量、坚决不走无序举债搞建设之路的同时，加大逆周期调节力度，厘清政府和市场边界，鼓励依法依规市场化融资，增加有效投资，促进宏观经济良性循环，提升经济社会发展质量和可持续性。\n——坚持协同配合。科学实施政策“组合拳”，加强财政、货币、投资等政策协同配合。积极的财政政策要加力提效，充分发挥专项债券作用，支持有一定收益但难以商业化合规融资的重大公益性项目（以下简称重大项目）。稳健的货币政策要松紧适度，配合做好专项债券发行及项目配套融资，引导金融机构加强金融服务，按商业化原则依法合规保障重大项目合理融资需求。\n——坚持突出重点。切实选准选好专项债券项目，集中资金支持重大在建工程建设和补短板并带动扩大消费，优先解决必要在建项目后续融资，尽快形成实物工作量，防止形成“半拉子”工程。\n——坚持防控风险。始终从长期大势认识当前形势，坚持推动高质量发展，坚持举债要同偿债能力相匹配。专项债券必须用于有一定收益的重大项目，融资规模要保持与项目收益相平衡。地方政府加强专项债券风险防控和项目管理，金融机构按商业化原则独立审批、审慎决策，坚决防控风险。\n——坚持稳定预期。既要强化宏观政策逆周期调节，主动预调微调，也要坚持稳中求进工作总基调，精准把握宏观调控的度，稳定和提振市场预期。必须坚持结构性去杠杆的改革方向，坚决不搞“大水漫灌”。对举借隐性债务上新项目、铺新摊子的要坚决问责、终身问责、倒查责任。","level":1},{"name":"二、支持做好专项债券项目融资工作","text":"（一）合理明确金融支持专项债券项目标准。发挥专项债券带动作用和金融机构市场化融资优势，依法合规推进专项债券支持的重大项目建设。对没有收益的重大项目，通过统筹财政预算资金和地方政府一般债券予以支持。对有一定收益且收益全部属于政府性基金收入的重大项目，由地方政府发行专项债券融资；收益兼有政府性基金收入和其他经营性专项收入（以下简称专项收入，包括交通票款收入等），且偿还专项债券本息后仍有剩余专项收入的重大项目，可以由有关企业法人项目单位（以下简称项目单位）根据剩余专项收入情况向金融机构市场化融资。\n（二）精准聚焦重点领域和重大项目。鼓励地方政府和金融机构依法合规使用专项债券和其他市场化融资方式，重点支持京津冀协同发展、长江经济带发展、“一带一路”建设、粤港澳大湾区建设、长三角区域一体化发展、推进海南全面深化改革开放等重大战略和乡村振兴战略，以及推进棚户区改造等保障性安居工程、易地扶贫搬迁后续扶持、自然灾害防治体系建设、铁路、收费公路、机场、水利工程、生态环保、医疗健康、水电气热等公用事业、城镇基础设施、农业农村基础设施等领域以及其他纳入“十三五”规划符合条件的重大项目建设。\n（三）积极鼓励金融机构提供配套融资支持。对于实行企业化经营管理的项目，鼓励和引导银行机构以项目贷款等方式支持符合标准的专项债券项目。鼓励保险机构为符合标准的中长期限专项债券项目提供融资支持。允许项目单位发行公司信用类债券，支持符合标准的专项债券项目。\n（四）允许将专项债券作为符合条件的重大项目资本金。对于专项债券支持、符合中央重大决策部署、具有较大示范带动效应的重大项目，主要是国家重点支持的铁路、国家高速公路和支持推进国家重大战略的地方高速公路、供电、供气项目，在评估项目收益偿还专项债券本息后专项收入具备融资条件的，允许将部分专项债券作为一定比例的项目资本金，但不得超越项目收益实际水平过度融资。地方政府要按照一一对应原则，将专项债券严格落实到实体政府投资项目，不得将专项债券作为政府投资基金、产业投资基金等各类股权基金的资金来源，不得通过设立壳公司、多级子公司等中间环节注资，避免层层嵌套、层层放大杠杆。\n（五）确保落实到期债务偿还责任。省级政府对专项债券依法承担全部偿还责任。组合使用专项债券和市场化融资的项目，项目收入实行分账管理。项目对应的政府性基金收入和用于偿还专项债券的专项收入及时足额缴入国库，纳入政府性基金预算管理，确保专项债券还本付息资金安全；项目单位依法对市场化融资承担全部偿还责任，在银行开立监管账户，将市场化融资资金以及项目对应可用于偿还市场化融资的专项收入，及时足额归集至监管账户，保障市场化融资到期偿付。市场化转型尚未完成、存量隐性债务尚未化解完毕的融资平台公司不得作为项目单位。严禁项目单位以任何方式新增隐性债务。","level":1},{"name":"三、进一步完善专项债券管理及配套措施","text":"（一）大力做好专项债券项目推介。地方政府通过印发项目清单、集中公告等方式，加大向金融机构推介符合标准专项债券项目力度。金融管理部门积极配合地方政府工作，组织和协调金融机构参与。金融机构按照商业化原则、自主自愿予以支持，加快专项债券推介项目落地。\n（二）保障专项债券项目融资与偿债能力相匹配。地方政府、项目单位和金融机构加强对重大项目融资论证和风险评估，充分论证项目预期收益和融资期限及还本付息的匹配度，合理编制项目预期收益与融资平衡方案，反映项目全生命周期和年度收支平衡情况，使项目预期收益覆盖专项债券及市场化融资本息。需要金融机构市场化融资支持的，地方政府指导项目单位比照开展工作，向金融机构全面真实及时披露审批融资所需信息，准确反映偿还专项债券本息后的专项收入，使项目对应可用于偿还市场化融资的专项收入与市场化融资本息相平衡。金融机构严格按商业化原则审慎做好项目合规性和融资风险审核，在偿还专项债券本息后的专项收入确保市场化融资偿债来源的前提下，对符合条件的重大项目予以支持，自主决策是否提供融资及具体融资数量并自担风险。\n（三）强化信用评级和差别定价。推进全国统一的地方政府债务信息公开平台建设，由地方政府定期公开债务限额、余额、债务率、偿债率以及经济财政状况、债券发行、存续期管理等信息，形成地方政府债券统计数据库，支持市场机构独立评级，根据政府债务实际风险水平，合理形成市场化的信用利差。加快建立地方政府信用评级体系，加强地方政府债务风险评估和预警结果在金融监管等方面的应用。\n（四）提升地方政府债券发行定价市场化程度。坚持地方政府债券市场化发行，进一步减少行政干预和窗口指导，不得通过财政存款和国库现金管理操作等手段变相干预债券发行定价，促进债券发行利率合理反映地区差异和项目差异。严禁地方政府及其部门通过金融机构排名、财政资金存放、设立信贷目标等方式，直接或间接向金融机构施压。\n（五）丰富地方政府债券投资群体。落实完善相关政策，推动地方政府债券通过商业银行柜台在本地区范围内向个人和中小机构投资者发售，扩大对个人投资者发售量，提高商业银行柜台发售比例。鼓励和引导商业银行、保险公司、基金公司、社会保险基金等机构投资者和个人投资者参与投资地方政府债券。合理确定地方政府债券柜台发售的定价机制，增强对个人投资者的吸引力。适时研究储蓄式地方政府债券。指导金融机构积极参与地方政府债券发行认购，鼓励资管产品等非法人投资者增加地方政府债券投资。积极利用证券交易所提高非金融机构和个人投资地方政府债券的便利性。推出地方政府债券交易型开放式指数基金，通过“债券通”等机制吸引更多境外投资者投资。推动登记结算机构等债券市场基础设施互联互通。\n（六）合理提高长期专项债券期限比例。专项债券期限原则上与项目期限相匹配，并统筹考虑投资者需求、到期债务分布等因素科学确定，降低期限错配风险，防止资金闲置。逐步提高长期债券发行占比，对于铁路、城际交通、收费公路、水利工程等建设和运营期限较长的重大项目，鼓励发行10年期以上的长期专项债券，更好匹配项目资金需求和期限。组合使用专项债券和市场化融资的项目，专项债券、市场化融资期限与项目期限保持一致。合理确定再融资专项债券期限，原则上与同一项目剩余期限相匹配，避免频繁发债增加成本。完善专项债券本金偿还方式，在到期一次性偿还本金方式基础上，鼓励专项债券发行时采取本金分期偿还方式，既确保分期项目收益用于偿债，又平滑债券存续期内偿债压力。\n（七）加快专项债券发行使用进度。地方政府要根据提前下达的部分新增专项债务限额，结合国务院批准下达的后续专项债券额度，抓紧启动新增债券发行。金融机构按市场化原则配合地方政府做好专项债券发行工作。对预算拟安排新增专项债券的项目通过先行调度库款的办法，加快项目建设进度，债券发行后及时回补。各地要均衡专项债券发行时间安排，力争当年9月底前发行完毕，尽早发挥资金使用效益。","level":1},{"name":"四、依法合规推进重大项目融资","text":"（一）支持重大项目市场化融资。对于部分实行企业化经营管理且有经营性收益的基础设施项目，包括已纳入国家和省市县级政府及部门印发的“十三五”规划并按规定权限完成审批或核准程序的项目，以及发展改革部门牵头提出的其他补短板重大项目，金融机构可按照商业化原则自主决策，在不新增隐性债务前提下给予融资支持，保障项目合理资金需求。\n（二）合理保障必要在建项目后续融资。在严格依法解除违法违规担保关系基础上，对存量隐性债务中的必要在建项目，允许融资平台公司在不扩大建设规模和防范风险前提下与金融机构协商继续融资。鼓励地方政府合法合规增信，通过补充有效抵质押物或由第三方担保机构（含政府出资的融资担保公司）担保等方式，保障债权人合法权益。\n（三）多渠道筹集重大项目资本金。鼓励地方政府通过统筹预算收入、上级转移支付、结转结余资金，以及按规定动用预算稳定调节基金等渠道筹集重大项目资本金。允许各地使用财政建设补助资金、中央预算内投资作为重大项目资本金，鼓励将发行地方政府债券后腾出的财力用于重大项目资本金。","level":1},{"name":"五、加强组织保障","text":"（一）严格落实工作责任。财政部、国家发展改革委和金融管理部门等按职责分工和本通知要求，抓紧组织落实相关工作。省级政府对组合使用专项债券和市场化融资的项目建立事前评审和批准机制，对允许专项债券作为资本金的项目要重点评估论证，加强督促检查。地方各级政府负责组织制定本级专项债券项目预期收益与融资平衡方案，客观评估项目预期收益和资产价值。金融机构按照商业化原则自主决策，在不新增隐性债务前提下给予融资支持。\n（二）加强部门监管合作。在地方党委和政府领导下，建立财政、金融管理、发展改革等部门协同配合机制，健全专项债券项目安排协调机制，加强地方财政、发展改革等部门与金融单位之间的沟通衔接，支持做好专项债券发行及项目配套融资工作。财政部门及时向当地发展改革、金融管理部门及金融机构提供有关专项债券项目安排信息、存量隐性债务中的必要在建项目信息等。发展改革部门按职责分工做好建设项目审批或核准工作。金融管理部门指导金融机构做好补短板重大项目和有关专项债券项目配套融资工作。\n（三）推进债券项目公开。地方各级政府按照有关规定，加大地方政府债券信息公开力度，依托全国统一的集中信息公开平台，加快推进专项债券项目库公开，全面详细公开专项债券项目信息，对组合使用专项债券和市场化融资的项目以及将专项债券作为资本金的项目要单独公开，支持金融机构开展授信风险评估，让信息“多跑路”、金融机构“少跑腿”。进一步发挥主承销商作用，不断加强专项债券信息公开和持续监管工作。出现更换项目单位等重大事项的，应当第一时间告知债权人。金融机构加强专项债券项目信息应用，按照商业化原则自主决策，及时遴选符合条件的项目予以支持；需要补充信息的，地方政府及其相关部门要给予配合。\n（四）建立正向激励机制。研究建立正向激励机制，将做好专项债券发行及项目配套融资工作、加快专项债券发行使用进度与全年专项债券额度分配挂钩，对专项债券发行使用进度较快的地区予以适当倾斜支持。适当提高地方政府债券作为信贷政策支持再贷款担保品的质押率，进一步提高金融机构持有地方政府债券的积极性。\n（五）依法合规予以免责。既要强化责任意识，谁举债谁负责、谁融资谁负责，从严整治举债乱象，也要明确政策界限，允许合法合规融资行为，避免各方因担心被问责而不作为。对金融机构依法合规支持专项债券项目配套融资，以及依法合规支持已纳入国家和省市县级政府及部门印发的“十三五”规划并按规定权限完成审批或核准程序的项目，发展改革部门牵头提出的其他补短板重大项目，凡偿债资金来源为经营性收入、不新增隐性债务的，不认定为隐性债务问责情形。对金融机构支持存量隐性债务中的必要在建项目后续融资且不新增隐性债务的，也不认定为隐性债务问责情形。\n（六）强化跟踪评估监督。地方各级政府、地方金融监管部门、金融机构动态跟踪政策执行情况，总结经验做法，梳理存在问题，及时研究提出政策建议。国务院有关部门要加强政策解读和宣传培训，按职责加大政策执行情况监督力度，尤其要对将专项债券作为资本金的项目加强跟踪评估，重大事项及时按程序请示报告。","level":1}]},{"id":"r0589","sections":[{"name":"中共中央宣传部 中共中央组织部关于认真组织学习《习近平新时代中国特色社会主义思想学习问答》的通知","text":"各省、自治区、直辖市党委宣传部、组织部，中央和国家机关各部委、各人民团体宣传部门、组织人事部门，各中管金融企业党委，部分国有重要骨干企业党组（党委），部分高等学校党委，中央军委政治工作部宣传局、组织局：","level":1},{"name":"","text":"党的十八大以来，以习近平同志为核心的党中央勇于推进实践基础上的理论创新，全面系统回答了新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义这个重大时代课题，创立了习近平新时代中国特色社会主义思想。这一思想是从新时代中国特色社会主义全部实践中产生的理论结晶，是推动新时代党和国家事业不断向前发展的科学指南，是引领中国、影响世界的当代中国马克思主义、21世纪马克思主义。深入学习贯彻习近平新时代中国特色社会主义思想，是全党全国的首要政治任务。\n根据党中央要求，为把学习贯彻习近平新时代中国特色社会主义思想不断引向深入，中央宣传部组织编写了《习近平新时代中国特色社会主义思想学习问答》（以下简称《问答》）。《问答》紧跟实践发展步伐，聚焦理论热点难点，回应干部群众关切，以问答体的形式全面系统展现了习近平新时代中国特色社会主义思想的重大意义、科学体系、丰富内涵和实践要求，内容通俗易懂、形式新颖活泼，是全党开展党史学习教育的指定学习材料，是广大党员、干部、群众学习习近平新时代中国特色社会主义思想的重要辅助读物。\n各级党组织要按照学懂弄通做实的要求，组织全体党员认真读原著、学原文、悟原理，并把《问答》纳入学习计划，作出周密安排，开展多形式、分层次、全覆盖的学习培训。要紧密结合党史学习教育，把学党史和悟思想贯通起来，结合中国共产党的百年奋斗历程，深刻领会把握习近平新时代中国特色社会主义思想的精神实质、核心要义、理论品格，不断提高学习贯彻自觉性坚定性。各级党委（党组）理论学习中心组要坚持领导干部带头，学好用好《问答》，努力打造学习习近平新时代中国特色社会主义思想的“示范班”。各级党校（行政学院）、干部学院和其他各类干部教育培训机构要把《问答》纳入培训教学内容，各高校要把《问答》作为师生理论学习教材，各级党委讲师团要围绕《问答》内容，组织好对党员、干部和基层群众的宣讲活动。\n延伸阅读\n《习近平新时代中国特色社会主义思想学习问答》出版发行\n党史学习教育专题","level":0}]},{"id":"r0590","sections":[{"name":"关于深化职称制度改革的意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于深化职称制度改革的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于深化职称制度改革的意见》全文如下。\n职称是专业技术人才学术技术水平和专业能力的主要标志。职称制度是专业技术人才评价和管理的基本制度，对于党和政府团结凝聚专业技术人才，激励专业技术人才职业发展，加强专业技术人才队伍建设具有重要意义。按照党中央关于深化人才发展体制机制改革的部署，现就深化职称制度改革提出以下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。高举中国特色社会主义伟大旗帜，全面贯彻党的十八大和十八届三中、四中、五中、六中全会精神，以邓小平理论、“三个代表”重要思想、科学发展观为指导，深入贯彻习近平总书记系列重要讲话精神和治国理政新理念新思想新战略，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，牢固树立和贯彻落实新发展理念，立足服务人才强国战略和创新驱动发展战略，坚持党管人才原则，遵循人才成长规律，把握职业特点，以职业分类为基础，以科学评价为核心，以促进人才开发使用为目的，建立科学化、规范化、社会化的职称制度，为客观科学公正评价专业技术人才提供制度保障。\n（二）基本原则\n——坚持服务发展、激励创新。围绕经济社会发展和人才队伍建设需求，服务人才强国战略和创新驱动发展战略，充分发挥人才评价“指挥棒”作用，进一步简政放权，最大限度释放和激发专业技术人才创新创造创业活力，推动大众创业、万众创新。\n——坚持遵循规律、科学评价。遵循人才成长规律，以品德、能力、业绩为导向，完善评价标准，创新评价方式，克服唯学历、唯资历、唯论文的倾向，科学客观公正评价专业技术人才，让专业技术人才有更多时间和精力深耕专业，让作出贡献的人才有成就感和获得感。\n——坚持问题导向、分类推进。针对现行职称制度存在的问题特别是专业技术人才反映的突出问题，精准施策。把握不同领域、不同行业、不同层次专业技术人才特点，分类评价。\n——坚持以用为本、创新机制。围绕用好用活人才，创新人才评价机制，把人才评价与使用紧密结合，促进专业技术人才职业发展，满足各类用人单位选才用才需要。\n（三）主要目标。通过深化职称制度改革，重点解决制度体系不够健全、评价标准不够科学、评价机制不够完善、管理服务不够规范配套等问题，使专业技术人才队伍结构更趋合理，能力素质不断提高。力争通过3年时间，基本完成工程、卫生、农业、会计、高校教师、科学研究等职称系列改革任务；通过5年努力，基本形成设置合理、评价科学、管理规范、运转协调、服务全面的职称制度。","level":1},{"name":"二、健全职称制度体系","text":"（四）完善职称系列。保持现有职称系列总体稳定。继续沿用工程、卫生、农业、经济、会计、统计、翻译、新闻出版广电、艺术、教师、科学研究等领域的职称系列，取消个别不适应经济社会发展的职称系列，整合职业属性相近的职称系列。适应经济社会发展新需求，探索在新兴职业领域增设职称系列。新设职称系列由中央和国家机关有关部门提出，经人力资源社会保障部审核后，报国务院批准。各地区各部门未经批准不得自行设置职称系列。职称系列可根据专业领域设置相应专业类别。\n军队专业技术人才参加通用专业职称评审按照国家有关规定执行；相近专业职称评审可参照国家有关规定；特殊专业职称评审可根据军队实际情况制定评审办法，评审结果纳入国家人才评价管理体系。\n（五）健全层级设置。各职称系列均设置初级、中级、高级职称，其中高级职称分为正高级和副高级，初级职称分为助理级和员级，可根据需要仅设置助理级。目前未设置正高级职称的职称系列均设置到正高级，以拓展专业技术人才职业发展空间。\n（六）促进职称制度与职业资格制度有效衔接。以职业分类为基础，统筹研究规划职称制度和职业资格制度框架，避免交叉设置，减少重复评价，降低社会用人成本。在职称与职业资格密切相关的职业领域建立职称与职业资格对应关系，专业技术人才取得职业资格即可认定其具备相应系列和层级的职称，并可作为申报高一级职称的条件。初级、中级职称实行全国统一考试的专业不再进行相应的职称评审或认定。","level":1},{"name":"三、完善职称评价标准","text":"（七）坚持德才兼备、以德为先。坚持把品德放在专业技术人才评价的首位，重点考察专业技术人才的职业道德。用人单位通过个人述职、考核测评、民意调查等方式全面考察专业技术人才的职业操守和从业行为，倡导科学精神，强化社会责任，坚守道德底线。探索建立职称申报评审诚信档案和失信黑名单制度，纳入全国信用信息共享平台。完善诚信承诺和失信惩戒机制，实行学术造假“一票否决制”，对通过弄虚作假、暗箱操作等违纪违规行为取得的职称，一律予以撤销。\n（八）科学分类评价专业技术人才能力素质。以职业属性和岗位需求为基础，分系列修订职称评价标准，实行国家标准、地区标准和单位标准相结合，注重考察专业技术人才的专业性、技术性、实践性、创造性，突出对创新能力的评价。合理设置职称评审中的论文和科研成果条件，不将论文作为评价应用型人才的限制性条件。对在艰苦边远地区和基层一线工作的专业技术人才，淡化或不作论文要求；对实践性、操作性强，研究属性不明显的职称系列，可不作论文要求；探索以专利成果、项目报告、工作总结、工程方案、设计文件、教案、病历等成果形式替代论文要求；推行代表作制度，重点考察研究成果和创作作品质量，淡化论文数量要求。对职称外语和计算机应用能力考试不作统一要求。确实需要评价外语和计算机水平的，由用人单位或评审机构自主确定评审条件。对在艰苦边远地区和基层一线工作的专业技术人才，以及对外语和计算机水平要求不高的职称系列和岗位，不作职称外语和计算机应用能力要求。\n（九）突出评价专业技术人才的业绩水平和实际贡献。注重考核专业技术人才履行岗位职责的工作绩效、创新成果，增加技术创新、专利、成果转化、技术推广、标准制定、决策咨询、公共服务等评价指标的权重，将科研成果取得的经济效益和社会效益作为职称评审的重要内容。取得重大基础研究和前沿技术突破、解决重大工程技术难题、在经济社会各项事业发展中作出重大贡献的专业技术人才，可直接申报评审高级职称。对引进的海外高层次人才和急需紧缺人才，放宽资历、年限等条件限制，建立职称评审绿色通道。对长期在艰苦边远地区和基层一线工作的专业技术人才，侧重考察其实际工作业绩，适当放宽学历和任职年限要求。","level":1},{"name":"四、创新职称评价机制","text":"（十）丰富职称评价方式。建立以同行专家评审为基础的业内评价机制，注重引入市场评价和社会评价。基础研究人才评价以同行学术评价为主，应用研究和技术开发人才评价突出市场和社会评价，哲学社会科学研究人才评价重在同行认可和社会效益。对特殊人才通过特殊方式进行评价。鼓励有条件的地区单独建立基层专业技术人才职称评审委员会或评审组，单独评审。采用考试、评审、考评结合、考核认定、个人述职、面试答辩、实践操作、业绩展示等多种评价方式，提高职称评价的针对性和科学性。\n（十一）拓展职称评价人员范围。进一步打破户籍、地域、身份、档案、人事关系等制约，创造便利条件，畅通非公有制经济组织、社会组织、自由职业专业技术人才职称申报渠道。科技、教育、医疗、文化等领域民办机构专业技术人才与公立机构专业技术人才在职称评审等方面享有平等待遇。高校、科研院所、医疗机构等企事业单位中经批准离岗创业或兼职的专业技术人才，3年内可在原单位按规定正常申报职称，其创业或兼职期间工作业绩作为职称评审的依据。打通高技能人才与工程技术人才职业发展通道，符合条件的高技能人才，可参加工程系列专业技术人才职称评审。在内地就业的港澳台专业技术人才，以及持有外国人永久居留证或各地颁发的海外高层次人才居住证的外籍人员，可按规定参加职称评审。公务员不得参加专业技术人才职称评审。\n（十二）推进职称评审社会化。对专业性强、社会通用范围广、标准化程度高的职称系列，以及不具备评审能力的单位，依托具备较强服务能力和水平的专业化人才服务机构、行业协会学会等社会组织，组建社会化评审机构进行职称评审。建立完善个人自主申报、业内公正评价、单位择优使用、政府指导监督的社会化评审机制，满足非公有制经济组织、社会组织以及新兴业态职称评价需求，服务产业结构优化升级和实体经济发展。\n（十三）加强职称评审监督。完善各级职称评审委员会核准备案管理制度，明确界定评审委员会评审的专业和人员范围，从严控制面向全国的职称评审委员会。完善评审专家遴选机制，加强评审专家库建设，积极吸纳高校、科研机构、行业协会学会、企业专家，实行动态管理。健全职称评审委员会工作程序和评审规则，严肃评审纪律，明确评审委员会工作人员和评审专家责任，强化评审考核，建立倒查追责机制。建立职称评审公开制度，实行政策公开、标准公开、程序公开、结果公开。企事业单位领导不得利用职务之便为本人或他人评定职称谋取利益。建立职称评审回避制度、公示制度和随机抽查、巡查制度，建立复查、投诉机制，加强对评价全过程的监督管理，构建政府监管、单位（行业）自律、社会监督的综合监管体系。严禁社会组织以营利为目的开展职称评审，突出职称评审公益性，加强评价能力建设，强化自我约束和外部监督。\n依法清理规范各类职称评审、考试、发证和收费事项，大力查处开设虚假网站、制作和贩卖假证等违纪违法行为，打击考试舞弊、假冒职称评审、扰乱职称评审秩序、侵害专业技术人才利益等违法行为。","level":1},{"name":"五、促进职称评价与人才培养使用相结合","text":"（十四）促进职称制度与人才培养制度的有效衔接。充分发挥职称制度对提高人才培养质量的导向作用，紧密结合专业技术领域人才需求和职业标准，在工程、卫生、经济、会计、统计、审计、教育、翻译、新闻出版广电等专业领域，逐步建立与职称制度相衔接的专业学位研究生培养制度，加快培育重点行业、重要领域专业技术人才；推进职称评审与专业技术人才继续教育制度相衔接，加快专业技术人才知识更新。\n（十五）促进职称制度与用人制度的有效衔接。用人单位结合用人需求，根据职称评价结果合理使用专业技术人才，实现职称评价结果与各类专业技术人才聘用、考核、晋升等用人制度的衔接。对于全面实行岗位管理、专业技术人才学术技术水平与岗位职责密切相关的事业单位，一般应在岗位结构比例内开展职称评审。对于不实行岗位管理的单位，以及通用性强、广泛分布在各社会组织的职称系列和新兴职业，可采用评聘分开方式。坚持以用为本，深入分析职业属性、单位性质和岗位特点，合理确定评价与聘用的衔接关系，评以适用、以用促评。健全考核制度，加强聘后管理，在岗位聘用中实现人员能上能下。","level":1},{"name":"六、改进职称管理服务方式","text":"（十六）下放职称评审权限。进一步推进简政放权、放管结合、优化服务。政府部门在职称评价工作中要加强宏观管理，加强公共服务，加强事中事后监管，减少审批事项，减少微观管理，减少事务性工作。发挥用人主体在职称评审中的主导作用，科学界定、合理下放职称评审权限，人力资源社会保障部门对职称的整体数量、结构进行宏观调控，逐步将高级职称评审权下放到符合条件的市地或社会组织，推动高校、医院、科研院所、大型企业和其他人才智力密集的企事业单位按照管理权限自主开展职称评审。对于开展自主评审的单位，政府不再审批评审结果，改为事后备案管理。加强对自主评审工作的监管，对于不能正确行使评审权、不能确保评审质量的，将暂停自主评审工作直至收回评审权。\n（十七）健全公共服务体系。按照全覆盖、可及性、均等化的要求，打破地域、所有制、身份等限制，建立权利平等、条件平等、机会平等的职称评价服务平台，简化职称申报手续和审核环节。健全专业化的考试评价机构，建立职称评审考试信息化管理系统，开展职称证书查询验证服务。选择应用性、实践性、社会通用性强的职称系列，依托京津冀协同发展等国家战略，积极探索跨区域职称互认。在条件成熟的领域探索专业技术人才评价结果的国际互认。\n（十八）加强领导，落实责任。坚持党管人才原则，切实加强党委和政府对职称工作的统一领导。各级党委及其组织部门要把职称制度改革作为人才工作的重要内容，在政策研究、宏观指导等方面发挥统筹协调作用。各级政府人力资源社会保障部门会同行业主管部门负责职称政策制定、制度建设、协调落实和监督检查；充分发挥社会组织专业优势，鼓励其参与评价标准制定，有序承接具体评价工作；用人单位作为人才使用主体，要根据本单位岗位设置和人员状况，自主组织开展职称评审或推荐本单位专业技术人才参加职称评审，实现评价结果与使用有机结合。\n各地区各部门要充分认识职称制度改革的重要性、复杂性、敏感性，将职称制度改革列入重要议事日程，加强组织领导，狠抓工作落实。人力资源社会保障部要会同有关部门抓紧制定配套措施，分系列推进职称制度改革。各地区各部门要深入调查研究，制定具体实施方案，坚持分类推进、试点先行、稳步实施，妥善处理改革中遇到的矛盾和问题。加强职称管理法治建设，完善职称政策法规体系。加强舆论引导，搞好政策解读，做好深入细致的思想政治工作，引导广大专业技术人才积极支持和参与职称制度改革，确保改革平稳推进和顺利实施。\n延伸阅读\n完善职称评价标准 加强职称评审监管——人社部副部长汤涛就深化职称制度改革答记者问","level":1}]},{"id":"r0591","sections":[{"name":"关于隆重庆祝中华人民共和国成立70周年广泛组织开展“我和我的祖国”群众性主题宣传教育活动的通知","text":"近日，中共中央办公厅、国务院办公厅印发了《关于隆重庆祝中华人民共和国成立70周年广泛组织开展“我和我的祖国”群众性主题宣传教育活动的通知》，对庆祝中华人民共和国成立70周年群众性主题宣传教育活动作出安排部署。","level":1},{"name":"","text":"《通知》强调，要高举中国特色社会主义伟大旗帜，以习近平新时代中国特色社会主义思想为指导，增强“四个意识”，坚定“四个自信”，做到“两个维护”，紧紧围绕隆重庆祝中华人民共和国成立70周年，大力弘扬以爱国主义为核心的伟大民族精神，在全国城乡广泛开展形式多样、内容丰富的群众性主题宣传教育活动，着重增强仪式感、参与感、现代感，讲好中国故事，讲好中国共产党故事，讲好新时代中国特色社会主义故事，充分宣传展示中华人民共和国成立70年来特别是改革开放以来的光辉历程、伟大成就和宝贵经验，突出宣传展示党的十八大以来党和国家事业取得的全方位、开创性历史成就，发生的深层次、根本性历史变革，激励和动员全党全军全国各族人民更加紧密团结在以习近平同志为核心的党中央周围，不忘初心、牢记使命、永远奋斗，立足本职岗位作贡献，把爱国奋斗精神转化为实际行动，为决胜全面建成小康社会、夺取新时代中国特色社会主义伟大胜利、实现中华民族伟大复兴的中国梦而不懈奋斗。\n《通知》提出，要广泛开展各类群众性主题宣传教育活动。一是学习体验活动。精心设计推出学习体验线路，引导干部群众就近就便开展实地考察、国情调研，观城乡新貌、看身边变化。二是主题宣讲活动。广泛组织开展百姓宣讲活动，以真人真事和真情实感，讲好履职敬业、追梦筑梦、奋斗圆梦的故事。举办系列论坛，围绕中华人民共和国成立70年来特别是党的十八大以来相关领域发生的巨大变化、取得的伟大成就进行主题宣讲。三是共和国故事汇活动。动员老战士、老同志、老专家、老教师、老劳模等讲述亲身经历，开展读主题图书、看主题影视剧活动，组织社区诗歌会和“时代新人说——我和祖国共成长”演讲比赛，讴歌英雄事迹，弘扬革命精神。四是缅怀革命先烈活动。集中开展祭扫烈士墓、敬献花篮、宣读祭文、瞻仰遗物和继承先烈遗志宣誓活动，组织共产党员、共青团员、少先队员重温入党入团入队誓词。组织青少年暑期参加红色主题夏令营、体验营等，体验革命情怀，传承红色基因。五是先进模范学习宣传活动。评选表彰“新中国最美奋斗者”，组织干部群众深入走访慰问。六是同升国旗、同唱国歌活动。从现在到今年年底，每天早上7时，各级广播电台、电视台在主频率、主频道整点播放国歌。各级党政机关、人民团体、大型企事业单位、全国城乡社区和爱国主义教育基地等，国庆前后要举行隆重的升国旗仪式，在国庆长假期间要悬挂国旗。鼓励居民家庭悬挂国旗。各级各类学校要教育学生了解国旗、国徽和国歌的历史和精神内涵。七是主题作品征集展示活动。围绕“我和祖国共成长”，征集评选展示一批主题鲜明、体裁多样的优秀作品，传播主流价值理念。八是“开学第一课”教育活动。聚焦“我和祖国共成长”，深入开展爱国主义教育和革命传统教育。举办面向青少年学生的多媒体作品征集展示活动。九是节日主题活动。深入挖掘中华民族传统节日的文化内涵，突出爱国主题，就近就便开展小型多样的节日文化活动，传承优秀节日文化、传统美德。十是国防教育活动。以“赞颂辉煌成就、军民同心筑梦”为主题，深入基层组织开展宣讲活动。组织开展国防主题文艺展演、竞技比赛、军事研学、军营开放、国防教育进校园等活动，增强全民国防观念。十一是网上主题宣传教育活动。围绕“我和我的祖国”主题，主动设置议题，精心设计开发网民喜闻乐见的网络文化产品，开展网上缅怀先烈活动、网上知识竞赛等，吸引网民参与。十二是各类群众性文化活动。组织开展广场舞展演、合唱节、音乐节等活动，在各地社区举办邻居节，开展爱心陪伴、邻里圆桌会、邻里结对帮扶等活动，广泛开展国庆游园活动，营造欢乐喜庆祥和的节日气氛。十三是精心打造社会公共环境。实施公益宣传平台传播工程，开展公益广告宣传。充分利用街头阵地，张贴悬挂展示标语口号、宣传挂图，打造街头正能量。\n《通知》强调，各地区各部门要把握正确方向，坚定不移地同以习近平同志为核心的党中央保持高度一致，坚持团结稳定鼓劲、正面宣传为主。要突出思想内涵，把成就讲足、把经验讲透、把形势讲清、把前景讲明，进一步振奋精神、鼓舞士气。要吸引群众参与，坚持热在基层、热在群众，充分发挥群众主体性，引领广大群众立足本职作贡献、建功立业新时代。要培育国庆文化，使国庆黄金周成为爱国活动周。要坚持务实节俭，着力推动解决实际问题，增强群众的获得感、成就感、幸福感，让喜庆气氛浸染每一个社会群体。要严格落实中央八项规定及其实施细则精神，坚决反对形式主义，坚决防止铺张浪费，注重节俭办活动，不给基层和群众增加负担，严禁借庆祝活动搞商业投机和不正之风，严禁违规制作发放纪念品和集资摊派。要加强组织领导，周密安排、精心实施，充分结合实际，因地制宜，务求实效，把安全责任落实到活动的各个环节，确保各项活动安全有序、欢乐祥和。\n《通知》还同时发布了庆祝中华人民共和国成立70周年宣传标语口号，供各地区各部门选用。","level":0}]},{"id":"r0592","sections":[{"name":"中办印发《省（自治区、直辖市）纪委书记、副书记提名考察办法（试行）》等三个文件","text":"落实十八届三中全会决定，党的纪律检查体制改革取得新的制度成果\n中共中央办公厅印发《省（自治区、直辖市）纪委书记、副书记提名考察办法（试行）》等三个文件","level":1},{"name":"","text":"点击此处观看视频\n近日，经中央全面深化改革领导小组会议审议，中共中央办公厅印发了《省（自治区、直辖市）纪委书记、副书记提名考察办法（试行）》、《中央纪委派驻纪检组组长、副组长提名考察办法（试行）》、《中管企业纪委书记、副书记提名考察办法（试行）》。\n三个《提名考察办法》是党中央推进党的纪律检查体制改革的重大举措，是落实党章规定和十八届三中全会第36条的具体化，是中央纪委立足本届任期立行立改、探索实践的制度成果，为坚持党对反腐败工作的领导、增强纪委监督权的权威性提供了组织制度保障。办法紧扣提名考察作出规定，明确省（自治区、直辖市）纪委书记副书记、中央纪委派驻纪检组组长副组长、中管企业纪委书记副书记的提名、考察以上级纪委会同组织部门为主。在提名条件上，突出强调纪委书记、副书记人选要敢于监督、善于监督，注重从履行党风廉政建设主体责任、监督责任表现突出的优秀干部中选拔；在干部来源上，明确要拓宽选人视野和渠道，可以从纪检监察系统内和系统外提名，纪委书记人选一般应当交流任职。在提名、考察程序上，分别明确了提名、考察具体要求和有关各方的职责分工。\n三个《提名考察办法》着眼于打造一支忠诚、干净、担当的纪检干部队伍，紧紧抓住领导干部这个“关键少数”，强调坚持党管干部原则，坚持五湖四海，坚持高标准严要求。纪检干部是党的干部的重要组成部分。要依靠各级党委、纪委和组织部门齐心协力，全面提高知人识人、选人用人能力水平，强化责任担当，确保选拔出来的纪检领导干部过得硬、立得住，经得起考验，切实担负起监督执纪问责职责。\n办法已经出台，关键在于落实。各级党委、纪委和组织部门要根据三个《提名考察办法》精神，紧密结合实际，切实选好配强各级纪委书记副书记、纪检组组长副组长，为党风廉政建设和反腐败斗争提供坚强组织保证。\n延伸阅读：\n认真落实三个《提名考察办法》 打造忠诚干净担当的纪检干部队伍——专访纪律检查体制改革专项小组负责同志","level":0}]},{"id":"r0593","sections":[{"name":"中办国办发出通知要求 切实做好元旦春节期间有关工作 确保各族人民群众度过欢乐祥和的节日","text":"近日，中共中央办公厅、国务院办公厅就做好2013年元旦、春节期间有关工作发出通知，要求各地区各部门认真学习贯彻党的十八大精神，学习贯彻中央关于改进工作作风、密切联系群众的各项规定和要求，切实做好关心群众生活的各项工作，确保各族人民群众度过欢乐祥和的节日。","level":1},{"name":"","text":"通知强调，各级党委和政府要把民生工作放在更加突出位置，采取有力措施解决好群众生活中的实际困难和问题。及时足额发放基本养老金、失业保险金、困难群众救助资金和优抚对象抚恤补助金，及早发放困难群众和重点优抚对象春节一次性生活补贴。妥善安排受灾地区群众生活，中央和地方各级政府安排的救灾资金要及时足额发放到户到人，解决好灾区群众口粮、饮水、衣被、住所、取暖、看病等问题。做好城市流浪乞讨人员救助服务工作，确保他们安全过冬。开展就业援助月活动，重点帮助零就业家庭、未就业残疾人、未就业高校毕业生等实现就业。集中开展农民工工资支付情况专项执法检查，保证农民工及时足额拿到应得报酬。广泛开展走访慰问、送温暖献爱心和志愿服务活动。\n通知要求，各地要积极组织货源，加强价格监管，严格落实鲜活农产品运输“绿色通道”政策，保证节日商品市场供应充足、价格稳定。搞好煤电油气运跟踪监测和协调，保证节日期间供水、供电、供油、供气、供暖不出问题。集中开展产品质量和食品药品安全专项执法检查。组织更多优秀文艺节目和文化产品，加大公共文化设施免费开放力度，深入开展文化卫生科技“三下乡”活动，在乡村、社区广泛开展群众性文娱活动，加大文化市场综合执法力度，丰富城乡居民节日精神文化生活。着力整顿和规范旅游市场秩序，营造良好旅游消费环境。大力宣传节约、绿色、低碳消费，积极倡导健康文明节日文化理念。\n通知强调，要在节前集中开展安全生产大检查和专项治理整顿，着力抓好煤矿、消防、交通运输、烟花爆竹等重点行业和领域安全隐患排查治理，坚决遏制重特大事故发生。加强大型集会、烟花燃放等活动安全防护工作，严防发生拥挤、踩踏等事故。扎实做好春运工作，落实好重大节假日小型客车免费通行政策，加强交通安全监管执法，保障群众出行安全顺利。深入开展矛盾纠纷排查化解工作，着力做好信访工作。加强社会管理综合治理，严厉打击违法犯罪活动，加大社会面巡逻防控力度，努力营造平安和谐社会环境。\n通知要求，各级领导干部要深入基层一线、深入贫困地区和受灾地区、深入困难群众中去，积极为群众排忧解难。到基层调研和走访慰问要轻车简从，不扰民、不增加基层负担。大力弘扬艰苦奋斗、勤俭节约作风，本着简约、俭朴原则安排好节日期间各种活动。大力精简各种茶话会、联欢会，严格控制年终评比达标表彰活动，严禁用公款搞相互走访、送礼、宴请等拜年活动，未经批准不得举办各类节日庆典活动。严禁以各种名义年终突击花钱和滥发津贴、补贴、奖金、实物，严禁公车私用，严禁用公款大吃大喝、旅游和参与各种高消费娱乐、健身活动，严禁收受可能影响公正执行公务的礼品、礼金、有价证券、支付凭证和商业预付卡，严禁参与赌博活动。各级纪检监察机关要加大监督检查力度，对违纪违规行为要发现一起、查处一起、通报一起。\n通知强调，各地区各部门各单位要严格执行值班制度，确保节日期间工作正常运转。","level":0}]},{"id":"r0594","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于进一步深化改革促进乡村医疗卫生体系健康发展的意见》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于进一步深化改革促进乡村医疗卫生体系健康发展的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于进一步深化改革促进乡村医疗卫生体系健康发展的意见》全文如下。\n完善乡村医疗卫生体系，是全面推进健康中国建设的迫切要求，也是全面推进乡村振兴的应有之义。为进一步深化改革，促进乡村医疗卫生体系健康发展，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻党的二十大精神，落实新时代党的卫生与健康工作方针，把乡村医疗卫生工作摆在乡村振兴的重要位置，以基层为重点，以体制机制改革为驱动，加快县域优质医疗卫生资源扩容和均衡布局，推动重心下移、资源下沉，健全适应乡村特点、优质高效的乡村医疗卫生体系，让广大农民群众能够就近获得更加公平可及、系统连续的医疗卫生服务，为维护人民健康提供有力保障。\n（二）工作原则\n——坚持和加强党对乡村医疗卫生工作的全面领导。把保障人民健康放在优先发展的战略位置，坚持乡村基本医疗卫生服务公益属性，发挥党委领导和政府主导作用，压实地方特别是市县两级党委和政府主体责任。\n——坚持强化医疗卫生资源县域统筹。按照因地制宜、先立后破的要求，加强县域内资源整合和优化配置，改善基层基础设施条件，推进县域医共体建设，提高乡村医疗卫生体系综合服务、应急处置和疫情防控能力。\n——坚持把人才队伍建设摆在重要位置。发展壮大医疗卫生队伍，把工作重点放在农村和社区，尊重人才价值和成长规律，立足在岗乡村医生现状，加强适宜人才培养和引进，推动乡村医生向执业（助理）医师转化，打造一支专业化、规范化乡村医生队伍。\n——坚持进一步深化体制机制改革。推进医疗、医保、医药、医教改革协同联动，创新完善乡村医疗卫生管理体制和运行机制，切实落实乡村医生多渠道补偿政策，统筹解决好乡村医生收入和待遇保障问题，健全多劳多得、优绩优酬的激励制度，防止给农民群众增加不应有的负担，保持医保基金平稳运行，激发改革内生动力。\n（三）目标任务。到2025年，乡村医疗卫生体系改革发展取得明显进展。乡村医疗卫生机构功能布局更加均衡合理，基础设施条件明显改善，智能化、数字化应用逐步普及，中医药特色优势进一步发挥，防病治病和健康管理能力显著提升，乡村重大疫情和突发公共卫生事件应对处置能力不断增强。乡村医疗卫生人才队伍发展壮大，人员素质和结构明显优化，待遇水平得到提高，养老等社会保障问题有效解决。乡村医疗卫生体系运行机制进一步完善，投入机制基本健全，基层首诊、双向转诊、急慢分治、上下联动的分级诊疗格局初步形成。","level":1},{"name":"二、强化县域内医疗卫生资源统筹和布局优化","text":"（四）优化乡村医疗卫生机构布局。根据乡村形态变化和人口迁徙流动情况，因地制宜合理配置乡村两级医疗卫生资源，宜乡则乡、宜村则村，提升乡村医疗卫生机构单体规模和服务辐射能力，从注重机构全覆盖转向更加注重服务全覆盖。重点支持建设一批能力较强、具有一定辐射和带动作用的中心乡镇卫生院。常住人口较多、区域面积较大、县城不在县域中心、县级医院服务覆盖能力不足的县，可以在县城之外选建1至2个中心乡镇卫生院，使其基本达到县级医院服务水平。依托村党群服务中心建好用好村卫生室，增强卫生健康服务功能。鼓励服务半径小、交通便利地区相邻行政村合建卫生室。对于临近乡镇卫生院、人口较少等不适宜单设卫生室的行政村，可以通过乡镇卫生院定期巡诊、派驻以及邻（联）村延伸服务等方式，保障基本医疗卫生服务供给。加强边远地区、民族地区以及山区（高原）、海岛、牧区、库区等特殊地区村卫生室建设。推进乡村医疗卫生机构一体化管理，有条件的地方可以逐步将符合条件的公办村卫生室转为乡镇卫生院延伸举办的村级医疗服务点。\n（五）强化和拓展县域医疗卫生体系服务功能。健全以县级医院为龙头、乡镇卫生院为枢纽、村卫生室为基础的乡村医疗卫生服务体系，推进县域内医疗卫生服务一体化。提高县级医院常见病、多发病、慢性病诊疗以及危急重症患者抢救和疑难复杂疾病向上转诊服务能力。支持县级医院设施和服务能力建设，力争常住人口超过5万人或服务半径大的县（市、旗）至少有1所县级医院（包含中医医院）达到二级甲等医院医疗服务能力。全面提升乡镇卫生院防病治病和健康管理能力，鼓励拓展康复医疗、医养结合、安宁疗护等服务功能。完善并提高乡镇卫生院建设和装备标准，健全急诊急救和巡诊服务体系，提升外科服务能力，使其可以按照相关诊疗规范开展常规手术。加强村卫生室能力建设，强化其基本医疗服务功能，允许具备条件的村卫生室拓展符合其功能定位的医疗服务。可以采取县域内医疗卫生机构整体参加医疗责任保险等方式，健全村卫生室医疗风险分担机制。坚持中西医并重，促进中医药传承创新发展，扩大乡村医疗卫生机构中医药服务供给。鼓励社会力量办诊所、门诊部、民营医院等，为农民群众提供多元化医疗服务，并参与承接政府购买公共卫生服务。\n（六）加强乡村医疗卫生体系疾病预防控制能力建设。创新医防协同、医防融合机制，健全乡村公共卫生体系。制定完善乡村医疗卫生机构公共卫生责任清单。加强县级医院、乡镇卫生院公共卫生相关科室建设。在有条件的乡镇中心卫生院建立标准化的发热门诊，配备负压救护车，一般乡镇卫生院建立标准化的发热诊室（哨点）。强化村卫生室基本公共卫生服务功能，严格落实传染病疫情报告责任，提高风险隐患早期识别能力，筑牢农村疾病预防控制网底。加强县域传染病防控救治体系和应急处置能力建设。推进县级疾病预防控制中心标准化建设。加强医疗机构与疾病预防控制机构医防协同配合，逐步建立疾病预防控制监督员制度。\n（七）加快推进县域内医疗卫生服务信息化。完善区域全民健康信息标准化体系，推进人口信息、电子病历、电子健康档案和公共卫生信息互联互通共享，到2025年统筹建成县域卫生健康综合信息平台。大力推进“互联网+医疗健康”，构建乡村远程医疗服务体系，推广远程会诊、预约转诊、互联网复诊、远程检查，加快推动人工智能辅助诊断在乡村医疗卫生机构的配置应用。提升家庭医生签约和乡村医疗卫生服务数字化、智能化水平。","level":1},{"name":"三、发展壮大乡村医疗卫生人才队伍","text":"（八）多渠道引才用才。改革完善乡村医疗卫生人才培养机制，切实增加全科、儿科、儿童保健科、口腔科以及中医、护理、公共卫生、预防保健、心理健康、精神卫生、康复、职业健康等紧缺人才供给。逐步扩大农村订单定向免费医学生培养规模，完善协议服务政策，地方可根据实际需求面向农村规范培养拟从事全科医疗的高等职业教育层次医学生。落实艰苦边远地区县乡医疗卫生机构公开招聘倾斜政策。医学专业高等学校毕业生到乡村两级医疗卫生机构工作，按规定享受基层就业学费补偿国家助学贷款代偿政策。落实医学专业高等学校毕业生免试申请乡村医生执业注册政策，免试注册的大学生乡村医生应限期考取执业（助理）医师资格。积极组织执业（助理）医师参加全科医生转岗培训。引导符合条件的乡村医生参加执业（助理）医师资格考试，依法取得执业（助理）医师资格。到2025年，乡村医生中具备执业（助理）医师资格的人员比例提高到45%左右，逐步形成以执业（助理）医师为主体、全科专业为特色的乡村医疗卫生服务队伍。\n（九）创新人才使用机制。加强县域医疗卫生人才一体化配置和管理，有条件的地方可对招聘引进的医疗卫生人才实行县管乡用、乡聘村用，建立健全人才双向流动机制。适当提高乡镇卫生院的中高级专业技术岗位比例。对在乡镇卫生院连续工作满15年或累计工作满25年且仍在乡镇卫生院工作的专业技术人员，在满足聘用条件下，可通过“定向评价、定向使用”聘用至相应岗位，不受岗位结构比例限制。逐步将实现乡村一体化管理的村卫生室执业（助理）医师纳入乡镇卫生院职称评聘。统筹县域内医疗卫生人才资源，建立健全定期向乡村派驻医务人员工作机制。鼓励县级医疗卫生机构与县域内乡村医疗卫生机构共同开展家庭医生签约服务，稳步扩大服务覆盖面。健全公共卫生医师制度，探索在乡村医疗卫生机构赋予公共卫生医师处方权。建立公共卫生专业技术人员和医疗机构临床医生交叉培训制度，鼓励人员双向流动。\n（十）完善收入和待遇保障机制。落实“允许医疗卫生机构突破现行事业单位工资调控水平，允许医疗服务收入扣除成本并按规定提取各项基金后主要用于人员奖励”要求，统筹平衡乡镇卫生院与当地县级公立医院绩效工资水平的关系，合理核定绩效工资总量和水平。提升乡村医疗卫生机构全科医生工资水平，使其与当地县级公立医院同等条件临床医师工资水平相衔接。有条件的地方可以在乡村医疗卫生机构绩效工资内部分配时设立全科医生津贴项目并在绩效工资中单列。完善并落实基本公共卫生服务经费、医保基金和农村居民个人共同负担家庭医生签约服务费政策，拓宽筹资渠道，探索统筹使用，完善分配机制。严格落实乡村医生基本公共卫生服务补助、基本药物制度补助、一般诊疗费政策，动态调整补助标准，逐步提高乡村医生收入。对在艰苦边远地区和国家乡村振兴重点帮扶县服务的乡村医生，地方要适当增加补助。盘活现有资源，妥善安排乡镇卫生院特别是中西部偏远地区乡镇卫生院职工周转住房。对属于农村集体经济组织成员的乡村医生，要切实维护其合法权益。\n（十一）盘活用好县域编制资源。以县为单位每5年动态调整乡镇卫生院人员编制总量，盘活用好存量编制。乡镇卫生院用于专业技术人员的编制不得低于编制总额的90%。拓宽乡村医生发展空间，同等条件下乡镇卫生院优先聘用获得执业（助理）医师资格的乡村医生，进一步吸引执业（助理）医师、医学院校毕业生到村卫生室工作。\n（十二）分类解决乡村医生养老和医疗保障问题。已纳入事业编制的乡村医生，按照有关规定参加机关事业单位基本养老保险、职工基本医疗保险等社会保险。未纳入事业编制的乡村医生，按照有关规定参加企业职工基本养老保险或城乡居民基本养老保险、职工基本医疗保险或城乡居民基本医疗保险等社会保险，有条件的地方可以结合实际给予适当补助。对年满60周岁的乡村医生，各地要结合实际采取补助等多种形式进一步提高其养老待遇。","level":1},{"name":"四、改革完善乡村医疗卫生体系运行机制","text":"（十三）加快构建紧密型县域医共体。推进紧密型县域医共体建设，在编制使用、人员招聘、人事安排、绩效考核、收入分配、职称评聘等方面赋予其更多自主权，推动实行人财物统一集中管理。对紧密型县域医共体实行医保基金总额付费，加强监督考核，建立结余留用、合理超支分担机制，落实医共体牵头医疗卫生机构对医共体内各成员医疗卫生机构规范合理使用医保基金的内部监督管理责任，强化激励约束。鼓励对医共体内各医疗卫生机构负责人实行年薪制。加强医共体绩效考核，引导资源和患者向乡村两级医疗卫生机构下沉。推动乡镇卫生院与县级医院用药目录衔接统一、处方自由流动。开展中医治未病服务。\n（十四）健全乡村医疗卫生体系投入机制。落实市县两级党委和政府乡村医疗卫生体系建设主体责任，政府办乡村医疗卫生机构的基本建设和设备购置等发展建设支出由地方政府根据基层医疗卫生机构发展建设规划足额安排；人员经费和业务经费等运行成本通过服务收费和政府补助补偿，政府补助按照“核定任务、核定收支、绩效考核补助”的办法核定。有条件的地方可以对村卫生室给予运行补助。省级加大统筹力度，确保乡村医疗卫生体系均衡健康发展。中央财政通过基本公共卫生服务、基本药物制度补助资金对乡村医疗卫生机构予以支持，并对提升困难地区乡村基层医疗服务能力按规定给予补助。中央预算内投资加大对县域医疗服务体系龙头医疗机构的投入，重点支持脱贫地区、原中央苏区、易地扶贫搬迁安置地区县级医院建设。地方政府新增财力向乡村医疗卫生领域倾斜。\n（十五）建立健全城市支援健康乡村建设机制。完善城乡协同、以城带乡帮扶机制，深化医疗卫生对口帮扶，有计划开展医疗人才组团式帮扶，鼓励国家和省级区域医疗中心开展对欠发达地区、革命老区、边境地区医疗卫生机构的对口帮扶，将指导基层、下沉服务作为县级以上公立医院的基本职责。建立健全城市三级医院包县、二级医院包乡、乡镇卫生院包村工作机制。深化东西部协作，将支持乡村医疗卫生体系建设作为重要帮扶内容。","level":1},{"name":"五、提高农村地区医疗保障水平","text":"（十六）巩固拓展医疗保障脱贫攻坚成果。持续健全基本医保、大病保险、医疗救助三重制度综合保障机制。落实分类资助农村低收入人口参保政策，继续对农村特困人员参保给予全额资助、对低保对象参保给予定额资助；完善符合条件的易返贫致贫人口资助参保政策，资助标准由各省（自治区、直辖市）根据经济社会发展水平和城乡居民基本医保筹资标准合理确定。强化高额医疗费用支出预警监测，建立健全防范化解因病返贫致贫风险长效机制。\n（十七）加大医保基金支持力度。积极通过乡村一体化管理实现村卫生室医保结算，在有条件的地方支持将符合条件的村卫生室纳入医保定点管理。支持分级诊疗模式和家庭医生签约服务制度建设，依托乡村医疗卫生机构推行门诊统筹按人头付费。有条件的地方可以调整乡镇卫生院、村卫生室一般诊疗费。各地实施动态调整医疗服务价格时，要统筹支持乡村医疗卫生机构发展，促进分级诊疗。合理提高医保基金对乡村医疗卫生机构的总额控制指标，年度新增医保基金重点向乡村医疗卫生机构倾斜，逐步提高县域内医保基金用于乡村医疗卫生机构的比例。医保报销目录中增设农村地区适宜卫生服务项目，逐步提高乡村医疗卫生机构服务性收入占比。\n（十八）优化农村医保管理服务。加强农村地区医保经办管理服务和监督管理能力建设，探索将村级医保服务纳入农村网格化服务管理。加强基层医保基金监管能力建设，把医保基金监管纳入乡镇政府综合监管体系，持续加大对骗保套保等违法违规行为的打击力度。","level":1},{"name":"六、加强组织领导","text":"（十九）压实工作责任。建立省级统筹、市负总责、县抓落实的工作机制，把乡村医疗卫生体系建设作为五级书记抓乡村振兴的重要内容，建立健全地方各级党委乡村医疗卫生工作领导体制机制，强化属地责任，纳入当地经济社会发展规划统筹部署，切实落实领导、投入保障、管理、监督责任。\n（二十）加强协同配合。各地要结合实际细化实化工作重点和政策措施。建立卫生健康、党委农村工作部门牵头，机构编制、发展改革、教育、财政、人力资源社会保障、自然资源、农业农村、乡村振兴、医保、疾控、中医药等部门和单位参与的工作推进机制，形成支持乡村医疗卫生体系建设的工作合力。加快村民委员会公共卫生委员会建设。注重发挥各级人大、政协监督作用。支持群团组织、社会组织等积极参与乡村医疗卫生事业发展。\n（二十一）强化考核督导。建立乡村医疗卫生体系健康发展督导评估机制，中央和省级层面加强对地方政府政策保障、人员队伍建设等重点任务进展情况的综合督导评估，并将其作为乡村振兴有关督查考核的重要内容。\n（二十二）营造良好氛围。建立健全乡村医疗卫生人员荣誉表彰制度。各类人才项目、荣誉表彰、评奖评优向乡村医疗卫生人员倾斜。加大对乡村医疗卫生人员中先进事迹的宣传力度，在全社会形成尊重乡村医疗卫生人员、关心乡村医疗卫生工作的良好氛围。\n延伸阅读\n健全适应乡村特点、优质高效的乡村医疗卫生体系——中央农办、国家卫生健康委负责人就《关于进一步深化改革促进乡村医疗卫生体系健康发展的意见》答记者问","level":1}]},{"id":"r0595","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于加强社会主义法治文化建设的意见》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于加强社会主义法治文化建设的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于加强社会主义法治文化建设的意见》全文如下。\n社会主义法治文化是中国特色社会主义文化的重要组成部分，是社会主义法治国家建设的重要支撑。为加强社会主义法治文化建设，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，深入学习宣传贯彻习近平法治思想和习近平总书记关于文化自信的重要论述，把建设社会主义法治文化作为建设中国特色社会主义法治体系、建设社会主义法治国家的战略性、基础性工作和建设社会主义文化强国的重要内容，切实提高全民族法治素养和道德素质，着力建设面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义法治文化，为全面依法治国提供坚强思想保证和强大精神动力，为全面建设社会主义现代化国家、实现中华民族伟大复兴的中国梦夯实法治基础。\n（二）工作原则\n——坚持党对全面依法治国的领导，牢固确立习近平法治思想在全面依法治国中的指导地位，确保社会主义法治文化建设的正确方向，增强“四个意识”、坚定“四个自信”、做到“两个维护”，坚定不移走中国特色社会主义法治道路。\n——坚持以人民为中心，做到社会主义法治文化建设为了人民、依靠人民，不断满足人民日益增长的对民主、法治、公平、正义的需要。\n——坚持法安天下、德润人心，把社会主义核心价值观融入社会主义法治文化建设全过程各方面，实现法治和德治相辅相成、相得益彰。\n——坚持知行合一、重在实践，引导全体人民成为社会主义法治的忠实崇尚者、自觉遵守者、坚定捍卫者。\n——坚持继承发展、守正创新，弘扬中华优秀传统文化、革命文化、社会主义先进文化，学习借鉴世界优秀法治文明成果，不断发展和繁荣社会主义法治文化。\n（三）总体目标。通过不懈努力，宪法法律权威进一步树立，尊法学法守法用法氛围日益浓厚，法治文化事业繁荣兴盛，法治文化人才队伍不断壮大，社会主义法治文化建设工作体制机制进一步完善。到2035年，基本形成与法治国家、法治政府、法治社会相适应，与中国特色社会主义法治体系相适应的社会主义法治文化，基本形成全社会办事依法、遇事找法、解决问题用法、化解矛盾靠法的法治环境。","level":1},{"name":"二、主要任务","text":"（四）深入学习宣传贯彻习近平法治思想。深化学习教育，抓好领导干部这个重点，把习近平法治思想作为党委（党组）理论学习中心组学习重点内容、党校（行政学院）和干部学院重点课程，不断深化思想认识、筑牢理论根基，提高领导干部运用法治思维和法治方式开展工作的本领。加强宣传解读，通过媒体报道、评论言论、理论文章、学习读本、短视频等形式，运用各类融媒体手段和平台，推动习近平法治思想深入人心。把习近平法治思想学习宣传同普法工作结合起来，同法治政府建设示范创建活动等结合起来，发挥好各类基层普法阵地的作用。把习近平法治思想融入学校教育，纳入高校法治理论教学体系，做好进教材、进课堂、进头脑工作。依托中国政法实务大讲堂，深入宣讲习近平法治思想。加强对法治领域错误思想观点的辨析批驳，帮助干部群众明辨是非，坚定走中国特色社会主义法治道路的信心。\n（五）完善中国特色社会主义法治理论。把马克思主义法治理论与中国具体实际相结合，不断推进马克思主义法治理论中国化时代化大众化。深刻认识，在新时代坚持和巩固马克思主义法治理论的指导地位，最重要的就是牢固确立习近平法治思想在全面依法治国中的指导地位。围绕习近平法治思想“十一个坚持”确立一批选题，组织法学专家和实践工作者深入研究，推出一批有分量的研究成果。加强对中国特色社会主义法律制度的理论研究，完善中国特色社会主义法治理论的学术体系、理论体系、话语体系。加强党内法规理论研究，强化依规治党学理支撑，推动全面从严治党向纵深发展。从我国国情和实际出发，研究回答法治中国建设中的重大问题，提炼标识性法学学术概念，凝练中国特色社会主义法律体系的特点和优势，促进法学研究成果推广和应用。加强中国特色新型法治智库建设，加大对重大法治理论、法治文化研究课题支持力度，加强法律实务部门和理论研究部门的交流互动，为法治实践提供高质量的决策参考。开展法治文化科研教学，支持有条件的单位自主设置法治文化相关二级学科硕士点、博士点。\n（六）大力弘扬宪法精神。深入持久开展宪法宣传教育，在全社会牢固树立宪法法律至上、法律面前人人平等、权由法定、权依法使等基本法治观念，维护宪法权威。落实国家工作人员宪法宣誓制度，组织好“12·4”国家宪法日、“宪法宣传周”系列宣传，推动宪法宣传教育常态化、制度化。抓住“关键少数”，把宪法纳入各级领导干部学法清单，作为领导干部学法基本任务、法治素养评估和年度述法基本内容，增强领导干部宪法意识，促进领导干部带头以宪法为根本活动准则，带头尊法学法守法用法，提高运用法治思维和法治方式深化改革、推动发展、化解矛盾、维护稳定、应对风险的能力。落实《青少年法治教育大纲》，把宪法纳入国民教育，融入校园文化，持续举办全国学生“学宪法讲宪法”、“宪法晨读”等系列活动，在青少年成人礼中设置礼敬宪法环节，增强青少年宪法观念。在“五四宪法”历史资料陈列馆基础上建设国家宪法宣传教育馆，建设各类宪法学习宣传教育基地，通过升国旗、奏唱国歌等仪式仪礼和开展重大节庆活动，增进全社会对宪法的尊崇和信仰。把宪法教育和爱国主义教育有机结合起来，以宪法教育激发爱国热情，增进各族群众对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的认同。\n（七）在法治实践中持续提升公民法治素养。注重公民法治习惯的实践养成，促进人民群众广泛参与法治，用科学立法、严格执法、公正司法的实践教育人民，推动全民守法。坚持科学立法，推进党的领导入法入规，把党的主张依照法定程序转化为国家意志，把社会主义核心价值观融入法律法规的立改废释全过程，使法律法规、司法解释等更好体现国家价值目标、社会价值取向和公民价值准则，以良法保障善治。坚持严格执法，强化严格规范公正文明执法意识，促进提高依法行政能力和水平。坚持公正司法，健全公正高效权威的司法制度，促进司法文明，努力让人民群众在每一个司法案件中感受到公平正义。坚持全民守法，让依法工作生活真正成为一种习惯，任何组织和个人都不得有超越宪法法律的特权。加大全民普法力度，在针对性和实效性上下功夫，落实“谁执法谁普法”普法责任制，加强以案普法、以案释法，发挥典型案例引领法治风尚、塑造社会主义核心价值观的积极作用，不断提升全体公民法治意识和法治素养。广泛开展民法典普法工作，让民法典走到群众身边、走进群众心里，大力弘扬平等自愿、诚实信用等法治精神，教育引导公民正确行使权利、积极履行义务。强化依法治理，从人民群众反映强烈的问题改起、从细节抓起、从小事做起，积极引导公民在日常生活中遵守交通规则、做好垃圾分类、杜绝餐饮浪费、革除滥食野生动物陋习等，培养规则意识，培育良好法治环境。在法治轨道上应对突发事件，依法加强应急管理，引导全社会依法行动、依法办事。突出学习宣传党章，深入开展党规党纪教育，教育引导广大党员做党章党规党纪和国家法律的自觉尊崇者、模范遵守者、坚定捍卫者。完善社会矛盾纠纷多元预防调处化解综合机制，把非诉讼纠纷解决机制挺在前面，引导人们理性平和协商解决矛盾纠纷。把法治文化建设纳入公民道德建设工程、社会信用体系建设中，推动完善市民公约、乡规民约、学生守则、行业规章、团体章程等社会规范。\n（八）推动中华优秀传统法律文化创造性转化、创新性发展。传承中华法系的优秀思想和理念，研究我国古代法制传统和成败得失，挖掘民为邦本、礼法并用、以和为贵、明德慎罚、执法如山等中华传统法律文化精华，根据时代精神加以转化，加强研究阐发、公共普及、传承运用，使中华优秀传统法律文化焕发出新的生命力。加强对我国法律文化历史遗迹的保护，弘扬代表性人物的事迹和精神，因地制宜建立基地，免费向社会开放。加强对法律文化典籍、文物的保护和整理，让书写在古籍里的文字活起来、传下去。挖掘善良风俗、家规家训中的优秀法治内容，倡导传承优良家风。\n（九）繁荣发展社会主义法治文艺。坚持以人民为中心的工作导向，把社会效益放在首位，创作生产与精神文明建设“五个一工程”等文艺精品工程有机衔接的优秀法治文艺作品。落实媒体公益普法责任，综合运用“报、网、端、微、屏”等资源和平台，推动法治融媒体建设，建立以内容建设为根本、先进技术为支撑、创新管理为保障的法治全媒体传播体系，创建法治品牌栏目、节目。推动法治文化数字化建设，以全国“智慧普法”平台为依托，组织开展法治动漫微视频征集展播活动，建立全国法治文艺精品库，汇聚优秀网络法治文艺作品，逐步实现共建共享。加大法治文化惠民力度，充分利用“三下乡”活动，组织丰富多彩的法治文艺下基层，在重大节庆日、法律法规实施日等时间节点，组织开展群众性法治文化活动。\n（十）加强社会主义法治文化阵地建设。把法治文化阵地建设纳入城乡规划，建好用好各种法治文化阵地，扩大覆盖面，提高利用率和群众参与度。加强法治宣传教育基地、法治文化创作基地、青少年法治教育实践基地等建设，完善建设标准，增强实用功能。注重发掘、研究、保护共和国红色法治文化，传承红色法治基因，建设一批以红色法治文化为主题的高质量法治宣传教育基地。把法治元素融入长城、大运河、长征、黄河等国家文化公园建设，融入国家重大文化建设项目，发挥示范带动作用。积极利用新时代文明实践中心（所、站）、爱国主义教育基地和公共文化机构等阵地，开展群众喜闻乐见的法治文化活动。加强对县（市、区、旗）、乡镇（街道）、村（社区）等区域治理法治状况的研究评估工作。以民主法治示范村（社区）等为基础，努力打造各具特色的法治文化体验线路，形成一批深受人民群众喜爱的区域性法治文化集群。推动法治文化与地方、行业特色文化有机融合，促进法治文化进机关、进农村、进社区、进企业、进学校、进军营、进网络等。加强基层单位法治文化形象塑造，建设法治“微景观”。着力提升市县法治文化阵地建设质量，推动从有形覆盖向有效覆盖转变。基本实现每个村（社区）至少有一个法治文化阵地，充分发挥其教育作用。\n（十一）加强法治文化国际交流。把建设社会主义法治文化作为提高国家文化软实力的重要途径，对外阐释构建人类命运共同体的法治内涵和法治主张。注重在共建“一带一路”中发挥法治文化作用，建立和完善相关纠纷解决机制和组织机构，推动沿线国家、地区开展法治文化交流合作。建立涉外工作法务制度，加快我国法域外适用的法律体系建设和研究，推动海外法律服务高质量发展，更好服务于海外法律纠纷解决和涉外法律工作，提高涉外工作法治化水平。把法治外宣作为国际传播能力建设的重要内容，善于讲述中国法治故事，展示我国法治国家的形象，不断提升社会主义法治文化影响力。举办法治国际论坛，开展与世界各国法治文化对话。","level":1},{"name":"三、组织保障","text":"（十二）加强组织领导。各级党委和政府要高度重视社会主义法治文化建设，加强领导、统一部署，把法治文化建设纳入法治建设总体规划，纳入公共文化服务体系。将法治文化作为优化营商环境的重要内容，作为法治示范创建、精神文明创建、平安中国建设等创建指标体系的重要内容。党政主要负责人要切实履行推进法治建设第一责任人职责，及时研究解决法治文化建设中的重要问题。完善优秀法治文化作品的鼓励支持政策，加大对法治文艺精品和法治文化基地的扶持力度，促进法治文化作品创作和传播。将法治文化建设所需经费列入本级预算，统筹利用好现有经费渠道，拓宽资金来源，鼓励社会资本参与法治文化建设。\n（十三）健全工作机制。建立健全党委统一领导、政府主导实施、部门分工负责、社会力量积极参与的社会主义法治文化建设工作机制。中央全面依法治国委员会办公室和各地全面依法治省（市、县）委员会办公室加强统筹协调，司法行政部门具体负责日常工作。党委宣传、网信、法院、检察院、教育、财政、文化和旅游等部门要发挥职能作用，积极推进法治文化建设。各部门要按照“谁主管谁负责”原则，加强本部门本行业本系统法治文化建设。各群团组织和社会组织要充分发挥作用，通过各种途径和形式参与法治文化建设。\n（十四）强化人才培养。坚持立德树人、德法兼修，实施法治文化人才教育培养计划，深入开展社会主义核心价值观和社会主义法治理念教育。加强法治文化专业队伍建设。完善普法讲师团服务管理，推动实现制度化规范化。健全法治文化志愿服务体系，提高志愿服务水平，推进志愿服务精准化、常态化、便利化、品牌化。加强法治报刊出版网络队伍建设，加强法治新闻采编创作人员法治培训。发展壮大法治文化理论研究力量，培育学科带头人。完善法治文化建设人才培养使用评价激励机制。\n（十五）培育推广典型。鼓励和支持各地区各部门根据实际情况大胆探索、勇于创新。加强培育法治文化建设先进典型，形成一批可复制可推广的好经验好做法。建立法治文化建设示范点，发挥引领示范作用。做好法治文化建设成果宣传和典型推广，形成良好氛围。","level":1}]},{"id":"r0596","sections":[{"name":"党的纪律检查机关案件审理工作条例","text":"第一章 总 则","level":1},{"name":"","text":"第一条 根据党章和《关于党内政治生活的若干准则》，结合案件审理工作的实践经验，制定本条例。\n第二条 案件审理工作，是对违犯党的纪律的案件的审核处理工作，是党的纪律检查工作的重要组成部分，是检查处理党员或党组织违犯党纪案件的重要环节。做好案件审理工作，对于正确地处理违犯党的纪律的案件，维护党的纪律的严肃性，端正党风；对于坚持四项基本原则，保证党的路线、方针、政策、决议的贯彻执行，促进社会主义物质文明和精神文明建设，有着积极的作用。\n第三条 审理党员或党组织违犯党的纪律的案件，必须坚持实事求是的原则。以事实为依据，重证据，不主观臆断，不带框框。对于处理错了的案件，一经发现，坚决改正。\n第四条 对犯错误的同志，必须坚持“惩前毖后，治病救人”的方针。对他们耐心地进行思想教育，根据其错误，恰当处理，既反对惩办主义，又不得姑息、迁就。\n第五条 处理党员或党组织违犯党的纪律的案件，必须坚持严肃慎重、区别对待的原则。违纪必究，严肃处理，不能含糊敷衍。但在处理的时候，必须慎重从事。对具体案件，要具体分析其错误事实、性质、情节和危害，根据不同情况，做不同处理。\n第六条 对于违犯党的纪律的党员，必须坚持在党的纪律面前人人平等的原则。不论其职位高低，贡献大小，资历长短，都要严肃查处，决不容许有不受党纪约束的特殊党员。\n第七条 对党员或党组织的处分，必须坚持民主集中制的原则，由党委或纪委集体讨论决定。不允许任何个人或少数人决定和批准对党员或党组织的处分。\n第八条 审查处理违犯党的纪律的案件的人员，需要回避的，经批准后实行回避。","level":0},{"name":"第二章 任务和职责范围","text":"第九条 案件审理工作的任务是：审查处理党员、党组织违犯党的纪律的案件和复查的案件。实事求是地核对违犯党的纪律的案件的事实材料，审核鉴别证据，根据党的政策和国家的法律法规，分析认定问题的性质，按照党章的规定和党对犯错误党员的一贯政策以及规定的程序，正确地处理违犯党的纪律的党员或党组织。\n第十条 职责范围：\n（一）审理按照批准权限由本级纪委或同级党委批准的违犯党的纪律的案件；\n（二）审理报送上级纪委或党委审批的案件；\n（三）审理下级纪委报的特别重要或复杂的案件；\n（四）审理下级纪委对同级党委处理案件的决定有不同意见请求予以复查或复议的案件；\n（五）审理下级纪委报来的备案案件；\n（六）审理领导同志交办的其他案件；\n（七）受理本级党委、纪委及上级党委、纪委批准的案件中党员对所受处分或结论不服的申诉；\n（八）调查研究案件审理工作和执行党纪的情况，拟定有关案件审理工作规范化的规定，对下级纪委的审理工作进行业务指导；\n（九）为进行党性、党风、党纪教育选择典型案例。","level":1},{"name":"第三章 审理案件的基本要求","text":"第十一条 事实清楚\n事实是定案的基础。审理案件，必须将错误事实发生的时间、地点、情节、后果、本人应负的责任，以及产生错误的主客观原因等，审核清楚。如发现事实不清，要责成或协同原报案单位重新查证清楚，要使所认定的错误事实符合客观实际。\n第十二条 证据确凿\n证据是判断事实的依据。对证据必须认真地进行鉴别，去伪存真。认定错误的事实，一定要有充分的证据。没有证据或证据不充分、不确凿，不能认定。证据充分确凿，即使犯错误的人拒不承认，也可以认定。\n第十三条 定性准确\n认定问题的性质，必须在事实清楚、证据确凿的基础上，以党章、《关于党内政治生活的若干准则》、党的方针政策和国家的法律法规为准绳，进行具体分析，是什么性质的问题就定什么性质。性质难以确定的，用写实的办法作出结论。\n第十四条 处理恰当\n在事实清楚、证据确凿、定性准确的基础上，作出恰当处理。既不要处理过头，又不要姑息迁就。\n在任何情况下都不得株连无辜。\n第十五条 手续完备\n处理案件要严格按照党章规定的手续办理，按照处分党员或党组织的批准权限审批。手续不完备的，原报案单位必须补办。\n报请审批的案件，须报以下材料：\n（1）处分决定；\n（2）错误事实调查报告和主要证据材料；\n（3）本人检查材料和对处分决定的意见以及党组织对本人意见的说明；\n（4）党的纪律检查委员会或党组织的审查意见。\n复查的案件须报：复查或复议报告和主要证据材料；处理决定及有关党组织的意见；本人意见和党组织对本人不同意见的说明；原处分决定和原定案的主要证据材料。","level":1}]},{"id":"r0597","sections":[{"name":"中共中央 国务院关于2023年度国家科学技术奖励的决定","text":"中共中央 国务院关于2023年度国家科学技术奖励的决定\n（2024年6月24日）","level":1},{"name":"","text":"中国式现代化关键在科技现代化，全面建成社会主义现代化强国关键看科技自立自强。党的十八大以来，以习近平同志为核心的党中央坚持把科技创新摆在国家发展全局的核心位置，健全新型举国体制，加快推进高水平科技自立自强，我国科技事业取得历史性成就、发生历史性变革，进入创新型国家行列。广大科技工作者奋力投身科技创新，不断取得新成果、实现新突破，为中国式现代化建设提供了坚实支撑。\n为深入贯彻习近平新时代中国特色社会主义思想和党的二十大精神，深入实施科教兴国战略、人才强国战略、创新驱动发展战略，中共中央、国务院决定，对为我国科学技术进步、经济社会发展、国防现代化建设作出突出贡献的科学技术人员和组织给予奖励。\n根据《国家功勋荣誉表彰条例》、《国家科学技术奖励条例》的规定，经国家科学技术奖励评审委员会评审、国家科学技术奖励委员会审定和科技部审核，党中央、国务院批准并报请国家主席习近平签署，授予李德仁院士、薛其坤院士国家最高科学技术奖；党中央、国务院批准，授予“拓扑电子材料计算预测”国家自然科学奖一等奖，授予“三维流形的有限复叠”等48项科技成果国家自然科学奖二等奖，授予“集成电路化学机械抛光关键技术与装备”等8项科技成果国家技术发明奖一等奖，授予“绿色生物基材料包膜控释肥创制与应用”等54项科技成果国家技术发明奖二等奖，授予“复兴号高速列车”等3项科技成果国家科学技术进步奖特等奖，授予“‘深海一号’超深水大气田开发工程关键技术与应用”等16项科技成果国家科学技术进步奖一等奖，授予“耐寒抗风高产橡胶树品种培育及其应用”等120项科技成果国家科学技术进步奖二等奖，授予约翰·爱德华·霍普克罗夫特教授等10名外国专家中华人民共和国国际科学技术合作奖。\n党中央号召，全国科技工作者要向国家最高科学技术奖获奖者及全体获奖人员学习，更加紧密团结在以习近平同志为核心的党中央周围，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，锚定科技强国建设目标，坚持“四个面向”，大力弘扬爱国、创新、求实、奉献、协同、育人的科学家精神，加强基础研究和应用基础研究，打好关键核心技术攻坚战，加快实现高水平科技自立自强，以科技创新支撑高质量发展、保障高水平安全，培育发展新质生产力，为以中国式现代化全面推进强国建设、民族复兴伟业作出新的更大贡献。","level":0}]},{"id":"r0598","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于进一步加强财会监督工作的意见》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于进一步加强财会监督工作的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于进一步加强财会监督工作的意见》全文如下。\n财会监督是依法依规对国家机关、企事业单位、其他组织和个人的财政、财务、会计活动实施的监督。近年来，财会监督作为党和国家监督体系的重要组成部分，在推进全面从严治党、维护中央政令畅通、规范财经秩序、促进经济社会健康发展等方面发挥了重要作用，同时也存在监督体系尚待完善、工作机制有待理顺、法治建设亟待健全、监督能力有待提升、一些领域财经纪律亟需整治等问题。为进一步加强财会监督工作，更好发挥财会监督职能作用，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大精神，完整、准确、全面贯彻新发展理念，加快构建新发展格局，着力推动高质量发展，更好统筹发展和安全，坚持以完善党和国家监督体系为出发点，以党内监督为主导，突出政治属性，严肃财经纪律，健全财会监督体系，完善工作机制，提升财会监督效能，促进财会监督与其他各类监督贯通协调，推动健全党统一领导、全面覆盖、权威高效的监督体系。\n（二）工作要求\n——坚持党的领导，发挥政治优势。坚持加强党的全面领导和党中央集中统一领导，把党的领导落实到财会监督全过程各方面，确保党中央、国务院重大决策部署有效贯彻落实。\n——坚持依法监督，强化法治思维。按照全面依法治国要求，健全财经领域法律法规和政策制度，加快补齐法治建设短板，依法依规开展监督，严格执法、严肃问责。\n——坚持问题导向，分类精准施策。针对重点领域多发、高发、易发问题和突出矛盾，分类别、分阶段精准施策，强化对公权力运行的制约和监督，建立长效机制，提升监督效能。\n——坚持协同联动，加强贯通协调。按照统筹协同、分级负责、上下联动的要求，健全财会监督体系，构建高效衔接、运转有序的工作机制，与其他各类监督有机贯通、相互协调，形成全方位、多层次、立体化的财会监督工作格局。\n（三）主要目标。到2025年，构建起财政部门主责监督、有关部门依责监督、各单位内部监督、相关中介机构执业监督、行业协会自律监督的财会监督体系；基本建立起各类监督主体横向协同，中央与地方纵向联动，财会监督与其他各类监督贯通协调的工作机制；财会监督法律制度更加健全，信息化水平明显提高，监督队伍素质不断提升，在规范财政财务管理、提高会计信息质量、维护财经纪律和市场经济秩序等方面发挥重要保障作用。","level":1},{"name":"二、进一步健全财会监督体系","text":"（四）加强党对财会监督工作的领导。各级党委要加强对财会监督工作的领导，保障党中央决策部署落实到位，统筹推动各项工作有序有效开展。各级政府要建立财会监督协调工作机制，明确工作任务、健全机制、完善制度，加强对下级财会监督工作的督促和指导。\n（五）依法履行财会监督主责。各级财政部门是本级财会监督的主责部门，牵头组织对财政、财务、会计管理法律法规及规章制度执行情况的监督。加强预算管理监督，推动构建完善综合统筹、规范透明、约束有力、讲求绩效、持续安全的现代预算制度，推进全面实施预算绩效管理。加强对行政事业性国有资产管理规章制度、政府采购制度实施情况的监督，保障国有资产安全完整，规范政府采购行为。加强对财务管理、内部控制的监督，督促指导相关单位规范财务管理，提升内部管理水平。加强对会计行为的监督，提高会计信息质量。加强对注册会计师、资产评估和代理记账行业执业质量的监督，规范行业秩序，促进行业健康发展。\n（六）依照法定职责实施部门监督。有关部门要依法依规强化对主管、监管行业系统和单位财会监督工作的督促指导。加强对所属单位预算执行的监督，强化预算约束。按照职责分工加强对政府采购活动、资产评估行业的监督，提高政府采购资金使用效益，推动资产评估行业高质量发展。加强对归口财务管理单位财务活动的指导和监督，严格财务管理。按照会计法赋予的职权对有关单位的会计资料实施监督，规范会计行为。\n（七）进一步加强单位内部监督。各单位要加强对本单位经济业务、财务管理、会计行为的日常监督。结合自身实际建立权责清晰、约束有力的内部财会监督机制和内部控制体系，明确内部监督的主体、范围、程序、权责等，落实单位内部财会监督主体责任。各单位主要负责人是本单位财会监督工作第一责任人，对本单位财会工作和财会资料的真实性、完整性负责。单位内部应明确承担财会监督职责的机构或人员，负责本单位经济业务、财会行为和会计资料的日常监督检查。财会人员要加强自我约束，遵守职业道德，拒绝办理或按照职权纠正违反法律法规规定的财会事项，有权检举单位或个人的违法违规行为。\n（八）发挥中介机构执业监督作用。会计师事务所、资产评估机构、税务师事务所、代理记账机构等中介机构要严格依法履行审计鉴证、资产评估、税收服务、会计服务等职责，确保独立、客观、公正、规范执业。切实加强对执业质量的把控，完善内部控制制度，建立内部风险防控机制，加强风险分类防控，提升内部管理水平，规范承揽和开展业务，建立健全事前评估、事中跟踪、事后评价管理体系，强化质量管理责任。持续提升中介机构一体化管理水平，实现人员调配、财务安排、业务承接、技术标准、信息化建设的实质性一体化管理。\n（九）强化行业协会自律监督作用。注册会计师协会、资产评估协会、注册税务师协会、银行业协会、证券业协会等要充分发挥督促引导作用，促进持续提升财会信息质量和内部控制有效性。加强行业诚信建设，健全行业诚信档案，把诚信建设要求贯穿行业管理和服务工作各环节。进一步加强行业自律监管，运用信用记录、警示告诫、公开曝光等措施加大惩戒力度，完善对投诉举报、媒体质疑等的处理机制，推动提升财会业务规范化水平。","level":1},{"name":"三、完善财会监督工作机制","text":"（十）加强财会监督主体横向协同。构建财政部门、有关部门、各单位、中介机构、行业协会等监督主体横向协同工作机制。各级财政部门牵头负责本级政府财会监督协调工作机制日常工作，加强沟通协调，抓好统筹谋划和督促指导；税务、人民银行、国有资产监管、银行保险监管、证券监管等部门积极配合、密切协同。建立健全部门间财会监督政策衔接、重大问题处理、综合执法检查、监督结果运用、监督线索移送、监督信息交流等工作机制，形成监督合力，提升监督效能。建立部门与行业协会联合监管机制，推动行政监管与自律监管有机结合。相关中介机构要严格按照法律法规、准则制度进行执业，并在配合财会监督执法中提供专业意见。中介机构及其从业人员对发现的违法违规行为，应及时向主管部门、监管部门和行业协会报告。各单位应配合依法依规实施财会监督，不得拒绝、阻挠、拖延，不得提供虚假或者有重大遗漏的财会资料及信息。\n（十一）强化中央与地方纵向联动。压实各有关方面财会监督责任，加强上下联动。国务院财政部门加强财会监督工作的制度建设和统筹协调，牵头组织制定财会监督工作规划，明确年度监督工作重点，指导推动各地区各部门各单位组织实施。县级以上地方政府和有关部门依法依规组织开展本行政区域内财会监督工作。国务院有关部门派出机构依照法律法规规定和上级部门授权实施监督工作。地方各级政府和有关部门要畅通财会监督信息渠道，建立财会监督重大事项报告机制，及时向上一级政府和有关部门反映财会监督中发现的重大问题。\n（十二）推动财会监督与其他各类监督贯通协调。建立健全信息沟通、线索移送、协同监督、成果共享等工作机制。开展财会监督要自觉以党内监督为主导，探索深化贯通协调有效路径，加强与巡视巡察机构协作，建立重点监督协同、重大事项会商、线索移交移送机制，通报财会监督检查情况，研究办理巡视巡察移交的建议；加强与纪检监察机关的贯通协调，完善财会监督与纪检监察监督在贯彻落实中央八项规定精神、纠治“四风”、整治群众身边腐败和不正之风等方面要求贯通协调机制，加强监督成果共享，发现党员、监察对象涉嫌违纪或职务违法、职务犯罪的问题线索，依法依规及时移送纪检监察机关；发挥财会监督专业力量作用，选派财会业务骨干参加巡视巡察、纪委监委监督检查和审查调查。强化与人大监督、民主监督的配合协同，完善与人大监督在提高预算管理规范性、有效性等方面贯通协调机制。增强与行政监督、司法监督、审计监督、统计监督的协同性和联动性，加强信息共享，推动建立健全长效机制，形成监督合力。畅通群众监督、舆论监督渠道，健全财会监督投诉举报受理机制，完善受理、查处、跟踪、整改等制度。","level":1},{"name":"四、加大重点领域财会监督力度","text":"（十三）保障党中央、国务院重大决策部署贯彻落实。把推动党中央、国务院重大决策部署贯彻落实作为财会监督工作的首要任务。聚焦深化供给侧结构性改革，做好稳增长、稳就业、稳物价工作，保障和改善民生，防止资本无序扩张，落实财政改革举措等重大部署，综合运用检查核查、评估评价、监测监控、调查研究等方式开展财会监督，严肃查处财经领域违反中央宏观决策和治理调控要求、影响经济社会健康稳定发展的违纪违规行为，确保党中央政令畅通。\n（十四）强化财经纪律刚性约束。加强对财经领域公权力行使的制约和监督，严肃财经纪律。聚焦贯彻落实减税降费、党政机关过紧日子、加强基层保基本民生保工资保运转工作、规范国库管理、加强资产管理、防范债务风险等重点任务，严肃查处财政收入不真实不合规、违规兴建楼堂馆所、乱设财政专户、违规处置资产、违规新增地方政府隐性债务等突出问题，强化通报问责和处理处罚，使纪律真正成为带电的“高压线”。\n（十五）严厉打击财务会计违法违规行为。坚持“强穿透、堵漏洞、用重典、正风气”，从严从重查处影响恶劣的财务舞弊、会计造假案件，强化对相关责任人的追责问责。加强对国有企业、上市公司、金融企业等的财务、会计行为的监督，严肃查处财务数据造假、出具“阴阳报告”、内部监督失效等突出问题。加强对会计信息质量的监督，依法严厉打击伪造会计账簿、虚构经济业务、滥用会计准则等会计违法违规行为，持续提升会计信息质量。加强对会计师事务所、资产评估机构、代理记账机构等中介机构执业质量监督，聚焦行业突出问题，加大对无证经营、挂名执业、违规提供报告、超出胜任能力执业等违法违规行为的整治力度，强化行业日常监管和信用管理，坚决清除害群之马。","level":1},{"name":"五、保障措施","text":"（十六）加强组织领导。各地区各有关部门要强化组织领导，加强协同配合，结合实际制定具体实施方案，确保各项工作任务落地见效。将财会监督工作推进情况作为领导班子和有关领导干部考核的重要内容；对于贯彻落实财会监督决策部署不力、职责履行不到位的，要严肃追责问责。\n（十七）推进财会监督法治建设。健全财会监督法律法规制度，及时推动修订预算法、会计法、注册会计师法、资产评估法、财政违法行为处罚处分条例等法律法规。健全财政财务管理、资产管理等制度，完善内部控制制度体系。深化政府会计改革，完善企业会计准则体系和非营利组织会计制度，增强会计准则制度执行效果。\n（十八）加强财会监督队伍建设。县级以上财政部门应强化财会监督队伍和能力建设。各单位应配备与财会监督职能任务相匹配的人员力量，完善财会监督人才政策体系，加强财会监督人才培训教育，分类型、分领域建立高层次财会监督人才库，提升专业能力和综合素质。按照国家有关规定完善财会监督人才激励约束机制。\n（十九）统筹推进财会监督信息化建设。深化“互联网+监督”，充分运用大数据和信息化手段，切实提升监管效能。依托全国一体化在线政务服务平台，统筹整合各地区各部门各单位有关公共数据资源，分级分类完善财会监督数据库，推进财会监督数据汇聚融合和共享共用。构建财会领域重大风险识别预警机制。\n（二十）提升财会监督工作成效。优化监督模式与方式方法，推动日常监督与专项监督、现场监督与非现场监督、线上监督与线下监督、事前事中事后监督相结合，实现监督和管理有机统一。加大对违法违规行为的处理处罚力度，大幅提高违法违规成本，推动实施联合惩戒，依法依规开展追责问责。加强财会监督结果运用，完善监督结果公告公示制度，对违反财经纪律的单位和人员，加大公开曝光力度，属于党员和公职人员的，及时向所在党组织、所在单位通报，发挥警示教育作用。\n（二十一）加强宣传引导。加强财会监督法律法规政策宣传贯彻，强化财会从业人员执业操守教育。在依法合规、安全保密等前提下，大力推进财会信息公开工作，提高财会信息透明度。鼓励先行先试，强化引领示范，统筹抓好财会监督试点工作。加强宣传解读和舆论引导，积极回应社会关切，充分调动各方面积极性，营造财会监督工作良好环境。\n延伸阅读\n健全财会监督体制机制 提升财会监督效能——财政部负责人就《关于进一步加强财会监督工作的意见》答记者问","level":1}]},{"id":"r0599","sections":[{"name":"中共中央办公厅 国务院办公厅印发《深化集体林权制度改革方案》","text":"近日，中共中央办公厅、国务院办公厅印发《深化集体林权制度改革方案》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《深化集体林权制度改革方案》全文如下。\n集体林是提升碳汇能力的重要载体，是维护生态安全的重要基础，是实现乡村振兴的重要资源。集体林权制度改革对于巩固和完善农村基本经营制度、促进农民就业增收、建设生态文明、推动绿色发展具有重要意义。为深化集体林权制度改革，巩固和拓展改革成果，制定本方案。","level":0},{"name":"一、总体要求","text":"深化集体林权制度改革，要以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大精神，全面贯彻习近平生态文明思想，牢固树立和践行绿水青山就是金山银山理念，积极稳妥推进集体林权制度创新，依法保护农民和林业经营者的集体林权益，增强生态保护和林业发展内生动力，不断完善生态产品价值实现机制和生态补偿制度，充分发挥森林多种功能，推动林业高质量发展，推进农民农村共同富裕，促进人与自然和谐共生，努力实现生态美、百姓富的有机统一。\n——坚持改革方向，稳步深化探索。确保集体林地承包关系长期稳定，放活林地经营权、保障林木所有权。尊重群众首创精神，及时总结提炼经验做法，分区分类施策，突出问题导向，坚持底线思维，不搞一刀切、强迫命令，确保改革始终沿着正确方向前进。\n——坚持生态优先、绿色发展。把保护生态放在首位，推进森林资源节约集约循环利用，统筹保护与发展，科学开展森林经营，提高森林质量，增加生态产品供给，提升森林生态效益、经济效益、社会效益。\n——坚持尊重农民意愿，保护农民权益。充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，实施一批发展所需、基层所盼、民心所向的改革举措，让群众有更多的获得感、幸福感、安全感。\n到2025年，基本形成权属清晰、责权利统一、保护严格、流转有序、监管有效的集体林权制度。在此基础上，通过继续深化改革，进一步发展林业适度规模经营，推动森林经营更加科学高效、支持保护制度更加完善、林权价值增值途径更加多样，不断促进森林资源持续增长、森林生态质量持续提高、林区发展条件持续改善、农民收入持续增加。","level":1},{"name":"二、主要任务","text":"（一）加快推进“三权分置”。实行集体林地所有权、承包权、经营权“三权分置”。落实所有权，坚持集体林地所有权不变，维护农民集体对承包林地发包、调整、监督等各项权能。稳定承包权，保持集体林地承包关系稳定并长久不变，承包期届满时应坚持延包原则，不得将承包林地打乱重分，确保绝大多数农户原有承包林地继续保持稳定。保障进城落户农民合法林地权益，鼓励依法自愿有偿转让。开展集体林地延包试点，家庭承包林地剩余期限10年以内的，发包方可以依法提前确认延包合同，以林地承包到期为起点起算并合理确定延包期限。放活经营权，林地经营权可以依法再流转或者依法向金融机构融资担保。林地经营权合同终止时，要保障林地经营权人的林木财产权益，鼓励林地受让方以公允价格受让林木所有权，维持林业正常生产经营活动。流转期限5年以上的林地经营权可以向不动产登记机构申请登记发证，可以作为林权抵押贷款、申报林业项目、申请林木采伐及其他有关行政管理事项的凭证。\n（二）发展林业适度规模经营。鼓励各地采取措施，引导农户通过出租、入股、合作等方式流转林地经营权。支持小农户通过多种形式联合开展生产，推广家庭联合经营、农村集体经济组织与农户股份合作经营、农户委托经营模式。发挥各类社会化服务组织带动小农户作用，完善小农户利益联结机制，促进小农户和现代林业发展有机衔接。对仍由农村集体经济组织统一经营管理的林地，将集体林地收益权量化到户，收益权证发放到户。支持各地组建林权收储机构，采取市场化方式收储分散林权。鼓励探索林权资产折资量化的林票运行机制，增强森林资源资产对社会资本的吸引力。各地要依托现有平台搭建林权流转交易系统，建立社会资本投资林权的渠道。鼓励各类企业参与林业投资经营，加强对社会资本投资林业的全过程监督，建立健全联农带农机制。鼓励各地采取改善林业生产经营条件、购买社会化服务、补助林权收储担保费用等措施培育林业规模经营主体。支持分区分类探索国有林场经营性收入分配激励机制，引导国有林场与农村集体经济组织和农户联合经营，促进集体林经营水平提升。完善林权流转纠纷调处机制，将集体林地承包经营纠纷调处纳入平安中国建设考评体系。\n（三）切实加强森林经营。从保障农民合法权益出发，依法依规科学划定公益林和天然林范围，不得随意扩大范围。合理优化公益林中集体林的比例，适当考虑将森林生态区位不重要或者生态状况不脆弱的集体林地依法调出公益林范围，经国务院和省（自治区、直辖市）政府同意，并予以公布。县级林草主管部门要探索建立以森林经营方案为基础的管理制度，支持和引导规模经营主体单独编制森林经营方案，将森林经营方案作为审批林木采伐、安排林业项目等行政管理事项的重要依据。实施森林质量精准提升工程，推广森林高效经营模式，采取林分改造、森林抚育、优化林种树种结构等措施，提升生态系统多样性、稳定性、持续性。鼓励各地结合实际探索差异化森林经营补助政策，重点支持中幼林抚育。推行全周期森林经营，通过采伐更新、抚育复壮、择伐补造等措施，加快低产低效林和成过熟林改造更新。\n（四）保障林木所有权权能。对林业经营者实行林木采伐限额5年总额控制政策，取消人工商品林主伐年龄限制，明确人工公益林更新条件，实施林木采伐告知承诺方式审批，将林木采伐限额指标分配、林木采伐许可申请和审批及采伐监管情况纳入政府公开事项目录清单。强化对森林经营方案和告知承诺执行情况的监管，地方政府要用好用足林木采伐限额，将依法采伐的木材纳入地方政府森林资源保护发展目标责任制，满足森林经营中合理的林木采伐需求。不得以各种名义禁止或限制合法的林木采伐行为，确需禁止或限制的，应依法对权利人给予经济补偿。\n（五）积极支持产业发展。加强木本粮油、木材、竹材、森林药材等重要初级林产品供给能力建设，鼓励林业大省、大市、大县培育林业支柱产业。实施兴林富民行动，农业农村产业发展、地区振兴、绿色经济和循环经济发展等政策要形成合力，支持集体林业大县发展林业产业，实施一批以工代赈项目，提升一批现代产业园区，扶持一批专精特新林业企业。在保护森林资源和生态的前提下，可依法利用公益林的林下资源、林间空地、林缘林地等，适度发展林下经济、生态旅游、森林康养、自然教育等绿色富民产业，严禁变相搞别墅、高尔夫球场等违法违规行为，并加强林区的历史文化遗产保护。通过政府采购积极推广应用木竹结构建筑和木竹建材。建立森林生态产品标志管理和产品追溯体系，创建区域林业特色品牌。鼓励各地举办森林生态产品推介活动，提供市场营销服务。结合农村公益性基础设施建设和相关行业发展规划实施，支持林业产业路、旅游路、资源路等集体林基础设施建设。推动将一批用于林业生产的先进适用机械按程序列入农机购置与应用补贴机具种类范围。\n（六）探索完善生态产品价值实现机制。建立健全林业碳汇计量监测体系，形成林业碳汇核算基准线和方法学。支持符合条件的林业碳汇项目开发为温室气体自愿减排项目并参与市场交易，建立健全能够体现碳汇价值的生态保护补偿机制。探索实施林业碳票制度，制定林业碳汇管理办法，鼓励碳排放企业、大型活动组织者、社会公众等通过购买林业碳汇履行社会责任。健全森林生态效益补偿机制，统一天然林管护和国家级公益林补偿政策。鼓励各地结合生态保护贡献、生态区位重要程度、森林管护难度等因素探索实行差异化补偿。实行公益林、商品林分类经营管理，明确分级保护、差异化利用措施，保障权利人权益，促进林权价值增值。鼓励地方通过租赁、赎买、合作等方式妥善处置重要生态区位内的集体林，维护权利人的合法权益。\n（七）加大金融支持力度。充分发挥绿色金融引领作用，研究将符合条件的林权交易服务、林产品精深加工等纳入绿色金融支持范围，加大金融支持力度。完善绿色贷款统计。鼓励和引导金融机构结合职能定位和业务范围，加大对林业贷款的支持力度。将林权抵押贷款和林业经营主体贷款纳入金融机构服务乡村振兴考核评估范畴，强化激励约束。商业银行林权抵押贷款不良率高出自身各项贷款不良率3个百分点（含）以内的，可不作为监管部门监管评级和银行内部考核评价的扣分因素。健全抵押林权快速处置机制，引导金融机构按市场化原则加大对林权抵押贷款的支持力度，提高林权抵押率。加强林权收储担保业务监管，发挥林权收储机构经营林权资产的专业优势，鼓励社会资本开展林权收储担保服务。探索基于碳汇权益的绿色信贷产品，符合条件的可纳入碳减排支持工具范围，支持符合条件的发行人发行乡村振兴票据或以林权作为担保发行债券。支持保险机构创新开发各类林业保险产品，鼓励地方政府将林业保险产品纳入地方优势特色农产品保险奖补政策范围。鼓励各地完善承保机构市场竞争机制，提升服务质效。\n（八）妥善解决历史遗留问题。基于第三次全国国土调查统一底图，加快推进林权登记存量数据整合移交，纳入不动产登记信息平台管理，妥善解决集体林地类重叠、权属交叉等问题。开展集体林权首次登记的，相关经费纳入地方财政预算。发挥村组作用，在承包合同签订前，开展地籍调查工作。已登记的整宗林地申请变更、转移、抵押登记的，不得要求申请人重新提交林权地籍调查成果。因原林权登记成果图件缺失、界址不清，确需要开展补充调查的，由政府组织开展地籍调查。推动不动产登记信息平台与林权综合监管平台有效对接，实现林权审批、交易和登记信息实时互通共享。改革自留山使用制度，赋予农民更加充分的财产权益，探索将其林地长期使用权分为使用权和经营权，赋予经营权流转和融资担保权能，完善其继承和自愿有偿退出政策。","level":1},{"name":"三、保障措施","text":"（九）加强组织领导。地方各级党委和政府要高度重视深化集体林权制度改革，将其纳入林长制工作范围，实行主要领导负责制，及时解决遇到的矛盾和问题，总结推广典型经验和做法。各省（自治区、直辖市）要结合实际加快制定实施方案，明确责任、细化任务，对工作不力的依规依纪依法追究责任，确保改革落地见效。市县两级原则上不制定配套文件。国家林草局负责协调推进本方案提出的各项任务措施，有关部门要加强沟通、密切配合，形成工作合力。凡涉及调整现行法律或行政法规的，按照有关程序经全国人大及其常委会或国务院授权后实施。\n（十）支持先行探索。支持福建、江西、重庆建设深化集体林权制度改革先行区，充分发挥引领作用，为全国深化集体林权制度改革提供可复制可推广的经验和模式。鼓励各地结合自身实际积极深化集体林权制度改革，在种树农民收益保障机制、集体林业大县利益补偿机制、发展林业规模经营、林权价值增值途径、林权投融资机制、林业财产权益保护制度、林业产业发展、集体林经营管理制度和社会化服务等方面探索一批有效的经验做法。加强跟踪指导，对出现偏差和以各种名义进行不当开发的行为，及时予以制止和纠偏。\n（十一）加强队伍建设。地方各级党委和政府要依法明确林草主管部门职责，统筹使用编制资源，适当增加专业技术岗位。强化林草主管部门行政执法职责，推动人员编制向执法一线倾斜。集体林业大县要切实加强基层林业工作力量，乡镇政府要明确相关机构承担林业工作。森林公安由公安机关直接领导管理，职能保持不变，基层森林公安队伍框架和力量布局保持基本稳定。实施生态护林员能力提升行动，增强生态护林员辅助服务的能力。\n（十二）强化考核评价。国家林草局和省级林草主管部门要建立客观反映深化集体林权制度改革成效的评价指标体系，并将评价结果纳入林长制督查考核范围，重大事项及时向党中央、国务院请示报告。","level":1}]},{"id":"r0600","sections":[{"name":"关于在深化国有企业改革中坚持党的领导加强党的建设的若干意见","text":"点击此处观看视频","level":1},{"name":"","text":"近日，中共中央办公厅印发了《关于在深化国有企业改革中坚持党的领导加强党的建设的若干意见》（以下简称《若干意见》），对在深化国有企业改革中坚持党的领导、加强党的建设提出要求、作出部署。\n坚持党的领导，是中国特色社会主义最本质的特征，也是国有企业的独特优势。在协调推进“四个全面”战略布局的伟大进程中，必须毫不动摇坚持党对国有企业的领导，毫不动摇加强国有企业党的建设。出台《若干意见》，对于加强国有企业党的建设，保证国有企业改革发展的社会主义方向，提升国有企业的制度优势和竞争优势，促进国有企业做强做优做大，具有十分重要的战略意义和现实意义。\n《若干意见》指出，坚持党的建设与国有企业改革同步谋划，充分发挥党组领导核心作用、党委政治核心作用、基层党组织战斗堡垒作用和党员先锋模范作用；坚持党管干部原则，从严选拔国有企业领导人员，建立适应现代企业制度要求和市场竞争需要的选人用人机制；严格落实国有企业党建工作责任制，切实履行党风廉政建设主体责任和监督责任；把加强党的领导和完善公司治理统一起来，明确国有企业党组织在公司法人治理结构中的法定地位；坚持从严教育管理国有企业领导人员，强化对国有企业领导人员特别是主要领导履职行权的监督；适应国有资本授权经营体制改革需要，加强对国有资本投资、运营公司的领导；把建立党的组织、开展党的工作，作为国有企业推进混合所有制改革的必要前提。\n当前，国有企业改革正处于攻坚期和深水区，党的领导只能加强，不能削弱。《若干意见》强调，各地区各有关部门党委（党组）和各国有企业党组（党委）要切实加强对国有企业党建工作的领导和指导，不断完善党委（党组）抓、书记抓、各有关部门抓，一级抓一级、层层抓落实的党建工作格局，确保党的领导、党的建设在国有企业改革中得到充分体现和切实加强。\n延伸阅读\n中央组织部负责人就《关于在深化国有企业改革中坚持党的领导加强党的建设的若干意见》答记者问","level":0}]},{"id":"r0601","sections":[{"name":"关于人大预算审查监督重点向支出预算和政策拓展的指导意见","text":"近日，中共中央办公厅印发了《关于人大预算审查监督重点向支出预算和政策拓展的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于人大预算审查监督重点向支出预算和政策拓展的指导意见》全文如下。\n为贯彻落实党的十八届三中全会关于加强人大预算决算审查监督职能的要求，实现人大预算审查监督重点向支出预算和政策拓展，根据党中央决策部署和预算法、监督法等法律规定，现提出如下指导意见。","level":0},{"name":"一、重要意义","text":"审查批准预算、决算和监督预算执行是宪法和预算法、监督法等法律赋予全国人大及其常委会、地方各级人大及其常委会的重要职权。人大依法开展预算审查监督，对规范预算行为、促进依法行政、推动经济社会发展，发挥了重要作用。同时也要看到，过去政府预算审核管理和人大预算审查监督的重点主要是赤字规模和预算收支平衡状况，对支出预算和政策关注不够，对财政资金使用绩效和政策实施效果关注不够，不利于发挥政策对编制支出预算的指导和约束作用，不利于提高人大预算审查监督的针对性和有效性。\n党的十八大以来，以习近平同志为核心的党中央就人大制度和人大工作提出一系列新论断新举措新要求，为在新的历史条件下坚持、完善、发展人民代表大会制度，加强和改进人大预算审查监督工作，提供了科学理论指导和行动指南。实施人大预算审查监督重点向支出预算和政策拓展，是依法加强和改进人大预算审查监督工作的内在要求，是建立和完善中国特色社会主义预算审查监督制度的重要举措，是提高财政资金使用绩效和政策实施效果的客观需要，也是对预算法、监督法关于人大预算决算审查监督特别是支出预算和政策审查监督规定的细化深化。人大加强对支出预算和政策的审查监督，有利于强化政策对支出预算的指导和约束作用，使预算安排和政策更好地贯彻落实党中央重大方针政策和决策部署；有利于加强和改善宏观调控，有效发挥财政在宏观经济管理中的重要作用；有利于提高支出预算编制质量和预算执行规范化水平，实施全面规范、公开透明的预算制度；有利于加强对政府预算的全口径审查和全过程监管，更好发挥财政在国家治理中的基础和重要支柱作用，更好发挥人民代表大会制度支撑国家治理体系和治理能力的根本政治制度作用。","level":1},{"name":"二、总体要求","text":"全国人大及其常委会、地方各级人大及其常委会在开展预算审查监督重点向支出预算和政策拓展工作中，要深入学习贯彻党的十九大精神，以习近平新时代中国特色社会主义思想为指导，坚持党的领导、人民当家作主、依法治国有机统一，以宪法和预算法、监督法等法律为依据，坚持正确监督、有效监督，加强对支出预算和政策的审查监督，提高针对性和有效性，推进依法行政、依法理财，保障党中央重大方针政策和决策部署的贯彻落实。\n1.坚持党中央集中统一领导。旗帜鲜明讲政治，坚持党总揽全局、协调各方的领导核心作用，把坚持党的领导首先是坚持党中央集中统一领导作为首要原则，把维护习近平总书记的核心地位、维护党中央权威和集中统一领导摆在讲政治的首要位置，增强政治意识、大局意识、核心意识、看齐意识，自觉在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致，向党中央看齐，向党的理论和路线方针政策看齐，向党中央决策部署看齐，认真负责、不折不扣执行党中央决策部署，使党的主张通过法定程序成为国家意志，使支出预算和政策更好体现和落实党中央决策部署，保障党的路线方针政策在国家工作中得到全面贯彻和有效执行。\n2.坚持围绕和服务党和国家大局。牢牢把握中国特色社会主义进入新时代、我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，坚持稳中求进工作总基调，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，坚定不移贯彻落实新发展理念，主动适应经济发展新常态，坚持以推进供给侧结构性改革为主线，开展支出预算和政策审查监督工作，使财政预算和政策更好服务于党和国家中心工作，推动经济社会持续健康发展。\n3.坚持以人民为中心的发展思想。把人民群众对美好生活的向往作为奋斗目标，推进完善支出预算和政策，着力保障和改善民生，推动解决制约全面建成小康社会的短板和瓶颈问题，推动解决人民群众普遍关心的热点难点问题，使改革发展成果更多惠及全体人民，不断增强人民群众的获得感、幸福感。\n4.坚持依法开展审查监督。严格按照宪法和预算法、监督法等法律赋予的预算审查监督职权，通过法定程序、运用法定方式，加强支出预算和政策审查监督工作，提高审查监督的针对性和有效性。坚持监督与支持相统一，人大通过依法加强预算审查监督，推动政府依法行政、依法理财。\n5.坚持问题导向。紧紧围绕贯彻落实党中央重大方针政策和决策部署，结合人大代表和人民群众普遍关心的热点难点问题、审计查出的突出问题、制约事业发展的关键问题等，加强对相关支出预算和政策的审查监督，提出有效、可行的意见建议，着力推动解决突出矛盾，推动建立健全解决问题的长效机制。加强对支出绩效和政策目标落实情况的监督，推动建立健全预算绩效管理机制。\n6.坚持积极探索与扎实推进相结合。立足我国基本国情、经济社会发展阶段及财政预算管理水平，既扎实做好基础性工作，为深入实施改革举措创造条件，又适应新的形势和任务要求，认真研究总结预算审查监督经验做法和规律，深化拓展支出预算和政策审查监督的内容，探索创新方式方法，确保改革取得成效。","level":1},{"name":"三、主要内容","text":"政府预算反映国家的战略、规划、政策，反映政府的职责、活动范围、方向。支出政策是政府根据党中央重大方针政策和决策部署、预算法等法律规定制定的财政支出安排措施，包括财政支出的方向、规模、结构和管理制度等。支出预算是政府根据党中央重大方针政策和决策部署、预算法等法律规定，按照规定的程序、方法和标准编制的，对各种支出作出统筹安排，并报经本级人民代表大会审查批准后执行的财政支出计划。人大通过审查监督支出预算和政策，保障党中央重大方针政策和决策部署的贯彻落实。\n按照党中央改革部署要求和预算法、监督法规定，人大对支出预算和政策开展全口径审查和全过程监管。主要内容包括：\n1.支出预算的总量与结构。审查支出预算总量，重点审查预算安排是否符合党中央确定的年度经济社会发展目标、国家宏观调控总体要求、国民经济和社会发展相关规划、中期财政规划，审查支出政策的可持续性，更好发挥政府职能作用。审查支出预算结构，重点审查支出预算和政策是否体现党中央就各重要领域提出的重大方针政策和决策部署要求，切实提高财政资金配置效率。\n2.重点支出与重大投资项目。加强对重点支出与重大投资项目的审查，保障党中央重大方针政策和决策部署确定的重点支出与重大投资项目。推动政府健全重点支出与重大投资项目决策机制，合理确定重点支出与重大投资项目范围。加强对重点支出与重大投资项目执行情况的监督，督促实现支出绩效和政策目标。\n3.部门预算。重点审查监督部门预算贯彻落实党中央重大方针政策和决策部署情况；部门预算编制的完整性情况；项目库建设、项目支出预算与支出政策衔接匹配情况；部门重大项目支出绩效目标设定、实现及评价结果应用情况；审计查出问题整改落实情况等。\n4.财政转移支付。重点审查监督贯彻党中央重大方针政策和决策部署情况，转移支付与财政事权和支出责任划分的匹配情况；转移支付对促进实现各地区财政平衡及基本公共服务均等化情况；专项转移支付的清理整合情况；专项转移支付的整体绩效情况。监督转移支付预算执行和政策实施，重点是预算批准后在法律规定时间内批复下达以及资金使用绩效与政策实施效果情况等。\n5.政府债务。硬化地方政府预算约束，坚决制止无序举债搞建设，规范举债融资行为。结合地方政府债务规模、全国经济发展水平等情况，合理评估全国政府债务风险水平。地方政府债务审查监督要重点审查地方政府债务纳入预算管理的情况；要根据各地的债务率、利息负担率、新增债务率等风险评估指标体系，结合债务资金安排使用和偿还计划，评价地方政府举债规模的合理性。积极稳妥化解累积的地方政府债务风险，坚决遏制隐性债务增量，决不允许新增各类隐性债务。\n加强对政府预算收入编制的审查。政府预算收入编制要与经济社会发展水平相适应，与财政政策相衔接，根据经济政策调整等因素科学预测。强化对政府预算收入执行情况的监督，推动严格依法征收，不收“过头税”，防止财政收入虚增、空转。推动依法规范非税收入管理。","level":1},{"name":"四、主要程序和方法","text":"全国人大及其常委会、地方各级人大及其常委会要按照总结、继承、完善、提高的原则，在巩固完善现有程序和方法基础上，进一步探索健全程序，创新方式方法，提高可操作性和运转效率，提高审查监督的针对性和有效性。\n1.认真贯彻落实党中央重大方针政策和决策部署。要深入学习贯彻习近平新时代中国特色社会主义思想和党的十九大精神，认真学习贯彻中央全会、中央经济工作会议、中央政治局会议等重要会议精神，明确目标任务，掌握部署要求，做好预算审查监督工作。坚持党对人大预算审查监督工作的领导，全国人大及其常委会开展预算审查监督工作中的重要事项和重要问题要及时向党中央请示报告，地方人大及其常委会开展预算审查监督工作中的重要事项和重要问题要及时向本级党委请示报告。\n2.充分听取意见建议。每年在政府预算草案编制前，应当通过召开座谈会、通报会等多种形式，认真听取本级人大代表、专家智库等社会各界关于重点支出、重大投资项目、重大支出政策等方面的意见建议。各级人大常委会预算工作委员会等工作机构要结合听取意见建议情况，与本级政府财政等部门密切沟通，认真研究提出关于年度预算的分析报告。\n3.深入开展专题调研。全国人大及其常委会、地方各级人大及其常委会应当根据年度工作要点和监督工作计划，听取和审议政府关于重点支出预算和政策专项工作报告，开展重点支出预算和政策专题调研，提出有针对性、前瞻性和可行性的意见建议。\n4.探索就重大事项或特定问题组织调查。根据预算法，各级人大和县级以上各级人大常委会可以就预算、决算中的重大事项或特定问题组织调查。根据《全国人大常委会关于加强中央预算审查监督的决定》，经全国人大常委会委员长会议专项批准，人大常委会预算工作委员会可以对各部门、各预算单位、重大建设项目的预算资金使用和专项资金的使用进行调查，政府有关部门和单位应当积极协助、配合。全国人大及其常委会、地方各级人大及其常委会就重大事项或特定问题组织调查，要按照前面第一项规定要求，向党中央或者本级党委请示报告。\n5.探索开展预算专题审议。人大财政经济委员会每年对预算草案进行初步审查时，应根据中央经济工作会议精神，结合人大常委会年度监督工作重点、人大代表和人民群众关心的热点难点问题、审计查出的突出问题等，对有关支出预算和政策开展专题审议。政府有关部门负责人应到会听取意见，回答询问。人大有关的专门委员会可以结合开展执法检查、听取政府专项工作报告等，对相关领域部门预算草案、相关重点支出和重大投资项目、有关转移支付资金和政策开展调查研究，更好发挥人大专门委员会的专业特点和优势。根据需要，可以引入社会中介机构为人大预算审查监督工作提供服务。\n6.推动落实人大及其常委会有关预算决算决议。通过听取报告、开展专题调研、组织代表视察等形式，推动政府及其有关部门积极落实本级人民代表大会及其常委会有关预算决算的决议。人大常委会预算工作委员会等工作机构应当听取政府财政等部门落实预算决算决议的工作安排情况通报，并将有关情况发送本级人大代表。\n7.及时听取重大财税政策报告。对于事关全国或者本级行政区域内经济社会发展全局、涉及群众切身利益的重大财税政策，各级政府在政策出台前应当向本级人大常委会报告。预算执行中，政府财政等部门出台增加收入或者支出、减少收入的政策措施，需要进行预算调整的，应当及时向本级人大常委会预算工作委员会等工作机构通报有关情况，依法编制预算调整方案，报本级人大常委会审查批准。\n8.加快推进预算联网监督工作。要适应信息社会发展要求，加快推进预算联网监督工作，实现预算审查监督信息化和网络化。要充分利用预算联网平台，加强对支出预算和政策的审查监督，提升审查监督内容的翔实性和时效性，增强审查监督工作的针对性和有效性。","level":1},{"name":"五、组织保障","text":"各级党委要进一步提高对推进人大预算审查监督重点向支出预算和政策拓展改革重要性的认识，加强组织领导，把握工作方向，及时研究解决改革中遇到的新情况新问题，支持和保证人大依法行使监督权，确保各项措施落实到位。\n全国人大及其常委会、地方各级人大及其常委会要牢固树立“四个意识”，切实增强责任感使命感，依法加强对支出预算和政策的审查监督，通过法定程序贯彻落实好党中央重大方针政策和决策部署。人大财政经济委员会、有关的专门委员会、常委会预算工作委员会等工作机构要积极作出安排，深入扎实开展审查监督工作。在政府预算草案编制前和编制过程中，人大常委会预算工作委员会等工作机构要加强与政府财政等部门的沟通，及时将听取人大代表和社会各界意见建议的情况反馈给政府财政等部门，使预算草案更好地回应人大代表和社会各界的意见建议。在对预算草案初步方案及上一年预算执行情况进行初步审查中，人大财政经济委员会依法提出初步审查意见，本级政府财政部门应当结合初步审查意见对预算草案和报告作进一步修改完善。各级人民代表大会上，各代表团、人大财政经济委员会、有关的专门委员会应当着重围绕党中央重大方针政策和决策部署对预算草案进行审查，保持预算的统一性和完整性。应当及时向社会公开对支出预算和政策的有关审查监督情况。\n各级政府要主动接受同级人大及其常委会的监督，积极创造条件，认真落实改革措施。要按照党的十八届三中全会关于“审核预算的重点由平衡状态、赤字规模向支出预算和政策拓展”的要求，积极改进完善预算报告、决算报告和预算草案、决算草案编报工作。预算报告、决算报告应当重点报告贯彻落实党中央重大方针政策和决策部署的主要情况，报告重大支出政策和税收政策调整变化情况，报告收入、支出安排及赤字、债务规模等财政总量政策与国家及本区域年度经济社会发展目标、宏观调控要求的一致性情况，报告支出预算、决算和政策实施的主要情况，报告重大投资项目的安排和实施情况。逐步改变相关重点支出与财政收支增幅或生产总值层层挂钩、先确定各领域支出总额再安排具体项目的做法。支出预算原则上要反映各项支出预算安排的政策依据、标准、支出方向及绩效目标等情况，增强重大增支政策出台的预期性。支出决算要重点报告和反映支出预算调整情况、支出完成预算情况、重大项目的资金使用绩效与政策实施效果情况。支出预算和决算要列示重大政府投资计划和重大投资项目表。进一步完善和丰富政府性基金预算、国有资本经营预算和社会保险基金预算的编报。在保持预算报告、财政预算草案纸质文件提供方式基础上，探索以电子化方式提供预算文件。各级审计机关研究提出下一年度审计监督重点内容和重点项目时，应当征求本级人大常委会预算工作委员会等工作机构的意见建议，形成监督合力。各级审计机关应当加强对专项资金绩效和政策执行的审计监督，并在向本级人大常委会报告年度预算执行和其他财政收支的审计工作报告时予以重点反映，为人大常委会开展支出决算和政策审查监督提供支持服务。各级政府财政、审计等部门和各预算部门单位，要积极做好落实改革措施的具体工作。要进一步推进预算公开透明，主动接受社会监督。\n地方各级人大及其常委会、地方各级政府要在认真贯彻落实党中央重大方针政策和决策部署的基础上，按照地方党委工作安排，加强对支出预算总量与结构、重点支出与重大投资项目、部门预算、财政转移支付、地方政府债务等的审查监督，并结合本地区实际，探索创新方式方法，健全完善程序机制，不断提高人大预算审查监督针对性和有效性，不断提升政府依法行政、依法理财水平。","level":1}]},{"id":"r0602","sections":[{"name":"关于建立以国家公园为主体的自然保护地体系的指导意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于建立以国家公园为主体的自然保护地体系的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于建立以国家公园为主体的自然保护地体系的指导意见》全文如下。\n建立以国家公园为主体的自然保护地体系，是贯彻习近平生态文明思想的重大举措，是党的十九大提出的重大改革任务。自然保护地是生态建设的核心载体、中华民族的宝贵财富、美丽中国的重要象征，在维护国家生态安全中居于首要地位。我国经过60多年的努力，已建立数量众多、类型丰富、功能多样的各级各类自然保护地，在保护生物多样性、保存自然遗产、改善生态环境质量和维护国家生态安全方面发挥了重要作用，但仍然存在重叠设置、多头管理、边界不清、权责不明、保护与发展矛盾突出等问题。为加快建立以国家公园为主体的自然保护地体系，提供高质量生态产品，推进美丽中国建设，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，贯彻落实习近平生态文明思想，认真落实党中央、国务院决策部署，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，牢固树立新发展理念，以保护自然、服务人民、永续发展为目标，加强顶层设计，理顺管理体制，创新运行机制，强化监督管理，完善政策支撑，建立分类科学、布局合理、保护有力、管理有效的以国家公园为主体的自然保护地体系，确保重要自然生态系统、自然遗迹、自然景观和生物多样性得到系统性保护，提升生态产品供给能力，维护国家生态安全，为建设美丽中国、实现中华民族永续发展提供生态支撑。\n（二）基本原则\n——坚持严格保护，世代传承。牢固树立尊重自然、顺应自然、保护自然的生态文明理念，把应该保护的地方都保护起来，做到应保尽保，让当代人享受到大自然的馈赠和天蓝地绿水净、鸟语花香的美好家园，给子孙后代留下宝贵自然遗产。\n——坚持依法确权，分级管理。按照山水林田湖草是一个生命共同体的理念，改革以部门设置、以资源分类、以行政区划分设的旧体制，整合优化现有各类自然保护地，构建新型分类体系，实施自然保护地统一设置，分级管理、分区管控，实现依法有效保护。\n——坚持生态为民，科学利用。践行绿水青山就是金山银山理念，探索自然保护和资源利用新模式，发展以生态产业化和产业生态化为主体的生态经济体系，不断满足人民群众对优美生态环境、优良生态产品、优质生态服务的需要。\n——坚持政府主导，多方参与。突出自然保护地体系建设的社会公益性，发挥政府在自然保护地规划、建设、管理、监督、保护和投入等方面的主体作用。建立健全政府、企业、社会组织和公众参与自然保护的长效机制。\n——坚持中国特色，国际接轨。立足国情，继承和发扬我国自然保护的探索和创新成果。借鉴国际经验，注重与国际自然保护体系对接，积极参与全球生态治理，共谋全球生态文明建设。\n（三）总体目标。建成中国特色的以国家公园为主体的自然保护地体系，推动各类自然保护地科学设置，建立自然生态系统保护的新体制新机制新模式，建设健康稳定高效的自然生态系统，为维护国家生态安全和实现经济社会可持续发展筑牢基石，为建设富强民主文明和谐美丽的社会主义现代化强国奠定生态根基。\n到2020年，提出国家公园及各类自然保护地总体布局和发展规划，完成国家公园体制试点，设立一批国家公园，完成自然保护地勘界立标并与生态保护红线衔接，制定自然保护地内建设项目负面清单，构建统一的自然保护地分类分级管理体制。到2025年，健全国家公园体制，完成自然保护地整合归并优化，完善自然保护地体系的法律法规、管理和监督制度，提升自然生态空间承载力，初步建成以国家公园为主体的自然保护地体系。到2035年，显著提高自然保护地管理效能和生态产品供给能力，自然保护地规模和管理达到世界先进水平，全面建成中国特色自然保护地体系。自然保护地占陆域国土面积18%以上。","level":1},{"name":"二、构建科学合理的自然保护地体系","text":"（四）明确自然保护地功能定位。自然保护地是由各级政府依法划定或确认，对重要的自然生态系统、自然遗迹、自然景观及其所承载的自然资源、生态功能和文化价值实施长期保护的陆域或海域。建立自然保护地目的是守护自然生态，保育自然资源，保护生物多样性与地质地貌景观多样性，维护自然生态系统健康稳定，提高生态系统服务功能；服务社会，为人民提供优质生态产品，为全社会提供科研、教育、体验、游憩等公共服务；维持人与自然和谐共生并永续发展。要将生态功能重要、生态环境敏感脆弱以及其他有必要严格保护的各类自然保护地纳入生态保护红线管控范围。\n（五）科学划定自然保护地类型。按照自然生态系统原真性、整体性、系统性及其内在规律，依据管理目标与效能并借鉴国际经验，将自然保护地按生态价值和保护强度高低依次分为3类。\n国家公园：是指以保护具有国家代表性的自然生态系统为主要目的，实现自然资源科学保护和合理利用的特定陆域或海域，是我国自然生态系统中最重要、自然景观最独特、自然遗产最精华、生物多样性最富集的部分，保护范围大，生态过程完整，具有全球价值、国家象征，国民认同度高。\n自然保护区：是指保护典型的自然生态系统、珍稀濒危野生动植物种的天然集中分布区、有特殊意义的自然遗迹的区域。具有较大面积，确保主要保护对象安全，维持和恢复珍稀濒危野生动植物种群数量及赖以生存的栖息环境。\n自然公园：是指保护重要的自然生态系统、自然遗迹和自然景观，具有生态、观赏、文化和科学价值，可持续利用的区域。确保森林、海洋、湿地、水域、冰川、草原、生物等珍贵自然资源，以及所承载的景观、地质地貌和文化多样性得到有效保护。包括森林公园、地质公园、海洋公园、湿地公园等各类自然公园。\n制定自然保护地分类划定标准，对现有的自然保护区、风景名胜区、地质公园、森林公园、海洋公园、湿地公园、冰川公园、草原公园、沙漠公园、草原风景区、水产种质资源保护区、野生植物原生境保护区（点）、自然保护小区、野生动物重要栖息地等各类自然保护地开展综合评价，按照保护区域的自然属性、生态价值和管理目标进行梳理调整和归类，逐步形成以国家公园为主体、自然保护区为基础、各类自然公园为补充的自然保护地分类系统。\n（六）确立国家公园主体地位。做好顶层设计，科学合理确定国家公园建设数量和规模，在总结国家公园体制试点经验基础上，制定设立标准和程序，划建国家公园。确立国家公园在维护国家生态安全关键区域中的首要地位，确保国家公园在保护最珍贵、最重要生物多样性集中分布区中的主导地位，确定国家公园保护价值和生态功能在全国自然保护地体系中的主体地位。国家公园建立后，在相同区域一律不再保留或设立其他自然保护地类型。\n（七）编制自然保护地规划。落实国家发展规划提出的国土空间开发保护要求，依据国土空间规划，编制自然保护地规划，明确自然保护地发展目标、规模和划定区域，将生态功能重要、生态系统脆弱、自然生态保护空缺的区域规划为重要的自然生态空间，纳入自然保护地体系。\n（八）整合交叉重叠的自然保护地。以保持生态系统完整性为原则，遵从保护面积不减少、保护强度不降低、保护性质不改变的总体要求，整合各类自然保护地，解决自然保护地区域交叉、空间重叠的问题，将符合条件的优先整合设立国家公园，其他各类自然保护地按照同级别保护强度优先、不同级别低级别服从高级别的原则进行整合，做到一个保护地、一套机构、一块牌子。\n（九）归并优化相邻自然保护地。制定自然保护地整合优化办法，明确整合归并规则，严格报批程序。对同一自然地理单元内相邻、相连的各类自然保护地，打破因行政区划、资源分类造成的条块割裂局面，按照自然生态系统完整、物种栖息地连通、保护管理统一的原则进行合并重组，合理确定归并后的自然保护地类型和功能定位，优化边界范围和功能分区，被归并的自然保护地名称和机构不再保留，解决保护管理分割、保护地破碎和孤岛化问题，实现对自然生态系统的整体保护。在上述整合和归并中，对涉及国际履约的自然保护地，可以暂时保留履行相关国际公约时的名称。","level":1},{"name":"三、建立统一规范高效的管理体制","text":"（十）统一管理自然保护地。理顺现有各类自然保护地管理职能，提出自然保护地设立、晋（降）级、调整和退出规则，制定自然保护地政策、制度和标准规范，实行全过程统一管理。建立统一调查监测体系，建设智慧自然保护地，制定以生态资产和生态服务价值为核心的考核评估指标体系和办法。各地区各部门不得自行设立新的自然保护地类型。\n（十一）分级行使自然保护地管理职责。结合自然资源资产管理体制改革，构建自然保护地分级管理体制。按照生态系统重要程度，将国家公园等自然保护地分为中央直接管理、中央地方共同管理和地方管理3类，实行分级设立、分级管理。中央直接管理和中央地方共同管理的自然保护地由国家批准设立；地方管理的自然保护地由省级政府批准设立，管理主体由省级政府确定。探索公益治理、社区治理、共同治理等保护方式。\n（十二）合理调整自然保护地范围并勘界立标。制定自然保护地范围和区划调整办法，依规开展调整工作。制定自然保护地边界勘定方案、确认程序和标识系统，开展自然保护地勘界定标并建立矢量数据库，与生态保护红线衔接，在重要地段、重要部位设立界桩和标识牌。确因技术原因引起的数据、图件与现地不符等问题可以按管理程序一次性纠正。\n（十三）推进自然资源资产确权登记。进一步完善自然资源统一确权登记办法，每个自然保护地作为独立的登记单元，清晰界定区域内各类自然资源资产的产权主体，划清各类自然资源资产所有权、使用权的边界，明确各类自然资源资产的种类、面积和权属性质，逐步落实自然保护地内全民所有自然资源资产代行主体与权利内容，非全民所有自然资源资产实行协议管理。\n（十四）实行自然保护地差别化管控。根据各类自然保护地功能定位，既严格保护又便于基层操作，合理分区，实行差别化管控。国家公园和自然保护区实行分区管控，原则上核心保护区内禁止人为活动，一般控制区内限制人为活动。自然公园原则上按一般控制区管理，限制人为活动。结合历史遗留问题处理，分类分区制定管理规范。","level":1},{"name":"四、创新自然保护地建设发展机制","text":"（十五）加强自然保护地建设。以自然恢复为主，辅以必要的人工措施，分区分类开展受损自然生态系统修复。建设生态廊道、开展重要栖息地恢复和废弃地修复。加强野外保护站点、巡护路网、监测监控、应急救灾、森林草原防火、有害生物防治和疫源疫病防控等保护管理设施建设，利用高科技手段和现代化设备促进自然保育、巡护和监测的信息化、智能化。配置管理队伍的技术装备，逐步实现规范化和标准化。\n（十六）分类有序解决历史遗留问题。对自然保护地进行科学评估，将保护价值低的建制城镇、村屯或人口密集区域、社区民生设施等调整出自然保护地范围。结合精准扶贫、生态扶贫，核心保护区内原住居民应实施有序搬迁，对暂时不能搬迁的，可以设立过渡期，允许开展必要的、基本的生产活动，但不能再扩大发展。依法清理整治探矿采矿、水电开发、工业建设等项目，通过分类处置方式有序退出；根据历史沿革与保护需要，依法依规对自然保护地内的耕地实施退田还林还草还湖还湿。\n（十七）创新自然资源使用制度。按照标准科学评估自然资源资产价值和资源利用的生态风险，明确自然保护地内自然资源利用方式，规范利用行为，全面实行自然资源有偿使用制度。依法界定各类自然资源资产产权主体的权利和义务，保护原住居民权益，实现各产权主体共建保护地、共享资源收益。制定自然保护地控制区经营性项目特许经营管理办法，建立健全特许经营制度，鼓励原住居民参与特许经营活动，探索自然资源所有者参与特许经营收益分配机制。对划入各类自然保护地内的集体所有土地及其附属资源，按照依法、自愿、有偿的原则，探索通过租赁、置换、赎买、合作等方式维护产权人权益，实现多元化保护。\n（十八）探索全民共享机制。在保护的前提下，在自然保护地控制区内划定适当区域开展生态教育、自然体验、生态旅游等活动，构建高品质、多样化的生态产品体系。完善公共服务设施，提升公共服务功能。扶持和规范原住居民从事环境友好型经营活动，践行公民生态环境行为规范，支持和传承传统文化及人地和谐的生态产业模式。推行参与式社区管理，按照生态保护需求设立生态管护岗位并优先安排原住居民。建立志愿者服务体系，健全自然保护地社会捐赠制度，激励企业、社会组织和个人参与自然保护地生态保护、建设与发展。","level":1},{"name":"五、加强自然保护地生态环境监督考核","text":"实行最严格的生态环境保护制度，强化自然保护地监测、评估、考核、执法、监督等，形成一整套体系完善、监管有力的监督管理制度。\n（十九）建立监测体系。建立国家公园等自然保护地生态环境监测制度，制定相关技术标准，建设各类各级自然保护地“天空地一体化”监测网络体系，充分发挥地面生态系统、环境、气象、水文水资源、水土保持、海洋等监测站点和卫星遥感的作用，开展生态环境监测。依托生态环境监管平台和大数据，运用云计算、物联网等信息化手段，加强自然保护地监测数据集成分析和综合应用，全面掌握自然保护地生态系统构成、分布与动态变化，及时评估和预警生态风险，并定期统一发布生态环境状况监测评估报告。对自然保护地内基础设施建设、矿产资源开发等人类活动实施全面监控。\n（二十）加强评估考核。组织对自然保护地管理进行科学评估，及时掌握各类自然保护地管理和保护成效情况，发布评估结果。适时引入第三方评估制度。对国家公园等各类自然保护地管理进行评价考核，根据实际情况，适时将评价考核结果纳入生态文明建设目标评价考核体系，作为党政领导班子和领导干部综合评价及责任追究、离任审计的重要参考。\n（二十一）严格执法监督。制定自然保护地生态环境监督办法，建立包括相关部门在内的统一执法机制，在自然保护地范围内实行生态环境保护综合执法，制定自然保护地生态环境保护综合执法指导意见。强化监督检查，定期开展“绿盾”自然保护地监督检查专项行动，及时发现涉及自然保护地的违法违规问题。对违反各类自然保护地法律法规等规定，造成自然保护地生态系统和资源环境受到损害的部门、地方、单位和有关责任人员，按照有关法律法规严肃追究责任，涉嫌犯罪的移送司法机关处理。建立督查机制，对自然保护地保护不力的责任人和责任单位进行问责，强化地方政府和管理机构的主体责任。","level":1},{"name":"六、保障措施","text":"（二十二）加强党的领导。地方各级党委和政府要增强“四个意识”，严格落实生态环境保护党政同责、一岗双责，担负起相关自然保护地建设管理的主体责任，建立统筹推进自然保护地体制改革的工作机制，将自然保护地发展和建设管理纳入地方经济社会发展规划。各相关部门要履行好自然保护职责，加强统筹协调，推动工作落实。重大问题及时报告党中央、国务院。\n（二十三）完善法律法规体系。加快推进自然保护地相关法律法规和制度建设，加大法律法规立改废释工作力度。修改完善自然保护区条例，突出以国家公园保护为主要内容，推动制定出台自然保护地法，研究提出各类自然公园的相关管理规定。在自然保护地相关法律、行政法规制定或修订前，自然保护地改革措施需要突破现行法律、行政法规规定的，要按程序报批，取得授权后施行。\n（二十四）建立以财政投入为主的多元化资金保障制度。统筹包括中央基建投资在内的各级财政资金，保障国家公园等各类自然保护地保护、运行和管理。国家公园体制试点结束后，结合试点情况完善国家公园等自然保护地经费保障模式；鼓励金融和社会资本出资设立自然保护地基金，对自然保护地建设管理项目提供融资支持。健全生态保护补偿制度，将自然保护地内的林木按规定纳入公益林管理，对集体和个人所有的商品林，地方可依法自主优先赎买；按自然保护地规模和管护成效加大财政转移支付力度，加大对生态移民的补偿扶持投入。建立完善野生动物肇事损害赔偿制度和野生动物伤害保险制度。\n（二十五）加强管理机构和队伍建设。自然保护地管理机构会同有关部门承担生态保护、自然资源资产管理、特许经营、社会参与和科研宣教等职责，当地政府承担自然保护地内经济发展、社会管理、公共服务、防灾减灾、市场监管等职责。按照优化协同高效的原则，制定自然保护地机构设置、职责配置、人员编制管理办法，探索自然保护地群的管理模式。适当放宽艰苦地区自然保护地专业技术职务评聘条件，建设高素质专业化队伍和科技人才团队。引进自然保护地建设和发展急需的管理和技术人才。通过互联网等现代化、高科技教学手段，积极开展岗位业务培训，实行自然保护地管理机构工作人员继续教育全覆盖。\n（二十六）加强科技支撑和国际交流。设立重大科研课题，对自然保护地关键领域和技术问题进行系统研究。建立健全自然保护地科研平台和基地，促进成熟科技成果转化落地。加强自然保护地标准化技术支撑工作。自然保护地资源可持续经营管理、生态旅游、生态康养等活动可研究建立认证机制。充分借鉴国际先进技术和体制机制建设经验，积极参与全球自然生态系统保护，承担并履行好与发展中大国相适应的国际责任，为全球提供自然保护的中国方案。","level":1}]},{"id":"r0603","sections":[{"name":"中共中央办公厅印发《关于推动党史学习教育常态化长效化的意见》","text":"近日，中共中央办公厅印发了《关于推动党史学习教育常态化长效化的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于推动党史学习教育常态化长效化的意见》全文如下。\n在全党开展党史学习教育，是以习近平同志为核心的党中央立足百年党史新起点、着眼开创事业发展新局面作出的一项重大战略决策。这次学习教育认真贯彻学史明理、学史增信、学史崇德、学史力行的要求，取得重要政治成果、理论成果、实践成果、制度成果，广大党员、干部受到一次全面深刻的政治教育、思想淬炼、精神洗礼，全党历史自觉、历史自信大大增强，党的创造力、凝聚力、战斗力大大提升，达到了学党史、悟思想、办实事、开新局的目的。为进一步推动全党深入学习贯彻习近平新时代中国特色社会主义思想和党的十九届六中全会精神，巩固拓展党史学习教育成果，更好用党的百年奋斗重大成就和历史经验增长智慧、增进团结、增加信心、增强斗志，更加坚定自觉地牢记初心使命、开创发展新局，在新的赶考之路上考出好成绩，现就推动党史学习教育常态化长效化，提出如下意见。\n一、着眼坚定历史自信，坚持不懈把党史作为必修课、常修课。深入学习习近平总书记关于党的历史的重要论述，从中深刻领悟党百年奋斗的历史价值和学习党史的根本目的、基本要求、科学态度，进一步增强学党史用党史的思想自觉和行动自觉。以学习贯彻党的十九届六中全会精神为重点，持之以恒推进党史总结、学习、教育、宣传，进一步做到学史明理、学史增信、学史崇德、学史力行。原原本本学习党的第三个历史决议，学懂弄通党百年奋斗的光辉历程，学懂弄通党坚守初心使命的执着奋斗，学懂弄通党百年奋斗的历史意义和历史经验，学懂弄通以史为鉴、开创未来的重要要求，特别是深入领会党的十八大以来党和国家事业取得的历史性成就、发生的历史性变革，深入领会新时代原创性思想、变革性实践、突破性进展、标志性成果，不断深化对历史进程的认识、历史规律的把握、历史智慧的运用。坚持把党的历史经验作为正确判断形势、科学预见未来、把握历史主动的重要思想武器，作为想问题、作决策、办事情的重要遵循，作为判断重大政治是非的重要依据，作为加强党性修养的重要指引。强化历史认知，推动正确党史观更深入、更广泛地树立起来，让正史成为全党全社会的共识，教育广大党员、干部和全体人民特别是广大青年从党的百年奋斗中看清楚过去我们为什么能够成功、弄明白未来我们怎样才能继续成功，更好把握党的历史发展的主题主线、主流本质，坚定历史自信、筑牢历史记忆，满怀信心地向前进。发挥党委（党组）理论学习中心组龙头作用，把党史学习作为常态化内容纳入其中，经常性地开展专题学习、专题研讨，推动领导班子、领导干部带头学党史、经常学党史。发挥干部教育培训机制作用，特别是结合年轻干部的成长经历和思想实际，进一步充实党史教育课程，丰富党史教育形式，提高党史教学质量。用好学校思政课这个渠道，推动党史更好地进教材、进课堂、进头脑，发挥好党史立德树人的重要作用。继续抓好党史、新中国史、改革开放史、社会主义发展史宣传教育，融入群众性文化活动和精神文明创建，用好新时代文明实践中心、县级融媒体中心等平台，开展切合基层实际的学习教育活动，引导全社会更好知史爱党、知史爱国。把党史宣传融入重大主题宣传，持续推出导向正确、质量过硬、形式鲜活的党史题材作品，创新创作吸引力感染力强的融媒体产品。深化党史研究，加强党史学科建设，发挥专业研究机构、研究力量作用，不断推出高质量研究成果，为推动党史学习教育常态化长效化提供有力学理支撑。\n二、着眼增强理论自觉，坚持不懈用习近平新时代中国特色社会主义思想武装头脑。深入贯彻学党史悟思想的基本要求，从马克思主义中国化的百年历程中深刻感悟思想伟力，充分认识中国共产党为什么能、中国特色社会主义为什么好，归根到底是因为马克思主义行；马克思主义之所以行，就在于党不断推进马克思主义中国化时代化并用以指导实践。坚持把学习习近平新时代中国特色社会主义思想作为重中之重，引导广大党员、干部更加深刻认识这一重要思想坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，是当代中国马克思主义、二十一世纪马克思主义，是中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃；深刻认识这一重要思想科学回答了中国之问、世界之问、人民之问、时代之问；深刻感悟这一重要思想对实现中华民族伟大复兴的统领作用，对走好中国式现代化道路的引领作用，对建设长期执政的马克思主义政党的指引作用。坚持读原著学原文、悟原理知原义，坚持在学懂弄通做实上下功夫，坚持联系思想实际、工作实际，深入学习习近平总书记重要著作，跟进学习习近平总书记最新重要讲话精神，既注重从总体上系统把握，又分专题分领域深入领会，做到至信而深厚、融通而致用、执着而笃行。坚持解放思想、实事求是、守正创新，深入研究阐释关系党和国家事业发展全局的战略问题，不断回答深层次思想认识问题、重大现实问题、社会热点难点问题，形成更多有分量的研究成果，以扎实的理论研究支撑理论武装。加强对象化、分众化理论宣传，用好新媒体新平台，推出更多通俗易懂的理论读物，讲好新时代党的创新理论的学理哲理、道理情理。推动领导干部带头学、广大党员跟进学、全社会广泛学，不断提高全党马克思主义理论素养，提高广大干部群众思想觉悟，更好用党的创新理论把全党武装起来、把人民凝聚起来，把党中央决策部署的各项任务落实下去。\n三、着眼提高政治能力，坚持不懈领悟“两个确立”决定性意义、坚定做到“两个维护”的高度自觉。把常态化长效化学习党史的过程作为增强政治意识、强化党性锻炼，不断提高政治判断力、政治领悟力、政治执行力的过程，引导广大党员、干部深刻认识旗帜鲜明讲政治是我们党作为马克思主义政党的根本要求，保证党的团结统一是党的生命；深刻认识党的十八大以来党和国家事业取得历史性成就、发生历史性变革，根本在于有习近平总书记作为党中央的核心、全党的核心掌舵领航，在于有习近平新时代中国特色社会主义思想科学指引。推动各级党组织不断提高党内政治生活质量，通过民主生活会、组织生活会、“三会一课”、主题党日、重温入党誓词、过“政治生日”等，引导广大党员、干部强化党的意识、党员意识，深刻认识坚持党的全面领导特别是党中央集中统一领导是我们的根本政治优势，进一步领悟“两个确立”的决定性意义，始终在政治立场、政治方向、政治原则、政治道路上同以习近平同志为核心的党中央保持高度一致。强化对党忠诚教育，把对党忠诚、做到“两个维护”体现在坚决贯彻党中央决策部署的行动上，体现在履职尽责、做好本职工作的实效上，体现在党员、干部的日常言行上，自觉同党的理论和路线方针政策对标对表、及时校准偏差，党中央作出的战略决策必须坚决执行，确保不偏向、不变通、不走样。强化政治能力训练和政治实践历练，善于从政治上研判形势、分析问题，牢记“国之大者”，一切在大局下思考、一切在大局下行动，以干工作、办实事的实际行动提高贯彻党中央决策部署的本领和水平。\n四、着眼强化宗旨意识，坚持不懈为群众办实事办好事。深入践行以人民为中心的发展思想，巩固“我为群众办实事”实践活动成果，走好新时代党的群众路线。发挥基层党组织战斗堡垒作用和党员先锋模范作用，用心用情用力解决群众的操心事、揪心事、烦心事，增强人民获得感、幸福感、安全感。在落实民生项目清单、做实政策措施的基础上，推动工作流程规范化、创新做法制度化、成熟经验机制化，完善解决民生问题的体制机制。省、市、县党政领导班子要立足实际，围绕巩固拓展脱贫攻坚成果、全面推进乡村振兴，围绕加强城乡公共服务、解决人民群众急难愁盼问题，围绕解决困难群体实际问题，制定年度民生实事计划并跟进抓好落实。县处级以上党政领导班子成员要建立基层联系点，定期深入基层了解社情民意、解决实际困难。各级党组织要积极组织开展志愿服务，鼓励和引导党员、干部到工作地或居住地，满腔热忱地为群众办实事、解难事，在为民造福中让群众看到党员、干部作风的新改进、面貌的新变化。坚决反对形式主义、官僚主义，不开空头支票，不增加基层负担，防止“作秀”、“造盆景”，多做为民利民惠民的实绩。\n五、着眼激发昂扬斗志，坚持不懈弘扬伟大建党精神。坚持把弘扬伟大建党精神作为推进党史学习教育常态化长效化的重要任务，作为培育党内政治文化的重要内容，作为践行社会主义核心价值观的重要抓手，融入党员、干部学习教育的日常，体现在干事创业的平常，做到见人见事见精神。加强革命传统教育，用好中国共产党历史展览馆这个精神殿堂，用好革命遗址遗迹、纪念馆、博物馆等红色资源，发挥革命英烈、时代楷模示范引领作用，以重大节日和纪念日为契机开展主题活动，引导广大党员、干部深刻领悟中国共产党人精神谱系的丰富内涵和时代意义，传承红色基因，赓续红色血脉。加强党的光荣传统和优良作风教育，完善作风建设长效机制，把好传统带进新征程，将好作风弘扬在新时代。加强形势政策教育，利用专题培训、集中宣讲、媒体传播等多种形式，及时深入解读国际国内形势，解读党和政府的政策措施，引导广大党员、干部准确认识和把握我国社会主要矛盾和中心任务，把思想统一到党中央科学判断上来，增强继续前行的信心。加强斗争精神教育，注重从党的历史中汲取战胜风险挑战的智慧和力量，在新时代的伟大实践中不断锤炼斗争精神和斗争本领，激励广大党员、干部发扬历史主动精神，敢于直面矛盾问题和困难挑战，积极履职尽责、勇于担当作为，保持踔厉奋发、笃行不怠的坚定意志，为党和人民事业赤诚奉献。\n六、着眼永葆初心使命，坚持不懈推进自我革命。把常态化长效化学习党史作为不断砥砺初心使命的重要途径，作为推进党的自我革命的重要要求，引导广大党员、干部深刻认识勇于自我革命是我们党区别于其他政党的显著标志，是我们党对如何跳出历史周期率的时代回答。全面贯彻新时代党的建设总要求，以党的政治建设为统领，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争，不断增强党自我净化、自我完善、自我革新、自我提高能力。用好党推进自我革命的宝贵经验，认真践行永葆马克思主义政党本色的实践要求，在为谁执政、为谁用权、为谁谋利这个根本问题上头脑要特别清醒、立场要特别坚定。经常性开展政治体检，自觉打扫思想政治灰尘，积极开展批评和自我批评，不断增强政治免疫力。各级领导班子和领导干部要经常对照党章党规，对照党中央决策部署，对照人民群众新期待，对照先进典型、身边榜样，查找自身在政治、思想、组织、作风、能力、廉洁等方面存在的差距和不足，深刻检视剖析，认真抓好整改落实。督促党员领导干部严守党的政治纪律和政治规矩，严格执行廉洁自律准则、党内政治生活若干准则，严格落实中央八项规定及其实施细则精神，认真贯彻新时代党的组织路线，知敬畏、存戒惧、守底线，崇尚对党忠诚的大德、造福人民的公德、严于律己的品德，驰而不息抓作风改作风。\n推动党史学习教育常态化长效化是建设马克思主义学习型政党的一项长期重要任务。各级党委（党组）要提高政治站位，落实主体责任，加强组织领导，完善制度机制，进一步巩固拓展党史学习教育成果。领导干部要学在前、作表率，带着对党的深厚感情学党史，带着对事业的强烈责任用党史，形成一级带一级、全党一起学的良好局面。积极探索适合不同行业、不同领域、不同群体深入学党史的方法途径，既要精准有效覆盖，又要生动鲜活开展，使学党史、知党史、用党史在全社会蔚然成风。要把推动党史学习教育常态化长效化同做好中心工作结合起来，把党史学习教育成效转化为干事创业的动力、举措和成效，满怀信心奋进新征程、建功新时代，以实际行动迎接党的二十大胜利召开，不断开创党和国家事业发展新局面。\n党史学习教育","level":0}]},{"id":"r0604","sections":[{"name":"中共中央办公厅 国务院办公厅关于进一步强化食品安全全链条监管的意见","text":"中共中央办公厅 国务院办公厅关于进一步强化食品安全全链条监管的意见\n（2025年3月13日）","level":1},{"name":"","text":"为进一步理清食品安全监管责任，建立健全协同监管机制，强化全链条监管合力，坚决守牢食品安全底线，切实保障人民群众身体健康和生命安全，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、完善食用农产品协同监管","text":"（一）严格落实食用农产品质量安全监管职责。生态环境部门负责推进农用地土壤重金属污染溯源和整治。农业农村部门负责履行食用农产品从种植养殖到进入批发、零售市场或生产加工企业前的质量安全监管职责；市场监管部门负责履行食用农产品进入批发、零售市场或生产加工企业后的质量安全监管职责。县级以上地方政府要认真落实食用农产品质量安全属地管理责任，加强监管能力建设，研究解决本级食用农产品质量安全监管中的职能交叉和监管空白问题，避免出现监管漏洞和盲区。乡镇政府要落实食用农产品质量安全监管责任。\n（二）加强食用农产品产地准出与市场准入衔接。农业农村部门和市场监管部门要加强协调配合，切实发挥承诺达标合格证在食用农产品产地准出与市场准入中的衔接作用。农业农村部门要做好承诺达标合格证开具、使用相关工作的指导服务和监督检查，对未按规定开具承诺达标合格证的依法予以查处，加强食用农产品上市前禁限用药物和易超标常规药物残留速测把关。市场监管部门要督促食品生产经营者强化进货查验，指导食用农产品批发市场依法开展入场查验和抽样检验，加大禁限用药物和易超标常规药物残留速测力度。鼓励食品生产经营者优先采购附具承诺达标合格证的食用农产品。建立承诺达标合格证问题通报协查机制，完善不合格产品闭环处置流程。\n（三）强化肉类产品检验检疫出证查验。农业农村部门要强化肉类产品检验检疫出证管理，建立完善屠宰检疫出证信息化系统，推进肉类产品品质检验无纸化出证，明确检验检疫证明公开查验途径。完善禁止对牲畜、禽类注水或注入其他物质的相关规定。市场监管部门要督促食品生产经营者将肉类产品检验检疫合格证明作为肉类产品进货查验的基础凭证；积极探索应用信息化手段，加强与农业农村部门的信息共享和互联互通。\n（四）加快建立食用农产品质量安全追溯协作和执法合作机制。农业农村部要会同市场监管总局等部门制定食用农产品质量安全追溯管理办法，建立健全食用农产品质量安全追溯目录。农业农村、市场监管部门要建立食用农产品质量安全监管信息共享及反馈机制，加强食用农产品质量安全风险防范，强化舆情监测和应急处置协调联动；密切食用农产品质量安全行政执法协调协作，对突出问题进行专项治理整顿。","level":1},{"name":"二、强化食品生产经营许可审查","text":"（五）规范食品生产经营市场准入。食品生产经营许可部门应严格落实许可审查要求，严禁擅自改变许可条件或未经审查即予许可，省级以上市场监管部门要对食品生产经营许可实施情况进行督导检查。地方政府指定市场监管部门以外的部门实施许可的，应符合法律授权规定，明确申请受理、材料审查、现场核查、许可决定责任分工，完善许可和监管工作衔接机制。加强传统特色食品加工制作工艺保护，与现代检测技术有机衔接，确保食品特色和质量安全。\n（六）完善特殊食品注册许可制度。省级以上市场监管部门依职责严格开展特殊食品注册、备案、生产许可审查，对符合条件的重点品种实施优先审评审批。市场监管总局和国家卫生健康委要加强协作，开展特殊食品技术联动、专家联审；统筹完善食品健康声称和保健食品功能声称相关工作。\n（七）完善食品安全检查员制度。市场监管部门要加强食品安全检查履职能力建设，进一步完善食品安全检查员制度，做好许可审查、监督检查、注册核查等专业检查工作。强化培训考核和统一调配使用，提升专业检查能力和水平。","level":1},{"name":"三、加快建立食品贮存监管机制","text":"（八）加强食品贮存安全监管。农业农村、海关、市场监管、粮食和储备等部门依职责建立健全食品贮存监管制度，明确监管要求。加强对从事食用农产品、食品、食品添加剂及食品原料等贮存主体的监督检查，规范贮存经营行为。\n（九）落实食品贮存主体责任。食品贮存主体应建立完善食品安全管理制度，保证必备的食品贮存条件，实施食品贮存全过程记录，严格风险管控。食品贮存委托方应对受托方的食品安全保障能力进行审核，并监督受托方按照保证食品安全的要求进行贮存。食品贮存委托方和受托方应当明确入库出库交付查验要求，严格交付衔接和入库出库管理。\n（十）强化食品贮存属地管理责任。县级以上地方政府应明确食品贮存的部门监管和行业管理责任，督促属地食品贮存主体落实食品安全责任。非食品生产经营者从事对温度、湿度等有特殊要求食品贮存业务的，应纳入食品安全监管范围。","level":1},{"name":"四、加快建立食品运输协同监管机制","text":"（十一）建立实施散装液态食品运输准运制度。依法建立散装液态食品运输准运制度，明确运输散装液态食品车辆的食品安全准入条件和技术标准，核发食品准运证明，确保专车专用。制定实行运输准运制度的散装液态食品重点品种目录。\n（十二）加强食品运输全过程监管。市场监管部门要会同交通运输、农业农村、粮食和储备等部门建立健全对食品和食用农产品运输发货方、承运方、收货方的协同监管机制，研究制定运输电子联单管理要求，加强交付、装卸、运输管理和运输工具日常管理，强化从业人员教育培训，压实各方食品安全主体责任，防范污染变质风险。","level":1},{"name":"五、健全食品寄递安全和配送安全管理","text":"（十三）强化食品寄递安全管理。邮政管理部门要督促邮政企业、快递企业落实实名收寄、收寄验视、过机安检制度，防范利用寄递渠道寄递假冒伪劣食品。邮政管理部门要与市场监管等部门加强协作，加大对寄递环节涉食品安全违法线索的核查处置力度，依法打击利用寄递渠道销售假冒伪劣食品的违法行为。\n（十四）加强网络订餐配送安全管理。市场监管部门要督促网络订餐平台、餐饮经营者履行食品安全法律法规规定的义务，落实网络订餐配送环节食品安全责任。人力资源社会保障部门要将掌握食品安全法律知识纳入网约配送员国家职业技能标准。网络订餐平台、餐饮经营者应根据国家职业技能标准，结合实际建立适合网络订餐配送行业劳动者的培训模式，强化食品安全法律知识培训。","level":1},{"name":"六、加强网络食品销售新业态监管","text":"（十五）压实网络食品销售从业主体责任。网络交易平台企业要按规定设置专门的食品安全管理机构或指定专职食品安全管理人员；严格审查食品生产经营者入网销售主体资质，规范主体信息、食品信息刊载公示，依法对食用农产品承诺达标合格证展示、药物残留检测等进行检查把关；加强入网销售行为过程管控，及时发现违规行为并作出相应处置。主播及其服务机构要规范开展营销活动，依法对其推荐的食品进行查验。广告活动参与者要依法开展食品类互联网广告设计、制作、代理、发布等。食品生产经营者要严把质量安全关，保持线上线下同标同质。从业主体明知或应知产品违法但未采取相关处置措施的，依法承担相应责任。\n（十六）强化网络销售食品安全问题协同治理。市场监管部门要会同农业农村、工业和信息化、网信、广电等部门明确直播带货、私域电商、社区团购等网络食品销售新业态治理要求，依职责加强网络销售食品安全问题信息监测通报和协查处置。网信部门对各部门通报的网络销售食品安全方面的不实虚假信息配合做好相应处置工作。强化行政处罚和刑事处罚双向衔接，依法打击违法犯罪行为。","level":1},{"name":"七、健全餐饮服务综合监管机制","text":"（十七）加强网络订餐线上线下一体化监管。市场监管部门要会同工业和信息化、网信等部门对存在食品安全严重违法情形的平台依法处置。推动平台和商户实行“互联网+明厨亮灶”，强化无堂食外卖监管和社会监督。\n（十八）强化集中用餐单位食品安全协同管理。教育、民政、卫生健康等部门要强化对本行业集中用餐单位的食品安全教育和日常管理。市场监管部门要强化集中用餐单位食品安全监督检查及抽检监测，依法查处违法行为并通报同级行业主管部门。\n（十九）完善校园食品安全协同管理机制。教育部门要会同农业农村、市场监管部门建立健全学校食堂食品安全全过程管理制度。教育部门要加强对学校食品安全相关工作的统筹管理和指导，完善学校食堂大宗食材供应商资质评审制度，建立供应商不良记录清单，推动优质安全食材进入学校食堂。推动学校食堂大宗食材集中招标采购，建立采购数字化平台，规范食材采购、供应、验收、结算等流程。教育部门要指导中小学校园膳食监督家长委员会高效规范运行，会同市场监管等部门及时办理反馈或直送的问题。市场监管部门要严格承包经营、食材供应、供餐等经营主体准入许可，依法查处涉及学校食品安全违法行为。","level":1},{"name":"八、完善进口食品风险联防联控机制","text":"（二十）强化进口食品部门监管联动。境外发生的食品安全事件可能对我国境内造成影响，或者在进口食品中发现严重食品安全问题的，海关应当及时采取风险预警或者控制措施，并向同级市场监管、卫生健康、农业农村部门通报，接到通报的部门应当及时采取相应措施，并向海关反馈。市场监管部门发现国内市场上销售的进口食品存在严重食品安全问题，或者在生产加工环节发现企业将进口的非食品原料用于食品生产加工的，应当及时采取风险防控措施，依法依规处置并向同级海关通报；海关对市场监管部门通报的问题，应及时开展风险评估，并根据评估情况依法依规处置。有关部门应依职责加强对综合保税区等海关特殊监管区域内食品生产经营的安全监管。\n（二十一）完善跨境电商零售进口食品监管制度。商务部要会同海关总署、市场监管总局建立跨境电商零售进口食品负面清单，将明令暂停进口的疫区食品以及因出现重大质量安全风险启动应急处置的食品等列入负面清单并实时调整。海关要根据市场监管部门需要，按规定提供跨境电商企业、平台及境内服务商等相关信息，及时开展食品安全风险信息交流。市场监管总局、商务部等部门要进一步明确跨境电商零售进口食品召回责任。市场监管部门要加大召回监管力度，督促相关责任方及时召回。","level":1},{"name":"九、加强组织实施","text":"各地区各有关部门要高度重视食品安全工作，在党中央集中统一领导下，强化组织领导，结合实际抓好本意见贯彻落实。国务院食品安全委员会及其办公室要充分发挥统筹协调指导作用，整合优化食品安全领域技术资源，提高支撑保障能力。各有关部门要各负其责、有效协同，确保食品安全全链条、各环节监管有机衔接，责任全面落实。重大事项及时按程序向党中央、国务院请示报告。","level":1}]},{"id":"r0605","sections":[{"name":"关于做好2015年元旦春节期间有关工作的通知","text":"点击此处观看视频","level":1},{"name":"","text":"中共中央办公厅、国务院办公厅近日印发了《关于做好2015年元旦春节期间有关工作的通知》。全文如下：\n为切实做好2015年元旦、春节期间各项工作，确保全国人民度过欢乐祥和的节日，经党中央、国务院同意，现将有关事项通知如下。\n一、扎实做好关心群众特别是困难群众生活工作，把党和政府的温暖送到群众家中。各级党委、政府要统筹安排、整合资源，集中对生产生活困难、迫切需要帮助的群众开展走访慰问、送温暖等活动。各级领导干部要按照党的群众路线教育实践活动整改落实要求，进一步增强群众观念，改进工作作风，深入基层一线，多到老少边穷、受灾地区去，多到困难群众中去，帮助群众解决遇到的各类急难问题。做好困难优抚对象和低保户、五保户、残疾人家庭以及受灾地区群众等特殊困难群众的生活救助工作，开展好对低保边缘户、因病致贫户、流动困难群众等的临时救助。优化社会救助运行机制，提高办理效率，确保困难群众求助有门、受助及时。做好企业退休人员基本养老金、符合条件的城乡老年居民养老金、失业保险金发放工作。集中开展农民工工资支付情况专项检查，畅通举报投诉渠道，严厉打击恶意拖欠、拒不支付劳动报酬的违法犯罪行为，保证农民工及时足额拿到应得报酬。\n二、保障节日市场平稳运行，丰富群众精神文化生活。各地区各有关部门要加大市场监测和调控力度，稳定粮油、肉蛋、蔬菜等重要商品供应，执行好社会救助和保障标准与物价上涨挂钩的联动机制，搞好煤电油气运组织协调，保障城乡居民消费需要和价格基本稳定。加强食品药品安全、电子商务和网络购物、旅游市场等方面的监管，依法打击制假售假违法犯罪活动。组织开展以年节为主题的形式多样的文化活动，广泛开展文化进万家、文艺界“深入生活、扎根人民”主题实践活动，加大公共文化设施免费开放力度，组织开展民间文化艺术普及推广活动，为基层一线群众提供更多体现社会主义核心价值观要求、人民群众喜闻乐见的优秀文化产品。坚持正确导向和健康基调，抵制低俗之风，依法查处各种网络违法行为，净化网络文化环境，营造良好节日文化氛围。\n三、统筹做好春运工作，让群众出行便利、安全。各地区各有关部门要进一步完善春运工作协调机制，科学调度各类运力资源，强化铁路、公路、水路、民航、城市公共交通等的协同衔接，保障“两节”运力供给。加强票源信息、运行时刻、出行提示等出行信息服务，针对学生、外来务工人员开展特色购票服务。加强运输安全监管，严查超速、超载、疲劳驾驶、酒后驾驶等交通违法行为，加强交通疏导管控，针对可能出现的极端恶劣天气和旅客滞留等突发情况，做好应急处置各项准备工作，防止大规模交通拥堵和人员伤亡事故发生。\n四、切实抓好安全生产工作，着力维护社会和谐稳定。各地区各有关部门要严格落实安全生产责任，集中深入开展事故隐患排查治理和安全生产监督检查，重点强化对烟花爆竹产运储销和燃放等环节的安全监管，加强重点场所消防安全检查，严格落实人员密集场所和大型群众性活动安全防范措施，认真抓好煤矿等重点行业安全专项整治，有效防范各类生产安全事故和重特大火灾事故。集中开展矛盾纠纷排查化解，依法妥善解决群众反映强烈的突出问题。强化社会面巡逻防控，严厉打击“两抢一盗”、电信诈骗等多发性侵财犯罪和各种严重暴力犯罪。深化严打暴恐活动专项行动，强化重点地区、重点部位治安管控，严防暴力恐怖袭击事件发生。做好重大流行性疾病等公共卫生事件防范应对。\n五、坚持务实节俭文明过节，严禁年底突击花钱。各级党政机关和党员干部要带头落实中央八项规定精神，严格财经纪律，勤俭过节、文明过节，不得以任何名义年终突击花钱和滥发津贴、补贴、奖金和实物，不得用财政性资金举办年会、经营性文艺晚会，不得以各种借口违反中央八项规定精神。按照中央八项规定精神和反对“四风”的要求，务实节俭组织好正常的党团、工会活动，开展好年终走访慰问生活困难党员、老党员、老干部和军队离退休干部、烈军属及企业困难职工等活动，保障干部职工按规定享有的正常福利待遇。加强舆论引导，畅通监督渠道，积极营造节俭文明过节氛围。\n六、严格执行廉洁从政各项规定，坚决杜绝“节日腐败”。各级领导干部要持续深入反对“四风”，严禁用公款搞相互走访、送礼、宴请等拜年活动，严禁用公款吃喝、旅游和参与高消费娱乐健身活动，严禁出入私人会所、借培训中心奢侈浪费，严禁用公款购买赠送贺年卡及烟花爆竹等年货节礼，严禁用公款接待走亲访友、外出旅游等非公务活动，严禁利用婚丧喜庆敛财，严禁违规收受礼品、礼金和各种有价证券、支付凭证、商业预付卡、电子红包，严禁参与各种形式的赌博活动，严禁公车私用，严禁将相关费用转嫁给国有企业、民营企业。各级纪检监察机关要加大惩戒问责力度，对违规违纪行为严查快处，在追究直接责任人责任的同时，严肃追究相关领导的主体责任和监督责任，问题典型、突出的点名道姓通报曝光。\n七、认真做好值守应急工作，确保各项工作正常运转。各地区各部门要强化岗位责任制，严格执行24小时专人值班和领导带班制度。健全应急协调机制，畅通信息报送渠道，遇有突发事件或重要紧急情况要立即请示报告，并及时采取有效措施妥善应对和处置。公安、消防、医院、气象、银行、供水、供暖、供电、供气等直接服务群众的窗口单位，要安排好节日值班，加强值班力量，确保提供优质高效服务。\n各地区各部门要认真贯彻本通知精神，并统筹做好岁末年初各项工作，确保把中央决策部署落到实处。","level":0}]},{"id":"r0606","sections":[{"name":"关于加强和改进流动党员管理工作的意见","text":"随着我国改革开放的不断深入和社会主义市场经济体制的不断完善，各类人员在产业之间转移和地区之间流动日益频繁，其中有不少是共产党员。加强和改进流动党员管理，是新形势下保持共产党员先进性、提高党的执政能力的一项重要任务。为进一步做好这项工作，根据《中国共产党章程》和党内有关规定，提出如下意见。","level":1},{"name":"一、总体要求和主要原则","text":"流动党员是指由于就业或居住地变化等原因，在较长时间内无法正常参加正式组织关系所在党组织活动的党员。\n（一）加强和改进流动党员管理工作的总体要求：要坚持以马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想为指导，全面落实科学发展观，贯彻党要管党、从严治党的方针，从有利于党组织管理、有利于流动党员发挥作用出发，创新管理方式，落实管理责任，努力使流动党员都能接受党组织的教育和管理，始终保持先进性。\n（二）加强和改进流动党员管理工作的主要原则：\n1．坚持以流入地党组织为主、流出地和流入地党组织共同管理。构建流出地与流入地党组织密切配合、有机衔接的流动党员管理机制。\n2．坚持区别情况、动态管理。根据流动党员的分布状况、职业特点和居住地点等情况，采取单位管理、行业管理和社区管理等多种方式，努力做到党员流动到哪里，党组织的管理就覆盖到哪里。\n3．坚持教育、管理与服务相结合。强化服务意识，寓教育、管理于服务之中，增强流动党员的党性观念、组织观念和光荣感、归属感与责任感。","level":1},{"name":"二、党组织在流动党员管理工作中的主要责任和对流动党员的基本要求","text":"（一）流出地党组织的主要责任\n流出地党组织要了解掌握外出流动党员情况，加强与流入地党组织的联系，配合流入地党组织共同做好流动党员外出期间的教育管理工作。\n1．在党员外出前进行教育并提出要求，按规定登记并发放《流动党员活动证》。\n2．掌握外出党员的流动去向、外出时间、地点和联系方式等情况。\n3．了解党员外出后的思想、就业和生活等情况，及时向外出流动党员通报党组织的重要情况，通知外出流动党员按规定参加党内选举等重要活动。\n4．外出流动党员返回后，认真查验《流动党员活动证》等有关材料，及时了解党员外出期间的表现和参加党的组织生活情况。\n5．了解预备党员外出期间的表现，按规定做好预备党员转正工作。\n（二）流入地党组织的主要责任\n流入地党组织对流动党员管理负有主要责任，要加强与流出地党组织的联系，把流动党员纳入本地党员教育管理的整体工作中。\n1．认真查验《流动党员活动证》，做好外来流动党员身份确认工作。\n2．加强对外来流动党员的经常性教育和管理，将外来流动党员编入党的一个基层组织，组织他们参加党的组织生活。\n3．关心外来流动党员，为他们的就业、学习和生活提供必要帮助。\n4．在《流动党员活动证》上如实填写党员参加组织生活、交纳党费等情况，及时将外来流动党员的重要情况反馈给流出地党组织。\n5．做好外来流动人员中预备党员的教育和管理工作。\n（三）对流动党员的基本要求\n流动党员要认真履行党员义务，正确行使党员权利，在流入地参加党的日常组织生活，在正式组织关系所在党组织参加选举等重要活动，自觉接受流出地和流入地党组织的教育和管理，发挥先锋模范作用。\n1．外出前，应向所在党支部报告外出事由、时间、地点及联系方式，领取《流动党员活动证》。\n2．凭《流动党员活动证》及时到流入地党组织报到，积极参加党的组织生活，按规定交纳党费，完成党组织交给的任务。流动党员原则上应当按月交纳党费，因外出地点变动频繁等原因按月交纳确有困难的，可以按季交纳。\n3．主动与流出地党组织保持联系，每年至少向流出地党组织汇报一次外出期间思想、工作和参加党的组织生活情况。外出地点、就业单位、居住地和联系方式等发生变化时，应及时向流出地党组织和有关党组织报告。\n4．外出返回后，及时将《流动党员活动证》交给流出地党组织查验，如实向党组织汇报外出期间的情况。","level":1},{"name":"三、改进流动党员管理方法","text":"（一）完善流动党员组织关系管理。流动党员一般应当持《流动党员活动证》。简化《流动党员活动证》发放手续，《流动党员活动证》经流出地党的基层委员会盖章后，由党支部登记发放。流入地党支部要及时验证并报上级党组织备案。《流动党员活动证》由流动党员正式组织关系所在党支部或组织生活所在党支部每年审核一次。流动党员无正当理由不及时办理组织关系转接事宜、长期不与流入地和流出地党组织联系的，党组织要进行批评教育，经教育仍不改正的，其正式组织关系所在党组织要按党章及党内有关规定进行组织处理。\n（二）及时将流动党员编入流入地党的基层组织。流动党员就业单位有党组织的，应当编入其就业单位党组织；就业单位没有党组织的，可以就近就便编入所在社区（村）党组织或其他单位党组织，也可依托商会、行业协会等单位的党组织进行管理。在流动党员较为集中的社区（村）、项目工地、商务楼宇和集贸市场等，可专门建立流动党员党组织。流出地党组织可在外出流动党员相对集中的地方建立党组织，依托驻外办事机构党组织或委托流入地党组织进行管理，条件成熟后移交流入地党组织管理和领导。\n（三）探索利用现代技术手段加强对流动党员的管理。有条件的地方党委组织部门要通过建立流动党员信息库等方式，及时掌握本地区外出和外来流动党员的基本情况。","level":1},{"name":"四、切实加强组织领导","text":"各级党委特别是县（市、区、旗）党委要把加强和改进流动党员管理工作摆上重要议事日程，纳入基层党建工作责任制，切实加强领导和指导。党委组织部门要与政府有关部门加强沟通和协作，定期通报和研究流动党员管理工作。有关部门在流动人员登记备案中，要增加“政治面貌”内容。要通过多种渠道解决流动党员管理工作所需经费和场所问题。\n要坚持以人为本，强化基层党组织的服务功能，有条件的地方可建立街道（乡镇）、社区（村）党员服务站（点），积极为流动党员提供就业、培训和权益保障等方面的服务。\n要加强对流动党员管理工作的督促检查。对在流动党员管理工作中不负责任、推诿扯皮的，要对有关责任人给予教育帮助，情节严重的，要作出必要的组织处理。市、县党委组织部门每年底要逐级上报流动党员管理工作情况。各省、自治区、直辖市党委组织部门每年要组织一次抽查。\n要鼓励创新并及时总结推广好的经验和做法，不断探索加强和改进流动党员管理的有效途径。\n延伸阅读：\n中共中央办公厅印发《关于加强党员经常性教育的意见》等四个保持共产党员先进性长效机制文件的通知","level":1}]},{"id":"r0607","sections":[{"name":"公务员申诉规定","text":"公务员申诉规定\n（2008年5月14日中共中央组织部、人力资源社会保障部制定并发布 2022年3月1日中共中央组织部部务会会议修订 2022年3月19日中共中央组织部发布）","level":1},{"name":"第一章 总 则","text":"第一条 为了依法处理公务员申诉，保障公务员合法权益，建设信念坚定、为民服务、勤政务实、敢于担当、清正廉洁的高素质专业化公务员队伍，根据《中华人民共和国公务员法》等有关法律法规，制定本规定。\n第二条 公务员对涉及本人的人事处理不服，可以依照本规定申请复核或者提出申诉。\n法律法规对监察官、法官、检察官的申诉另有规定的，从其规定。\n领导成员公务员的申诉，按照有关规定办理。\n第三条 公务员申诉工作坚持以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想为指导，贯彻落实新时代党的组织路线和干部工作方针政策，完善机关内部监督机制，促进机关依法行使职权，规范公务员依法维权，坚持下列原则：\n（一）依法依规、有错必纠；\n（二）公平公正、处理恰当；\n（三）稳慎及时、注重沟通。\n第四条 复核、申诉期间，人事处理继续执行。\n公务员不因申请复核或者提出申诉而被加重处理。","level":1},{"name":"第二章 机构与管辖","text":"第五条 受理公务员申诉的机关应当组成公务员申诉公正委员会，负责对案件事实、适用法律法规、工作程序等进行审议，向受理机关提出审理意见。\n公务员申诉公正委员会实行一案一委员会制，一般由受理机关的人员组成，可以吸收其他机关的有关人员参加。公务员申诉公正委员会组成人数为单数，设主任委员一名，负责案件审理的组织工作。\n第六条 公务员对本人所在机关作出的人事处理不服的申诉，由同级公务员主管部门管辖。\n省级以下机关公务员对公务员主管部门作出的申诉处理决定不服的再申诉，由同级党委或者上一级公务员主管部门管辖。其中，对省、自治区、直辖市公务员主管部门作出的申诉处理决定不服的再申诉，由省、自治区、直辖市党委管辖。地方党委受理的再申诉，由党委指定的部门负责组建公务员申诉公正委员会开展案件审理工作。\n第七条 县级以下机关公务员对经县级党委批准或者乡镇党委作出的人事处理不服的申诉，由上一级公务员主管部门管辖。\n第八条 中央垂直管理部门省级以下机关公务员对人事处理不服的申诉，由上一级机关管辖。对申诉处理决定不服的再申诉，由作出申诉处理决定的机关的上一级机关管辖。\n第九条 实行双重领导并以上级单位领导为主的部门省级以下机关、省以下垂直管理部门公务员申诉的管辖，参照本规定第八条的规定执行。对省垂直管理机关作出的申诉处理决定不服的再申诉，由省、自治区、直辖市党委管辖。\n第十条 公务员对监察机关作出的涉及本人的处理决定不服的，向监察机关申请复审、复核。","level":1},{"name":"第三章 申请与受理","text":"第十一条 公务员对涉及本人的下列人事处理不服，可以申请复核或者提出申诉：\n（一）处分；\n（二）辞退或者取消录用；\n（三）降职；\n（四）定期考核定为不称职；\n（五）免职；\n（六）申请辞职、提前退休未予批准；\n（七）不按照规定确定或者扣减工资、福利、保险待遇；\n（八）法律、法规规定可以申诉的其他情形。\n第十二条 公务员申请复核，应当自知道该人事处理之日起30日内向原人事处理机关提交书面申请。在复核决定作出前，申请复核的公务员不得提出申诉。复核决定逾期未作出的，申请复核的公务员可以在复核期满之日起15日内提出申诉。\n第十三条 公务员对复核结果不服的，可以自接到复核决定之日起15日内提出申诉；也可以不经复核，自知道人事处理之日起30日内直接提出申诉。\n公务员对申诉处理决定不服的，可以自接到申诉处理决定之日起30日内提出再申诉。\n第十四条 公务员提出申诉和再申诉，应当提交申诉书等材料，提出再申诉的，还应当提交申诉处理决定复印件。\n申诉书应当载明下列内容：\n（一）申诉人的姓名、单位、职务职级、联系方式、住址及其他基本情况；\n（二）被申诉机关的名称及作出的人事处理决定和复核的情况；\n（三）申诉的事项、理由及要求；\n（四）提出申诉的日期。\n第十五条 因不可抗力等正当理由超过规定的期限申请复核或者提出申诉、再申诉的，经受理机关批准可以提出申请。\n第十六条 复核、申诉、再申诉应当由受到人事处理的公务员本人提出；如本人丧失行为能力或者死亡，可以由其配偶、父母、子女、兄弟姐妹等近亲属代为提出。\n第十七条 受理机关应当对申请人提出的申诉、再申诉是否符合受理条件进行审查，在接到申诉书之日起30日内，作出受理或者不予受理的决定，并以书面形式通知申请人。不予受理的，应当说明理由。\n第十八条 符合以下条件的申诉、再申诉，应予受理：\n（一）申请人符合本规定第十六条的规定；\n（二）申诉、再申诉事项属于本规定第十一条规定的受理范围；\n（三）在规定的期限内提出；\n（四）属于受理机关管辖；\n（五）申诉材料齐备。\n凡不符合上述条件之一的申诉、再申诉，不予受理。\n申诉材料不齐备的，应当及时一次性告知申请人，限期15日内补正。审查期限自收到全部补正材料后的次日起算。\n第十九条 对于决定受理的申诉案件，受理机关自决定受理之日起7日内向被申诉机关送达应诉通知书和申诉书副本。\n被申诉机关接到应诉通知书之日起15日内提交答辩书，并提供作出该人事处理决定的依据和证据。\n受理机关收到答辩书后，经审核符合答辩要求的，在7日内将副本送达申诉人，申诉人在接到答辩书副本7日内可以提出书面意见。\n第二十条 处理决定作出前，申请人可以书面提出撤回复核、申诉和再申诉的申请。受理机关在接到申请后终结处理工作，并书面告知申请人和被申诉机关。\n申请人撤回复核、申诉和再申诉后，如无正当理由，不得再以同一事由提出。","level":1},{"name":"第四章 审理与决定","text":"第二十一条 原人事处理机关在接到复核申请书后，应当对人事处理认定的事实、依据和工作程序等进行全面核查，在30日内作出维持、撤销或者变更原人事处理的复核决定，并书面通知申请人。\n第二十二条 受理申诉和再申诉的机关应当自决定受理之日起60日内作出处理决定。案情复杂的，可以适当延长，但是延长时间不得超过30日。\n第二十三条 受理机关对公务员申诉、再申诉涉及事项，应当调查核实。调查应当由2名以上工作人员进行。接受调查的机关和个人应当如实提供情况。\n调查人员应当充分听取申诉人、被申诉机关和相关人员的意见，加强沟通协调，做好政策解释和矛盾调处工作。\n第二十四条 受理机关应当将申诉案件材料和调查材料提交公务员申诉公正委员会进行全面审阅。必要时，公务员申诉公正委员会可以听取申诉人和被申诉机关当面陈述申辩。\n第二十五条 公务员申诉公正委员会根据调查情况对下列事项进行审议：\n（一）原人事处理认定的事实是否存在、清楚，证据是否确凿、充分；\n（二）原人事处理适用法律、法规、规章和有关规定是否正确；\n（三）原人事处理的程序是否符合规定；\n（四）原人事处理是否显失公正；\n（五）被申诉机关有无超越职权或者滥用职权的情形；\n（六）其他需要审议的事项。\n在审理对复核决定、申诉处理决定不服的申诉、再申诉时，还应当对复核决定和申诉处理决定进行审议。\n第二十六条 公务员申诉公正委员会应当按照少数服从多数的原则提出明确审理意见，并向受理机关提交审理报告。审议中的不同意见应当如实记入审理报告。\n第二十七条 对于事实清楚、规定明确的申诉案件，调查、审理程序可以适当简化。\n第二十八条 受理机关应当根据公务员申诉公正委员会的审理意见，区别不同情况，作出下列申诉处理决定：\n（一）原人事处理认定事实清楚，适用法律、法规、规章和有关规定正确，处理恰当、程序合法的，维持原人事处理。\n（二）原人事处理认定事实不存在的，按照管理权限责令原人事处理机关撤销或者直接撤销原人事处理。\n（三）原人事处理认定事实清楚，但适用法律、法规、规章和有关规定有误，或者处理明显不当的，按照管理权限责令原人事处理机关变更或者直接变更原人事处理。\n（四）原人事处理认定事实不清，证据不足，或者违反规定程序和权限的，责令原人事处理机关重新处理。\n再申诉处理决定应当参照前款规定作出。\n受理机关在作出申诉处理决定的同时，可以就申诉案件向原人事处理机关提出人事管理有关意见。\n第二十九条 申诉处理决定作出后，要制作申诉处理决定书。申诉处理决定书应当载明下列内容：\n（一）申诉人的姓名、单位、职务职级及其他基本情况；\n（二）被申诉机关的名称，原人事处理和复核决定所认定的事实、理由及适用的法律、法规、规章和有关规定；\n（三）申诉的事项、理由及要求；\n（四）公务员申诉公正委员会认定的事实、理由及适用的法律、法规、规章和有关规定；\n（五）申诉处理决定；\n（六）作出决定的日期；\n（七）其他需要载明的内容。\n再申诉处理决定书除前款规定内容外，还应当载明申诉处理决定的内容和作出申诉处理决定的日期。\n申诉处理决定书和再申诉处理决定书应当加盖受理机关或者公务员申诉公正委员会的印章。\n第三十条 申诉处理决定书应当在作出处理决定之日起7日内送达申诉人和原人事处理机关。再申诉处理决定书还应当送达作出申诉处理决定的机关。\n第三十一条 原人事处理机关应当将复核决定书、申诉处理决定书、再申诉处理决定书存入受处理公务员个人档案。\n申诉处理机关应当自作出处理决定之日起60日内，将申诉案件处理和执行等情况按照管理权限向上一级公务员主管部门或者上一级机关备案。\n第三十二条 公务员申诉公正委员会委员和受理机关工作人员与案件当事人存在利害关系、可能影响案件公正处理的，本人应当自行回避。申诉人和被申诉机关也可以申请相关人员回避，受理机关在收到回避申请之日起3个工作日内作出决定。回避决定作出前，相关人员暂停参与调查和审理。\n第三十三条 案件审理期间，因不可抗力等原因导致无法审理的，受理机关可以决定中止审理工作，待有关情形消除后，再恢复审理工作。\n第三十四条 公务员申诉公正委员会委员和受理机关工作人员，对工作中涉及的国家秘密、工作秘密、商业秘密和个人隐私应当保密。","level":1},{"name":"第五章 执行与监督","text":"第三十五条 申诉处理决定在发生效力后执行。\n下列处理决定是发生效力的决定：\n（一）已过法定期限没有提出再申诉的申诉处理决定；\n（二）中央公务员主管部门作出的申诉处理决定；\n（三）中央垂直管理机关作出的申诉处理决定；\n（四）再申诉处理决定。\n第三十六条 原人事处理机关在申诉处理决定生效后30日内执行，并将执行情况书面告知作出申诉处理决定的机关。\n第三十七条 非因违反规定程序和权限，被责令重新处理的，原人事处理机关不得以同一事实和理由作出与原处理决定相同或者基本相同的处理决定。\n公务员对重新作出的人事处理决定不服，可以提出申诉、再申诉。\n第三十八条 原人事处理错误的，应当及时予以纠正；造成名誉损害的，应当赔礼道歉、恢复名誉、消除影响；造成经济损失的，依法给予赔偿，并视情况对作出错误处理的责任人进行处理。\n第三十九条 机关不执行发生效力的申诉处理决定，或者对申诉人打击报复的，对负有责任的领导人员和直接责任人员，受理申诉的机关可以向有关机关提出给予其处理处分的建议；构成犯罪的，依法追究刑事责任。\n第四十条 公务员在复核、申诉中捏造事实，诬告、陷害他人的，根据情节轻重，给予批评教育或者处分；给他人造成名誉损害的，应当赔礼道歉、恢复名誉、消除影响；构成犯罪的，依法追究刑事责任。\n第四十一条 公务员申诉公正委员会委员和受理机关工作人员，不按本规定处理公务员复核、申诉的，根据情节轻重，给予批评教育或者处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第四十二条 参照公务员法管理的机关（单位）中除工勤人员以外的工作人员的申诉，参照本规定执行。\n第四十三条 本规定由中共中央组织部负责解释。\n第四十四条 本规定自发布之日起施行。\n附件：1.公务员申诉案件受理通知书\n2.公务员申诉案件不予受理通知书\n3.公务员申诉案件应诉通知书\n[点击下载表格]","level":1}]},{"id":"r0608","sections":[{"name":"中央组织部、财政部联合下发通知 要求各地区各相关部门做好党员支持新冠肺炎疫情防控自愿捐款资金分配使用工作","text":"坚决打赢疫情防控阻击战","level":1},{"name":"","text":"近日，中共中央组织部、财政部联合下发通知，对各地区各相关部门做好党员自愿捐款资金分配使用工作作出安排。\n通知指出，新冠肺炎疫情发生以来，以习近平同志为核心的党中央始终把人民群众生命安全和身体健康放在第一位，全面加强对疫情防控的集中统一领导。为示范推动各级党组织和广大党员尽快行动起来，习近平总书记和中央政治局其他常委同志带头捐款，以身作则、以上率下，支持新冠肺炎疫情防控工作。全国各地区各部门各行业广大党员踊跃捐款、慷慨奉献，表达了对疫区人民的深情关怀，展现了新时代共产党员在危难时刻的责任担当。\n通知明确，党员捐款资金体现慰问性质，主要用于慰问战斗在疫情斗争第一线的医务人员、基层干部、公安民警、社区工作者、志愿者和新闻工作者等，其中重点慰问一线医务人员。对在疫情防控斗争中牺牲的干部群众家属也应予以重点慰问。根据疫情实际和需要，党员捐款资金重点向疫情最严重的湖北省倾斜。\n通知强调，各地区各相关部门要尽快摸清慰问资助对象底数，研究确定各类慰问资助对象的发放档次和标准，精心组织，及时将党员捐款资金发放到人，把以习近平同志为核心的党中央和广大党员的支持和关怀送到慰问资助对象手中。\n根据有关要求，中央组织部已将截至目前上缴的党员捐款52.8亿元，转交财政部分配下达。\n延伸阅读\n图解：党员自愿捐款资金如何分配使用","level":0}]},{"id":"r0609","sections":[{"name":"关于党的基层组织任期的意见","text":"近日，中共中央办公厅印发了《关于党的基层组织任期的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于党的基层组织任期的意见》全文如下。\n党的十九大党章修正案规定：“党的基层委员会、总支部委员会、支部委员会每届任期三年至五年。”为贯彻落实党章规定，严肃党内政治生活，严格党的组织制度，完善党的基层组织任期，现提出如下意见。\n一、党的基层委员会每届任期一般为5年，党的总支部委员会、支部委员会每届任期一般为3年，其中，村和社区党的委员会、总支部委员会、支部委员会每届任期为5年。\n本意见印发前已换届的党的基层组织，原则上从本届任期届满后，开始执行上述规定。\n二、党的基层组织应严格执行任期制度，任期届满按期进行换届选举。如需延期或提前进行换届选举，应报上级党的委员会批准，延长或提前期限一般不超过1年。\n三、各地区各部门各单位党委（党组）要高度重视，加强组织领导，确保党的基层组织任期调整统一规范、平稳衔接。根据党组织隶属关系和干部管理权限，上级党组织要切实负起责任，认真做好基层党组织领导班子调整配备等相关换届准备工作，及时提醒督促按期换届。\n四、中国人民解放军、中国人民武装警察部队党的基层组织任期，由中央军委规定。\n五、本意见自发布之日起施行。其他有关党的基层组织任期的规定，凡与本意见不一致的，按照本意见执行。\n延伸阅读\n图解：十九大之后 党的基层组织任期发生了哪些具体变化？","level":0}]},{"id":"r0610","sections":[{"name":"中共中央办公厅印发《关于建立中小学校党组织领导的校长负责制的意见（试行）》","text":"近日，中共中央办公厅印发了《关于建立中小学校党组织领导的校长负责制的意见（试行）》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"通知指出，加强党对教育工作的全面领导是办好教育的根本保证。建立中小学校党组织领导的校长负责制，是坚持为党育人、为国育才，保证党的教育方针和党中央决策部署在中小学校得到贯彻落实的必然要求。\n通知要求，各地区各有关部门要认真贯彻落实本意见精神，加强组织领导和工作指导，切实把这项工作抓紧抓好。要在深入总结试点工作基础上，健全发挥中小学校党组织领导作用的体制机制，确保党组织履行好把方向、管大局、作决策、抓班子、带队伍、保落实的领导职责。要把党建工作作为办学治校的重要内容，发挥基层党组织作用，加强党员队伍建设，使基层党组织成为学校教书育人的坚强战斗堡垒。要把思想政治工作紧紧抓在手上，深入开展社会主义核心价值观教育，抓好学生德育工作，把弘扬革命传统、传承红色基因深刻融入学校教育，厚植爱党、爱国、爱人民、爱社会主义的情感，努力培养德智体美劳全面发展的社会主义建设者和接班人。要加强分类指导、分步实施，针对不同类型、不同规模的学校，在做好思想准备、组织准备、工作准备的前提下，成熟一个调整一个，推动改革落到实处。贯彻落实中的重要事项，要及时向党中央请示报告。\n《关于建立中小学校党组织领导的校长负责制的意见（试行）》全文如下。\n为全面贯彻新时代党的组织路线和党的教育方针，坚持和加强党对中小学校的全面领导，根据党章和有关党内法规、国家法律，现就建立中小学校党组织领导的校长负责制提出如下意见。","level":0},{"name":"一、发挥中小学校党组织领导作用","text":"（一）中小学校党组织全面领导学校工作，履行把方向、管大局、作决策、抓班子、带队伍、保落实的领导职责。\n1.坚持以习近平新时代中国特色社会主义思想为指导，增强“四个意识”、坚定“四个自信”、做到“两个维护”，贯彻党的基本理论、基本路线、基本方略，坚持为党育人、为国育才，确保党的教育方针和党中央决策部署在中小学校得到切实贯彻落实。\n2.坚持把政治标准和政治要求贯穿办学治校、教书育人全过程各方面，坚持社会主义办学方向，落实立德树人根本任务，团结带领全校教职工推动学校改革发展，培养德智体美劳全面发展的社会主义建设者和接班人。\n3.讨论决定事关学校改革发展稳定及教育教学、行政管理中的“三重一大”事项和学校章程等基本管理制度，支持和保证校长依法依规行使职权。\n4.坚持党管干部原则，按照有关规定和干部管理权限，负责干部的教育、培训、选拔、考核和监督。讨论决定学校内部组织机构的设置及其负责人的人选，协助上级党组织做好学校领导人员的教育管理监督等工作。\n5.坚持党管人才原则，按照有关规定做好教师等人才的培养、招聘、使用、管理、服务和职称评审、奖惩等相关工作。\n6.开展社会主义核心价值观教育，抓好学生德育工作，做好教职工思想政治工作和学校意识形态工作，加强师德师风建设和学校精神文明建设，推动形成良好校风教风学风。\n7.加强学校各级党组织建设和党员队伍建设工作，严格执行“三会一课”等党的组织生活制度，发挥基层党组织战斗堡垒作用和党员先锋模范作用。\n8.坚持全面从严治党，领导学校党的纪律检查工作，落实党风廉政建设主体责任。\n9.领导工会、共青团、妇女组织、少先队等群团组织和教职工大会（教职工代表大会），强化党建带团建、队建，加强学生会和学生社团管理，做好统一战线工作。\n10.讨论决定学校其他重要事项。\n（二）学校党组织实行集体领导和个人分工负责相结合的制度。凡属重大问题都要按照集体领导、民主集中、个别酝酿、会议决定的原则，由党组织会议集体讨论作出决定。党组织班子成员根据集体的决定和分工，切实履行职责。\n（三）学校党组织书记主持党组织全面工作，负责组织党组织重要活动，督促检查党组织决议贯彻落实，督促党组织班子成员履行职责、发挥作用。","level":1},{"name":"二、支持和保证校长行使职权","text":"（四）校长在学校党组织领导下，依法依规行使职权，按照学校党组织有关决议，全面负责学校的教育教学和行政管理等工作。\n1.研究拟订和执行学校发展规划、基本管理制度、内部教育教学管理组织机构设置方案。研究拟订和执行具体规章制度、年度工作计划。\n2.组织开展教学活动和教育教学研究，加强教育教学管理，深化教育教学改革，负责招生、就业和学生学籍管理。\n3.加强学生德育、体育、美育、劳动教育和心理健康教育，提高学校思政课教学质量。组织开展学校文化活动和科学普及活动，建设文明校园。\n4.研究拟订和执行学校重大建设项目、重要资产处置、重要办学资源配置方案，管理和保护学校资产。\n5.研究拟订和执行学校年度预算、大额度支出，加强财务管理和审计监督。\n6.加强教师等各类人才日常教育管理服务工作，依据有关规定与教师以及内部其他工作人员订立、解除或终止聘用合同。\n7.做好学校安全稳定和后勤保障工作。\n8.组织开展学校对外交流与合作，加强学校与社会、家庭的联系，形成育人合力。\n9.向学校党组织报告重大决议执行情况，向教职工大会（教职工代表大会）报告工作，支持群团组织开展工作，依法保障师生员工合法权益。\n10.履行法律法规和学校章程规定的其他职权。","level":1},{"name":"三、建立健全议事决策制度","text":"（五）学校党组织会议讨论决定学校重大问题。党组织会议由党组织书记召集并主持，不是党组织班子成员的行政班子成员根据工作需要可列席会议。会议议题由学校领导班子成员提出，党组织书记确定。会议应当有半数以上党组织班子成员到会方能召开；讨论决定干部任免等重要事项时，必须有三分之二以上党组织班子成员到会。\n（六）校长办公会议（校务会议）是学校行政议事决策机构，研究提出拟由学校党组织讨论决定的重要事项方案，具体部署落实党组织决议的有关措施，研究处理教育教学、行政管理等工作。会议由校长召集并主持。会议成员一般为学校行政班子成员，不是行政班子成员的党组织班子成员可参加会议。会议议题由学校领导班子成员提出，校长确定。会议应当有半数以上行政班子成员到会方能召开。校长应当在广泛听取与会人员意见基础上，对讨论研究的事项作出决定。\n（七）学校党组织会议和校长办公会议（校务会议）要坚持科学决策、民主决策、依法决策。讨论决定学校重大问题，应当在调查研究基础上提出建议方案，经学校领导班子成员特别是党组织书记与校长充分沟通且无重大分歧后提交会议讨论决定。对涉及干部工作的方案，在提交党组织会议讨论决定前，应当在一定范围内进行充分酝酿。对事关师生员工切身利益的重要事项，应当通过教职工大会（教职工代表大会）或其他方式，广泛听取师生员工的意见和建议。对专业性、技术性较强的重要事项，应当经过专家评估及技术、政策、法律咨询。会议决定的事项如需变更、调整，应当按照决策程序进行复议。\n中小学校要结合实际，制定学校党组织会议、校长办公会议（校务会议）的会议制度和议事规则，并按管理权限报教育主管部门审查和备案。","level":1},{"name":"四、完善协调运行机制","text":"（八）实行中小学校党组织领导的校长负责制，必须发挥党组织领导作用，保证校长依法依规行使职权，建立健全党组织统一领导、党政分工合作、协调运行的工作机制。合理确定学校领导班子成员分工，明确工作职责。学校领导班子成员要认真执行集体决定，按照分工积极主动开展工作。\n（九）建立学校党组织书记和校长定期沟通制度。党组织书记和校长要及时交流思想、工作情况，带头维护班子团结。学校党组织会议、校长办公会议（校务会议）的重要议题，党组织书记、校长应当在会前听取对方意见，意见不一致的议题暂缓上会，待进一步交换意见、取得共识后再提交会议讨论。集体决定重大问题前，党组织书记、校长和有关领导班子成员要个别酝酿、充分沟通。\n（十）学校领导班子成员应当经常沟通情况、协调工作。学校党组织书记、校长要发扬民主，充分听取和尊重班子成员的意见，支持他们的工作。学校领导班子成员要相互理解、相互支持，对职责分工交叉的工作，注意协调配合，努力营造团结共事的和谐氛围。\n（十一）发挥教职工大会（教职工代表大会）和群团组织作用，健全师生员工参与民主管理和监督的工作机制。按照规定实行党务公开和校务公开，及时向师生员工、群团组织等通报学校工作情况。","level":1},{"name":"五、加强组织领导","text":"（十二）选好配强学校领导班子特别是党组织书记和校长。上级党组织要认真履行领导和把关作用，按照有关规定，严格标准条件和程序，精准科学选人用人，注重选拔党性强、懂教育、会管理、有威信、善于做思想政治工作的优秀党员干部担任学校党组织书记，着力培养政治过硬、品德高尚、业务精湛、治校有方的校长队伍。党组织设置为党委、党总支的中小学校，党组织书记、校长一般应当分设，党组织书记一般不兼任行政领导职务，校长是中共党员的应当同时担任党组织副书记；党组织设置为党支部的中小学校，党组织书记、校长一般由一人担任，同时应当设1名专职副书记；学校行政班子副职中的党员一般应当进入党组织班子。加强学校领导班子思想政治建设，完善培养选拔、教育培训、考核评价、激励保障机制，加强任期考核，推动学校领导人员履职尽责、潜心育人、清正廉洁。\n（十三）加强学校基层党组织和党员队伍建设。以提升组织力为重点，突出政治功能，优化基层党组织设置、创新活动方式，严格党员教育管理、严肃党的组织生活，推动党建工作与教育教学、德育和思想政治工作深度融合。加强对优秀教师的政治引领和政治吸纳，健全“双培养”机制。开展党组织书记抓基层党建工作述职评议考核。建立与中小学校党组织领导的校长负责制相适应的保障机制，健全党务工作机构，充实党务工作力量，落实党务工作队伍激励保障措施。集团化办学等类型的中小学校党组织要按照党组织隶属关系和办学实际，加强对成员学校、分支机构党建工作的领导和指导。\n（十四）建立和落实中小学校党组织领导的校长负责制执行情况报告制度，学校党组织要结合年度考核向上级党组织报告执行情况，学校领导班子成员要在民主生活会、述职评议、年度工作总结中报告个人执行情况。上级党组织和有关部门要将学校贯彻执行党组织领导的校长负责制情况作为巡察监督、教育督导的重要内容和对学校领导班子、领导人员考核评价的重要参考，对违反民主集中制原则，不执行学校党组织决议，或因班子内部不团结而严重影响工作的，按照有关规定追究相关人员责任，必要时对班子进行调整。\n（十五）地方各级党委要认真履行主体责任，党委组织、教育工作等部门要各司其职、密切配合，坚持分类指导、分步实施，稳慎推进建立中小学校党组织领导的校长负责制。针对不同类型、不同规模的学校，统筹领导班子调整、制度机制配套和学校章程修订等相关工作，在做好思想准备、组织准备、工作准备的前提下，成熟一个调整一个。通过教育培训、经验交流等方式，加强对中小学校贯彻执行党组织领导的校长负责制的工作指导，及时研究解决工作中出现的问题。\n本意见适用于具有独立法人资格且设立党的基层委员会、总支部委员会、支部委员会的公办中小学校（含中等职业学校），公办幼儿园参照执行，民办中小学校党的工作按照有关规定执行。不具有独立法人资格或未单独设立党的支部委员会的中小学校，党组织发挥战斗堡垒作用，履行党章和有关规定明确的职责任务。","level":1}]},{"id":"r0611","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于做好全国民族团结进步模范推荐评选工作的通知》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于做好全国民族团结进步模范推荐评选工作的通知》（以下简称《通知》）。《通知》指出，党中央、国务院决定，今年首次以党中央、国务院名义开展全国民族团结进步模范表彰。","level":1},{"name":"","text":"《通知》明确了推荐评选工作总体要求。要高举中国特色社会主义伟大旗帜，坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大以及中央民族工作会议精神，全面贯彻习近平总书记关于加强和改进民族工作的重要思想，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，坚持党对评选表彰工作的领导，坚持政治标准，突出铸牢中华民族共同体意识主线要求，突出实绩导向，认真总结2019年全国民族团结进步模范表彰以来，我国民族团结进步事业取得的成就和经验，评选表彰各地各行业涌现出的民族团结进步模范，广泛宣传先进事迹，引领各族人民坚定对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的高度认同，团结奋进新征程、积极建功新时代，为以中国式现代化全面推进强国建设、民族复兴伟业不懈奋斗。\n《通知》明确了推荐评选范围和条件。2019年以来为我国民族团结进步事业作出突出贡献的模范集体和模范个人均可被推荐，符合条件的已故人员可以追授。推荐对象应当在推动落实铸牢中华民族共同体意识各项任务、加强中华民族共同体建设中取得显著成绩。具体包括在构筑中华民族共有精神家园、深入开展铸牢中华民族共同体意识理论研究和宣传教育、推动民族地区实现高质量发展、维护国家统一和反对分裂、推动对口支援和东西部协作、促进各民族交往交流交融、推进民族事务治理体系和治理能力现代化、有效防范化解民族领域风险隐患、加强民族地区基层组织和政权建设以及其他方面作出突出贡献的集体和个人。\n《通知》明确了推荐评选程序和工作要求。要加强组织领导，精心组织实施，切实发挥党委（党组）领导和把关作用。要严格按照规定的标准、条件和程序，全面考察推荐对象的政治素质、主要实绩和群众认可情况，确保推荐对象的先进性、代表性和时代性。要充分发扬民主、广泛听取意见，注重群众评价，确保公开公平公正。","level":0}]},{"id":"r0612","sections":[{"name":"中办印发关于做好“光荣在党50年”纪念章颁发工作的通知","text":"近日，中共中央办公厅印发了《关于做好“光荣在党50年”纪念章颁发工作的通知》（以下简称《通知》）。《通知》指出，党中央决定，2021年首次颁发“光荣在党50年”纪念章。这项工作是中国共产党成立100周年庆祝活动的重要组成部分，对于增强党员的荣誉感、归属感、使命感，汇聚全党为实现“十四五”规划和2035年远景目标持续奋斗的磅礴力量，具有十分重要的意义。","level":1},{"name":"","text":"《通知》明确了“光荣在党50年”纪念章首次颁发对象，即颁发给健在的截至2021年7月1日党龄达到50周年、一贯表现良好的党员。要求各级党组织高度重视，结合本地区本部门本单位实际，认真做好统计、组织颁发等工作，确保每名符合条件的党员在7月1日前获颁纪念章，深切感受到以习近平同志为核心的党中央的关怀和温暖。\n“光荣在党50年”纪念章首次颁发以后，将作为一项经常性工作，一般每年“七一”集中颁发一次。日前，经党中央批准，中央组织部印发了《“光荣在党50年”纪念章颁发管理办法》，对纪念章的颁发程序、颁发方式、制作、管理等作出规定。\n延伸阅读\n谁能荣获“光荣在党50年”纪念章\n如何计算党员的党龄\n同志，快来领取“生日”卡\n奋斗百年路 启航新征程","level":0}]},{"id":"r0613","sections":[{"name":"中国共产党纪律检查机关案件检查工作条例","text":"第一章 总则","level":1},{"name":"","text":"第一条\n检查中国共产党内违纪案件是中国共产党的纪律检查机关的一项重要工作，是严肃党纪的中心环节。为使案件检查工作规范化、制度化，提高办案质量和效率，根据中国共产党章程有关规定，结合案件检查工作的实践，制定本条例。\n第二条\n案件检查工作的指导思想是，通过执纪办案，维护党的章程和其他党内法规，严肃党的纪律，加强党风廉政建设，保护改革开放，促进经济发展，保证党的基本路线的贯彻执行。\n第三条\n纪检机关依照党章和本条例行使案件检查权，不受国家机关、社会组织和个人的干涉。\n第四条\n案件检查必须坚持实事求是的原则，以事实为根据，以党纪为准绳，做到事实清楚，证据确凿，定性准确，处理恰当，手续完备。\n第五条\n案件检查要坚持在党的纪律面前人人平等的原则，对任何党员和党组织违犯党的纪律的行为，都必须依据本条例进行检查。\n第六条\n案件检查要依靠党的各级组织，走群众路线，加强纪检系统内部以及与有关部门的协调配合。\n第七条\n案件检查要贯彻惩前毖后、治病救人的方针，达到既维护党纪的严肃性，又教育本人和广大党员的目的。\n第八条\n案件检查中，要切实保障党员包括被检查的党员行使党章所赋予的各项权利。\n第九条\n案件检查实行分级办理、各负其责的工作制度。","level":0}]},{"id":"r0614","sections":[{"name":"中共中央办公厅印发《共青团中央改革方案》","text":"近日，中共中央办公厅印发了《共青团中央改革方案》。《方案》强调，共青团是党的助手和后备军，是党和政府联系青年的桥梁和纽带。推进共青团改革，是全面从严治党的一部分，是焕发共青团生机活力的重要举措。","level":1},{"name":"","text":"党的十八大以来，以习近平同志为总书记的党中央高度重视、亲切关心青少年和共青团工作，把共青团改革作为全面深化改革的重要方面作出战略谋划和部署。习近平总书记多次作出重要批示指示，为共青团中央改革指方向、定方针、提任务。中央政治局常委会会议、中央全面深化改革领导小组会议、中央书记处会议分别审议了《方案》。\n《方案》明确了共青团中央改革的指导思想、基本原则、主要目标。《方案》提出，要深入贯彻党的十八大和十八届三中、四中、五中全会精神，全面贯彻习近平总书记系列重要讲话特别是关于青少年和共青团工作的重要指示精神，深刻把握中国特色社会主义群团发展道路“六个坚持”的基本要求和“三统一”的基本特征，牢牢把握为实现中华民族伟大复兴中国梦而奋斗这一中国青年运动的时代主题，以保持和增强政治性、先进性、群众性为基本要求，着力解决存在的突出问题，增强自我革新的勇气，着力推进组织创新和工作创新，带领全团把广大青年紧密团结凝聚在党的周围，为协调推进“五位一体”总体布局和“四个全面”战略布局、实现“两个一百年”奋斗目标作贡献。共青团改革必须坚持党的领导、把准政治方向，坚持立足根本、围绕时代主题，坚持服务青年、直接联系青年，坚持问题导向、有效改进作风，坚持加强基层、支持基层创新，构建“凝聚青年、服务大局、当好桥梁、从严治团”的工作格局，更好团结带领青年发挥生力军和突击队作用，更好肩负起党交给共青团的光荣使命，紧跟党的步伐、走在群团改革前列。\n《方案》从四大方面、十二个领域提出了改革措施。第一，改进团中央领导机构人员构成、机构设置和运行机制。完善代表大会和委员会制度，增强团的代表大会、全委会、常委会的代表性，在团中央领导机构中明显提高基层和一线团干部、团员的比例；扩大代表大会代表的参与渠道，建立代表大会发言制度、团中央委员会向代表报告工作和听取意见建议制度、团代表走访团员青年制度；完善全委会委员议事建言机制，建立委员重点发言制度、委员提案制度；更好发挥常委会作用，提高决策科学化水平。改革优化机关职能和机构，实行工作力量“减上补下”，团中央精减机关行政编制，补充相应数量的挂职干部，带动省级团委根据实际情况适当精简编制、充实县级团委和直接服务青年的工作领域；改革团中央直属单位。改进团的领导体制和机关运行方式，完善双重领导体制；推动机关干部到基层一线开展工作，建立完善团中央机关干部常态化下沉基层、向基层服务对象报到工作机制，推动机关干部摆脱文山会海、走出高楼大院；建立扁平化、项目化工作机制，让青年了解团的历史、参与机关工作、增强主人翁意识、找到家的感觉。\n第二，改革团中央机关干部选拔、使用和管理。把团的岗位作为党政等各领域、各行业优秀年轻干部提高群众工作能力、培养群众工作作风、丰富群众工作经验的重要平台，坚持德才兼备、五湖四海，突出“知青少年、懂青少年、爱青少年”，不拘一格从党员、团员中选拔优秀人才，建设专职、挂职、兼职干部相结合，符合群团组织特点、充满生机活力的团中央机关干部队伍；改进机关干部选任交流，注重人岗相适，不搞年龄层层递减，从严选拔专职干部，挂职、兼职干部在机关所任职务从工作需要出发，不完全对应行政级别；完善机关干部综合考核评价机制，增加基层团组织和团员青年评价权重。加强机关干部作风建设，扎实开展“学党章党规、学系列讲话，做合格党员”学习教育，持续深入开展团干部健康成长教育，引导机关干部大部分工作时间到青年中去；全面加强党风廉政建设，严守党的政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律和生活纪律；建立团干部直接联系青年制度，每名专职、挂职团干部经常性联系100名左右不同领域的团员青年，兼职团干部直接联系10名左右普通青年，努力做到经常有声音、有互动、有话题、有线下活动、有面对面交流。\n第三，改革创新团的工作、活动和基层组织建设。把思想政治引领贯穿团的各项工作和活动，深入学习贯彻习近平总书记系列重要讲话精神，广泛开展中国特色社会主义和中国梦宣传教育，积极培育和践行社会主义核心价值观，切实担负起引导青年听党话、跟党走的政治任务。创新组织动员团员青年服务大局的载体和方式，团结动员广大青年认识、适应、引领经济发展新常态，积极践行创新、协调、绿色、开放、共享发展理念，参与供给侧结构性改革，立足本职岗位为“十三五”作贡献。提高服务青年和维护青少年合法权益的能力，推动出台面向青年的普惠性服务政策，推进基层服务型团组织建设，建立团内外资源区域化统筹配置机制，形成共青团工作品牌体系；更加注重直接服务普通青年，努力打造直接联系服务青少年的阵地依托，推动团的各级领导机关组织实施直接面向青年的重点服务项目，开设直接面向青年的活动场所，适应青年的作息特点合理安排工作时间，提升服务能力；改革创新青少年维权工作，构建“大权益”工作格局，明确维护青少年权益工作的对象和权责边界，更好发挥党委和政府联系青少年的桥梁纽带作用。大力实施“网上共青团”工程，以“智慧团建”和“青年之声”为重点，建设工作网、联系网、服务网“三网合一”的“网上共青团”，形成“互联网＋共青团”格局，实现团网深度融合、团青充分互动、线上线下一体运行。着力夯实基层基础，改进团员发展和教育管理，增强团员先进性光荣感，严格入团程序，加强团员意识教育，推动全体团员成为注册志愿者，充分发挥团员在青年中的模范作用和对青年的凝聚作用，在经济社会发展各项急难险重任务中当好生力军和突击队；改革创新团的基层组织设置，构建纵横交织的网络化组织体系；建设“团干部＋社工＋青年志愿者”队伍，充实基层工作力量；加强联系服务引导，把青年社会组织紧密团结起来。\n第四，加大党委和政府对共青团工作的支持保障力度。落实党建带团建制度，推动把团建纳入各级党委党建工作规划和年度考核内容，团建工作占一定比重；建立抓落实的督导机制，对省级落实党建带团建工作的情况进行定期检查；把“推荐优秀团员作入党积极分子人选”作为基层团组织的重要工作职责，推动党组织将推优纳入党员发展工作规划。健全政府协调工作机制，制定青年发展规划，各地制定相应规划，注重与经济社会发展规划及相关专项规划衔接；加强共青团和青年工作学科建设，推动把青年群众工作列入各类干部培训课程；健全稳定规范的共青团工作经费保障制度；加大对团的基层工作阵地建设支持力度，推动群团组织基层工作和服务阵地共建共享。\n《方案》要求，以团中央改革为牵引，加强统筹指导，带动地方各级、各领域共青团在党委领导下，结合工作实际谋划改革、推进改革，形成以上率下、全团抓改革的工作局面。\n延伸阅读\n团中央负责人就共青团改革答记者问\n人民日报评论员：建设更加充满活力更加坚强有力的共青团\n光明日报评论员：改革推动共青团事业大步向前","level":0}]},{"id":"r0615","sections":[{"name":"中共中央办公厅 国务院办公厅印发《建设高标准市场体系行动方案》","text":"近日，中共中央办公厅、国务院办公厅印发了《建设高标准市场体系行动方案》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《建设高标准市场体系行动方案》全文如下。\n建设高标准市场体系是加快完善社会主义市场经济体制的重要内容，对加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局具有重要意义。为深入贯彻党中央、国务院决策部署，构建更加成熟、更加定型的高水平社会主义市场经济体制，进一步激发各类市场主体活力，现就建设高标准市场体系制定以下行动方案。","level":0},{"name":"一、总体要求","text":"以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的十九大和十九届二中、三中、四中、五中全会精神，坚定不移贯彻新发展理念，坚持稳中求进工作总基调，以推动高质量发展为主题，以深化供给侧结构性改革为主线，以改革创新为根本动力，以满足人民日益增长的美好生活需要为根本目的，充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，牢牢把握扩大内需这个战略基点，坚持平等准入、公正监管、开放有序、诚信守法，畅通市场循环，疏通政策堵点，打通流通大动脉，推进市场提质增效，通过5年左右的努力，基本建成统一开放、竞争有序、制度完备、治理完善的高标准市场体系，为推动经济高质量发展、加快构建新发展格局、推进国家治理体系和治理能力现代化打下坚实基础。","level":1},{"name":"二、夯实市场体系基础制度","text":"（一）全面完善产权保护制度\n1.完善平等保护产权的法律法规体系。推进实施刑法修正案（十一），落实打击非公有制企业工作人员侵害企业财产权益等相关犯罪的规定，加强对非公有制经济财产权的刑法保护。出台实施关于审理专利授权确权行政案件若干问题的规定。完善专利法、著作权法相关配套法规。进一步细化完善国有产权交易各项制度。全面清理对不同所有制经济产权区别对待的法规。\n2.健全产权执法司法保护制度。启动第二批涉产权纠纷案件再审工作。完善涉企产权保护案件的申诉、复查、再审等机制。推动涉产权冤错案件依法甄别纠正常态化机制化。总结涉政府产权纠纷问题专项治理行动成功经验，研究建立常态化工作机制。严格规范公检法机关涉案财物处置程序，建立健全有效衔接的涉案财物处置制度体系。\n3.强化知识产权保护。推进实施审理侵犯商业秘密民事案件适用法律若干问题的规定，出台审理涉药品上市审评审批专利民事案件适用法律若干问题的规定。制定出台知识产权侵权惩罚性赔偿适用法律若干问题的解释，对恶意侵权、长时间持续侵权、商标侵权等行为，严格执行侵权惩罚性赔偿制度。探索建立知识产权侵权快速反应机制。做好商标代理管理办法、地理标志产品保护规定、官方标志保护办法等部门规章的制定修订工作。研究制定药品专利保护、跨境电商领域知识产权保护规则，编制发布企业知识产权保护指南和知识产权保护国别指南。优化专利、商标等申请和审查程序，提高审查效率，压缩审查时间。建立健全专利、商标等无形资产评估管理体系。\n4.健全农村集体产权制度。全面推开农村集体产权制度改革试点，完善农村集体产权确权和保护制度，分类建立健全集体资产清产核资、登记、保管、使用、处置制度和财务管理监督制度。规范农村产权流转交易，切实防止集体经济组织内部少数人侵占、非法处置集体资产，防止外部资本侵吞、非法控制集体资产。完善集体产权资产评估、流转交易、担保等综合服务体系，加强农村土地经营权流转规范管理和服务。\n（二）全面实施市场准入负面清单制度\n5.全面落实“全国一张清单”管理模式。严禁各地区各部门自行发布具有市场准入性质的负面清单。健全市场准入负面清单动态调整机制。建立覆盖省、市、县三级的市场准入隐性壁垒台账，畅通市场主体对隐性壁垒的意见反馈渠道和处理回应机制。制定市场准入效能评估标准并开展综合评估。\n6.开展放宽市场准入试点。制定出台海南自由贸易港、深圳建设中国特色社会主义先行示范区、横琴粤澳深度合作区放宽市场准入特别措施。选择符合条件的地区开展放宽市场准入试点。\n7.推进企业注销便利化。实施对未开业以及无债权债务非上市企业、个体工商户实行简易注销程序。完善企业注销网上服务平台，优化注销办理流程。建立企业破产案件简化审理模式，对资产数额不大、经营地域不广的企业实行简易破产程序。开展个人破产制度改革试点。\n（三）全面完善公平竞争制度\n8.增强公平竞争审查制度刚性约束。探索建立公平竞争审查举报处理和回应机制，及时核查举报涉及的问题。健全公平竞争审查机制，进一步明确和细化纳入审查范围的政策措施类别。出台公平竞争审查例外规定适用指南，建立例外规定动态调整和重大事项实时调整机制。研究制定行业性审查规则，进一步细化认定标准。\n9.加强和改进反垄断与反不正当竞争执法。坚决反对垄断和不正当竞争行为。制定原料药等专项领域反垄断指南、豁免制度适用指南，出台实施企业境外反垄断合规指引。推动完善平台企业垄断认定、数据收集使用管理、消费者权益保护等方面的法律规范。加强平台经济、共享经济等新业态领域反垄断和反不正当竞争规制。完善涉企收费目录清单制度，严厉查处涉企违规收费行为。\n10.破除区域分割和地方保护。完善市场竞争状况评估制度。鼓励各地区构建跨区域的统一市场准入服务系统，统一身份实名认证互认、统一名称自主申报行业字词库、统一企业经营范围库，实现跨区域注册登记无差别标准。除法律法规明确规定外，不得要求企业必须在某地登记注册，不得为企业跨区域迁移设置障碍。构建跨区域的市场监管案件移送、执法协助、联合执法机制，针对新型、疑难、典型案件，畅通会商渠道，互通裁量标准。","level":1},{"name":"三、推进要素资源高效配置","text":"（四）推动经营性土地要素市场化配置\n11.深化土地管理制度改革。加强对土地利用计划的管理和跟踪评估，完善年度建设用地总量调控制度，健全重大项目用地保障机制，实施“增存挂钩”，城乡建设用地指标使用应更多由省级政府负责。推进委托用地审批权试点，建立健全省级政府用地审批工作评价机制，根据各省（自治区、直辖市）土地管理水平综合评价结果，动态调整试点省份。\n12.完善建设用地市场体系。在符合国土空间规划和用途管制要求前提下，推动不同产业用地类型合理转换，探索增加混合产业用地供给。积极探索实施农村集体经营性建设用地入市制度。加快推进城乡统一的建设用地市场建设，统一交易规则和交易平台，完善城乡基准地价、标定地价的制定与发布制度，形成与市场价格挂钩的动态调整机制。\n13.开展土地指标跨区域交易试点。对城乡建设用地增减挂钩节余指标跨省域调剂政策实施评估，探索建立全国性的建设用地指标跨区域交易机制。改进完善跨省域补充耕地国家统筹机制，稳妥推进补充耕地国家统筹实施。在有条件的地方探索建立省域内跨区域补充耕地指标交易市场，完善交易规则和服务体系。\n（五）推动劳动力要素有序流动\n14.推动户籍准入年限同城化累计互认。除超大、特大城市外，在具备条件的都市圈或城市群探索实行户籍准入年限同城化累计互认，试行以经常居住地登记户口制度，有序引导人口落户。完善全国统一的社会保险公共服务平台，推动社保转移接续。加快建设医疗保障信息系统，构建全国统一、多级互联的数据共享交换体系，促进跨地区、跨层级、跨部门业务协同办理。\n15.提升人力资源服务质量。加快发展人力资源服务业，简化优化人力资源服务许可流程，加强人力资源市场事中事后监管。依托具备较强服务能力和水平的专业化人才服务机构、行业协会学会等社会组织，组建社会化评审机构，对专业性强、社会通用范围广、标准化程度高的职称系列，开展社会化职称评审。\n（六）促进资本市场健康发展\n16.稳步推进股票发行注册制改革。坚守科创板定位，突出“硬科技”特色，评估完善注册制试点安排，深化以信息披露为核心的股票发行注册制改革。完善投资者保护制度，建立与市场板块、产品风险特点相匹配的投资者适当性制度，鼓励和规范上市公司现金分红。加强资本市场监管，增强监管的全面性、一致性、科学性和有效性，提高监管透明度和法治化水平。监管不到位的金融改革举措不能贸然推出。坚持对违法违规行为零容忍，确保金融改革行稳致远。\n17.建立常态化退市机制。进一步完善退市标准，简化退市程序，畅通多元化退出渠道。严格实施退市制度，对触及退市标准的坚决予以退市，对恶意规避退市标准的予以严厉打击。\n18.培育资本市场机构投资者。稳步推进银行理财子公司和保险资产管理公司设立，鼓励银行及银行理财子公司依法依规与符合条件的证券基金经营机构和创业投资基金、政府出资产业投资基金合作，研究完善保险机构投资私募理财产品、私募股权基金、创业投资基金、政府出资产业投资基金和债转股的相关政策。提高各类养老金、保险资金等长期资金的权益投资比例，开展长周期考核。\n19.降低实体经济融资成本。健全市场化利率形成和传导机制，促进银行对贷款市场报价利率（LPR）的运用，引导督促金融机构合理定价，发挥好定向降准、再贷款、再贴现等货币政策工具的引导作用。积极稳妥发展普惠金融，积极稳妥推进金融产品和服务方式创新。加大“信易贷”模式推广力度，支持开展信用融资，拓展贷款抵押质押物范围。\n（七）发展知识、技术和数据要素市场\n20.创新促进科技成果转化机制。制定出台完善科技成果评价机制、促进科技成果转化的意见，提升技术要素市场化配置能力。修订发布技术合同认定规则及科技成果登记办法，加强对技术合同和科技成果的规范管理。完善国家技术转移体系，培育发展国家技术转移机构，建立国家技术转移人才培养体系，提高技术转移人员的技术评价与筛选、知识产权运营、商业化咨询等专业服务能力。\n21.健全职务科技成果产权制度。深入开展赋予科研人员职务科技成果所有权或长期使用权试点，探索职务科技成果产权激励新模式。适时总结试点经验，完善职务科技成果转化激励政策和科研人员职务发明成果权益分享机制。\n22.加快培育发展数据要素市场。制定出台新一批数据共享责任清单，加强地区间、部门间数据共享交换。研究制定加快培育数据要素市场的意见，建立数据资源产权、交易流通、跨境传输和安全等基础制度和标准规范，推动数据资源开发利用。积极参与数字领域国际规则和标准制定。\n23.设立知识产权和科技成果产权交易机构。支持中国技术交易所、上海技术交易所、深圳证券交易所等机构建设国家知识产权和科技成果产权交易机构，在全国范围内开展知识产权转让、许可等运营服务，加快推进技术交易服务发展。","level":1},{"name":"四、改善提升市场环境和质量","text":"（八）提升商品和服务质量\n24.完善质量管理政策措施。深入实施质量提升行动。进一步完善质量激励政策，建立政府质量奖获奖企业和个人先进质量管理经验宣传推广长效机制。完善企业产品和服务标准自我声明公开和监督制度。完善强制性产品认证制度，建立科学合理的认证目录动态调整机制。健全产品伤害监测与预防干预体系，完善缺陷产品召回制度、产品质量安全事故强制报告制度。\n25.优化企业标准“领跑者”制度。推动第三方评价机构发布一批企业标准排行榜，引导更多企业声明公开更高质量的标准。修订企业标准化管理办法，整合精简强制性标准。\n26.进一步发挥品牌的引领作用。加强农产品商标及地理标志商标的注册和保护。组织好中国品牌日活动，健全集体商标、证明商标注册管理制度，打造一批特色鲜明、竞争力强、市场信誉好的区域品牌。开展促进品牌消费、品质消费“双品网购节”活动。\n27.推动商品市场创新发展。建立重点市场联系机制，开展商品市场优化升级专项行动，培育一批商品经营特色突出、产业链供应链服务功能强大、线上线下融合发展的商品市场示范基地。\n（九）强化消费者权益保护\n28.加强消费维权制度建设。制定消费者权益保护法实施条例。健全消费者公益诉讼制度，探索建立消费者集体诉讼制度，在诉讼程序、庭审过程、举证责任等方面加强对消费者的司法保护。支持消费者协会行使公益性诉讼权利。\n29.简化消费争议处理程序。尽快明确小额消费纠纷的数额，完善小额消费纠纷司法程序，鼓励小额消费纠纷案件通过进入小额诉讼程序实现快速处理。完善消费纠纷在线解决机制，畅通投诉举报渠道，探索建立维权处理结果消费者反馈评价机制。\n（十）强化市场基础设施建设\n30.推动市场基础设施互联互通。持续完善综合立体交通网络。加强新一代信息技术在铁路、公路、水运、民航、邮政等领域的应用，提升综合运行效能。支持公共性快递分拣处理中心、智能投递设施等建设。打造一批物联网产业基地和物联网技术应用示范城市。持续支持中西部地区城乡结合部、县域和农村商贸基础设施建设和协同共享，畅通区域间、城乡间流通网络。\n31.实施智能市场发展示范工程。积极发展“智慧商店”、“智慧街区”、“智慧商圈”、“智慧社区”，建设一批智能消费综合体验馆。加大新型基础设施投资力度，推动第五代移动通信、物联网、工业互联网等通信网络基础设施，人工智能、云计算、区块链等新技术基础设施，数据中心、智能计算中心等算力基础设施建设。结合京津冀、粤港澳大湾区、长三角及海南自由贸易港等区域市场发展需求，针对跨境电商、跨境寄递物流、跨境支付和供应链管理等典型场景，构建安全便利的国际互联网数据专用通道和国际化数据信息专用通道。\n32.引导平台企业健康发展。支持平台企业创新发展，增强国际竞争力。实施教育、医疗、快递物流等网络基础设施改造提升工程，推动互联网医疗、在线教育、第三方物流、即时递送、在线办公、网上办事等新型服务平台发展，有效发挥平台企业在要素配置中的优化集成作用。畅通市场数据信息流，整合线上线下支付交易数据，推动实现跨部门共享。依法规范发展平台经济，强化对平台企业监管。\n33.培育发展能源商品交易平台。通过股份制改造、兼并重组等多种方式，在油气、电力、煤炭等领域积极培育形成运营规范、具有较大影响力的交易平台。支持上海期货交易所、全国电力交易机构、全国煤炭交易中心充分发挥作用，进一步健全交易机制、完善交易规则、严格监管标准。鼓励具备条件的资源型地区依托现有交易场所，探索建设区域性能源资源交易中心。","level":1},{"name":"五、实施高水平市场开放","text":"（十一）有序扩大服务业市场开放\n34.有序扩大金融服务业市场开放。支持社会资本依法进入银行、证券、资产管理、债券市场等金融服务业。允许在境内设立外资控股的合资银行、证券公司及外商独资或合资的资产管理公司。统筹规划银行间与交易所债券市场对外开放，优化准入标准、发行管理，明确中国债券市场对外开放的整体性制度框架，研究制定交易所债券市场境外机构债券发行管理办法。支持符合条件的民营金融机构和境内外资金融机构获得非金融企业债务融资工具A类主承销商资格，参与银行间债券市场。\n35.有序扩大社会服务业市场开放。以医疗、教育、体育、托幼、环保、市政等领域为重点，减少市场准入限制，取消对营利性医疗、教育等机构在证照办理、设备购置等方面的不合理限制。完善医疗机构设置规划方式，对社会办医疗机构实行指导性规划，加强对社会资本投资医疗机构的服务。\n36.完善外商投资准入前国民待遇加负面清单管理制度。进一步缩减外商投资准入负面清单，扩大鼓励外商投资产业目录范围，支持外资加大创新投入力度，营造内外资企业一视同仁、公平竞争的公正市场环境。抓好重大外资项目落地，破除各种市场准入隐性壁垒，打造市场化法治化国际化营商环境，提高外商投资服务水平。\n37.完善引导境外消费回流政策。鼓励重点城市增设一批离境退税商店，在确保有效监管、风险可控前提下，在符合条件的离境退税商店推广开展“即买即退”业务。增加海南离岛免税城市和门店。\n（十二）推动规则等制度型开放\n38.深化竞争规则领域开放合作。积极推进多双边自由贸易协定竞争政策等议题谈判，加强竞争领域多双边合作交流，不断深化改革，提升合作水平。促进内外贸法律法规、监管体制、经营资质、质量标准、检验检疫、认证认可等相衔接。推动检验检测认证与海外投资、产能合作项目紧密对接，加强国际合格评定人才培养，主动参与认证认可有关国际标准和规则制定。\n39.推动消费品国内外标准接轨。在医用电器、消毒用品、智能照明电器、家用电器、学生用品、婴幼儿配方食品等领域制定修订一批国家标准及其检测方法，加大国际标准采用力度。实施内外销产品同线同标同质工程，在消费品领域积极推行高端品质认证。","level":1},{"name":"六、完善现代化市场监管机制","text":"（十三）推进综合协同监管\n40.全面推行“双随机、一公开”监管。完善并严格执行抽查事项清单，建立健全行业监管部门与综合监管部门协调配合机制，推进部门联合“双随机、一公开”监管常态化。加强政府部门间涉企信息统一归集共享。完善“互联网+监管”，实现重要监管业务在线办理、信息及时上传、问题及时处置。\n41.健全对新业态的包容审慎监管制度。按照鼓励创新、平等保护原则，对新技术、新产业、新业态、新模式等实行包容审慎监管，分类实行相应的监管规则和标准，加强和规范事中事后监管，不得简单化予以禁止或者不予监管。\n（十四）加强重点领域监管\n42.加强重点商品市场价格监管。建立价格监测与价格监管联动机制，建立健全价格监管规则，加强对重要民生商品和资源性产品价格监测。整合部门和市场机构对重点市场的调查监测资源，建立价格监管智慧支撑平台。\n43.强化要素市场交易监管。健全要素市场化交易平台，逐步推进全流程电子化交易，规范各类交易平台规则，完善要素交易信息披露制度。尽快制定技术市场交易管理制度，制定数据交易准则，健全投诉举报查处机制，规范交易行为。\n（十五）健全依法诚信的自律机制和监管机制\n44.完善市场主体信用承诺制度。依托各级信用信息共享平台和行业信用信息系统，按照有关规定将市场主体的承诺履行情况记入信用记录，作为事中事后监管的重要依据。对履行承诺的市场主体，根据信用记录为其提供便利措施；对不履行承诺的市场主体，视情节依法实施限制。完善企业信用修复和异议处理机制。梳理可开展信用承诺的行政许可事项和政务服务事项，制定格式规范的信用承诺书，并依托各级信用门户网站向社会公开。鼓励市场主体主动向社会作出信用承诺。\n45.大力推进信用分级分类监管。推动税收管理、进出口、生态环保、医疗保障、医药招采等更多重点领域深入实施信用分级分类监管，根据监管对象信用状况采取差异化监管措施，为市场主体提供更加精准便利的服务。\n（十六）健全社会监督机制\n46.发挥行业协会商会作用。制定促进行业协会商会规范健康发展的实施意见，推动行业协会商会建立健全行业经营自律规范、自律公约，规范会员行为。鼓励行业协会商会制定发布产品和服务标准，参与制定国家标准、行业标准、团体标准及有关政策法规。\n47.发挥市场专业化服务组织的监督作用。加快培育第三方服务机构和市场中介组织，提升市场专业化服务能力。在全国范围内推行检验检测机构资质认定告知承诺制，深化检验检测机构和认证机构市场化改革，促进第三方检验检测机构和认证机构发展。\n48.发挥公众和舆论监督作用。加强政策宣传，更好发挥舆论监督作用，健全公众参与监督的激励机制，修订完善有奖举报制度，完善对恶意中伤生产经营者、扰乱正常市场秩序的“打假”行为的认定细则和处罚制度。建立健全消费者投诉信息公示制度。\n（十七）加强对监管机构的监督\n49.健全对监管机构履行职责的监督机制。强化对监管机构依法履行监管职责情况的监督检查，促进监管权力规范透明运行。对监管机构不作为、乱作为要依规依法严肃追责问责。推动监管部门建立健全工作人员廉洁从业相关制度，实现依法监管、公正监管、廉洁监管。\n（十八）维护市场安全和稳定\n50.完善维护市场安全的体制机制。落实总体国家安全观，高度重视市场运行的风险挑战和市场体系安全问题，密切跟踪国内外重要商品市场、服务市场和要素市场形势变化，完善政策储备并动态更新政策工具箱。完善宏观经济管理部门与市场监管部门的工作联动和信息共享，强化对重点市场和市场基础设施的跨部门协同监管。完善安全审查机制，重视运用国际通行规则维护国家安全。\n51.积极防范市场异常波动和外部冲击风险。加强对大宗商品、资本、技术、数据等重点市场交易的监测预测预警，研究制定重大市场风险冲击应对预案。健全金融风险预防、预警、处置、问责制度体系。提高通过大数据等方式认定竞争违法行为、预警识别市场运行风险的能力，强化市场预期管理。\n坚持和加强党对高标准市场体系建设的领导，增强“四个意识”、坚定“四个自信”、做到“两个维护”，把党的领导贯穿高标准市场体系建设全过程，确保改革始终沿着正确方向前进。各地区各部门要充分认识建设高标准市场体系的重要意义，按照职责分工，完善工作机制，积极主动作为，破除本位主义，增强合作意识，认真抓好行动方案落实工作，支持有条件的地区开展高标准市场体系示范建设。国家发展改革委、市场监管总局、商务部负责统筹协调有关任务落实，及时对行动方案落实情况进行跟踪评估和督促指导，推动各项工作落到实处。重要情况及时按程序请示报告。","level":1}]},{"id":"r0616","sections":[{"name":"中共中央办公厅 国务院办公厅关于加强生态环境分区管控的意见","text":"中共中央办公厅 国务院办公厅关于加强生态环境分区管控的意见\n（2024年3月6日）","level":1},{"name":"","text":"生态环境分区管控是以保障生态功能和改善环境质量为目标，实施分区域差异化精准管控的环境管理制度，是提升生态环境治理现代化水平的重要举措。实施生态环境分区管控，严守生态保护红线、环境质量底线、资源利用上线，科学指导各类开发保护建设活动，对于推动高质量发展，建设人与自然和谐共生的现代化具有重要意义。为加强生态环境分区管控，经党中央、国务院同意，现提出如下意见。","level":0},{"name":"一、总体要求","text":"加强生态环境分区管控，要坚持以习近平新时代中国特色社会主义思想特别是习近平生态文明思想为指导，深入贯彻党的二十大精神，落实全国生态环境保护大会部署，完整、准确、全面贯彻新发展理念，加快构建新发展格局，协同推进降碳、减污、扩绿、增长，充分尊重自然规律和区域差异，全面落实主体功能区战略，充分衔接国土空间规划和用途管制，以高水平保护推动高质量发展、创造高品质生活，努力建设人与自然和谐共生的美丽中国。\n——生态优先，绿色发展。坚持尊重自然、顺应自然、保护自然，守住自然生态安全边界和环境质量底线，落实自然生态安全责任，推进绿色低碳发展。\n——源头预防，系统保护。健全生态环境源头预防体系，统筹山水林田湖草沙一体化保护和系统治理，加强生物多样性保护，强化多污染物协同控制和区域协同治理。\n——精准科学，依法管控。聚焦区域性、流域性突出生态环境问题，精准科学施策，依法依规建立从问题识别到解决方案的分区分类管控策略。\n——明确责任，协调联动。国家层面做好顶层设计，地方党委和政府落实主体责任，有关部门加强沟通协调，建立分工协作工作机制，提高政策统一性、规则一致性、执行协同性。\n到2025年，生态环境分区管控制度基本建立，全域覆盖、精准科学的生态环境分区管控体系初步形成。到2035年，体系健全、机制顺畅、运行高效的生态环境分区管控制度全面建立，为生态环境根本好转、美丽中国目标基本实现提供有力支撑。","level":1},{"name":"二、全面推进生态环境分区管控","text":"（一）制定生态环境分区管控方案。深入实施主体功能区战略，全面落实《全国国土空间规划纲要（2021－2035年）》，制定以落实生态保护红线、环境质量底线、资源利用上线硬约束为重点，以生态环境管控单元为基础，以生态环境准入清单为手段，以信息平台为支撑的生态环境分区管控方案。坚持国家指导、省级统筹、市级落地的原则，分级编制发布本行政区域内生态环境分区管控方案。省级、市级生态环境分区管控方案由同级政府组织编制，充分做好与国土空间规划“一张图”系统的衔接，报上一级生态环境主管部门备案后发布实施。\n（二）确定生态环境管控单元。基于生态环境结构、功能、质量等区域特征，通过环境评价，在大气、水、土壤、生态、声、海洋等各生态环境要素管理分区的基础上，落实“三区三线”划定成果，以生态保护红线为基础，把该保护的区域划出来，确定生态环境优先保护单元；以生态环境质量改善压力大、资源能源消耗强度高、污染物排放集中、生态破坏严重、环境风险高的区域为主体，把发展同保护矛盾突出的区域识别出来，确定生态环境重点管控单元；生态环境优先保护单元和生态环境重点管控单元以外的其他区域实施一般管控。\n（三）编制生态环境准入清单。落实市场准入负面清单，根据生态环境功能定位和国土空间用途管制要求，聚焦解决突出生态环境问题，系统集成现有生态环境管理规定，精准编制差别化生态环境准入清单，提出管控污染物排放、防控环境风险、提高资源能源利用效率等要求。因地制宜实施“一单元一策略”的精细化管理，生态环境优先保护单元要加强生态系统保护和功能维护，生态环境重点管控单元要针对突出生态环境问题强化污染物排放管控和环境风险防控，其他区域要保持生态环境质量基本稳定。生态环境质量改善压力大、问题和风险突出的地方，要制定更为精准的管控要求。\n（四）加强生态环境分区管控信息共享。推进国家和省级生态环境分区管控系统与其他业务系统的信息共享、业务协同，强化对数据管理、调整更新、实施应用、跟踪评估、监督管理的支撑作用。推进新一代信息技术、人工智能等与生态环境分区管控融合创新，完善在线政务服务和智慧决策功能，提升服务效能。\n（五）统筹开展定期调整与动态更新。生态环境分区管控方案原则上保持稳定，每5年结合国民经济和社会发展规划、国土空间规划评估情况定期调整。5年内确需更新的，按照“谁发布、谁更新”的原则，在充分衔接国民经济和社会发展规划、国土空间规划的基础上，开展动态更新，同时报上一级生态环境主管部门备案。因重大战略、生态环境保护目标等发生变化而更新的，应组织科学论证；生态保护红线、饮用水水源保护区、自然保护地等法定保护区域依法依规设立、调整或撤并以及法律法规有新规定的，相应进行同步更新。","level":1},{"name":"三、助推经济社会高质量发展","text":"（六）服务国家重大战略。通过生态环境分区管控，加强整体性保护和系统性治理，支撑优化重大生产力布局，服务国家重大基础设施建设，保障国家重大战略实施。落实长江经济带发展战略，推动长江全流域按单元精细化分区管控，加强沿江重化工业水污染防治和环境风险防控，防止重污染企业和项目向长江中上游转移。落实黄河流域生态保护和高质量发展战略，实施上中下游地区差异化分区管控，优化黄河中上游能源化工和新能源产业布局，促进中下游产业绿色低碳循环发展。强化生态环境分区管控在京津冀、长三角、粤港澳大湾区产业、能源和交通运输结构调整中的应用，建立陆岸海联动、区域一体化的生态环境管控机制，引导传统制造业绿色低碳转型升级及战略性新兴产业合理布局。\n（七）促进绿色低碳发展。落实国家高耗能、高排放、低水平项目管理有关制度和政策要求，引导重点行业向环境容量大、市场需求旺盛、市场保障条件好的地区科学布局、有序转移。强化生态环境重点管控单元管理，推进石化化工、钢铁、建材等传统产业绿色低碳转型升级和清洁生产改造。完善产业园区环境基础设施建设，推动产业集聚发展和集中治污。衔接生态环境准入清单，引导人口密度较高的中心城区传统产业功能空间有序腾退。优化生态环境优先保护单元管理，鼓励探索生态产品价值实现模式和路径，提升生态碳汇能力。在保证生态系统多样性、稳定性、持续性的前提下，支持国家重大战略、重大基础设施、民生保障等项目建设。实施好沙漠、戈壁、荒漠地区大型风电和光伏基地建设。\n（八）支撑综合决策。加强生态环境分区管控成果应用，为地方党委和政府提供决策支撑。把生态环境分区管控实施成效评估作为优化环境影响评价管理的重要依据。加强生态环境分区管控对企业投资的引导，在生态环境分区管控信息平台依法依规设置公共查阅权限，方便企业分析项目与生态环境分区管控要求的符合性，激发经营主体发展活力。","level":1},{"name":"四、实施生态环境高水平保护","text":"（九）维护生态安全格局。严格落实生态保护红线管控要求。以生态保护红线为重点，改善生态系统质量，提升生态系统稳定性和服务功能。强化生物多样性保护，健全生物多样性保护网络。加强监测预警，主动适应气候变化。对青藏高原生态屏障区、黄河重点生态区、长江重点生态区和东北森林带、北方防沙带、南方丘陵山地带、海岸带等重点区域，分单元识别突出环境问题，落实环境治理差异化管控要求。\n（十）推动环境质量改善。强化生态环境分区管控实施，形成问题识别、精准溯源、分区施策的工作闭环，推动解决突出生态环境问题，防范结构性、布局性环境风险，为高质量发展腾出容量、拓展空间。深化流域水环境分区管控，统筹水资源、水环境、水生态治理，强化流域内水源涵养区、河湖水域及其缓冲带等重要水生态空间管理，加强农业面源污染防治。加强近岸海域生态环境分区管控，陆海统筹推进重点河口海湾管理。综合考虑大气区域传输规律和空间布局敏感性等，强化分区分类差异化协同管控。按照土壤污染程度和相关标准，实施农用地分类管理和建设用地准入管理。加强声环境管理，推动大型交通基础设施、工业集中区等与噪声敏感建筑物集中区域用地布局协调。探索开展地下水污染防治分区管控模式，统筹地上地下，制定差别化的生态环境准入和污染风险管控要求。\n（十一）强化生态环境保护政策协同。发挥生态环境分区管控在源头预防体系中的基础性作用，实现全域覆盖、跨部门协同、多要素综合的精细化管理。加强生态环境分区管控与国土空间规划的动态衔接，针对不同区域开发保护建设活动的特点，聚焦生态环境质量改善，实施分单元差异化的生态环境管理，生态环境主管部门和自然资源主管部门要选择典型地区开展试点、积累经验、完善机制，形成政策合力。开展生态环境分区管控减污降碳协同试点，研究落实以碳排放、污染物排放等为依据的差别化调控政策。强化生态环境保护相关政策与生态环境分区管控制度的协同，将生态环境分区管控要求纳入生态环境有关标准、政策等制定修订中。鼓励各地以产业园区、自由贸易试验区等为重点，开展生态环境分区管控与环境影响评价、排污许可、环境监测、执法监管等协调联动改革试点，探索构建全链条生态环境管理体系。","level":1},{"name":"五、加强监督考核","text":"（十二）强化监督管理。有关部门要按照职责分工，依托相关监管平台，充分利用大数据、卫星遥感、无人机等技术手段开展动态监控，对发现的突出问题和风险隐患开展现场检查并严格依法查处。对生态功能明显降低的生态环境优先保护单元、生态环境问题突出的生态环境重点管控单元以及环境质量明显下降的其他区域，加强监管执法，依法依规推动限期整改。将生态环境分区管控制度落实中存在的突出问题纳入中央和省级生态环境保护督察。\n（十三）完善考核评价。将生态环境分区管控实施情况纳入污染防治攻坚战成效考核等，考核结果作为地方领导班子和有关领导干部综合考核评价、奖惩任免的重要参考。国务院生态环境主管部门会同有关部门对工作落实情况进行跟踪了解，工作成效作为“绿水青山就是金山银山”实践创新基地建设等的重要参考。","level":1},{"name":"六、组织保障","text":"（十四）加强组织领导。坚持党对生态环境分区管控工作的领导。地方各级党委和政府要严格落实生态环境保护“党政同责、一岗双责”，完善工作推进机制，定期研究生态环境分区管控工作，常态化推进共享共用、调整更新、监督落实等事项，及时报告重要工作进展，形成上下联动、各司其职、齐抓共管的良好格局。各地区可结合实际制定配套文件。\n（十五）强化部门联动。国务院生态环境主管部门要会同有关部门制定完善生态环境分区管控相关政策。发展改革部门要积极推动生态环境分区管控成果与国民经济和社会发展相关规划、区域规划编制实施充分衔接。自然资源主管部门要依托国土空间规划“一张图”系统，共享生态保护红线等数据，加强生态环境分区管控方案与国土空间规划的衔接，共同做好相关研究及试点先行等工作。水行政主管部门负责水资源管理、水域岸线管理等有关工作，实施水资源差别化管理，合理控制水资源开发利用规模，与生态环境分区管控联动。林业和草原主管部门要加强各类自然保护地管理与生态环境分区管控的协调联动。工业和信息化、住房城乡建设、交通运输、农业农村等有关主管部门要根据职责分工，加强本领域相关工作与生态环境分区管控协调联动，制定行业发展和开发利用政策、规划时，应充分考虑生态环境分区管控要求，减少对生态系统功能和环境质量的负面影响。有关部门应出台有利于生态环境分区管控实施应用的政策，并推动生态环境分区管控监督执法协调联动。\n（十六）完善法规标准。推动将生态环境分区管控要求纳入相关法律法规制定修订。鼓励有立法权的地方研究制定与生态环境分区管控相关的地方性法规。国务院生态环境主管部门要会同自然资源主管部门等研究制定生态环境分区管控单元划分要求及相关标准规范。\n（十七）强化能力建设。加强生态环境分区管控领域相关学科建设、科学研究和人才培养，加快建立专业化队伍。完善生态环境分区管控信息平台建设。各级财政部门要综合考虑工作目标和任务，按照财政事权和支出责任划分原则落实资金保障。\n（十八）积极宣传引导。将生态环境分区管控纳入党政领导干部教育培训内容。加强宣传解读，及时总结推广正面典型，曝光反面案例，营造全社会广泛关注、共同参与的良好氛围。","level":1}]},{"id":"r0617","sections":[{"name":"中共中央办公厅、国务院办公厅印发《加快推进教育现代化实施方案（2018—2022年）》","text":"近日，中共中央办公厅、国务院办公厅印发了《加快推进教育现代化实施方案（2018－2022年）》（以下简称《实施方案》），并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《实施方案》指出，今后5年加快推进教育现代化的指导思想是：以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中全会精神，以培养社会主义建设者和接班人为根本任务，以全面加强党对教育工作的领导为根本保证，以促进公平和提高质量为时代主题，围绕加快推进教育现代化这一主线，聚焦教育发展的战略性问题、紧迫性问题和人民群众关心的问题，统筹实施各类工程项目和行动计划，着力深化改革、激发活力，着力补齐短板、优化结构，更好发挥教育服务国计民生的作用，确保完成决胜全面建成小康社会教育目标任务，为推动高质量发展、实现2035年奋斗目标夯实基础。\n《实施方案》提出了加快推进教育现代化的实施原则：立足当前，着眼长远；聚焦重点，带动全局；问题导向，改革创新；分区规划，分类推进。总体目标是：经过5年努力，全面实现各级各类教育普及目标，全面构建现代化教育制度体系，教育总体实力和国际影响力大幅提升。实现更高水平、更有质量的普及，教育改革发展成果更公平地惠及全体人民，教育服务经济社会发展的能力显著提高，社会关注的教育热点难点问题得到有效缓解，多样化可选择的优质教育资源更加丰富，人民群众受教育机会进一步扩大，学习大国建设取得重要进展。\n《实施方案》提出了推进教育现代化的十项重点任务：\n一是实施新时代立德树人工程。全面推动习近平新时代中国特色社会主义思想进教材进课堂进头脑，把习近平新时代中国特色社会主义思想贯穿课程教材建设全过程，把教材体系、教学体系有效转化为学生的知识体系、价值体系。增强中小学德育针对性实效性，从中小学生身心特点和思想实际出发改进德育方式方法，注重循序渐进、因材施教、潜移默化，开展喜闻乐见、入脑入心的德育活动。提升高等学校思想政治工作质量。将思想政治工作体系贯穿于学科体系、教学体系、教材体系、管理体系当中，深入构建一体化育人体系。大力加强体育美育劳动教育。加强劳动和实践育人，构建学科教学和校园文化相融合、家庭和社会相衔接的综合劳动、实践育人机制。\n二是推进基础教育巩固提高。推进义务教育优质均衡发展，加快城乡义务教育一体化发展。推进学前教育普及普惠发展，健全学前教育管理机构和专业化管理队伍，加强幼儿园质量监管与业务指导。加快高中阶段教育普及攻坚，推动普通高中优质特色发展。保障特殊群体受教育权利，将进城务工人员随迁子女义务教育纳入城镇发展规划，加强对留守儿童的关爱保护，组织实施特殊教育提升计划。着力减轻中小学生过重课外负担，支持中小学校普遍开展课后服务工作。\n三是深化职业教育产教融合。构建产业人才培养培训新体系，完善学历教育与培训并重的现代职业教育体系，推动教育教学改革与产业转型升级衔接配套。健全产教融合的办学体制机制，坚持面向市场、服务发展、促进就业的办学方向，优化专业结构设置，大力推进产教融合、校企合作，开展国家产教融合建设试点。建立健全职业教育制度标准，完善学校设置、专业教学、教师队伍、学生实习、经费投入、信息化建设等系列制度和标准，制定并落实职业院校生均拨款制度。建立国务院职业教育工作联席会议制度。\n四是推进高等教育内涵发展。加快“双一流”建设，推动建设高等学校全面落实建设方案，研究建立中国特色“双一流”建设的综合评价体系。建设一流本科教育，深入实施“六卓越一拔尖”计划2.0，实施一流专业建设“双万计划”，实施创新创业教育改革燎原计划、高等学校毕业生就业创业促进计划。提升研究生教育水平，完善产教融合的专业学位研究生培养模式、科教融合的学术学位研究生培养模式，加强紧缺高端复合人才培养。完善高等教育质量标准和监测评价体系。提升高等学校科学研究与创新服务能力，实施高等学校基础研究珠峰计划，建设一批前沿科学中心，支持高等学校建设一批重大科技基础设施，积极参与国家实验室建设。继续实施高等学校哲学社会科学繁荣计划。\n五是全面加强新时代教师队伍建设。加强师德师风建设，把师德师风作为评价教师队伍素质的第一标准，实施师德师风建设工程。提高教师教育质量，实施教师教育振兴行动计划，大力培养高素质专业化中小学教师。深化教师管理制度改革，创新编制管理，修订高等学校、中小学和中职学校岗位设置管理指导意见，分类推进教师职称制度改革。保障教师工资待遇，健全中小学教师工资长效联动机制，核定绩效工资总量时统筹考虑当地公务员实际收入水平，实现与当地公务员工资收入同步调整，完善中小学教师绩效工资总量核定分配办法和内部分配办法。补强薄弱地区教师短板，深入实施乡村教师支持计划、银龄讲学计划、援藏援疆万名教师支教计划。\n六是大力推进教育信息化。着力构建基于信息技术的新型教育教学模式、教育服务供给方式以及教育治理新模式。促进信息技术与教育教学深度融合，支持学校充分利用信息技术开展人才培养模式和教学方法改革，逐步实现信息化教与学应用师生全覆盖。创新信息时代教育治理新模式，开展大数据支撑下的教育治理能力优化行动，推动以互联网等信息化手段服务教育教学全过程。加快推进智慧教育创新发展，设立“智慧教育示范区”，开展国家虚拟仿真实验教学项目等建设，实施人工智能助推教师队伍建设行动。构建“互联网+教育”支撑服务平台，深入推进“三通两平台”建设。\n七是实施中西部教育振兴发展计划。坚决打赢教育脱贫攻坚战，以保障义务教育为核心，全面落实教育扶贫政策，稳步提升贫困地区教育基本公共服务水平。推进“三区三州”等深度贫困地区教育脱贫攻坚。补齐中西部教育发展短板，加快中西部地区义务教育学校标准化建设，全面改善贫困地区义务教育薄弱学校基本办学条件，支持中西部地区加快普及高中阶段教育，加快发展民族教育。提升中西部高等教育发展水平，继续实施中西部高等学校基础能力建设工程、东部高等学校对口支援西部高等学校计划，“部省合建”支持中西部地区14所高等学校发展。实施乡村振兴战略教育行动，大力发展现代农业职业教育，推进服务乡村振兴战略的高等农林教育改革，加快乡村振兴急需紧缺人才培养。\n八是推进教育现代化区域创新试验。创新体制机制，探索新时代区域教育改革发展的新模式。高起点高标准规划发展雄安新区教育，优先发展高质量基础教育，加快发展现代职业教育，以新机制新模式建设雄安大学。深化粤港澳高等教育合作交流，促进教育资源特别是高等教育相关的人才、科技、信息等要素在粤港澳大湾区高效流动。构建长三角教育协作发展新格局，进一步加大区域内教育资源相互开放的力度，搭建各级各类教育协作发展与创新平台，实现资源优势互补和有序流动。促进海南教育创新发展，依托海南自由贸易试验区打造新时代教育全面深化改革开放的新标杆。\n九是推进共建“一带一路”教育行动。加快培养高层次国际化人才，完善留学生回国创业就业政策，提高中外合作办学质量，完善中外合作办学准入和退出机制。加强与共建“一带一路”国家教育合作，建设“一带一路”教育资源信息服务综合平台，建立国际科教合作交流平台，实施高等学校科技创新服务“一带一路”倡议行动计划。深化与共建“一带一路”国家人文交流，大力支持中外民间交流，加强中外体育艺术等人文交流。优化孔子学院区域布局，加强孔子学院能力建设，全面提高办学水平。加大汉语国际教育工作力度。\n十是深化重点领域教育综合改革。加快重点领域和关键环节改革步伐，为加快推进教育现代化提供制度支撑。积极稳妥推进考试招生制度改革，坚定高考改革方向，完善普通高中学业水平考试制度，进一步推进学术学位与专业学位硕士研究生分类考试，完善博士研究生“申请－考核”和直接攻博等选拔机制。完善民办教育分类管理，全面落实民办教育促进法，修订民办教育促进法实施条例，积极鼓励社会力量依法兴办教育，促进民办教育持续健康发展。加快构建终身学习制度体系，加强终身学习法律法规建设，搭建沟通各级各类教育、衔接多种学习成果的全民终身学习立交桥，加快发展社区教育、老年教育，深入推动学习型组织建设和学习型城市建设。深化教育领域放管服改革，深化简政放权、放管结合、优化服务改革，推进政府职能转变，构建政府、学校、社会之间的新型关系。推进学校治理现代化。\n《实施方案》明确了推进教育现代化四个方面的保障措施：一是全面加强教育系统党的建设，不断提高教育系统党的建设质量，坚定不移推进全面从严治党向纵深发展。二是全面推进依法治教，加快完善教育法律制度体系，加快推进教育行政执法体制机制改革，建立健全教育系统法律顾问制度，加强学校法治工作，广泛深入开展青少年法治教育。三是完善教育经费投入和管理机制，健全财政教育投入机制，全面实施绩效管理。四是加强教育督导评估，有效发挥教育督导“督导评估、检查验收、质量监测”职能，保障教育事业优先优质发展。\n《实施方案》最后强调，各级党委和政府要把思想和行动统一到党中央、国务院关于加快教育现代化、建设教育强国的重大部署上来，加强组织领导，结合地方实际制定本地区落实方案。各部门要主动履职尽责，确保实施方案确定的目标任务落到实处。国务院教育督导部门定期组织督导评估，压实落实责任。及时总结宣传典型经验和做法，凝聚全社会共同促进教育健康发展的共识，为新时代教育改革发展营造良好环境和氛围。\n延伸阅读\n中共中央、国务院印发《中国教育现代化2035》\n教育部负责人就《中国教育现代化2035》和《加快推进教育现代化实施方案（2018－2022年）》答记者问","level":0}]},{"id":"r0618","sections":[{"name":"中共中央办公厅印发《关于在全党大兴调查研究的工作方案》","text":"近日，中共中央办公厅印发了《关于在全党大兴调查研究的工作方案》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于在全党大兴调查研究的工作方案》全文如下。\n为深入学习贯彻习近平新时代中国特色社会主义思想，全面贯彻落实党的二十大精神，党中央决定，在全党大兴调查研究，作为在全党开展的主题教育的重要内容，推动全面建设社会主义现代化国家开好局起好步。现制定如下工作方案。","level":0},{"name":"一、重要意义","text":"调查研究是我们党的传家宝。党的十八大以来，以习近平同志为核心的党中央高度重视调查研究工作，习近平总书记强调指出，调查研究是谋事之基、成事之道，没有调查就没有发言权，没有调查就没有决策权；正确的决策离不开调查研究，正确的贯彻落实同样也离不开调查研究；调查研究是获得真知灼见的源头活水，是做好工作的基本功；要在全党大兴调查研究之风。习近平总书记这些重要指示，深刻阐明了调查研究的极端重要性，为全党大兴调查研究、做好各项工作提供了根本遵循。\n当前，我国发展面临新的战略机遇、新的战略任务、新的战略阶段、新的战略要求、新的战略环境。世界百年未有之大变局加速演进，不确定、难预料因素增多，国内改革发展稳定面临不少深层次矛盾躲不开、绕不过，各种风险挑战、困难问题比以往更加严峻复杂，迫切需要通过调查研究把握事物的本质和规律，找到破解难题的办法和路径。在全党大兴调查研究，是深入学习贯彻习近平新时代中国特色社会主义思想、感悟这一重要思想的真理力量和实践伟力的必然要求，是深刻领悟“两个确立”的决定性意义、坚决做到“两个维护”的具体实践，是应对新时代新征程前进路上的风浪考验、推进中国式现代化的有力举措，是时刻保持解决大党独有难题的清醒和坚定、回答“六个如何始终”的现实需要，是转变工作作风、密切联系群众、提高履职本领、强化责任担当的有效途径。","level":1},{"name":"二、总体要求","text":"在全党大兴调查研究，要坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻落实党的二十大精神，紧紧围绕党的理论和路线方针政策、党中央重大决策部署的贯彻执行，大力弘扬党的光荣传统和优良作风，突出问题导向和目标导向，促进广大党员、干部特别是领导干部带头深入调查研究，不断深化对党的创新理论的认识和把握，善于运用党的创新理论研究新情况、解决新问题、总结新经验、探索新规律，扑下身子干实事、谋实招、求实效，使调查研究工作同中心工作和决策需要紧密结合起来，更好为科学决策服务，为提高党的执政能力和领导水平服务，为完成新时代新征程的使命任务服务。\n在全党大兴调查研究，必须坚持党的群众路线，从群众中来、到群众中去，增进同人民群众的感情，真诚倾听群众呼声、真实反映群众愿望、真情关心群众疾苦，自觉向群众学习、向实践学习，从人民的创造性实践中获得正确认识，把党的正确主张变为群众的自觉行动。必须坚持实事求是，坚守党性原则，一切从实际出发，理论联系实际，听真话、察实情，坚持真理、修正错误，有一是一、有二是二，既报喜又报忧，不唯书、不唯上、只唯实。必须坚持问题导向，增强问题意识，敢于正视问题、善于发现问题，以解决问题为根本目的，真正把情况摸清、把问题找准、把对策提实，不断提出真正解决问题的新思路新办法。必须坚持攻坚克难，发扬斗争精神，增强斗争本领，勇于涉险滩、破难题，知难而进、迎难而上，把调查研究成果转化为推进工作、战胜困难的实际成效。必须坚持系统观念，深入实际、深入基层、深入群众调查了解情况，把握好全局和局部、当前和长远、宏观和微观、主要矛盾和次要矛盾、特殊和一般的关系，前瞻性思考、全局性谋划、整体性推进党和国家各项事业。","level":1},{"name":"三、调研内容","text":"在全党大兴调查研究，要紧紧围绕全面贯彻落实党的二十大精神、推动高质量发展，直奔问题去，实行问题大梳理、难题大排查，着力打通贯彻执行中的堵点淤点难点。各级党委（党组）要立足职能职责，围绕做好事关全局的战略性调研、破解复杂难题的对策性调研、新时代新情况的前瞻性调研、重大工作项目的跟踪性调研、典型案例的解剖式调研、推动落实的督查式调研，突出重点、直击要害，结合实际确定调研内容。主要是12个方面。\n1.贯彻落实党中央决策部署和习近平总书记对本地区本部门本领域工作重要指示批示精神的主要情况和重点问题。\n2.贯彻新发展理念、构建新发展格局、推动高质量发展中的重大问题，推进高水平科技自立自强，扩大国内需求、深化供给侧结构性改革、建设现代化产业体系、落实“两个毫不动摇”、吸引和利用外资，全面推进乡村振兴中的主要情况和重点问题。\n3.统筹发展和安全，确保粮食、能源、产业链供应链、生产、食品药品、公共卫生等安全，防范化解重大经济金融风险中的主要情况和重点问题。\n4.全面深化改革开放中的重大问题，重要领域和关键环节改革、推进高水平对外开放中的主要情况和重点问题。\n5.全面依法治国中的重大问题，完善中国特色社会主义法律体系、推进依法行政、严格公正司法、建设法治社会等主要情况和重点问题。\n6.意识形态领域面临的挑战，推进文化自信自强、建设社会主义文化强国和新闻舆论引导、网络综合治理中的主要情况和重点问题。\n7.推进共同富裕、增进民生福祉中的重大问题，巩固拓展脱贫攻坚成果、缩小城乡区域发展差距和收入分配差距的主要情况和重点问题。\n8.人民最关心最直接最现实的利益问题，特别是就业、教育、医疗、托育、养老、住房等群众急难愁盼的具体问题。\n9.牢固树立和践行绿水青山就是金山银山理念方面的差距和不足，推进美丽中国建设、保护生态环境和维护生态安全中的主要情况和重点问题。\n10.维护社会稳定中的重大问题，防灾减灾救灾和重大突发公共事件处置保障短板，处理新形势下人民内部矛盾和强化社会治安整体防控的主要情况和重点问题。\n11.全面从严治党中的重大问题，落实党的领导弱化虚化淡化、党组织政治功能和组织功能不够强，干事创业精气神不足、不担当不作为，应对“黑天鹅”、“灰犀牛”事件和防范化解风险能力不强，形式主义、官僚主义，特权思想和特权行为等重点问题。\n12.本地区本部门本单位长期未解决的老大难问题。","level":1},{"name":"四、方法步骤","text":"在全党大兴调查研究，分为6个步骤。\n（一）提高认识。各级党委（党组）要通过理论学习中心组学习、读书班等，组织党员、干部深入学习领会习近平总书记关于调查研究的重要论述，学习习近平总书记关于本地区本部门本领域的重要讲话和重要指示批示精神，继承和发扬老一辈革命家深入基层调查研究的优良作风，增强做好调查研究的思想自觉、政治自觉、行动自觉。\n（二）制定方案。各级党委（党组）要围绕调研内容，结合本地区本部门本单位实际，广泛听取各方面意见，研究制定调查研究的具体方案，明确调研的项目课题、方式方法和工作要求等，统筹安排、合理确定调研的时间、地点、人员。党委（党组）主要负责同志要亲自主持制定方案。\n（三）开展调研。县处级以上领导班子成员每人牵头1个课题开展调研，同时，针对相关领域或工作中最突出的难点问题进行专项调研。要坚持因地制宜，综合运用座谈访谈、随机走访、问卷调查、专家调查、抽样调查、统计分析等方式，充分运用互联网、大数据等现代信息技术开展调查研究，提高科学性和实效性。要深入农村、社区、企业、医院、学校、新经济组织、新社会组织等基层单位，掌握实情、把脉问诊，问计于群众、问计于实践。要转换角色、走进群众，了解群众的烦心事操心事揪心事，发现和查找工作中的差距不足。要结合典型案例，分析问题、剖析原因，举一反三采取改进措施。要加强督查调研，检查工作是否真正落实、问题是否真正解决。\n（四）深化研究。全面梳理汇总调研情况，运用习近平新时代中国特色社会主义思想的世界观、方法论和贯穿其中的立场观点方法，进行深入分析、充分论证和科学决策。特别是对那些具有普遍性和制度性的问题、涉及改革发展稳定的深层次关键性问题，以及难题积案和顽瘴痼疾等，要研究透彻、找准根源和症结。在此基础上，领导班子交流调研情况，研究对策措施，形成解决问题、促进工作的思路办法和政策举措，确保每个问题都有务实管用的破解之策。\n（五）解决问题。对调研中反映和发现的问题，逐一梳理形成问题清单、责任清单、任务清单，逐一列出解决措施、责任单位、责任人和完成时限。对短期能够解决的，立行立改、马上就办。对一时难以解决、需要持续推进的，明确目标，紧盯不放，一抓到底，做到问题不解决不松劲、解决不彻底不放手。\n（六）督查回访。各级党委（党组）要建立调研成果转化运用清单，加强对调研课题完成情况、问题解决情况的督查督办和跟踪问效；领导干部要定期对调研对象和解决问题等事项进行回访，注意发现和解决新的问题。","level":1},{"name":"五、工作要求","text":"（一）加强组织领导。各级党委（党组）要高度重视调查研究工作，作出专门部署，科学精准做好方案设计、过程实施、监督问效等各个环节工作。党委（党组）主要负责同志负总责，抓好本地区本部门本单位调查研究的推进落实；班子其他成员各负其责，抓好分管领域和分管单位的调查研究工作。领导干部要带头开展调查研究，改进调研方法，以上率下、作出示范。\n（二）严明工作纪律。调查研究要严格执行中央八项规定及其实施细则精神，轻车简从，厉行节约，不搞层层陪同。要采取“四不两直”方式，多到困难多、群众意见集中、工作打不开局面的地方和单位开展调研，防止嫌贫爱富式调研。要加强调研统筹，避免扎堆调研、多头调研、重复调研，不增加基层负担。要力戒形式主义、官僚主义，不搞作秀式、盆景式和蜻蜓点水式调研，防止走过场、不深入。要在调查的基础上深化研究，防止调查多研究少、情况多分析少，提出的对策建议不解决实际问题。对违反作风建设要求和廉洁自律规定的，要依规依纪严肃问责。\n（三）坚持统筹推进。对表现在基层、根子在上面的问题，对涉及多个地区或部门单位的问题，上下协同、整体推动解决。统筹当前和长远，发现总结调查研究的有效做法和成功经验，完善调查研究的长效机制，使调查研究成为党员、干部的经常性工作，在全党蔚然成风、产生实效。\n（四）加大宣传力度。充分利用党报、党刊、电视台、广播电台、网络传播平台等，采取多种多样的宣传形式和手段，大力宣传大兴调查研究的重要意义和各地区各部门各单位大兴调查研究的具体举措、实际成效，凝聚起大兴调查研究的共识和力量，营造浓厚氛围。\n延伸阅读\n在全党大兴调查研究 中央明确12个方面重点内容和6个步骤","level":1}]},{"id":"r0619","sections":[{"name":"关于分类推进人才评价机制改革的指导意见","text":"近日，中共中央办公厅、国务院办公厅印发了《关于分类推进人才评价机制改革的指导意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于分类推进人才评价机制改革的指导意见》全文如下。\n人才评价是人才发展体制机制的重要组成部分，是人才资源开发管理和使用的前提。建立科学的人才分类评价机制，对于树立正确用人导向、激励引导人才职业发展、调动人才创新创业积极性、加快建设人才强国具有重要作用。当前，我国人才评价机制仍存在分类评价不足、评价标准单一、评价手段趋同、评价社会化程度不高、用人主体自主权落实不够等突出问题，亟需通过深化改革加以解决。为深入贯彻落实《中共中央印发〈关于深化人才发展体制机制改革的意见〉的通知》，创新人才评价机制，发挥人才评价指挥棒作用，现就分类推进人才评价机制改革提出如下意见。","level":0},{"name":"一、总体要求和基本原则","text":"（一）总体要求。全面贯彻党的十九大精神，以习近平新时代中国特色社会主义思想为指导，认真落实党中央、国务院决策部署，按照统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局要求，落实新发展理念，围绕实施人才强国战略和创新驱动发展战略，以科学分类为基础，以激发人才创新创业活力为目的，加快形成导向明确、精准科学、规范有序、竞争择优的科学化社会化市场化人才评价机制，建立与中国特色社会主义制度相适应的人才评价制度，努力形成人人渴望成才、人人努力成才、人人皆可成才、人人尽展其才的良好局面，使优秀人才脱颖而出。\n（二）基本原则\n——坚持党管人才原则。充分发挥党的思想政治优势、组织优势、密切联系群众优势，进一步加强党对人才评价工作的领导，将改革完善人才评价机制作为人才工作的重要内容，在全社会大兴识才爱才敬才用才容才聚才之风，把各方面优秀人才集聚到党和人民的伟大奋斗中来。\n——坚持服务发展。围绕经济社会发展和人才发展需求，充分发挥人才评价正向激励作用，推动多出人才、出好人才，最大限度激发和释放人才创新创业活力，促进人才发展与经济社会发展深度融合。\n——坚持科学公正。遵循人才成长规律，突出品德、能力和业绩评价导向，分类建立体现不同职业、不同岗位、不同层次人才特点的评价机制，科学客观公正评价人才，让各类人才价值得到充分尊重和体现。\n——坚持改革创新。围绕用好用活人才，着力破除思想障碍和制度藩篱，加快转变政府职能，保障落实用人主体自主权，发挥政府、市场、专业组织、用人单位等多元评价主体作用，营造有利于人才成长和发挥作用的评价制度环境。","level":1},{"name":"二、分类健全人才评价标准","text":"（三）实行分类评价。以职业属性和岗位要求为基础，健全科学的人才分类评价体系。根据不同职业、不同岗位、不同层次人才特点和职责，坚持共通性与特殊性、水平业绩与发展潜力、定性与定量评价相结合，分类建立健全涵盖品德、知识、能力、业绩和贡献等要素，科学合理、各有侧重的人才评价标准。加快新兴职业领域人才评价标准开发工作。建立评价标准动态更新调整机制。\n（四）突出品德评价。坚持德才兼备，把品德作为人才评价的首要内容，加强对人才科学精神、职业道德、从业操守等评价考核，倡导诚实守信，强化社会责任，抵制心浮气躁、急功近利等不良风气，从严治理弄虚作假和学术不端行为。完善人才评价诚信体系，建立诚信守诺、失信行为记录和惩戒制度。探索建立基于道德操守和诚信情况的评价退出机制。\n（五）科学设置评价标准。坚持凭能力、实绩、贡献评价人才，克服唯学历、唯资历、唯论文等倾向，注重考察各类人才的专业性、创新性和履责绩效、创新成果、实际贡献。着力解决评价标准“一刀切”问题，合理设置和使用论文、专著、影响因子等评价指标，实行差别化评价，鼓励人才在不同领域、不同岗位作出贡献、追求卓越。","level":1},{"name":"三、改进和创新人才评价方式","text":"（六）创新多元评价方式。按照社会和业内认可的要求，建立以同行评价为基础的业内评价机制，注重引入市场评价和社会评价，发挥多元评价主体作用。基础研究人才以同行学术评价为主，加强国际同行评价。应用研究和技术开发人才突出市场评价，由用户、市场和专家等相关第三方评价。哲学社会科学人才评价重在同行认可和社会效益。丰富评价手段，科学灵活采用考试、评审、考评结合、考核认定、个人述职、面试答辩、实践操作、业绩展示等不同方式，提高评价的针对性和精准性。\n（七）科学设置人才评价周期。遵循不同类型人才成长发展规律，科学合理设置评价考核周期，注重过程评价和结果评价、短期评价和长期评价相结合，克服评价考核过于频繁的倾向。探索实施聘期评价制度。突出中长期目标导向，适当延长基础研究人才、青年人才等评价考核周期，鼓励持续研究和长期积累。\n（八）畅通人才评价渠道。进一步打破户籍、地域、所有制、身份、人事关系等限制，依托具备条件的行业协会、专业学会、公共人才服务机构等，畅通非公有制经济组织、社会组织和新兴职业等领域人才申报评价渠道。对引进的海外高层次人才和急需紧缺人才，建立评价绿色通道。完善外籍人才、港澳台人才申报评价办法。\n（九）促进人才评价和项目评审、机构评估有机衔接。按照既出成果、又出人才的要求，在各类工程项目、科技计划、机构平台等评审评估中加强人才评价，完善在重大科研、工程项目实施、急难险重工作中评价、识别人才机制。深入推进项目评审、人才评价、机构评估改革，树立正确评价导向，进一步精简整合、取消下放、优化布局评审事项，简化评审环节，改进评审方式，减轻人才负担。避免简单通过各类人才计划头衔评价人才。加强评价结果共享，避免多头、频繁、重复评价人才。","level":1},{"name":"四、加快推进重点领域人才评价改革","text":"（十）改革科技人才评价制度。围绕建设创新型国家和世界科技强国目标，结合科技体制改革，建立健全以科研诚信为基础，以创新能力、质量、贡献、绩效为导向的科技人才评价体系。对主要从事基础研究的人才，着重评价其提出和解决重大科学问题的原创能力、成果的科学价值、学术水平和影响等。对主要从事应用研究和技术开发的人才，着重评价其技术创新与集成能力、取得的自主知识产权和重大技术突破、成果转化、对产业发展的实际贡献等。对从事社会公益研究、科技管理服务和实验技术的人才，重在评价考核工作绩效，引导其提高服务水平和技术支持能力。\n实行代表性成果评价，突出评价研究成果质量、原创价值和对经济社会发展实际贡献。改变片面将论文、专利、项目、经费数量等与科技人才评价直接挂钩的做法，建立并实施有利于科技人才潜心研究和创新的评价制度。\n注重个人评价与团队评价相结合。适应科技协同创新和跨学科、跨领域发展等特点，进一步完善科技创新团队评价办法，实行以合作解决重大科技问题为重点的整体性评价。对创新团队负责人以把握研究发展方向、学术造诣水平、组织协调和团队建设等为评价重点。尊重认可团队所有参与者的实际贡献，杜绝无实质贡献的虚假挂名。\n（十一）科学评价哲学社会科学和文化艺术人才。坚持马克思主义指导地位、为人民做学问的研究立场、以人民为中心的创作导向，注重政治标准和学术标准、继承性和民族性、原创性和时代性、系统性和专业性相统一，建立健全中国特色的哲学社会科学和文化艺术人才评价体系，推进中国特色哲学社会科学学科体系、学术体系、话语体系建设，推出更多无愧于民族、无愧于时代的文艺精品。\n根据人文科学、社会科学、文化艺术等不同学科领域，理论研究、应用对策研究、艺术表演创作等不同类型，对其人才实行分类评价。对主要从事理论研究的人才，重点评价其在推动理论创新、传承文明、学科建设等方面的能力贡献。对主要从事应用对策研究的人才，重点评价其围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，为党和政府决策提供服务支撑的能力业绩。对主要从事艺术表演创作的人才，重点评价其在艺术表演、作品创作、满足人民精神文化需求等方面的能力业绩。突出成果的研究质量、内容创新和社会效益，推行理论文章、决策咨询研究报告、建言献策成果、优秀网络文章、艺术创作作品等与论文、专著等效评价。\n（十二）健全教育人才评价体系。坚持立德树人，把教书育人作为教育人才评价的核心内容。深化高校教师评价制度改革，坚持社会主义办学方向，坚持思想政治素质和业务能力双重考察、全面考核和突出重点相结合，注重对师德师风、教育教学、科学研究、社会服务、专业发展的综合评价。坚持分类指导和分层次评价相结合，根据不同类型高校、不同岗位教师的职责特点，分类分层次分学科设置评价内容和评价方式。突出教育教学业绩评价，将人才培养中心任务落到实处，要求所有教师都必须承担教育教学工作，建立健全教学工作量评价标准，落实教授为本专科生授课制度，加强教学质量和课堂教学纪律考核。\n适应现代职业教育发展需要，按照兼备专业理论知识和技能操作实践能力的要求，完善职业院校（含技工院校）“双师型”教师评价标准，吸纳行业、企业作为评价参与主体，重点评价其职业素养、专业教学能力和生产一线实践经验。\n适应中小学素质教育和课程改革新要求，建立充分体现中小学教师岗位特点的评价标准，重点评价其教育教学方法、教书育人工作业绩和一线实践经历。严禁简单用学生升学率和考试成绩评价中小学教师。\n（十三）改进医疗卫生人才评价制度。强化医疗卫生人才临床实践能力评价，完善涵盖医德医风、临床实践、科研带教、公共卫生服务等要素的评价指标体系，合理确定不同医疗卫生机构、不同专业岗位人才评价重点。对主要从事临床工作的人才，重点考察其临床医疗医技水平、实践操作能力和工作业绩，引入临床病历、诊治方案等作为评价依据。对主要从事科研工作的人才，重点考察其创新能力业绩，突出创新成果的转化应用能力。对主要从事疾病预防控制等的公共卫生人才，重点考察其流行病学调查、传染病疫情和突发公共卫生事件处置、疾病及危害因素监测与评价等能力。\n建立符合全科医生岗位特点的评价机制，考核其掌握全科医学基本理论知识、常见病多发病诊疗、预防保健和提供基本公共卫生服务的能力，将签约居民数量、接诊量、服务质量、群众满意度作为重要评价因素。\n按照强基层、保基本及分级诊疗要求，建立更加注重临床水平、服务质量、工作业绩的基层医疗卫生人才评价机制，鼓励医疗卫生人才服务基层，更好满足基层人民群众健康需求。\n（十四）创新技术技能人才评价制度。适应工程技术专业化、标准化程度高、通用性强等特点，分专业领域建立健全工程技术人才评价标准，着力解决评价标准过于追求学术化问题，重点评价其掌握必备专业理论知识和解决工程技术难题、技术创造发明、技术推广应用、工程项目设计、工艺流程标准开发等实际能力和业绩。探索推动工程师国际互认，提高工程教育质量和工程技术人才职业化、国际化水平。\n健全以职业能力为导向、以工作业绩为重点、注重职业道德和知识水平的技能人才评价体系。加快构建国家职业标准、行业企业工种岗位要求、专项职业能力考核规范等多层次职业标准。完善职业资格评价、职业技能等级认定、专项职业能力考核等多元化评价方式，做好评价结果有机衔接。坚持职业标准和岗位要求、职业能力考核和工作业绩评价、专业评价和企业认可相结合的原则，对技术技能型人才突出实际操作能力和解决关键生产技术难题要求，对知识技能型人才突出掌握运用理论知识指导生产实践、创造性开展工作要求，对复合技能型人才突出掌握多项技能、从事多工种多岗位复杂工作要求，引导鼓励技能人才培育精益求精的工匠精神。\n（十五）完善面向企业、基层一线和青年人才的评价机制。建立与产业发展需求、经济结构相适应的企业人才评价机制，突出创新创业实践能力，推动企业自主创新能力提升。对业绩贡献突出的优秀企业家、经营管理人才、高层次创新创业人才，可放宽学历、资历、年限等申报条件。健全以市场和出资人认可为重要标准的企业经营管理人才评价体系，突出对经营业绩和综合素质的考核。建立社会化的职业经理人评价制度。\n创新基层人才评价激励机制。对长期在基层一线和艰苦边远地区工作的人才，加大爱岗敬业表现、实际工作业绩、工作年限等评价权重，着力拓展基层人才职业发展空间。健全以职业农民为主体的农村实用人才评价制度，完善教育培训、认定评价管理、政策扶持“三位一体”的制度体系。完善社会工作专业人才职业水平评价制度，加强社会工作者职业化管理与激励保障，提升社会治理和社会服务现代化水平。\n完善青年人才评价激励措施。破除论资排辈、重显绩不重潜力等陈旧观念，重点遴选支持一批有较大发展潜力、有真才实学、堪当重任的优秀青年人才。加大各类科技、教育、人才工程项目对青年人才支持力度，鼓励设立青年专项，促进优秀青年人才脱颖而出。探索建立优秀青年人才举荐制度。","level":1},{"name":"五、健全完善人才评价管理服务制度","text":"（十六）保障和落实用人单位自主权。尊重用人单位主导作用，支持用人单位结合自身功能定位和发展方向评价人才，促进人才评价与培养、使用、激励等相衔接。合理界定和下放人才评价权限，推动具备条件的高校、科研院所、医院、文化机构、大型企业、国家实验室、新型研发机构及其他人才智力密集单位自主开展评价聘用（任）工作。防止人才评价行政化、“官本位”倾向，充分发挥学术委员会等作用。对开展自主评价的单位，人才管理部门不再进行资格审批，通过完善信用机制、第三方评估、检查抽查等方式加强事中事后监管。\n（十七）健全市场化、社会化的管理服务体系。进一步明确政府、市场、用人主体在人才评价中的职能定位，建立权责清晰、管理科学、协调高效的人才评价管理体制。推动人才管理部门转变职能、简政放权，强化政府人才评价宏观管理、政策法规制定、公共服务、监督保障等职能，减少审批事项和微观管理。发挥市场、社会等多元评价主体作用，积极培育发展各类人才评价社会组织和专业机构，逐步有序承接政府转移的人才评价职能。建立人才评价机构综合评估、动态调整机制。\n（十八）优化公平公正的评价环境。加强人才评价法治建设，健全完善规章制度，提高评价质量和公信力，维护人才合法权益。严格规范评价程序，建立健全申报、审核、公示、反馈、申诉、巡查、举报、回溯等制度。加强评价专家数据库建设和资源共享，建立随机、回避、轮换的专家遴选机制，优化专家来源和结构，强化业内代表性。建立评价专家责任和信誉制度，实施退出和问责机制。强化人才评价综合治理，依法清理规范各类人才评价活动和发证、收费等事项，加强考试环境治理，落实考试安全主体责任。加强人才评价文化建设，提倡开展平等包容的学术批评、学术争论，保障不同学术观点的充分讨论，营造求真务实、鼓励创新、宽容失败的评价氛围和环境。\n各地区各部门要坚持党管人才原则，切实加强党委和政府对改革完善人才评价机制的统一领导，党委组织部门要牵头抓总，有关部门要各司其职、密切配合，发挥社会力量重要作用，认真抓好组织落实。要深入调查研究，结合实际制定具体实施方案，加强分类指导，强化督促检查，确保改革任务落地见效。军队可根据本意见，结合实际建立健全军队人才评价机制。要坚持分类推进、先行试点、稳步实施，及时研究解决改革中遇到的新情况新问题。要加强政策解读和舆论引导，积极回应社会关切，为分类推进人才评价机制改革营造良好氛围。","level":1}]},{"id":"r0620","sections":[{"name":"中共中央办公厅转发《中央宣传部、中央组织部关于认真组织学习〈习近平谈治国理政〉第四卷的通知》","text":"近日，中共中央办公厅转发了《中央宣传部、中央组织部关于认真组织学习〈习近平谈治国理政〉第四卷的通知》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《中央宣传部、中央组织部关于认真组织学习〈习近平谈治国理政〉第四卷的通知》全文如下。\n党的十八大以来，以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，创立了习近平新时代中国特色社会主义思想。习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，是中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃。党确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位，反映了全党全军全国各族人民共同心愿，对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。\n《习近平谈治国理政》第一卷至第三卷出版以来，在宣传党的创新理论、激发人民奋斗实践方面发挥了重要作用，也为国际社会了解中国、读懂中国打开了重要“思想之窗”，有力展示了中国形象。《习近平谈治国理政》第三卷出版两年多来，习近平总书记在领导党和人民应变局、开新局的伟大实践中，坚持解放思想、实事求是、守正创新，又提出一系列原创性的治国理政新理念新思想新战略，进一步科学回答了中国之问、世界之问、人民之问、时代之问。\n经党中央批准，中央宣传部（国务院新闻办公室）会同中央党史和文献研究院、中国外文局，编辑出版了《习近平谈治国理政》第四卷。该书收入了习近平总书记在2020年2月3日至2022年5月10日期间的讲话、谈话、演讲、致辞、指示、贺信等109篇，分为21个专题。\n《习近平谈治国理政》第四卷生动记录了以习近平同志为核心的党中央，面对百年变局和世纪疫情相互叠加、世界进入新的动荡变革期的复杂局面，面对世所罕见、史所罕见的风险挑战，统筹国内国际两个大局，统筹疫情防控和经济社会发展，统筹发展和安全，团结带领全党全国各族人民在中华大地上全面建成小康社会、开启全面建设社会主义现代化国家新征程的伟大实践，集中展现了马克思主义中国化的最新成果，充分体现了我们党为推动构建人类命运共同体、共建美好世界作出的最新贡献，是全面系统反映习近平新时代中国特色社会主义思想的权威著作。\n《习近平谈治国理政》第四卷的出版发行，对于推动广大党员、干部和群众深入学习贯彻习近平新时代中国特色社会主义思想，深刻领会“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，在新时代新征程上团结奋斗、勇毅前行；对于帮助国际社会及时了解这一重要思想的最新发展，增进对中国共产党和中国人民过去为什么能够成功、未来怎样才能继续成功的认识，加深对中国之路、中国之治、中国之理的理解，具有重要意义。\n认真学习《习近平谈治国理政》第四卷，是用习近平新时代中国特色社会主义思想武装全党、教育人民的重大政治任务。各级党组织要精心组织安排，将《习近平谈治国理政》第四卷与第一卷、第二卷、第三卷作为一个整体，引导广大党员、干部读原著学原文、悟原理知原义，真正做到虔诚而执着、至信而深厚。各级党委（党组）理论学习中心组要把《习近平谈治国理政》第四卷列入学习计划，在学懂弄通做实上下功夫，不断提高政治判断力、政治领悟力、政治执行力，切实把学习成果转化为奋进新征程、建功新时代的工作举措和实际成效。各级党校（行政学院）、干部学院要把《习近平谈治国理政》第四卷纳入培训教学重要内容，各高等学校要将其作为思想政治教育重要教材，各级党委讲师团以及新时代文明实践中心、县级融媒体中心、“学习强国”学习平台要创新开展对象化、分众化宣讲宣传，不断增强吸引力感染力。要坚持理论联系实际的马克思主义学风，结合全面做好改革发展稳定各方面工作、高效做好统筹疫情防控和经济社会发展工作，更好用习近平新时代中国特色社会主义思想把全党武装起来、把党中央决策部署的各项任务落实下去，凝聚起全面建设社会主义现代化国家的磅礴力量，以实际行动迎接党的二十大胜利召开。\n延伸阅读\n《习近平谈治国理政》第四卷中英文版出版发行\n学习《习近平谈治国理政》第一卷\n学习《习近平谈治国理政》第二卷\n学习《习近平谈治国理政》第三卷","level":0}]},{"id":"r0621","sections":[{"name":"关于全面深化公安改革若干重大问题的框架意见","text":"点击此处观看视频","level":1},{"name":"","text":"近日，《关于全面深化公安改革若干重大问题的框架意见》及相关改革方案，已经中央审议通过，即将印发实施。\n党中央、国务院对公安工作高度重视，对公安队伍建设十分关心。党的十八大以来，习近平总书记等中央领导同志多次听取公安工作汇报，并就深入推进公安改革、进一步加强和改进新形势下的公安工作和公安队伍建设作出重要指示。在中央全面深化改革领导小组的领导下，在中央司法体制改革领导小组的指导下，公安部成立全面深化改革领导小组，加强研究谋划、深入调研论证，在形成《意见》和方案稿后，又广泛征求了各地、各有关部门和基层单位的意见，并根据各方意见反复修改完善。《意见》和方案先后经中央全面深化改革领导小组会议、中央政治局常委会议审议通过。\n全面深化公安改革的总体目标是：完善与推进国家治理体系和治理能力现代化、建设中国特色社会主义法治体系相适应的现代警务运行机制和执法权力运行机制，建立符合公安机关性质任务的公安机关管理体制，建立体现人民警察职业特点、有别于其他公务员的人民警察管理制度。到2020年，基本形成系统完备、科学规范、运行有效的公安工作和公安队伍管理制度体系，实现基础信息化、警务实战化、执法规范化、队伍正规化，进一步提升人民群众的安全感、满意度和公安机关的执法公信力。\n全面深化公安改革共有七个方面的主要任务、100多项改革措施。一是健全维护国家安全工作机制，二是创新社会治安治理机制，三是深化公安行政管理改革，四是完善执法权力运行机制，五是完善公安机关管理体制，六是健全人民警察管理制度，七是规范警务辅助人员管理。\n全面深化公安改革坚持以问题为导向，将改革的指向聚焦在三个方面：一是着力完善现代警务运行机制，提高社会治安防控水平和治安治理能力，提高人民群众的安全感。二是着力推进公安行政管理改革，提高管理效能和服务水平，从政策上、制度上推出更多惠民利民便民新举措，提高人民群众的满意度。三是着力建设法治公安，确保严格规范公正文明执法，提高公安机关执法水平和执法公信力，努力让人民群众在每一项执法活动、每一起案件办理中都能感受到社会公平正义。\n在创新社会治安治理机制方面，这次改革从完善治安管理防控机制、创新惩防犯罪工作机制、完善国际警务合作机制、健全情报信息主导警务机制等方面，提出了创新治安治理方式、提高治安治理水平的若干措施。围绕创新立体化社会治安防控体系，建立健全更加注重源头预防、综合治理的社会治安治理模式。加快建立以公民身份号码为基础的公民统一社会信用代码制度，推动建立违法犯罪记录与信用、相关职业准入等挂钩制度。健全社会治安组织动员机制，推动社会治安社会化治理。健全涉众型经济犯罪、涉电信诈骗犯罪侦查工作机制。健全同有关部门密切协作、高效顺畅的海外追逃追赃、遣返引渡工作机制，等等。\n在深化公安行政管理改革方面，这次改革从深化行政审批制度改革、扎实推进户籍制度改革、创新人口服务管理、健全完善外国人在中国永久居留制度和改革边防出入境、交通、消防监督管理制度等方面，提出了一系列服务改革开放、促进经济发展和便民利民的政策性措施、制度性安排。建立行政审批事项定期清理和行政审批权力清单制度。扎实推进户籍制度改革，取消暂住证制度，全面实施居住证制度，建立健全与居住年限等条件相挂钩的基本公共服务提供机制。落实无户口人员落户政策。建立户口迁移网上流转核验制度和居民身份证异地受理制度，方便异地办理户口和身份证。改革内地往来港澳边检查验模式，提高通关效率。向县级公安机关下放出入境证件受理审批权限。健全完善统一规范、灵活务实的外国人在中国永久居留制度。改革驾驶人培训考试，推行驾驶人自主预约考试、异地考试等制度。深化机动车检验改革，全面实施省内异地验车，逐步推行跨省异地验车。加快建立跨省异地处理交通违法和缴纳罚款制度。缩小建设工程消防审批范围。全面落实报警求助首接责任制、群众办事一次告知制、窗口单位弹性工作制，大力推行“预约服务”、“绿色通道”和“一站式”等服务模式。积极搭建综合性网络服务平台和新媒体移动终端，推行行政审批事项全程网上流转，方便群众咨询、办事和查询、监督，等等。\n在完善执法权力运行机制方面，这次改革从完善执法办案制度、执法司法衔接机制、执法责任制、人权保障制度等方面，提出了规范执法权力运行、促进社会公平正义的一系列改革举措。探索实行受案立案分离和立案归口管理制度。健全行政裁量基准制度，细化量化裁量标准。深化执法公开，落实执法告知制度。围绕推进以审判为中心的诉讼制度改革，完善适应证据裁判规则要求的证据收集工作机制，完善严格实行非法证据排除规则和严禁刑讯逼供、体罚虐待违法犯罪嫌疑人的工作机制，建立健全讯问犯罪嫌疑人录音录像制度和对违法犯罪嫌疑人辩解、申诉、控告认真审查、及时处理机制，完善侦查阶段听取辩护律师意见的工作制度。规范查封、扣押、冻结、处理涉案财物程序，实行涉案财物集中管理。完善执法责任制，健全执法过错纠正和责任追究制度，建立冤假错案责任终身追究制。探索建立主办侦查员制度，落实办案质量终身负责制，等等。\n全面深化公安改革还明确提出，根据人民警察的性质特点，建立有别于其他公务员的人民警察管理制度和保障机制。按照职位类别和职务序列，对人民警察实行分类管理。适应正规化、专业化、职业化建设要求，建立健全人民警察招录培养机制。贯彻落实人民警察生活待遇“高于地方、略低于军队”的原则，建立符合人民警察职业特点的工资待遇保障体系。完善人民警察抚恤优待制度，建立健全人身意外伤害保险等职业风险保障制度。依法维护人民警察执法权威。规范警务辅助人员管理，等等。\n延伸阅读\n公安部副部长黄明就全面深化公安改革有关情况答记者问","level":0}]},{"id":"r0622","sections":[{"name":"中共中央关于进一步全面深化改革 推进中国式现代化的决定","text":"中共中央关于进一步全面深化改革 推进中国式现代化的决定\n（2024年7月18日中国共产党第二十届中央委员会第三次全体会议通过）","level":1},{"name":"","text":"为贯彻落实党的二十大作出的战略部署，二十届中央委员会第三次全体会议研究了进一步全面深化改革、推进中国式现代化问题，作出如下决定。","level":0},{"name":"一、进一步全面深化改革、推进中国式现代化的重大意义和总体要求","text":"（1）进一步全面深化改革的重要性和必要性。改革开放是党和人民事业大踏步赶上时代的重要法宝。党的十一届三中全会是划时代的，开启了改革开放和社会主义现代化建设新时期。党的十八届三中全会也是划时代的，开启了新时代全面深化改革、系统整体设计推进改革新征程，开创了我国改革开放全新局面。\n以习近平同志为核心的党中央团结带领全党全军全国各族人民，以伟大的历史主动、巨大的政治勇气、强烈的责任担当，冲破思想观念束缚，突破利益固化藩篱，敢于突进深水区，敢于啃硬骨头，敢于涉险滩，坚决破除各方面体制机制弊端，实现改革由局部探索、破冰突围到系统集成、全面深化的转变，各领域基础性制度框架基本建立，许多领域实现历史性变革、系统性重塑、整体性重构，总体完成党的十八届三中全会确定的改革任务，实现到党成立一百周年时各方面制度更加成熟更加定型取得明显成效的目标，为全面建成小康社会、实现党的第一个百年奋斗目标提供有力制度保障，推动我国迈上全面建设社会主义现代化国家新征程。\n当前和今后一个时期是以中国式现代化全面推进强国建设、民族复兴伟业的关键时期。中国式现代化是在改革开放中不断推进的，也必将在改革开放中开辟广阔前景。面对纷繁复杂的国际国内形势，面对新一轮科技革命和产业变革，面对人民群众新期待，必须继续把改革推向前进。这是坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化的必然要求，是贯彻新发展理念、更好适应我国社会主要矛盾变化的必然要求，是坚持以人民为中心、让现代化建设成果更多更公平惠及全体人民的必然要求，是应对重大风险挑战、推动党和国家事业行稳致远的必然要求，是推动构建人类命运共同体、在百年变局加速演进中赢得战略主动的必然要求，是深入推进新时代党的建设新的伟大工程、建设更加坚强有力的马克思主义政党的必然要求。改革开放只有进行时，没有完成时。全党必须自觉把改革摆在更加突出位置，紧紧围绕推进中国式现代化进一步全面深化改革。\n（2）进一步全面深化改革的指导思想。坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，深入学习贯彻习近平总书记关于全面深化改革的一系列新思想、新观点、新论断，完整准确全面贯彻新发展理念，坚持稳中求进工作总基调，坚持解放思想、实事求是、与时俱进、求真务实，进一步解放和发展社会生产力、激发和增强社会活力，统筹国内国际两个大局，统筹推进“五位一体”总体布局，协调推进“四个全面”战略布局，以经济体制改革为牵引，以促进社会公平正义、增进人民福祉为出发点和落脚点，更加注重系统集成，更加注重突出重点，更加注重改革实效，推动生产关系和生产力、上层建筑和经济基础、国家治理和社会发展更好相适应，为中国式现代化提供强大动力和制度保障。\n（3）进一步全面深化改革的总目标。继续完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化。到二〇三五年，全面建成高水平社会主义市场经济体制，中国特色社会主义制度更加完善，基本实现国家治理体系和治理能力现代化，基本实现社会主义现代化，为到本世纪中叶全面建成社会主义现代化强国奠定坚实基础。\n——聚焦构建高水平社会主义市场经济体制，充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，坚持和完善社会主义基本经济制度，推进高水平科技自立自强，推进高水平对外开放，建成现代化经济体系，加快构建新发展格局，推动高质量发展。\n——聚焦发展全过程人民民主，坚持党的领导、人民当家作主、依法治国有机统一，推动人民当家作主制度更加健全、协商民主广泛多层制度化发展、中国特色社会主义法治体系更加完善，社会主义法治国家建设达到更高水平。\n——聚焦建设社会主义文化强国，坚持马克思主义在意识形态领域指导地位的根本制度，健全文化事业、文化产业发展体制机制，推动文化繁荣，丰富人民精神文化生活，提升国家文化软实力和中华文化影响力。\n——聚焦提高人民生活品质，完善收入分配和就业制度，健全社会保障体系，增强基本公共服务均衡性和可及性，推动人的全面发展、全体人民共同富裕取得更为明显的实质性进展。\n——聚焦建设美丽中国，加快经济社会发展全面绿色转型，健全生态环境治理体系，推进生态优先、节约集约、绿色低碳发展，促进人与自然和谐共生。\n——聚焦建设更高水平平安中国，健全国家安全体系，强化一体化国家战略体系，增强维护国家安全能力，创新社会治理体制机制和手段，有效构建新安全格局。\n——聚焦提高党的领导水平和长期执政能力，创新和改进领导方式和执政方式，深化党的建设制度改革，健全全面从严治党体系。\n到二〇二九年中华人民共和国成立八十周年时，完成本决定提出的改革任务。\n（4）进一步全面深化改革的原则。总结和运用改革开放以来特别是新时代全面深化改革的宝贵经验，贯彻以下原则：坚持党的全面领导，坚定维护党中央权威和集中统一领导，发挥党总揽全局、协调各方的领导核心作用，把党的领导贯穿改革各方面全过程，确保改革始终沿着正确政治方向前进；坚持以人民为中心，尊重人民主体地位和首创精神，人民有所呼、改革有所应，做到改革为了人民、改革依靠人民、改革成果由人民共享；坚持守正创新，坚持中国特色社会主义不动摇，紧跟时代步伐，顺应实践发展，突出问题导向，在新的起点上推进理论创新、实践创新、制度创新、文化创新以及其他各方面创新；坚持以制度建设为主线，加强顶层设计、总体谋划，破立并举、先立后破，筑牢根本制度，完善基本制度，创新重要制度；坚持全面依法治国，在法治轨道上深化改革、推进中国式现代化，做到改革和法治相统一，重大改革于法有据、及时把改革成果上升为法律制度；坚持系统观念，处理好经济和社会、政府和市场、效率和公平、活力和秩序、发展和安全等重大关系，增强改革系统性、整体性、协同性。","level":1},{"name":"二、构建高水平社会主义市场经济体制","text":"高水平社会主义市场经济体制是中国式现代化的重要保障。必须更好发挥市场机制作用，创造更加公平、更有活力的市场环境，实现资源配置效率最优化和效益最大化，既“放得活”又“管得住”，更好维护市场秩序、弥补市场失灵，畅通国民经济循环，激发全社会内生动力和创新活力。\n（5）坚持和落实“两个毫不动摇”。毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展，保证各种所有制经济依法平等使用生产要素、公平参与市场竞争、同等受到法律保护，促进各种所有制经济优势互补、共同发展。\n深化国资国企改革，完善管理监督体制机制，增强各有关管理部门战略协同，推进国有经济布局优化和结构调整，推动国有资本和国有企业做强做优做大，增强核心功能，提升核心竞争力。进一步明晰不同类型国有企业功能定位，完善主责主业管理，明确国有资本重点投资领域和方向。推动国有资本向关系国家安全、国民经济命脉的重要行业和关键领域集中，向关系国计民生的公共服务、应急能力、公益性领域等集中，向前瞻性战略性新兴产业集中。健全国有企业推进原始创新制度安排。深化国有资本投资、运营公司改革。建立国有企业履行战略使命评价制度，完善国有企业分类考核评价体系，开展国有经济增加值核算。推进能源、铁路、电信、水利、公用事业等行业自然垄断环节独立运营和竞争性环节市场化改革，健全监管体制机制。\n坚持致力于为非公有制经济发展营造良好环境和提供更多机会的方针政策。制定民营经济促进法。深入破除市场准入壁垒，推进基础设施竞争性领域向经营主体公平开放，完善民营企业参与国家重大项目建设长效机制。支持有能力的民营企业牵头承担国家重大技术攻关任务，向民营企业进一步开放国家重大科研基础设施。完善民营企业融资支持政策制度，破解融资难、融资贵问题。健全涉企收费长效监管和拖欠企业账款清偿法律法规体系。加快建立民营企业信用状况综合评价体系，健全民营中小企业增信制度。支持引导民营企业完善治理结构和管理制度，加强企业合规建设和廉洁风险防控。加强事中事后监管，规范涉民营企业行政检查。\n完善中国特色现代企业制度，弘扬企业家精神，支持和引导各类企业提高资源要素利用效率和经营管理水平、履行社会责任，加快建设更多世界一流企业。\n（6）构建全国统一大市场。推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通。加强公平竞争审查刚性约束，强化反垄断和反不正当竞争，清理和废除妨碍全国统一市场和公平竞争的各种规定和做法。规范地方招商引资法规制度，严禁违法违规给予政策优惠行为。建立健全统一规范、信息共享的招标投标和政府、事业单位、国有企业采购等公共资源交易平台体系，实现项目全流程公开管理。提升市场综合监管能力和水平。健全国家标准体系，深化地方标准管理制度改革。\n完善要素市场制度和规则，推动生产要素畅通流动、各类资源高效配置、市场潜力充分释放。构建城乡统一的建设用地市场。完善促进资本市场规范发展基础制度。培育全国一体化技术和数据市场。完善主要由市场供求关系决定要素价格机制，防止政府对价格形成的不当干预。健全劳动、资本、土地、知识、技术、管理、数据等生产要素由市场评价贡献、按贡献决定报酬的机制。推进水、能源、交通等领域价格改革，优化居民阶梯水价、电价、气价制度，完善成品油定价机制。\n完善流通体制，加快发展物联网，健全一体衔接的流通规则和标准，降低全社会物流成本。深化能源管理体制改革，建设全国统一电力市场，优化油气管网运行调度机制。\n加快培育完整内需体系，建立政府投资支持基础性、公益性、长远性重大项目建设长效机制，健全政府投资有效带动社会投资体制机制，深化投资审批制度改革，完善激发社会资本投资活力和促进投资落地机制，形成市场主导的有效投资内生增长机制。完善扩大消费长效机制，减少限制性措施，合理增加公共消费，积极推进首发经济。\n（7）完善市场经济基础制度。完善产权制度，依法平等长久保护各种所有制经济产权，建立高效的知识产权综合管理体制。完善市场信息披露制度，构建商业秘密保护制度。对侵犯各种所有制经济产权和合法利益的行为实行同责同罪同罚，完善惩罚性赔偿制度。加强产权执法司法保护，防止和纠正利用行政、刑事手段干预经济纠纷，健全依法甄别纠正涉企冤错案件机制。\n完善市场准入制度，优化新业态新领域市场准入环境。深化注册资本认缴登记制度改革，实行依法按期认缴。健全企业破产机制，探索建立个人破产制度，推进企业注销配套改革，完善企业退出制度。健全社会信用体系和监管制度。","level":1},{"name":"三、健全推动经济高质量发展体制机制","text":"高质量发展是全面建设社会主义现代化国家的首要任务。必须以新发展理念引领改革，立足新发展阶段，深化供给侧结构性改革，完善推动高质量发展激励约束机制，塑造发展新动能新优势。\n（8）健全因地制宜发展新质生产力体制机制。推动技术革命性突破、生产要素创新性配置、产业深度转型升级，推动劳动者、劳动资料、劳动对象优化组合和更新跃升，催生新产业、新模式、新动能，发展以高技术、高效能、高质量为特征的生产力。加强关键共性技术、前沿引领技术、现代工程技术、颠覆性技术创新，加强新领域新赛道制度供给，建立未来产业投入增长机制，完善推动新一代信息技术、人工智能、航空航天、新能源、新材料、高端装备、生物医药、量子科技等战略性产业发展政策和治理体系，引导新兴产业健康有序发展。以国家标准提升引领传统产业优化升级，支持企业用数智技术、绿色技术改造提升传统产业。强化环保、安全等制度约束。\n健全相关规则和政策，加快形成同新质生产力更相适应的生产关系，促进各类先进生产要素向发展新质生产力集聚，大幅提升全要素生产率。鼓励和规范发展天使投资、风险投资、私募股权投资，更好发挥政府投资基金作用，发展耐心资本。\n（9）健全促进实体经济和数字经济深度融合制度。加快推进新型工业化，培育壮大先进制造业集群，推动制造业高端化、智能化、绿色化发展。建设一批行业共性技术平台，加快产业模式和企业组织形态变革，健全提升优势产业领先地位体制机制。优化重大产业基金运作和监管机制，确保资金投向符合国家战略要求。建立保持制造业合理比重投入机制，合理降低制造业综合成本和税费负担。\n加快构建促进数字经济发展体制机制，完善促进数字产业化和产业数字化政策体系。加快新一代信息技术全方位全链条普及应用，发展工业互联网，打造具有国际竞争力的数字产业集群。促进平台经济创新发展，健全平台经济常态化监管制度。建设和运营国家数据基础设施，促进数据共享。加快建立数据产权归属认定、市场交易、权益分配、利益保护制度，提升数据安全治理监管能力，建立高效便利安全的数据跨境流动机制。\n（10）完善发展服务业体制机制。完善支持服务业发展政策体系，优化服务业核算，推进服务业标准化建设。聚焦重点环节分领域推进生产性服务业高质量发展，发展产业互联网平台，破除跨地区经营行政壁垒，推进生产性服务业融合发展。健全加快生活性服务业多样化发展机制。完善中介服务机构法规制度体系，促进中介服务机构诚实守信、依法履责。\n（11）健全现代化基础设施建设体制机制。构建新型基础设施规划和标准体系，健全新型基础设施融合利用机制，推进传统基础设施数字化改造，拓宽多元化投融资渠道，健全重大基础设施建设协调机制。深化综合交通运输体系改革，推进铁路体制改革，发展通用航空和低空经济，推动收费公路政策优化。提高航运保险承保能力和全球服务水平，推进海事仲裁制度规则创新。健全重大水利工程建设、运行、管理机制。\n（12）健全提升产业链供应链韧性和安全水平制度。抓紧打造自主可控的产业链供应链，健全强化集成电路、工业母机、医疗装备、仪器仪表、基础软件、工业软件、先进材料等重点产业链发展体制机制，全链条推进技术攻关、成果应用。建立产业链供应链安全风险评估和应对机制。完善产业在国内梯度有序转移的协作机制，推动转出地和承接地利益共享。建设国家战略腹地和关键产业备份。加快完善国家储备体系。完善战略性矿产资源探产供储销统筹和衔接体系。","level":1},{"name":"四、构建支持全面创新体制机制","text":"教育、科技、人才是中国式现代化的基础性、战略性支撑。必须深入实施科教兴国战略、人才强国战略、创新驱动发展战略，统筹推进教育科技人才体制机制一体改革，健全新型举国体制，提升国家创新体系整体效能。\n（13）深化教育综合改革。加快建设高质量教育体系，统筹推进育人方式、办学模式、管理体制、保障机制改革。完善立德树人机制，推进大中小学思政课一体化改革创新，健全德智体美劳全面培养体系，提升教师教书育人能力，健全师德师风建设长效机制，深化教育评价改革。优化高等教育布局，加快建设中国特色、世界一流的大学和优势学科。分类推进高校改革，建立科技发展、国家战略需求牵引的学科设置调整机制和人才培养模式，超常布局急需学科专业，加强基础学科、新兴学科、交叉学科建设和拔尖人才培养，着力加强创新能力培养。完善高校科技创新机制，提高成果转化效能。强化科技教育和人文教育协同。加快构建职普融通、产教融合的职业教育体系。完善学生实习实践制度。引导规范民办教育发展。推进高水平教育开放，鼓励国外高水平理工类大学来华合作办学。\n优化区域教育资源配置，建立同人口变化相协调的基本公共教育服务供给机制。完善义务教育优质均衡推进机制，探索逐步扩大免费教育范围。健全学前教育和特殊教育、专门教育保障机制。推进教育数字化，赋能学习型社会建设，加强终身教育保障。\n（14）深化科技体制改革。坚持面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康，优化重大科技创新组织机制，统筹强化关键核心技术攻关，推动科技创新力量、要素配置、人才队伍体系化、建制化、协同化。加强国家战略科技力量建设，完善国家实验室体系，优化国家科研机构、高水平研究型大学、科技领军企业定位和布局，推进科技创新央地协同，统筹各类科创平台建设，鼓励和规范发展新型研发机构，发挥我国超大规模市场引领作用，加强创新资源统筹和力量组织，推动科技创新和产业创新融合发展。构建科技安全风险监测预警和应对体系，加强科技基础条件自主保障。健全科技社团管理制度。扩大国际科技交流合作，鼓励在华设立国际科技组织，优化高校、科研院所、科技社团对外专业交流合作管理机制。\n改进科技计划管理，强化基础研究领域、交叉前沿领域、重点领域前瞻性、引领性布局。加强有组织的基础研究，提高科技支出用于基础研究比重，完善竞争性支持和稳定支持相结合的基础研究投入机制，鼓励有条件的地方、企业、社会组织、个人支持基础研究，支持基础研究选题多样化，鼓励开展高风险、高价值基础研究。深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为。\n强化企业科技创新主体地位，建立培育壮大科技领军企业机制，加强企业主导的产学研深度融合，建立企业研发准备金制度，支持企业主动牵头或参与国家科技攻关任务。构建促进专精特新中小企业发展壮大机制。鼓励科技型中小企业加大研发投入，提高研发费用加计扣除比例。鼓励和引导高校、科研院所按照先使用后付费方式把科技成果许可给中小微企业使用。\n完善中央财政科技经费分配和管理使用机制，健全中央财政科技计划执行和专业机构管理体制。扩大财政科研项目经费“包干制”范围，赋予科学家更大技术路线决定权、更大经费支配权、更大资源调度权。建立专家实名推荐的非共识项目筛选机制。允许科研类事业单位实行比一般事业单位更灵活的管理制度，探索实行企业化管理。\n深化科技成果转化机制改革，加强国家技术转移体系建设，加快布局建设一批概念验证、中试验证平台，完善首台（套）、首批次、首版次应用政策，加大政府采购自主创新产品力度。加强技术经理人队伍建设。\n允许科技人员在科技成果转化收益分配上有更大自主权，建立职务科技成果资产单列管理制度，深化职务科技成果赋权改革。深化高校、科研院所收入分配改革。允许更多符合条件的国有企业以创新创造为导向，在科研人员中开展多种形式中长期激励。\n构建同科技创新相适应的科技金融体制，加强对国家重大科技任务和科技型中小企业的金融支持，完善长期资本投早、投小、投长期、投硬科技的支持政策。健全重大技术攻关风险分散机制，建立科技保险政策体系。提高外资在华开展股权投资、风险投资便利性。\n（15）深化人才发展体制机制改革。实施更加积极、更加开放、更加有效的人才政策，完善人才自主培养机制，加快建设国家高水平人才高地和吸引集聚人才平台。加快建设国家战略人才力量，着力培养造就战略科学家、一流科技领军人才和创新团队，着力培养造就卓越工程师、大国工匠、高技能人才，提高各类人才素质。建设一流产业技术工人队伍。完善人才有序流动机制，促进人才区域合理布局，深化东中西部人才协作。完善青年创新人才发现、选拔、培养机制，更好保障青年科技人员待遇。健全保障科研人员专心科研制度。\n强化人才激励机制，坚持向用人主体授权、为人才松绑。建立以创新能力、质量、实效、贡献为导向的人才评价体系。打通高校、科研院所和企业人才交流通道。完善海外引进人才支持保障机制，形成具有国际竞争力的人才制度体系。探索建立高技术人才移民制度。","level":1},{"name":"五、健全宏观经济治理体系","text":"科学的宏观调控、有效的政府治理是发挥社会主义市场经济体制优势的内在要求。必须完善宏观调控制度体系，统筹推进财税、金融等重点领域改革，增强宏观政策取向一致性。\n（16）完善国家战略规划体系和政策统筹协调机制。构建国家战略制定和实施机制，加强国家重大战略深度融合，增强国家战略宏观引导、统筹协调功能。健全国家经济社会发展规划制度体系，强化规划衔接落实机制，发挥国家发展规划战略导向作用，强化国土空间规划基础作用，增强专项规划和区域规划实施支撑作用。健全专家参与公共决策制度。\n围绕实施国家发展规划、重大战略促进财政、货币、产业、价格、就业等政策协同发力，优化各类增量资源配置和存量结构调整。探索实行国家宏观资产负债表管理。把经济政策和非经济性政策都纳入宏观政策取向一致性评估。健全预期管理机制。健全支撑高质量发展的统计指标核算体系，加强新经济新领域纳统覆盖。加强产业活动单位统计基础建设，优化总部和分支机构统计办法，逐步推广经营主体活动发生地统计。健全国际宏观政策协调机制。\n（17）深化财税体制改革。健全预算制度，加强财政资源和预算统筹，把依托行政权力、政府信用、国有资源资产获取的收入全部纳入政府预算管理。完善国有资本经营预算和绩效评价制度，强化国家重大战略任务和基本民生财力保障。强化对预算编制和财政政策的宏观指导。加强公共服务绩效管理，强化事前功能评估。深化零基预算改革。统一预算分配权，提高预算管理统一性、规范性，完善预算公开和监督制度。完善权责发生制政府综合财务报告制度。\n健全有利于高质量发展、社会公平、市场统一的税收制度，优化税制结构。研究同新业态相适应的税收制度。全面落实税收法定原则，规范税收优惠政策，完善对重点领域和关键环节支持机制。健全直接税体系，完善综合和分类相结合的个人所得税制度，规范经营所得、资本所得、财产所得税收政策，实行劳动性所得统一征税。深化税收征管改革。\n建立权责清晰、财力协调、区域均衡的中央和地方财政关系。增加地方自主财力，拓展地方税源，适当扩大地方税收管理权限。完善财政转移支付体系，清理规范专项转移支付，增加一般性转移支付，提升市县财力同事权相匹配程度。建立促进高质量发展转移支付激励约束机制。推进消费税征收环节后移并稳步下划地方，完善增值税留抵退税政策和抵扣链条，优化共享税分享比例。研究把城市维护建设税、教育费附加、地方教育附加合并为地方附加税，授权地方在一定幅度内确定具体适用税率。合理扩大地方政府专项债券支持范围，适当扩大用作资本金的领域、规模、比例。完善政府债务管理制度，建立全口径地方债务监测监管体系和防范化解隐性债务风险长效机制，加快地方融资平台改革转型。规范非税收入管理，适当下沉部分非税收入管理权限，由地方结合实际差别化管理。\n适当加强中央事权、提高中央财政支出比例。中央财政事权原则上通过中央本级安排支出，减少委托地方代行的中央财政事权。不得违规要求地方安排配套资金，确需委托地方行使事权的，通过专项转移支付安排资金。\n（18）深化金融体制改革。加快完善中央银行制度，畅通货币政策传导机制。积极发展科技金融、绿色金融、普惠金融、养老金融、数字金融，加强对重大战略、重点领域、薄弱环节的优质金融服务。完善金融机构定位和治理，健全服务实体经济的激励约束机制。发展多元股权融资，加快多层次债券市场发展，提高直接融资比重。优化国有金融资本管理体制。\n健全投资和融资相协调的资本市场功能，防风险、强监管，促进资本市场健康稳定发展。支持长期资金入市。提高上市公司质量，强化上市公司监管和退市制度。建立增强资本市场内在稳定性长效机制。完善大股东、实际控制人行为规范约束机制。完善上市公司分红激励约束机制。健全投资者保护机制。推动区域性股权市场规则对接、标准统一。\n制定金融法。完善金融监管体系，依法将所有金融活动纳入监管，强化监管责任和问责制度，加强中央和地方监管协同。建设安全高效的金融基础设施，统一金融市场登记托管、结算清算规则制度，建立风险早期纠正硬约束制度，筑牢有效防控系统性风险的金融稳定保障体系。健全金融消费者保护和打击非法金融活动机制，构建产业资本和金融资本“防火墙”。推动金融高水平开放，稳慎扎实推进人民币国际化，发展人民币离岸市场。稳妥推进数字人民币研发和应用。加快建设上海国际金融中心。\n完善准入前国民待遇加负面清单管理模式，支持符合条件的外资机构参与金融业务试点。稳慎拓展金融市场互联互通，优化合格境外投资者制度。推进自主可控的跨境支付体系建设，强化开放条件下金融安全机制。建立统一的全口径外债监管体系。积极参与国际金融治理。\n（19）完善实施区域协调发展战略机制。构建优势互补的区域经济布局和国土空间体系。健全推动西部大开发形成新格局、东北全面振兴取得新突破、中部地区加快崛起、东部地区加快推进现代化的制度和政策体系。推动京津冀、长三角、粤港澳大湾区等地区更好发挥高质量发展动力源作用，优化长江经济带发展、黄河流域生态保护和高质量发展机制。高标准高质量推进雄安新区建设。推动成渝地区双城经济圈建设走深走实。健全主体功能区制度体系，强化国土空间优化发展保障机制。完善区域一体化发展机制，构建跨行政区合作发展新机制，深化东中西部产业协作。完善促进海洋经济发展体制机制。","level":1},{"name":"六、完善城乡融合发展体制机制","text":"城乡融合发展是中国式现代化的必然要求。必须统筹新型工业化、新型城镇化和乡村全面振兴，全面提高城乡规划、建设、治理融合水平，促进城乡要素平等交换、双向流动，缩小城乡差别，促进城乡共同繁荣发展。\n（20）健全推进新型城镇化体制机制。构建产业升级、人口集聚、城镇发展良性互动机制。推行由常住地登记户口提供基本公共服务制度，推动符合条件的农业转移人口社会保险、住房保障、随迁子女义务教育等享有同迁入地户籍人口同等权利，加快农业转移人口市民化。保障进城落户农民合法土地权益，依法维护进城落户农民的土地承包权、宅基地使用权、集体收益分配权，探索建立自愿有偿退出的办法。\n坚持人民城市人民建、人民城市为人民。健全城市规划体系，引导大中小城市和小城镇协调发展、集约紧凑布局。深化城市建设、运营、治理体制改革，加快转变城市发展方式。推动形成超大特大城市智慧高效治理新体系，建立都市圈同城化发展体制机制。深化赋予特大镇同人口和经济规模相适应的经济社会管理权改革。建立可持续的城市更新模式和政策法规，加强地下综合管廊建设和老旧管线改造升级，深化城市安全韧性提升行动。\n（21）巩固和完善农村基本经营制度。有序推进第二轮土地承包到期后再延长三十年试点，深化承包地所有权、承包权、经营权分置改革，发展农业适度规模经营。完善农业经营体系，完善承包地经营权流转价格形成机制，促进农民合作经营，推动新型农业经营主体扶持政策同带动农户增收挂钩。健全便捷高效的农业社会化服务体系。发展新型农村集体经济，构建产权明晰、分配合理的运行机制，赋予农民更加充分的财产权益。\n（22）完善强农惠农富农支持制度。坚持农业农村优先发展，完善乡村振兴投入机制。壮大县域富民产业，构建多元化食物供给体系，培育乡村新产业新业态。优化农业补贴政策体系，发展多层次农业保险。完善覆盖农村人口的常态化防止返贫致贫机制，建立农村低收入人口和欠发达地区分层分类帮扶制度。健全脱贫攻坚国家投入形成资产的长效管理机制。运用“千万工程”经验，健全推动乡村全面振兴长效机制。\n加快健全种粮农民收益保障机制，推动粮食等重要农产品价格保持在合理水平。统筹建立粮食产销区省际横向利益补偿机制，在主产区利益补偿上迈出实质步伐。统筹推进粮食购销和储备管理体制机制改革，建立监管新模式。健全粮食和食物节约长效机制。\n（23）深化土地制度改革。改革完善耕地占补平衡制度，各类耕地占用纳入统一管理，完善补充耕地质量验收机制，确保达到平衡标准。完善高标准农田建设、验收、管护机制。健全保障耕地用于种植基本农作物管理体系。允许农户合法拥有的住房通过出租、入股、合作等方式盘活利用。有序推进农村集体经营性建设用地入市改革，健全土地增值收益分配机制。\n优化土地管理，健全同宏观政策和区域发展高效衔接的土地管理制度，优先保障主导产业、重大项目合理用地，使优势地区有更大发展空间。建立新增城镇建设用地指标配置同常住人口增加协调机制。探索国家集中垦造耕地定向用于特定项目和地区落实占补平衡机制。优化城市工商业土地利用，加快发展建设用地二级市场，推动土地混合开发利用、用途合理转换，盘活存量土地和低效用地。开展各类产业园区用地专项治理。制定工商业用地使用权延期和到期后续期政策。","level":1},{"name":"七、完善高水平对外开放体制机制","text":"开放是中国式现代化的鲜明标识。必须坚持对外开放基本国策，坚持以开放促改革，依托我国超大规模市场优势，在扩大国际合作中提升开放能力，建设更高水平开放型经济新体制。\n（24）稳步扩大制度型开放。主动对接国际高标准经贸规则，在产权保护、产业补贴、环境标准、劳动保护、政府采购、电子商务、金融领域等实现规则、规制、管理、标准相通相容，打造透明稳定可预期的制度环境。扩大自主开放，有序扩大我国商品市场、服务市场、资本市场、劳务市场等对外开放，扩大对最不发达国家单边开放。深化援外体制机制改革，实现全链条管理。\n维护以世界贸易组织为核心的多边贸易体制，积极参与全球经济治理体系改革，提供更多全球公共产品。扩大面向全球的高标准自由贸易区网络，建立同国际通行规则衔接的合规机制，优化开放合作环境。\n（25）深化外贸体制改革。强化贸易政策和财税、金融、产业政策协同，打造贸易强国制度支撑和政策支持体系，加快内外贸一体化改革，积极应对贸易数字化、绿色化趋势。推进通关、税务、外汇等监管创新，营造有利于新业态新模式发展的制度环境。创新发展数字贸易，推进跨境电商综合试验区建设。建设大宗商品交易中心，建设全球集散分拨中心，支持各类主体有序布局海外流通设施，支持有条件的地区建设国际物流枢纽中心和大宗商品资源配置枢纽。健全贸易风险防控机制，完善出口管制体系和贸易救济制度。\n创新提升服务贸易，全面实施跨境服务贸易负面清单，推进服务业扩大开放综合试点示范，鼓励专业服务机构提升国际化服务能力。加快推进离岸贸易发展，发展新型离岸国际贸易业务。建立健全跨境金融服务体系，丰富金融产品和服务供给。\n（26）深化外商投资和对外投资管理体制改革。营造市场化、法治化、国际化一流营商环境，依法保护外商投资权益。扩大鼓励外商投资产业目录，合理缩减外资准入负面清单，落实全面取消制造业领域外资准入限制措施，推动电信、互联网、教育、文化、医疗等领域有序扩大开放。深化外商投资促进体制机制改革，保障外资企业在要素获取、资质许可、标准制定、政府采购等方面的国民待遇，支持参与产业链上下游配套协作。完善境外人员入境居住、医疗、支付等生活便利制度。完善促进和保障对外投资体制机制，健全对外投资管理服务体系，推动产业链供应链国际合作。\n（27）优化区域开放布局。巩固东部沿海地区开放先导地位，提高中西部和东北地区开放水平，加快形成陆海内外联动、东西双向互济的全面开放格局。发挥沿海、沿边、沿江和交通干线等优势，优化区域开放功能分工，打造形态多样的开放高地。实施自由贸易试验区提升战略，鼓励首创性、集成式探索。加快建设海南自由贸易港。\n发挥“一国两制”制度优势，巩固提升香港国际金融、航运、贸易中心地位，支持香港、澳门打造国际高端人才集聚高地，健全香港、澳门在国家对外开放中更好发挥作用机制。深化粤港澳大湾区合作，强化规则衔接、机制对接。完善促进两岸经济文化交流合作制度和政策，深化两岸融合发展。\n（28）完善推进高质量共建“一带一路”机制。继续实施“一带一路”科技创新行动计划，加强绿色发展、数字经济、人工智能、能源、税收、金融、减灾等领域的多边合作平台建设。完善陆海天网一体化布局，构建“一带一路”立体互联互通网络。统筹推进重大标志性工程和“小而美”民生项目。","level":1},{"name":"八、健全全过程人民民主制度体系","text":"发展全过程人民民主是中国式现代化的本质要求。必须坚定不移走中国特色社会主义政治发展道路，坚持和完善我国根本政治制度、基本政治制度、重要政治制度，丰富各层级民主形式，把人民当家作主具体、现实体现到国家政治生活和社会生活各方面。\n（29）加强人民当家作主制度建设。坚持好、完善好、运行好人民代表大会制度。健全人大对行政机关、监察机关、审判机关、检察机关监督制度，完善监督法及其实施机制，强化人大预算决算审查监督和国有资产管理、政府债务管理监督。健全人大议事规则和论证、评估、评议、听证制度。丰富人大代表联系人民群众的内容和形式。健全吸纳民意、汇集民智工作机制。发挥工会、共青团、妇联等群团组织联系服务群众的桥梁纽带作用。\n（30）健全协商民主机制。发挥人民政协作为专门协商机构作用，健全深度协商互动、意见充分表达、广泛凝聚共识的机制，加强人民政协反映社情民意、联系群众、服务人民机制建设。完善人民政协民主监督机制。\n完善协商民主体系，丰富协商方式，健全政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商以及社会组织协商制度化平台，加强各种协商渠道协同配合。健全协商于决策之前和决策实施之中的落实机制，完善协商成果采纳、落实、反馈机制。\n（31）健全基层民主制度。健全基层党组织领导的基层群众自治机制，完善基层民主制度体系和工作体系，拓宽基层各类组织和群众有序参与基层治理渠道。完善办事公开制度。健全以职工代表大会为基本形式的企事业单位民主管理制度，完善企业职工参与管理的有效形式。\n（32）完善大统战工作格局。完善发挥统一战线凝聚人心、汇聚力量政治作用的政策举措。坚持好、发展好、完善好中国新型政党制度。更好发挥党外人士作用，健全党外代表人士队伍建设制度。制定民族团结进步促进法，健全铸牢中华民族共同体意识制度机制，增强中华民族凝聚力。系统推进我国宗教中国化，加强宗教事务治理法治化。完善党外知识分子和新的社会阶层人士政治引领机制。全面构建亲清政商关系，健全促进非公有制经济健康发展、非公有制经济人士健康成长工作机制。完善港澳台和侨务工作机制。","level":1},{"name":"九、完善中国特色社会主义法治体系","text":"法治是中国式现代化的重要保障。必须全面贯彻实施宪法，维护宪法权威，协同推进立法、执法、司法、守法各环节改革，健全法律面前人人平等保障机制，弘扬社会主义法治精神，维护社会公平正义，全面推进国家各方面工作法治化。\n（33）深化立法领域改革。完善以宪法为核心的中国特色社会主义法律体系，健全保证宪法全面实施制度体系，建立宪法实施情况报告制度。完善党委领导、人大主导、政府依托、各方参与的立法工作格局。统筹立改废释纂，加强重点领域、新兴领域、涉外领域立法，完善合宪性审查、备案审查制度，提高立法质量。探索区域协同立法。健全党内法规同国家法律法规衔接协调机制。建设全国统一的法律法规和规范性文件信息平台。\n（34）深入推进依法行政。推进政府机构、职能、权限、程序、责任法定化，促进政务服务标准化、规范化、便利化，完善覆盖全国的一体化在线政务服务平台。完善重大决策、规范性文件合法性审查机制。加强政府立法审查。深化行政执法体制改革，完善基层综合执法体制机制，健全行政执法监督体制机制。完善行政处罚等领域行政裁量权基准制度，推动行政执法标准跨区域衔接。完善行政处罚和刑事处罚双向衔接制度。健全行政复议体制机制。完善行政裁决制度。完善垂直管理体制和地方分级管理体制，健全垂直管理机构和地方协作配合机制。稳妥推进人口小县机构优化。深化开发区管理制度改革。优化事业单位结构布局，强化公益性。\n（35）健全公正执法司法体制机制。健全监察机关、公安机关、检察机关、审判机关、司法行政机关各司其职，监察权、侦查权、检察权、审判权、执行权相互配合、相互制约的体制机制，确保执法司法各环节全过程在有效制约监督下运行。深化审判权和执行权分离改革，健全国家执行体制，强化当事人、检察机关和社会公众对执行活动的全程监督。完善执法司法救济保护制度，完善国家赔偿制度。深化和规范司法公开，落实和完善司法责任制。规范专门法院设置。深化行政案件级别管辖、集中管辖、异地管辖改革。构建协同高效的警务体制机制，推进地方公安机关机构编制管理改革，继续推进民航公安机关和海关缉私部门管理体制改革。规范警务辅助人员管理制度。\n坚持正确人权观，加强人权执法司法保障，完善事前审查、事中监督、事后纠正等工作机制，完善涉及公民人身权利强制措施以及查封、扣押、冻结等强制措施的制度，依法查处利用职权徇私枉法、非法拘禁、刑讯逼供等犯罪行为。推进刑事案件律师辩护全覆盖。建立轻微犯罪记录封存制度。\n（36）完善推进法治社会建设机制。健全覆盖城乡的公共法律服务体系，深化律师制度、公证体制、仲裁制度、调解制度、司法鉴定管理体制改革。改进法治宣传教育，完善以实践为导向的法学院校教育培养机制。加强和改进未成年人权益保护，强化未成年人犯罪预防和治理，制定专门矫治教育规定。\n（37）加强涉外法治建设。建立一体推进涉外立法、执法、司法、守法和法律服务、法治人才培养的工作机制。完善涉外法律法规体系和法治实施体系，深化执法司法国际合作。完善涉外民事法律关系中当事人依法约定管辖、选择适用域外法等司法审判制度。健全国际商事仲裁和调解制度，培育国际一流仲裁机构、律师事务所。积极参与国际规则制定。","level":1},{"name":"十、深化文化体制机制改革","text":"中国式现代化是物质文明和精神文明相协调的现代化。必须增强文化自信，发展社会主义先进文化，弘扬革命文化，传承中华优秀传统文化，加快适应信息技术迅猛发展新形势，培育形成规模宏大的优秀文化人才队伍，激发全民族文化创新创造活力。\n（38）完善意识形态工作责任制。健全用党的创新理论武装全党、教育人民、指导实践工作体系，完善党委（党组）理论学习中心组学习制度，完善思想政治工作体系。创新马克思主义理论研究和建设工程，实施哲学社会科学创新工程，构建中国哲学社会科学自主知识体系。完善新闻发言人制度。构建适应全媒体生产传播工作机制和评价体系，推进主流媒体系统性变革。完善舆论引导机制和舆情应对协同机制。\n推动理想信念教育常态化制度化。完善培育和践行社会主义核心价值观制度机制。改进创新文明培育、文明实践、文明创建工作机制。实施文明乡风建设工程。优化英模人物宣传学习机制，创新爱国主义教育和各类群众性主题活动组织机制，推动全社会崇尚英雄、缅怀先烈、争做先锋。构建中华传统美德传承体系，健全社会公德、职业道德、家庭美德、个人品德建设体制机制，健全诚信建设长效机制，教育引导全社会自觉遵守法律、遵循公序良俗，坚决反对拜金主义、享乐主义、极端个人主义和历史虚无主义。形成网上思想道德教育分众化、精准化实施机制。建立健全道德领域突出问题协同治理机制，完善“扫黄打非”长效机制。\n（39）优化文化服务和文化产品供给机制。完善公共文化服务体系，建立优质文化资源直达基层机制，健全社会力量参与公共文化服务机制，推进公共文化设施所有权和使用权分置改革。深化文化领域国资国企改革，分类推进文化事业单位深化内部改革，完善文艺院团建设发展机制。\n坚持以人民为中心的创作导向，坚持出成果和出人才相结合、抓作品和抓环境相贯通，改进文艺创作生产服务、引导、组织工作机制。健全文化产业体系和市场体系，完善文化经济政策。探索文化和科技融合的有效机制，加快发展新型文化业态。深化文化领域行政审批备案制度改革，加强事中事后监管。深化文娱领域综合治理。\n建立文化遗产保护传承工作协调机构，建立文化遗产保护督察制度，推动文化遗产系统性保护和统一监管。构建中华文明标识体系。健全文化和旅游深度融合发展体制机制。完善全民健身公共服务体系，改革完善竞技体育管理体制和运行机制。\n（40）健全网络综合治理体系。深化网络管理体制改革，整合网络内容建设和管理职能，推进新闻宣传和网络舆论一体化管理。完善生成式人工智能发展和管理机制。加强网络空间法治建设，健全网络生态治理长效机制，健全未成年人网络保护工作体系。\n（41）构建更有效力的国际传播体系。推进国际传播格局重构，深化主流媒体国际传播机制改革创新，加快构建多渠道、立体式对外传播格局。加快构建中国话语和中国叙事体系，全面提升国际传播效能。建设全球文明倡议践行机制。推动走出去、请进来管理便利化，扩大国际人文交流合作。","level":1},{"name":"十一、健全保障和改善民生制度体系","text":"在发展中保障和改善民生是中国式现代化的重大任务。必须坚持尽力而为、量力而行，完善基本公共服务制度体系，加强普惠性、基础性、兜底性民生建设，解决好人民最关心最直接最现实的利益问题，不断满足人民对美好生活的向往。\n（42）完善收入分配制度。构建初次分配、再分配、第三次分配协调配套的制度体系，提高居民收入在国民收入分配中的比重，提高劳动报酬在初次分配中的比重。完善劳动者工资决定、合理增长、支付保障机制，健全按要素分配政策制度。完善税收、社会保障、转移支付等再分配调节机制。支持发展公益慈善事业。\n规范收入分配秩序，规范财富积累机制，多渠道增加城乡居民财产性收入，形成有效增加低收入群体收入、稳步扩大中等收入群体规模、合理调节过高收入的制度体系。深化国有企业工资决定机制改革，合理确定并严格规范国有企业各级负责人薪酬、津贴补贴等。\n（43）完善就业优先政策。健全高质量充分就业促进机制，完善就业公共服务体系，着力解决结构性就业矛盾。完善高校毕业生、农民工、退役军人等重点群体就业支持体系，健全终身职业技能培训制度。统筹城乡就业政策体系，同步推进户籍、用人、档案等服务改革，优化创业促进就业政策环境，支持和规范发展新就业形态。完善促进机会公平制度机制，畅通社会流动渠道。完善劳动关系协商协调机制，加强劳动者权益保障。\n（44）健全社会保障体系。完善基本养老保险全国统筹制度，健全全国统一的社保公共服务平台。健全社保基金保值增值和安全监管体系。健全基本养老、基本医疗保险筹资和待遇合理调整机制，逐步提高城乡居民基本养老保险基础养老金。健全灵活就业人员、农民工、新就业形态人员社保制度，扩大失业、工伤、生育保险覆盖面，全面取消在就业地参保户籍限制，完善社保关系转移接续政策。加快发展多层次多支柱养老保险体系，扩大年金制度覆盖范围，推行个人养老金制度。发挥各类商业保险补充保障作用。推进基本医疗保险省级统筹，深化医保支付方式改革，完善大病保险和医疗救助制度，加强医保基金监管。健全社会救助体系。健全保障妇女儿童合法权益制度。完善残疾人社会保障制度和关爱服务体系。\n加快建立租购并举的住房制度，加快构建房地产发展新模式。加大保障性住房建设和供给，满足工薪群体刚性住房需求。支持城乡居民多样化改善性住房需求。充分赋予各城市政府房地产市场调控自主权，因城施策，允许有关城市取消或调减住房限购政策、取消普通住宅和非普通住宅标准。改革房地产开发融资方式和商品房预售制度。完善房地产税收制度。\n（45）深化医药卫生体制改革。实施健康优先发展战略，健全公共卫生体系，促进社会共治、医防协同、医防融合，强化监测预警、风险评估、流行病学调查、检验检测、应急处置、医疗救治等能力。促进医疗、医保、医药协同发展和治理。促进优质医疗资源扩容下沉和区域均衡布局，加快建设分级诊疗体系，推进紧密型医联体建设，强化基层医疗卫生服务。深化以公益性为导向的公立医院改革，建立以医疗服务为主导的收费机制，完善薪酬制度，建立编制动态调整机制。引导规范民营医院发展。创新医疗卫生监管手段。健全支持创新药和医疗器械发展机制，完善中医药传承创新发展机制。\n（46）健全人口发展支持和服务体系。以应对老龄化、少子化为重点完善人口发展战略，健全覆盖全人群、全生命周期的人口服务体系，促进人口高质量发展。完善生育支持政策体系和激励机制，推动建设生育友好型社会。有效降低生育、养育、教育成本，完善生育休假制度，建立生育补贴制度，提高基本生育和儿童医疗公共服务水平，加大个人所得税抵扣力度。加强普惠育幼服务体系建设，支持用人单位办托、社区嵌入式托育、家庭托育点等多种模式发展。把握人口流动客观规律，推动相关公共服务随人走，促进城乡、区域人口合理集聚、有序流动。\n积极应对人口老龄化，完善发展养老事业和养老产业政策机制。发展银发经济，创造适合老年人的多样化、个性化就业岗位。按照自愿、弹性原则，稳妥有序推进渐进式延迟法定退休年龄改革。优化基本养老服务供给，培育社区养老服务机构，健全公办养老机构运营机制，鼓励和引导企业等社会力量积极参与，推进互助性养老服务，促进医养结合。加快补齐农村养老服务短板。改善对孤寡、残障失能等特殊困难老年人的服务，加快建立长期护理保险制度。","level":1},{"name":"十二、深化生态文明体制改革","text":"中国式现代化是人与自然和谐共生的现代化。必须完善生态文明制度体系，协同推进降碳、减污、扩绿、增长，积极应对气候变化，加快完善落实绿水青山就是金山银山理念的体制机制。\n（47）完善生态文明基础体制。实施分区域、差异化、精准管控的生态环境管理制度，健全生态环境监测和评价制度。建立健全覆盖全域全类型、统一衔接的国土空间用途管制和规划许可制度。健全自然资源资产产权制度和管理制度体系，完善全民所有自然资源资产所有权委托代理机制，建立生态环境保护、自然资源保护利用和资产保值增值等责任考核监督制度。完善国家生态安全工作协调机制。编纂生态环境法典。\n（48）健全生态环境治理体系。推进生态环境治理责任体系、监管体系、市场体系、法律法规政策体系建设。完善精准治污、科学治污、依法治污制度机制，落实以排污许可制为核心的固定污染源监管制度，建立新污染物协同治理和环境风险管控体系，推进多污染物协同减排。深化环境信息依法披露制度改革，构建环境信用监管体系。推动重要流域构建上下游贯通一体的生态环境治理体系。全面推进以国家公园为主体的自然保护地体系建设。\n落实生态保护红线管理制度，健全山水林田湖草沙一体化保护和系统治理机制，建设多元化生态保护修复投入机制。落实水资源刚性约束制度，全面推行水资源费改税。强化生物多样性保护工作协调机制。健全海洋资源开发保护制度。健全生态产品价值实现机制。深化自然资源有偿使用制度改革。推进生态综合补偿，健全横向生态保护补偿机制，统筹推进生态环境损害赔偿。\n（49）健全绿色低碳发展机制。实施支持绿色低碳发展的财税、金融、投资、价格政策和标准体系，发展绿色低碳产业，健全绿色消费激励机制，促进绿色低碳循环发展经济体系建设。优化政府绿色采购政策，完善绿色税制。完善资源总量管理和全面节约制度，健全废弃物循环利用体系。健全煤炭清洁高效利用机制。加快规划建设新型能源体系，完善新能源消纳和调控政策措施。完善适应气候变化工作体系。建立能耗双控向碳排放双控全面转型新机制。构建碳排放统计核算体系、产品碳标识认证制度、产品碳足迹管理体系，健全碳市场交易制度、温室气体自愿减排交易制度，积极稳妥推进碳达峰碳中和。","level":1},{"name":"十三、推进国家安全体系和能力现代化","text":"国家安全是中国式现代化行稳致远的重要基础。必须全面贯彻总体国家安全观，完善维护国家安全体制机制，实现高质量发展和高水平安全良性互动，切实保障国家长治久安。\n（50）健全国家安全体系。强化国家安全工作协调机制，完善国家安全法治体系、战略体系、政策体系、风险监测预警体系，完善重点领域安全保障体系和重要专项协调指挥体系。构建联动高效的国家安全防护体系，推进国家安全科技赋能。\n（51）完善公共安全治理机制。健全重大突发公共事件处置保障体系，完善大安全大应急框架下应急指挥机制，强化基层应急基础和力量，提高防灾减灾救灾能力。完善安全生产风险排查整治和责任倒查机制。完善食品药品安全责任体系。健全生物安全监管预警防控体系。加强网络安全体制建设，建立人工智能安全监管制度。\n（52）健全社会治理体系。坚持和发展新时代“枫桥经验”，健全党组织领导的自治、法治、德治相结合的城乡基层治理体系，完善共建共治共享的社会治理制度。探索建立全国统一的人口管理制度。健全社会工作体制机制，加强党建引领基层治理，加强社会工作者队伍建设，推动志愿服务体系建设。推进信访工作法治化。提高市域社会治理能力，强化市民热线等公共服务平台功能，健全“高效办成一件事”重点事项清单管理机制和常态化推进机制。健全社会心理服务体系和危机干预机制。健全发挥家庭家教家风建设在基层治理中作用的机制。深化行业协会商会改革。健全社会组织管理制度。\n健全乡镇（街道）职责和权力、资源相匹配制度，加强乡镇（街道）服务管理力量。完善社会治安整体防控体系，健全扫黑除恶常态化机制，依法严惩群众反映强烈的违法犯罪活动。\n（53）完善涉外国家安全机制。建立健全周边安全工作协调机制。强化海外利益和投资风险预警、防控、保护体制机制，深化安全领域国际执法合作，维护我国公民、法人在海外合法权益。健全反制裁、反干涉、反“长臂管辖”机制。健全维护海洋权益机制。完善参与全球安全治理机制。","level":1},{"name":"十四、持续深化国防和军队改革","text":"国防和军队现代化是中国式现代化的重要组成部分。必须坚持党对人民军队的绝对领导，深入实施改革强军战略，为如期实现建军一百年奋斗目标、基本实现国防和军队现代化提供有力保障。\n（54）完善人民军队领导管理体制机制。健全贯彻军委主席负责制的制度机制，深入推进政治建军。优化军委机关部门职能配置，健全战建备统筹推进机制，完善重大决策咨询评估机制，深化战略管理创新，完善军事治理体系。健全依法治军工作机制。完善作战战备、军事人力资源等领域配套政策制度。深化军队院校改革，推动院校内涵式发展。实施军队企事业单位调整改革。\n（55）深化联合作战体系改革。完善军委联合作战指挥中心职能，健全重大安全领域指挥功能，建立同中央和国家机关协调运行机制。优化战区联合作战指挥中心编成，完善任务部队联合作战指挥编组模式。加强网络信息体系建设运用统筹。构建新型军兵种结构布局，加快发展战略威慑力量，大力发展新域新质作战力量，统筹加强传统作战力量建设。优化武警部队力量编成。\n（56）深化跨军地改革。健全一体化国家战略体系和能力建设工作机制，完善涉军决策议事协调体制机制。健全国防建设军事需求提报和军地对接机制，完善国防动员体系。深化国防科技工业体制改革，优化国防科技工业布局，改进武器装备采购制度，建立军品设计回报机制，构建武器装备现代化管理体系。完善军地标准化工作统筹机制。加强航天、军贸等领域建设和管理统筹。优化边海防领导管理体制机制，完善党政军警民合力治边机制。深化民兵制度改革。完善双拥工作机制。","level":1},{"name":"十五、提高党对进一步全面深化改革、推进中国式现代化的领导水平","text":"党的领导是进一步全面深化改革、推进中国式现代化的根本保证。必须深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，保持以党的自我革命引领社会革命的高度自觉，坚持用改革精神和严的标准管党治党，完善党的自我革命制度规范体系，不断推进党的自我净化、自我完善、自我革新、自我提高，确保党始终成为中国特色社会主义事业的坚强领导核心。\n（57）坚持党中央对进一步全面深化改革的集中统一领导。党中央领导改革的总体设计、统筹协调、整体推进。完善党中央重大决策部署落实机制，确保党中央令行禁止。各级党委（党组）负责落实党中央决策部署，谋划推进本地区本部门改革，鼓励结合实际开拓创新，创造可复制、可推广的新鲜经验。走好新时代党的群众路线，把社会期盼、群众智慧、专家意见、基层经验充分吸收到改革设计中来。围绕解决突出矛盾设置改革议题，优化重点改革方案生成机制，坚持真理、修正错误，及时发现问题、纠正偏差。完善改革激励和舆论引导机制，营造良好改革氛围。\n（58）深化党的建设制度改革。以调动全党抓改革、促发展的积极性、主动性、创造性为着力点，完善党的建设制度机制。加强党的创新理论武装，建立健全以学铸魂、以学增智、以学正风、以学促干长效机制。深化干部人事制度改革，鲜明树立选人用人正确导向，大力选拔政治过硬、敢于担当、锐意改革、实绩突出、清正廉洁的干部，着力解决干部乱作为、不作为、不敢为、不善为问题。树立和践行正确政绩观，健全有效防范和纠治政绩观偏差工作机制。落实“三个区分开来”，激励干部开拓进取、干事创业。推进领导干部能上能下常态化，加大调整不适宜担任现职干部力度。健全常态化培训特别是基本培训机制，强化专业训练和实践锻炼，全面提高干部现代化建设能力。完善和落实领导干部任期制，健全领导班子主要负责人变动交接制度。增强党组织政治功能和组织功能。探索加强新经济组织、新社会组织、新就业群体党的建设有效途径。完善党员教育管理、作用发挥机制。完善党内法规，增强党内法规权威性和执行力。\n（59）深入推进党风廉政建设和反腐败斗争。健全政治监督具体化、精准化、常态化机制。锲而不舍落实中央八项规定精神，健全防治形式主义、官僚主义制度机制。持续精简规范会议文件和各类创建示范、评比达标、节庆展会论坛活动，严格控制面向基层的督查、检查、考核总量，提高调研质量，下大气力解决过频过繁问题。制定乡镇（街道）履行职责事项清单，健全为基层减负长效机制。建立经常性和集中性相结合的纪律教育机制，深化运用监督执纪“四种形态”，综合发挥党的纪律教育约束、保障激励作用。\n完善一体推进不敢腐、不能腐、不想腐工作机制，着力铲除腐败滋生的土壤和条件。健全不正之风和腐败问题同查同治机制，深化整治权力集中、资金密集、资源富集领域腐败，严肃查处政商勾连破坏政治生态和经济发展环境问题，完善对重点行贿人的联合惩戒机制，丰富防治新型腐败和隐性腐败的有效办法。加强诬告行为治理。健全追逃防逃追赃机制。加强新时代廉洁文化建设。\n完善党和国家监督体系。强化全面从严治党主体责任和监督责任。健全加强对“一把手”和领导班子监督配套制度。完善权力配置和运行制约机制，反对特权思想和特权现象。推进执纪执法和刑事司法有机衔接。健全巡视巡察工作体制机制。优化监督检查和审查调查机构职能，完善垂直管理单位纪检监察体制，推进向中管企业全面派驻纪检监察组。深化基层监督体制机制改革。推进反腐败国家立法，修改监察法，出台反跨境腐败法。\n（60）以钉钉子精神抓好改革落实。对党中央进一步全面深化改革的决策部署，全党必须求真务实抓落实、敢作善为抓落实，坚持上下协同、条块结合，科学制定改革任务书、时间表、优先序，明确各项改革实施主体和责任，把重大改革落实情况纳入监督检查和巡视巡察内容，以实绩实效和人民群众满意度检验改革。\n中国式现代化是走和平发展道路的现代化。对外工作必须坚定奉行独立自主的和平外交政策，推动构建人类命运共同体，践行全人类共同价值，落实全球发展倡议、全球安全倡议、全球文明倡议，倡导平等有序的世界多极化、普惠包容的经济全球化，深化外事工作机制改革，参与引领全球治理体系改革和建设，坚定维护国家主权、安全、发展利益，为进一步全面深化改革、推进中国式现代化营造良好外部环境。\n全党全军全国各族人民要更加紧密地团结在以习近平同志为核心的党中央周围，高举改革开放旗帜，凝心聚力、奋发进取，为全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴而努力奋斗。\n延伸阅读\n习近平：关于《中共中央关于进一步全面深化改革、推进中国式现代化的决定》的说明\n党的二十届三中全会","level":1}]},{"id":"r0623","sections":[{"name":"中共中央办公厅 国务院办公厅关于做好第二轮土地承包到期后再延长30年试点工作的意见","text":"中共中央办公厅 国务院办公厅关于做好第二轮土地承包到期后再延长30年试点工作的意见","level":1},{"name":"","text":"保持土地承包关系稳定并长久不变，第二轮土地承包到期后再延长30年，是以习近平同志为核心的党中央作出的重大决策部署。为积极稳妥做好第二轮土地承包到期后再延长30年试点工作（以下简称延包试点），经党中央、国务院同意，根据有关法律法规和政策要求，现提出如下意见。","level":0},{"name":"一、总体要求","text":"坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，全面落实习近平总书记关于“三农”工作的重要论述，坚持稳中求进、守正创新，牢牢把住处理好农民和土地关系这条主线，锚定加快建设农业强国目标，坚持把依法维护农民权益作为出发点和落脚点，把强化集体所有制根基、保障和实现农民集体成员权利同激活资源要素统一起来，充分运用农村承包地确权登记颁证成果，通过细致工作有序推进，确保第二轮土地承包到期后再延长30年政策扎实落实到位，不断完善农村承包地所有权、承包权、经营权分置政策体系，进一步巩固和完善农村基本经营制度。\n工作中要做到：坚持集体所有制不动摇，严禁打破原集体土地所有权的界限在全村范围内搞平均承包，充分维护农民集体对承包地发包、调整、监督、收回等各项权能，探索和丰富农村土地集体所有制的有效实现形式。坚持农户家庭承包经营，农村集体土地由本集体经济组织内农民家庭承包，农户承包地要保持稳定，发包方及其他组织、个人不得违法调整和收回农户承包地。坚持农民主体地位，充分发挥农民主动性和创造性，鼓励农民集体在法律和政策范围内因地制宜探索延包具体路径和办法。坚持维护农村社会稳定，尊重历史、照顾现实，统筹考虑、循序渐进，科学合理安排进度，做好矛盾纠纷调处，保持农村社会稳定安宁。\n各级党委和政府要深刻认识开展延包试点的重要性、艰巨性、复杂性，提前谋划，做好工作指导，积极稳妥推进各项部署落实，加强探索实践并根据实际情况及时调整完善相关措施。第二轮土地承包合同到期的，原则上要在期满后1年内完成延包工作。","level":1},{"name":"二、稳妥有序开展延包试点","text":"（一）坚持延包原则。开展延包试点，以农村承包地确权登记颁证成果为基础，以第二轮土地承包合同到期为起点再延长承包期30年。以户为单位开展延包，确保绝大多数农户原有承包地继续保持稳定，不能推倒重来、打乱重分，不能借机违法调整或收回农户承包地。\n（二）依法依规从严掌握“小调整”。坚持“大稳定、小调整”，“小调整”的前提是“大稳定”。“小调整”是指在农村集体经济组织个别农户之间进行承包地小范围适当调整，仅限于少数存在承包地因自然灾害毁损等特殊情形且群众普遍要求调地的村组。\n（三）规范延包程序。要按照延包工作规程确定的成立工作小组、摸底核实、制定方案、开展调查、审核公示、签订合同、完善证书、资料归档等程序规范开展试点。延包工作小组由本集体经济组织成员大会或成员代表大会依法选举产生。延包方案由农民集体在法律和政策范围内民主协商，在本集体经济组织范围内公示不少于15日，依照相关法律规定征得本集体经济组织成员同意后公开组织实施。延包方案涉及承包地调整的，应当报乡（镇）政府和县级政府农业农村主管部门批准。县级以上地方政府农业农村主管部门、乡（镇）政府要加强对延包方案制定和实施的指导监督，发现问题的，应当及时予以纠正。\n（四）妥善解决突出矛盾。依法维护第二轮土地承包期放弃承包等无地农户的合法权益，妥善处置因缺地少地导致生活困难农户的合理诉求。鼓励按照相关规定通过集体收益分配、提供就业服务、公益性岗位安置等土地以外的方式解决突出矛盾。对承包地暂缓确权登记颁证等问题，结合延包试点妥善处置。","level":1},{"name":"三、加强农民土地承包权益保护","text":"（五）保障农村集体经济组织成员土地承包权益。具有本集体经济组织成员身份的承包农户家庭成员依法享有土地承包权益，非集体经济组织成员不参与延包。充分保障出嫁、离婚、丧偶妇女和入赘婿等群体的知情权、参与权，做好跨区域协调工作，避免“两头空”、防止“两头占”，依照农村土地承包法、农村集体经济组织法等法律法规维护其合法土地承包权益。依法保障进城落户农民合法土地承包权益。探索建立农户自愿有偿退出土地承包经营权的办法。\n（六）依法收回消亡户承包地。坚持农村土地农民集体所有，因家庭成员全部死亡而导致承包方消亡的，发包方应当依法收回承包地，原承包方应得的承包收益，依照民法典规定继承。承包方分立、合并的，应当与发包方确立新的承包关系。相关程序等由省级政府农业农村主管部门作出规定。\n（七）严格机动地和新增耕地管理。机动地面积不得超过本集体经济组织耕地总面积的5%，且不得新增。通过依法开垦、复垦及土地整理等方式新增加的耕地要严格管理，县级以上政府依法明确土地所有权。确定为农村集体所有耕地的纳入农村集体财产管理，在尊重农民意愿前提下，通过确权确地、确权确股等方式承包到户，可以采取多种方式发展生产经营，由集体经营的所得收益主要用于分红，确保集体经济组织成员受益。\n（八）从严掌握确权确股不确地。坚持确权到户到地，不得违背农民意愿以行政手段推动确权确股不确地，也不得简单以少数服从多数的名义强迫不愿确股的农民确股。实行确权确股不确地的条件和程序，由省级政府农业农村主管部门依法作出规定。","level":1},{"name":"四、加强农村土地承包合同管理","text":"（九）全面开展合同网签。加快健全国家、省、市、县互联互通的农村土地承包信息应用平台，抓紧建立全国统一的农村土地承包合同网签系统。健全农村土地承包合同网签制度，对出现互换、转让、土地征收和承包方分立、合并等情形的，及时变更或终止承包合同。\n（十）加强档案管理。延包试点中形成的对国家、社会和个人有保存价值的各种文字、图表、声像、数据等文件材料，应当纳入农村土地承包档案管理。制定延包档案管理办法。县级以上地方政府农业农村主管部门和档案主管部门及乡镇党委和政府应当制定工作方案，健全管理制度，确保农村土地承包档案完整和安全。发包方应当将农村土地承包档案纳入村级档案管理。\n（十一）做好与不动产统一登记有序衔接。加强农村土地承包合同信息与登记信息、征地信息等互通共享，保障土地承包合同管理与不动产登记有序衔接。已颁发的土地承包权利证书在新的承包期继续有效且不变不换。承包方、承包地块等发生变化的，可依据承包合同办理不动产登记。对延包中仅因土地承包合同期限变化顺延的，依据承包合同记载的信息办理登记，在原农村土地承包经营权证上标注记载，加盖不动产登记专用章。不得搞统一换发证书，增加基层和农民负担。\n（十二）保障流转土地稳定经营。依法保障流转双方合法权益，发挥好农村集体经济组织作用，在尊重农民意愿前提下，引导承包方和受让方充分协商，通过合同约定等方式明确承包延期后土地续租事宜，稳定经营主体预期。强化流转土地经营权监管，不鼓励大规模长时间流转农村土地。坚决遏制流转土地“非农化”，有效防止“非粮化”。","level":1},{"name":"五、加强组织领导","text":"（十三）健全工作机制。坚持和加强党对延包工作的全面领导，由中央统筹、省负总责、市县乡抓落实，省市县乡逐级成立工作专班，切实解决突出问题，坚决落实工作责任。在党中央集中统一领导下，中央农村工作领导小组负责延包工作的牵头抓总、统筹协调和督促落实，定期听取进展汇报，及时研究重大问题、总结推广先进经验。完善第二轮土地承包到期后再延长30年试点部际联席会议工作制度，农业农村部、中央农办履行牵头单位职责，抓好延包工作组织实施；司法、财政、自然资源、档案、妇联等部门按照职责分工做好相关工作，加强政策支持协同，推动延包工作落实。各省（自治区、直辖市）党委和政府要加强组织领导，研究制定延包具体办法，加强调度监测，试点期间每年向党中央、国务院报告情况。县乡党委和政府要针对具体问题制定工作方案，明确专人负责，加强延包政策、业务和技术培训，稳妥做好合同网签、信息变更、纠纷调处等工作。充分发挥农村基层党组织领导作用，组织村“两委”成员、派驻干部、到村任职选调生、老党员等积极参与相关工作，充实村组延包工作力量。各地在延包试点中不得向农民收取费用。\n（十四）做好宣传引导。加大政策宣传培训力度，通过政府网站、新闻发布会以及报刊、广播、电视、新媒体等渠道，采取群众喜闻乐见的方式，使广大干部群众全面准确了解延包政策，营造良好社会氛围。\n（十五）加强风险防范。密切关注延包试点中出现的新情况新问题，及时报告工作中遇到的困难和问题。出台政策前要做好社会稳定风险评估。健全多元化纠纷解决机制，加强农村土地承包经营纠纷调解仲裁队伍能力建设和条件保障，依法采取协商、调解、仲裁、诉讼等方式及时稳妥解决延包中出现的矛盾纠纷。","level":1}]},{"id":"r0624","sections":[{"name":"中共中央办公厅印发《关于全面落实中央纪委向中央一级党和国家机关派驻纪检机构的方案》的通知","text":"点击此处观看视频","level":1},{"name":"","text":"近日，经党中央同意，中共中央办公厅印发了《关于全面落实中央纪委向中央一级党和国家机关派驻纪检机构的方案》的通知。中央决定，中央纪委共设置47家派驻机构，其中，综合派驻27家、单独派驻20家，实现对139家中央一级党和国家机关派驻纪检机构全覆盖，并对领导体制、职能调整、主要职责、机构设置等作出了明确规定。\n党的十八届三中全会《决定》要求：“全面落实中央纪委向中央一级党和国家机关派驻纪检机构，实行统一名称、统一管理。派驻机构对派出机关负责，履行监督职责。”贯彻三中全会精神，中央纪委态度坚决、立行立改。2014年12月，中央制定出台《关于加强中央纪委派驻机构建设的意见》，为派驻全覆盖确定了时间表和路线图。2015年1月，经中央审批同意，中央纪委在中央办公厅、中央组织部、中央宣传部、中央统战部、全国人大机关、国务院办公厅、全国政协机关等对党和国家政治生活有重要影响的中央和国家机关新设7家派驻机构，其中5家实行综合派驻，为实现派驻全覆盖创新了方法、探索了路径。\n中央纪委对中央一级党和国家机关全面派驻纪检机构，是深化纪律检查体制改革的重要成果。全面派驻根植于党的十八大以来派驻工作改革实践土壤，坚持内涵发展、创新组织制度，内部挖潜、盘活存量，采取综合派驻和单独派驻相结合的方式实现全覆盖。综合派驻改变“一对一”的模式，有效整合现有派驻机构的力量，做到精简高效。综合派驻纪检组在一家机关办公、管若干家的事，地位相对超脱，有利于聚焦中心任务，强化监督执纪问责，增强派驻监督相对独立性和权威性，充分发挥“派”的权威和“驻”的优势。\n实现派驻机构全覆盖，有利于强化党的自我监督，使党内监督不留死角、没有空白，为全面从严治党提供有力支撑。目前，各派驻纪检组主要负责人均已到位。下一步，中央纪委将按照中央部署，抓紧落实后续工作，会同有关部门完成纪检组组建，选好配强派驻机构领导班子和干部队伍。中央纪委要求，各派驻纪检组要边组建边工作，做好调整中的工作衔接，理顺工作关系，建立健全工作机制。各省区市纪委要按照中央要求，统一规划、分步实施，结合实际推进本地区派驻监督全覆盖。","level":0}]},{"id":"r0625","sections":[{"name":"中共中央 国务院印发《扩大内需战略规划纲要（2022—2035年）》","text":"近日，中共中央、国务院印发了《扩大内需战略规划纲要（2022—2035年）》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《扩大内需战略规划纲要（2022—2035年）》主要内容如下。\n坚定实施扩大内需战略、培育完整内需体系，是加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局的必然选择，是促进我国长远发展和长治久安的战略决策。为推动实施扩大内需战略，根据《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》，制定本规划纲要。","level":0},{"name":"一、规划背景","text":"（一）我国扩大内需已取得显著成效\n改革开放以来特别是党的十八大以来，我国在深度参与国际产业分工的同时，不断提升国内供给质量水平，着力释放国内市场需求，促进形成强大国内市场，内需对经济发展的支撑作用明显增强。\n消费基础性作用持续强化。最终消费支出占国内生产总值的比重连续11年保持在50%以上。住行消费等传统消费显著增长，城镇居民人均住房建筑面积稳步提高，汽车新车销量连续13年位居全球第一。消费新业态新模式快速发展，2021年实物商品网上零售额占社会消费品零售总额比重为24.5%，人均服务性消费支出占人均消费支出比重为44.2%。\n投资关键作用更好发挥。我国资本形成总额占国内生产总值的比重保持在合理水平，为优化供给结构、推动经济平稳发展提供了有力支撑。基础设施建设水平全面提升，全国综合运输大通道加快贯通，一批重大水利设施建成使用。5G等新型基础设施建设加快推进，重大科技项目建设取得显著成就，高技术产业投资持续较快增长。医疗卫生、生态环保、农业农村、教育等领域短板弱项加快补齐。\n国内市场运行机制不断健全。高标准市场体系加快建设，“放管服”改革持续深化，营商环境不断优化，要素市场化配置、产权制度等重点改革稳步推进，流通体系加快健全，社会保障制度逐步完善，统筹城乡的基本公共服务体系加快形成，市场活力得到有效激发。\n国际国内市场联系更加紧密。我国国内生产总值超过110万亿元，已成为全球第二大商品消费市场，带动进口规模持续扩大、结构不断优化。国际经贸合作扎实推进，对外开放高地建设进展显著，我国成为最具吸引力的外资流入国之一，利用外资质量不断提高，我国市场与全球市场进一步协调发展、互惠互利。\n（二）重大意义\n实施扩大内需战略是满足人民对美好生活向往的现实需要。我国经济由高速增长阶段转向高质量发展阶段，发展要求和发展条件都呈现新特征，特别是人民对美好生活的向往总体上已经从“有没有”转向“好不好”，呈现多样化、多层次、多方面的特点。解决人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，必须坚定实施扩大内需战略，固根基、扬优势、补短板、强弱项，通过增加高质量产品和服务供给，满足人民群众需要，促进人的全面发展和社会全面进步，推动供需在更高水平上实现良性循环。\n实施扩大内需战略是充分发挥超大规模市场优势的主动选择。大国经济具有内需为主导的显著特征。内需市场一头连着经济发展，一头连着社会民生，是经济发展的主要依托。我国经济经过改革开放40多年持续快速发展，逐步在市场需求、产业体系、人力资源、软硬基础设施等方面形成了超大规模市场优势，为培育完整内需体系奠定了基础。进一步发挥超大规模市场优势，必须坚定实施扩大内需战略，扩大居民消费和有效投资，增强经济发展韧性，促进经济持续健康发展。\n实施扩大内需战略是应对国际环境深刻变化的必然要求。世界百年未有之大变局加速演进，国际力量对比深刻调整，新冠肺炎疫情影响广泛深远，世界经济增长不平衡不确定性增大，单边主义、保护主义、霸权主义对世界和平与发展构成威胁。面对复杂严峻的外部环境，必须坚定实施扩大内需战略，以自身的稳定发展有效应对外部风险挑战。\n实施扩大内需战略是更高效率促进经济循环的关键支撑。构建新发展格局关键在于经济循环的畅通无阻。促进国内大循环更为顺畅，必须坚定实施扩大内需战略，打通经济循环堵点，夯实国内基本盘；实现国内国际双循环相互促进，也必须坚定实施扩大内需战略，更好依托国内大市场，有效利用全球要素和市场资源，更高效率实现内外市场联通，促进发展更高水平的国内大循环。\n（三）机遇和挑战\n进入新发展阶段，我国国内市场基础更加扎实，实施扩大内需战略的环境条件深刻变化。展望未来一段时期，国内市场主导国民经济循环特征会更加明显，消费已成为我国经济增长的主拉动力，居民消费优化升级同现代科技和生产方式相结合，我国这一全球最有潜力的消费市场还将不断成长壮大。我国正处于新型工业化、信息化、城镇化、农业现代化快速发展阶段，与发达国家相比，在很多方面还有较大投资空间，投资需求潜力巨大。同时，中国特色社会主义制度优势显著，宏观经济治理能力持续提升，改革创新不断孕育新的发展动力，全国统一大市场加快建设，商品和要素流通制度环境持续改善，我国生产要素质量和配置水平显著提升，国内市场空间更趋广阔。\n同时要看到，我国扩大内需仍面临不少制约。劳动力、土地、环境等要素趋紧制约投资增长，创新能力不能完全适应高质量发展要求，群众个性化、多样化消费需求难以得到有效满足；城乡区域发展和收入分配差距较大，民生保障存在短板，财政金融等领域风险隐患不容忽视，制约内需潜力释放的体制机制堵点仍然较多；国际竞争日趋激烈，把我国打造成国际高端要素资源的“引力场”任重道远。\n综合来看，我国扩大内需机遇和挑战都有新的发展变化，总体上机遇大于挑战。必须坚定实施扩大内需战略，准确把握国内市场发展规律，未雨绸缪，趋利避害，在危机中育先机、于变局中开新局，不断释放内需潜力，充分发挥内需拉动作用，建设更加强大的国内市场，推动我国经济平稳健康可持续发展。","level":1},{"name":"二、总体要求","text":"（四）指导思想\n以习近平新时代中国特色社会主义思想为指导，坚持稳中求进工作总基调，立足新发展阶段，完整、准确、全面贯彻新发展理念，构建新发展格局，以推动高质量发展为主题，以深化供给侧结构性改革为主线，以改革创新为根本动力，以满足人民日益增长的美好生活需要为根本目的，坚持系统观念，更好统筹发展和安全，牢牢把握扩大内需这个战略基点，加快培育完整内需体系，加强需求侧管理，促进形成强大国内市场，着力畅通国内经济大循环，促进国内国际双循环良性互动，推动我国经济行稳致远、社会安定和谐，为全面建设社会主义现代化国家奠定坚实基础。\n（五）工作原则\n——坚持党的领导，发挥制度优势。充分发挥党总揽全局、协调各方的领导核心作用，贯彻党把方向、谋大局、定政策、促改革的要求，把党的领导贯彻到扩大内需战略实施全过程，发挥我国国家制度和国家治理体系多方面显著优势，为扩大内需战略实施提供根本保证。\n——坚持人民立场，增进民生福祉。坚持以人民为中心，把满足人民日益增长的美好生活需要作为扩大内需的出发点和落脚点，始终做到发展为了人民、发展依靠人民、发展成果由人民共享，扎实推动共同富裕，不断增强人民群众的获得感、幸福感、安全感。\n——坚持顶层设计，服务全局战略。坚持扩大内需这个战略基点，以创新驱动、高质量供给引领和创造新需求，使扩大内需成为构建新发展格局的重要支撑，推动质量变革、效率变革、动力变革，促进供需在更高水平上实现动态平衡。\n——坚持改革开放，增强内生动力。坚定不移用改革的办法释放和激发市场潜力，把有效市场和有为政府结合起来，充分发挥市场在资源配置中的决定性作用，更好发挥政府作用，破除制约内需增长的体制机制障碍，不断提高要素配置和产品流通效率，同时实施更高水平对外开放，充分利用国际高端要素资源，持续增强国内市场活力。\n——坚持系统观念，强化协同高效。加强前瞻性思考、全局性谋划、战略性布局、整体性推进，加快培育完整内需体系，统筹好供给和需求、消费和投资、内需和外需、数量和质量、国内和国际、速度和效益、效率和公平、发展和安全等重大关系，尽力而为、量力而行，实现发展质量、结构、规模、速度、效益、安全相统一，使扩大内需成为一个可持续的历史过程。\n（六）发展目标\n按照全面建设社会主义现代化国家的战略安排，展望2035年，实施扩大内需战略的远景目标是：消费和投资规模再上新台阶，完整内需体系全面建立；新型工业化、信息化、城镇化、农业现代化基本实现，强大国内市场建设取得更大成就，关键核心技术实现重大突破，以创新驱动、内需拉动的国内大循环更加高效畅通；人民生活更加美好，城乡居民人均收入再迈上新的大台阶，中等收入群体显著扩大，基本公共服务实现均等化，城乡区域发展差距和居民生活水平差距显著缩小，全体人民共同富裕取得更为明显的实质性进展；改革对内需发展的支撑作用大幅提升，高标准市场体系更加健全，现代流通体系全面建成；我国参与全球经济合作和竞争新优势持续增强，国内市场的国际影响力大幅提升。\n锚定2035年远景目标，综合考虑发展环境和发展条件，“十四五”时期实施扩大内需战略的主要目标是：\n——促进消费投资，内需规模实现新突破。消费的基础性作用和投资的关键作用进一步增强。内需持续健康发展，质量效益明显提升，超大规模市场优势充分发挥，国内市场更加强大，培育完整内需体系取得明显进展。\n——完善分配格局，内需潜能不断释放。分配结构明显改善，城乡区域发展差距和居民生活水平差距逐步缩小，居民人均可支配收入实际增长和经济增长基本同步。基本公共服务均等化水平持续提升，多层次社会保障体系更加健全，社会事业加快发展。\n——提升供给质量，国内需求得到更好满足。供给侧结构性改革取得重大进展，农业基础更加稳固，制造业比重基本稳定，现代服务业加快建设，实体经济发展根基进一步夯实，传统产业改造提升加速推进，新产业新业态加快发展，创新能力显著提升，产业基础高级化、产业链现代化水平明显提高，供给体系对国内需求的适配性不断增强。\n——完善市场体系，激发内需取得明显成效。统一开放、竞争有序、制度完备、治理完善的高标准市场体系基本建成，商品和要素在城乡区域间流动更加顺畅，产权制度改革和要素市场化配置改革取得重大进展，营商环境持续优化，公平竞争制度更加完善，现代流通体系建立健全。\n——畅通经济循环，内需发展效率持续提升。更高水平开放型经济新体制基本形成，我国与周边区域经济合作程度进一步加深，对周边和全球经济发展的带动作用不断增强。\n（七）重点任务\n坚持问题导向，围绕推动高质量发展，针对我国中长期扩大内需面临的主要问题，特别是有效供给能力不足、分配差距较大、流通体系现代化程度不高、消费体制机制不健全、投资结构仍需优化等堵点难点，部署实施扩大内需战略的重点任务。\n加快培育完整内需体系。把实施扩大内需战略同深化供给侧结构性改革有机结合起来，按照生产、分配、流通、消费和投资再生产的全链条拓展内需体系，培育由提高供给质量、优化分配格局、健全流通体系、全面促进消费、拓展投资空间等共同组成的完整内需体系。\n促进形成强大国内市场。着力挖掘内需潜力，特别是推进新型城镇化和城乡区域协调发展释放内需潜能，进一步做大国内市场规模。通过优化市场结构、健全市场机制、激发市场活力、提升市场韧性，进一步做强国内市场，促进国内市场平稳发展和国际影响力持续提升。\n支撑畅通国内经济循环。进一步推进各种要素组合有机衔接和循环流转，形成产品服务增加、社会财富积聚、人民福祉增进、国家实力增强的良性国内经济循环。以强大的国内经济循环为支撑，着力推进高水平对外开放，打造国际高端要素资源“引力场”，使国内和国际市场更好联通，以国际循环提升国内大循环效率和水平，实现国内国际双循环互促共进。","level":1},{"name":"三、全面促进消费，加快消费提质升级","text":"最终消费是经济增长的持久动力。顺应消费升级趋势，提升传统消费，培育新型消费，扩大服务消费，适当增加公共消费，着力满足个性化、多样化、高品质消费需求。\n（八）持续提升传统消费\n提高吃穿等基本消费品质。加强引导、强化监督、支持创新，推动增加高品质基本消费品供给，推进内外销产品同线同标同质。倡导健康饮食结构，增加健康、营养农产品和食品供给，促进餐饮业健康发展。坚持不懈制止餐饮浪费。\n释放出行消费潜力。优化城市交通网络布局，大力发展智慧交通。推动汽车消费由购买管理向使用管理转变。推进汽车电动化、网联化、智能化，加强停车场、充电桩、换电站、加氢站等配套设施建设。便利二手车交易。\n促进居住消费健康发展。坚持“房子是用来住的、不是用来炒的”定位，加强房地产市场预期引导，探索新的发展模式，加快建立多主体供给、多渠道保障、租购并举的住房制度，稳妥实施房地产市场平稳健康发展长效机制，支持居民合理自住需求，遏制投资投机性需求，稳地价、稳房价、稳预期。完善住房保障基础性制度和支持政策，以人口净流入的大城市为重点，扩大保障性租赁住房供给。因地制宜发展共有产权住房。完善长租房政策，逐步使租购住房在享受公共服务上具有同等权利。健全住房公积金制度。推进无障碍设施建设，促进家庭装修消费，增加智能家电消费，推动数字家庭发展。\n更好满足中高端消费品消费需求。促进免税业健康有序发展。促进民族品牌加强同国际标准接轨，充分衔接国内消费需求，增加中高端消费品国内供应。培育建设国际消费中心城市，打造一批区域消费中心。深入推进海南国际旅游消费中心建设。\n（九）积极发展服务消费\n扩大文化和旅游消费。完善现代文化产业体系和文化市场体系，推进优质文化资源开发，推动中华优秀传统文化创造性转化、创新性发展。鼓励文化文物单位依托馆藏文化资源，开发各类文化创意产品，扩大优质文化产品和服务供给。大力发展度假休闲旅游。拓展多样化、个性化、定制化旅游产品和服务。加快培育海岛、邮轮、低空、沙漠等旅游业态。释放通用航空消费潜力。\n增加养老育幼服务消费。适应人口老龄化进程，推动养老事业和养老产业协同发展，加快健全居家社区机构相协调、医养康养相结合的养老服务体系。发展银发经济，推动公共设施适老化改造，开发适老化技术和产品。推动生育政策与经济社会政策配套衔接，减轻家庭生育、养育、教育负担，改善优生优育全程服务，释放生育政策潜力。增加普惠托育供给，发展集中管理运营的社区托育服务。\n提供多层次医疗健康服务。全面推进健康中国建设，深化医药卫生体制改革，完善公共卫生体系，促进公立医院高质量发展。支持社会力量提供多层次多样化医疗服务，鼓励发展全科医疗服务，增加专科医疗等细分服务领域有效供给。积极发展中医药事业，着力增加高质量的中医医疗、养生保健、康复、健康旅游等服务。积极发展个性化就医服务。加强职业健康保护。完善常态化疫情防控举措。适时优化国家免疫规划疫苗种类，逐步将安全、有效、财政可负担的疫苗纳入国家免疫规划。\n提升教育服务质量。健全国民教育体系，促进教育公平。完善普惠性学前教育和特殊教育、专门教育保障机制。推动义务教育优质均衡发展和城乡一体化。巩固提升高中阶段教育普及水平。着眼建设世界一流大学和一流科研院所，加强科教基础设施和产教融合平台建设。完善职业技术教育和培训体系，增强职业技术教育适应性。鼓励社会力量提供多样化教育服务，支持和规范民办教育发展，全面规范校外教育培训行为，稳步推进民办教育分类管理改革，开展高水平中外合作办学。\n促进群众体育消费。深入实施全民健身战略，建设国家步道体系，推动体育公园建设。以足球、篮球等职业体育为抓手，提升体育赛事活动质量和消费者观感、体验度，促进竞赛表演产业扩容升级。发展在线健身、线上赛事等新业态。推进冰雪运动“南展西扩东进”，带动群众“喜冰乐雪”。\n推动家政服务提质扩容。促进家政服务业专业化、规模化、网络化、规范化发展，完善家政服务标准体系，发展员工制家政企业。深化家政服务业提质扩容“领跑者”行动。提升家政服务和培训质量，推动社会化职业技能等级认定，加强家政从业人员职业风险保障。推进家政进社区，构建24小时全生活链服务体系。鼓励发展家庭管家等高端家政服务。\n提高社区公共服务水平。构建公共服务、便民利民服务、志愿互助服务相结合的社区服务体系，增强社区服务功能，引导社会力量参与社区服务供给，持续提升社区服务质量，提高社区服务智能化水平。支持家政、养老、托幼、物业等业态融合创新。提升社区疫情防控能力和水平。\n（十）加快培育新型消费\n支持线上线下商品消费融合发展。加快传统线下业态数字化改造和转型升级。丰富5G网络和千兆光网应用场景。加快研发智能化产品，支持自动驾驶、无人配送等技术应用。发展智慧超市、智慧商店、智慧餐厅等新零售业态。健全新型消费领域技术和服务标准体系，依法规范平台经济发展，提升新业态监管能力。\n培育“互联网+社会服务”新模式。做强做优线上学习服务，推动各类数字教育资源共建共享。积极发展“互联网+医疗健康”服务，健全互联网诊疗收费政策，将符合条件的互联网医疗服务项目按程序纳入医保支付范围。深入发展在线文娱，鼓励传统线下文化娱乐业态线上化，支持打造数字精品内容和新兴数字资源传播平台。鼓励发展智慧旅游、智慧广电、智能体育。支持便捷化线上办公、无接触交易服务等发展。\n促进共享经济等消费新业态发展。拓展共享生活新空间，鼓励共享出行、共享住宿、共享旅游等领域产品智能化升级和商业模式创新，完善具有公共服务属性的共享产品相关标准。打造共享生产新动力，鼓励企业开放平台资源，充分挖掘闲置存量资源应用潜力。鼓励制造业企业探索共享制造的商业模式和适用场景。顺应网络、信息等技术进步趋势，支持和引导新的生活和消费方式健康发展。\n发展新个体经济。支持社交电商、网络直播等多样化经营模式，鼓励发展基于知识传播、经验分享的创新平台。支持线上多样化社交、短视频平台规范有序发展，鼓励微应用、微产品、微电影等创新。\n（十一）大力倡导绿色低碳消费\n积极发展绿色低碳消费市场。健全绿色低碳产品生产和推广机制。促进居民耐用消费品绿色更新和品质升级。大力发展节能低碳建筑。完善绿色采购制度，加大政府对低碳产品采购力度。建立健全绿色产品标准、标识、认证体系和生态产品价值实现机制。加快构建废旧物资循环利用体系，规范发展汽车、动力电池、家电、电子产品回收利用行业。\n倡导节约集约的绿色生活方式。深入开展绿色生活创建。推进绿色社区建设。按照绿色低碳循环理念规划建设城乡基础设施。倡导绿色低碳出行，发展城市公共交通，完善城市慢行交通系统。完善城市生态和通风廊道，提升城市绿化水平。深入实施国家节水行动。持续推进过度包装治理，倡导消费者理性消费，推动形成“节约光荣、浪费可耻”的社会氛围。","level":1},{"name":"四、优化投资结构，拓展投资空间","text":"善于把握投资方向，消除投资障碍，聚焦关键领域和薄弱环节，努力增加制造业投资，加大重点领域补短板力度，系统布局新型基础设施，着力提高投资效率，促进投资规模合理增长、结构不断优化，增强投资增长后劲。\n（十二）加大制造业投资支持力度\n围绕推动制造业高质量发展、建设制造强国，引导各类优质资源要素向制造业集聚。加大传统制造业优化升级投资力度，扩大先进制造领域投资，提高制造业供给体系质量和效率。加大制造业技术改造力度，支持企业应用创新技术和产品实施技术改造。完善促进制造业发展的政策制度，降低企业生产经营成本，提升制造业盈利能力。加强制造业投资的用地、用能等要素保障。创新完善制造业企业股权、债券融资工具。\n（十三）持续推进重点领域补短板投资\n加快交通基础设施建设。完善以铁路为主干、以公路为基础、水运民航比较优势充分发挥的国家综合立体交通网，推进“6轴7廊8通道”主骨架建设，增强区域间、城市群间、省际间交通运输联系。加强中西部地区、沿江沿海战略骨干通道建设，有序推进能力紧张通道升级扩容，加强与周边国家互联互通。加快国家铁路网建设，贯通“八纵八横”高速铁路主通道，有序推进区域连接线建设，加快普速铁路建设和既有铁路改造升级。支持重点城市群率先建成城际铁路网，推进重点都市圈市域（郊）铁路和城市轨道交通发展，并与干线铁路融合发展。完善公路网骨干线路，提升国家高速公路网络质量，加快省际高速公路建设，推进普通国省道瓶颈路段贯通升级。继续推进“四好农村路”建设。加强航空网络建设，加快建设国际和区域枢纽机场，积极推进支线机场和通用机场建设，推动打造京津冀、长三角、粤港澳大湾区、成渝世界级机场群。提升水运综合优势，在津冀沿海、长三角、粤港澳大湾区推动构建世界级港口群，支持建设国际航运中心，加快长江等内河高等级航道网建设。构建多层级、一体化综合交通枢纽体系。\n加强能源基础设施建设。提升电网安全和智能化水平，优化电力生产和输送通道布局，完善电网主网架布局和结构，有序建设跨省跨区输电通道重点工程，积极推进配电网改造和农村电网建设，提升向边远地区输配电能力。优化煤炭产运结构，推进煤矿智能化、绿色化发展，优化建设蒙西、蒙东、陕北、山西、新疆五大煤炭供应保障基地，提高煤炭铁路运输能力。加快全国干线油气管道建设，集约布局、有序推进液化天然气接收站和车船液化天然气加注站规划建设。大幅提高清洁能源利用水平，建设多能互补的清洁能源基地，以沙漠、戈壁、荒漠地区为重点加快建设大型风电、光伏基地。统筹推进现役煤电机组超低排放和节能改造，提升煤电清洁高效发展水平。推动构建新型电力系统，提升清洁能源消纳和存储能力。\n加快水利基础设施建设。加快推进集防洪减灾、水资源调配、水生态保护等功能为一体的综合水网建设，提升国家水安全保障能力。推动综合性水利枢纽和调蓄工程建设，立足流域整体和水资源空间均衡配置，加快推进跨流域跨区域水资源配置工程建设，实施对区域发展具有重要作用的引调水工程，提升水资源优化配置能力。加强节水基础设施建设。提升水旱灾害防御能力，加快补齐大江大河大湖防洪短板，推进堤防加固、河道治理、控制性工程、蓄滞洪区等建设，加强中小河流治理、山洪灾害防治和病险水库除险加固。推进供水、灌溉、水源工程建设，加强供水区域间联合调度。有条件的地区可将城镇周边的村庄纳入城镇供水体系。强化农村中小型水源工程建设和饮用水水源保护，推进大中型灌区建设与现代化改造。在沿海缺水城市推动大型海水淡化设施建设。\n完善物流基础设施网络。统筹国家物流枢纽、国家骨干冷链物流基地、示范物流园区等布局建设，优化国家层面的骨干物流基础设施网络，提高跨区域物流服务能力，支撑构建“通道+枢纽+网络”的现代物流运行体系。优化以综合物流园区、专业配送中心、末端配送网点为支撑的商贸物流设施网络。加快建设农产品产地仓储保鲜冷链物流设施，提高城乡冷链设施网络覆盖水平，推动食品产销供的冷链全覆盖。\n加大生态环保设施建设力度。全面提升生态环境基础设施水平，构建集污水、垃圾、固废、危废、医废处理处置设施和监测监管能力于一体的环境基础设施体系，形成由城市向建制镇和乡村延伸覆盖的环境基础设施网络。实施重要生态系统保护和修复重大工程。推动建立生态保护补偿制度。全面推进资源高效利用，建设促进提高清洁能源利用水平、降低二氧化碳排放的生态环保设施。\n完善社会民生基础设施。补齐医疗领域建设短板，完善城市传染病救治网络，全面提升县级医院救治能力，持续改善县级医院设施条件，补齐乡镇卫生院、村卫生室等基础医疗设备配备，全面改善疾控机构设施设备条件，健全口岸公共卫生防控体系，提高公共卫生防控救治能力。加快补齐教育资源短板，加强教育基础设施建设，改善各级各类学校办学条件。增加普惠性养老和医养结合服务设施。完善妇幼健康服务设施，积极规划建设婴幼儿照护和未成年人保护服务机构及设施。提升县级公共文化设施水平，加强广播电视传输覆盖等设施建设。加快高品质、各具特色的旅游景区、度假区、休闲街区建设。提升体育场地设施水平，持续改善群众身边健身设施。\n（十四）系统布局新型基础设施\n加快建设信息基础设施。建设高速泛在、天地一体、集成互联、安全高效的信息基础设施，增强数据感知、传输、存储、运算能力。加快物联网、工业互联网、卫星互联网、千兆光网建设，构建全国一体化大数据中心体系，布局建设大数据中心国家枢纽节点，推动人工智能、云计算等广泛、深度应用，促进“云、网、端”资源要素相互融合、智能配置。以需求为导向，增强国家广域量子保密通信骨干网络服务能力。\n全面发展融合基础设施。推动5G、人工智能、大数据等技术与交通物流、能源、生态环保、水利、应急、公共服务等深度融合，助力相关行业治理能力提升。支持利用5G技术对有线电视网络进行改造升级。积极稳妥发展车联网。\n前瞻布局创新基础设施。支持有条件的地方建设区域性创新高地，适度超前布局建设重大科技基础设施。优化提升国家产业创新中心、国家制造业创新中心、国家工程研究中心、国家技术创新中心等产业创新基础设施，强化共性基础技术供给。","level":1},{"name":"五、推动城乡区域协调发展，释放内需潜能","text":"城镇化是扩大内需的重要支撑，把扩大内需战略和新型城镇化战略有序衔接起来，使之成为经济发展的重要推动力。推动城乡区域协调发展是释放内需潜能、促进产业升级的重要举措，坚持全国一盘棋，全面实施乡村振兴战略，坚持实施区域重大战略、区域协调发展战略，增强发展的整体性、协调性，充分释放内需潜在势能。\n（十五）推进以人为核心的新型城镇化\n推进农业转移人口市民化。深化户籍制度改革，建立健全经常居住地提供基本公共服务制度，促进农业转移人口全面融入城市，提高市民化质量。完善财政转移支付与农业转移人口市民化挂钩相关政策。依法保障进城落户农民农村土地承包权、宅基地使用权、集体收益分配权，建立农村产权流转市场体系，健全农户“三权”市场化退出机制和配套政策。\n培育城市群和都市圈。推进成渝地区双城经济圈等城市群建设，完善城市群一体化发展体制机制，统筹推进基础设施协调布局、产业分工协作、公共服务共享、生态共建环境共治。依托辐射带动能力较强的中心城市，提高通勤圈协同发展水平，培育发展同城化程度高的现代化都市圈。推进超大特大城市瘦身健体，严控中心城市规模无序扩张。完善大中城市宜居宜业功能，支持培育新生中小城市。健全城镇体系，依法依规加强城市生态修复和功能完善，合理确定城市规模、人口密度、空间结构。\n推进以县城为重要载体的城镇化建设。推进县城公共服务、环境卫生、市政公用、产业配套等设施提级扩能，增强综合承载能力和治理能力。鼓励东部城镇化地区县城加快发展，支持中西部和东北城镇化地区县城建设，合理引导农产品主产区和重点生态功能区县城建设。按照区位条件、资源禀赋、发展基础，分类引导小城镇发展。促进特色小镇规范健康发展。\n推进城市设施规划建设和城市更新。加强市政水、电、气、路、热、信等体系化建设，推进地下综合管廊等设施和海绵城市建设，加强城市内涝治理，加强城镇污水和垃圾收集处理体系建设，建设宜居、创新、智慧、绿色、人文、韧性城市。加强城镇老旧小区改造和社区建设，补齐居住社区设施短板，完善社区人居环境。加快地震易发区房屋设施抗震加固改造，加强城市安全监测。强化历史文化保护，塑造城市风貌，延续城市历史文脉。\n（十六）积极推动农村现代化\n实施乡村建设行动。综合考虑村庄演变规律、集聚特点、现状分布，结合农民生产生活半径，合理确定村庄布局和规模。完善乡村基础设施和综合服务设施，提升农房品质，严格建房安全标准。加强农村生态文明建设和农村人居环境整治。推进农村移风易俗。加大农村地区文化遗产保护力度，保护传统村落、民族村寨和乡村风貌，让居民望得见山、看得见水、记得住乡愁。\n完善乡村市场体系。健全农产品流通网络，加强农村商贸体系建设，畅通工业品下乡、农产品进城双向流通渠道。完善以县级物流节点为核心、乡镇服务站点为骨架、村级末端网点为延伸的县乡村三级物流节点设施体系，完善农村电商配套服务。培育农产品网络品牌。推动农村居民汽车、家电、家具、家装消费升级。引导县域引入城市消费新业态新模式，充分满足县乡居民个性化、多元化、中高端消费需求。持续依法打击假冒伪劣产品，规范农村市场秩序。\n丰富乡村经济形态。深入实施质量兴农战略，推动农村一二三产业融合发展，高质量发展现代农产品加工业，延长农业产业链条。发展各具特色的现代乡村富民产业，壮大休闲农业、乡村旅游、民宿经济、乡村文化等特色产业。完善利益联结机制，让农民更多分享产业增值收益。发展新型农村集体经济，扶持各类新型农业经营主体，提高农业经营效益和农民职业吸引力。推动乡村人才振兴，优化农村创新创业环境，激发农村创新创业活力。\n健全城乡融合发展体制机制。强化以工补农、以城带乡，推动形成工农互促、城乡互补、协调发展、共同繁荣的新型工农城乡关系。统筹推进城乡规划布局和建设管理，让城乡之间各美其美、美美与共。推动城乡在要素配置、产业发展、安全标准、公共服务、生态保护等方面相互融合和协同发展，促进城乡生产要素平等交换、双向自由流动和公共资源合理配置，逐步缩小城乡发展差距和居民生活水平差距。\n（十七）优化区域经济布局\n依托区域重大战略打造内需新增长极。以疏解北京非首都功能为“牛鼻子”，持续推动京津冀协同发展。坚持生态优先、绿色发展和共抓大保护、不搞大开发，全面推动长江经济带高质量发展。支持香港、澳门更好融入国家发展大局，积极稳妥推进粤港澳大湾区建设。紧扣“一体化”和“高质量”，提升长三角一体化发展水平。协调上中下游共抓大保护，扎实推进黄河流域生态保护和高质量发展。支持经济发展优势区域增强经济和人口承载能力，提升创新策源能力和全球资源配置能力，促进区域间融合互动、融通补充，培育新增长极，带动全国经济效率整体提升。\n推动区域协调发展完善内需增长空间格局。在全国统一大市场框架下充分发挥各地区比较优势，努力实现差异竞争、错位发展，释放区域协调发展的巨大内需潜力。深入推进西部大开发、东北全面振兴、中部地区崛起、东部率先发展，支持欠发达地区、革命老区等特殊类型地区加快发展，加大对民族地区发展支持力度。推动巩固拓展脱贫攻坚成果同乡村振兴有效衔接，完善农村低收入人口和欠发达地区帮扶机制。健全区际利益补偿等促进区域协调发展机制。积极拓展海洋经济发展空间。","level":1},{"name":"六、提高供给质量，带动需求更好实现","text":"供给侧有效畅通可以打通循环堵点、消除瓶颈制约，满足现有需求并进一步引领创造新需求。要面向需求结构变化和供给革命，顺应新一轮科技革命和产业变革趋势，强化科技自立自强，以创新驱动、高质量供给引领和创造新需求，推动供需在更高水平上实现良性循环。\n（十八）加快发展新产业新产品\n实现科技高水平自立自强。以国家战略性需求为导向优化国家创新体系整体布局，强化以国家实验室为引领的战略科技力量。推进科研院所、高等学校和企业科研力量优化配置、资源共享。健全新型举国体制，确定科技创新方向和重点，改进科研项目组织管理方式。在人工智能、量子信息、脑科学等前沿领域实施一批前瞻性、战略性国家重大科技项目。聚焦核心基础零部件及元器件、关键基础材料、关键基础软件、先进基础工艺和产业技术基础，引导产业链上下游联合攻关。持之以恒加强基础研究，发挥好重要院所、高校的国家队作用，重点布局一批基础学科研究中心。加强科学研究与市场应用的有效衔接，支持产学研协同，促进产业链、创新链、生态链融通发展。强化企业科技创新主体作用。\n壮大战略性新兴产业。深入推进国家战略性新兴产业集群发展，建设国家级战略性新兴产业基地。全面提升信息技术产业核心竞争力，推动人工智能、先进通信、集成电路、新型显示、先进计算等技术创新和应用。加快生物医药、生物农业、生物制造、基因技术应用服务等产业化发展。发展壮大新能源产业。推进前沿新材料研发应用。促进重大装备工程应用和产业化发展，加快大飞机、航空发动机和机载设备等研发，推进卫星及应用基础设施建设。发展数字创意产业。在前沿科技和产业变革领域，组织实施未来产业孵化与加速计划，前瞻谋划未来产业。推动先进制造业集群发展，建设国家新型工业化产业示范基地，培育世界级先进制造业集群。\n加强创新产品应用。依托我国超大规模市场和完备产业体系，创造有利于新技术快速大规模应用和迭代升级的独特优势，加速科技成果向现实生产力转化。完善激励和风险补偿机制，推动首台（套）装备、首批次材料等示范应用。建立重要产品快速审评审批机制。\n加快推动数字产业化和产业数字化。加强数字社会、数字政府建设，发展普惠性“上云用数赋智”，不断提升数字化治理水平。建立完善跨部门跨区域的数据资源流通应用机制，强化数据安全保障能力，优化数据要素流通环境。加快数据资源开发利用及其制度规范建设，打造具有国际竞争力的数字产业集群，加大中小企业特别是制造业中小企业数字化赋能力度。积极参与数字领域国际规则和标准制定。\n激发人才创新活力。遵循人才成长规律和科研活动规律，培养造就更多国际一流的领军人才。加强创新型、应用型、技能型人才培养，壮大高水平工程师和高技能人才队伍。鼓励大型企业与科研院所联合培养科技人才。健全以创新能力、质量、实效、贡献为导向的科技人才评价体系，完善技能人才评价制度。弘扬科学精神和工匠精神，提升全民科学素质。\n（十九）积极促进传统产业改造提升\n大力发展现代农业。持续强化农业基础地位，加快建立现代农业产业体系、生产体系、经营体系，发展农业专业化社会化服务。健全农业支持保护制度，优化农业生产区域布局，加强粮食生产功能区、重要农产品生产保护区、特色农产品优势区建设。优化农业生产结构，扩大紧缺农产品生产。加强高标准农田建设，加强东北黑土地保护和地力恢复，增强粮食综合生产能力。推动畜牧业转型升级，发展标准化规模养殖，强化动物疫病风险防控，推进畜禽养殖废弃物资源化利用。推进水产绿色健康养殖，规范有序发展海洋渔业。强化农业科技和装备支撑，推进农业机械化和农机装备智能化。推动发展智慧农业。\n推进制造业高端化、智能化、绿色化。深入实施工业互联网创新发展战略。促进数据、人才、技术等生产要素在传统产业汇聚，推动企业加快数字化改造。发展智能制造、绿色制造，推动生产方式向柔性、智能、精细化转变。构建多层次资源高效循环利用体系，推进大宗固废综合利用，规范发展再制造产业。\n优化区域产业产能布局。发挥各地区比较优势，优化区域分工协作格局。优化石化化工、钢铁等重要基础性产业规划布局，严格控制建设高耗能、高排放项目。不断完善产业结构调整指导目录、西部地区鼓励类产业目录等，支持引导中西部和东北地区依托资源要素禀赋，在充分考虑资源环境承载能力基础上承接国内产业梯度转移。推进老工业基地制造业竞争优势重构。加强对重大生产力布局的统一规划和宏观指导，防止盲目投资和重复建设。\n持续推动生产性服务业向高端延伸。发展服务型制造，鼓励制造业企业发展生产性服务业，拓展研发设计、供应链协同、系统解决方案、柔性化定制、全生命周期管理等增值服务，促进制造业企业由提供“产品”向提供“产品+服务”转变，提升价值链。推动现代服务业同先进制造业融合发展。积极发展科技服务业。支持智能制造、流程再造等领域新型专业化服务机构发展。发展研发、设计、检测等生产性服务外包，鼓励电子商务等服务业企业向制造环节拓展。引导研发设计企业与制造业企业嵌入式合作。培育专业化、国际化的知识产权服务品牌机构。聚焦提高要素配置效率，推动供应链金融、信息数据、人力资源等服务创新发展。\n（二十）着力加强标准质量品牌建设\n健全产品和服务标准体系。建立健全全国统一的强制性国家标准体系。构建现代农业全产业链标准体系，完善制造业高端化标准体系，动态调整消费品安全标准，健全旅游、养老、商贸流通等服务业标准体系。优化企业标准“领跑者”制度。大力发展先进团体标准。加快构建国家现代先进测量体系。加强检验检测体系建设。\n持续提高产品和服务质量。加强质量安全监管，推进质量分级，稳步提高消费品质量安全水平。健全质量认证体系，完善质量认证采信机制。加快建设覆盖线上线下的重要产品追溯体系，实施优质服务标识管理制度，促进品质消费。\n深入实施商标品牌战略。打造中国品牌，培育和发展中华老字号和特色传统文化品牌。持续办好中国品牌日活动，宣传推介国货精品，增强全社会品牌发展意识，在市场公平竞争、消费者自主选择中培育更多享誉世界的中国品牌。","level":1},{"name":"七、健全现代市场和流通体系，促进产需有机衔接","text":"完善的市场体系可以推动资源配置实现效益最大化和效率最优化，高效的流通体系能够在更大范围更深程度把生产和消费有机联系起来。要推动形成全国统一大市场，加快健全市场体系基础制度，建设现代流通体系，优化生产要素配置，有效提高市场运行和流通效率，促进生产与需求紧密结合。\n（二十一）提升要素市场化配置水平\n推进劳动力要素有序流动。营造公平就业环境，保障城乡劳动者享有平等就业权利。建立协调衔接的劳动力、人才流动政策体系和交流合作机制，健全统一规范的人力资源市场体系，完善全国统一的人力资源社会保障公共服务平台，推动公共资源由主要按城市行政等级配置向主要按实际服务管理人口规模配置转变。\n推动经营性土地要素市场化配置。健全城乡统一的建设用地市场，合理调节土地增值收益。探索建立全国性的建设用地指标和补充耕地指标跨区域交易机制。加快培育发展建设用地二级市场，推进产业用地市场化配置，推动不同产业用地类型合理转换，探索增加混合产业用地供给。完善城乡基准地价、标定地价的制定与发布制度，逐步形成与市场价格挂钩动态调整机制。充分利用市场机制盘活存量土地和低效用地。\n完善知识、技术、数据要素配置机制。深化科技成果使用权、处置权、收益权改革，完善职务科技成果转化激励机制。加大科研单位改革力度，支持科研事业单位试行更灵活的岗位、薪酬等管理制度。建立健全高等学校、科研机构、企业间创新资源自由有序流动机制。建设国家知识产权和科技成果产权交易机构。完善数据要素市场化配置机制，建立数据资源产权、交易流通、跨境传输、安全保护等基础制度和标准规范。\n（二十二）加快建立公平统一市场\n完善公平竞争的市场秩序。在要素获取、准入许可、经营运行、标准制定、招投标、政府采购等方面，对各类所有制企业平等对待。建立公平开放透明的竞争规则，构建覆盖事前事中事后全环节的竞争政策实施机制，健全公平竞争审查机制，强化公平竞争审查刚性约束。加强和改进反垄断和反不正当竞争执法，完善法律法规。完善市场竞争状况评估制度。\n加快构建全国统一大市场。破除地方保护和市场分割，建设高效规范、公平竞争的国内统一市场，破除妨碍生产要素市场化配置和商品服务流通的体制机制障碍，降低全社会交易成本。健全市场准入负面清单制度，全面提升市场准入效能。推进能源、铁路、电信、公用事业等行业竞争性环节市场化改革。深化公共资源交易平台整合共享。合理划分不同层级政府市场监管事权，构建跨区域市场监管机制，有效防止滥用行政权力限制竞争。\n（二十三）建设现代流通体系\n优化现代商贸体系。提升城市商业水平，发展智慧商圈，构建分层分类的城市商业格局，打造“一刻钟”便民生活圈。加强县域商业建设，建立完善农村商业体系。加快物联网、人工智能等技术与商贸流通业态融合创新，同时注意防范垄断和安全风险。\n发展现代物流体系。围绕做优服务链条、做强服务功能、做好供应链协同，完善集约高效的现代物流服务体系。促进现代物流业与农业、制造、商贸等融合发展。积极发展公铁水联运、江海联运和铁路快运。探索建立城市群物流统筹协调机制，培育有机协同的物流集群。优化国际海运航线，强化国际航空货运网络，巩固提升中欧班列等国际铁路运输组织，推动跨境公路运输发展，支持优化海外仓全球布局，加快构建高效畅通的多元化国际物流干线通道，形成内外联通、安全高效的物流网络。","level":1},{"name":"八、深化改革开放，增强内需发展动力","text":"用足用好改革这个关键一招，实行更高水平开放，能够为深挖国内需求潜力、拓展扩大最终需求提供强大动力。要聚焦重点领域重点问题，加强改革开放举措的系统集成、协同高效，完善促进消费、扩大投资的制度安排，为国内市场发展提供源源不断的动力和活力。\n（二十四）完善促进消费的体制机制\n持续释放服务消费潜力。实施宽进严管，对可以依靠市场充分竞争提升供给质量的服务消费领域取消准入限制。对于电力、油气等行业中具有自然垄断属性的服务领域，根据不同行业特点实行网运分开，放宽上下游竞争相对充分服务业准入门槛。按照政事分开、事企分开、管办分离的要求，持续推进教育、科技、文化、卫生、体育等领域事业单位改革。\n加强消费者权益保护。建立健全适应消费新业态新模式发展特点的新型监管机制。建立假冒伪劣产品惩罚性巨额赔偿制度。健全缺陷产品召回、产品伤害监测、产品质量担保等制度，完善多元化消费维权机制和纠纷解决机制。严格食品药品监管，确保安全。强化重点商品和服务领域价格监管，维护市场价格秩序。\n（二十五）推进投融资体制改革\n加大对民间投资支持和引导力度。坚持毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展，促进公有制经济和非公有制经济优势互补、共同发展。完善支持政策，发挥政府资金引导带动作用，引导民间资本参与新型基础设施、新型城镇化、交通水利等重大工程和补短板领域建设。鼓励民营企业增加研发投入，推动设备更新和技术改造，扩大战略性新兴产业投资，提高自主创新能力，掌握拥有自主知识产权的核心技术。鼓励和引导非国有资本投资主体通过参股控股、资产收购等多种形式，参与国有企业改制重组。切实保护民营企业的合法权益，培育和维护公平竞争的投资环境。加强对民营企业的服务、指导和规范管理。\n持续完善投资管理模式。协同推进投资审批制度改革，规范有序推广企业投资项目承诺制、区域评估、标准地改革等投资审批创新经验，加强投资决策与规划和用地、环评的制度衔接。完善投资法规制度和执法机制，健全地方配套制度体系。加强投资项目特别是备案类项目的事中事后监管。建立健全投资审批数据部门间共享机制，推动投资审批权责“一张清单”、审批数据“一体共享”、审批事项“一网通办”。\n健全投资项目融资机制。持续优化政府投资结构，加大对补短板领域支持力度。有序推动基础设施领域不动产投资信托基金健康发展。通过多种方式盘活存量资产，形成存量资产和新增投资的良性循环。规范有序推进政府和社会资本合作。鼓励金融机构依法合规提供更多直达实体经济的金融产品和服务。健全政府性融资担保体系。增强资本市场对实体经济的融资功能，提高直接融资特别是股权融资比重。扩大债券融资规模，推进债券市场互联互通。\n（二十六）优化营商环境激发市场活力\n深化“放管服”改革。持续深化行政审批制度改革和商事制度改革，减少和优化涉企经营许可事项，改革完善生产许可制度，简化工业产品生产许可证审批程序。加快建立全方位、多层次、立体化监管体系，实现事前事中事后全链条全领域监管。提升企业开办标准化、规范化、便利化水平，简化普通注销程序，建立健全企业破产和自然人破产制度。加快推动市场数据跨部门共享，规范商业机构数据公开使用与发布。完善营商环境评价体系。\n健全现代产权制度。加强产权保护和激励，完善以公平为原则的产权保护制度，完善产权执法司法保护制度，全面依法平等保护各类产权。强化知识产权全链条保护，提升知识产权审查能力，建立健全知识产权侵权快速反应、惩罚性赔偿等机制。加强数据、知识、环境等领域产权制度建设，完善自然资源资产产权制度和法律法规。完善国有产权交易制度，完善农村集体产权确权和保护制度。\n完善社会信用体系。推进信用法治建设，健全社会信用法律法规和政策体系。依法依规加强信用信息归集、共享、公开、应用，建立公共信用信息同金融信息共享整合机制。建立健全以信用为基础的新型监管机制，加强企业信用状况综合评价，推广信用承诺和告知承诺制，依法依规健全守信激励和失信惩戒机制。强化消费信用体系建设。加强诚信文化建设和宣传教育，营造公平诚信的市场环境和社会环境。\n（二十七）发挥对外开放对内需的促进作用\n高质量共建“一带一路”。推进基础设施互联互通，拓展第三方市场合作。构筑互利共赢的产业链供应链合作体系，深化国际产能合作，扩大双向贸易和投资，健全多元化投融资体系。加快推进西部陆海新通道高质量发展，提高中欧班列开行质量，推动国际陆运贸易规则制定。支持各地深化与共建“一带一路”国家交流合作。\n持续提升利用外资水平。推进投资便利化，稳步推动规则、规制、管理、标准等制度型开放，健全外商投资准入前国民待遇加负面清单管理制度，全面深入落实准入后国民待遇，促进内外资企业公平竞争。鼓励外商投资中高端制造、高新技术和现代服务产业。加强外商投资合法权益保护。促进引资与引智更好结合，鼓励外资企业进一步融入我国创新体系。\n打造高水平、宽尺度、深层次的开放高地。坚持推动更高水平开放与区域协调发展相结合，协同推动扩大内陆开放、加快沿边开放、提升沿海开放层次。建设好各类开发开放平台和载体，加快培育更多内陆开放高地。发挥京津冀、长三角、粤港澳大湾区等地区先导示范效应，打造面向东北亚、中亚、南亚、东南亚的沿边开放合作门户。赋予自由贸易试验区更大改革自主权。稳步推进海南自由贸易港建设，建立中国特色自由贸易港政策和制度体系。\n稳步推进多双边贸易合作。实施自由贸易区提升战略，做好区域全面经济伙伴关系协定生效后实施工作，推动商签更多高标准自由贸易协定和区域贸易协定。促进我与周边国家地区农业、能源、服务贸易、高新技术等领域合作不断深化。推进国际陆海贸易新通道建设。优化促进外贸发展的财税政策，不断完善与我国经济发展水平相适应的关税制度。\n扩大重要商品和服务进口。拓宽优质消费品、先进技术、重要设备、关键零部件和重要能源资源进口渠道。支持国内产业转型升级需要的技术、设备及零部件进口，鼓励研发设计、节能环保、环境服务等生产性服务进口。扩大与人民生活密切相关的优质商品、医药产品和康复服务等进口。支持边境贸易创新发展。持续办好中国国际进口博览会、中国进出口商品交易会、中国国际服务贸易交易会、中国国际消费品博览会等，推动进口规模扩大、结构优化、来源多元化。","level":1},{"name":"九、扎实推动共同富裕，厚植内需发展潜力","text":"共同富裕是社会主义的本质要求，是中国式现代化的重要特征。坚持以人民为中心的发展思想，在高质量发展中促进共同富裕，正确处理效率和公平的关系，完善收入分配格局，构建初次分配、再分配、三次分配协调配套的基础性制度安排，加大税收、社保、转移支付等调节力度并提高精准性，扩大中等收入群体比重，增加低收入群体收入，合理调节高收入，取缔非法收入，促进社会公平正义，促进人的全面发展，增强内需发展后劲。\n（二十八）持续优化初次分配格局\n提升就业质量增加劳动者劳动收入。持续实施就业优先战略，坚持经济发展就业导向，扩大就业容量，提升就业质量，促进充分就业。注重缓解结构性就业矛盾，加快提升劳动者技能素质，发展现代职业教育，健全终身职业技能培训制度。加快新一代信息技术与制造业深度融合，挖掘新产业新业态新模式带动就业潜力，创造更多更高质量更高收入的就业岗位。健全就业公共服务体系、劳动关系协调机制，完善重点群体就业支持体系。加快乡村产业振兴，积极促进农民工就业，增加农村居民工资性收入。\n提高劳动报酬在初次分配中的比重。坚持居民收入增长和经济增长基本同步、劳动报酬提高和劳动生产率提高基本同步，增加劳动者特别是一线劳动者劳动报酬。完善企业薪酬调查和信息发布制度，健全劳动者工资决定、合理增长和支付保障机制，健全最低工资标准调整机制。改革完善事业单位工资、国有企业工资分配等制度。积极推行工资集体协商制度。实施渐进式延迟法定退休年龄。\n健全各类生产要素参与分配机制。构建知识、技术、数据等创新要素参与收益分配机制，强化以增加知识价值为导向的分配政策，发挥工资激励保障作用。完善国有企业科技人才薪酬激励政策。完善股份制企业特别是上市公司分红制度。完善股票发行、信息披露等制度，推动资本市场规范健康发展。创新更多适应家庭财富管理需求的金融产品，增加居民投资收益。探索通过土地、资本等要素使用权、收益权增加中低收入群体要素收入。\n扩大中等收入群体规模。通过开展示范区建设等，探索扎实推动共同富裕的有效路径。推进高等学校和职业院校毕业生、技能型劳动者、农民工等群体稳定增收，培育高素质农民，完善小微创业者扶持政策，支持个体工商户、灵活就业人员等群体勤劳致富，使更多普通劳动者通过自身努力进入中等收入群体。健全公共服务体系，合理减轻中等收入群体负担。\n（二十九）逐步健全再分配机制\n加大财税制度对收入分配的调节力度。健全直接税体系，完善综合与分类相结合的个人所得税制度，加强对高收入者的税收调节和监管。完善中央与地方财政事权和支出责任划分，推动教育、养老、医疗、住房保障等基本公共服务均等化。完善转移支付制度，重点加大对发展水平相对落后地区的转移支付力度。有序增加社会民生领域资金投入，优化教育支出结构。\n健全社会保障制度。推进基本养老保险由制度全覆盖到法定人群全覆盖，完善灵活就业人员参加职工社会保险制度。发展企业年金、职业年金，规范发展第三支柱养老保险。完善基本医疗保险制度，健全重特大疾病医疗保险和救助制度，支持商业健康保险发展。实现企业职工基本养老保险全国统筹，推动基本医疗保险、失业保险省级统筹，巩固完善工伤保险省级统筹。健全社会保障待遇调整机制。完善社会救助制度兜底功能。完善帮扶残疾人、孤儿等社会福利制度。健全退役军人工作体系和保障制度。\n（三十）重视发挥第三次分配作用\n发展慈善事业。建立健全慈善事业发展体制机制，规范培育发展慈善组织。完善慈善褒奖制度，引导支持有意愿有能力的企业和社会群体积极参与公益慈善事业。\n健全志愿服务体系。发展社会工作服务机构和志愿服务组织，壮大志愿者队伍，搭建更多志愿服务平台，全面提升志愿服务水平。广泛开展志愿服务关爱行动。探索建立文明实践积分银行，将志愿服务活动、践行文明行为等纳入积分管理，促进形成志愿服务良好社会氛围。","level":1},{"name":"十、提升安全保障能力，夯实内需发展基础","text":"把安全发展贯穿扩大内需工作各领域和全过程，着力提升粮食、能源和战略性矿产资源等领域供应保障能力，有效维护产业链供应链稳定，不断提高应对突发应急事件能力，为国内市场平稳发展提供坚强安全保障。\n（三十一）保障粮食安全\n推进粮食稳产增产。深入实施藏粮于地、藏粮于技战略，坚持最严格的耕地保护制度，严守18亿亩耕地红线，坚决遏制耕地“非农化”、严格管控“非粮化”。推进合理布局，主产区、主销区、产销平衡区都要保面积、保产量，加大粮食生产政策支持力度，确保口粮绝对安全、谷物基本自给。实施重要农产品保障战略，实现生猪基本自给、其他重要农副产品供应充足。\n健全粮食产购储加销体系。落实粮食安全党政同责要求。深化粮食等重要农产品收储制度改革，加快培育多元市场购销主体，科学确定粮食储备规模、结构、布局，完善粮食储备管理体制和运行机制。加强粮食、棉、糖等重要农产品仓储物流设施建设。强化地方储备体系建设，健全层级分明、运作高效的农产品储备体系。深入推进优质粮食工程，加快构建现代化粮食产业体系。持续倡导节粮减损。\n加强种子安全保障。建立健全现代种业体系，加强种质资源保护利用和种子库建设，提高资源保护、育种创新、品种测试、良种繁育能力，实施农业生物育种重大科技项目。在尊重科学、严格监管的前提下，有序推进生物育种产业化应用。\n（三十二）强化能源资源安全保障\n增强国内生产供应能力。推动国内油气增储上产，加强陆海油气开发。推动页岩气稳产增产，提升页岩油开发规模。引导和鼓励社会资本进入油气勘探开采领域。稳妥推进煤制油气，规划建设煤制油气战略基地。深入实施找矿突破战略行动，开展战略性矿产资源现状调查和潜力评价，积极开展现有矿山深部及外围找矿，延长矿山服务年限。持续推进矿山智能化、绿色化建设。\n（三十三）增强产业链供应链安全保障能力\n推进制造业补链强链。实施产业基础再造工程，健全产业基础支撑体系，加强产业技术标准体系建设。巩固拓展与周边国家产业链供应链合作，共同维护国际产业链供应链稳定运行。实施制造业供应链提升工程，构建制造业供应链生态体系。围绕重点行业产业链供应链关键原材料、技术、产品，增强供应链灵活性可靠性。\n保障事关国计民生的基础产业安全稳定运行。聚焦保障煤电油气运安全稳定运行，强化关键仪器设备、关键基础软件、大型工业软件、行业应用软件和工业控制系统、重要零部件的稳定供应，保证核心系统运行安全。保障居民基本生活必需品产业链安全，实现极端情况下群众基本生活不受大的影响。\n（三十四）推动应急管理能力建设\n增强重特大突发事件应急能力。加强应急物资装备保障体系建设，强化公共卫生、灾害事故等领域应急物资保障，完善中央、省、市、县、乡五级应急物资储备网络。建设国家级应急物资储备库，升级地方应急物资储备库和救援装备库，中央应急物资储备向中西部地区和灾害多发易发地区倾斜。优化重要应急物资产能区域布局，实施应急产品生产能力储备工程，引导企业积极履行社会责任建立必要的产能储备，建设区域性应急物资生产保障基地，完善国家应急资源管理平台。健全应急决策支撑体系，建设应急技术装备研发实验室。加快提升应急物流投送与快速反应能力，完善应急广播体系。\n加强应急救援力量建设。完善航空应急救援体系，推进新型智能装备、航空消防大飞机、特种救援装备、特殊工程机械设备研发配备。加大综合性消防救援队伍和专业救援队伍、社会救援队伍建设力度，推动救援队伍能力现代化。推进城乡公共消防设施建设，推进重点场所消防系统改造。强化危险化学品、矿山、道路交通等重点领域生命防护，提高安全生产重大风险防控能力。\n推进灾害事故防控能力建设。支持城乡防灾基础设施建设，完善防汛抗旱、防震减灾、防风抗潮、森林草原防灭火、地震地质灾害防治等骨干设施。提升城市防洪排涝能力，逐步建立完善防洪排涝体系。优化国土空间防灾减灾救灾设施布局，推进公共基础设施安全加固，加快构建城乡应急避难场所体系。加强防灾减灾救灾和安全生产科技信息化支撑能力，加快构建天空地一体化灾害事故监测预警体系和应急通信体系。发展巨灾保险。","level":1},{"name":"十一、实施保障","text":"（三十五）加强党的全面领导\n各地区各部门要深入学习贯彻习近平新时代中国特色社会主义思想，增强“四个意识”、坚定“四个自信”、做到“两个维护”，不断提高政治判断力、政治领悟力、政治执行力，不断提高把握新发展阶段、贯彻新发展理念、构建新发展格局的政治能力、战略眼光、专业水平，抓好重大任务和政策落实。充分调动各有关方面实施扩大内需战略的积极性、主动性、创造性，为实现规划纲要确定的主要目标提供坚强组织保障。\n（三十六）完善组织协调机制\n各有关部门要加强实施扩大内需战略部际协调，发挥统筹协调作用，推动落实扩大内需各项工作；定期编制扩大内需战略实施方案，进一步细化实化规划纲要明确的重大任务和重大政策。地方各级政府要因地制宜积极作为，把实施扩大内需战略纳入经济社会发展规划，结合实际制定本地区扩大内需战略政策措施，压实地方落实扩大内需战略责任，创新规划纲要组织实施方式，发挥各方面作用，坚决杜绝形式主义、官僚主义。\n（三十七）强化政策协同配合\n完善宏观经济治理，不断创新和完善宏观调控，强化宏观政策对实施扩大内需战略的统筹支持。着力发挥规划纲要导向作用，加强财政、货币、就业、产业、投资、消费、环保、区域等政策的协同配合，推动形成扩大内需的政策合力。密切跟踪分析政策落实情况及内需形势变化，加强扩大内需政策研究储备，完善政策制定和执行机制，强化政策成效评估，保障战略目标顺利实现。\n（三十八）加大宣传引导力度\n各地区各有关部门要加强扩大内需战略的宣传和引导，综合运用各种媒体，通过大众喜闻乐见的形式深入解读扩大内需战略的新举措新要求，进一步营造浓厚社会氛围。及时总结规划纲要实施成效，充分挖掘各地区和不同行业、企业在扩大内需方面的成功案例，通过多种形式及时总结推广好经验好做法。","level":1}]},{"id":"r0626","sections":[{"name":"中共中央办公厅 国务院办公厅关于进一步加强矿山安全生产工作的意见","text":"矿山安全生产事关人民群众生命财产安全，事关经济发展和社会稳定大局，是安全生产的重中之重。为深入贯彻党的二十大精神，进一步加强矿山安全生产工作，经党中央、国务院同意，现提出如下意见。","level":1},{"name":"一、严格矿山安全生产准入","text":"（一）严格灾害严重煤矿安全准入。停止新建产能低于90万吨/年的煤与瓦斯突出、冲击地压、水文地质类型极复杂的煤矿。新建煤与瓦斯突出、冲击地压、水文地质类型极复杂的煤矿原则上应按采煤、掘进智能化设计。\n（二）严格非煤矿山源头管控。严格按照矿产资源规划、国土空间规划和用途管制要求，科学合理设置矿山。矿产资源勘查应达到规定程度，相邻矿山生产建设作业范围最小距离应满足相关安全规定，普通建筑用砂石露天矿山不得以山脊划界。除符合规定的情形外，新设采矿权范围不得与已设采矿权垂直投影范围重叠，可集中开发的同一矿体不得设立2个以上采矿权。采矿许可证证载规模是拟建设规模，矿山设计单位可在项目可行性研究基础上，充分考虑资源高效利用、安全生产、生态环境保护等因素，在矿山初步设计和安全设施设计中科学论证并确定实际生产建设规模，矿山企业应当严格按照经审查批准的安全设施设计建设、生产。\n（三）规范安全生产行政许可。煤矿、金属非金属地下矿山、尾矿库等矿山的安全设施设计审查和安全生产许可证审批由省级以上矿山安全监管部门负责，不得下放或者委托。矿山安全监管部门应当制定矿山建设项目安全设施设计审查规范，严格实质内容审查，不得仅对程序和形式进行审查。矿山开发没有进行一次性总体设计的，原则上不得审批安全设施设计。1个采矿权范围内原则上只能设置1个生产系统。审批首次申请安全生产许可证的，应进行现场核查。","level":1},{"name":"二、推进矿山转型升级","text":"（四）分类处置不具备安全生产条件的矿山。对未依法取得采矿许可证、安全生产许可证擅自从事矿产资源开采的，越界开采、以采代建、持勘查许可证采矿且拒不整改的，与煤共（伴）生金属非金属矿山经停产整顿仍达不到煤矿安全生产条件的，使用应当淘汰的危及生产安全的工艺、设备且拒不整改仍然生产建设的，或者经停产整顿仍不具备安全生产条件的矿山，依法予以关闭取缔。对长期停工停产、资源枯竭的矿山，灾害严重且难以有效防治的煤矿，积极引导退出。\n（五）推进尾矿库闭库销号。对运行到设计最终标高、不再排尾作业、停用超过3年或者没有生产经营主体的尾矿库，应当及时闭库治理并销号。完成闭库治理的尾矿库，应由县级以上地方政府公告销号，不再作为尾矿库进行使用，不得重新用于排放尾矿。\n（六）实施非煤矿山整合重组。鼓励大型矿山企业兼并重组和整合技改中小型非煤矿山企业。推动同一个矿体分属2个以上不同开采主体的非煤矿山，生产建设作业范围最小距离不满足相关安全规定的非煤矿山，以山脊划界的普通建筑用砂石露天矿山等企业整合重组，统一开采规划、生产系统和安全管理。\n（七）加快矿山升级改造。推动中小型矿山机械化升级改造和大型矿山自动化、智能化升级改造，加快灾害严重、高海拔等矿山智能化建设，打造一批自动化、智能化标杆矿山。地下矿山应当建立人员定位、安全监测监控、通信联络、压风自救和供水施救等系统。新建、改扩建金属非金属地下矿山原则上采用充填采矿法，不能采用的应严格论证。中小型金属非金属地下矿山不得有4个以上生产水平同时采矿。尾矿库应当建立在线安全监测系统，新建四等、五等小型尾矿库应当采用一次性建坝。\n（八）提高科技创新支撑能力。强化矿山安全科技支撑体系建设。加强矿山重大灾害预防与治理研究，组织重大关键技术攻关。推进矿山信息化、智能化装备和机器人研发及应用。实施一批矿山安全类重大科技项目。研究推进建设矿山安全领域全国重点实验室。","level":1},{"name":"三、防范化解重大安全风险","text":"（九）健全矿山安全管理体系。矿山企业应当健全以安全风险分级管控和隐患排查治理双重预防机制为核心的安全生产标准化管理体系。严格开展风险辨识评估并实施分级管控，定期开展全员全覆盖隐患排查治理，建立风险隐患台账清单，实行闭环管理。各级矿山安全监管监察部门应当推动企业切实提高风险隐患排查和整改质量，建立重大隐患治理督办制度，在重大隐患消除前跟踪监管，并监督整改销号。对排查整改不到位导致重大隐患依然存在或发生事故的，依法追究企业及相关责任人责任。\n（十）强化重大灾害治理。矿山企业应当查明隐蔽致灾因素，实施煤与瓦斯突出、冲击地压、水害等重大灾害分区管理、超前治理。将煤矿灾害等级鉴定纳入安全检测检验范围，及时公示鉴定结果。规范煤矿生产能力管理和核定工作。金属非金属露天矿山采场及排土场边坡高度大于100米的，应当逐年进行边坡稳定性分析。金属非金属地下矿山采空区体积超过规定的，应当及时进行稳定性专项评估。尾矿库排洪构筑物每3年应进行一次质量检测。\n（十一）严格设备设施安全管理。完善矿山井下特种设备安全标志审核发放和监督机制。定期对取得矿山井下特种设备安全标志的在用设备设施开展安全可靠性检验。建立矿用安全设备全生命周期智慧监管平台，实行矿用设备安全责任追究制度。\n（十二）规范非煤矿山外包工程管理。非煤矿山企业统一负责外包工程施工单位的安全管理。金属非金属地下矿山严禁将爆破作业专项外包。金属非金属地下基建矿山掘进工程承包单位数量不得超过3家。大中型金属非金属地下生产矿山采掘工程承包单位数量不得超过2家，小型金属非金属地下生产矿山采掘工程承包单位数量不得超过1家，承包单位严禁转包和分包采掘工程及爆破作业项目。承包单位应当向项目部派出项目负责人、技术人员和特种作业人员；项目负责人、技术人员应当具有矿山相关专业中专以上学历或者中级以上专业技术职称，且不得在其他矿山兼职。力争到2025年年底，生产矿山建立本单位采掘（剥）施工队伍或者委托具备相应条件的企业整体管理。\n（十三）加强停工停产矿山安全管控。停工停产整改的矿山应当制定整改方案，限定单班下井人数，同一作业地点控制在10人以内，并向矿山安全监管监察部门报告后方可进行整改作业。地方政府及有关部门应当对停工停产整改煤矿实施驻矿盯守，对其他停工停产矿山落实驻矿盯守或者巡查责任，并按规定进行复工复产验收，因监督检查不力，停工停产期间继续组织建设生产的，依法严肃追究企业及相关责任人责任。\n（十四）提升风险监测预警处置能力。加强矿山多灾种和灾害链综合监测、风险早期识别和预警预报能力建设。矿山集中地区应当建立区域性矿山救援队伍。地下矿山、尾矿库“头顶库”应当建立应急广播等通信系统，确保应急指令能第一时间传达至影响范围内所有人员。加强应急预案演练、评估和修订。每年汛期前地方政府应当组织尾矿库“头顶库”企业与下游居民开展联合演练。强化灾害性天气预警预报，遇极端天气严禁人员入井。","level":1},{"name":"四、强化企业主体责任","text":"（十五）落实主要负责人责任。矿山及其上级企业主要负责人（含法定代表人、实际控制人、实际负责人）依法履行安全生产第一责任人责任，加大安全投入和安全培训力度，及时研究解决矿山安全生产重大问题。矿山企业总部应当加强下属企业监督检查，主要负责人应当定期到生产现场督促检查安全生产工作，严禁下达超能力生产计划或者经营指标。推广矿长安全生产考核记分制度。\n（十六）健全安全管理机构。涉矿中央企业总部和涉矿大中型企业应当配备安全总监。地下矿山应当配备矿长、总工程师和分管安全、生产、机电等工作的副矿长，所配备人员应当具有矿山相关专业大专以上学历或者中级以上专业技术职称，且不得在其他矿山兼职。煤矿、金属非金属矿山、尾矿库应当配备相关专业中专以上学历或者中级以上专业技术职称的专职技术人员。灾害严重矿山应当按要求配备灾害治理专职领导人员、专门机构、专业人员。\n（十七）强化安全基础管理。矿山企业应当建立健全并落实全员安全生产岗位责任制和安全生产管理制度。按照要求绘制、更新相关图纸，并报送矿山安全监管监察部门。未经安全培训合格的从业人员不得上岗作业，矿长、总工程师和分管安全、生产、机电等工作的副矿长每年应当接受专门的安全教育培训。首次取证的地下矿山特种作业人员应当具有高中以上文化程度。严格井下劳动定员管理，不得超定员安排人员下井作业，提高井下艰苦岗位津贴。取消井下劳务派遣用工，矿山企业或承包单位对欠薪应依法承担清偿责任。","level":1},{"name":"五、落实地方党政领导责任和部门监管监察责任","text":"（十八）落实地方党政领导责任。坚持党政同责、一岗双责、齐抓共管、失职追责，严格落实矿山安全领导责任，组织开展区域性矿山隐蔽致灾因素普查治理，严厉打击非法盗采矿产资源行为。加强矿山安全监管机构和队伍建设，专业监管人员配备比例不低于在职人员的75%。矿山安全重点市、县党政主要领导要定期研究矿山安全生产工作，深入矿山井下督促检查。实行市级、县级地方政府领导包保煤矿、金属非金属地下矿山和尾矿库安全生产责任制。\n（十九）落实矿山安全监管责任。各地区应当坚持明责知责、履责尽责，按照分级分类原则，明确省市县三级矿山安全监管执法管辖权限，明确矿山和尾矿库日常安全监管主体，建立部门联合执法和问题线索移交机制，大力提高执法专业素养，切实提升发现问题和解决问题的强烈意愿和能力水平。中央企业所属矿山安全监管应由市地级以上部门负责。尾矿库“头顶库”、采深超800米或者单班下井人数超30人的金属非金属地下矿山、边坡高度超200米的金属非金属露天矿山等高风险矿山安全监管，原则上不得下放至县级部门。按照“谁主管、谁负责”原则，矿山安全监管监察部门负责矿山安全监察和矿山安全生产监督管理工作。按照“管行业必须管安全、管业务必须管安全、管生产经营必须管安全”要求，其他各有关部门要在行业管理、业务管理、生产经营管理中一体推进落实矿山安全生产各项要求。各级安全生产委员会办公室要加强对矿山安全生产工作的协调指导。\n（二十）强化矿山安全国家监察。健全国家矿山安全监察体制，国家矿山安全监察部门负责监督检查地方矿山安全监管工作，向地方政府提出改善和加强矿山安全监管工作的意见和建议。统筹矿山安全监管监察执法保障体系建设，推动落实监管监察能力建设规划，完善技术支撑体系，健全国家矿山安全智能化监管监察系统。","level":1},{"name":"六、推进矿山安全依法治理","text":"（二十一）加强执法保障建设。推动修订矿山安全法，制定煤矿安全生产条例，加强矿山安全标准化建设工作。完善矿山安全监管监察专业人才培养机制，提高待遇保障。加强在线监控联网和矿山安全综合信息化平台建设，强化执法装备保障。\n（二十二）强化安全监督检查。矿山行业管理和安全监管监察部门应严格检查执法，严禁以罚代管、罚而不管。推动建立健全矿山安全生产案件移送、行政执法和刑事司法衔接机制，发现涉嫌犯罪的按规定及时移交司法机关。加强矿山领域安全评价、设计、检测、检验、认证、咨询、培训、监理等第三方服务机构监督管理。建立矿山安全评价检测检验报告公开制度。建立健全重大违法违规信息公示制度、联合惩戒制度和举报奖励制度。建立责任倒查机制，严格执行“谁检查、谁签名、谁负责”，对发现重大隐患不处理处罚或跟踪整改不到位的，依法严肃追责问责。\n（二十三）严格事故调查处理。对较大涉险事故、瞒报谎报重大及以下矿山生产安全事故，视情况提级调查。接到瞒报谎报事故举报，属地县级以上地方政府应当组织核查。发生较大以上死亡事故的矿山，应当停产整顿，经验收符合安全生产条件后方可恢复生产。","level":1},{"name":"七、强化组织实施","text":"（二十四）健全保障措施。各地区各有关部门要加强组织领导，明确任务分工，细化工作措施，研究配套政策。要统筹资金渠道，加强矿山淘汰退出、尾矿库治理、信息化系统、智能化矿山建设和安全监督检查等经费保障。应急管理部牵头建立矿山安全协调推进机制，将本意见落实情况纳入省级政府安全生产和消防工作考核巡查内容。纪检监察机关、组织人事部门和安全生产监管监察部门按照权限和职责，对安全生产责任履行不到位的，要依规依纪依法严肃追责问责，确保矿山安全生产工作各项部署要求落实到位。","level":1}]},{"id":"r0627","sections":[{"name":"国务院关于落实《政府工作报告》","text":"国务院关于落实《政府工作报告》\n重点工作部门分工的意见\n国发〔2020〕6号\n各省、自治区、直辖市人民政府，国务院各部委、各直属机构：\n为全面贯彻党的十九大和十九届二中、三中、四中全会精神，深入落实中央经济工作会议精神和十三届全国人大三次会议通过的《政府工作报告》部署，做好今年政府工作，实现经济社会发展目标任务，现就《政府工作报告》确定的重点工作，提出部门分工意见如下：\n一、落实2020年发展主要目标和下一阶段工作总体部署\n（一）总体要求和主要预期目标。\n1.在以习近平同志为核心的党中央坚强领导下，以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中全会精神，坚决贯彻党的基本理论、基本路线、基本方略，增强“四个意识”、坚定“四个自信”、做到“两个维护”，紧扣全面建成小康社会目标任务，统筹推进疫情防控和经济社会发展工作，在疫情防控常态化前提下，坚持稳中求进工作总基调，坚持新发展理念，坚持以供给侧结构性改革为主线，坚持以改革开放为动力推动高质量发展，坚决打好三大攻坚战，加大“六稳”工作力度，保居民就业、保基本民生、保市场主体、保粮食能源安全、保产业链供应链稳定、保基层运转，坚定实施扩大内需战略，维护经济发展和社会稳定大局，确保完成决战决胜脱贫攻坚目标任务，全面建成小康社会。（国务院各部门分别负责，年内持续推进）\n2.优先稳就业保民生，坚决打赢脱贫攻坚战，努力实现全面建成小康社会目标任务；城镇新增就业900万人以上，城镇调查失业率6%左右，城镇登记失业率5.5%左右；居民消费价格涨幅3.5%左右；进出口促稳提质，国际收支基本平衡；居民收入增长与经济增长基本同步；现行标准下农村贫困人口全部脱贫、贫困县全部摘帽；重大金融风险有效防控；单位国内生产总值能耗和主要污染物排放量继续下降，努力完成“十三五”规划目标任务。（国家发展改革委、财政部、人力资源社会保障部、生态环境部、商务部、人民银行、海关总署、银保监会、证监会、国家外汇局、国务院扶贫办等按职责分工负责，12月底前完成）\n（二）积极的财政政策要更加积极有为。\n3.今年赤字率拟按3.6%以上安排，财政赤字规模比去年增加1万亿元，同时发行1万亿元抗疫特别国债。上述2万亿元全部转给地方，建立特殊转移支付机制，资金直达市县基层、直接惠企利民，主要用于保就业、保基本民生、保市场主体，包括支持减税降费、减租降息、扩大消费和投资等，强化公共财政属性，决不允许截留挪用。要大力优化财政支出结构，基本民生支出只增不减，重点领域支出要切实保障，一般性支出要坚决压减，严禁新建楼堂馆所，严禁铺张浪费。各级政府必须真正过紧日子，中央政府要带头，中央本级支出安排负增长，其中非急需非刚性支出压减50%以上。各类结余、沉淀资金要应收尽收、重新安排。要大力提质增效，各项支出务必精打细算，一定要把每一笔钱都用在刀刃上、紧要处，一定要让市场主体和人民群众有真真切切的感受。（财政部牵头，国家发展改革委、人力资源社会保障部、人民银行、税务总局等按职责分工负责，12月底前完成）\n（三）稳健的货币政策要更加灵活适度。\n4.综合运用降准降息、再贷款等手段，引导广义货币供应量和社会融资规模增速明显高于去年。保持人民币汇率在合理均衡水平上基本稳定。（人民银行、国家外汇局牵头，年内持续推进）创新直达实体经济的货币政策工具，务必推动企业便利获得贷款，推动利率持续下行。（人民银行、银保监会、国家发展改革委、财政部等按职责分工负责，年内持续推进）\n（四）就业优先政策要全面强化。\n5.财政、货币和投资等政策要聚力支持稳就业。努力稳定现有就业，积极增加新的就业，促进失业人员再就业。各地要清理取消对就业的不合理限制，促就业举措要应出尽出，拓岗位办法要能用尽用。（人力资源社会保障部、国家发展改革委、财政部、人民银行等按职责分工负责，年内持续推进）\n（五）继续打好三大攻坚战。\n6.脱贫是全面建成小康社会必须完成的硬任务，要坚持现行脱贫标准，增加扶贫投入，强化扶贫举措落实，确保剩余贫困人口全部脱贫，健全和执行好返贫人口监测帮扶机制，巩固脱贫成果。（国务院扶贫办牵头，年内持续推进）\n7.要打好蓝天、碧水、净土保卫战，实现污染防治攻坚战阶段性目标。（生态环境部牵头，年内持续推进）\n8.加强金融等领域重大风险防控，坚决守住不发生系统性风险底线。（人民银行、银保监会、证监会、国家发展改革委、财政部、国家外汇局等按职责分工负责，年内持续推进）\n二、加大宏观政策实施力度，着力稳企业保就业\n（六）加大减税降费力度。\n9.强化阶段性政策，与制度性安排相结合，放水养鱼，助力市场主体纾困发展。继续执行去年出台的下调增值税税率和企业养老保险费率政策，新增减税降费约5000亿元。前期出台6月前到期的减税降费政策，包括免征中小微企业养老、失业和工伤保险单位缴费，减免小规模纳税人增值税，免征公共交通运输、餐饮住宿、旅游娱乐、文化体育等服务增值税，减免民航发展基金、港口建设费，执行期限全部延长到今年年底。小微企业、个体工商户所得税缴纳一律延缓到明年。预计全年为企业新增减负超过2.5万亿元。要坚决把减税降费政策落到企业，尽力帮助企业特别是中小微企业、个体工商户渡过难关。（财政部、国家发展改革委、工业和信息化部、人力资源社会保障部、住房城乡建设部、交通运输部、商务部、文化和旅游部、税务总局、市场监管总局、国家医保局、中国民航局等按职责分工负责，年内持续推进）\n（七）推动降低企业生产经营成本。\n10.降低工商业电价5%政策延长到今年年底。宽带和专线平均资费降低15%。减免国有房产租金，鼓励各类业主减免或缓收房租，并予政策支持。坚决整治涉企违规收费。（国家发展改革委、工业和信息化部、财政部、住房城乡建设部、国务院国资委、市场监管总局等按职责分工负责，6月底前出台相关政策，年内持续推进）\n（八）强化对稳企业的金融支持。\n11.中小微企业贷款延期还本付息政策再延长至明年3月底，对普惠型小微企业贷款应延尽延，对其他困难企业贷款协商延期。（人民银行、银保监会牵头，6月底前出台相关政策，年内持续推进）完善考核激励机制，鼓励银行敢贷、愿贷、能贷，大幅增加小微企业信用贷、首贷、无还本续贷，利用金融科技和大数据降低服务成本，提高服务精准性。（人民银行、银保监会、国家发展改革委牵头，6月底前出台相关政策，年内持续推进）大幅拓展政府性融资担保覆盖面并明显降低费率。（财政部、银保监会牵头，年内持续推进）大型商业银行普惠型小微企业贷款增速要高于40%。（银保监会、人民银行牵头，12月底前完成）促进涉企信用信息共享。（国家发展改革委、人民银行、市场监管总局等按职责分工负责，年内持续推进）支持企业扩大债券融资。（人民银行、国家发展改革委、证监会等按职责分工负责，8月底前出台相关政策，年内持续推进）加强监管，防止资金“空转”套利，打击恶意逃废债。金融机构与贷款企业共生共荣，鼓励银行合理让利。（国家发展改革委、财政部、人民银行、银保监会、证监会等按职责分工负责，年内持续推进）为保市场主体，一定要让中小微企业贷款可获得性明显提高，一定要让综合融资成本明显下降。（人民银行、银保监会、财政部等按职责分工负责，适时出台相关政策，年内持续推进）\n（九）千方百计稳定和扩大就业。\n12.加强对重点行业、重点群体就业支持。（人力资源社会保障部牵头，年内持续推进）今年高校毕业生达874万人，要促进市场化社会化就业，高校和属地政府都要提供不断线的就业服务，扩大基层服务项目招聘。（人力资源社会保障部、教育部、财政部等按职责分工负责，年内持续推进）做好退役军人安置和就业保障。（退役军人部牵头，年内持续推进）实行农民工在就业地平等享受就业服务政策。（人力资源社会保障部牵头，年内持续推进）帮扶残疾人、零就业家庭等困难群体就业。（人力资源社会保障部、中国残联等按职责分工负责，年内持续推进）今年对低收入人员实行社保费自愿缓缴政策，涉及就业的行政事业性收费全部取消，合理设定流动摊贩经营场所。（人力资源社会保障部、财政部、国家发展改革委、住房城乡建设部、税务总局等按职责分工负责，7月底前出台相关政策）资助以训稳岗拓岗，加强面向市场的技能培训，鼓励以工代训，共建共享生产性实训基地，今明两年职业技能培训3500万人次以上，高职院校扩招200万人，要使更多劳动者长技能、好就业。（人力资源社会保障部、教育部、国家发展改革委、财政部等按职责分工负责，12月底前完成当年任务）\n三、依靠改革激发市场主体活力，增强发展新动能\n（十）深化“放管服”改革。\n13.在常态化疫情防控下，要调整措施、简化手续，促进全面复工复产、复市复业。（国家发展改革委、国务院办公厅牵头，有关部门按职责分工负责，年内持续推进）推动更多服务事项一网通办。（国务院办公厅牵头，有关部门按职责分工负责，年内持续推进）做到企业开办全程网上办理。放宽小微企业、个体工商户登记经营场所限制，便利各类创业者注册经营、及时享受扶持政策。（市场监管总局牵头，12月底前完成）支持大中小企业融通发展。（工业和信息化部牵头，年内持续推进）完善社会信用体系。（国家发展改革委、人民银行牵头，适时出台相关政策，年内持续推进）以公正监管维护公平竞争，持续打造市场化、法治化、国际化营商环境。（国务院办公厅、国家发展改革委、司法部、财政部、住房城乡建设部、市场监管总局等按职责分工负责，年内持续推进）\n（十一）推进要素市场化配置改革。\n14.推动中小银行补充资本和完善治理，更好服务中小微企业。（银保监会、财政部、人民银行、证监会等按职责分工负责，适时出台相关政策，年内持续推进）改革创业板并试点注册制，发展多层次资本市场。（证监会牵头，6月底前出台相关政策，年内落地）强化保险保障功能。（银保监会牵头，年内持续推进）赋予省级政府建设用地更大自主权。（自然资源部牵头，6月底前完成）促进人才流动。（人力资源社会保障部牵头，年内持续推进）培育技术和数据市场，激活各类要素潜能。（国家发展改革委、科技部、工业和信息化部等按职责分工负责，年内持续推进）\n（十二）提升国资国企改革成效。\n15.实施国企改革三年行动。（国务院国资委牵头，10月底前出台相关政策）健全现代企业制度，完善国资监管体制。（国务院国资委、财政部等按职责分工负责，年内持续推进）深化混合所有制改革。（国家发展改革委、国务院国资委牵头，年内持续推进）基本完成剥离办社会职能和解决历史遗留问题。（国务院国资委牵头，12月底前完成）国企要聚焦主责主业，健全市场化经营机制，提高核心竞争力。（国务院国资委牵头，年内持续推进）\n（十三）优化民营经济发展环境。\n16.保障民营企业平等获取生产要素和政策支持，清理废除与企业性质挂钩的不合理规定。构建亲清政商关系，促进非公有制经济健康发展。（国家发展改革委、工业和信息化部、财政部、市场监管总局、全国工商联等按职责分工负责，年内持续推进）限期完成清偿政府机构、国有企业拖欠民营和中小企业款项的任务。（工业和信息化部牵头，有关部门按职责分工负责，逐月调度通报清欠情况）\n（十四）推动制造业升级和新兴产业发展。\n17.支持制造业高质量发展。（工业和信息化部、国家发展改革委等按职责分工负责，年内持续推进）大幅增加制造业中长期贷款。（人民银行、银保监会、国家发展改革委牵头，年内持续推进）发展工业互联网，推进智能制造，培育新兴产业集群。发展研发设计、现代物流、检验检测认证等生产性服务业。电商网购、在线服务等新业态在抗疫中发挥了重要作用，要继续出台支持政策，全面推进“互联网+”，打造数字经济新优势。（国家发展改革委、工业和信息化部、商务部、国家邮政局等按职责分工负责，9月底前出台相关政策，年内持续推进）\n（十五）提高科技创新支撑能力。\n18.稳定支持基础研究和应用基础研究，引导企业增加研发投入，促进产学研融通创新。加快建设国家实验室，重组国家重点实验室体系，发展社会研发机构，加强关键核心技术攻关。发展民生科技。深化国际科技合作。改革科技成果转化机制，畅通创新链，营造鼓励创新、宽容失败的科研环境。实行重点项目攻关“揭榜挂帅”，谁能干就让谁干。（科技部、国家发展改革委、工业和信息化部、教育部、财政部、外交部、国家卫生健康委、农业农村部、国务院国资委、中科院、工程院、国家能源局、国家国防科工局等按职责分工负责，年内持续推进）加强知识产权保护。（国家知识产权局牵头，年内持续推进）\n（十六）深入推进大众创业万众创新。\n19.发展创业投资和股权投资，增加创业担保贷款。（国家发展改革委、财政部、人力资源社会保障部、人民银行、银保监会、证监会等按职责分工负责，年内持续推进）深化新一轮全面创新改革试验。（国家发展改革委、科技部牵头，年内持续推进）新建一批双创示范基地。（国家发展改革委牵头，年内持续推进）坚持包容审慎监管，发展平台经济、共享经济，更大激发社会创造力。（国务院办公厅、国家发展改革委、科技部、工业和信息化部、商务部、市场监管总局等按职责分工负责，年内持续推进）\n四、实施扩大内需战略，推动经济发展方式加快转变\n（十七）推动消费回升。\n20.通过稳就业促增收保民生，提高居民消费意愿和能力。（国家发展改革委、人力资源社会保障部、民政部、商务部、国家医保局等按职责分工负责，年内持续推进）支持餐饮、商场、文化、旅游、家政等生活服务业恢复发展，推动线上线下融合。促进汽车消费，大力解决停车难问题。发展养老、托幼服务。发展大健康产业。改造提升步行街。支持电商、快递进农村，拓展农村消费。要多措并举扩消费，适应群众多元化需求。（国家发展改革委、教育部、科技部、工业和信息化部、民政部、财政部、住房城乡建设部、农业农村部、商务部、文化和旅游部、国家卫生健康委、市场监管总局、体育总局、国家医保局、国家邮政局、国家中医药局、国家药监局、全国老龄办、全国妇联等按职责分工负责，年内持续推进）\n（十八）扩大有效投资。\n21.今年拟安排地方政府专项债券3.75万亿元，比去年增加1.6万亿元，提高专项债券可用作项目资本金的比例，中央预算内投资安排6000亿元。重点支持既促消费惠民生又调结构增后劲的“两新一重”建设，主要是：加强新型基础设施建设，发展新一代信息网络，拓展5G应用，建设数据中心，增加充电桩、换电站等设施，推广新能源汽车，激发新消费需求、助力产业升级。加强新型城镇化建设，大力提升县城公共设施和服务能力，以适应农民日益增加的到县城就业安家需求。新开工改造城镇老旧小区3.9万个，支持管网改造、加装电梯等，发展居家养老、用餐、保洁等多样社区服务。加强交通、水利等重大工程建设。增加国家铁路建设资本金1000亿元。健全市场化投融资机制，支持民营企业平等参与。要优选项目，不留后遗症，让投资持续发挥效益。（国家发展改革委、财政部、工业和信息化部、住房城乡建设部、交通运输部、水利部、农业农村部、民政部、商务部、国家卫生健康委、人民银行、银保监会、国家能源局、中国国家铁路集团有限公司、开发银行、进出口银行、农业发展银行等按职责分工负责，年内持续推进）\n（十九）深入推进新型城镇化。\n22.发挥中心城市和城市群综合带动作用，培育产业、增加就业。（国家发展改革委牵头，年内持续推进）坚持房子是用来住的、不是用来炒的定位，因城施策，促进房地产市场平稳健康发展。完善便民、无障碍设施，让城市更宜业宜居。（住房城乡建设部牵头，年内持续推进）\n（二十）加快落实区域发展战略。\n23.继续推动西部大开发、东北全面振兴、中部地区崛起、东部率先发展。深入推进京津冀协同发展、粤港澳大湾区建设、长三角一体化发展。推进长江经济带共抓大保护。编制黄河流域生态保护和高质量发展规划纲要。推动成渝地区双城经济圈建设。促进革命老区、民族地区、边疆地区、贫困地区加快发展。发展海洋经济。（国家发展改革委牵头，年内持续推进）\n24.实施好支持湖北发展一揽子政策，支持保就业、保民生、保运转，促进经济社会秩序全面恢复。（国家发展改革委牵头，年内持续推进）\n（二十一）提高生态环境治理成效。\n25.突出依法、科学、精准治污。深化重点地区大气污染治理攻坚。（生态环境部牵头，年内持续推进）加强污水、垃圾处置设施建设，推进生活垃圾分类。（国家发展改革委、住房城乡建设部、生态环境部等按职责分工负责，年内持续推进）加快人口密集区危化品生产企业搬迁改造。（工业和信息化部牵头，年内持续推进）壮大节能环保产业。（国家发展改革委、工业和信息化部、生态环境部等按职责分工负责，年内持续推进）\n26.严惩非法捕杀、交易、食用野生动物行为。（国家林草局、农业农村部、市场监管总局、公安部、海关总署等按职责分工负责，年内持续推进）实施重要生态系统保护和修复重大工程，促进生态文明建设。（国家发展改革委、财政部、自然资源部、生态环境部、国家林草局等按职责分工负责，年内持续推进）\n（二十二）保障能源安全。\n27.推动煤炭清洁高效利用，发展可再生能源，完善石油、天然气、电力产供销体系，提升能源储备能力。（国家发展改革委、财政部、国家能源局牵头，年内持续推进）\n五、确保实现脱贫攻坚目标，促进农业丰收农民增收\n（二十三）坚决打赢脱贫攻坚战。\n28.加大剩余贫困县和贫困村攻坚力度，对外出务工劳动力，要在就业地稳岗就业。开展消费扶贫行动，支持扶贫产业恢复发展。继续执行对摘帽县的主要扶持政策。接续推进脱贫与乡村振兴有效衔接，全力让脱贫群众迈向富裕。（国务院扶贫办、国家发展改革委、人力资源社会保障部、农业农村部、人民银行、开发银行、农业发展银行等按职责分工负责，年内持续推进）加强易地扶贫搬迁后续扶持。（国家发展改革委、国务院扶贫办牵头，年内持续推进）深化东西部扶贫协作和中央单位定点扶贫。（国务院扶贫办牵头，年内持续推进）强化对特殊贫困人口兜底保障。（民政部牵头，年内持续推进）搞好脱贫攻坚普查。（国家统计局、国务院扶贫办牵头，7月开始对第1批普查对象进行现场登记）\n（二十四）着力抓好农业生产。\n29.稳定粮食播种面积和产量，提高复种指数，提高稻谷最低收购价，增加产粮大县奖励，大力防治重大病虫害。支持大豆等油料生产。（农业农村部、国家发展改革委、财政部等按职责分工负责，12月底前完成）惩处违法违规侵占耕地行为。（自然资源部、农业农村部等按职责分工负责，年内持续推进）新建高标准农田8000万亩。培育推广优良品种。（农业农村部牵头，12月底前完成）完善农机补贴政策。（农业农村部、财政部等按职责分工负责，年内持续推进）深化农村改革。（农业农村部牵头，年内持续推进）加强非洲猪瘟等疫病防控，恢复生猪生产，发展畜禽水产养殖。（农业农村部牵头，年内持续推进）健全农产品流通体系。（商务部、国家发展改革委、农业农村部等按职责分工负责，年内持续推进）压实“米袋子”省长负责制和“菜篮子”市长负责制。14亿中国人的饭碗，务必牢牢端在自己手中。（国家发展改革委、农业农村部、国家粮食和储备局等按职责分工负责，12月底前完成）\n（二十五）拓展农民就业增收渠道。\n30.支持农民就近就业创业，促进一二三产业融合发展，扩大以工代赈规模，让返乡农民工能打工、有收入。加强农民职业技能培训。依法根治拖欠农民工工资问题。（国家发展改革委、财政部、人力资源社会保障部、农业农村部等按职责分工负责，年内持续推进）扶持适度规模经营主体，加强农户社会化服务。（农业农村部牵头，年内持续推进）支持农产品深加工。（工业和信息化部、农业农村部等按职责分工负责，年内持续推进）完善乡村产业发展用地保障政策。（自然资源部、农业农村部牵头，年内持续推进）增强集体经济实力。（农业农村部牵头，年内持续推进）增加专项债券投入，支持现代农业设施、饮水安全工程和人居环境整治，持续改善农民生产生活条件。（国家发展改革委、财政部、农业农村部、水利部、住房城乡建设部、生态环境部、农业发展银行等按职责分工负责，12月底前完成）\n六、推进更高水平对外开放，稳住外贸外资基本盘\n（二十六）稳定产业链供应链。\n31.面对外部环境变化，要坚定不移扩大对外开放，稳定产业链供应链，以开放促改革促发展。（国家发展改革委、商务部牵头，年内持续推进）\n（二十七）促进外贸基本稳定。\n32.围绕支持企业增订单稳岗位保就业，加大信贷投放，扩大出口信用保险覆盖面，降低进出口合规成本，支持出口产品转内销。（商务部、财政部、人民银行、银保监会、进出口银行等按职责分工负责，6月底前出台相关政策，年内持续推进）加快跨境电商等新业态发展，提升国际货运能力。（商务部、国家发展改革委、交通运输部、海关总署、国家邮政局等按职责分工负责，9月底前出台相关政策，年内持续推进）推进新一轮服务贸易创新发展试点。（商务部牵头，8月底前完成）筹办好第三届进博会，积极扩大进口，发展更高水平面向世界的大市场。（商务部牵头，11月底前完成）\n（二十八）积极利用外资。\n33.大幅缩减外资准入负面清单。（国家发展改革委、商务部等按职责分工负责，6月底前完成）出台跨境服务贸易负面清单。（商务部牵头，12月底前完成）深化经济特区改革开放。（国家发展改革委牵头，年内持续推进）赋予自贸试验区更大改革开放自主权。（商务部牵头，年内持续推进）在中西部地区增设自贸试验区、综合保税区，增加服务业扩大开放综合试点。（商务部、海关总署等按职责分工负责，12月底前完成）加快海南自由贸易港建设。（国家发展改革委牵头，商务部等有关部门按职责分工负责，年内持续推进）营造内外资企业一视同仁、公平竞争的市场环境。（国家发展改革委、商务部、市场监管总局等按职责分工负责，年内持续推进）\n（二十九）高质量共建“一带一路”。\n34.坚持共商共建共享，遵循市场原则和国际通行规则，发挥企业主体作用，开展互惠互利合作。引导对外投资健康发展。（国家发展改革委、商务部、外交部等按职责分工负责，年内持续推进）\n（三十）推动贸易和投资自由化便利化。\n35.坚定维护多边贸易体制，积极参与世贸组织改革。推动签署区域全面经济伙伴关系协定，推进中日韩等自贸谈判。（商务部牵头，年内持续推进）共同落实中美第一阶段经贸协议。（财政部、国家发展改革委、农业农村部、商务部、人民银行、海关总署等按职责分工负责，年内持续推进）致力于加强与各国经贸合作，实现互利共赢。（商务部牵头，年内持续推进）\n七、围绕保障和改善民生，推动社会事业改革发展\n（三十一）加强公共卫生体系建设。\n36.坚持生命至上，改革疾病预防控制体制，加强传染病防治能力建设，完善传染病直报和预警系统，坚持及时公开透明发布疫情信息。（国家卫生健康委牵头，12月底前出台相关政策）用好抗疫特别国债，加大疫苗、药物和快速检测技术研发投入，增加防疫救治医疗设施，增加移动实验室，强化应急物资保障，强化基层卫生防疫。加快公共卫生人才队伍建设。（国家发展改革委、教育部、科技部、工业和信息化部、财政部、人力资源社会保障部、交通运输部、商务部、国家卫生健康委、市场监管总局、国家中医药局、国家药监局等按职责分工负责，年内持续推进）深入开展爱国卫生运动。普及卫生健康知识，倡导健康文明生活方式。（国家卫生健康委牵头，教育部、民政部、生态环境部、住房城乡建设部、农业农村部、市场监管总局等按职责分工负责，10月底前出台相关政策）要大幅提升防控能力，坚决防止疫情反弹，坚决守护人民健康。（国家卫生健康委牵头，年内持续推进）\n（三十二）提高基本医疗服务水平。\n37.居民医保人均财政补助标准增加30元。（财政部、国家医保局牵头，7月底前出台相关政策）开展门诊费用跨省直接结算试点。（国家医保局牵头，年内持续推进）对受疫情影响的医疗机构给予扶持。（国家发展改革委、财政部、人力资源社会保障部、国家卫生健康委、国家医保局等按职责分工负责，年内持续推进）深化公立医院综合改革。（国家卫生健康委、财政部牵头，12月底前出台相关政策）建设区域医疗中心。（国家发展改革委、国家卫生健康委、国家中医药局牵头，年内持续推进）发展“互联网+医疗健康”。提高城乡社区医疗服务能力。推进分级诊疗。构建和谐医患关系。（国家卫生健康委牵头，年内持续推进）促进中医药振兴发展，加强中西医结合。（国家卫生健康委、国家中医药局、国家发展改革委牵头，教育部、科技部、财政部、农业农村部、国家医保局、国家药监局等按职责分工负责，7月底前出台相关政策，年内持续推进）严格食品药品监管，确保安全。（市场监管总局、国家药监局、海关总署等按职责分工负责，年内持续推进）\n（三十三）推动教育公平发展和质量提升。\n38.坚持立德树人。有序组织中小学教育教学和中高考工作。加强乡镇寄宿制学校、乡村小规模学校和县城学校建设。完善随迁子女义务教育入学政策。办好特殊教育、继续教育，支持和规范民办教育。发展普惠性学前教育，帮助民办幼儿园纾困。推动高等教育内涵式发展，推进一流大学和一流学科建设，支持中西部高校发展。扩大高校面向农村和贫困地区招生规模。发展职业教育。加强教师队伍建设。推进教育信息化。要稳定教育投入，优化投入结构，缩小城乡、区域、校际差距，让教育资源惠及所有家庭和孩子，让他们有更光明未来。（教育部牵头，国家发展改革委、工业和信息化部、司法部、财政部、人力资源社会保障部、中国残联等按职责分工负责，年内持续推进）\n（三十四）加大基本民生保障力度。\n39.上调退休人员基本养老金，提高城乡居民基础养老金最低标准。实现企业职工基本养老保险基金省级统收统支，提高中央调剂比例。全国近3亿人领取养老金，必须确保按时足额发放。扩大失业保险保障范围，将参保不足1年的农民工等失业人员都纳入常住地保障。（人力资源社会保障部、财政部牵头，7月底前出台相关政策）落实退役军人优抚政策。（退役军人部牵头，12月底前出台相关政策）做好因公殉职人员抚恤。（人力资源社会保障部、财政部、退役军人部等按职责分工负责，年内持续推进）\n40.完善社会救助制度。扩大低保保障范围，对城乡困难家庭应保尽保，将符合条件的城镇失业和返乡人员及时纳入低保。对因灾因病因残遭遇暂时困难的人员，都要实施救助。要切实保障所有困难群众基本生活，保民生也必将助力更多失业人员再就业敢创业。（民政部牵头，财政部、人力资源社会保障部、中国残联等按职责分工负责，6月底前出台相关政策，年内持续推进）\n（三十五）丰富群众精神文化生活。\n41.培育和践行社会主义核心价值观，发展哲学社会科学、新闻出版、广播影视等事业。加强文物保护利用和非物质文化遗产传承。（文化和旅游部、广电总局、国家文物局等按职责分工负责，年内持续推进）加强公共文化服务，倡导全民健身和全民阅读，使全社会充满活力、向上向善。（文化和旅游部、体育总局等按职责分工负责，年内持续推进）筹办北京冬奥会、冬残奥会。（有关部门按职责分工负责，年内持续推进）\n（三十六）加强和创新社会治理。\n42.健全社区管理和服务机制。加强乡村治理。支持社会组织、人道救助、志愿服务、慈善事业等健康发展。保障妇女、儿童、老人、残疾人合法权益。（民政部、国务院妇儿工委办公室、全国老龄办、全国妇联、中国残联、中国红十字会总会等按职责分工负责，年内持续推进）完善信访制度，化解信访突出矛盾。（国家信访局牵头，有关部门按职责分工负责，年内持续推进）加强法律援助，及时解决群众合理诉求，妥善化解矛盾纠纷。（司法部牵头，年内持续推进）开展第七次全国人口普查。（国家统计局牵头，普查标准时点是2020年11月1日零时）加强国家安全能力建设。（安全部牵头，年内持续推进）完善社会治安防控体系，依法打击各类犯罪，建设更高水平的平安中国。（公安部牵头，年内持续推进）\n（三十七）强化安全生产责任。\n43.加强洪涝、火灾、地震等灾害防御，做好气象服务，提高应急管理、抢险救援和防灾减灾能力。实施安全生产专项整治。坚决遏制重特大事故发生。（应急部、工业和信息化部、公安部、自然资源部、生态环境部、住房城乡建设部、交通运输部、水利部、中国地震局、中国气象局、国家粮食和储备局、国家林草局等按职责分工负责，年内持续推进）\n八、加强政府自身建设，做好“十四五”规划编制\n（三十八）坚持依法行政，建设廉洁政府。\n44.各级政府要自觉在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致，践行以人民为中心的发展思想，落实全面从严治党要求，坚持依法行政，建设法治政府，坚持政务公开，提高治理能力。要依法接受同级人大及其常委会的监督，自觉接受人民政协的民主监督，主动接受社会和舆论监督。发挥好工会、共青团、妇联等群团组织作用。政府工作人员要自觉接受法律、监察和人民监督。加强廉洁政府建设，坚决惩治腐败。（国务院各部门分别负责，年内持续推进）强化审计监督。（审计署牵头，年内持续推进）\n（三十九）突出求真务实，主动担当作为。\n45.各级政府要始终坚持实事求是，牢牢把握社会主义初级阶段这个基本国情，遵循客观规律，一切从实际出发，立足办好自己的事。要大力纠治“四风”，力戒形式主义、官僚主义，把广大基层干部干事创业的手脚从形式主义的束缚中解脱出来，为担当者担当，让履职者尽责。要紧紧依靠人民群众，尊重基层首创精神，以更大力度推进改革开放，激发社会活力，凝聚亿万群众的智慧和力量。广大干部应临难不避、实干为要，凝心聚力抓发展、保民生。（国务院各部门分别负责，年内持续推进）\n（四十）做好“十四五”规划编制工作。\n46.今年要编制好“十四五”规划，为开启第二个百年奋斗目标新征程擘画蓝图。（国家发展改革委牵头，年内持续推进）\n九、做好民族、宗教、侨务、国防、港澳台、外交工作\n（四十一）全面贯彻党的民族政策和宗教工作基本方针，认真落实侨务政策。\n47.要坚持和完善民族区域自治制度，支持少数民族和民族地区加快发展，铸牢中华民族共同体意识。（国家民委牵头，年内持续推进）全面贯彻党的宗教工作基本方针，发挥宗教界人士和信教群众在促进经济社会发展中的积极作用。（有关部门按职责分工负责，年内持续推进）要发挥好侨胞侨眷的独特优势，不断增强中华儿女凝聚力，同心共创辉煌。（有关部门按职责分工负责，年内持续推进）\n（四十二）扎实推进国防和军队建设。\n48.要深入贯彻习近平强军思想，深入贯彻新时代军事战略方针，坚持政治建军、改革强军、科技强军、人才强军、依法治军。坚持党对人民军队的绝对领导，严格落实军委主席负责制。全力加强练兵备战，坚定维护国家主权、安全、发展利益。打好军队建设发展“十三五”规划落实攻坚战，编制军队建设“十四五”规划。深化国防和军队改革，提高后勤和装备保障能力。完善国防动员体系，始终让军政军民团结坚如磐石。（有关部门按职责分工负责，年内持续推进）推动国防科技创新发展。（国家国防科工局等按职责分工负责，年内持续推进）\n（四十三）全面准确贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治的方针。\n49.建立健全特别行政区维护国家安全的法律制度和执行机制，落实特区政府的宪制责任。支持港澳发展经济、改善民生，更好融入国家发展大局，保持香港、澳门长期繁荣稳定。（国务院港澳办牵头，年内持续推进）\n（四十四）坚持对台工作大政方针。\n50.坚持一个中国原则，在“九二共识”基础上推动两岸关系和平发展。坚决反对和遏制“台独”分裂行径。完善促进两岸交流合作、深化两岸融合发展、保障台湾同胞福祉的制度安排和政策措施，团结广大台湾同胞共同反对“台独”、促进统一，开创民族复兴的美好未来。（有关部门按职责分工负责，年内持续推进）\n（四十五）坚定不移走和平发展道路。\n51.同各国携手共进，应对公共卫生危机、经济严重衰退等全球性挑战。加强防疫合作，促进世界经济稳定，推进全球治理，维护以联合国为核心的国际体系和以国际法为基础的国际秩序，推动构建人类命运共同体。坚定不移走和平发展道路，在扩大开放中深化与各国友好合作。（外交部、科技部、商务部、国家卫生健康委、国际发展合作署、国家中医药局、国家药监局等按职责分工负责，年内持续推进）\n今年是决胜全面小康、决战脱贫攻坚的收官之年，也是实现“两个一百年”奋斗目标的历史交汇之年。我们要更加紧密地团结在以习近平同志为核心的党中央周围，高举中国特色社会主义伟大旗帜，以习近平新时代中国特色社会主义思想为指导，认真贯彻党中央、国务院决策部署，迎难而上，锐意进取，统筹推进疫情防控和经济社会发展，努力完成全年目标任务。一是加强组织领导。各部门主要负责同志要切实履职尽责，抓紧组织制定本部门贯彻实施方案，于6月20日前报国务院。要对照分工逐项建立工作台账，明确时间表、责任人和成果形式，确保各项任务有措施、可量化、能落实。二是强化协同配合。各部门要切实加大工作力度，加快工作进度，任务牵头部门和协办部门要立足大局，协同配合，形成合力，不推诿扯皮。三是注重统筹兼顾。各部门要加强形势研判，统筹国内和国际，兼顾当前和长远，坚定发展信心，增强发展动力。要深入实际、深入基层、深入群众，及时推动解决实际困难和问题，根据形势变化调整完善政策。四是抓好督查督办。各部门要增强责任感和紧迫感，主动担当、积极作为，狠抓工作落实，做好日常跟踪督办。要切实加强对各地的指导服务，减轻基层负担。各省（自治区、直辖市）人民政府要主动对接国务院有关部门，结合本地实际进一步明确工作重点，细化措施，抓好落实。国务院办公厅建立《政府工作报告》督查总台账，定期对账督办，对进度慢、办事敷衍、成效不明显的开展专项督查，对不作为、乱作为的坚决追责问责，切实推动各项重点工作落地见效。\n国务院\n2020年6月6日\n（此件公开发布）","level":1},{"name":"","text":"延伸阅读\n政府工作报告","level":0}]},{"id":"r0628","sections":[{"name":"中央纪委下发《关于严禁元旦春节期间公款购买赠送烟花爆竹等年货节礼的通知》","text":"点击此处观看视频","level":1},{"name":"","text":"21日，中央纪委下发《关于严禁元旦春节期间公款购买赠送烟花爆竹等年货节礼的通知》，全文如下：\n元旦、春节将至，遵照中央指示，要继续落实好八项规定精神、坚决反对“四风”。节日期间，公款赠送节礼现象普遍，不正之风易发多发，广大群众反映强烈。现提出如下纪律要求：\n各级党政机关、人民团体、国有企事业单位和金融机构，严禁用公款购买赠送烟花爆竹、烟酒、花卉、食品等年货节礼（慰问困难群众职工不在此限）。要严肃财经纪律，强化审计监督，相关费用不准转嫁摊派，一律不予公款报销。\n各级纪检监察机关要强化执纪监督，对违纪行为快查快办，严格责任追究，及时通报曝光。深入落实八项规定精神，必须在坚持中深化，在深化中坚持，不断巩固纠正“四风”成果。广大党员干部要带头勤俭节约、移风易俗，以优良党风政风带动民风社风，过一个平安欢乐祥和的佳节。","level":0}]},{"id":"r0629","sections":[{"name":"中办印发《领导干部配偶、子女及其配偶经商办企业管理规定》","text":"近日，中共中央办公厅印发了《领导干部配偶、子女及其配偶经商办企业管理规定》（以下简称《规定》），并发出通知，要求有关党委（党组）及其组织（人事）部门提高政治站位，压实管理责任，完善工作机制，严肃纪律要求，不折不扣抓好《规定》贯彻落实。","level":1},{"name":"","text":"加强对领导干部配偶、子女及其配偶经商办企业管理，是全面从严治党、从严管理监督干部的重要举措。《规定》贯彻落实新时代党的组织路线，总结实践经验，对领导干部配偶、子女及其配偶经商办企业管理的适用对象和情形、工作措施、纪律要求等作出明确规定，对于规范和制约权力运行，从源头上防范廉政风险，促进领导干部家风建设，具有重要意义。\n《规定》明确，领导干部配偶、子女及其配偶经商办企业管理的适用对象，主要是党政机关、群团组织、企事业单位厅局级及相当职务层次以上领导干部；经商办企业情形，主要是投资开办企业、担任私营企业或外资企业等高级职务、私募股权基金投资及从业、从事有偿社会中介和法律服务等行为。《规定》对不同层级、不同类别领导干部配偶、子女及其配偶经商办企业分别提出了禁业要求，领导干部职务层次越高要求越严，综合部门严于其他部门。\n《规定》要求，领导干部每年报告个人有关事项时，应当如实填报配偶、子女及其配偶经商办企业情况，年度集中报告后新产生的经商办企业情况要及时报告。对领导干部报告情况要进行随机抽查和重点查核，发现有关经商办企业违反禁业规定的，责令领导干部作出说明，由其配偶、子女及其配偶退出经商办企业，或者由领导干部本人退出现职、接受职务调整，并视情况给予领导干部相应处理处分。其中，对拟提拔或进一步使用的领导干部，结合干部选拔任用“凡提四必”进行查核，不符合拟任岗位禁业规定的，应退出经商办企业，不同意退出的不予任用。\n《规定》要求，对领导干部不如实报告配偶、子女及其配偶经商办企业情况，配偶、子女及其配偶违反禁业规定经商办企业和以委托代持、隐名投资等形式虚假退出，以及利用职权为配偶、子女及其配偶经商办企业提供便利、谋取私利等行为，依规依纪依法进行严肃处理，对管理不力造成严重后果或不良影响的责任单位和责任人员进行严肃问责。\n延伸阅读\n仲祖文：从严管党治吏走向纵深的重大举措","level":0}]},{"id":"r0630","sections":[{"name":"关于规范国歌奏唱礼仪的实施意见","text":"中共中央办公厅、国务院办公厅近日印发了《关于规范国歌奏唱礼仪的实施意见》，并发出通知，要求各地区各部门结合实际认真贯彻执行。\n关于规范国歌奏唱礼仪的实施意见","level":1},{"name":"","text":"国歌是国家的象征和标志。我国宪法明确规定，中华人民共和国国歌是《义勇军进行曲》。国歌凝结着中国共产党领导人民争取民族独立、人民解放和实现国家富强、人民富裕的全部奋斗，是鼓舞人民奋勇前进的强劲旋律，是进行爱国主义教育的鲜活教材。热爱、尊重国歌，学唱、传唱国歌，规范、普及国歌奏唱礼仪，对于激发人们爱国报国情感、培育和践行社会主义核心价值观，具有重要作用。为更好发挥国歌在推进社会主义核心价值观建设中的教育引导作用，现就规范国歌奏唱礼仪提出如下意见。","level":0},{"name":"一、国歌奏唱场合","text":"1．国歌可以在下列场合奏唱。重要的庆典活动或者政治性公众集会开始时，正式的外交场合或者重大的国际性集会开始时，举行升旗仪式时，重大运动赛会开始或者我国运动员在国际体育赛事中获得冠军时，遇有维护祖国尊严的斗争场合，重大公益性文艺演出活动开始时，其他重要的正式场合。\n2．国歌不得在下列场合奏唱。私人婚丧庆悼，舞会、联谊会等娱乐活动，商业活动，非政治性节庆活动，其他在活动性质或者气氛上不适宜的场合。","level":1},{"name":"二、国歌奏唱礼仪","text":"1．一般要求。奏唱国歌时，应当着装得体，精神饱满，肃立致敬，有仪式感和庄重感；自始至终跟唱，吐字清晰，节奏适当，不得改变曲调、配乐、歌词，不得中途停唱或者中途跟唱；不得交语、击节、走动或者鼓掌，不得接打电话或者从事其他无关行为。国歌不得与其他歌曲紧接奏唱。\n2．外事活动。除遵守一般要求外，着装应当符合外事活动要求；遇接待国宾仪式或者国际性集会时，可以连奏有关国家国歌或者有关国际组织会歌。\n3．运动赛会。除遵守一般要求外，国歌奏唱仪式开始前应当全体起立；比赛中遇奏国歌的情况，在不违反竞赛规则的前提下，应当遵循裁判指示暂停比赛活动。\n4．学校活动。除遵守一般要求外，少先队员应当行队礼。","level":1},{"name":"三、开展宣传教育","text":"1．普及国歌内容。各类学校要将国歌歌词和曲谱作为教育教学的重要内容，小学、幼儿园要组织学生学唱国歌。各类新闻媒体和宣传文化阵地要加大国歌内容的宣传力度，从历史和现实的结合上解读国歌的深刻内涵和蕴含的精神，使人们理解国歌、记住国歌、唱好国歌。各地要广泛组织群众学唱国歌，开展国歌传唱活动，让国歌的旋律在全社会响亮起来。\n2．普及国歌奏唱礼仪知识。要综合运用多种方式进行国歌奏唱礼仪宣传普及，使人们知晓国歌适宜奏唱的场合和应当遵守的礼仪规范。要广泛开展国歌奏唱礼仪体验活动，让人们在参与中感悟国歌的真谛和力量，增强对国歌的礼敬感。\n3．开展对违反国歌奏唱礼仪行为的监督。地方各级人民政府对本行政区域内的国歌奏唱行为实施监督管理。对在不适宜的场合违规奏唱国歌并造成不良社会影响的现象，对奏唱国歌时不合礼仪的行为，要批评教育，严肃纠正，增强国歌奏唱的严肃性和规范性。","level":1}]},{"id":"r0631","sections":[{"name":"中共中央组织部印发《关于认真学习贯彻习近平总书记重要指示精神 扎实推进“三严三实”专题教育的通知》","text":"点击此处观看视频","level":1},{"name":"","text":"近日，中共中央组织部印发通知，对认真学习贯彻习近平总书记重要指示精神、扎实推进“三严三实”专题教育提出要求。\n《通知》指出，习近平总书记在浙江和贵州考察、会见全国优秀县委书记、主持召开中央全面深化改革领导小组第十四次会议时，对开展“三严三实”专题教育、践行“三严三实”要求作出重要指示。习近平总书记强调，在县处级以上领导干部中开展“三严三实”专题教育，是今年党的建设的一项重要任务，要突出问题导向，贯彻从严要求，既巩固和扩大从严治党成果，又有效解决党的建设面临的新问题。习近平总书记的重要指示精神，对于高标准高质量开展专题教育、确保取得实效，具有十分重要的指导意义。各级党委（党组）要认真组织学习，领会精神实质，抓好贯彻落实。\n《通知》强调，认真学习深刻领会习近平总书记重要指示精神。要把学习贯彻习近平总书记重要指示精神作为专题学习研讨的重要内容。通过学习，使领导干部深刻领会习近平总书记关于领导干部要可信、做人干事都让组织放心的要求，努力成为党和人民信赖的好干部；深刻领会习近平总书记关于学习老一辈革命家崇高品德的要求，检身正己、见贤思齐；深刻领会习近平总书记关于把“三严三实”贯穿改革全过程的要求，既当改革的促进派，又当改革的实干家；深刻领会习近平总书记关于领导干部要带头搞好专题教育的要求，清清白白做人、干干净净做事、堂堂正正做官。各级领导干部要在领会核心要义上下功夫，在打牢思想根基上下功夫，在坚持知行合一上下功夫，以思想自觉引领行动自觉。\n《通知》要求，紧密结合改革发展实际查找解决“不严不实”问题。要始终坚持问题导向，围绕“三严三实”要求，特别要结合贯彻全面深化改革要求、大力推进各领域改革的实际，找准“不严不实”的突出问题和具体表现。领导干部要把自己摆进去，把部门职能、岗位职责摆进去，把思想、工作和作风实际摆进去，剖析问题根源、落实改进措施，使推动改革的能力强起来，勇于担当的精神树起来，主动作为的行动实起来。\n《通知》提出，用推动改革的实际成效检验专题教育成果。整改思路要立足于推进改革，整改措施要有助于推进改革，整改成效要体现在推进改革，围绕解决与深化改革不相适应的思想观念、体制机制障碍等问题，引导领导干部看大局、明大势，坚定改革决心和信心，抓实问题、开实药方、提实举措，着力破解深层次体制机制问题，不断释放发展活力，让广大群众有更多获得感。\n《通知》强调，以从严从实作风抓好专题教育。党委（党组）要切实履行主体责任，对“关键动作”一个一个专题研究，在重要节点专门听取情况汇报。党委（党组）书记要切实履行第一责任，率先垂范、严格把关。组织部门要切实履行牵头责任，具体设计每个动作，督促落实每项要求，盯住盯紧薄弱环节，加强与相关部门的沟通协调，形成齐抓共管合力，推动中央部署不折不扣落到位、见成效。\n延伸阅读\n习近平在浙江调研\n习近平在贵州调研\n习近平会见全国优秀县委书记\n习近平主持召开中央全面深化改革领导小组第十四次会议","level":0}]},{"id":"r0632","sections":[{"name":"中共中央发出关于印发《习近平新时代中国特色社会主义思想学习纲要》的通知","text":"近日，中共中央发出关于印发《习近平新时代中国特色社会主义思想学习纲要（2023年版）》的通知。全文如下：","level":1},{"name":"","text":"党的十八大以来，以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，科学回答了新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义等重大时代课题，创立了习近平新时代中国特色社会主义思想。习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，是中华文化和中国精神的时代精华，实现了马克思主义中国化时代化新的飞跃。党确立习近平总书记党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位，是党在新时代取得的重大政治成果，反映了全党全军全国各族人民共同心愿，对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。\n为推动全党全社会深刻领悟“两个确立”的决定性意义，把学习贯彻习近平新时代中国特色社会主义思想进一步引向深入，根据党中央要求，中央宣传部对2019年出版的《习近平新时代中国特色社会主义思想学习纲要》进行修订，组织编写了《习近平新时代中国特色社会主义思想学习纲要（2023年版）》（以下简称《纲要（2023年版）》）。党中央认为，《纲要（2023年版）》对习近平新时代中国特色社会主义思想作了全面系统阐述，充分反映了这一思想的最新发展，有助于更好地理解把握党的创新理论的基本精神、基本内容、基本要求。党中央同意印发《纲要（2023年版）》（由中央宣传部统一印发），作为广大党员、干部、群众深入学习领会习近平新时代中国特色社会主义思想的重要辅助读物。\n各级党委（党组）要坚持用习近平新时代中国特色社会主义思想统一思想、统一意志、统一行动，着力在武装头脑、指导实践、推动工作上下功夫。要组织全体党员认真读原著、学原文、悟原理，并紧密结合学习贯彻习近平新时代中国特色社会主义思想主题教育，把《纲要（2023年版）》纳入学习计划，作出周密安排，开展多形式、分层次、全覆盖的学习培训。要做到深学笃信，坚持原原本本学、及时跟进学，全面系统深入把握这一思想的核心要义、精神实质、丰富内涵、实践要求，不断增进政治认同、思想认同、理论认同、情感认同；要做到精思细悟，深刻把握这一思想的世界观、方法论和贯穿其中的立场观点方法，知其然又知其所以然，不断提高马克思主义理论水平；要做到知行合一，大力弘扬理论联系实际的优良学风，更加自觉用这一思想指导解决实际问题，切实把学习成效转化为做好本职工作、推动事业发展的生动实践。\n要坚持不懈用习近平新时代中国特色社会主义思想凝心铸魂，在全党全社会深入开展学习宣传阐释工作，引导广大党员、干部、群众深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，自觉在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴而团结奋斗。\n学习贯彻习近平新时代中国特色社会主义思想主题教育","level":0}]},{"id":"r0633","sections":[{"name":"中共中央办公厅 国务院办公厅印发《关于进一步加强生物多样性保护的意见》","text":"近日，中共中央办公厅、国务院办公厅印发了《关于进一步加强生物多样性保护的意见》，并发出通知，要求各地区各部门结合实际认真贯彻落实。","level":1},{"name":"","text":"《关于进一步加强生物多样性保护的意见》全文如下。\n生物多样性是人类赖以生存和发展的基础，是地球生命共同体的血脉和根基，为人类提供了丰富多样的生产生活必需品、健康安全的生态环境和独特别致的景观文化。中国是世界上生物多样性最丰富的国家之一，生物多样性保护已取得长足成效，但仍面临诸多挑战。为贯彻落实党中央、国务院有关决策部署，切实推进生物多样性保护工作，现提出如下意见。","level":0},{"name":"一、总体要求","text":"（一）指导思想。以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中、五中全会精神，深入贯彻习近平生态文明思想，立足新发展阶段，完整、准确、全面贯彻新发展理念，构建新发展格局，坚持生态优先、绿色发展，以有效应对生物多样性面临的挑战、全面提升生物多样性保护水平为目标，扎实推进生物多样性保护重大工程，持续加大监督和执法力度，进一步提高保护能力和管理水平，确保重要生态系统、生物物种和生物遗传资源得到全面保护，将生物多样性保护理念融入生态文明建设全过程，积极参与全球生物多样性治理，共建万物和谐的美丽家园。\n（二）工作原则\n——尊重自然，保护优先。牢固树立尊重自然、顺应自然、保护自然的生态文明理念，坚持保护优先、自然恢复为主，遵循自然生态系统演替和地带性分布规律，充分发挥生态系统自我修复能力，避免人类对生态系统的过度干预，对重要生态系统、生物物种和生物遗传资源实施有效保护，保障生态安全。\n——健全体制，统筹推进。在党中央、国务院领导下，发挥中国生物多样性保护国家委员会统筹协调作用，完善年度工作调度机制。各成员单位应着眼于提升生态系统服务功能，聚焦重点区域、领域和关键问题，各司其职，协调一致，密切配合，互通信息，有序推进生物多样性保护工作。\n——分级落实，上下联动。明确中央和地方生物多样性保护和管理事权，分级压实责任。中央层面做好规划、立法等顶层设计，制定出台政策措施、规划和技术规范等，加强对地方工作的指导和支持。地方各级党委和政府落实生物多样性保护责任，上下联动、形成合力。\n——政府主导，多方参与。发挥各级政府在生物多样性保护中的主导作用，加大管理、投入和监督力度，建立健全企事业单位、社会组织和公众参与生物多样性保护的长效机制，提高社会各界保护生物多样性的自觉性和参与度，营造全社会共同参与生物多样性保护的良好氛围。\n（三）总体目标\n到2025年，持续推进生物多样性保护优先区域和国家战略区域的本底调查与评估，构建国家生物多样性监测网络和相对稳定的生物多样性保护空间格局，以国家公园为主体的自然保护地占陆域国土面积的18%左右，森林覆盖率提高到24.1%，草原综合植被盖度达到57%左右，湿地保护率达到55%，自然海岸线保有率不低于35%，国家重点保护野生动植物物种数保护率达到77%，92%的陆地生态系统类型得到有效保护，长江水生生物完整性指数有所改善，生物遗传资源收集保藏量保持在世界前列，初步形成生物多样性可持续利用机制，基本建立生物多样性保护相关政策、法规、制度、标准和监测体系。\n到2035年，生物多样性保护政策、法规、制度、标准和监测体系全面完善，形成统一有序的全国生物多样性保护空间格局，全国森林、草原、荒漠、河湖、湿地、海洋等自然生态系统状况实现根本好转，森林覆盖率达到26%，草原综合植被盖度达到60%，湿地保护率提高到60%左右，以国家公园为主体的自然保护地占陆域国土面积的18%以上，典型生态系统、国家重点保护野生动植物物种、濒危野生动植物及其栖息地得到全面保护，长江水生生物完整性指数显著改善，生物遗传资源获取与惠益分享、可持续利用机制全面建立，保护生物多样性成为公民自觉行动，形成生物多样性保护推动绿色发展和人与自然和谐共生的良好局面，努力建设美丽中国。","level":1},{"name":"二、加快完善生物多样性保护政策法规","text":"（四）加快生物多样性保护法治建设。健全生物多样性保护和监管制度，研究推进野生动物保护、渔业、湿地保护、自然保护地、森林、野生植物保护、生物遗传资源获取与惠益分享等领域法律法规的制定修订工作。研究起草生物多样性相关传统知识保护条例，制定完善外来入侵物种名录和管理办法。各地可因地制宜出台相应的生物多样性保护地方性法规。\n（五）将生物多样性保护纳入各地区、各有关领域中长期规划。制定新时期国家生物多样性保护战略与行动计划，编制生物多样性保护重大工程十年规划。各省、自治区、直辖市制定国民经济和社会发展五年规划时，应提出生物多样性保护目标和主要任务。相关部门将生物多样性保护纳入行业发展规划，加强可持续管理，减少对生态系统功能和生物多样性的负面影响。各地可结合实际制定修订本区域生物多样性保护行动计划及规划，明确省、市、县生物多样性保护的目标和职责分工。鼓励企业和社会组织自愿制定生物多样性保护行动计划。\n（六）制定和完善生物多样性保护相关政策制度。健全自然保护地生态保护补偿制度，完善生态环境损害赔偿制度，健全生物多样性损害鉴定评估方法和工作机制，完善打击野生动植物非法贸易制度。推行草原森林河流湖泊海湾休养生息，实施长江十年禁渔，健全耕地休耕轮作制度。落实有关从事种源进口等的个人或企业财税政策。","level":1},{"name":"三、持续优化生物多样性保护空间格局","text":"（七）落实就地保护体系。在国土空间规划中统筹划定生态保护红线，优化调整自然保护地，加强对生物多样性保护优先区域的保护监管，明确重点生态功能区生物多样性保护和管控政策。因地制宜科学构建促进物种迁徙和基因交流的生态廊道，着力解决自然景观破碎化、保护区域孤岛化、生态连通性降低等突出问题。合理布局建设物种保护空间体系，重点加强珍稀濒危动植物、旗舰物种和指示物种保护管理，明确重点保护对象及其受威胁程度，对其栖息生境实施不同保护措施。选择重要珍稀濒危物种、极小种群和遗传资源破碎分布点建设保护点。持续推进各级各类自然保护地、城市绿地等保护空间标准化、规范化建设。\n（八）推进重要生态系统保护和修复。统筹考虑生态系统完整性、自然地理单元连续性和经济社会发展可持续性，统筹推进山水林田湖草沙冰一体化保护和修复。实施《全国重要生态系统保护和修复重大工程总体规划（2021－2035年）》，科学规范开展重点生态工程建设，加快恢复物种栖息地。加强重点生态功能区、重要自然生态系统、自然遗迹、自然景观及珍稀濒危物种种群、极小种群保护，提升生态系统的稳定性和复原力。\n（九）完善生物多样性迁地保护体系。优化建设动植物园、濒危植物扩繁和迁地保护中心、野生动物收容救护中心和保育救助站、种质资源库（场、区、圃）、微生物菌种保藏中心等各级各类抢救性迁地保护设施，填补重要区域和重要物种保护空缺，完善生物资源迁地保存繁育体系。科学构建珍稀濒危动植物、旗舰物种和指示物种的迁地保护群落，对于栖息地环境遭到严重破坏的重点物种，加强其替代生境研究和示范建设，推进特殊物种人工繁育和野化放归工作。抓好迁地保护种群的档案建设与监测管理。","level":1},{"name":"四、构建完备的生物多样性保护监测体系","text":"（十）持续推进生物多样性调查监测。完善生物多样性调查监测技术标准体系，统筹衔接各类资源调查监测工作，全面推进生物多样性保护优先区域和黄河重点生态区、长江重点生态区、京津冀、近岸海域等重点区域生态系统、重点生物物种及重要生物遗传资源调查。充分依托现有各级各类监测站点和监测样地（线），构建生态定位站点等监测网络。建立反映生态环境质量的指示物种清单，开展长期监测，鼓励具备条件的地区开展周期性调查。持续推进农作物和畜禽、水产、林草植物、药用植物、菌种等生物遗传资源和种质资源调查、编目及数据库建设。每5年更新《中国生物多样性红色名录》。\n（十一）完善生物多样性保护与监测信息云平台。加大生态系统和重点生物类群监测设备研制和设施建设力度，加快卫星遥感和无人机航空遥感技术应用，探索人工智能应用，推动生物多样性监测现代化。依托国家生态保护红线监管平台，有效衔接国土空间基础信息平台，应用云计算、物联网等信息化手段，充分整合利用各级各类生物物种、遗传资源数据库和信息系统，在保障生物遗传资源信息安全的前提下实现数据共享。研究开发生物多样性预测预警模型，建立预警技术体系和应急响应机制，实现长期动态监控。\n（十二）完善生物多样性评估体系。建立健全生物多样性保护恢复成效、生态系统服务功能、物种资源经济价值等评估标准体系。结合全国生态状况调查评估，每5年发布一次生物多样性综合评估报告。开展大型工程建设、资源开发利用、外来物种入侵、生物技术应用、气候变化、环境污染、自然灾害等对生物多样性的影响评价，明确评价方式、内容、程序，提出应对策略。","level":1},{"name":"五、着力提升生物安全管理水平","text":"（十三）依法加强生物技术环境安全监测管理。严格落实生物安全法，建立健全生物技术环境安全评估与监管技术支撑体系，充分整合现有监测基础，合理布局监测站点，快速识别感知生物技术安全风险。完善监测信息报告系统，建立生物安全培训、跟踪检查、定期报告等工作制度，制定风险防控计划和生物安全事件应急预案，强化过程管理，保障生物安全。\n（十四）建立健全生物遗传资源获取和惠益分享监管制度。实施生物遗传资源及其相关传统知识调查登记，制定完善生物遗传资源目录，建立生物遗传资源信息平台，促进生物遗传资源获取、开发利用、进出境、知识产权保护、惠益分享等监管信息跨部门联通共享。完善获取、利用、进出境审批责任制和责任追究制，强化生物遗传资源对外提供和合作研究利用的监督管理。\n（十五）持续提升外来入侵物种防控管理水平。完善外来入侵物种防控部际协调机制，统筹协调解决外来入侵物种防控重大问题。开展外来入侵物种普查，加强农田、渔业水域、森林、草原、湿地、近岸海域、海岛等重点区域外来入侵物种的调查、监测、预警、控制、评估、清除、生态修复等工作。完善外来物种入侵防范体系，加强外来物种引入审批管理，强化入侵物种口岸防控，加强海洋运输压载水监管。推进野生动物外来疫病监测预警平台布局建设，构建外来物种风险评价和监管技术支撑体系，进一步加强早期预警狙击、应急控制、阻断扑灭、可持续综合防御控制等技术研究和示范应用。","level":1},{"name":"六、创新生物多样性可持续利用机制","text":"（十六）加强生物资源开发和可持续利用技术研究。开展新作物、新品种、新品系、新遗传材料和作物病虫害发展动态调查研究，加强野生动植物种质资源保护和可持续利用，保障粮食安全和生态安全。提高种质资源品种改良生物技术水平，推进酿造、燃料、环境、药品等方面替代资源研发，促进环保、农业、医疗、军事、工业等领域生物资源科技成果转化应用。\n（十七）规范生物多样性友好型经营活动。引导规范利用生物资源，发展野生生物资源人工繁育培育利用、生物质转化利用、农作物和森林草原病虫害绿色防控等绿色产业。进一步扩大生物多样性保护与乡村振兴相协同的示范技术、创新机制等应用范围。制定自然保护地控制区经营性项目特许经营管理办法，鼓励原住居民参与特许经营活动，在适当区域开展自然教育、生态旅游和康养等活动，构建高品质、多样化生态产品体系。","level":1},{"name":"七、加大执法和监督检查力度","text":"（十八）全面开展执法监督检查。建立重要保护物种栖息地生态破坏定期遥感监测机制，将危害国家重点保护野生动植物及其栖息地行为和整治情况纳入中央生态环境保护督察、“绿盾”自然保护地强化监督等专项行动。定期组织开展海洋伏季休（禁）渔和内陆大江大河（湖）禁渔期专项执法行动，清理取缔各种非法利用和破坏水生生物资源及其生态、生境的行为。健全联合执法机制，严厉打击非法猎捕、采集、运输、交易野生动植物及其制品等违法犯罪行为，形成严打严防严管严控的高压态势。健全行政执法与刑事司法联动机制，建立健全案件分级管理、应急处置、挂牌督办等机制，对严重破坏重要生物物种、生物遗传资源等构成犯罪的依法追究刑事责任。结合生态保护红线生态破坏监管试点，严肃查处危害生物多样性行为。\n（十九）严格落实责任追究制度。构建生物多样性保护成效考核指标体系，将生物多样性保护成效作为党政领导班子和领导干部综合考核评价及责任追究、离任审计的重要参考，对造成生态环境和资源严重破坏的实行终身追责。","level":1},{"name":"八、深化国际合作与交流","text":"（二十）积极参与全球生物多样性治理。秉持人类命运共同体理念，主动参与全球多边环境治理，加强关键议题交流磋商，推动制定“2020年后全球生物多样性框架”，切实履行我国参加的生物多样性公约、湿地公约、濒危野生动植物种国际贸易公约等生物多样性相关的国际条约，积极参与生物多样性相关国际标准制定。\n（二十一）加强多元化生物多样性保护伙伴关系。借助生物多样性公约和湿地公约等缔约方大会、“一带一路”绿色发展国际联盟等契机和平台，加强生物多样性保护与绿色发展领域的双多边对话合作，增强伙伴关系认同，推动知识、信息、科技交流和成果共享，提升国际影响力。继续积极参与打击跨境生物资源贸易犯罪国际专项联合执法行动。","level":1},{"name":"九、全面推动生物多样性保护公众参与","text":"（二十二）加强宣传教育。加强生物多样性保护相关法律法规、科学知识、典型案例、重大项目成果等宣传普及，推动新闻媒体和网络平台积极开展生物多样性保护公益宣传，推动生物多样性博物馆建设，推出一批具有鲜明教育警示意义和激励作用的陈列展览，面向地方各级党政干部加大教育培训力度，引导各级党委和政府、企事业单位、社会组织及公众自觉主动参与生物多样性保护。\n（二十三）完善社会参与机制。通过政府购买服务等形式激励企事业单位、社会组织开展生物多样性保护宣传教育、咨询服务和法律援助等活动。完善违法活动举报机制，畅通举报渠道，鼓励公民和社会组织积极举报滥捕滥伐、非法交易、污染环境等导致生物多样性受损的违法行为，支持新闻媒体开展舆论监督。强化信息公开机制，及时回应公众关注的相关热点问题。建立健全生物多样性公益诉讼机制，强化公众参与生物多样性保护的司法保障。","level":1},{"name":"十、完善生物多样性保护保障措施","text":"（二十四）加强组织领导。地方各级党委和政府要严格落实生态环境保护党政同责、一岗双责，进一步加强相关组织建设、队伍建设和制度建设，切实担负起生物多样性保护责任，推进环境污染防治和生物多样性保护协同增效。各有关部门要认真履行生物多样性保护相关职能，将生物多样性保护有关工作纳入绩效考核内容，实行目标责任制，加强协调配合，推动工作落实。\n（二十五）完善资金保障制度。加强各级财政资源统筹，通过现有资金渠道继续支持生物多样性保护。研究建立市场化、社会化投融资机制，多渠道、多领域筹集保护资金。\n（二十六）强化科技与人才支撑。加强生物多样性保护、恢复领域基础科学和应用技术研究，推动科技成果转化应用。发挥科研院所专业教育优势，加强生物多样性人才培养和学术交流。完善人才选拔机制和管理办法，建设高素质专业化人才队伍，增强生物多样性保护和履约、对话合作能力。","level":1}]}]);
